            }));
            const result = insertBankTransactions(toInsert);
            if (result.success) {
                await forceSaveDB();
                setImportResult({ success: true, message: `Γ£ô ${result.importedCount} transacciones consolidadas exitosamente.` });
                onImportComplete?.(result.importedCount);
