            <div className={`p-4 rounded-2.5xl border ${themes[color]} group-hover:scale-110 transition-all duration-500 shadow-xl`}>
                <Icon className="w-6 h-6" />
            </div>
            <div className="overflow-hidden">
                <div className="text-2xl font-black text-white tracking-tighter leading-none mb-1 font-mono uppercase truncate">{value}</div>
                <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{label}</div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import {
  Plus, Save, XCircle, Calculator, Truck, Calendar,
  ShieldCheck, Zap, Cpu, Sparkles, DollarSign, Info, Layers, Clock, Trash2
} from 'lucide-react';
import { Supplier, Product, Bill, BillItem, getFloridaTaxRate } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface BillFormProps {
  onSubmit: (billData: Partial<Bill>, items: Partial<BillItem>[]) => void;
  onCancel?: () => void;
  suppliers: Supplier[];
  products: Product[];
  initialData?: Bill;
  isEditing?: boolean;
}

interface FormData {
  supplier_id: number | '';
  issue_date: string;
  due_date: string;
  status: 'draft' | 'received' | 'approved' | 'paid' | 'overdue' | 'cancelled';
  notes: string;
}

interface ItemData {
  product_id: number | '';
  description: string;
  quantity: number;
  unit_price: number;
  taxable: boolean;
}

export const BillForm: React.FC<BillFormProps> = ({
  onSubmit,
  onCancel,
  suppliers,
  products,
  initialData,
  isEditing = false
}) => {
  const { t } = useLocale();
  const [formData, setFormData] = useState<FormData>({
    supplier_id: initialData?.supplier_id || '',
    issue_date: initialData?.issue_date || new Date().toISOString().split('T')[0],
    due_date: initialData?.due_date || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    status: initialData?.status || 'draft',
    notes: initialData?.notes || ''
  });

  const [items, setItems] = useState<ItemData[]>(
    initialData?.items?.map(item => ({
      product_id: item.product_id || '',
      description: item.description,
      quantity: item.quantity,
      unit_price: item.unit_price,
      taxable: item.taxable
    })) || [
      { product_id: '', description: '', quantity: 1, unit_price: 0, taxable: true }
    ]
  );

  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleInputChange = (field: keyof FormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleItemChange = (index: number, field: keyof ItemData, value: any) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };

    if (field === 'product_id' && value) {
      const product = products.find(p => p.id === parseInt(value));
      if (product) {
        newItems[index].description = product.name;
        newItems[index].unit_price = product.cost || product.price;
        newItems[index].taxable = product.taxable;
      }
    }
    setItems(newItems);
  };

  const addItem = () => {
    setItems([...items, { product_id: '', description: '', quantity: 1, unit_price: 0, taxable: true }]);
  };

  const removeItem = (index: number) => {
    if (items.length > 1) {
      setItems(items.filter((_, i) => i !== index));
    }
  };

  const calculateTotals = () => {
    let subtotal = 0;
    let taxAmount = 0;
    const selectedSupplier = suppliers.find(s => s.id === formData.supplier_id);
    const county = selectedSupplier?.florida_county || 'Miami-Dade';
    const taxRate = getFloridaTaxRate(county);

    items.forEach(item => {
      const lineTotal = item.quantity * item.unit_price;
      subtotal += lineTotal;
      if (item.taxable) taxAmount += lineTotal * taxRate;
    });

    return { subtotal, taxAmount, total: subtotal + taxAmount };
  };

  const { subtotal, taxAmount, total } = calculateTotals();
  const selectedSupplier = suppliers.find(s => s.id === formData.supplier_id);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Validaci├│n: asegurar que hay proveedor seleccionado
    if (!formData.supplier_id) {
      alert(t('billForm.validation.supplier'));
      return;
    }

    // Validaci├│n: asegurar que hay al menos un item
    if (!items || items.length === 0) {
      alert(t('billForm.validation.items'));
      return;
    }

    const billData: Partial<Bill> = { ...formData, supplier_id: formData.supplier_id as number };
    const billItems = items.map(item => ({ ...item, product_id: item.product_id || undefined }));
    onSubmit(billData, billItems);
  };

  const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-y-auto">
      <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-6xl my-auto overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-white/5 blur-[120px] pointer-events-none"></div>

        {/* Header Hub */}
        <header className="flex items-center justify-between p-10 relative z-10">
          <div className="flex items-center gap-6">
            <div className="text-orange-500">
              {isEditing ? <Cpu className="w-8 h-8" /> : <Sparkles className="w-8 h-8" />}
            </div>
            <div>
              <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                {isEditing ? t('billForm.titleEdit') : t('billForm.titleNew')}
              </h2>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-2 flex items-center gap-2">
                <ShieldCheck className="w-3.5 h-3.5 text-orange-500" /> {t('billForm.protocol')}
              </p>
            </div>
          </div>
          <button onClick={onCancel} className="p-3 bg-slate-950/50 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95">
            <XCircle className="w-6 h-6" />
          </button>
        </header>

        <form onSubmit={handleSubmit} className="flex-1 overflow-hidden flex flex-col">
          <div className="p-10 space-y-12 overflow-y-auto custom-scrollbar max-h-[70vh]">

            {/* Phase 1: Supplier & Logic Mapping */}
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-10">
              <div className="xl:col-span-1 space-y-8">
                <div className="space-y-4">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 ml-1">
                    <Truck className="w-3.5 h-3.5 text-orange-500" /> {t('billForm.primarySupplier')}
                  </label>
                  <select
                    value={formData.supplier_id}
                    onChange={(e) => handleInputChange('supplier_id', parseInt(e.target.value) || '')}
                    className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-orange-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px] transition-all appearance-none cursor-pointer"
                    required
                  >
                    <option value="">{t('billForm.selectSupplier')}</option>
                    {suppliers.map(s => <option key={s.id} value={s.id}>{(s.business_name || s.name).toUpperCase()}</option>)}
                  </select>
                </div>

                {selectedSupplier && (
                  <div className="bg-slate-950 border border-slate-800 rounded-3xl p-6 relative group overflow-hidden">
                    <div className="absolute top-0 left-0 w-1 h-full bg-orange-500/50"></div>
                    <div className="space-y-4 relative z-10">
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{t('billForm.supplierMetadata')}</p>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <p className="text-[8px] font-bold text-slate-600 uppercase">{t('billForm.jurisdiction')}</p>
                          <p className="text-[10px] font-black text-white">{selectedSupplier.florida_county.toUpperCase()}</p>
                        </div>
                        <div>
                          <p className="text-[8px] font-bold text-slate-600 uppercase">{t('billForm.terms')}</p>
                          <p className="text-[10px] font-black text-orange-500">{selectedSupplier.payment_terms} {t('billForm.days')}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>

              <div className="xl:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-10">
                <PremiumInput label={t('billForm.issueDate')} icon={Calendar} value={formData.issue_date} onChange={(v: any) => handleInputChange('issue_date', v)} type="date" required />
                <PremiumInput label={t('billForm.dueDate')} icon={Clock} value={formData.due_date} onChange={(v: any) => handleInputChange('due_date', v)} type="date" required />

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 ml-1">
                    <Zap className="w-3.5 h-3.5 text-orange-500" /> {t('billForm.operationalStatus')}
                  </label>
                  <div className="flex bg-slate-950 rounded-2xl p-1 border border-slate-800">
                    {['draft', 'received', 'approved', 'paid'].map(s => (
                      <button
                        key={s}
                        type="button"
                        onClick={() => handleInputChange('status', s)}
                        className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${formData.status === s ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 ml-1">
                    <Info className="w-3.5 h-3.5 text-orange-500" /> {t('billForm.auditNotes')}
                  </label>
                  <input
                    type="text"
                    value={formData.notes}
                    onChange={(e) => handleInputChange('notes', e.target.value)}
                    placeholder={t('billForm.notesPlaceholder')}
                    className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-orange-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px]"
                  />
                </div>
              </div>
            </div>

            {/* Phase 2: Transaction Matrix (Line Items) */}
            <div className="space-y-8">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center gap-4">
                  <Layers className="w-6 h-6 text-orange-500" /> {t('billForm.transactionMatrix')}
                </h3>
                <button type="button" onClick={addItem} className="px-6 py-3 bg-orange-600/10 border border-orange-500/20 text-orange-500 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-orange-600 hover:text-white transition-all">
                  {t('billForm.addLine')}
                </button>
              </div>

              <div className="space-y-4">
                {items.map((item, index) => (
                  <div key={index} className="grid grid-cols-1 md:grid-cols-12 gap-6 bg-slate-950/50 p-6 rounded-[2rem] border border-slate-800 hover:border-slate-700 transition-all group/line">
                    <div className="md:col-span-3">
                      <select
                        value={item.product_id}
                        onChange={(e) => handleItemChange(index, 'product_id', parseInt(e.target.value) || '')}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-orange-500 focus:outline-none text-[10px] font-black uppercase tracking-widest"
                      >
                        <option value="">{t('billForm.productSku')}</option>
                        {products.map(p => <option key={p.id} value={p.id}>{p.name.toUpperCase()}</option>)}
                      </select>
                    </div>
                    <div className="md:col-span-3">
                      <input
                        type="text"
                        value={item.description}
                        onChange={(e) => handleItemChange(index, 'description', e.target.value)}
                        placeholder={t('billForm.description')}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-orange-500 focus:outline-none text-[10px] font-black uppercase tracking-widest"
                      />
                    </div>
                    <div className="md:col-span-2">
                      <input
                        type="number"
                        value={item.quantity}
                        onChange={(e) => handleItemChange(index, 'quantity', parseFloat(e.target.value) || 0)}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-orange-500 focus:outline-none text-[10px] font-black font-mono text-center"
                      />
                    </div>
                    <div className="md:col-span-2">
                      <input
                        type="number"
                        value={item.unit_price}
                        onChange={(e) => handleItemChange(index, 'unit_price', parseFloat(e.target.value) || 0)}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-orange-500 focus:outline-none text-[10px] font-black font-mono text-right text-emerald-500"
                      />
                    </div>
                    <div className="md:col-span-2 flex items-center justify-between gap-4">
                      <div className="text-right flex-1">
                        <p className="text-[8px] font-black text-slate-600 uppercase">{t('billForm.subtotal')}</p>
                        <p className="text-xs font-black text-white font-mono">{formatCurrency(item.quantity * item.unit_price)}</p>
                      </div>
                      <button type="button" onClick={() => removeItem(index)} className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all opacity-0 group-hover/line:opacity-100">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Phase 3: Liquid Consolidation (Totals) */}
          <footer className="p-10 border-t border-slate-800 bg-slate-950/80 relative z-10">
            <div className="flex flex-col md:flex-row items-center justify-between gap-12">
              <div className="flex gap-16 order-2 md:order-1">
                <ConsolidationStat label={t('billForm.netSubtotal')} value={formatCurrency(subtotal)} />
                <ConsolidationStat label={t('billForm.taxFlorida')} value={formatCurrency(taxAmount)} />
                <div className="group">
                  <p className="text-[10px] font-black text-orange-500 uppercase tracking-[0.3em] mb-3">{t('billForm.totalObligated')}</p>
                  <p className="text-5xl font-black text-white font-mono tracking-tighter group-hover:scale-105 transition-transform origin-left">{formatCurrency(total)}</p>
                </div>
              </div>

              <div className="flex gap-6 w-full md:w-auto order-1 md:order-2">
                <button type="button" onClick={onCancel} className="flex-1 md:flex-none px-10 py-5 bg-slate-900 border border-slate-800 text-slate-400 rounded-2.5xl font-black uppercase tracking-widest text-[10px] hover:bg-slate-800 transition-all">
                  {t('billForm.abortProtocol')}
                </button>
                <button type="submit" className="flex-1 md:flex-none px-12 py-5 bg-orange-600 hover:bg-orange-500 text-white rounded-2.5xl font-black uppercase tracking-widest text-[11px] transition-all flex items-center justify-center gap-4 shadow-3xl shadow-orange-900/40 hover:-translate-y-1 active:scale-95">
                  <Save className="w-5 h-5" />
                  {isEditing ? t('billForm.confirmAdjustment') : t('billForm.registerObligation')}
                </button>
              </div>
            </div>
          </footer>
        </form>
      </div>
    </div>
  );
};

const PremiumInput = ({ label, icon: Icon, value, onChange, type = "text", required, placeholder }: any) => (
  <div className="space-y-4">
    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 ml-1">
      <Icon className="w-3.5 h-3.5 text-orange-500" /> {label} {required && '*'}
    </label>
    <input
      type={type}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-orange-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px] transition-all"
      required={required}
    />
  </div>
);

const ConsolidationStat = ({ label, value }: any) => (
  <div className="text-left">
    <p className="text-[8px] font-black text-slate-600 uppercase tracking-widest mb-1">{label}</p>
    <p className="text-xl font-black text-slate-300 font-mono italic">{value}</p>
  </div>
);

import React, { useState } from 'react';
import {
  Eye, Edit, Trash2, FileText, Calendar, DollarSign, Truck,
  Filter, Plus, Zap, ShieldAlert, ArrowUpRight, Activity, Clock, Search
} from 'lucide-react';
import { Bill } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface BillListProps {
  bills: Bill[];
  onView: (bill: Bill) => void;
  onEdit: (bill: Bill) => void;
  onDelete: (id: number) => void;
  onAddBill: () => void;
}

export const BillList: React.FC<BillListProps> = ({
  bills,
  onView,
  onEdit,
  onDelete,
  onAddBill
}) => {
  const { t } = useLocale();
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');

  const getStatusConfig = (status: string) => {
    switch (status) {
      case 'draft': return { label: t('billList.status.draft'), color: 'text-slate-500', bg: 'bg-slate-500/10', border: 'border-slate-500/20', icon: '≡ƒô¥' };
      case 'received': return { label: t('billList.status.received'), color: 'text-amber-500', bg: 'bg-amber-500/10', border: 'border-amber-500/20', icon: '≡ƒôÑ' };
      case 'approved': return { label: t('billList.status.approved'), color: 'text-blue-500', bg: 'bg-blue-500/10', border: 'border-blue-500/20', icon: 'Γ£à' };
      case 'paid': return { label: t('billList.status.paid'), color: 'text-emerald-500', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20', icon: '≡ƒÆ░' };
      case 'overdue': return { label: t('billList.status.overdue'), color: 'text-rose-500', bg: 'bg-rose-500/10', border: 'border-rose-500/20', icon: 'ΓÜá∩╕Å' };
      case 'cancelled': return { label: t('billList.status.cancelled'), color: 'text-slate-600', bg: 'bg-slate-800/50', border: 'border-slate-700/50', icon: 'Γ¥î' };
      default: return { label: status.toUpperCase(), color: 'text-slate-400', bg: 'bg-slate-900', border: 'border-slate-800', icon: '≡ƒôä' };
    }
  };

  const filteredBills = (bills || []).filter(bill => {
    if (!bill) return false;
    const matchesStatus = statusFilter === 'all' || bill.status === statusFilter;
    const matchesSearch =
      (bill.bill_number || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (bill.supplier?.name || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (bill.supplier?.business_name || '').toLowerCase().includes(searchTerm.toLowerCase());
    return matchesStatus && matchesSearch;
  });

  const handleDelete = (bill: Bill) => {
    if (bill.status === 'paid') {
      alert(t('billList.delete.paidWarning'));
      return;
    }
    if (window.confirm(t('billList.delete.confirm', { billNumber: bill.bill_number }))) {
      onDelete(bill.id);
    }
  };

  const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      {/* Header Hub */}
      <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-orange-600/10 rounded-2.5xl border border-orange-500/20 shadow-orange-900/10 shadow-lg group">
            <FileText className="w-10 h-10 text-orange-500 group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none">{t('billList.title')}</h1>
            <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2">
              <Zap className="w-3.5 h-3.5 text-orange-500 animate-pulse" /> {t('billList.subtitle')}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-4 justify-center">
          <div className="relative group">
            <Search className="w-4 h-4 absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-500 group-focus-within:text-orange-500 transition-colors" />
            <input
              type="text"
              placeholder={t('billList.searchPlaceholder')}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-12 pr-6 py-4 bg-slate-950 text-white rounded-2xl border border-slate-800 focus:border-orange-500 focus:outline-none w-80 font-medium text-sm transition-all"
            />
          </div>

          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-6 py-4 bg-slate-950 text-white rounded-2xl border border-slate-800 focus:border-orange-500 focus:outline-none font-medium text-sm appearance-none cursor-pointer"
          >
            <option value="all">{t('billList.filter.allStatuses')}</option>
            {['draft', 'received', 'approved', 'paid', 'overdue', 'cancelled'].map(s => (
              <option key={s} value={s}>{s.toUpperCase()}</option>
            ))}
          </select>

          <button
            onClick={onAddBill}
            className="flex items-center gap-3 px-8 py-4 bg-orange-600 hover:bg-orange-500 text-white rounded-2xl font-bold text-sm transition-all shadow-xl shadow-orange-900/40 hover:-translate-y-1"
          >
            <Plus className="w-4 h-4" />
            {t('billList.button.newObligation')}
          </button>
        </div>
      </div>

      {filteredBills.length === 0 ? (
        <div className="bg-slate-900 border border-slate-800 rounded-[3.5rem] p-24 text-center border-dashed group opacity-60">
          <FileText className="w-20 h-20 text-slate-800 mx-auto mb-8 group-hover:scale-110 transition-transform duration-500" />
          <h3 className="text-2xl font-black text-white uppercase tracking-tighter mb-4">{t('billList.empty.title')}</h3>
          <p className="text-slate-500 font-black uppercase tracking-[0.2em] text-[10px]">{t('billList.empty.message')}</p>
        </div>
      ) : (
        <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-4 shadow-2xl relative group overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-orange-500/5 blur-[100px] pointer-events-none"></div>

          <div className="divide-y divide-slate-800/40">
            {filteredBills.map((bill) => {
              const cfg = getStatusConfig(bill.status);
              const isOverdue = bill.status === 'overdue';

              return (
                <div key={bill.id} className="p-8 hover:bg-white/[0.02] transition-colors relative group/item">
                  <div className="flex flex-col xl:flex-row items-start xl:items-center justify-between gap-10">
                    <div className="flex items-center gap-6 min-w-[300px]">
                      <div className={`w-14 h-14 rounded-2.2xl border shadow-lg flex items-center justify-center relative ${cfg.bg} ${cfg.border} ${cfg.color} group-hover/item:scale-105 transition-transform`}>
                        <FileText className="w-6 h-6" />
                        <span className="absolute -top-2 -right-2 text-base">{cfg.icon}</span>
                      </div>
                      <div>
                        <h3 className="text-xl font-black text-white tracking-tighter uppercase leading-none mb-2">{bill.bill_number || 'Sin ref.'}</h3>
                        <div className={`px-2 py-0.5 rounded border text-[8px] font-black uppercase tracking-widest w-fit ${cfg.bg} ${cfg.color} ${cfg.border}`}>
                          {cfg.label}
                        </div>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-12 flex-1 w-full">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-slate-950 border border-slate-800 flex items-center justify-center text-slate-500">
                          <Truck className="w-5 h-5" />
                        </div>
                        <div>
                          <p className="text-xs font-black text-white uppercase truncate max-w-[150px]">{bill.supplier?.business_name || bill.supplier?.name}</p>
                          <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">{t('billList.label.strategicAlly')}</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-slate-950 border border-slate-800 flex items-center justify-center text-slate-500">
                          <Calendar className="w-5 h-5" />
                        </div>
                        <div>
                          <p className="text-xs font-black text-white font-mono uppercase">{t('billList.label.dueDate')} {bill.due_date ? new Date(bill.due_date).toLocaleDateString() : '-'}</p>
                          <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1 italic">{t('billList.label.issueDate')} {bill.issue_date ? new Date(bill.issue_date).toLocaleDateString() : '-'}</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-slate-950 border border-slate-800 flex items-center justify-center text-slate-500">
                          <DollarSign className="w-5 h-5" />
                        </div>
                        <div>
                          <p className="text-base font-black text-orange-400 font-mono tracking-tighter">{formatCurrency(bill.total_amount || 0)}</p>
                          <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">{t('billList.label.financialLoad')}</p>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-3">
                      <button onClick={() => onView(bill)} className="p-4 bg-slate-950 border border-slate-800 rounded-2xl text-blue-500 hover:bg-blue-600 hover:text-white transition-all shadow-sm">
                        <Eye className="w-5 h-5" />
                      </button>
                      <button onClick={() => onEdit(bill)} className="p-4 bg-slate-950 border border-slate-800 rounded-2xl text-amber-500 hover:bg-amber-600 hover:text-white transition-all shadow-sm">
                        <Edit className="w-5 h-5" />
                      </button>
                      <button
                        onClick={() => handleDelete(bill)}
                        disabled={bill.status === 'paid'}
                        className={`p-4 bg-slate-950 border border-slate-800 rounded-2xl transition-all shadow-sm ${(bill.status === 'paid') ? 'opacity-30 cursor-not-allowed text-slate-700' : 'text-rose-500 hover:bg-rose-600 hover:text-white'}`}
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </div>

                  {isOverdue && (
                    <div className="mt-6 p-4 bg-rose-600/10 border border-rose-500/20 rounded-2xl flex items-center gap-4 animate-pulse">
                      <ShieldAlert className="w-5 h-5 text-rose-500" />
                      <span className="text-[10px] font-black text-rose-400 uppercase tracking-widest">
                        {bill.due_date ? t('billList.alert.overdue', { days: Math.ceil((Date.now() - new Date(bill.due_date).getTime()) / (1000 * 60 * 60 * 24)) }) : t('billList.alert.overdueNoDate')}
                      </span>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* High-Fidelity Stats Hub */}
      <div className="bg-slate-950 border border-white/5 p-12 rounded-[3.5rem] shadow-3xl relative overflow-hidden group">
        <div className="absolute top-0 left-0 w-96 h-96 bg-orange-600/5 blur-[120px] -ml-48 -mt-48 group-hover:bg-orange-600/10 transition-all duration-700"></div>

        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-12">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-orange-600/10 rounded-[2rem] border border-orange-500/20 shadow-lg">
              <Activity className="w-10 h-10 text-orange-500" />
            </div>
            <div>
              <h4 className="text-2xl font-black text-white uppercase tracking-tighter">{t('billList.analytics.title')}</h4>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">{t('billList.analytics.subtitle')}</p>
            </div>
          </div>

          <div className="grid grid-cols-2 lg:grid-cols-4 gap-12 w-full md:w-auto">
            <IntelMiniStat value={filteredBills.length} label={t('billList.analytics.documents')} color="orange" />
            <IntelMiniStat value={formatCurrency(filteredBills.reduce((sum, b) => sum + b.total_amount, 0))} label={t('billList.analytics.totalVolume')} color="emerald" isCurrency />
            <IntelMiniStat value={filteredBills.filter(b => b.status === 'paid').length} label={t('billList.analytics.settled')} color="emerald" />
            <IntelMiniStat
              value={formatCurrency(filteredBills.filter(b => b.status !== 'paid' && b.status !== 'cancelled').reduce((sum, b) => sum + b.total_amount, 0))}
              label={t('billList.analytics.pending')}
              color="rose"
              isCurrency
            />
          </div>
        </div>
      </div>
    </div>
  );
};

const IntelMiniStat = ({ value, label, color, isCurrency }: any) => {
  const colors: any = {
    orange: 'text-orange-500',
    emerald: 'text-emerald-500',
    rose: 'text-rose-500',
  };

  return (
    <div className="text-center md:text-left px-4 group">
      <div className={`font-black ${colors[color]} font-mono mb-1 leading-none ${isCurrency ? 'text-2xl tracking-tighter' : 'text-4xl'}`}>
        {value}
      </div>
      <div className="text-[8px] font-black text-slate-500 uppercase tracking-[0.3em]">{label}</div>
    </div>
  );
};

import { useState, useEffect } from 'react';
import {
  Plus, Edit2, Eye, Search,
  Building, TrendingUp, DollarSign, CreditCard,
  ChevronRight, ChevronDown, AlertCircle, CheckCircle, XCircle, AlertTriangle
} from 'lucide-react';
import { logger } from '../core/logging/SystemLogger';
import { ChartOfAccount, getChartOfAccounts, createChartOfAccount, updateChartOfAccount, deleteChartOfAccount } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';
import { suggestAccountNumber, validateAccountNumber } from '../utils/accountingUtils';
import { DoubleEntryValidator } from '../services/accounting/DoubleEntryValidator';

// Extender la interfaz para incluir propiedades de jerarqu├¡a
interface ChartOfAccountWithHierarchy extends ChartOfAccount {
  children?: ChartOfAccountWithHierarchy[];
  level?: number;
}

export function ChartOfAccounts() {
  const { t } = useLocale();
  const [accounts, setAccounts] = useState<ChartOfAccountWithHierarchy[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set(['1000', '2000', '3000', '4000', '5000']));
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<'ALL' | 'asset' | 'liability' | 'equity' | 'revenue' | 'expense'>('ALL');
  const [showInactive, setShowInactive] = useState(false);

  // Estados para CRUD
  const [showForm, setShowForm] = useState(false);
  const [editingAccount, setEditingAccount] = useState<ChartOfAccount | null>(null);
  // detail_type options grouped by account_type
  const DETAIL_TYPE_OPTIONS: Record<string, string[]> = {
    asset: ['Cash', 'Checking Account', 'Accounts Receivable', 'Inventory'],
    liability: ['Accounts Payable', 'Credit Card Payable', 'Sales Tax Payable (DR-15)', 'Reemployment Tax Payable (RT-6)'],
    equity: ["Owner's Equity", 'Retained Earnings'],
    revenue: ['Sales', 'Service Income'],
    expense: ['Cost of Goods Sold', 'Direct Labor', 'Office Supplies', 'Utilities', 'Rent', 'Advertising', 'Payroll Expenses', 'Bank Fees']
  };

  const [formData, setFormData] = useState<Partial<ChartOfAccount>>({
    account_code: '',
    number: '',
    account_name: '',
    account_type: 'asset',
    normal_balance: 'debit',
    parent_account: '',
    is_active: true,
    detail_type: ''
  });
  const [numberWarning, setNumberWarning] = useState<string | null>(null);
  // Warning de clasificaci├│n preventiva (Fase 4)
  const [classificationAlert, setClassificationAlert] = useState<string | null>(null);
  const [pendingAction, setPendingAction] = useState<'create' | 'update' | null>(null);

  useEffect(() => {
    if (showForm && !editingAccount && !formData.number && formData.account_type) {
      setFormData(prev => ({ ...prev, number: suggestAccountNumber(prev.account_type || 'asset') }));
    }
  }, [showForm, editingAccount, formData.account_type]);

  useEffect(() => {
    const warning = validateAccountNumber(formData.number || '', formData.account_type || 'asset');
    setNumberWarning(warning);
  }, [formData.number, formData.account_type]);

  useEffect(() => {
    loadChartOfAccounts();
  }, []);

  const loadChartOfAccounts = async () => {
    try {
      setLoading(true);
      logger.info('ChartOfAccounts', 'load_start', 'Iniciando carga del plan de cuentas');

      // Usar funci├│n real de la base de datos
      const flatAccounts = getChartOfAccounts();
      const hierarchicalAccounts = buildAccountHierarchy(flatAccounts);
      setAccounts(hierarchicalAccounts);

      logger.info('ChartOfAccounts', 'load_success', `Chart of accounts loaded: ${hierarchicalAccounts.length} root accounts`);
    } catch (error) {
      logger.error('ChartOfAccounts', 'load_failed', 'Error loading chart of accounts', null, error as Error);
      setError(t('chartOfAccounts.error'));
    } finally {
      setLoading(false);
    }
  };

  const handleCreateAccount = async (force = false) => {
    // Validaci├│n preventiva de clasificaci├│n
    if (!force && formData.detail_type) {
      const warn = DoubleEntryValidator.validateAccountDefinition(
        formData.account_type || 'asset',
        formData.detail_type
      );
      if (warn) {
        setClassificationAlert(warn.reason);
        setPendingAction('create');
        return;
      }
    }
    setClassificationAlert(null);
    setPendingAction(null);

    try {
      logger.info('ChartOfAccounts', 'create_start', 'Iniciando creaci├│n de nueva cuenta', { accountCode: formData.account_code });
      console.info(`[INFO] Cuenta guardada con detail_type: ${formData.detail_type || null}`);

      const result = await createChartOfAccount(formData);

      if (result.success) {
        logger.info('ChartOfAccounts', 'create_success', 'Account created successfully', { accountCode: formData.account_code, detailType: formData.detail_type || null });
        setShowForm(false);
        setFormData({
          account_code: '',
          number: '',
          account_name: '',
          account_type: 'asset',
          normal_balance: 'debit',
          parent_account: '',
          is_active: true,
          detail_type: ''
        });
        await loadChartOfAccounts();
      } else {
        logger.error('ChartOfAccounts', 'create_failed', 'Error al crear cuenta', { error: result.message });
        setError(result.message);
      }
    } catch (error) {
      logger.error('ChartOfAccounts', 'create_error', 'Exception creating account', null, error as Error);
      setError(t('chartOfAccounts.unexpectedError'));
    }
  };

  const handleEditAccount = (account: ChartOfAccount) => {
    logger.info('ChartOfAccounts', 'edit_start', 'Iniciando edici├│n de cuenta', { accountCode: account.account_code });
    setEditingAccount(account);
    setFormData({
      account_code: account.account_code,
      number: account.number || '',
      account_name: account.account_name,
      account_type: account.account_type,
      normal_balance: account.normal_balance,
      parent_account: account.parent_account || '',
      is_active: account.is_active,
      detail_type: account.detail_type || ''
    });
    setShowForm(true);
  };

  const handleUpdateAccount = async (force = false) => {
    if (!editingAccount) return;

    // Validaci├│n preventiva de clasificaci├│n
    if (!force && formData.detail_type) {
      const warn = DoubleEntryValidator.validateAccountDefinition(
        formData.account_type || 'asset',
        formData.detail_type
      );
      if (warn) {
        setClassificationAlert(warn.reason);
        setPendingAction('update');
        return;
      }
    }
    setClassificationAlert(null);
    setPendingAction(null);

    try {
      logger.info('ChartOfAccounts', 'update_start', 'Iniciando actualizaci├│n de cuenta', { accountCode: editingAccount.account_code });
      console.info(`[INFO] Cuenta guardada con detail_type: ${formData.detail_type || null}`);

      const result = await updateChartOfAccount(editingAccount.account_code, formData);

      if (result.success) {
        logger.info('ChartOfAccounts', 'update_success', 'Account updated successfully', { accountCode: editingAccount.account_code, detailType: formData.detail_type || null });
        setShowForm(false);
        setEditingAccount(null);
        setFormData({
          account_code: '',
          number: '',
          account_name: '',
          account_type: 'asset',
          normal_balance: 'debit',
          parent_account: '',
          is_active: true,
          detail_type: ''
        });
        await loadChartOfAccounts();
      } else {
        logger.error('ChartOfAccounts', 'update_failed', 'Error al actualizar cuenta', { error: result.message });
        setError(result.message);
      }
    } catch (error) {
      logger.error('ChartOfAccounts', 'update_error', 'Exception updating account', null, error as Error);
      setError(t('chartOfAccounts.unexpectedError'));
    }
  };

  const handleDeleteAccount = async (account: ChartOfAccount) => {
    if (!confirm(t('chartOfAccounts.deleteConfirm', { code: account.account_code, name: account.account_name }))) {
      return;
    }

    try {
      logger.info('ChartOfAccounts', 'delete_start', 'Iniciando eliminaci├│n de cuenta', { accountCode: account.account_code });

      const result = await deleteChartOfAccount(account.account_code);

      if (result.success) {
        logger.info('ChartOfAccounts', 'delete_success', 'Cuenta eliminada exitosamente', { accountCode: account.account_code });
        await loadChartOfAccounts(); // Recargar datos
      } else {
        logger.error('ChartOfAccounts', 'delete_failed', 'Error al eliminar cuenta', { error: result.message });
        setError(result.message);
      }
    } catch (error) {
      logger.error('ChartOfAccounts', 'delete_error', 'Exception deleting account', null, error as Error);
      setError(t('chartOfAccounts.unexpectedError'));
    }
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingAccount) {
      handleUpdateAccount();
    } else {
      handleCreateAccount();
    }
  };

  const handleCancelForm = () => {
    setShowForm(false);
    setEditingAccount(null);
    setFormData({
      account_code: '',
      number: '',
      account_name: '',
      account_type: 'asset',
      normal_balance: 'debit',
      parent_account: '',
      is_active: true,
      detail_type: ''
    });
  };

  const buildAccountHierarchy = (flatAccounts: ChartOfAccount[]): ChartOfAccountWithHierarchy[] => {
    const accountMap = new Map<string, ChartOfAccountWithHierarchy>();
    const rootAccounts: ChartOfAccountWithHierarchy[] = [];

    // Crear mapa de cuentas
    flatAccounts.forEach(account => {
      accountMap.set(account.account_code, { ...account, children: [], level: 0 });
    });

    // Construir jerarqu├¡a
    flatAccounts.forEach(account => {
      const accountNode = accountMap.get(account.account_code)!;

      if (account.parent_account) {
        const parent = accountMap.get(account.parent_account);
        if (parent) {
          parent.children!.push(accountNode);
          accountNode.level = (parent.level || 0) + 1;
        }
      } else {
        rootAccounts.push(accountNode);
      }
    });

    return rootAccounts;
  };

  const toggleNode = (accountCode: string) => {
    const newExpanded = new Set(expandedNodes);
    if (newExpanded.has(accountCode)) {
      newExpanded.delete(accountCode);
    } else {
      newExpanded.add(accountCode);
    }
    setExpandedNodes(newExpanded);
  };

  const getAccountTypeIcon = (type: string) => {
    switch (type) {
      case 'asset': return <Building className="h-4 w-4 text-green-400" />;
      case 'liability': return <CreditCard className="h-4 w-4 text-red-400" />;
      case 'equity': return <TrendingUp className="h-4 w-4 text-blue-400" />;
      case 'revenue': return <DollarSign className="h-4 w-4 text-emerald-400" />;
      case 'expense': return <TrendingUp className="h-4 w-4 text-orange-400 rotate-180" />;
      default: return <AlertCircle className="h-4 w-4 text-slate-500" />;
    }
  };

  const getAccountTypeColor = (type: string) => {
    switch (type) {
      case 'asset': return 'text-green-400';
      case 'liability': return 'text-red-400';
      case 'equity': return 'text-blue-400';
      case 'revenue': return 'text-emerald-400';
      case 'expense': return 'text-orange-400';
      default: return 'text-slate-500';
    }
  };

  const renderAccount = (account: ChartOfAccountWithHierarchy, level: number = 0) => {
    const hasChildren = account.children && account.children.length > 0;
    const isExpanded = expandedNodes.has(account.account_code);
    const indent = level * 24;

    // Filtros
    if (filterType !== 'ALL' && account.account_type !== filterType) return null;
    if (!showInactive && !account.is_active) return null;
    if (searchTerm && !account.account_name.toLowerCase().includes(searchTerm.toLowerCase()) &&
      !account.account_code.includes(searchTerm)) return null;

    return (
      <div key={account.account_code}>
        <div
          className={`flex items-center py-2 px-4 hover:bg-white/5 border-l-2 ${account.is_active ? 'border-transparent' : 'border-white/10'
            }`}
          style={{ paddingLeft: `${16 + indent}px` }}
        >
          {/* Expand/Collapse */}
          <div className="w-6 flex justify-center">
            {hasChildren ? (
              <button
                onClick={() => toggleNode(account.account_code)}
                className="text-slate-500 hover:text-white transition-colors"
              >
                {isExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
              </button>
            ) : (
              <div className="w-4" />
            )}
          </div>

          {/* Icono de tipo */}
          <div className="mr-3">
            {getAccountTypeIcon(account.account_type)}
          </div>

          {/* C├│digo de cuenta */}
          <div className="w-20 font-mono text-slate-400 flex flex-col justify-center leading-tight">
            <span className="text-sm font-bold text-blue-400">{account.number || 'N/A'}</span>
            <span className="text-[10px] opacity-70">{account.account_code}</span>
          </div>

          {/* Nombre de cuenta */}
          <div className={`flex-1 text-white font-black uppercase tracking-tight ${level === 0 ? 'text-sm' : 'text-xs opacity-90 font-bold'}`}>
            {account.account_name}
          </div>

          {/* Tipo de cuenta */}
          <div className={`text-xs px-2 py-1 rounded ${getAccountTypeColor(account.account_type)} bg-white/5`}>
            {t(`chartOfAccounts.type${account.account_type.charAt(0).toUpperCase() + account.account_type.slice(1)}`)}
          </div>

          {/* Balance normal */}
          <div className="w-20 text-[10px] font-black uppercase text-center text-slate-600">
            {t(`chartOfAccounts.${account.normal_balance}`)}
          </div>

          {/* Estado */}
          <div className="w-16 text-center">
            {account.is_active ? (
              <CheckCircle className="h-4 w-4 text-green-400 mx-auto" />
            ) : (
              <AlertCircle className="h-4 w-4 text-slate-600 mx-auto" />
            )}
          </div>

          {/* Acciones */}
          <div className="flex space-x-2 ml-4">
            <button
              onClick={() => handleEditAccount(account)}
              className="text-blue-400 hover:text-blue-300 transition-colors"
              title={t('chartOfAccounts.editAccount')}
            >
              <Edit2 className="h-4 w-4" />
            </button>
            <button
              onClick={() => handleDeleteAccount(account)}
              className="text-red-400 hover:text-red-300 transition-colors"
              title={t('chartOfAccounts.deleteAccount')}
            >
              <AlertCircle className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Cuentas hijas */}
        {hasChildren && isExpanded && (
          <div>
            {account.children!.map(child => renderAccount(child, level + 1))}
          </div>
        )}
      </div>
    );
  };

  if (loading) {
    return (
      <div className="bg-white/10 rounded-lg p-8">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-slate-500">{t('chartOfAccounts.loading')}</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-900/20 border border-red-700 rounded-lg p-8">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-400 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-red-300 mb-2">Error</h3>
          <p className="text-red-200">{error}</p>
          <button
            onClick={loadChartOfAccounts}
            className="mt-4 bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded-xl transition-all font-bold shadow-lg shadow-red-900/40 active:scale-95"
          >
            {t('chartOfAccounts.retry')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight">
            <Building className="w-8 h-8 text-blue-500" />
            {t('chartOfAccounts.title')}
          </h2>
          <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mt-1">
            {t('chartOfAccounts.subtitle')}
          </p>
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-xl flex items-center gap-2 transition-all font-bold shadow-lg shadow-blue-900/40 active:scale-95"
        >
          <Plus className="h-4 w-4" />
          <span>{t('chartOfAccounts.newAccount')}</span>
        </button>
      </div>

      <div className="bg-slate-900/40 border border-slate-800/50 rounded-2xl p-4 mb-6">
        <div className="flex flex-wrap gap-4 items-center">
          <div className="flex-1 min-w-64">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 h-3.5 w-3.5" />
              <input
                type="text"
                placeholder={t('chartOfAccounts.searchPlaceholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-slate-950/50 border border-slate-800/50 text-white pl-10 pr-4 py-2 rounded-xl text-xs focus:outline-none focus:border-blue-500/50"
              />
            </div>
          </div>

          <div>
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value as any)}
              className="bg-slate-950/50 border border-slate-800/50 text-slate-300 px-3 py-2 rounded-xl text-xs focus:outline-none focus:border-blue-500/50"
            >
              <option value="ALL" className="bg-slate-900">{t('chartOfAccounts.filterAll')}</option>
              <option value="asset" className="bg-slate-900">{t('chartOfAccounts.typeAsset')}</option>
              <option value="liability" className="bg-slate-900">{t('chartOfAccounts.typeLiability')}</option>
              <option value="equity" className="bg-slate-900">{t('chartOfAccounts.typeEquity')}</option>
              <option value="revenue" className="bg-slate-900">{t('chartOfAccounts.typeRevenue')}</option>
              <option value="expense" className="bg-slate-900">{t('chartOfAccounts.typeExpense')}</option>
            </select>
          </div>

          <label className="flex items-center space-x-2 text-slate-500 cursor-pointer">
            <input
              type="checkbox"
              checked={showInactive}
              onChange={(e) => setShowInactive(e.target.checked)}
              className="rounded border-slate-800 bg-slate-950 text-blue-600"
            />
            <span className="text-[10px] font-bold uppercase tracking-wider">{t('chartOfAccounts.showInactive')}</span>
          </label>
        </div>
      </div>

      <div className="bg-slate-900/40 border border-slate-800/50 rounded-2xl overflow-hidden shadow-2xl">
        <div className="bg-slate-950/30 px-4 py-3 border-b border-slate-800/50">
          <div className="flex items-center text-[10px] font-black text-slate-500 uppercase tracking-widest" style={{ paddingLeft: '40px' }}>
            <div className="w-20 pl-2">{t('chartOfAccounts.colCode')}</div>
            <div className="flex-1 ml-3">{t('chartOfAccounts.colName')}</div>
            <div className="w-24 text-center">{t('chartOfAccounts.colType')}</div>
            <div className="w-20 text-center">{t('chartOfAccounts.colBalance')}</div>
            <div className="w-16 text-center">{t('chartOfAccounts.colStatus')}</div>
            <div className="w-20 text-center">{t('chartOfAccounts.colActions')}</div>
          </div>
        </div>

        <div className="max-h-[600px] overflow-y-auto custom-scrollbar">
          {accounts.length === 0 ? (
            <div className="text-center py-12 text-slate-600">
              <AlertCircle className="h-12 w-12 mx-auto mb-4" />
              <p>{t('chartOfAccounts.noAccountsFound')}</p>
            </div>
          ) : (
            accounts.map(account => renderAccount(account))
          )}
        </div>
      </div>

      {/* Resumen */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        {['asset', 'liability', 'equity', 'revenue', 'expense'].map(type => {
          const count = accounts.reduce((acc, account) => {
            const countInTree = (acc: ChartOfAccountWithHierarchy): number => {
              let count = acc.account_type === type ? 1 : 0;
              if (acc.children) {
                count += acc.children.reduce((sum, child) => sum + countInTree(child), 0);
              }
              return count;
            };
            return acc + countInTree(account);
          }, 0);

          return (
            <div key={type} className="bg-white/10 rounded-lg p-4 text-center">
              <div className="mb-2">{getAccountTypeIcon(type)}</div>
              <div className="text-2xl font-black tracking-tight text-white">{count}</div>
              <div className={`text-sm ${getAccountTypeColor(type)}`}>
                {type === 'asset' ? t('chartOfAccounts.typeAsset') :
                  type === 'liability' ? t('chartOfAccounts.typeLiability') :
                    type === 'equity' ? t('chartOfAccounts.typeEquity') :
                      type === 'revenue' ? t('chartOfAccounts.typeRevenue') : t('chartOfAccounts.typeExpense')}
              </div>
            </div>
          );
        })}
      </div>

      {/* Modal de formulario */}
      {showForm && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] p-10 w-full max-w-xl shadow-[0_0_50px_rgba(0,0,0,0.5)] animate-in zoom-in duration-300 relative group">
            <div className="flex items-start justify-between mb-10">
              <h3 className="text-2xl font-black text-white tracking-tighter uppercase">
                {editingAccount ? t('chartOfAccounts.editAccount') : t('chartOfAccounts.newAccount')}
              </h3>
              <button
                onClick={() => setShowForm(false)}
                className="p-3 bg-slate-950/50 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95"
              >
                <XCircle className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleFormSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex gap-4">
                  <div className="flex-1">
                    <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                      {t('chartOfAccounts.formCode')}
                    </label>
                    <input
                      type="text"
                      value={formData.account_code}
                      onChange={(e) => setFormData({ ...formData, account_code: e.target.value })}
                      className="w-full bg-slate-950/50 border border-slate-800/50 text-white px-4 py-3 rounded-2xl focus:outline-none focus:border-blue-500/50 transition-all font-mono text-sm"
                      placeholder="e.g. 1000"
                      required
                      disabled={!!editingAccount}
                    />
                  </div>
                  <div className="flex-1">
                    <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                      N├ÜMERO GAAP
                    </label>
                    <input
                      type="text"
                      maxLength={5}
                      value={formData.number || ''}
                      onChange={(e) => setFormData({ ...formData, number: e.target.value.replace(/\D/g, '') })}
                      className={`w-full bg-slate-950/50 border text-white px-4 py-3 rounded-2xl focus:outline-none transition-all font-mono text-sm ${numberWarning ? 'border-orange-500/50 focus:border-orange-500/50' : 'border-slate-800/50 focus:border-blue-500/50'}`}
                      placeholder="e.g. 10100"
                    />
                    {numberWarning && (
                      <div className="flex items-center gap-1 mt-2 text-orange-400">
                        <AlertCircle className="w-3 h-3" />
                        <span className="text-[9px] font-medium">{numberWarning}</span>
                      </div>
                    )}
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                    {t('chartOfAccounts.formName')}
                  </label>
                  <input
                    type="text"
                    value={formData.account_name}
                    onChange={(e) => setFormData({ ...formData, account_name: e.target.value })}
                    className="w-full bg-slate-950/50 border border-slate-800/50 text-white px-4 py-3 rounded-2xl focus:outline-none focus:border-blue-500/50 transition-all uppercase font-bold text-xs"
                    placeholder={t('chartOfAccounts.formName')}
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                    {t('chartOfAccounts.formType')}
                  </label>
                  <select
                    value={formData.account_type}
                    onChange={(e) => setFormData({ ...formData, account_type: e.target.value as any })}
                    className="w-full bg-slate-950/50 border border-slate-800/50 text-white px-4 py-3 rounded-2xl focus:outline-none focus:border-blue-500/50 transition-all"
                    required
                  >
                    <option value="asset" className="bg-slate-900">{t('chartOfAccounts.activo')}</option>
                    <option value="liability" className="bg-slate-900">{t('chartOfAccounts.pasivo')}</option>
                    <option value="equity" className="bg-slate-900">{t('chartOfAccounts.patrimonio')}</option>
                    <option value="revenue" className="bg-slate-900">{t('chartOfAccounts.ingreso')}</option>
                    <option value="expense" className="bg-slate-900">{t('chartOfAccounts.gasto')}</option>
                  </select>
                </div>

                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                    {t('chartOfAccounts.formBalance')}
                  </label>
                  <select
                    value={formData.normal_balance}
                    onChange={(e) => setFormData({ ...formData, normal_balance: e.target.value as any })}
                    className="w-full bg-slate-950/50 border border-slate-800/50 text-white px-4 py-3 rounded-2xl focus:outline-none focus:border-blue-500/50 transition-all"
                    required
                  >
                    <option value="debit" className="bg-slate-900">{t('chartOfAccounts.debito')}</option>
                    <option value="credit" className="bg-slate-900">{t('chartOfAccounts.credito')}</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                  {t('chartOfAccounts.formParent')}
                </label>
                <input
                  type="text"
                  value={formData.parent_account}
                  onChange={(e) => setFormData({ ...formData, parent_account: e.target.value })}
                  className="w-full bg-slate-950/50 border border-slate-800/50 text-white px-4 py-3 rounded-2xl focus:outline-none focus:border-blue-500/50 transition-all font-mono"
                  placeholder="1000"
                />
              </div>

              {/* Detail Type ΓÇö filtrado din├ímicamente por account_type */}
              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 px-1">
                  DETAIL TYPE
                  <span className="ml-2 text-slate-600 normal-case font-normal">(opcional)</span>
                </label>
                <select
                  id="detail_type"
                  value={formData.detail_type || ''}
                  onChange={(e) => setFormData({ ...formData, detail_type: e.target.value })}
                  className="w-full bg-slate-950/50 border border-slate-800/50 text-white px-4 py-3 rounded-2xl focus:outline-none focus:border-blue-500/50 transition-all text-sm"
                >
                  <option value="" className="bg-slate-900 text-slate-400">ΓÇö Sin clasificar ΓÇö</option>
                  {(DETAIL_TYPE_OPTIONS[formData.account_type || 'asset'] || []).map((opt) => (
                    <option key={opt} value={opt} className="bg-slate-900">
                      {opt}
                    </option>
                  ))}
                </select>
                {formData.detail_type && (
                  <p className="mt-1.5 text-[10px] text-blue-400 px-1">
                    Γ£ô Detail type: <span className="font-bold">{formData.detail_type}</span>
                  </p>
                )}
              </div>

              <div className="flex items-center gap-3 px-1">
                <input
                  type="checkbox"
                  id="is_active"
                  checked={formData.is_active}
                  onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  className="w-4 h-4 rounded border-slate-800 bg-slate-950 text-blue-600 focus:ring-0 focus:ring-offset-0"
                />
                <label htmlFor="is_active" className="text-[10px] font-bold text-slate-500 uppercase tracking-widest cursor-pointer">
                  {t('chartOfAccounts.formActive')}
                </label>
              </div>

              {/* ΓöÇΓöÇ ALERTA DE CLASIFICACI├ôN PREVENTIVA (Fase 4) ΓöÇΓöÇ */}
              {classificationAlert && (
                <div className="bg-orange-900/20 border border-orange-500/40 rounded-2xl p-4 animate-in slide-in-from-top duration-300">
                  <div className="flex items-start gap-3">
                    <div className="p-1.5 bg-orange-500/10 rounded-lg shrink-0">
                      <AlertTriangle className="w-4 h-4 text-orange-400" />
                    </div>
                    <div className="flex-1">
                      <p className="text-[9px] font-black text-orange-400 uppercase tracking-widest mb-1.5">
                        Alerta de Clasificaci├│n
                      </p>
                      <p className="text-xs text-orange-200 font-bold leading-relaxed italic">
                        {classificationAlert}
                      </p>
                      <div className="flex gap-3 mt-3">
                        <button
                          type="button"
                          onClick={() => setClassificationAlert(null)}
                          className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-white transition-colors"
                        >
                          Corregir
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            if (pendingAction === 'create') handleCreateAccount(true);
                            if (pendingAction === 'update') handleUpdateAccount(true);
                          }}
                          className="text-[9px] font-black uppercase tracking-widest text-orange-400 hover:text-orange-300 transition-colors"
                        >
                          Continuar de todas formas
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <div className="flex gap-4 pt-6">
                <button
                  type="submit"
                  className="flex-1 bg-blue-600 hover:bg-blue-500 text-white py-3.5 px-6 rounded-xl font-bold uppercase tracking-widest text-xs transition-all shadow-xl shadow-blue-900/40 active:scale-95"
                >
                  {editingAccount ? t('chartOfAccounts.update') : t('chartOfAccounts.create')}
                </button>
                <button
                  type="button"
                  onClick={() => setShowForm(false)}
                  className="flex-1 bg-slate-800 hover:bg-slate-700 text-slate-300 py-3.5 px-6 rounded-xl font-bold uppercase tracking-widest text-xs transition-all active:scale-95"
                >
                  {t('chartOfAccounts.cancel')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Building2, AlertTriangle, CheckCircle, Save, RefreshCw, Shield, FileText, Users, Receipt, XCircle, Cloud } from 'lucide-react';
import { getCompanyData, updateCompanyData, checkAccountingDataAssociation, CompanyData } from '@/database/simple-db';
import { logger } from '../core/logging/SystemLogger';
import { LogoUploader } from './LogoUploader';
import { BackupService } from '../services/backup/BackupService';
import { useLocale } from '../i18n/useLocale';

interface CompanyDataFormProps {
  onClose?: () => void;
}

export function CompanyDataForm({ onClose }: CompanyDataFormProps) {
  const { t } = useLocale();
  const [companyData, setCompanyData] = useState<CompanyData | null>(null);
  const [formData, setFormData] = useState<Partial<CompanyData>>({});
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [accountingCheck, setAccountingCheck] = useState({ hasData: false, customers: 0, suppliers: 0, invoices: 0, bills: 0 });
  const [showWarningModal, setShowWarningModal] = useState(false);
  const [pendingChanges, setPendingChanges] = useState<Partial<CompanyData>>({});
  const [activeTab, setActiveTab] = useState<'empresa' | 'finanzas' | 'usuarios'>('empresa');
  const [isCloudLinked, setIsCloudLinked] = useState(false);

  useEffect(() => {
    loadCompanyData();
    checkAccountingAssociations();

    const token = localStorage.getItem('gdrive_token');
    setIsCloudLinked(!!token);
  }, []);

  const handleCloudLink = () => {
    if (isCloudLinked) {
      if (window.confirm(t('companyData.cloud.confirmDisconnect'))) {
        localStorage.removeItem('gdrive_token');
        setIsCloudLinked(false);
      }
    } else {
      BackupService.initiateCloudLink();
    }
  };

  const loadCompanyData = async () => {
    try {
      setLoading(true);
      setError(null);

      logger.info('CompanyDataForm', 'load_start', 'Cargando datos de empresa');

      const data = getCompanyData();
      if (data) {
        setCompanyData(data);
        setFormData(data);
        logger.info('CompanyDataForm', 'load_success', 'Datos de empresa cargados');
      } else {
        setError('No se encontraron datos de empresa. Contacte al administrador.');
        logger.warn('CompanyDataForm', 'no_data', 'No se encontraron datos de empresa');
      }

    } catch (error) {
      logger.error('CompanyDataForm', 'load_failed', 'Error al cargar datos de empresa', null, error as Error);
      setError(`Error al cargar los datos de la empresa: ${error instanceof Error ? error.message : String(error)}`);
    } finally {
      setLoading(false);
    }
  };

  const checkAccountingAssociations = () => {
    try {
      const check = checkAccountingDataAssociation();
      setAccountingCheck(check);
      logger.info('CompanyDataForm', 'accounting_check', 'Verificaci├│n de datos contables', check);
    } catch (error) {
      logger.error('CompanyDataForm', 'accounting_check_failed', 'Error al verificar datos contables', null, error as Error);
    }
  };

  const handleInputChange = (field: keyof CompanyData, value: string | number) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSave = async (skipWarning: boolean = false) => {
    try {
      setSaving(true);
      setError(null);
      setSuccess(null);
      setWarnings([]);

      if (!skipWarning && accountingCheck.hasData) {
        const criticalFields = ['company_name', 'legal_name', 'tax_id'];
        const hasCriticalChanges = criticalFields.some(field =>
          formData[field as keyof CompanyData] !== companyData?.[field as keyof CompanyData]
        );

        if (hasCriticalChanges) {
          setPendingChanges(formData);
          setShowWarningModal(true);
          setSaving(false);
          return;
        }
      }

      logger.info('CompanyDataForm', 'save_start', 'Guardando datos de empresa', formData);

      const result = await updateCompanyData(formData);

      if (result.success) {
        setSuccess(result.message);
        if (result.warnings) {
          setWarnings(result.warnings);
        }

        await loadCompanyData();

        logger.info('CompanyDataForm', 'save_success', 'Datos de empresa guardados correctamente');

        // Dar un momento para ver el mensaje de ├⌐xito antes de cerrar
        if (onClose) {
          setTimeout(() => {
            onClose();
          }, 1500);
        }
      } else {
        setError(result.message);
        logger.error('CompanyDataForm', 'save_failed', 'Error al guardar datos de empresa', { error: result.message });
      }

    } catch (error) {
      logger.error('CompanyDataForm', 'save_exception', 'Excepci├│n al guardar datos de empresa', null, error as Error);
      setError(`Error al guardar: ${error instanceof Error ? error.message : 'Error desconocido'}`);
    } finally {
      setSaving(false);
      setShowWarningModal(false);
      setPendingChanges({});
    }
  };

  const confirmSaveWithWarning = () => {
    setFormData(pendingChanges);
    handleSave(true);
  };

  const cancelSaveWithWarning = () => {
    setShowWarningModal(false);
    setPendingChanges({});
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="bg-slate-900 rounded-3xl p-12 border border-slate-800 flex flex-col items-center justify-center animate-pulse">
        <div className="relative mb-6">
          <div className="h-16 w-16 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin"></div>
        </div>
        <p className="text-slate-300 font-black uppercase tracking-widest text-xs">{t('companyData.loading')}</p>
      </div>
    );
  }

  if (error && !companyData) {
    return (
      <div className="bg-rose-500/10 border border-rose-500/20 rounded-3xl p-8 flex flex-col items-center text-center">
        <div className="p-4 bg-rose-500/20 rounded-2xl mb-4">
          <AlertTriangle className="h-8 w-8 text-rose-400" />
        </div>
        <h3 className="text-xl font-black text-rose-300 mb-2">{t('companyData.error')}</h3>
        <p className="text-rose-200/70 font-medium max-w-md">{error}</p>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
      <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-6xl max-h-[92vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-500/5 blur-[120px] pointer-events-none"></div>

        {/* Header Hub */}
        <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
          <div className="flex items-center gap-6">
            <div className="p-4 bg-blue-600/10 rounded-2.5xl border border-blue-500/20 shadow-blue-900/10 shadow-lg">
              <Building2 className="h-10 w-10 text-blue-500" />
            </div>
            <div>
              <h1 className="text-3xl font-black text-white tracking-tighter uppercase leading-none">{t('companyData.title')}</h1>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2 flex items-center gap-2">
                <Shield className="w-3.5 h-3.5 text-blue-500" /> {t('companyData.subtitle')}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-6">
            <button
              onClick={() => handleSave()}
              disabled={saving}
              className="bg-blue-600 hover:bg-blue-700 disabled:bg-slate-800 text-white px-6 py-2.5 rounded-xl flex items-center space-x-3 transition-all font-bold shadow-lg shadow-blue-900/40 active:scale-95"
            >
              {saving ? (
                <RefreshCw className="h-4 w-4 animate-spin" />
              ) : (
                <Save className="h-4 w-4" />
              )}
              <span className="text-xs">{saving ? t('companyData.saving') : t('companyData.saveButton')}</span>
            </button>
            <button
              onClick={() => onClose ? onClose() : window.history.back()}
              className="p-3 bg-slate-950/50 border border-slate-800 rounded-xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95"
            >
              <XCircle className="w-6 h-6" />
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col">
          <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">
            {/* Alertas de datos contables */}
            {accountingCheck.hasData && (
              <div className="bg-amber-500/5 border border-amber-500/20 rounded-[2.5rem] p-10 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                  <Shield className="w-32 h-32 text-amber-500" />
                </div>
                <div className="flex items-start space-x-8 relative z-10">
                  <div className="p-5 bg-amber-500/20 rounded-2xl">
                    <Shield className="h-8 w-8 text-amber-400" />
                  </div>
                  <div className="flex-1">
                    <h3 className="text-xl font-black text-amber-400 mb-2 uppercase tracking-tight">{t('companyData.alert.title')}</h3>
                    <p className="text-amber-200/70 font-medium mb-8 text-sm leading-relaxed max-w-2xl">
                      {t('companyData.alert.description')}
                    </p>
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                      <MetricCard icon={Users} label={t('companyData.alert.customers')} value={accountingCheck.customers} color="blue" />
                      <MetricCard icon={Building2} label={t('companyData.alert.suppliers')} value={accountingCheck.suppliers} color="emerald" />
                      <MetricCard icon={FileText} label={t('companyData.alert.invoices')} value={accountingCheck.invoices} color="purple" />
                      <MetricCard icon={Receipt} label={t('companyData.alert.bills')} value={accountingCheck.bills} color="orange" />
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Mensajes de estado */}
            <div className="space-y-4">
              {error && (
                <div className="bg-rose-500/10 border border-rose-500/20 rounded-2xl p-6 flex items-center gap-4 animate-in slide-in-from-top-4">
                  <div className="p-2 bg-rose-500/20 rounded-lg">
                    <AlertTriangle className="h-5 w-5 text-rose-400" />
                  </div>
                  <p className="text-rose-300 font-bold text-sm tracking-tight">{error}</p>
                </div>
              )}

              {success && (
                <div className="bg-emerald-500/10 border border-emerald-500/20 rounded-2xl p-6 flex items-center gap-4 animate-in slide-in-from-top-4">
                  <div className="p-2 bg-emerald-500/20 rounded-lg">
                    <CheckCircle className="h-5 w-5 text-emerald-400" />
                  </div>
                  <p className="text-emerald-300 font-bold text-sm tracking-tight">{success}</p>
                </div>
              )}
            </div>

            {/* Formulario con pesta├▒as */}
            {companyData && (
              <div className="bg-slate-950/30 rounded-[2.5rem] border border-slate-800/80 overflow-hidden shadow-inner flex flex-col flex-1 min-h-0">
                {/* Pesta├▒as Modernas */}
                <div className="bg-slate-950/50 px-10 pt-8 border-b border-slate-800">
                  <nav className="flex space-x-12">
                    {[
                      { id: 'empresa', label: t('companyData.tab.company'), icon: Building2 },
                      { id: 'finanzas', label: t('companyData.tab.finance'), icon: Receipt },
                      { id: 'usuarios', label: t('companyData.tab.users'), icon: Shield }
                    ].map((tab: any) => (
                      <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`flex items-center gap-4 py-6 px-4 font-black text-[10px] uppercase tracking-[0.2em] transition-all relative ${activeTab === tab.id
                          ? 'text-blue-400'
                          : 'text-slate-500 hover:text-slate-300'
                          }`}
                      >
                        <tab.icon className={`w-4 h-4 ${activeTab === tab.id ? 'text-blue-500' : 'text-slate-600'}`} />
                        {tab.label}
                        {activeTab === tab.id && (
                          <div className="absolute bottom-0 left-0 w-full h-1 bg-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.6)] rounded-t-full"></div>
                        )}
                      </button>
                    ))}
                  </nav>
                </div>

                {/* Contenido de pesta├▒as */}
                <div className="flex-1 overflow-y-auto p-12 custom-scrollbar">
                  {activeTab === 'empresa' && (
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 animate-in fade-in duration-500">
                      {/* Logo Section */}
                      <div className="lg:col-span-4 space-y-10">
                        <section>
                          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-3 mb-8">
                            <div className="w-2 h-2 bg-blue-500 rounded-full shadow-[0_0_10px_rgba(59,130,246,0.5)]"></div>
                            {t('companyData.visual.title')}
                          </h3>
                          <div className="bg-slate-950/80 p-10 rounded-[2.5rem] border-2 border-slate-800 border-dashed hover:border-blue-500/30 transition-all group flex flex-col items-center justify-center">
                            <LogoUploader
                              currentLogo={formData.logo_path || ''}
                              onLogoChange={(logoPath) => handleInputChange('logo_path', logoPath || '')}
                              disabled={saving}
                            />
                          </div>
                        </section>

                        {/* Cloud Vault Section */}
                        <section className="pt-10 border-t border-slate-800/50">
                          <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-widest flex items-center gap-3 mb-8">
                            <Cloud className="w-4 h-4 shadow-[0_0_10px_rgba(59,130,246,0.3)]" />
                            {t('companyData.cloud.title')}
                          </h3>
                          <div className={`p-8 rounded-[2rem] border transition-all ${isCloudLinked ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-slate-900/50 border-slate-800 shadow-inner'}`}>
                            <div className="flex items-center gap-5 mb-6">
                              <div className={`p-3 rounded-2xl ${isCloudLinked ? 'bg-emerald-500/20' : 'bg-slate-950 border border-slate-800'}`}>
                                {isCloudLinked ? <CheckCircle className="w-6 h-6 text-emerald-500" /> : <AlertTriangle className="w-6 h-6 text-slate-500" />}
                              </div>
                              <span className={`text-sm font-black uppercase tracking-tight ${isCloudLinked ? 'text-emerald-400' : 'text-slate-400'}`}>
                                {isCloudLinked ? t('companyData.cloud.linked') : t('companyData.cloud.notLinked')}
                              </span>
                            </div>
                            <p className="text-xs text-slate-500 mb-8 leading-relaxed font-bold">
                              {isCloudLinked ? t('companyData.cloud.linkedDesc') : t('companyData.cloud.notLinkedDesc')}
                            </p>
                            <button
                              type="button"
                              onClick={handleCloudLink}
                              className={`w-full py-3 px-6 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all shadow-lg active:scale-95 ${isCloudLinked
                                ? 'bg-slate-950 border border-slate-800 text-slate-400 hover:text-white hover:bg-slate-900'
                                : 'bg-blue-600 text-white hover:bg-blue-500 shadow-blue-900/40'
                                }`}
                            >
                              {isCloudLinked ? t('companyData.cloud.disconnect') : t('companyData.cloud.connect')}
                            </button>
                          </div>
                        </section>
                      </div>

                      {/* Informaci├│n b├ísica */}
                      <div className="lg:col-span-8 space-y-12">
                        <section className="space-y-10">
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                            <DataInput label={t('companyData.field.companyName')} value={formData.company_name || ''} onChange={(v: any) => handleInputChange('company_name', v)} />
                            <DataInput label={t('companyData.field.legalName')} value={formData.legal_name || ''} onChange={(v: any) => handleInputChange('legal_name', v)} />
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                            <DataInput label={t('companyData.field.taxId')} value={formData.tax_id || ''} onChange={(v: any) => handleInputChange('tax_id', v)} mono />
                            <div className="md:col-span-2">
                              <DataInput label={t('companyData.field.address')} value={formData.address || ''} onChange={(v: any) => handleInputChange('address', v)} />
                            </div>
                          </div>

                          <div className="grid grid-cols-2 lg:grid-cols-4 gap-10">
                            <div className="col-span-2">
                              <DataInput label={t('companyData.field.city')} value={formData.city || ''} onChange={(v: any) => handleInputChange('city', v)} />
                            </div>
                            <div className="space-y-4">
