        <div className="text-sm text-slate-500 space-y-1">
          <p>ΓÇó <strong>{t('customerForm.infoItem1')}</strong></p>
          <p>ΓÇó <strong>{t('customerForm.infoItem2')}</strong></p>
          <p>ΓÇó <strong>{t('customerForm.infoItem3')}</strong></p>
          <p>ΓÇó <strong>{t('customerForm.infoItem4')}</strong></p>
          <p>ΓÇó <strong>{t('customerForm.infoItem5')}</strong></p>
          <p>ΓÇó {t('common.requiredField')}</p>
