          </label>
          <select
            value={formData.assigned_salesperson}
            onChange={(e) => handleInputChange('assigned_salesperson', e.target.value)}
            className="w-full bg-white/5 text-white px-4 py-2 rounded-md border border-white/10 focus:border-blue-500 focus:outline-none"
          >
            <option value="">{t('customerForm.unassigned')}</option>
            <option value="Ana Garc├¡a">Ana Garc├¡a</option>
            <option value="Carlos L├│pez">Carlos L├│pez</option>
            <option value="Mar├¡a Rodr├¡guez">Mar├¡a Rodr├¡guez</option>
            <option value="Juan Mart├¡nez">Juan Mart├¡nez</option>
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-slate-400 mb-1">
            {t('customerForm.status')}
          </label>
          <select
            value={formData.status}
            onChange={(e) => handleInputChange('status', e.target.value)}
            className="w-full bg-white/5 text-white px-4 py-2 rounded-md border border-white/10 focus:border-blue-500 focus:outline-none"
          >
            <option value="active">{t('common.active')}</option>
            <option value="inactive">{t('common.inactive')}</option>
            <option value="suspended">{t('common.suspended')}</option>
          </select>
        </div>

        <div className="flex items-center space-x-3 pt-6">
          <input
            type="checkbox"
            id="tax_exempt"
            checked={formData.tax_exempt}
            onChange={(e) => handleInputChange('tax_exempt', e.target.checked)}
            className="w-4 h-4 text-blue-600 bg-white/5 border-white/10 rounded focus:ring-blue-500"
          />
          <label htmlFor="tax_exempt" className="text-sm font-medium text-slate-400">
            {t('customerForm.taxExempt')}
          </label>
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-slate-400 mb-1">
          {t('customerForm.notes')}
        </label>
        <textarea
          value={formData.notes}
          onChange={(e) => handleInputChange('notes', e.target.value)}
          rows={3}
          className="w-full bg-white/5 text-white px-4 py-2 rounded-md border border-white/10 focus:border-blue-500 focus:outline-none"
          placeholder={t('customerForm.notesPlaceholder')}
        />
      </div>
    </div>
  );
  return (
    <div className="bg-white/10 rounded-lg p-6">
      <h2 className="text-xl font-semibold mb-6 flex items-center gap-2">
        {isEditing ? (
          <>
            <Save className="w-5 h-5 text-blue-500" />
            {t('customerForm.titleEdit')}
          </>
        ) : (
          <>
            <Plus className="w-5 h-5 text-green-500" />
            {t('customerForm.titleNew')}
          </>
        )}
      </h2>

      {/* Pesta├▒as */}
      <div className="flex space-x-1 mb-6 bg-slate-900 p-1 rounded-lg">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors flex-1 text-sm ${activeTab === tab.id
              ? 'bg-blue-600 text-white'
              : 'text-slate-400 hover:bg-white/5 hover:text-white'
              }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <form onSubmit={handleSubmit}>
        {/* Contenido de las pesta├▒as */}
        <div className="min-h-[400px]">
          {activeTab === 'personal' && renderPersonalTab()}
          {activeTab === 'contact' && renderContactTab()}
          {activeTab === 'address' && renderAddressTab()}
          {activeTab === 'commercial' && renderCommercialTab()}
        </div>

        {/* Botones */}
        <div className="flex justify-between pt-6 border-t border-white/10">
          <div className="flex space-x-3">
            {activeTab !== 'personal' && (
              <button
                type="button"
                onClick={() => {
                  const currentIndex = tabs.findIndex(tab => tab.id === activeTab);
                  if (currentIndex > 0) {
                    setActiveTab(tabs[currentIndex - 1].id);
                  }
                }}
                className="px-4 py-2 bg-gray-600 hover:bg-white/5 text-white rounded-md transition-colors"
              >
                {t('common.previous')}
              </button>
            )}

            {activeTab !== 'commercial' && (
              <button
                type="button"
                onClick={() => {
                  const currentIndex = tabs.findIndex(tab => tab.id === activeTab);
                  if (currentIndex < tabs.length - 1) {
                    setActiveTab(tabs[currentIndex + 1].id);
                  }
                }}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md transition-colors"
              >
                {t('common.next')}
              </button>
            )}
          </div>

          <div className="flex space-x-3">
            {onCancel && (
              <button
                type="button"
                onClick={onCancel}
                className="px-4 py-2 bg-gray-600 hover:bg-white/5 text-white rounded-md transition-colors flex items-center gap-2"
              >
                <X className="w-4 h-4" />
                {t('common.cancel')}
              </button>
            )}
            <button
              type="submit"
              className={`px-6 py-2 rounded-md transition-colors flex items-center gap-2 ${isEditing
                ? 'bg-blue-600 hover:bg-blue-700 text-white'
                : 'bg-green-600 hover:bg-green-700 text-white'
                }`}
            >
              {isEditing ? (
                <>
                  <Save className="w-4 h-4" />
                  {t('customerForm.updateCustomer')}
                </>
              ) : (
                <>
                  <Plus className="w-4 h-4" />
                  {t('customerForm.createCustomer')}
                </>
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import {
  Users, Edit, Trash2, MapPin, Mail, Phone, Search, Eye, Plus,
  Target, Zap, Activity, Filter, ArrowRight
} from 'lucide-react';
import { Customer } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface CustomerListProps {
  customers: Customer[];
  onEdit: (customer: Customer) => void;
  onView: (customer: Customer) => void;
  onDelete: (id: number) => void;
  onAddCustomer: () => void;
}

export const CustomerList: React.FC<CustomerListProps> = ({
  customers,
  onEdit,
  onView,
  onDelete,
  onAddCustomer
}) => {
  const { t } = useLocale();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCounty, setSelectedCounty] = useState('');

  const filteredCustomers = customers.filter(customer => {
    const matchesSearch = customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      customer.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      customer.phone.includes(searchTerm);
    const matchesCounty = selectedCounty === '' || customer.florida_county === selectedCounty;
    return matchesSearch && matchesCounty;
  });

  const uniqueCounties = Array.from(new Set(customers.map(c => c.florida_county))).sort();

  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString('es-ES', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      });
    } catch (error) {
      return t('customerList.invalidDate');
    }
  };

  const handleDelete = (customer: Customer) => {
    if (window.confirm(t('customerList.confirmDelete', { name: customer.name }))) {
      onDelete(customer.id);
    }
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      {/* Header Hub */}
      <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-blue-600/10 rounded-2.5xl border border-blue-500/20 shadow-blue-900/10 shadow-lg group">
            <Users className="w-10 h-10 text-blue-500 group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none">{t('customerList.title')}</h1>
            <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2">
              <Zap className="w-3.5 h-3.5 text-blue-500 animate-pulse" /> {t('customerList.subtitle')}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative group">
            <Search className="w-4 h-4 absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-500 group-focus-within:text-blue-500 transition-colors" />
            <input
              type="text"
              placeholder={t('customerList.searchPlaceholder')}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-12 pr-6 py-4 bg-slate-950 text-white rounded-2xl border border-slate-800 focus:border-blue-500 focus:outline-none w-80 font-medium text-sm transition-all focus:shadow-[0_0_20px_rgba(59,130,246,0.1)]"
            />
          </div>

          <select
            value={selectedCounty}
            onChange={(e) => setSelectedCounty(e.target.value)}
            className="px-6 py-4 bg-slate-950 text-white rounded-2xl border border-slate-800 focus:border-blue-500 focus:outline-none font-medium text-sm appearance-none cursor-pointer"
          >
            <option value="" style={{ color: 'black' }}>{t('customerList.allCounties')}</option>
            {uniqueCounties.map(county => (
              <option key={county} value={county} style={{ color: 'black' }}>{county?.toUpperCase()}</option>
            ))}
          </select>

          <button
            onClick={onAddCustomer}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl flex items-center gap-3 transition-all font-bold shadow-lg shadow-blue-900/40 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            {t('customerList.registerCustomer')}
          </button>
        </div>
      </div>

      {filteredCustomers.length === 0 ? (
        <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-24 text-center border-dashed group">
          <div className="w-24 h-24 bg-slate-950 rounded-[2rem] border border-slate-800 flex items-center justify-center mx-auto mb-8 group-hover:scale-110 transition-transform duration-500">
            <Target className="w-10 h-10 text-slate-700 group-hover:text-blue-500 transition-colors" />
          </div>
          <h3 className="text-xl font-black text-white tracking-tight mb-4">{t('customerList.emptyTitle')}</h3>
          <p className="text-slate-500 font-medium text-xs max-w-sm mx-auto">
            {t('customerList.emptyMessage')}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
          {filteredCustomers.map((customer) => (
            <div
              key={customer.id}
              className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] hover:border-blue-500/30 transition-all group relative overflow-hidden"
            >
              <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 blur-[60px] pointer-events-none group-hover:bg-blue-500/10 transition-all"></div>

              <div className="relative z-10">
                <div className="flex justify-between items-start mb-8">
                  <div className="flex-1">
                    <h3 className="text-lg font-black text-white tracking-tight leading-none group-hover:text-blue-400 transition-colors">
                      {customer.name}
                    </h3>
                    <div className="flex items-center gap-3 mt-3">
                      <span className="text-[9px] font-black text-blue-500 bg-blue-500/10 px-2 py-0.5 rounded border border-blue-500/20 uppercase">
                        ID: {customer.id.toString().padStart(4, '0')}
                      </span>
                      <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">
                        {formatDate(customer.created_at)}
                      </span>
                    </div>
                  </div>

                  <div className="flex gap-2">
                    <button
                      onClick={() => onView(customer)}
                      className="p-3 bg-slate-950 border border-slate-800 rounded-xl text-emerald-500 hover:bg-emerald-500 hover:text-white transition-all shadow-sm"
                    >
                      <Eye className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => onEdit(customer)}
                      className="p-3 bg-slate-950 border border-slate-800 rounded-xl text-blue-500 hover:bg-blue-500 hover:text-white transition-all shadow-sm"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(customer)}
                      className="p-3 bg-slate-950 border border-slate-800 rounded-xl text-rose-500 hover:bg-rose-500 hover:text-white transition-all shadow-sm"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 pt-6 border-t border-slate-800/50">
                  {customer.email && (
                    <div className="flex items-center text-slate-400">
                      <div className="w-8 h-8 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center mr-3">
                        <Mail className="w-3.5 h-3.5" />
                      </div>
                      <span className="text-xs font-black uppercase tracking-tighter truncate">{customer.email}</span>
                    </div>
                  )}

                  {customer.phone && (
                    <div className="flex items-center text-slate-400">
                      <div className="w-8 h-8 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center mr-3">
                        <Phone className="w-3.5 h-3.5" />
                      </div>
                      <span className="text-xs font-black font-mono tracking-widest">{customer.phone}</span>
                    </div>
                  )}

                  <div className="flex items-center text-slate-400">
                    <div className="w-8 h-8 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center mr-3">
                      <MapPin className="w-3.5 h-3.5" />
                    </div>
                    <span className="text-[10px] font-black text-white bg-blue-600/20 px-3 py-1 rounded-[0.5rem] border border-blue-500/30 uppercase tracking-[0.1em]">
                      {customer.florida_county}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Global Intel Footer */}
      {customers.length > 0 && (
        <div className="bg-slate-950 border border-white/5 p-12 rounded-[3.5rem] shadow-3xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600/5 blur-[120px] -mr-48 -mt-48 group-hover:bg-blue-600/10 transition-all duration-700"></div>

          <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-12">
            <div className="flex items-center gap-6">
              <div className="p-5 bg-blue-600/10 rounded-[2rem] border border-blue-500/20">
                <Activity className="w-10 h-10 text-blue-500" />
              </div>
              <div>
                <h4 className="text-2xl font-black text-white uppercase tracking-tighter">{t('customerList.networkSync')}</h4>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">{t('customerList.currentStatus')}</p>
              </div>
            </div>

            <div className="grid grid-cols-2 lg:grid-cols-4 gap-8 w-full md:w-auto">
              <IntelMiniStat value={customers.length} label={t('customerList.totalRecords')} color="blue" />
              <IntelMiniStat value={customers.filter(c => c.email).length} label={t('customerList.validatedContacts')} color="emerald" />
              <IntelMiniStat value={customers.filter(c => c.phone).length} label={t('customerList.activeLines')} color="amber" />
              <IntelMiniStat value={uniqueCounties.length} label={t('customerList.geoZones')} color="rose" />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const IntelMiniStat = ({ value, label, color }: any) => {
  const colors: any = {
    blue: 'text-blue-500',
    emerald: 'text-emerald-500',
    amber: 'text-amber-500',
    rose: 'text-rose-500',
  };

  return (
    <div className="text-center md:text-left px-6 border-r border-slate-800 last:border-none">
      <div className={`text-4xl font-black ${colors[color]} font-mono mb-1 leading-none`}>{value}</div>
      <div className="text-[8px] font-black text-slate-500 uppercase tracking-[0.3em]">{label}</div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Shield,
  AlertTriangle,
  CheckCircle2,
  Lock,
  Calendar,
  FileText,
  Activity,
  ArrowRight,
  TrendingDown,
  TrendingUp,
  DollarSign,
  Briefcase,
  Bot
} from 'lucide-react';
import { getCompanyLogoUrl, hasCompanyLogo } from '../utils/logoUtils';
import { format } from 'date-fns';
import { es, enUS } from 'date-fns/locale';
import { useLocale } from '../i18n/useLocale';

import { AuditChainService as AuditService } from '../core/audit/AuditChainService';
import { TaxService } from '../services/TaxService';
import { DatabaseService } from '@/database/DatabaseService';
import { getMonthlyFinancialSummary, MonthlySummary } from '@/database/simple-db';
import { DraftProposalService } from '../services/DraftProposalService';

import { ComplianceHistory } from './reports/ComplianceHistory';
import { AIProposalPanel } from './ai/AIProposalPanel';

interface DashboardProps {
  stats: {
    customers: number;
    invoices: number;
    revenue: number;
    suppliers: number;
    bills: number;
    expenses: number;
  };
  onNavigate: (section: string) => void;
  invoices: any[]; // Passed from parent for deeper analysis
  bills: any[];    // Passed from parent
}

export const Dashboard: React.FC<DashboardProps> = ({ stats, onNavigate, invoices = [], bills = [] }) => {
  const { t, language } = useLocale();
  const [integrityHash, setIntegrityHash] = useState<string>(t('common.loading'));
  const [nextTaxDeadline, setNextTaxDeadline] = useState<string>('');
  const [sunbizDaysLeft, setSunbizDaysLeft] = useState<number>(0);
  const [unclaimedPropDays, setUnclaimedPropDays] = useState<number>(0);
  const [realTaxLiability, setRealTaxLiability] = useState<number>(0);
  const [pendingTaxCount, setPendingTaxCount] = useState<number>(0);
  const [monthlyStats, setMonthlyStats] = useState<MonthlySummary[]>([]);
  const [aiProposalCount, setAiProposalCount] = useState<number>(0);

  useEffect(() => {
    // 1. Get Real Audit Hash from Iron Core
    const fetchHash = async () => {
      try {
        const hash = await AuditService.getLastValidHash();
        setIntegrityHash(hash.substring(0, 16) + '...');
      } catch (e) {
        setIntegrityHash('SECURE_CORE_ACTIVE');
      }
    };
    fetchHash();

    // 2. Real-time Compliance Logic
    const today = new Date();
    const currentYear = today.getFullYear();
    const deadline = new Date(currentYear, today.getMonth(), 20);
    if (today > deadline) deadline.setMonth(deadline.getMonth() + 1);
    const dateLocale = language === 'es' ? es : enUS;
    const dateFormat = language === 'es' ? "d 'de' MMMM" : "MMMM do";
    setNextTaxDeadline(format(deadline, dateFormat, { locale: dateLocale }));

    const sunbizDeadline = new Date(currentYear, 4, 1);
    if (today > sunbizDeadline) sunbizDeadline.setFullYear(currentYear + 1);
    setSunbizDaysLeft(Math.ceil(Math.abs(sunbizDeadline.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)));

    const unclaimedDeadline = new Date(currentYear, 3, 30);
    if (today > unclaimedDeadline) unclaimedDeadline.setFullYear(currentYear + 1);
    setUnclaimedPropDays(Math.ceil(Math.abs(unclaimedDeadline.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)));

    // 5. Fetch Real Tax Liability
    const fetchTax = async () => {
      try {
        const summary = await TaxService.getTaxLiabilitySummary();
        setRealTaxLiability(summary.totalAccrued);
        setPendingTaxCount(summary.pendingCount);
      } catch (e) { console.error(e); }
    };
    fetchTax();

    // 6. Fetch Monthly Stats for Charts
    const summary = getMonthlyFinancialSummary();
    setMonthlyStats(summary);

    // 7. Fetch AI Proposal Count
    const fetchAIProposals = async () => {
      try {
        const proposals = await DraftProposalService.getPendingProposals();
        setAiProposalCount(proposals.length);
      } catch (e) {
        console.error('Error fetching AI proposals:', e);
      }
    };
    fetchAIProposals();

    // Refresh AI proposal count every 30 seconds
    const interval = setInterval(fetchAIProposals, 30000);
    return () => clearInterval(interval);
  }, [language]);

  const netIncome = (stats.revenue - stats.expenses) || 0;
  const isProfitable = netIncome >= 0;

  // Month names for chart based on locale
  const getMonthName = (idx: number) => {
    const d = new Date(2026, idx, 1);
    return d.toLocaleString(language === 'es' ? 'es-ES' : 'en-US', { month: 'short' }).toUpperCase();
  };

  const getFullMonthName = (idx: number) => {
    const d = new Date(2026, idx, 1);
    return d.toLocaleString(language === 'es' ? 'es-ES' : 'en-US', { month: 'long' });
  };

  return (
    <div className="space-y-10 animate-fade-in">
      {/* --- SECTION 1: COMPLIANCE MONITOR (RADAR) --- */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* ELITE OBLIGATION RADAR */}
        <div className="card-elite group">
          <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 blur-[100px] -mr-32 -mt-32 pointer-events-none group-hover:bg-emerald-500/10 transition-all duration-700"></div>

          <div className="relative z-10 flex flex-col h-full justify-between">
            <div>
              <div className="flex items-center justify-between mb-8">
                <h3 className="text-xs font-black text-emerald-500 uppercase tracking-[0.2em] flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                  {t('dashboard.complianceRadar')}
                </h3>
                <div className="flex items-center gap-2 px-3 py-1 bg-white/5 rounded-full border border-white/10">
                  <Shield className="w-3.5 h-3.5 text-emerald-400" />
                  <span className="text-[10px] font-bold text-slate-500">{t('dashboard.coreHash')}: {integrityHash}</span>
                </div>
              </div>

              <div className="space-y-10">
                {/* Sunbiz Compliance */}
                <div className="relative">
                  <div className="flex justify-between items-end mb-3">
                    <span className="text-white font-semibold text-base">{t('dashboard.sunbizReport')}</span>
                    <span className={`badge-elite ${sunbizDaysLeft < 30 ? 'bg-rose-500/20 text-rose-400' : 'bg-white/5 text-slate-500'}`}>
                      {sunbizDaysLeft} {t('dashboard.daysRemaining')}
                    </span>
                  </div>
                  <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-emerald-500 to-emerald-300 rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(16,185,129,0.5)]"
                      style={{ width: `${Math.max(10, Math.min(100, (365 - sunbizDaysLeft) / 365 * 100))}%` }}
                    ></div>
                  </div>
                </div>

                {/* Florida DR-15 Sales Tax */}
                <div className="relative bg-white/5 p-5 rounded-2xl border border-white/5 hover:border-emerald-500/30 transition-all duration-500">
                  <div className="flex items-center gap-5">
                    <div className="p-4 bg-emerald-500/10 rounded-2xl pulse-emerald">
                      <Calendar className="w-7 h-7 text-emerald-400" />
                    </div>
                    <div>
                      <span className="block text-[10px] uppercase text-slate-600 font-black tracking-widest mb-1">{t('dashboard.nextDeadline')}</span>
                      <span className="text-white font-bold text-xl tracking-tight">{nextTaxDeadline}</span>
                    </div>
                    <div className="ml-auto">
                      <div className="p-2 bg-white/5 rounded-xl border border-white/10">
                        <CheckCircle2 className="w-5 h-5 text-emerald-500/50" />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <button
              onClick={() => onNavigate('florida-dr15')}
              className="btn-elite-primary w-full mt-10 text-xs uppercase tracking-[0.2em] py-4"
            >
              {t('dashboard.startFiscalCycle')}
            </button>
          </div>
        </div>

        {/* COMPLIANCE HISTORY Overlay */}
        <div className="h-full bg-transparent overflow-hidden">
          <ComplianceHistory />
        </div>
      </div>

      {/* --- SECTION 2: FINANCIAL METRICS (ELITE CARDS) --- */}
      <div className="flex items-center justify-between px-2">
        <h2 className="text-sm font-black text-white p-2 flex items-center gap-3 uppercase tracking-widest">
          <Activity className="w-5 h-5 text-emerald-500" />
          {t('dashboard.vitalityMetrics')}
        </h2>
        <div className="h-px flex-1 bg-gradient-to-r from-emerald-500/20 to-transparent ml-4"></div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Ingressos */}
        <div className="card-elite hover:-translate-y-1 transition-all duration-500">
          <div className="flex justify-between items-start mb-6">
            <div className="p-3 bg-emerald-500/10 rounded-2xl">
              <TrendingUp className="w-6 h-6 text-emerald-400" />
            </div>
            <span className="text-[10px] font-black text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded-full border border-emerald-500/20 uppercase tracking-widest">
              {t('dashboard.sales')}
            </span>
          </div>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-2">{t('dashboard.totalRevenue')}</p>
          <h3 className="text-3xl font-black text-white tabular-nums">${stats.revenue.toLocaleString()}</h3>
        </div>

        {/* Net Profit */}
        <div className="card-elite hover:-translate-y-1 transition-all duration-500">
          <div className="flex justify-between items-start mb-6">
            <div className={`p-3 rounded-2xl ${isProfitable ? 'bg-emerald-500/10' : 'bg-rose-500/10'}`}>
              <DollarSign className={`w-6 h-6 ${isProfitable ? 'text-emerald-400' : 'text-rose-400'}`} />
            </div>
          </div>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-2">{t('dashboard.netProfit')}</p>
          <h3 className={`text-3xl font-black tabular-nums ${isProfitable ? 'text-white' : 'text-rose-400'}`}>
            ${netIncome.toLocaleString()}
          </h3>
        </div>

        {/* Tax Liability */}
        <div className="card-elite hover:-translate-y-1 border-emerald-500/20 transition-all duration-500">
          <div className="flex justify-between items-start mb-6">
            <div className="p-3 bg-amber-500/10 rounded-2xl">
              <Lock className="w-6 h-6 text-amber-500" />
            </div>
          </div>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-2">{t('dashboard.taxLiability')}</p>
          <h3 className="text-3xl font-black text-gray-200 tabular-nums">
            ${(realTaxLiability / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
          </h3>
          <div className="mt-4 flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse"></div>
            <span className="text-[10px] text-slate-500 font-bold uppercase">{pendingTaxCount} {t('dashboard.pendingDocs')}</span>
          </div>
        </div>

        {/* Active Customers */}
        <div className="card-elite hover:-translate-y-1 transition-all duration-500">
          <div className="flex justify-between items-start mb-6">
            <div className="p-3 bg-blue-500/10 rounded-2xl">
              <Briefcase className="w-6 h-6 text-blue-400" />
            </div>
            <div className="text-[10px] font-bold text-slate-500">v1.2 Beta</div>
          </div>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-2">{t('dashboard.customerPortfolio')}</p>
          <h3 className="text-3xl font-black text-white tabular-nums">{stats.customers}</h3>
        </div>
      </div>

      {/* --- SECTION 3: TREND ANALYSIS (CHARTS) --- */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 pb-10">

        {/* Bar Chart: Sales vs Purchases */}
        <div className="xl:col-span-2 card-elite min-h-[400px]">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-lg font-black text-white tracking-tight flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-emerald-400" />
                {t('dashboard.operationalTrend')} {new Date().getFullYear()}
              </h3>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">{t('dashboard.monthlySalesVsPurchases')}</p>
            </div>
            <div className="flex gap-4">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-emerald-500 rounded-sm shadow-[0_0_5px_rgba(16,185,129,0.5)]"></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase">{t('dashboard.sales')}</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-rose-500 rounded-sm shadow-[0_0_5px_rgba(244,63,94,0.5)]"></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase">{t('dashboard.purchases')}</span>
              </div>
            </div>
          </div>

          <div className="h-64 flex items-end justify-between gap-1 mt-12 px-4">
            {monthlyStats.map((item, idx) => {
              const maxVal = Math.max(...monthlyStats.map(m => Math.max(m.revenue, m.expenses))) || 1000;
              const revHeight = (item.revenue / maxVal) * 100;
              const expHeight = (item.expenses / maxVal) * 100;
              const monthName = getMonthName(idx);
              const fullMonthName = getFullMonthName(idx);

              return (
                <div key={item.month} className="flex-1 flex flex-col items-center group/cell h-full justify-end">
                  <div className="relative w-full h-full flex items-end justify-center gap-1.5 px-1 pb-4 border-b border-white/5 group-hover/cell:bg-white/[0.02] rounded-t-lg transition-all">
                    {/* Tooltip on hover */}
                    <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-slate-900 border border-white/10 p-3 rounded-2xl opacity-0 group-hover/cell:opacity-100 transition-all duration-300 z-20 pointer-events-none shadow-2xl min-w-[140px] scale-90 group-hover/cell:scale-100 backdrop-blur-md">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 border-b border-white/5 pb-1">{fullMonthName}</p>
                      <p className="text-xs font-bold text-emerald-400 flex justify-between gap-4">
                        <span className="uppercase tracking-widest text-[9px] text-slate-500">{t('dashboard.sales')}:</span>
                        <span className="tabular-nums">${item.revenue.toLocaleString()}</span>
                      </p>
                      <p className="text-xs font-bold text-rose-400 flex justify-between gap-4">
                        <span className="uppercase tracking-widest text-[9px] text-slate-500">{t('dashboard.purchases')}:</span>
                        <span className="tabular-nums">${item.expenses.toLocaleString()}</span>
                      </p>
                    </div>

                    <div
                      className="w-full max-w-[12px] bg-emerald-500 rounded-t-sm transition-all duration-1000 group-hover/cell:opacity-100 opacity-60 shadow-[0_0_15px_rgba(16,185,129,0.2)]"
                      style={{ height: `${Math.max(2, revHeight)}%` }}
                    ></div>
                    <div
                      className="w-full max-w-[12px] bg-rose-500 rounded-t-sm transition-all duration-1000 group-hover/cell:opacity-100 opacity-60 shadow-[0_0_15px_rgba(244,63,94,0.2)]"
                      style={{ height: `${Math.max(2, expHeight)}%` }}
                    ></div>
                  </div>
                  <span className="text-[9px] font-black text-slate-600 mt-4 group-hover/cell:text-white transition-colors tracking-widest">
                    {monthName}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Quick Actions (Sidebar) */}
        <div className="card-elite flex flex-col">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-10 flex items-center gap-2">
            <div className="w-1.5 h-1.5 bg-slate-700 rounded-full"></div>
            {t('dashboard.quickAccess')}
          </h3>
          <div className="space-y-4 flex-grow">
            {[
              { id: 'invoices', label: t('dashboard.issueInvoice'), icon: FileText, color: 'emerald' },
              { id: 'journal-entries', label: t('dashboard.manualEntry'), icon: Activity, color: 'blue' },
              { id: 'ledger-hub', label: t('dashboard.accountingBooks'), icon: Lock, color: 'amber' },
              { id: 'tax-config', label: t('dashboard.taxSettings'), icon: Shield, color: 'rose' }
            ].map(action => (
              <button
                key={action.id}
                onClick={() => onNavigate(action.id)}
                className="w-full flex items-center justify-between p-5 bg-white/5 border border-white/5 rounded-xl hover:bg-white/10 hover:border-white/10 transition-all duration-300 group active:scale-[0.98]"
              >
                <div className="flex items-center gap-5">
                  <div className={`p-3 rounded-2xl transition-transform duration-500 group-hover:scale-110 group-hover:bg-white/5`}>
                    <action.icon className={`w-5 h-5 text-gray-400 group-hover:text-white transition-colors`} />
                  </div>
                  <span className="text-sm font-bold text-gray-200 tracking-tight group-hover:text-white transition-colors">{action.label}</span>
                </div>
                <ArrowRight className="w-4 h-4 text-slate-700 group-hover:text-white group-hover:translate-x-1 transition-all" />
              </button>
            ))}
          </div>

          <div className="mt-10 p-8 bg-blue-600/5 rounded-[2.5rem] border border-blue-600/10 text-center hover:bg-blue-600/10 transition-all cursor-pointer group/bot relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 blur-[50px] -mr-16 -mt-16 pointer-events-none"></div>
            <Bot className="w-10 h-10 text-blue-500 mx-auto mb-5 group-hover/bot:scale-110 transition-transform duration-500" />
            <p className="text-[10px] font-black text-blue-400 mb-2 uppercase tracking-[0.2em]">{t('dashboard.intelligentAssistant')}</p>
            {aiProposalCount > 0 ? (
              <div className="flex items-center justify-center gap-3">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                <p className="text-base font-black text-emerald-400 tracking-tighter">
                  {aiProposalCount} {aiProposalCount === 1 ? t('dashboard.proposal') : t('dashboard.proposals')}
                </p>
              </div>
            ) : (
              <p className="text-[10px] text-slate-600 leading-relaxed uppercase font-black tracking-widest">
                {t('dashboard.monitoring247')}
              </p>
            )}
          </div>
        </div>

      </div>

      {/* --- SECTION 4: PROACTIVE AI (PROPOSALS) --- */}
      {aiProposalCount > 0 && (
        <div className="mt-10 animate-in slide-in-from-bottom-10 duration-1000">
          <div className="flex items-center justify-between px-2 mb-8">
            <h2 className="text-sm font-black text-white p-2 flex items-center gap-4 uppercase tracking-widest">
              <Bot className="w-6 h-6 text-blue-500" />
              {t('dashboard.aiProposals')}
            </h2>
            <div className="h-px flex-1 bg-gradient-to-r from-blue-500/20 to-transparent ml-6"></div>
          </div>
          <AIProposalPanel />
        </div>
      )}
    </div>
  );
};

/**
 * PANEL DE DASHBOARD FINANCIERO - SISTEMA DUAL
 * 
 * Panel de resumen financiero en tiempo real que mantiene:
 * - Todos los datos financieros importantes
 * - Actualizaci├│n autom├ítica cada 2 minutos
 * - Resumen ejecutivo del estado del sistema
 * - Visibilidad permanente en dashboard
 */

import React, { useState, useEffect } from 'react';
import {
  BarChart3,
  RefreshCw,
  MessageSquare,
  AlertTriangle,
  DollarSign,
  FileText,
  Package,
  CreditCard,
  PieChart,
  Target,
  TrendingUp,
  Shield,
  ArrowUp,
  ArrowDown
} from 'lucide-react';
import { iaService } from '../services/IAService';
import { logger } from '../core/logging/SystemLogger';
import { useLocale } from '../i18n/useLocale';

interface DashboardData {
  totalBalance: number;
  balanceTrend: 'up' | 'down' | 'stable';
  monthlyInvoicing: number;
  invoicingTrend: 'up' | 'down' | 'stable';
  criticalStockCount: number;
  pendingCollections: number;
  overdueInvoices: number;
  alerts: Array<{
    id: string;
    type: 'warning' | 'error' | 'info';
    message: string;
    priority: 'high' | 'medium' | 'low';
  }>;
  accountingStructure: any[];
  recommendedActions: string[];
  periodAnalysis: string;
}

interface FinancialDashboardPanelProps {
  onOpenAssistant?: () => void;
}

export const FinancialDashboardPanel: React.FC<FinancialDashboardPanelProps> = ({ onOpenAssistant }) => {
  const { t } = useLocale();
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Cargar datos del dashboard
  useEffect(() => {
    loadDashboardData();

    // Actualizar cada 2 minutos
    const interval = setInterval(() => {
      loadDashboardData();
      setLastUpdate(new Date());
    }, 2 * 60 * 1000);

    return () => clearInterval(interval);
  }, []);

  const loadDashboardData = async () => {
    setIsLoading(true);
    setError(null);

    try {
      logger.info('FinancialDashboard', 'load_data', 'Cargando datos del dashboard financiero');

      // Obtener an├ílisis completo del sistema restaurado
      const analysis = await iaService.analyzeFinancialHealth();

      // Convertir a formato de dashboard
      const dashboardData: DashboardData = {
        totalBalance: calculateTotalBalance(analysis.data),
        balanceTrend: 'stable',
        monthlyInvoicing: calculateMonthlyInvoicing(analysis.data),
        invoicingTrend: 'up',
        criticalStockCount: calculateCriticalStock(analysis.data),
        pendingCollections: calculatePendingCollections(analysis.data),
        overdueInvoices: calculateOverdueInvoices(analysis.data),
        alerts: convertAlertsToFormat(analysis.alerts || []),
        accountingStructure: analysis.data.financial || [],
        recommendedActions: analysis.actions || [],
        periodAnalysis: analysis.content
      };

      setDashboardData(dashboardData);

      logger.info('FinancialDashboard', 'load_success', 'Dashboard financiero cargado exitosamente');

    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : 'Error desconocido';
      setError(errorMsg);
      logger.error('FinancialDashboard', 'load_failed', 'Error cargando dashboard', { error: errorMsg });
    } finally {
      setIsLoading(false);
    }
  };

  // Funciones auxiliares para calcular m├⌐tricas
  const calculateTotalBalance = (data: any): number => {
    if (!data.financial) return 0;
    return data.financial.reduce((sum: number, item: any) => sum + (item.cantidad_cuentas || 0), 0) * 1000;
  };

  const calculateMonthlyInvoicing = (data: any): number => {
    if (!data.invoices) return 0;
    const currentMonth = data.invoices.find((inv: any) => inv.status === 'paid');
    return currentMonth?.monto_total || 0;
  };

  const calculateCriticalStock = (_data: any): number => {
    try {
      const { dbExec } = require('../database/simple-db');
      const res = dbExec(
        `SELECT COUNT(*) as cnt FROM products
         WHERE active = 1
           AND (stock_quantity <= reorder_point OR stock_quantity <= min_stock_level)`
      );
      return res?.[0]?.values?.[0]?.[0] ?? 0;
    } catch {
      return 0;
    }
  };

  const calculatePendingCollections = (data: any): number => {
    if (!data.invoices) return 0;
    const pending = data.invoices.find((inv: any) => inv.status === 'sent');
    return pending?.monto_total || 0;
  };

  const calculateOverdueInvoices = (data: any): number => {
    if (!data.invoices) return 0;
    const overdue = data.invoices.find((inv: any) => inv.status === 'overdue');
    return overdue?.cantidad_facturas || 0;
  };

  const convertAlertsToFormat = (alerts: string[]): DashboardData['alerts'] => {
    return alerts.map((alert, index) => ({
      id: `alert-${index}`,
      type: alert.includes('CR├ìTICO') ? 'error' : alert.includes('ALERTA') ? 'warning' : 'info',
      message: alert,
      priority: alert.includes('CR├ìTICO') ? 'high' : alert.includes('ALERTA') ? 'medium' : 'low'
    }));
  };

  const formatTime = (date: Date): string => {
    return date.toLocaleTimeString(undefined, {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const DashboardCard: React.FC<{
    title: string;
    icon: React.ElementType;
    value: string | number;
    trend?: 'up' | 'down' | 'stable';
    subtitle?: string;
    color: 'green' | 'blue' | 'orange' | 'red';
  }> = ({ title, icon: Icon, value, trend, subtitle, color }) => {
    const colorClasses = {
      green: 'border-green-500 bg-green-900/10',
      blue: 'border-blue-500 bg-blue-900/10',
      orange: 'border-orange-500 bg-orange-900/10',
      red: 'border-red-500 bg-red-900/10'
    };

    const iconColors = {
      green: 'text-green-400',
      blue: 'text-blue-400',
      orange: 'text-orange-400',
      red: 'text-red-400'
    };

    return (
      <div className={`dashboard-card ${colorClasses[color]} border-l-4 p-4 rounded-r-lg`}>
        <div className="flex items-center justify-between mb-2">
          <Icon className={`w-6 h-6 ${iconColors[color]}`} />
          {trend && (
            <div className="flex items-center">
              {trend === 'up' && <ArrowUp className="w-4 h-4 text-green-400" />}
              {trend === 'down' && <ArrowDown className="w-4 h-4 text-red-400" />}
            </div>
          )}
        </div>
        <h4 className="text-sm font-medium text-slate-400 mb-1">{title}</h4>
        <p className="text-2xl font-black tracking-tight text-slate-100">{value}</p>
        {subtitle && <p className="text-xs text-slate-500 mt-1">{subtitle}</p>}
      </div>
    );
  };

  const DashboardSection: React.FC<{
    title: string;
    icon: React.ElementType;
    type: 'alert' | 'data' | 'action' | 'analysis';
    children: React.ReactNode;
  }> = ({ title, icon: Icon, type, children }) => {
    const typeColors = {
      alert: 'border-red-500 bg-red-900/10',
      data: 'border-blue-500 bg-blue-900/10',
      action: 'border-green-500 bg-green-900/10',
      analysis: 'border-purple-500 bg-purple-900/10'
    };

    const iconColors = {
      alert: 'text-red-400',
      data: 'text-blue-400',
      action: 'text-green-400',
      analysis: 'text-purple-400'
    };

    return (
      <div className={`${typeColors[type]} border-l-4 p-4 rounded-r-lg`}>
        <div className="flex items-center space-x-2 mb-3">
          <Icon className={`w-5 h-5 ${iconColors[type]}`} />
          <h4 className="font-medium text-slate-200">{title}</h4>
        </div>
        {children}
      </div>
    );
  };

  return (
    <div className="financial-dashboard-panel bg-slate-900 text-slate-100 rounded-lg border border-slate-700 p-6">
      {/* CABECERA CON ESTADO */}
      <div className="dashboard-header flex justify-between items-center mb-6 pb-4 border-b border-slate-700">
        <div className="header-left flex items-center space-x-4">
          <BarChart3 className="w-8 h-8 text-blue-400" />
          <div>
            <h3 className="text-xl font-semibold text-slate-100">{t('financialDashboard.title')}</h3>
            <div className="flex items-center space-x-2 mt-1">
              <RefreshCw className={`w-3 h-3 text-slate-400 ${isLoading ? 'animate-spin' : ''}`} />
              <span className="text-xs text-slate-400">
                {t('reportsdashboard.compliance.statusgenerated')}: {formatTime(lastUpdate)}
              </span>
            </div>
          </div>
        </div>
        <button
          onClick={onOpenAssistant}
          className="flex items-center space-x-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors"
        >
          <MessageSquare className="w-4 h-4" />
          <span>{t('financialDashboard.askAssistant')}</span>
        </button>
      </div>

      {/* ERROR */}
      {error && (
        <div className="mb-6 p-4 bg-red-900/20 border border-red-700 rounded-lg">
          <p className="text-red-300">{error}</p>
        </div>
      )}

      {/* LOADING */}
      {isLoading && (
        <div className="flex items-center justify-center p-8">
          <RefreshCw className="w-6 h-6 animate-spin text-blue-400 mr-2" />
          <span className="text-slate-300">{t('common.loading')}</span>
        </div>
      )}

      {/* CONTENIDO DEL DASHBOARD */}
      {dashboardData && !isLoading && (
        <div className="space-y-6">
          {/* RESUMEN R├üPIDO EN GRID */}
          <div className="dashboard-grid grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <DashboardCard
              title={t('financialDashboard.totalBalances')}
              icon={DollarSign}
              value={`$${dashboardData.totalBalance.toLocaleString()}`}
              trend={dashboardData.balanceTrend}
              color="green"
            />
            <DashboardCard
              title={t('financialDashboard.monthlyInvoicing')}
              icon={FileText}
              value={`$${dashboardData.monthlyInvoicing.toLocaleString()}`}
              trend={dashboardData.invoicingTrend}
              color="blue"
            />
            <DashboardCard
              title={t('financialDashboard.criticalStock')}
              icon={Package}
              value={dashboardData.criticalStockCount}
              subtitle={t('financialDashboard.products')}
              color="orange"
            />
            <DashboardCard
              title={t('financialDashboard.accountsReceivable')}
              icon={CreditCard}
              value={`$${dashboardData.pendingCollections.toLocaleString()}`}
              subtitle={`${dashboardData.overdueInvoices} ${t('financialDashboard.overdue')}`}
              color="red"
            />
          </div>

          {/* SECCIONES DETALLADAS */}
          <div className="dashboard-sections space-y-4">
            {/* ALERTAS */}
            <DashboardSection title={`ΓÜá∩╕Å ${t('financialDashboard.activeAlerts')}`} icon={AlertTriangle} type="alert">
              <div className="space-y-2">
                {dashboardData.alerts.map(alert => (
                  <div key={alert.id} className="flex items-center space-x-2 text-sm">
                    <div className={`w-2 h-2 rounded-full ${alert.priority === 'high' ? 'bg-red-400' :
                      alert.priority === 'medium' ? 'bg-orange-400' : 'bg-blue-400'
                      }`} />
                    <span className="text-red-200">{alert.message}</span>
                  </div>
                ))}
              </div>
            </DashboardSection>

            {/* DATOS FINANCIEROS */}
            <DashboardSection title={`≡ƒôè ${t('financialDashboard.accountingStructure')}`} icon={PieChart} type="data">
              <div className="grid grid-cols-2 gap-2">
                {dashboardData.accountingStructure.map((item: any, index: number) => (
                  <div key={index} className="bg-slate-800 p-3 rounded">
                    <span className="text-slate-300 text-sm">{item.account_type}:</span>
                    <span className="text-blue-300 ml-2 font-medium">{item.cantidad_cuentas}</span>
                  </div>
                ))}
              </div>
            </DashboardSection>

            {/* ACCIONES RECOMENDADAS */}
            <DashboardSection title={`≡ƒæë ${t('financialDashboard.priorityActions')}`} icon={Target} type="action">
              <div className="space-y-1">
                {dashboardData.recommendedActions.map((action, index) => (
                  <p key={index} className="text-sm text-green-200">{action}</p>
                ))}
              </div>
            </DashboardSection>

            {/* AN├üLISIS DEL PER├ìODO */}
            <DashboardSection title={`≡ƒöì ${t('financialDashboard.periodAnalysis')}`} icon={TrendingUp} type="analysis">
              <div className="text-sm text-purple-200 whitespace-pre-line">
                {dashboardData.periodAnalysis}
              </div>
            </DashboardSection>
          </div>

          {/* DISCLAIMER */}
          <div className="text-xs text-slate-500 text-center bg-slate-800 p-3 rounded flex items-center justify-center space-x-2">
            <Shield className="w-3 h-3" />
            <span>{t('financialDashboard.readOnlyDisclaimer')}</span>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Search, Calendar, FileText, BarChart3, Download, ArrowRight, ArrowDownCircle, ChevronRight, TrendingUp, TrendingDown, History, ShieldCheck, Box, Loader2 } from 'lucide-react';
import { ChartOfAccount, getAccountLedger } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface LedgerEntry {
  id: number;
  date: string;
  reference: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
  source_type: 'invoice' | 'bill' | 'journal_entry' | 'payment';
  source_id: number;
}

interface AccountLedger {
  account: ChartOfAccount;
  opening_balance: number;
  entries: LedgerEntry[];
  closing_balance: number;
  total_debits: number;
  total_credits: number;
}

interface GeneralLedgerProps {
  chartOfAccounts: ChartOfAccount[];
}

export const GeneralLedger: React.FC<GeneralLedgerProps> = ({ chartOfAccounts }) => {
  const { t } = useLocale();
  const [selectedAccount, setSelectedAccount] = useState<ChartOfAccount | null>(null);
  const [accountLedger, setAccountLedger] = useState<AccountLedger | null>(null);
  const [dateFrom, setDateFrom] = useState(() => {
    const date = new Date();
    date.setMonth(date.getMonth() - 1);
    return date.toISOString().split('T')[0];
  });
  const [dateTo, setDateTo] = useState(new Date().toISOString().split('T')[0]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'asset' | 'liability' | 'equity' | 'revenue' | 'expense'>('all');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (selectedAccount) {
      loadAccountLedger();
    }
  }, [selectedAccount, dateFrom, dateTo]);

  const loadAccountLedger = async () => {
    if (!selectedAccount) return;

    setIsLoading(true);
    try {
      const result = getAccountLedger(selectedAccount.account_code, dateFrom, dateTo);

      if (!result || !result.account) {
        setAccountLedger(null);
        return;
      }

      setAccountLedger({
        account: selectedAccount,
        opening_balance: result.startingBalance,
        entries: result.transactions.map((tx: any, idx: number) => ({
          id: tx.journal_id || idx,
          date: tx.entry_date,
          reference: tx.reference,
          description: tx.description,
          debit: tx.debit_amount,
          credit: tx.credit_amount,
          balance: tx.running_balance,
          source_type: 'journal_entry',
          source_id: tx.journal_id
        })),
        closing_balance: result.endingBalance,
        total_debits: result.totalDebit,
        total_credits: result.totalCredit
      });
    } catch (error) {
      console.error('Core Ledger Load Error:', error);
    } finally {
      setTimeout(() => setIsLoading(false), 400);
    }
  };

  const filteredAccounts = chartOfAccounts.filter(account => {
    const matchesSearch = account.account_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      account.account_code.toLowerCase().includes(searchTerm.toLowerCase());
    if (filterType === 'all') return matchesSearch;
    return matchesSearch && account.account_type === filterType;
  });

  const getAccountTypeBadge = (type: string) => {
    const styles: Record<string, string> = {
      asset: 'bg-blue-500/10 text-blue-500 border-blue-500/20',
      liability: 'bg-red-500/10 text-red-500 border-red-500/20',
      equity: 'bg-purple-500/10 text-purple-500 border-purple-500/20',
      revenue: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
      expense: 'bg-orange-500/10 text-orange-500 border-orange-500/20'
    };
    const labels: Record<string, string> = {
      asset: t('common.asset'),
      liability: t('common.liability'),
      equity: t('common.equity'),
      revenue: t('common.revenue'),
      expense: t('common.expense')
    };
    return (
      <span className={`px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wide border ${styles[type] || 'bg-slate-500/10 text-slate-500 border-slate-500/20'}`}>
        {labels[type] || type}
      </span>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Search and Filters Strip */}
      <div className="bg-slate-900/40 border border-slate-800 rounded-3xl p-6 backdrop-blur-md shadow-xl">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="space-y-2">
            <label className="text-xs font-medium text-slate-500 ml-1">{t('ledger.searchAccount')}</label>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600" />
              <input
                type="text"
                placeholder={t('ledger.searchPlaceholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-11 pr-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-white font-medium text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all placeholder:text-slate-700"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-medium text-slate-500 ml-1">{t('ledger.structure')}</label>
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value as any)}
              className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-white font-bold text-xs focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all"
            >
              <option value="all">{t('ledger.all')}</option>
              <option value="asset">{t('common.asset')}</option>
              <option value="liability">{t('common.liability')}</option>
              <option value="equity">{t('common.equity')}</option>
              <option value="revenue">{t('common.revenue')}</option>
              <option value="expense">{t('common.expense')}</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-medium text-slate-500 ml-1">{t('ledger.from')}</label>
            <input type="date" value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-white font-mono text-xs focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none" />
          </div>
          <div className="space-y-2">
            <label className="text-xs font-medium text-slate-500 ml-1">{t('ledger.to')}</label>
            <input type="date" value={dateTo} onChange={(e) => setDateTo(e.target.value)} className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-white font-mono text-xs focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Navigation Registry (Sidebar of GL) */}
        <div className="lg:col-span-1 border border-slate-800 rounded-[2rem] bg-slate-950/30 overflow-hidden flex flex-col h-[700px]">
          <div className="px-6 py-5 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between">
            <span className="text-xs font-bold text-white uppercase tracking-wider">{t('ledger.masterPlan')}</span>
            <Box className="w-4 h-4 text-slate-600" />
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar">
            {filteredAccounts.map((account) => (
              <button
                key={account.id}
                onClick={() => setSelectedAccount(account)}
                className={`w-full text-left px-6 py-5 border-b border-slate-800/50 hover:bg-slate-800/20 transition-all group flex items-start justify-between ${selectedAccount?.id === account.id ? 'bg-blue-600/10 border-l-4 border-l-blue-600' : ''
                  }`}
              >
                <div className="space-y-1">
                  <p className={`text-xs font-bold tracking-tight transition-colors ${selectedAccount?.id === account.id ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>
                    {account.number ? `${account.number} (${account.account_code})` : account.account_code}
                  </p>
                  <p className={`text-sm font-medium truncate max-w-[150px] ${selectedAccount?.id === account.id ? 'text-blue-400' : 'text-slate-500'}`}>
                    {account.account_name}
                  </p>
                  {getAccountTypeBadge(account.account_type)}
                </div>
                {selectedAccount?.id === account.id && <ChevronRight className="w-4 h-4 text-blue-500 mt-2" />}
              </button>
            ))}
          </div>
        </div>

        {/* Dynamic Ledger Data View */}
        <div className="lg:col-span-3">
          {selectedAccount ? (
            <div className="bg-slate-900/40 border border-slate-800 rounded-[2rem] overflow-hidden shadow-2xl h-full flex flex-col">
              <header className="px-10 py-8 bg-slate-950/40 border-b border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div className="flex items-center gap-5">
                  <div className="p-4 bg-blue-600/10 rounded-2xl border border-blue-500/20">
                    <BarChart3 className="w-8 h-8 text-blue-500" />
                  </div>
                  <div>
                    <div>
