/**
 * HelpCenter.tsx - Centro de Ayuda del Sistema
 * 
 * Muestra las gu├¡as de uso y operaciones comunes del sistema.
 * Basado en el contenido de knowledge/SystemKnowledge.ts
 */

import React, { useState } from 'react';
import {
    BookOpen,
    Lightbulb,
    Search,
    ChevronDown,
    ChevronUp,
    FileText,
    HelpCircle,
    ArrowLeft
} from 'lucide-react';
import { SYSTEM_GUIDES, QUICK_OPERATIONS, FAQ } from '../knowledge/SystemKnowledge';
import { useLocale } from '../i18n/useLocale';

interface HelpCenterProps {
    // Props opcionales si se necesitan
}

export const HelpCenter: React.FC<HelpCenterProps> = () => {
    const { t } = useLocale();
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
    const [expandedGuide, setExpandedGuide] = useState<string | null>(null);

    // NEW: Active Guide View mode (for immediate visibility)
    const [viewingGuide, setViewingGuide] = useState<string | null>(null);

    // Filtrar gu├¡as
    const filteredGuides = Object.entries(SYSTEM_GUIDES).filter(([_, guide]) => {
        const matchesSearch = guide.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            guide.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            guide.steps.some(step => step.toLowerCase().includes(searchTerm.toLowerCase()));

        const matchesCategory = selectedCategory ? guide.category === selectedCategory : true;

        return matchesSearch && matchesCategory;
    });

    const formatGuideContent = (guide: typeof SYSTEM_GUIDES[string]) => {
        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
                    <h2 className="text-2xl font-black tracking-tight text-white mb-2">{guide.title}</h2>
                    <p className="text-slate-400 mb-6 text-lg">{guide.description}</p>

                    <div className="bg-slate-950/50 p-6 rounded-xl border border-slate-800">
                        <h4 className="text-sm font-semibold text-blue-400 mb-4 uppercase tracking-wider flex items-center gap-2">
                            <FileText className="w-4 h-4" />
                            {t('helpCenter.stepsToFollow')}
                        </h4>
                        <ol className="relative space-y-6 pl-2">
                            {guide.steps.map((step, idx) => (
                                <li key={idx} className="pl-6 relative border-l-2 border-slate-800 last:border-0 pb-1">
                                    <span className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-slate-800 border-2 border-blue-500/50 flex items-center justify-center">
                                        <span className="w-1.5 h-1.5 rounded-full bg-blue-500"></span>
                                    </span>
                                    <p className="text-slate-200 text-base leading-relaxed">{step}</p>
                                </li>
                            ))}
                        </ol>
                    </div>
                </div>

                {guide.tips && guide.tips.length > 0 && (
                    <div className="bg-emerald-900/10 p-6 rounded-2xl border border-emerald-500/20 shadow-lg">
                        <h4 className="text-lg font-semibold text-emerald-400 mb-4 flex items-center gap-2">
                            <Lightbulb className="w-5 h-5" />
                            {t('helpCenter.proTips')}
                        </h4>
                        <ul className="space-y-3">
                            {guide.tips.map((tip, idx) => (
                                <li key={idx} className="flex items-start gap-3 bg-emerald-900/20 p-3 rounded-lg border border-emerald-500/10">
                                    <span className="mt-1.5 w-1.5 h-1.5 bg-emerald-400 rounded-full flex-shrink-0 shadow-[0_0_8px_rgba(52,211,153,0.8)]"></span>
                                    <span className="text-slate-200 text-sm leading-relaxed">{tip}</span>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                <div className="flex items-center gap-2 text-xs text-slate-500 mt-4 justify-end">
                    <span className="font-semibold">{t('helpCenter.systemPath')}</span>
                    <code className="bg-slate-800 px-3 py-1 rounded-md text-blue-300 font-mono border border-slate-700">{guide.relatedMenu}</code>
                </div>
            </div>
        );
    };

    // Main Render Logic
    const activeGuideData = viewingGuide ? SYSTEM_GUIDES[viewingGuide] : null;

    if (activeGuideData && viewingGuide) {
        return (
            <div className="h-full flex flex-col bg-slate-950 overflow-hidden">
                <div className="p-6 border-b border-slate-800 flex items-center gap-4 bg-slate-900/30">
                    <button
                        onClick={() => setViewingGuide(null)}
                        className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors group"
                    >
                        <ArrowLeft className="w-6 h-6 group-hover:-translate-x-1 transition-transform" />
                    </button>
                    <div>
                        <h1 className="text-xl font-black tracking-tight text-white">{t('helpCenter.guideTitle')}</h1>
                        <p className="text-slate-400 text-xs">{t('helpCenter.backToHelp')}</p>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                    <div className="max-w-4xl mx-auto">
                        {formatGuideContent(activeGuideData)}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col bg-slate-950 overflow-hidden">
            {/* Header */}
            <div className="p-6 border-b border-slate-800">
                <div className="flex items-center gap-4 mb-6">
                    <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-900/20">
                        <BookOpen className="w-8 h-8 text-white" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black tracking-tight text-white tracking-tight">{t('helpCenter.title')}</h1>
                        <p className="text-slate-400 text-sm mt-1">{t('helpCenter.subtitle')}</p>
                    </div>
                </div>

                {/* Search & Filter */}
                <div className="flex flex-col md:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                        <input
                            type="text"
                            placeholder={t('helpCenter.searchPlaceholder')}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 text-white pl-10 pr-4 py-3 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-600 transition-all placeholder:text-slate-600"
                        />
                    </div>
                    <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 custom-scrollbar">
                        <button
                            onClick={() => {
                                setSelectedCategory(null);
                                setSearchTerm('');
                            }}
                            className={`px-4 py-2 rounded-lg text-sm font-medium capitalize transition-all whitespace-nowrap ${!selectedCategory
                                ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20'
                                : 'bg-slate-900 text-slate-400 hover:text-white hover:bg-slate-800 border border-slate-800'
                                }`}
                        >
                            {t('helpCenter.categories.home')}
                        </button>
                        {['ventas', 'compras', 'inventario', 'contabilidad', 'impuestos', 'sistema'].map(cat => (
                            <button
                                key={cat}
                                onClick={() => setSelectedCategory(selectedCategory === cat ? null : cat)}
                                className={`px-4 py-2 rounded-lg text-sm font-medium capitalize transition-all whitespace-nowrap ${selectedCategory === cat
                                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20'
                                    : 'bg-slate-900 text-slate-400 hover:text-white hover:bg-slate-800 border border-slate-800'
                                    }`}
                            >
                                {t(`helpCenter.categories.${cat === 'ventas' ? 'sales' : cat === 'compras' ? 'purchases' : cat === 'inventario' ? 'inventory' : cat === 'contabilidad' ? 'accounting' : cat === 'impuestos' ? 'taxes' : 'system'}`)}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">

                {/* Quick Operations (Only show if no search/filter active) */}
                {!searchTerm && !selectedCategory && (
                    <div className="mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                        <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                            <Lightbulb className="w-5 h-5 text-yellow-400" />
                            {t('helpCenter.quickAccess')}
                        </h2>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {QUICK_OPERATIONS.map((op, i) => (
                                <button
                                    key={i}
                                    onClick={() => {
                                        const guideEntry = Object.entries(SYSTEM_GUIDES).find(([key]) => key === op.guide);
                                        if (guideEntry) {
                                            setViewingGuide(op.guide); // OPEN IMMEDIATELY
                                        }
                                    }}
                                    className="bg-slate-900/50 hover:bg-slate-800 border border-slate-800 hover:border-blue-500/30 p-4 rounded-xl text-center group transition-all"
                                >
                                    <div className="w-10 h-10 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-3 group-hover:scale-110 transition-transform">
                                        <BookOpen className="w-5 h-5 text-blue-400" />
                                    </div>
                                    <span className="text-sm font-medium text-slate-300 group-hover:text-white">
                                        {(op as any).labelKey ? t((op as any).labelKey) : op.label}
                                    </span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Guides List */}
                <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                    <FileText className="w-5 h-5 text-blue-400" />
                    {t('helpCenter.availableGuides')}
                </h2>

                <div className="space-y-4">
                    {filteredGuides.length > 0 ? (
                        filteredGuides.map(([key, guide]) => (
                            <div
                                key={key}
                                className={`bg-slate-900 border rounded-xl overflow-hidden transition-all duration-300 border-slate-800 hover:border-slate-700`}
                            >
                                <button
                                    onClick={() => setViewingGuide(key)} // OPEN IMMEDIATELY
                                    className="w-full flex items-center justify-between p-4 text-left group"
                                >
                                    <div className="flex items-start gap-4">
                                        <div className="p-2 rounded-lg mt-0.5 bg-slate-800 text-slate-500 group-hover:bg-blue-500/10 group-hover:text-blue-400 transition-colors">
                                            <BookOpen className="w-5 h-5" />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-base text-slate-200 group-hover:text-white transition-colors">
                                                {guide.title}
                                            </h3>
                                            <p className="text-slate-500 text-sm mt-0.5">{guide.description}</p>
                                        </div>
                                    </div>
                                    <div className="text-slate-500 group-hover:text-blue-400 group-hover:translate-x-1 transition-all">
                                        <ChevronDown className="w-5 h-5 -rotate-90" />
                                    </div>
                                </button>
                            </div>
                        ))
                    ) : (
                        <div className="text-center py-12 bg-slate-900/30 rounded-2xl border border-slate-800 border-dashed">
                            <Search className="w-12 h-12 text-slate-700 mx-auto mb-3" />
                            <p className="text-slate-400 font-medium">{t('helpCenter.noGuidesFound')}</p>
                            <p className="text-slate-600 text-sm mt-1">{t('helpCenter.tryOtherTerms')}</p>
                            <button
                                onClick={() => { setSearchTerm(''); setSelectedCategory(null); }}
                                className="mt-4 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 text-sm rounded-lg transition-colors"
                            >
                                {t('helpCenter.clearFilters')}
                            </button>
                        </div>
                    )}
                </div>

                {/* FAQ Section */}
                <div className="mt-12 mb-8">
                    <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                        <HelpCircle className="w-5 h-5 text-purple-400" />
                        {t('helpCenter.faq')}
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {FAQ.map((item, idx) => (
                            <div key={idx} className="bg-slate-900/50 border border-slate-800 p-5 rounded-xl hover:bg-slate-900 transition-colors">
                                <h4 className="font-semibold text-slate-200 mb-2">{item.question}</h4>
                                <p className="text-slate-400 text-sm leading-relaxed">{item.answer}</p>
                            </div>
                        ))}
                    </div>
                </div>

            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Plus, Save, XCircle, Calculator, User, Calendar, ShieldCheck } from 'lucide-react';
import { Customer, Product, Invoice, InvoiceItem, getFloridaTaxRate } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface InvoiceFormProps {
  onSubmit: (invoiceData: Partial<Invoice>, items: Partial<InvoiceItem>[]) => void;
  onCancel?: () => void;
  customers: Customer[];
  products: Product[];
  initialData?: Invoice;
  isEditing?: boolean;
}

interface FormData {
  customer_id: number | '';
  issue_date: string;
  due_date: string;
  status: 'draft' | 'sent' | 'paid' | 'overdue' | 'cancelled';
  notes: string;
}

interface ItemData {
  product_id: number | '';
  description: string;
  quantity: number;
  unit_price: number;
  taxable: boolean;
}

export const InvoiceForm: React.FC<InvoiceFormProps> = ({
  onSubmit,
  onCancel,
  customers,
  products,
  initialData,
  isEditing = false
}) => {
  const { t } = useLocale();
  const [formData, setFormData] = useState<FormData>({
    customer_id: initialData?.customer_id || '',
    issue_date: initialData?.issue_date || new Date().toISOString().split('T')[0],
    due_date: initialData?.due_date || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    status: initialData?.status || 'draft',
    notes: initialData?.notes || ''
  });

  const [items, setItems] = useState<ItemData[]>(
    initialData?.items?.map(item => ({
      product_id: item.product_id || '',
      description: item.description,
      quantity: item.quantity,
      unit_price: item.unit_price,
      taxable: item.taxable
    })) || [
      { product_id: '', description: '', quantity: 1, unit_price: 0, taxable: true }
    ]
  );

  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleInputChange = (field: keyof FormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };
  const handleItemChange = (index: number, field: keyof ItemData, value: any) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };

    // Si se selecciona un producto, llenar autom├íticamente descripci├│n y precio
    if (field === 'product_id' && value) {
      const product = products.find(p => p.id === parseInt(value));
      if (product) {
        newItems[index].description = product.name;
        newItems[index].unit_price = product.price;
        newItems[index].taxable = product.taxable;
      }
    }

    setItems(newItems);
  };

  const addItem = () => {
    setItems([...items, { product_id: '', description: '', quantity: 1, unit_price: 0, taxable: true }]);
  };

  const removeItem = (index: number) => {
    if (items.length > 1) {
      setItems(items.filter((_, i) => i !== index));
    }
  };

  const calculateTotals = () => {
    let subtotal = 0;
    let taxAmount = 0;

    const selectedCustomer = customers.find(c => c.id === formData.customer_id);
    const county = selectedCustomer?.florida_county || 'Miami-Dade';
    const taxRate = getFloridaTaxRate(county);

    items.forEach(item => {
      const lineTotal = item.quantity * item.unit_price;
      subtotal += lineTotal;
      if (item.taxable) {
        taxAmount += lineTotal * taxRate;
      }
    });

    return {
      subtotal: subtotal,
      taxAmount: taxAmount,
      total: subtotal + taxAmount
    };
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.customer_id) {
      newErrors.customer_id = t('invoiceForm.errorCustomer');
    }

    if (!formData.issue_date) {
      newErrors.issue_date = t('invoiceForm.errorIssueDate');
    }

    if (!formData.due_date) {
      newErrors.due_date = t('invoiceForm.errorDueDate');
    }

    // Validar que la fecha de vencimiento sea posterior a la fecha de emisi├│n
    if (formData.issue_date && formData.due_date && formData.due_date < formData.issue_date) {
      newErrors.due_date = t('invoiceForm.errorDateOrder');
    }

    // Validar items
    items.forEach((item, index) => {
      if (!item.description.trim()) {
        newErrors[`item_${index}_description`] = t('invoiceForm.errorDescription');
      }
      if (item.quantity <= 0) {
        newErrors[`item_${index}_quantity`] = t('invoiceForm.errorQuantity');
      }
      if (item.unit_price < 0) {
        newErrors[`item_${index}_unit_price`] = t('invoiceForm.errorUnitPrice');
      }
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    const invoiceData: Partial<Invoice> = {
      customer_id: formData.customer_id as number,
      issue_date: formData.issue_date,
      due_date: formData.due_date,
      status: formData.status,
      notes: formData.notes
    };

    const invoiceItems: Partial<InvoiceItem>[] = items.map(item => ({
      product_id: item.product_id || undefined,
      description: item.description,
      quantity: item.quantity,
      unit_price: item.unit_price,
      taxable: item.taxable
    }));

    onSubmit(invoiceData, invoiceItems);
  };

  const { subtotal, taxAmount, total } = calculateTotals();
  const selectedCustomer = customers.find(c => c.id === formData.customer_id);

  return (
    <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
      <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-6xl max-h-[95vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
        <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
          <div className="flex items-center gap-6">
            <div className="text-blue-500">
              {isEditing ? <Calculator className="w-8 h-8" /> : <Plus className="w-8 h-8" />}
            </div>
            <div>
              <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                {isEditing ? t('forms.editInvoice') : t('forms.newInvoice')}
              </h2>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-2 flex items-center gap-2">
                <ShieldCheck className="w-3.5 h-3.5 text-blue-500" /> Electronic Billing Protocol v2.5
              </p>
            </div>
          </div>
          {onCancel && (
            <button onClick={onCancel} className="p-3 bg-slate-950/50 border border-slate-800 rounded-xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95">
              <XCircle className="w-6 h-6" />
            </button>
          )}
        </header>

        <form onSubmit={handleSubmit} className="flex-1 overflow-hidden flex flex-col">
          <div className="p-10 space-y-10 overflow-y-auto flex-1">
            {/* Customer and Date Information */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">
                  {t('invoiceForm.customer')}
                </label>
                <div className="relative group/select">
                  <select
                    value={formData.customer_id}
                    onChange={(e) => handleInputChange('customer_id', parseInt(e.target.value) || '')}
                    className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-blue-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px] appearance-none cursor-pointer h-[58px]"
                  >
                    <option value="">{t('invoiceForm.selectCustomer')}</option>
                    {customers.map(customer => (
                      <option key={customer.id} value={customer.id}>
                        {customer.business_name || customer.name}
                      </option>
                    ))}
                  </select>
                </div>
                {errors.customer_id && <p className="text-[9px] font-black text-rose-500 uppercase tracking-widest mt-2 ml-2">{errors.customer_id}</p>}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">
                  {t('invoiceForm.issueDate')}
                </label>
                <input
                  type="date"
                  value={formData.issue_date}
                  onChange={(e) => handleInputChange('issue_date', e.target.value)}
                  className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-blue-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px] h-[58px]"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">
                  {t('invoiceForm.dueDate')}
                </label>
                <input
                  type="date"
                  value={formData.due_date}
                  onChange={(e) => handleInputChange('due_date', e.target.value)}
                  className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-blue-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px] h-[58px]"
                />
              </div>
            </div>

            {/* Customer Information Display */}
            {selectedCustomer && (
              <div className="bg-slate-950 border border-slate-800 rounded-3xl p-8 relative group overflow-hidden shadow-inner">
                <div className="absolute top-0 left-0 w-1 h-full bg-blue-500/50"></div>
                <h3 className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center gap-2">
                  <User className="w-3.5 h-3.5 text-blue-500" />
                  {t('invoiceForm.customerInfo')}
                </h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
                  <div>
                    <p className="text-[8px] font-bold text-slate-600 uppercase mb-1">{t('customerDetail.name')}</p>
                    <p className="text-[10px] font-black text-white">{selectedCustomer.business_name || selectedCustomer.name}</p>
                  </div>
                  <div>
                    <p className="text-[8px] font-bold text-slate-600 uppercase mb-1">{t('customerDetail.contact')}</p>
                    <p className="text-[10px] font-black text-white">{selectedCustomer.email}</p>
                  </div>
                  <div>
                    <p className="text-[8px] font-bold text-slate-600 uppercase mb-1">{t('customerDetail.primaryPhone')}</p>
                    <p className="text-[10px] font-black text-white">{selectedCustomer.phone}</p>
                  </div>
                  <div>
                    <p className="text-[8px] font-bold text-slate-600 uppercase mb-1">{t('customerDetail.paymentTerms')}</p>
                    <p className="text-[10px] font-black text-blue-500">{t('common.days', { n: selectedCustomer.payment_terms || 0 })}</p>
                  </div>
                </div>
              </div>
            )}

            {/* Invoice Items */}
            <div className="space-y-8">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-black text-white uppercase tracking-tighter">{t('invoiceForm.items')}</h3>
                <button
                  type="button"
                  onClick={addItem}
                  className="px-4 py-2 bg-blue-600/10 border border-blue-500/20 text-blue-500 rounded-xl text-[10px] font-bold uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all active:scale-95"
                >
                  <Plus className="w-4 h-4 mr-2 inline" />
                  {t('invoiceForm.addItem')}
                </button>
              </div>

              <div className="space-y-4">
                {items.map((item, index) => (
                  <div key={index} className="grid grid-cols-1 md:grid-cols-12 gap-6 bg-slate-950/50 p-6 rounded-[2rem] border border-slate-800 hover:border-slate-700 transition-all group/line shadow-inner">
                    <div className="md:col-span-3 space-y-2">
                      <label className="text-[8px] font-black text-slate-600 uppercase px-1">{t('invoiceForm.product')}</label>
                      <select
                        value={item.product_id}
                        onChange={(e) => handleItemChange(index, 'product_id', parseInt(e.target.value) || '')}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-blue-500 focus:outline-none text-[10px] font-black uppercase tracking-widest appearance-none cursor-pointer"
                      >
                        <option value="">{t('invoiceForm.selectProduct')}</option>
                        {products.map(product => (
                          <option key={product.id} value={product.id}>
                            {product.name}
                          </option>
                        ))}
                      </select>
                    </div>

                    <div className="md:col-span-3 space-y-2">
                      <label className="text-[8px] font-black text-slate-600 uppercase px-1">{t('invoiceForm.description')}</label>
                      <input
                        type="text"
                        value={item.description}
                        onChange={(e) => handleItemChange(index, 'description', e.target.value)}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-blue-500 focus:outline-none text-[10px] font-black uppercase tracking-widest placeholder:text-slate-700"
                        placeholder={t('invoiceForm.itemDescriptionPlaceholder')}
                      />
                    </div>

                    <div className="md:col-span-2 space-y-2">
                      <label className="text-[8px] font-black text-slate-600 uppercase px-1 text-center block">{t('invoiceForm.quantity')}</label>
                      <input
                        type="number"
                        min="0.01"
                        step="0.01"
                        value={item.quantity}
                        onChange={(e) => handleItemChange(index, 'quantity', parseFloat(e.target.value) || 0)}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-blue-500 focus:outline-none text-[10px] font-black font-mono text-center"
                      />
                    </div>

                    <div className="md:col-span-2 space-y-2">
                      <label className="text-[8px] font-black text-slate-600 uppercase px-1 text-right block">{t('invoiceForm.unitPrice')}</label>
                      <input
                        type="number"
                        min="0"
                        step="0.01"
                        value={item.unit_price}
                        onChange={(e) => handleItemChange(index, 'unit_price', parseFloat(e.target.value) || 0)}
                        className="w-full bg-slate-900 text-white px-4 py-3 rounded-xl border border-slate-800 focus:border-blue-500 focus:outline-none text-[10px] font-black font-mono text-right text-emerald-500"
                      />
                    </div>

                    <div className="md:col-span-2 flex items-center justify-between gap-4 self-end pb-1">
                      <div className="flex-1 bg-slate-900/50 p-2 rounded-xl border border-slate-800/50">
                        <label className="flex items-center gap-2 cursor-pointer group justify-center">
                          <input
                            type="checkbox"
                            checked={item.taxable}
                            onChange={(e) => handleItemChange(index, 'taxable', e.target.checked)}
                            className="w-3 h-3 rounded bg-slate-950 border-slate-800 text-blue-500 focus:ring-blue-500/20"
                          />
                          <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest group-hover:text-slate-300 transition-colors">{t('invoiceForm.tax')}</span>
                        </label>
                      </div>
                      <button type="button" onClick={() => removeItem(index)} className="p-3 bg-rose-500/10 border border-rose-500/20 text-rose-500 hover:bg-rose-500 hover:text-white rounded-xl transition-all active:scale-90">
                        <XCircle className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Status and Notes */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">
                  {t('common.status')}
                </label>
                <div className="flex bg-slate-950 rounded-2xl p-1 border border-slate-800">
                  {['draft', 'sent', 'paid', 'overdue'].map(s => (
                    <button
                      key={s}
                      type="button"
                      onClick={() => handleInputChange('status', s)}
                      className={`flex-1 py-2 rounded-xl text-[9px] font-bold uppercase tracking-widest transition-all ${formData.status === s ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">
                  {t('common.notes')}
                </label>
                <textarea
                  value={formData.notes}
                  onChange={(e) => handleInputChange('notes', e.target.value)}
                  rows={2}
                  className="w-full bg-slate-950/50 text-white px-6 py-5 rounded-2xl border border-slate-800/50 focus:border-blue-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px] resize-none placeholder:text-slate-800"
                  placeholder={t('invoiceForm.notesPlaceholder')}
                />
              </div>
            </div>
          </div>

          {/* Invoice Summary Footer */}
          <footer className="p-10 border-t border-slate-800/50 bg-slate-950/80 relative z-10 flex flex-col md:flex-row items-center justify-between gap-12">
            <div className="flex gap-16">
              <div className="text-left">
                <p className="text-[8px] font-black text-slate-600 uppercase tracking-widest mb-1">{t('invoiceForm.subtotal')}</p>
                <p className="text-xl font-black text-slate-300 font-mono italic">${subtotal.toFixed(2)}</p>
              </div>
              <div className="text-left">
                <p className="text-[8px] font-black text-slate-600 uppercase tracking-widest mb-1">{t('invoiceForm.tax')} ({(getFloridaTaxRate(selectedCustomer?.florida_county || 'Miami-Dade') * 100).toFixed(1)}%)</p>
                <p className="text-xl font-black text-rose-400 font-mono italic">${taxAmount.toFixed(2)}</p>
              </div>
              <div className="group">
                <p className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em] mb-3">{t('invoiceForm.total')}</p>
                <p className="text-5xl font-black text-white font-mono tracking-tighter group-hover:scale-105 transition-transform origin-left">${total.toFixed(2)}</p>
              </div>
            </div>

            <div className="flex gap-6 w-full md:w-auto">
              {onCancel && (
                <button
                  type="button"
                  onClick={onCancel}
                  className="flex-1 md:flex-none px-8 py-2.5 bg-slate-900 border border-slate-800 text-slate-400 rounded-xl font-bold uppercase tracking-widest text-[10px] hover:bg-slate-800 transition-all shadow-lg active:scale-95"
                >
                  {t('common.cancel')}
                </button>
              )}
              <button
                type="submit"
                className="flex-1 md:flex-none px-10 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl font-bold uppercase tracking-widest text-[11px] transition-all flex items-center justify-center gap-3 shadow-lg shadow-blue-900/40 active:scale-95"
              >
                <Save className="w-5 h-5" />
                {isEditing ? t('invoiceForm.updateInvoice') : t('invoiceForm.createInvoice')}
              </button>
            </div>
          </footer>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  AlertCircle,
  CheckCircle,
  RefreshCw,
  FileText,
  Calculator,
  Zap,
  Play,
  History,
  Terminal as TerminalIcon,
  ChevronRight,
  TrendingUp,
  TrendingDown,
  Box,
  Beaker,
  ShieldAlert,
  Loader2
} from 'lucide-react';
import {
  createJournalEntry,
  getJournalEntries,
  generateSalesJournalEntry,
  generatePurchaseJournalEntry,
  JournalEntry,
  getInvoiceById,
  getBillById
} from '@/database/simple-db';
import { logger } from '../core/logging/SystemLogger';
import { useLocale } from '../i18n/useLocale';

export function JournalEntryTest() {
  const { t } = useLocale();
  const [journalEntries, setJournalEntries] = useState<JournalEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [testResults, setTestResults] = useState<any[]>([]);

  const loadJournalEntries = async () => {
    try {
      setLoading(true);
      const entries = getJournalEntries(20);
      setJournalEntries(entries);
    } catch (error) {
      setError(t('journalEntryTest.errorLoadingEntries'));
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  const testManualJournalEntry = async () => {
    try {
      const testEntry = {
        entry_date: new Date().toISOString().split('T')[0],
        reference_number: `TEST-${Date.now()}`,
        description: t('journalEntryTest.manualTestEntryDesc')
      };

      const testDetails = [
        { account_code: '1111', debit_amount: 1000, credit_amount: 0, description: t('journalEntryTest.cashEntryDesc') },
        { account_code: '4110', debit_amount: 0, credit_amount: 1000, description: t('journalEntryTest.serviceSaleDesc') }
      ];

      const result = await createJournalEntry(testEntry, testDetails);
      const testResult = {
        test: 'Manual Journey Protocol',
        success: result.success,
        message: result.message,
        entryId: result.entryId,
        timestamp: new Date().toISOString()
      };

      setTestResults(prev => [testResult, ...prev]);
      if (result.success) await loadJournalEntries();
    } catch (error) {
      setTestResults(prev => [{ test: 'Manual Journey Protocol', success: false, message: 'Exception', timestamp: new Date().toISOString() }, ...prev]);
    }
  };

  const testSalesJournalEntry = async () => {
    try {
      const invoice = getInvoiceById(1);
      if (!invoice) return;
      const result = await generateSalesJournalEntry(invoice);
      setTestResults(prev => [{
        test: 'Sales Auto-Ledger',
        success: result.success,
        message: result.message,
        entryId: result.entryId,
        timestamp: new Date().toISOString()
      }, ...prev]);
      if (result.success) await loadJournalEntries();
    } catch (error) { }
  };

  const testPurchaseJournalEntry = async () => {
    try {
      const bill = getBillById(1);
      if (!bill) return;
      const result = await generatePurchaseJournalEntry(bill);
      setTestResults(prev => [{
        test: 'Purchase Auto-Ledger',
        success: result.success,
        message: result.message,
        entryId: result.entryId,
        timestamp: new Date().toISOString()
      }, ...prev]);
      if (result.success) await loadJournalEntries();
    } catch (error) { }
  };

  const runAllTests = async () => {
    setTestResults([]);
    await testManualJournalEntry();
    await testSalesJournalEntry();
    await testPurchaseJournalEntry();
  };

  useEffect(() => {
    loadJournalEntries();
  }, []);

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      {/* Test Control Hub */}
      <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-amber-600/10 rounded-2.5xl border border-amber-500/20 shadow-amber-900/10 shadow-lg">
            <Beaker className="w-10 h-10 text-amber-500" />
          </div>
          <div>
            <h2 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">{t('journalEntryTest.title')}</h2>
            <p className="text-slate-500 font-black uppercase tracking-[0.3em] text-[10px] mt-2 flex items-center gap-2">
              <Zap className="w-3.5 h-3.5 text-amber-500 animate-pulse" /> {t('journalEntryTest.subtitle')}
            </p>
          </div>
        </div>

        <div className="flex gap-4">
          <button onClick={loadJournalEntries} className="p-4 bg-slate-950 border border-slate-800 text-slate-500 hover:text-white rounded-2xl transition-all">
            <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
          </button>
          <button onClick={runAllTests} className="flex items-center gap-3 px-10 py-4 bg-amber-600 hover:bg-amber-500 text-white rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-xl shadow-amber-900/30 active:scale-95">
            <Play className="w-4 h-4 fill-current" /> {t('journalEntryTest.runTotalSuite')}
          </button>
        </div>
      </div>

      {/* Action Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <TestTrigger
          title={t('journalEntryTest.manualEntry')}
          desc={t('journalEntryTest.generateTestEntry')}
          onClick={testManualJournalEntry}
          color="emerald"
          icon={TrendingUp}
        />
        <TestTrigger
          title={t('journalEntryTest.autoSales')}
          desc={t('journalEntryTest.invoiceToLedgerProtocol')}
          onClick={testSalesJournalEntry}
          color="blue"
          icon={Calculator}
        />
        <TestTrigger
          title={t('journalEntryTest.autoPurchases')}
          desc={t('journalEntryTest.billToLedgerProtocol')}
          onClick={testPurchaseJournalEntry}
          color="purple"
          icon={TrendingDown}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 mt-10">
        {/* Results Console */}
        <div className="lg:col-span-1 bg-slate-900/40 border border-slate-800 rounded-[3rem] overflow-hidden shadow-2xl flex flex-col h-[600px]">
          <header className="px-10 py-6 bg-slate-950/50 border-b border-slate-800 flex items-center justify-between">
            <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center gap-2">
              <TerminalIcon className="w-4 h-4 text-emerald-500" /> {t('journalEntryTest.testLogs')}
            </h4>
            <span className="text-[9px] font-black text-slate-600 bg-slate-900 px-2 py-1 rounded">REV 41.0</span>
          </header>
          <div className="flex-1 overflow-y-auto p-8 space-y-4 scrollbar-hide">
            {testResults.length === 0 ? (
              <div className="py-20 text-center opacity-20 italic font-black text-slate-500 uppercase tracking-widest text-[10px]">{t('journalEntryTest.waitingForExecution')}</div>
            ) : (
              testResults.map((result, i) => (
                <div key={i} className={`p-5 rounded-2xl border transition-all animate-in slide-in-from-left-4 duration-300 ${result.success ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-rose-500/5 border-rose-500/20'
                  }`}>
                  <div className="flex items-center justify-between mb-2">
                    <span className={`text-[10px] font-black uppercase tracking-widest ${result.success ? 'text-emerald-500' : 'text-rose-500'}`}>
                      {result.test}
                    </span>
                    {result.success ? <CheckCircle className="w-3 h-3 text-emerald-500" /> : <ShieldAlert className="w-3 h-3 text-rose-500" />}
                  </div>
                  <p className="text-sm font-bold text-slate-300 leading-tight mb-3">{result.message}</p>
                  <div className="flex items-center justify-between text-[8px] font-black uppercase tracking-widest text-slate-600">
                    <span>{new Date(result.timestamp).toLocaleTimeString()}</span>
                    {result.entryId && <span className="text-blue-500/60">E-ID: {result.entryId}</span>}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Ledger Preview */}
        <div className="lg:col-span-2 bg-slate-900/40 border border-slate-800 rounded-[3rem] overflow-hidden shadow-2xl flex flex-col h-[600px]">
          <header className="px-10 py-6 bg-slate-950/50 border-b border-slate-800 flex items-center justify-between">
            <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center gap-2">
              <History className="w-4 h-4 text-blue-500" /> {t('journalEntryTest.latestLabRecords')}
            </h4>
            {loading && <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />}
          </header>
          <div className="flex-1 overflow-y-auto p-10 space-y-6 scrollbar-hide">
            {journalEntries.map((entry) => (
              <div key={entry.id} className="p-8 bg-slate-950/40 border border-slate-800/60 rounded-[2.5rem] hover:border-blue-500/30 transition-all group">
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-5">
                    <div className={`w-3 h-3 rounded-full ${entry.is_balanced ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-rose-500 shadow-[0_0_15px_rgba(244,63,94,0.5)]'}`} />
                    <div>
                      <p className="text-xl font-black text-white uppercase tracking-tighter">{entry.reference_number || `TEST-NODE-${entry.id}`}</p>
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1">{entry.entry_date} ΓÇó {entry.description}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-black text-white font-mono tracking-tighter">${entry.total_debit.toLocaleString()}</p>
                    <p className={`text-[9px] font-black uppercase tracking-widest mt-1 ${entry.is_balanced ? 'text-emerald-500' : 'text-rose-500'}`}>
                      {entry.is_balanced ? t('journalEntryTest.syncOk') : t('journalEntryTest.outOfPivot')}
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-slate-800/50 pt-6">
                  {entry.details?.map((detail, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3 bg-slate-950/60 rounded-xl border border-slate-800/40">
                      <div className="flex items-center gap-3">
                        <span className="font-mono text-[9px] font-black text-blue-400 bg-blue-500/5 px-2 py-1 rounded-lg border border-blue-500/10">{detail.account_code}</span>
                        <span className="text-xs font-bold text-slate-400 truncate max-w-[100px]">{detail.account?.account_name}</span>
                      </div>
                      <span className={`text-xs font-black font-mono ${detail.debit_amount > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                        ${(detail.debit_amount || detail.credit_amount).toLocaleString()}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

const TestTrigger = ({ title, desc, onClick, color, icon: Icon }: any) => {
  const colors: any = {
    emerald: 'bg-emerald-600/10 border-emerald-500/20 text-emerald-500 group-hover:bg-emerald-600 group-hover:text-white',
    blue: 'bg-blue-600/10 border-blue-500/20 text-blue-500 group-hover:bg-blue-600 group-hover:text-white',
    purple: 'bg-purple-600/10 border-purple-500/20 text-purple-500 group-hover:bg-purple-600 group-hover:text-white',
  };

  return (
    <button
      onClick={onClick}
      className="group p-8 bg-slate-900 border border-slate-800 rounded-[2.5rem] text-left transition-all hover:border-blue-500/30 hover:-translate-y-2 shadow-xl"
    >
      <div className={`w-14 h-14 rounded-2xl border flex items-center justify-center mb-6 transition-all duration-500 ${colors[color]}`}>
        <Icon className="w-7 h-7" />
      </div>
      <h4 className="text-xl font-black text-white uppercase tracking-tighter mb-2">{title}</h4>
      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{desc}</p>
    </button>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Plus,
  Trash2,
  Calculator,
  Save,
  XCircle,
  AlertCircle,
  CheckCircle,
  FileText,
  Calendar,
  History,
  ShieldCheck,
  ArrowRight,
  ChevronRight,
  ArrowDownCircle,
  Hash,
  Search,
  Loader2,
  Cpu
} from 'lucide-react';
import { ChartOfAccount, createJournalEntry, getJournalEntries, JournalEntry, JournalDetail } from '@/database/simple-db';
import { toast } from 'react-hot-toast';
import { useLocale } from '../i18n/useLocale';

interface JournalEntryLine {
  id: string;
  account_id: number;
  account_code: string;
  account_name: string;
  description: string;
  debit: number;
  credit: number;
}

interface ManualJournalEntry {
  id?: number;
  date: string;
  reference: string;
  description: string;
  lines: JournalEntryLine[];
  total_debits: number;
  total_credits: number;
  is_balanced: boolean;
  created_at?: string;
}

interface ManualJournalEntriesProps {
  chartOfAccounts: ChartOfAccount[];
  onEntryCreated: () => void;
}

export const ManualJournalEntries: React.FC<ManualJournalEntriesProps> = ({
  chartOfAccounts,
  onEntryCreated
}) => {
  const { t } = useLocale();
  const [entries, setEntries] = useState<ManualJournalEntry[]>([]);
  const [showEntryForm, setShowEntryForm] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [currentEntry, setCurrentEntry] = useState<ManualJournalEntry>({
    date: new Date().toISOString().split('T')[0],
    reference: '',
    description: '',
    lines: [],
    total_debits: 0,
    total_credits: 0,
    is_balanced: false
  });

  useEffect(() => {
    loadJournalEntries();
  }, []);

  useEffect(() => {
    calculateTotals();
  }, [currentEntry.lines]);

  const loadJournalEntries = () => {
    try {
      const dbEntries = getJournalEntries(200);
      const mappedEntries: ManualJournalEntry[] = dbEntries.map(entry => ({
        id: entry.id,
        date: entry.entry_date,
        reference: entry.reference || entry.reference_number || '',
        description: entry.description,
        total_debits: entry.total_debit,
        total_credits: entry.total_credit,
        is_balanced: entry.is_balanced,
        lines: []
      }));
      setEntries(mappedEntries);
    } catch (error) {
      console.error('Error loading entries:', error);
      toast.error(t('journal.syncError'));
    }
  };

  const calculateTotals = () => {
    const totalDebits = currentEntry.lines.reduce((sum, line) => sum + (line.debit || 0), 0);
    const totalCredits = currentEntry.lines.reduce((sum, line) => sum + (line.credit || 0), 0);
    const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01;

    setCurrentEntry(prev => ({
      ...prev,
      total_debits: totalDebits,
      total_credits: totalCredits,
      is_balanced: isBalanced
    }));
  };

  const addNewLine = () => {
    const newLine: JournalEntryLine = {
      id: Date.now().toString(),
      account_id: 0,
      account_code: '',
      account_name: '',
      description: '',
      debit: 0,
      credit: 0
    };
    setCurrentEntry(prev => ({ ...prev, lines: [...prev.lines, newLine] }));
  };

  const updateLine = (lineId: string, field: keyof JournalEntryLine, value: any) => {
    setCurrentEntry(prev => ({
      ...prev,
      lines: prev.lines.map(line => {
        if (line.id === lineId) {
          const updatedLine = { ...line, [field]: value };
          if (field === 'account_id') {
            const account = chartOfAccounts.find(acc => acc.id === parseInt(value));
            if (account) {
              updatedLine.account_code = account.account_code;
              updatedLine.account_name = account.account_name;
            }
          }
          if (field === 'debit' && parseFloat(value) > 0) updatedLine.credit = 0;
          else if (field === 'credit' && parseFloat(value) > 0) updatedLine.debit = 0;
          return updatedLine;
        }
        return line;
      })
    }));
  };

  const removeLine = (lineId: string) => {
    setCurrentEntry(prev => ({
      ...prev,
      lines: prev.lines.filter(line => line.id !== lineId)
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEntry.is_balanced) {
      toast.error(t('journal.doubleEntryError'));
      return;
    }

    setIsLoading(true);
    try {
      const details: Partial<JournalDetail>[] = currentEntry.lines.map(line => ({
        account_code: line.account_code,
        debit_amount: line.debit,
        credit_amount: line.credit,
        description: line.description
      }));

      const entryData: Partial<JournalEntry> = {
        entry_date: currentEntry.date,
        reference: currentEntry.reference,
        description: currentEntry.description,
        total_debit: currentEntry.total_debits,
        total_credit: currentEntry.total_credits,
        is_balanced: true
      };

      const result = await createJournalEntry(entryData, details);
      if (result.success) {
        toast.success(t('journal.registeredSuccess'));
        loadJournalEntries();
        setShowEntryForm(false);
        resetForm();
        onEntryCreated();
      } else {
        toast.error(result.message);
      }
    } catch (error: any) {
      toast.error(t('journal.persistenceError') + error.message);
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setCurrentEntry({
      date: new Date().toISOString().split('T')[0],
      reference: '',
      description: '',
      lines: [],
      total_debits: 0,
      total_credits: 0,
      is_balanced: false
    });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Header Panel */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 p-1 bg-slate-900/40 border border-slate-800 rounded-3xl backdrop-blur-md">
        <div className="flex items-center gap-5 p-4">
          <div className="p-3 bg-blue-600/10 rounded-2xl border border-blue-500/20">
            <History className="w-8 h-8 text-blue-500" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-white tracking-tight">{t('journal.title')}</h2>
            <p className="text-xs font-medium text-slate-500 mt-1">{t('journal.subtitle')}</p>
          </div>
        </div>
        <div className="p-4 w-full md:w-auto">
          <button
            onClick={() => setShowEntryForm(true)}
            className="w-full md:w-auto bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl flex items-center justify-center gap-3 transition-all font-bold shadow-lg shadow-blue-900/40 active:scale-95"
          >
            <Plus className="w-5 h-5" />
            {t('journal.newEntry')}
          </button>
        </div>
      </div>

      {/* Registry Database Visual */}
      <div className="bg-slate-900/40 border border-slate-800/60 rounded-[2.5rem] overflow-hidden shadow-2xl backdrop-blur-sm">
        <div className="px-10 py-6 bg-slate-950/50 border-b border-slate-800 flex items-center justify-between">
          <h3 className="text-sm font-bold text-white flex items-center gap-3">
            <ShieldCheck className="w-4 h-4 text-emerald-500" />
            {t('journal.verifiedEntries')}
          </h3>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-900 rounded-xl border border-slate-800">
              <Search className="w-3.5 h-3.5 text-slate-500" />
              <span className="text-xs font-medium text-slate-500">{t('journal.filterHistory')}</span>
            </div>
          </div>
        </div>

        {entries.length === 0 ? (
          <div className="text-center py-24 opacity-30">
            <FileText className="mx-auto h-20 w-20 text-slate-700 mb-6" />
            <p className="font-black text-slate-500 uppercase tracking-widest text-xs">{t('journal.noEntries')}</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-slate-950/50 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-800">
                  <th className="px-10 py-5 text-left">{t('journal.fiscalDate')}</th>
                  <th className="px-10 py-5 text-left">{t('journal.auditRef')}</th>
                  <th className="px-10 py-5 text-left">{t('journal.description')}</th>
                  <th className="px-10 py-5 text-right w-32">{t('journal.totalDR')}</th>
                  <th className="px-10 py-5 text-right w-32">{t('journal.totalCR')}</th>
                  <th className="px-10 py-5 text-center w-24">{t('journal.status')}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/40">
                {entries.map((entry) => (
                  <tr key={entry.id} className="hover:bg-slate-800/30 transition-all group">
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-3">
                        <Calendar className="w-3.5 h-3.5 text-slate-600" />
                        <span className="font-mono text-xs text-slate-400 font-bold">{new Date(entry.date).toLocaleDateString()}</span>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <span className="font-bold text-xs text-blue-500 tracking-tight bg-blue-500/5 px-3 py-1.5 rounded-xl border border-blue-500/10 shadow-sm">{entry.reference}</span>
                    </td>
                    <td className="px-10 py-6">
                      <p className="text-sm font-bold text-slate-200 group-hover:text-white transition-colors">{entry.description}</p>
                    </td>
                    <td className="px-10 py-6 text-right font-mono font-black text-emerald-400/90 text-[13px]">
                      ${entry.total_debits.toLocaleString('en-US', { minimumFractionDigits: 2 })}
                    </td>
                    <td className="px-10 py-6 text-right font-mono font-black text-rose-400/90 text-[13px]">
                      ${entry.total_credits.toLocaleString('en-US', { minimumFractionDigits: 2 })}
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex justify-center">
                        <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]" />
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Industrial Grade Entry Modal */}
      {showEntryForm && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-2xl overflow-y-auto h-full w-full z-50 p-4 md:p-12 animate-in fade-in duration-300 flex items-center justify-center">
          <div className="relative bg-slate-900 border border-slate-800 shadow-[0_0_100px_rgba(0,0,0,0.5)] rounded-[3rem] overflow-hidden max-w-6xl w-full animate-in zoom-in duration-500">
            <header className="px-10 py-10 border-b border-slate-800/50 flex items-center justify-between relative z-10">
              <div className="flex items-center gap-6">
                <div className="text-blue-500">
                  <Cpu className="w-10 h-10" />
                </div>
                <div>
                  <h3 className="text-3xl font-black text-white tracking-tighter uppercase leading-none">{t('journal.folioInitiator')}</h3>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2 flex items-center gap-2">
                    <ShieldCheck className="w-3.5 h-3.5 text-blue-500" /> {t('journal.standardUSGAAP')}
                  </p>
                </div>
              </div>
              <button onClick={() => setShowEntryForm(false)} className="p-4 bg-slate-950/50 border border-slate-800 rounded-3xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95">
                <XCircle className="w-7 h-7" />
              </button>
            </header>

            <form onSubmit={handleSubmit} className="p-10 space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 mb-2 flex items-center gap-2">
                    <Calendar className="w-3.5 h-3.5" /> {t('journal.fiscalDate')}
                  </label>
                  <input
                    type="date"
                    value={currentEntry.date}
                    onChange={(e) => setCurrentEntry(prev => ({ ...prev, date: e.target.value }))}
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-6 py-4 text-white font-mono font-bold text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500/50 outline-none transition-all"
                    required
                  />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 mb-2 flex items-center gap-2">
                    <Hash className="w-3.5 h-3.5" /> {t('journal.internalRef')}
                  </label>
                  <input
                    type="text"
                    value={currentEntry.reference}
                    onChange={(e) => setCurrentEntry(prev => ({ ...prev, reference: e.target.value }))}
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-6 py-4 text-white font-black uppercase tracking-widest text-[10px] focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500/50 outline-none transition-all"
                    placeholder={t('journal.internalRefPlaceholder')}
                    required
                  />
                </div>
                <div className="md:col-span-2 space-y-3">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 mb-2 flex items-center gap-2">
                    <FileText className="w-3.5 h-3.5" /> {t('journal.generalGloss')}
                  </label>
                  <input
                    type="text"
                    value={currentEntry.description}
                    onChange={(e) => setCurrentEntry(prev => ({ ...prev, description: e.target.value }))}
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-6 py-4 text-white font-bold text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500/50 outline-none transition-all"
                    placeholder={t('journal.generalGlossPlaceholder')}
                    required
                  />
                </div>
              </div>

              <div className="bg-slate-950/40 border border-slate-800 rounded-[2rem] overflow-hidden shadow-inner p-1">
                <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-950 text-[10px] font-bold text-slate-500 uppercase tracking-widest border-b border-slate-800/50">
                    <tr>
                      <th className="px-8 py-5">{t('journal.account')}</th>
                      <th className="px-8 py-5">{t('journal.lineDetail')}</th>
                      <th className="px-8 py-5 text-right w-40">{t('journal.debit')}</th>
                      <th className="px-8 py-5 text-right w-40">{t('journal.credit')}</th>
                      <th className="py-5 w-16"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/40">
                    {currentEntry.lines.map((line) => (
                      <tr key={line.id} className="hover:bg-slate-800/20 transition-all">
                        <td className="px-6 py-4">
                          <select
                            value={line.account_id}
                            onChange={(e) => updateLine(line.id, 'account_id', e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 text-[10px] font-bold uppercase tracking-widest text-white focus:border-blue-500/50 focus:ring-2 focus:ring-blue-500/10 outline-none transition-all cursor-pointer"
                            required
                          >
                            <option value="">{t('journal.selectNode')}</option>
                            {chartOfAccounts.map((account) => (
                              <option key={account.id} value={account.id}>
                                {account.account_code} ΓÇó {account.account_name}
                              </option>
                            ))}
                          </select>
                        </td>
                        <td className="px-6 py-4">
                          <input
                            type="text"
                            value={line.description}
                            onChange={(e) => updateLine(line.id, 'description', e.target.value)}
                            className="w-full bg-transparent border-b border-slate-800 focus:border-blue-500 text-[10px] font-bold uppercase tracking-widest text-slate-400 p-3 outline-none transition-all"
                            placeholder={t('journal.lineDetailPlaceholder')}
                            required
                          />
                        </td>
                        <td className="px-6 py-4">
                          <input
                            type="number"
                            step="0.01"
                            value={line.debit || ''}
                            onChange={(e) => updateLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 text-right font-mono font-black text-emerald-400 text-sm focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/10 outline-none transition-all"
                            disabled={line.credit > 0}
                            onFocus={(e) => e.target.select()}
                          />
                        </td>
                        <td className="px-6 py-4">
                          <input
                            type="number"
                            step="0.01"
                            value={line.credit || ''}
                            onChange={(e) => updateLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 text-right font-mono font-black text-rose-400 text-sm focus:border-rose-500 focus:ring-2 focus:ring-rose-500/10 outline-none transition-all"
                            disabled={line.debit > 0}
                            onFocus={(e) => e.target.select()}
                          />
                        </td>
                        <td className="pr-6">
                          <button onClick={() => removeLine(line.id)} className="p-2 text-slate-600 hover:text-red-500 hover:bg-red-500/10 rounded-xl transition-all">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot className="bg-slate-950/60 font-black">
                    <tr>
                      <td colSpan={2} className="px-8 py-8">
                        <button
                          type="button"
                          onClick={addNewLine}
                          className="flex items-center gap-3 text-blue-500 hover:text-white bg-blue-500/5 hover:bg-blue-600 px-8 py-4 border border-blue-500/20 rounded-2xl font-black uppercase tracking-widest text-[10px] transition-all shadow-lg active:scale-95"
                        >
                          <Plus className="w-4 h-4" /> {t('journal.expandEntry')}
                        </button>
                      </td>
                      <td className="px-8 py-8 text-right bg-slate-900/40">
                        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-2 px-1">Total DR</span>
                        <span className="font-mono text-xl text-emerald-400">${currentEntry.total_debits.toFixed(2)}</span>
                      </td>
                      <td className="px-8 py-8 text-right bg-slate-900/40">
                        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-2 px-1">Total CR</span>
                        <span className="font-mono text-xl text-rose-400">${currentEntry.total_credits.toFixed(2)}</span>
                      </td>
                      <td className="bg-slate-900/40"></td>
                    </tr>
                  </tfoot>
                </table>
              </div>

              <div className="flex flex-col md:flex-row items-center justify-between gap-8 pt-8 border-t border-slate-800">
                <div className={`flex items-center gap-4 px-8 py-4 rounded-3xl border-2 transition-all ${currentEntry.is_balanced
                  ? 'bg-emerald-500/5 border-emerald-500/20 text-emerald-500'
                  : 'bg-rose-500/10 border-rose-500/30 text-rose-400 animate-pulse'
                  }`}>
                  {currentEntry.is_balanced ? <CheckCircle className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-[0.2em]">{currentEntry.is_balanced ? t('journal.validatedProtocol') : t('journal.outOfBalance')}</p>
                    {!currentEntry.is_balanced && (
                      <p className="text-xs font-bold font-mono tracking-tighter">{t('journal.imbalance')} ${Math.abs(currentEntry.total_debits - currentEntry.total_credits).toFixed(2)}</p>
                    )}
                  </div>
                </div>

                <div className="flex gap-4 w-full md:w-auto">
                  <button
                    type="button"
                    onClick={() => setShowEntryForm(false)}
                    className="flex-1 md:flex-none bg-slate-950/50 hover:bg-slate-800 border border-slate-800 text-slate-500 hover:text-white font-black uppercase tracking-widest text-[10px] px-10 py-5 rounded-2xl transition-all active:scale-95"
                  >
                    {t('journal.discard')}
                  </button>
                  <button
                    type="submit"
                    disabled={isLoading || !currentEntry.is_balanced || currentEntry.lines.length < 2}
                    className="flex-1 md:flex-none bg-blue-600 hover:bg-blue-500 text-white font-black uppercase tracking-widest text-[11px] px-12 py-5 rounded-2xl transition-all shadow-2xl shadow-blue-900/60 disabled:opacity-20 flex items-center justify-center gap-4 active:scale-95"
                  >
                    {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                    {t('journal.syncLedger')}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, CreditCard, Check, X, AlertCircle } from 'lucide-react';
import { PaymentMethod, getAllPaymentMethods, createPaymentMethod, updatePaymentMethod, deletePaymentMethod, canDeletePaymentMethod } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface PaymentMethodsProps {
  onPaymentMethodsChange?: () => void;
}

export const PaymentMethods: React.FC<PaymentMethodsProps> = ({ onPaymentMethodsChange }) => {
  const { t } = useLocale();
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [editingMethod, setEditingMethod] = useState<PaymentMethod | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    method_name: '',
    method_type: 'other' as 'cash' | 'check' | 'credit_card' | 'bank_transfer' | 'other',
    is_active: true,
    requires_reference: false
  });

  useEffect(() => {
    loadPaymentMethods();
  }, []);

  const loadPaymentMethods = () => {
    try {
      const methods = getAllPaymentMethods();
      setPaymentMethods(methods);
    } catch (error) {
      console.error('Error loading payment methods:', error);
      setError(t('paymentMethods.error.load'));
    }
  };

  const resetForm = () => {
    setFormData({
      method_name: '',
      method_type: 'other',
      is_active: true,
      requires_reference: false
    });
    setEditingMethod(null);
    setShowForm(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      let result;

      if (editingMethod) {
        result = updatePaymentMethod(editingMethod.id, formData);
      } else {
        result = await createPaymentMethod(formData);
      }

      if (result.success) {
        setSuccess(result.message);
        resetForm();
        loadPaymentMethods();
        onPaymentMethodsChange?.();

        setTimeout(() => setSuccess(null), 3000);
      } else {
        setError(result.message);
      }
    } catch (error) {
      console.error('Error saving payment method:', error);
      setError(t('paymentMethods.error.save'));
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (method: PaymentMethod) => {
    setEditingMethod(method);
    setFormData({
      method_name: method.method_name,
      method_type: method.method_type,
      is_active: method.is_active,
      requires_reference: method.requires_reference
    });
    setShowForm(true);
  };

  const handleDelete = async (method: PaymentMethod) => {
    const deleteCheck = canDeletePaymentMethod(method.id);

    if (!deleteCheck.canDelete) {
      setError(deleteCheck.reason || t('paymentMethods.error.cannotDelete'));
      return;
    }

    if (!window.confirm(`${t('paymentMethods.confirmDelete')} "${method.method_name}"?`)) {
      return;
    }

    try {
      const result = deletePaymentMethod(method.id);

      if (result.success) {
        setSuccess(result.message);
        loadPaymentMethods();
        onPaymentMethodsChange?.();

        setTimeout(() => setSuccess(null), 3000);
      } else {
        setError(result.message);
      }
    } catch (error) {
      console.error('Error deleting payment method:', error);
      setError(t('paymentMethods.error.delete'));
    }
  };

  const getMethodTypeLabel = (type: string) => {
    const labels = {
      cash: t('paymentMethods.type.cash'),
      check: t('paymentMethods.type.check'),
      credit_card: t('paymentMethods.type.creditCard'),
      bank_transfer: t('paymentMethods.type.bankTransfer'),
      other: t('paymentMethods.type.other')
    };
    return labels[type as keyof typeof labels] || type;
  };

  const getMethodTypeColor = (type: string) => {
    const colors = {
      cash: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
      check: 'text-blue-400 bg-blue-500/10 border-blue-500/20',
      credit_card: 'text-purple-400 bg-purple-500/10 border-purple-500/20',
      bank_transfer: 'text-orange-400 bg-orange-500/10 border-orange-500/20',
      other: 'text-slate-400 bg-slate-500/10 border-slate-500/20'
    };
    return colors[type as keyof typeof colors] || 'text-slate-400 bg-slate-500/10 border-slate-500/20';
  };

  return (
    <div className="space-y-6 bg-slate-950 p-8 rounded-2xl border border-slate-800 shadow-2xl">
      {/* Header */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-6 border-b border-slate-800 pb-6">
        <div>
          <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight">
            <CreditCard className="w-8 h-8 text-blue-500" />
            {t('paymentMethods.title')}
          </h2>
          <p className="text-slate-500 font-medium text-sm mt-2">{t('paymentMethods.subtitle')}</p>
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl flex items-center space-x-2 transition-all font-bold shadow-lg shadow-blue-900/40"
        >
          <Plus className="w-4 h-4 mr-2" />
          {t('paymentMethods.newMethod')}
        </button>
      </div>

      {/* Mensajes */}
      {error && (
        <div className="bg-rose-500/10 border border-rose-500/20 rounded-2xl p-4 animate-in fade-in duration-300">
          <div className="flex items-center gap-3">
            <AlertCircle className="h-5 w-5 text-rose-400" />
            <p className="text-sm text-rose-300 font-medium flex-1">{error}</p>
            <button onClick={() => setError(null)} className="text-rose-400 hover:text-rose-200">
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {success && (
        <div className="bg-emerald-500/10 border border-emerald-500/20 rounded-2xl p-4 animate-in fade-in duration-300">
          <div className="flex items-center gap-3">
            <Check className="h-5 w-5 text-emerald-400" />
            <p className="text-sm text-emerald-300 font-medium flex-1">{success}</p>
            <button onClick={() => setSuccess(null)} className="text-emerald-400 hover:text-emerald-200">
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Lista de m├⌐todos de pago */}
      <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden shadow-xl">
        <div className="px-6 py-4 border-b border-slate-800 bg-slate-900/50">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div>
            {t('paymentMethods.activeConfigurations')}
          </h3>
          <p className="text-slate-400 text-sm font-medium mt-1">
            {paymentMethods.length} {t('paymentMethods.registeredMethods')}
          </p>
        </div>

        {paymentMethods.length === 0 ? (
          <div className="text-center py-20 bg-slate-950/50">
            <div className="bg-slate-800 w-16 h-16 rounded-3xl flex items-center justify-center mx-auto mb-4 border border-slate-700">
              <CreditCard className="h-8 w-8 text-slate-500" />
            </div>
            <h3 className="text-lg font-black text-white">{t('paymentMethods.noMethods')}</h3>
            <p className="mt-1 text-slate-400 font-medium">
              {t('paymentMethods.noMethodsDesc')}
            </p>
          </div>
        ) : (
          <ul className="divide-y divide-slate-800/50">
            {paymentMethods.map((method) => (
              <li key={method.id} className="px-6 py-5 hover:bg-slate-800/30 transition-colors group">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-5">
                    <div className="p-3 bg-slate-800 rounded-2xl border border-slate-700 group-hover:border-slate-600 transition-all">
                      <CreditCard className="h-6 w-6 text-slate-400" />
                    </div>
                    <div>
                      <div className="flex items-center gap-3">
                        <p className="text-lg font-black text-white tracking-tight">
                          {method.method_name}
                        </p>
                        <span className={`px-3 py-1 text-xs font-bold rounded-lg border bg-slate-950/50 ${getMethodTypeColor(method.method_type)}`}>
                          {getMethodTypeLabel(method.method_type)}
                        </span>
                        {!method.is_active && (
                          <span className="px-3 py-1 text-xs font-bold rounded-lg bg-rose-500/10 text-rose-400 border border-rose-500/20">
                            {t('common.inactive')}
                          </span>
                        )}
                      </div>
                      <div className="mt-2 flex items-center gap-4 text-xs font-bold text-slate-500">
                        {method.requires_reference && (
                          <span className="flex items-center gap-1.5 text-blue-400/70 bg-blue-400/5 px-2 py-1 rounded-md border border-blue-400/10">
                            <AlertCircle className="w-3 h-3" />
                            {t('paymentMethods.requiresReference')}
                          </span>
                        )}
                        <span className="opacity-60 text-xs font-medium tracking-tight">
                          ID: {method.id} ΓÇó {new Date(method.created_at).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => handleEdit(method)}
                      className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-xl transition-all"
                      title={t('common.edit')}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(method)}
                      className="p-2 text-slate-400 hover:text-rose-400 hover:bg-rose-500/10 rounded-xl transition-all"
                      title={t('common.delete')}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Modal de formulario */}
      {showForm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="relative w-full max-w-lg bg-slate-900 border border-slate-700 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-2xl font-black text-white tracking-tight">
                    {editingMethod ? t('paymentMethods.form.titleEdit') : t('paymentMethods.form.titleNew')}
                  </h3>
                  <p className="text-slate-400 font-medium text-sm">{t('paymentMethods.form.subtitle')}</p>
                </div>
                <button
                  onClick={resetForm}
                  className="p-2 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-medium text-slate-500 ml-1">
                    {t('paymentMethods.form.name')}
                  </label>
                  <input
                    type="text"
                    value={formData.method_name}
                    onChange={(e) => setFormData(prev => ({ ...prev, method_name: e.target.value }))}
                    placeholder={t('paymentMethods.form.namePlaceholder')}
                    className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-white placeholder-slate-600 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all font-medium"
                    required
                    autoFocus
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-xs font-medium text-slate-500 ml-1">
                    {t('paymentMethods.form.type')}
                  </label>
                  <select
                    value={formData.method_type}
                    onChange={(e) => setFormData(prev => ({ ...prev, method_type: e.target.value as any }))}
                    className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-2xl text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all font-medium appearance-none cursor-pointer"
                    required
                  >
                    <option value="cash">≡ƒÆ╡ Efectivo (Cash)</option>
                    <option value="check">Γ£ì∩╕Å Cheque (Check)</option>
                    <option value="credit_card">≡ƒÆ│ Tarjeta (Card)</option>
                    <option value="bank_transfer">≡ƒÅª Transferencia (ACH/Zelle)</option>
                    <option value="other">ΓÜÖ∩╕Å Otro (Other)</option>
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div
                    onClick={() => setFormData(prev => ({ ...prev, is_active: !prev.is_active }))}
                    className={`p-4 rounded-2xl border cursor-pointer transition-all flex items-center justify-between ${formData.is_active ? 'bg-blue-500/10 border-blue-500/30' : 'bg-slate-950 border-slate-800'}`}
                  >
                    <span className={`text-sm font-bold ${formData.is_active ? 'text-blue-400' : 'text-slate-500'}`}>{t('paymentMethods.form.enabled')}</span>
                    <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${formData.is_active ? 'border-blue-400 bg-blue-400' : 'border-slate-700'}`}>
                      {formData.is_active && <Check className="w-3 h-3 text-slate-950 font-black" />}
                    </div>
                  </div>

                  <div
                    onClick={() => setFormData(prev => ({ ...prev, requires_reference: !prev.requires_reference }))}
                    className={`p-4 rounded-2xl border cursor-pointer transition-all flex items-center justify-between ${formData.requires_reference ? 'bg-blue-500/10 border-blue-500/30' : 'bg-slate-950 border-slate-800'}`}
                  >
                    <span className={`text-sm font-bold ${formData.requires_reference ? 'text-blue-400' : 'text-slate-500'}`}>{t('paymentMethods.form.requiresRef')}</span>
                    <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${formData.requires_reference ? 'border-blue-400 bg-blue-400' : 'border-slate-700'}`}>
                      {formData.requires_reference && <Check className="w-3 h-3 text-slate-950 font-black" />}
                    </div>
                  </div>
                </div>

                <div className="flex gap-3 pt-6">
                  <button
                    type="button"
                    onClick={resetForm}
                    className="flex-1 py-3 bg-slate-800 text-slate-300 rounded-2xl font-bold hover:bg-slate-700 transition-colors"
                  >
                    {t('common.discard')}
                  </button>
                  <button
                    type="submit"
                    disabled={isLoading}
                    className="flex-[2] py-3 bg-blue-600 text-white rounded-2xl font-black hover:bg-blue-700 transition-all shadow-lg shadow-blue-900/40 disabled:opacity-50"
                  >
                    {isLoading ? t('common.saving') : editingMethod ? t('common.saveChanges') : t('paymentMethods.form.confirm')}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import {
  ArrowLeft,
  Edit,
  Package,
  DollarSign,
  Tag,
  Truck,
  BarChart3,
  AlertTriangle,
  CheckCircle,
  Hash,
  Calendar,
  FileText,
  Shield,
  Clock
} from 'lucide-react';
import { Product } from '@/database/simple-db';

interface ProductDetailViewProps {
  product: Product;
  onBack: () => void;
  onEdit: (product: Product) => void;
  onDelete?: () => Promise<void>;
  onNavigateToKardex?: (productId: number) => void;
}

export const ProductDetailView: React.FC<ProductDetailViewProps> = ({
  product,
  onBack,
  onEdit,
  onNavigateToKardex
}) => {
  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(price);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getStockStatus = () => {
    if (product.is_service) return null;

    if (product.stock_quantity === 0) {
      return { status: 'out', label: 'Sin Stock', color: 'text-red-400', bgColor: 'bg-red-900/20', icon: AlertTriangle };
    } else if (product.stock_quantity <= product.reorder_point) {
      return { status: 'low', label: 'Stock Bajo', color: 'text-yellow-400', bgColor: 'bg-yellow-900/20', icon: AlertTriangle };
    } else {
      return { status: 'ok', label: 'Stock OK', color: 'text-green-400', bgColor: 'bg-green-900/20', icon: CheckCircle };
    }
  };

  const stockStatus = getStockStatus();

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button
            onClick={onBack}
            className="text-slate-500 hover:text-white transition-colors"
          >
            <ArrowLeft className="w-6 h-6" />
          </button>
          <div>
            <h1 className="text-2xl font-black tracking-tight text-white">{product.name}</h1>
            <p className="text-slate-500">SKU: {product.sku}</p>
          </div>
        </div>
        <div className="flex gap-2">
          {onNavigateToKardex && !product.is_service && (
            <button
              onClick={() => onNavigateToKardex(product.id)}
              className="bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-lg flex items-center space-x-2 transition-colors border border-slate-600"
            >
              <FileText className="w-4 h-4" />
              <span>Ver Kardex</span>
            </button>
          )}
          <button
            onClick={() => onEdit(product)}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center space-x-2 transition-colors"
          >
            <Edit className="w-4 h-4" />
            <span>Editar</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Informaci├│n Principal */}
        <div className="lg:col-span-2 space-y-6">
          {/* Informaci├│n B├ísica */}
          <div className="bg-white/10 rounded-lg p-6">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
              <Package className="w-5 h-5 mr-2" />
              Informaci├│n B├ísica
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Tipo</label>
                <div className="flex items-center">
                  {product.is_service ? (
                    <>
                      <Tag className="w-4 h-4 text-purple-400 mr-2" />
                      <span className="text-white">Servicio</span>
                    </>
                  ) : (
                    <>
                      <Package className="w-4 h-4 text-blue-400 mr-2" />
                      <span className="text-white">Producto F├¡sico</span>
                    </>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Categor├¡a</label>
                <p className="text-white">{product.category?.name || 'Sin categor├¡a'}</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Unidad de Medida</label>
                <p className="text-white capitalize">{product.unit_of_measure}</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Estado</label>
                <div className="flex items-center">
                  {product.active ? (
                    <>
                      <CheckCircle className="w-4 h-4 text-green-400 mr-2" />
                      <span className="text-green-400">Activo</span>
                    </>
                  ) : (
                    <>
                      <AlertTriangle className="w-4 h-4 text-slate-500 mr-2" />
                      <span className="text-slate-500">Inactivo</span>
                    </>
                  )}
                </div>
              </div>
            </div>

            {product.description && (
              <div className="mt-6">
                <label className="block text-sm font-medium text-slate-500 mb-2">Descripci├│n</label>
                <p className="text-white bg-white/5 rounded-lg p-3">{product.description}</p>
              </div>
            )}
          </div>

          {/* Precios */}
          <div className="bg-white/10 rounded-lg p-6">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
              <DollarSign className="w-5 h-5 mr-2" />
              Precios
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Precio de Venta</label>
                <p className="text-2xl font-black tracking-tight text-green-400">{formatPrice(product.price)}</p>
              </div>

              {product.cost && product.cost > 0 && (
                <div>
                  <label className="block text-sm font-medium text-slate-500 mb-1">Costo</label>
                  <p className="text-xl font-semibold text-white">{formatPrice(product.cost)}</p>
                  <p className="text-sm text-slate-500">
                    Margen: {((product.price - product.cost) / product.price * 100).toFixed(1)}%
                  </p>
                </div>
              )}
            </div>

            {/* Informaci├│n de impuestos */}
            <div className="mt-6 p-4 bg-white/5 rounded-lg">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-white font-medium">
                    {product.taxable ? 'Producto Gravable' : 'Producto Exento de Impuestos'}
                  </p>
                  {product.taxable && product.tax_rate && (
                    <p className="text-sm text-slate-500">
                      Tasa espec├¡fica: {product.tax_rate}%
                    </p>
                  )}
                  {product.taxable && !product.tax_rate && (
                    <p className="text-sm text-slate-500">
                      Usa tasa por defecto seg├║n condado del cliente
                    </p>
                  )}
                </div>
                <div className={`w-3 h-3 rounded-full ${product.taxable ? 'bg-green-400' : 'bg-gray-400'}`}></div>
              </div>
            </div>
          </div>

          {/* Inventario (solo para productos f├¡sicos) */}
          {!product.is_service && (
            <div className="bg-white/10 rounded-lg p-6">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
                <BarChart3 className="w-5 h-5 mr-2" />
                Inventario
              </h2>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                <div className="bg-white/5 rounded-lg p-4">
                  <p className="text-sm text-slate-500">Stock Actual</p>
                  <p className="text-2xl font-black tracking-tight text-white">{product.stock_quantity}</p>
                  <p className="text-xs text-slate-500">{product.unit_of_measure}</p>
                </div>

                <div className="bg-white/5 rounded-lg p-4">
                  <p className="text-sm text-slate-500">Stock M├¡nimo</p>
                  <p className="text-xl font-semibold text-white">{product.min_stock_level}</p>
                </div>

                <div className="bg-white/5 rounded-lg p-4">
                  <p className="text-sm text-slate-500">Stock M├íximo</p>
                  <p className="text-xl font-semibold text-white">{product.max_stock_level}</p>
                </div>

                <div className="bg-white/5 rounded-lg p-4">
                  <p className="text-sm text-slate-500">Punto Reorden</p>
                  <p className="text-xl font-semibold text-white">{product.reorder_point}</p>
                </div>
              </div>

              {stockStatus && (
                <div className={`p-4 rounded-lg ${stockStatus.bgColor} border border-opacity-20`}>
                  <div className="flex items-center">
                    <stockStatus.icon className={`w-5 h-5 ${stockStatus.color} mr-2`} />
                    <span className={`font-medium ${stockStatus.color}`}>
                      {stockStatus.label}
                    </span>
                  </div>
                  {stockStatus.status === 'low' && (
                    <p className="text-sm text-slate-400 mt-1">
                      Se recomienda reabastecer el inventario
                    </p>
                  )}
                  {stockStatus.status === 'out' && (
                    <p className="text-sm text-slate-400 mt-1">
                      Producto sin stock disponible
                    </p>
                  )}
                </div>
              )}

              {/* Informaci├│n f├¡sica */}
              {(product.weight || product.dimensions || product.barcode) && (
                <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
                  {product.weight && (
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Peso</label>
                      <p className="text-white">{product.weight} kg</p>
                    </div>
                  )}

                  {product.dimensions && (
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">Dimensiones</label>
                      <p className="text-white">{product.dimensions}</p>
                    </div>
                  )}

                  {product.barcode && (
                    <div>
                      <label className="block text-sm font-medium text-slate-500 mb-1">C├│digo de Barras</label>
                      <p className="text-white font-mono">{product.barcode}</p>
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          {/* Informaci├│n de servicio */}
          {product.is_service && product.service_duration && (
            <div className="bg-white/10 rounded-lg p-6">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
                <Clock className="w-5 h-5 mr-2" />
                Informaci├│n del Servicio
              </h2>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Duraci├│n</label>
                <p className="text-white">
                  {product.service_duration} minutos
                  {product.service_duration >= 60 && (
                    <span className="text-slate-500 ml-2">
                      ({Math.floor(product.service_duration / 60)}h {product.service_duration % 60}m)
                    </span>
                  )}
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Panel Lateral */}
        <div className="space-y-6">
          {/* Informaci├│n del Proveedor */}
          {product.supplier && (
            <div className="bg-white/10 rounded-lg p-6">
              <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                <Truck className="w-5 h-5 mr-2" />
                Proveedor
              </h3>
              <p className="text-white">{product.supplier.name}</p>
            </div>
          )}

          {/* Garant├¡a */}
          {product.warranty_period && (
            <div className="bg-white/10 rounded-lg p-6">
              <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                <Shield className="w-5 h-5 mr-2" />
                Garant├¡a
              </h3>
              <p className="text-white">
                {product.warranty_period} d├¡as
                {product.warranty_period >= 365 && (
                  <span className="text-slate-500 ml-2">
                    ({Math.floor(product.warranty_period / 365)} a├▒o{Math.floor(product.warranty_period / 365) > 1 ? 's' : ''})
                  </span>
                )}
              </p>
            </div>
          )}

          {/* Metadatos */}
          <div className="bg-white/10 rounded-lg p-6">
            <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
              <Calendar className="w-5 h-5 mr-2" />
              Informaci├│n del Sistema
            </h3>

            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">Creado</label>
                <p className="text-white text-sm">{formatDate(product.created_at)}</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">├Ültima Actualizaci├│n</label>
                <p className="text-white text-sm">{formatDate(product.updated_at)}</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-1">ID del Producto</label>
                <p className="text-white font-mono text-sm">#{product.id}</p>
              </div>
            </div>
          </div>

          {/* Notas */}
          {product.notes && (
            <div className="bg-white/10 rounded-lg p-6">
              <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                <FileText className="w-5 h-5 mr-2" />
                Notas
              </h3>
              <p className="text-slate-400 text-sm whitespace-pre-wrap">{product.notes}</p>
            </div>
          )}

          {/* Imagen del producto */}
          {product.image_path && (
            <div className="bg-white/10 rounded-lg p-6">
              <h3 className="text-lg font-semibold text-white mb-4">Imagen</h3>
              <div className="bg-white/5 rounded-lg p-4 text-center">
                <p className="text-slate-500 text-sm">Ruta de imagen:</p>
                <p className="text-white text-sm font-mono break-all">{product.image_path}</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  XCircle, Package, DollarSign, Hash, Tag, Truck, BarChart3,
  AlertTriangle, ShieldCheck, Zap, Cpu, Sparkles, Box, Server,
  Layers, Settings, Info, Maximize2, Save, Plus
} from 'lucide-react';
import { Product, ProductCategory, Supplier, getProductCategories, getSuppliers } from '@/database/simple-db';

interface ProductFormProps {
  onSubmit: (productData: Omit<Product, 'id' | 'created_at' | 'updated_at'>) => void;
  onCancel: () => void;
  initialData?: Product;
  isEditing?: boolean;
  categories?: ProductCategory[];
}

export const ProductForm: React.FC<ProductFormProps> = ({
  onSubmit,
  onCancel,
  initialData,
  isEditing = false
}) => {
  const [categories, setCategories] = useState<ProductCategory[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [activeTab, setActiveTab] = useState<'basic' | 'inventory' | 'advanced'>('basic');

  const [formData, setFormData] = useState({
    sku: initialData?.sku || '',
    name: initialData?.name || '',
    description: initialData?.description || '',
    price: initialData?.price || 0,
    cost: initialData?.cost || 0,
    category_id: initialData?.category_id || undefined,
    unit_of_measure: initialData?.unit_of_measure || 'unidad',
    taxable: initialData?.taxable ?? true,
    tax_rate: initialData?.tax_rate || undefined,
    stock_quantity: initialData?.stock_quantity || 0,
    min_stock_level: initialData?.min_stock_level || 0,
    max_stock_level: initialData?.max_stock_level || 100,
    reorder_point: initialData?.reorder_point || 10,
    supplier_id: initialData?.supplier_id || undefined,
    barcode: initialData?.barcode || '',
    image_path: initialData?.image_path || '',
    weight: initialData?.weight || undefined,
    dimensions: initialData?.dimensions || '',
    is_service: initialData?.is_service ?? false,
    service_duration: initialData?.service_duration || undefined,
    warranty_period: initialData?.warranty_period || undefined,
    notes: initialData?.notes || '',
    active: initialData?.active ?? true
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    setCategories(getProductCategories());
    setSuppliers(getSuppliers());
  }, []);

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};
    if (!formData.sku.trim()) newErrors.sku = 'SKU mandatorio';
    if (!formData.name.trim()) newErrors.name = 'Identificador mandatorio';
    if (formData.price < 0) newErrors.price = 'Valor negativo no permitido';
    if (formData.cost && formData.cost < 0) newErrors.cost = 'Costo negativo no permitido';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    const productData = { ...formData };
    if (formData.is_service) {
      productData.stock_quantity = 0;
      productData.min_stock_level = 0;
      productData.max_stock_level = 0;
      productData.reorder_point = 0;
      productData.weight = undefined;
      productData.dimensions = '';
      productData.barcode = '';
    } else {
      productData.service_duration = undefined;
    }

    onSubmit(productData);
  };

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const tabs = [
    { id: 'basic', label: 'B├ísico', icon: Info },
    { id: 'inventory', label: 'Matriz', icon: Layers },
    { id: 'advanced', label: 'Protocolos', icon: Settings }
  ];

  return (
    <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6">
      <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-5xl max-h-[92vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
        <div className="absolute top-0 right-0 w-96 h-96 bg-white/5 blur-[120px] pointer-events-none group-hover:bg-white/10 transition-all duration-700"></div>

        {/* Header */}
        <header className="flex items-center justify-between p-10 relative z-10">
          <div className="flex items-center gap-6">
            <div className="text-emerald-500">
              {isEditing ? <Cpu className="w-8 h-8" /> : <Sparkles className="w-8 h-8" />}
            </div>
            <div>
              <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                {isEditing ? 'Actualizar Ficha de Activo' : 'Sincronizar Nuevo Activo'}
              </h2>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-2 flex items-center gap-2">
                <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" /> Registro Central de Inventario v4.2
              </p>
            </div>
          </div>
          <button onClick={onCancel} className="p-3 bg-slate-950/50 border border-slate-800 rounded-xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95">
            <XCircle className="w-6 h-6" />
          </button>
        </header>

        {/* Tab Selector */}
        <div className="flex px-10 border-b border-slate-800/50 bg-slate-950/20">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-3 px-8 py-5 text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === tab.id ? 'text-emerald-400' : 'text-slate-500 hover:text-white'
                }`}
            >
              <tab.icon className="w-4 h-4" />
              <span>{tab.label}</span>
              {activeTab === tab.id && <div className="absolute bottom-0 left-0 w-full h-1 bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>}
            </button>
          ))}
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-hidden flex flex-col">
          <div className="flex-1 overflow-y-auto p-10 custom-scrollbar">
            {activeTab === 'basic' && (
              <div className="space-y-12 animate-in slide-in-from-bottom-4 duration-500">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  {/* Type Selector */}
                  <div className="p-8 bg-slate-950/50 border border-slate-800/50 rounded-3xl space-y-4">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">Naturaleza del Activo</label>
                    <div className="flex gap-4">
                      <TypeButton
                        active={!formData.is_service}
                        onClick={() => handleInputChange('is_service', false)}
                        icon={Box}
                        label="Producto F├¡sico"
                        color="emerald"
                      />
                      <TypeButton
                        active={formData.is_service}
                        onClick={() => handleInputChange('is_service', true)}
                        icon={Server}
                        label="Servicio / Digital"
                        color="rose"
                      />
                    </div>
                  </div>

                  <PremiumInput label="SKU / Hash" icon={Hash} value={formData.sku} error={errors.sku} onChange={(v: any) => handleInputChange('sku', v)} placeholder="SKU-999-X" required />
                  <div className="md:col-span-2">
                    <PremiumInput label="Nombre del Activo" icon={Package} value={formData.name} error={errors.name} onChange={(v: any) => handleInputChange('name', v)} placeholder="NOMBRE DESCRIPTIVO" required />
                  </div>

                  <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 px-1">
                      <Layers className="w-3.5 h-3.5 text-emerald-500" /> Clasificaci├│n Matriz
                    </label>
                    <select
                      value={formData.category_id || ''}
                      onChange={(e) => handleInputChange('category_id', e.target.value ? parseInt(e.target.value) : undefined)}
                      className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-emerald-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px]"
                    >
                      <option value="">SIN CATEGOR├ìA</option>
                      {categories.map((c) => <option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
                    </select>
                  </div>

                  <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 px-1">
                      <Zap className="w-3.5 h-3.5 text-emerald-500" /> Unidad de Control
                    </label>
                    <select
                      value={formData.unit_of_measure}
                      onChange={(e) => handleInputChange('unit_of_measure', e.target.value)}
                      className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-emerald-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px]"
                    >
                      {['unidad', 'pieza', 'kg', 'litro', 'metro', 'caja', 'paquete', 'hora', 'servicio'].map(u => (
                        <option key={u} value={u}>{u.toUpperCase()}</option>
                      ))}
                    </select>
                  </div>

                  <PremiumInput label="Precio Venta (Unit)" icon={DollarSign} value={formData.price.toString()} error={errors.price} onChange={(v: any) => handleInputChange('price', parseFloat(v) || 0)} type="number" />
                  <PremiumInput label="Costo Adquisici├│n" icon={DollarSign} value={formData.cost.toString()} error={errors.cost} onChange={(v: any) => handleInputChange('cost', parseFloat(v) || 0)} type="number" />
                </div>
              </div>
            )}

            {activeTab === 'inventory' && (
              <div className="space-y-10 animate-in slide-in-from-bottom-4 duration-500">
                {formData.is_service ? (
                  <div className="p-16 bg-blue-950/10 border-2 border-dashed border-blue-500/20 rounded-[3rem] text-center">
                    <Zap className="w-16 h-16 text-blue-500 mx-auto mb-6 animate-pulse" />
                    <h4 className="text-2xl font-black text-white uppercase tracking-tighter">Activo Intangible Detectado</h4>
                    <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.3em] mt-2">Los servicios no requieren m├⌐tricas de stock f├¡sico.</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                    <PremiumInput label="Stock Actual" icon={Box} value={formData.stock_quantity.toString()} onChange={(v: any) => handleInputChange('stock_quantity', parseInt(v) || 0)} type="number" />
                    <PremiumInput label="M├¡nimo Seguridad" icon={AlertTriangle} value={formData.min_stock_level.toString()} onChange={(v: any) => handleInputChange('min_stock_level', parseInt(v) || 0)} type="number" />
                    <PremiumInput label="Punto de Reorden" icon={Zap} value={formData.reorder_point.toString()} onChange={(v: any) => handleInputChange('reorder_point', parseInt(v) || 0)} type="number" />
                    <PremiumInput label="M├íximo Permitido" icon={Maximize2} value={formData.max_stock_level.toString()} onChange={(v: any) => handleInputChange('max_stock_level', parseInt(v) || 0)} type="number" />

                    <div className="md:col-span-2 space-y-3">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 px-1">
                        <Truck className="w-3.5 h-3.5 text-emerald-500" /> Proveedor Primario
                      </label>
                      <select
                        value={formData.supplier_id || ''}
                        onChange={(e) => handleInputChange('supplier_id', e.target.value ? parseInt(e.target.value) : undefined)}
                        className="w-full bg-slate-950/50 text-white px-6 py-4 rounded-2xl border border-slate-800/50 focus:border-emerald-500/50 focus:outline-none font-bold uppercase tracking-widest text-[9px]"
                      >
                        <option value="">SELECCIONAR PROVEEDOR</option>
                        {suppliers.map((s) => <option key={s.id} value={s.id}>{s.name.toUpperCase()}</option>)}
                      </select>
                    </div>

                    <div className="md:col-span-2">
                      <PremiumInput label="C├│digo EAN / Barras" icon={Hash} value={formData.barcode} onChange={(v: any) => handleInputChange('barcode', v)} placeholder="0000000000" />
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'advanced' && (
              <div className="space-y-10 animate-in slide-in-from-bottom-4 duration-500">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <PremiumInput label="Garant├¡a (D├¡as)" icon={ShieldCheck} value={formData.warranty_period?.toString() || ''} onChange={(v: any) => handleInputChange('warranty_period', parseInt(v) || undefined)} type="number" />
                  {formData.is_service && <PremiumInput label="Duraci├│n (Minutos)" icon={Zap} value={formData.service_duration?.toString() || ''} onChange={(v: any) => handleInputChange('service_duration', parseInt(v) || undefined)} type="number" />}

                  <div className="md:col-span-2 space-y-3">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 px-1">
                      <Info className="w-3.5 h-3.5 text-emerald-500" /> Notas T├⌐cnicas
                    </label>
                    <textarea
                      value={formData.notes}
                      onChange={(e) => handleInputChange('notes', e.target.value)}
                      rows={4}
                      className="w-full bg-slate-950/50 text-white px-8 py-6 rounded-[2rem] border border-slate-800/50 focus:border-emerald-500/50 focus:outline-none font-medium text-sm placeholder:text-slate-800"
                      placeholder="Informaci├│n adicional para auditor├¡a..."
                    />
                  </div>
                </div>

                <div className="flex items-center gap-6 p-8 bg-slate-950 border border-slate-800 rounded-3xl">
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      id="taxable"
                      checked={formData.taxable}
                      onChange={(e) => handleInputChange('taxable', e.target.checked)}
                      className="w-5 h-5 rounded border-slate-800 bg-slate-900 text-emerald-600 focus:ring-emerald-500/20"
                    />
                    <label htmlFor="taxable" className="text-xs font-black text-white uppercase tracking-widest">Activo Gravable (Impuestos)</label>
                  </div>
                  <div className="flex items-center gap-3 border-l border-slate-800 pl-6">
                    <input
                      type="checkbox"
                      id="active"
                      checked={formData.active}
                      onChange={(e) => handleInputChange('active', e.target.checked)}
                      className="w-5 h-5 rounded border-slate-800 bg-slate-900 text-blue-600 focus:ring-blue-500/20"
                    />
                    <label htmlFor="active" className="text-xs font-black text-white uppercase tracking-widest">Visibilidad en Cat├ílogo</label>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Footer Actions */}
          <footer className="p-10 border-t border-slate-800 bg-slate-950/50 relative z-10 flex items-center justify-between">
            <div className="hidden md:flex items-center gap-3 text-slate-500">
              <ShieldCheck className="w-5 h-5 text-emerald-500" />
              <span className="text-[9px] font-black uppercase tracking-[0.2em]">Sincronizaci├│n inmutable con el repositorio de activos ALPHA.</span>
            </div>

            <div className="flex gap-6 w-full md:w-auto">
              <button type="button" onClick={onCancel} className="flex-1 md:flex-none px-6 py-2.5 bg-slate-900 border border-slate-800 text-slate-400 rounded-xl font-bold uppercase tracking-widest text-[10px] hover:bg-slate-800 transition-all active:scale-95">
