                  <div className="flex gap-2">
                    <button onClick={() => onView(supplier)} className="p-3 bg-slate-950 border border-slate-800 rounded-xl text-emerald-500 hover:bg-emerald-500 hover:text-white transition-all shadow-sm">
                      <Eye className="w-4 h-4" />
                    </button>
                    <button onClick={() => onEdit(supplier)} className="p-3 bg-slate-950 border border-slate-800 rounded-xl text-blue-500 hover:bg-blue-500 hover:text-white transition-all shadow-sm">
                      <Edit className="w-4 h-4" />
                    </button>
                    <button onClick={() => handleDelete(supplier)} className="p-3 bg-slate-950 border border-slate-800 rounded-xl text-rose-500 hover:bg-rose-500 hover:text-white transition-all shadow-sm">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 pt-6 border-t border-slate-800/50">
                  {supplier.business_name && (
                    <div className="text-xs font-black text-white uppercase tracking-tighter bg-slate-950/50 px-3 py-2 rounded-xl border border-slate-800">
                      {supplier.business_name}
                    </div>
                  )}

                  <div className="flex flex-col gap-3">
                    {supplier.email && (
                      <div className="flex items-center text-slate-400">
                        <Mail className="w-3.5 h-3.5 mr-3 text-orange-500/60" />
                        <span className="text-[10px] font-black uppercase tracking-widest truncate">{supplier.email}</span>
                      </div>
                    )}
                    {supplier.phone && (
                      <div className="flex items-center text-slate-400">
                        <Phone className="w-3.5 h-3.5 mr-3 text-orange-500/60" />
                        <span className="text-[10px] font-black font-mono tracking-widest">{supplier.phone}</span>
                      </div>
                    )}
                  </div>

                  <div className="flex items-center justify-between pt-2">
                    <div className="flex items-center text-slate-400">
                      <MapPin className="w-3.5 h-3.5 mr-3 text-orange-500/60" />
                      <span className="text-[9px] font-black text-white bg-orange-600/20 px-3 py-1 rounded-[0.5rem] border border-orange-500/30 uppercase tracking-[0.1em]">
                        {supplier.florida_county}
                      </span>
                    </div>
                    {supplier.business_type && (
                      <span className="text-[8px] font-black text-slate-600 uppercase tracking-[0.2em]">{supplier.business_type}</span>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Analytics Footer */}
      {suppliers.length > 0 && (
        <div className="bg-slate-950 border border-white/5 p-12 rounded-[3.5rem] shadow-3xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-96 h-96 bg-orange-600/5 blur-[120px] -mr-48 -mt-48 group-hover:bg-orange-600/10 transition-all duration-700"></div>

          <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-12">
            <div className="flex items-center gap-6">
              <div className="p-5 bg-orange-600/10 rounded-[2rem] border border-orange-500/20 shadow-lg">
                <Activity className="w-10 h-10 text-orange-500" />
              </div>
              <div>
                <h4 className="text-2xl font-black text-white uppercase tracking-tighter">{t('supplierList.analytics.title')}</h4>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">{t('supplierList.analytics.subtitle')}</p>
              </div>
            </div>

            <div className="grid grid-cols-2 lg:grid-cols-4 gap-12 w-full md:w-auto">
              <IntelMiniStat value={suppliers.length} label={t('supplierList.analytics.totalAllies')} color="orange" />
              <IntelMiniStat value={suppliers.filter(s => s.email).length} label={t('supplierList.analytics.linkPorts')} color="emerald" />
              <IntelMiniStat value={suppliers.filter(s => s.phone).length} label={t('supplierList.analytics.activeChannels')} color="amber" />
              <IntelMiniStat value={uniqueCounties.length} label={t('supplierList.analytics.jurisZones')} color="rose" />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const IntelMiniStat = ({ value, label, color }: any) => {
  const colors: any = {
    orange: 'text-orange-500',
    emerald: 'text-emerald-500',
    amber: 'text-amber-500',
    rose: 'text-rose-500',
  };

  return (
    <div className="text-center md:text-left px-4">
      <div className={`text-4xl font-black ${colors[color]} font-mono mb-1 leading-none`}>{value}</div>
      <div className="text-[8px] font-black text-slate-500 uppercase tracking-[0.3em]">{label}</div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CreditCard, Calendar, DollarSign, FileText, Search, Filter, Plus, Check, X, Building2 } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { Bill, Supplier, getPaymentMethods, PaymentMethod, addPayment } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';

interface SupplierPayment {
  id: number;
  bill_id: number;
  supplier_id: number;
  amount: number;
  payment_date: string;
  payment_method: string;
  reference: string;
  notes?: string;
  created_at: string;
}

interface SupplierPaymentsProps {
  bills: Bill[];
  suppliers: Supplier[];
  onPaymentCreated: () => void;
}

export const SupplierPayments: React.FC<SupplierPaymentsProps> = ({
  bills,
  suppliers,
  onPaymentCreated
}) => {
  const { t } = useLocale();
  const { user } = useAuth();
  const [payments, setPayments] = useState<SupplierPayment[]>([]);
  const [pendingBills, setPendingBills] = useState<Bill[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([]);
  const [showPaymentForm, setShowPaymentForm] = useState(false);
  const [selectedBill, setSelectedBill] = useState<Bill | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'pending' | 'paid'>('pending');
  const [isLoading, setIsLoading] = useState(false);

  const [paymentForm, setPaymentForm] = useState({
    amount: '',
    payment_date: new Date().toISOString().split('T')[0],
    payment_method: '',
    reference: '',
    notes: ''
  });

  useEffect(() => {
    loadPendingBills();
    loadPayments();
    loadPaymentMethods();
  }, [bills]);

  const loadPaymentMethods = () => {
    try {
      const methods = getPaymentMethods();
      setPaymentMethods(methods);

      // Si hay m├⌐todos disponibles, seleccionar el primero por defecto
      if (methods.length > 0 && !paymentForm.payment_method) {
        setPaymentForm(prev => ({ ...prev, payment_method: methods[0].method_name }));
      }
    } catch (error) {
      console.error('Error loading payment methods:', error);
    }
  };

  const loadPendingBills = () => {
    // Filtrar facturas pendientes (asumiendo que las pagadas tienen status 'paid')
    const pending = bills.filter(bill =>
      bill.status !== 'paid'
    );
    setPendingBills(pending);
  };

  const loadPayments = () => {
    // En una implementaci├│n real, esto vendr├¡a de la base de datos
    // Por ahora simulamos algunos pagos
    const mockPayments: SupplierPayment[] = [];
    setPayments(mockPayments);
  };

  const getSupplierName = (supplierId: number) => {
    const supplier = suppliers.find(s => s.id === supplierId);
    return supplier ? supplier.name : t('supplierPayments.unknownSupplier');
  };

  const filteredBills = pendingBills.filter(bill => {
    const supplierName = getSupplierName(bill.supplier_id).toLowerCase();
    const matchesSearch = supplierName.includes(searchTerm.toLowerCase()) ||
      bill.bill_number.toLowerCase().includes(searchTerm.toLowerCase());

    if (filterStatus === 'all') return matchesSearch;
    if (filterStatus === 'pending') return matchesSearch && bill.status !== 'paid';
    if (filterStatus === 'paid') return matchesSearch && bill.status === 'paid';

    return matchesSearch;
  });

  const handlePaymentSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBill) return;

    setIsLoading(true);
    try {
      // Map form data to database SupplierPayment interface
      const paymentData: Partial<any> = {
        supplier_id: selectedBill.supplier_id,
        bill_id: selectedBill.id,
        amount: parseFloat(paymentForm.amount),
        payment_date: paymentForm.payment_date,
        payment_method: paymentForm.payment_method as any,
        reference_number: paymentForm.reference,
        notes: paymentForm.notes
      };

      const result = await addPayment(paymentData, user?.id || 1);

      if (!result.success) {
        throw new Error(result.message);
      }

      // Update local state with the created payment
      const payment: SupplierPayment = {
        id: result.paymentId || Date.now(),
        bill_id: selectedBill.id,
        supplier_id: selectedBill.supplier_id,
        amount: parseFloat(paymentForm.amount),
        payment_date: paymentForm.payment_date,
        payment_method: paymentForm.payment_method,
        reference: paymentForm.reference,
        notes: paymentForm.notes,
        created_at: new Date().toISOString()
      };

      // Actualizar el estado de la factura
      const { updateBill, forceSaveDB } = await import('../database/simple-db');
      await updateBill(selectedBill.id, { status: 'paid' } as any);
      await forceSaveDB();

      setPayments(prev => [...prev, payment]);
      setShowPaymentForm(false);
      setSelectedBill(null);
      setPaymentForm({
        amount: '',
        payment_date: new Date().toISOString().split('T')[0],
        payment_method: paymentMethods.length > 0 ? paymentMethods[0].method_name : '',
        reference: '',
        notes: ''
      });

      onPaymentCreated();
    } catch (error) {
      console.error('Error creating payment:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handlePayBill = (bill: Bill) => {
    setSelectedBill(bill);
    setPaymentForm(prev => ({
      ...prev,
      amount: bill.total_amount.toString(),
      payment_method: paymentMethods.length > 0 ? paymentMethods[0].method_name : ''
    }));
    setShowPaymentForm(true);
  };

  const calculateDaysUntilDue = (billDate: string) => {
    const dueDate = new Date(billDate);
    dueDate.setDate(dueDate.getDate() + 30); // Asumiendo 30 d├¡as de plazo
    const today = new Date();
    const diffTime = dueDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-black tracking-tight text-white">{t('supplierPayments.title')}</h2>
          <p className="text-slate-400">{t('supplierPayments.subtitle')}</p>
        </div>
      </div>

      {/* Filtros y b├║squeda */}
      <div className="bg-white/10 p-4 rounded-lg shadow-sm border border-white/10">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
              <input
                type="text"
                placeholder={t('supplierPayments.searchPlaceholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>
          </div>
          <div className="flex gap-2">
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
              className="px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="pending" style={{ color: 'black' }}>{t('supplierPayments.filter.pending')}</option>
              <option value="paid" style={{ color: 'black' }}>{t('supplierPayments.filter.paid')}</option>
              <option value="all" style={{ color: 'black' }}>{t('supplierPayments.filter.all')}</option>
            </select>
          </div>
        </div>
      </div>

      {/* Lista de facturas pendientes */}
      <div className="bg-white/10 rounded-lg shadow-sm border border-white/10">
        <div className="px-6 py-4 border-b border-white/10">
          <h3 className="text-lg font-black tracking-tight text-white">{t('supplierPayments.listTitle')}</h3>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-white/5">
              <tr>
                <th className="px-6 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 uppercase tracking-wider">
                  {t('supplierPayments.col.bill')}
                </th>
                <th className="px-6 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 uppercase tracking-wider">
                  {t('supplierPayments.col.supplier')}
                </th>
                <th className="px-6 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 uppercase tracking-wider">
                  {t('supplierPayments.col.date')}
                </th>
                <th className="px-6 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 uppercase tracking-wider">
                  {t('supplierPayments.col.amount')}
                </th>
                <th className="px-6 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 uppercase tracking-wider">
                  {t('supplierPayments.col.dueDate')}
                </th>
                <th className="px-6 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 uppercase tracking-wider">
                  {t('supplierPayments.col.actions')}
                </th>
              </tr>
            </thead>
            <tbody className="bg-white/10 divide-y divide-gray-700">
              {filteredBills.map((bill) => {
                const daysUntilDue = calculateDaysUntilDue(bill.issue_date);

                return (
                  <tr key={bill.id} className="hover:bg-white/5">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <FileText className="w-4 h-4 text-slate-500 mr-2" />
                        <span className="text-sm font-medium text-white">
                          {bill.bill_number}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <Building2 className="w-4 h-4 text-slate-500 mr-2" />
                        <span className="text-sm text-white">
                          {getSupplierName(bill.supplier_id)}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-400">
                      {new Date(bill.issue_date).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm font-medium text-white">
                        ${bill.total_amount.toFixed(2)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${daysUntilDue < 0
                        ? 'bg-red-100 text-red-800'
                        : daysUntilDue <= 7
                          ? 'bg-yellow-100 text-yellow-800'
                          : 'bg-green-100 text-green-800'
                        }`}>
                        {daysUntilDue < 0
                          ? t('supplierPayments.status.overdue', { days: Math.abs(daysUntilDue) })
                          : daysUntilDue === 0
                            ? t('supplierPayments.status.dueToday')
                            : t('supplierPayments.status.daysLeft', { days: daysUntilDue })
                        }
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <button
                        onClick={() => handlePayBill(bill)}
                        className="inline-flex items-center px-3 py-1 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                      >
                        <CreditCard className="w-4 h-4 mr-1" />
                        {t('supplierPayments.action.pay')}
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {filteredBills.length === 0 && (
            <div className="text-center py-8">
              <FileText className="mx-auto h-12 w-12 text-slate-500" />
              <h3 className="mt-2 text-sm font-medium text-white">{t('supplierPayments.empty.title')}</h3>
              <p className="mt-1 text-sm text-slate-400">
                {filterStatus === 'pending'
                  ? t('supplierPayments.empty.pending')
                  : t('supplierPayments.empty.filtered')
                }
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Modal de formulario de pago */}
      {showPaymentForm && selectedBill && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-96 shadow-lg rounded-md bg-white/10 border-white/10">
            <div className="mt-3">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-black tracking-tight text-white">
                  {t('paymentModal.title')}
                </h3>
                <button
                  onClick={() => setShowPaymentForm(false)}
                  className="text-slate-500 hover:text-slate-400"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="mb-4 p-3 bg-white/5 rounded-md">
                <p className="text-sm text-slate-400">
                  <strong className="text-white">{t('paymentModal.bill')}</strong> {selectedBill.bill_number}
                </p>
                <p className="text-sm text-slate-400">
                  <strong className="text-white">{t('paymentModal.supplier')}</strong> {getSupplierName(selectedBill.supplier_id)}
                </p>
                <p className="text-sm text-slate-400">
                  <strong className="text-white">{t('paymentModal.totalAmount')}</strong> ${selectedBill.total_amount.toFixed(2)}
                </p>
              </div>

              <form onSubmit={handlePaymentSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('paymentModal.paymentAmount')}
                  </label>
                  <div className="relative">
                    <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
                    <input
                      type="number"
                      step="0.01"
                      value={paymentForm.amount}
                      onChange={(e) => setPaymentForm(prev => ({ ...prev, amount: e.target.value }))}
                      className="w-full pl-10 pr-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('paymentModal.paymentDate')}
                  </label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
                    <input
                      type="date"
                      value={paymentForm.payment_date}
                      onChange={(e) => setPaymentForm(prev => ({ ...prev, payment_date: e.target.value }))}
                      className="w-full pl-10 pr-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('paymentModal.paymentMethod')}
                  </label>
                  <select
                    value={paymentForm.payment_method}
                    onChange={(e) => setPaymentForm(prev => ({ ...prev, payment_method: e.target.value }))}
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    required
                  >
                    <option value="" style={{ color: 'black' }}>{t('paymentModal.selectMethod')}</option>
                    {paymentMethods.map((method) => (
                      <option key={method.id} value={method.method_name} style={{ color: 'black' }}>
                        {method.method_name}
                      </option>
                    ))}
                  </select>
                  {paymentMethods.length === 0 && (
                    <p className="mt-1 text-sm text-red-400">
                      {t('paymentModal.noMethods')}
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('paymentModal.reference')}
                  </label>
                  <input
                    type="text"
                    value={paymentForm.reference}
                    onChange={(e) => setPaymentForm(prev => ({ ...prev, reference: e.target.value }))}
                    placeholder={t('paymentModal.referencePlaceholder')}
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('paymentModal.notes')}
                  </label>
                  <textarea
                    value={paymentForm.notes}
                    onChange={(e) => setPaymentForm(prev => ({ ...prev, notes: e.target.value }))}
                    rows={3}
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder={t('paymentModal.notesPlaceholder')}
                  />
                </div>

                <div className="flex justify-end space-x-3 pt-4">
                  <button
                    type="button"
                    onClick={() => setShowPaymentForm(false)}
                    className="px-4 py-2 border border-white/10 rounded-md text-sm font-medium text-slate-400 hover:bg-white/5 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                  >
                    {t('paymentModal.cancel')}
                  </button>
                  <button
                    type="submit"
                    disabled={isLoading}
                    className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50"
                  >
                    {isLoading ? t('paymentModal.processing') : t('paymentModal.submit')}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  AlertCircle, CheckCircle, Info, AlertTriangle, Bug,
  Filter, RefreshCw, Eye, EyeOff, Download, Trash2,
  Clock, User, Database, Shield, Activity
} from 'lucide-react';
import { logger, SystemLog, LogLevel, ErrorStats } from '../core/logging/SystemLogger';
import { useLocale } from '../i18n/useLocale';

export function SystemLogs() {
  const { t, language } = useLocale();
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [stats, setStats] = useState<ErrorStats | null>(null);
  const [filter, setFilter] = useState({
    level: 'ALL' as LogLevel | 'ALL',
    module: 'ALL',
    resolved: 'ALL',
    limit: 50
  });
  const [loading, setLoading] = useState(false);
  const [expandedLog, setExpandedLog] = useState<number | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(true);

  const loadLogs = async () => {
    setLoading(true);
    try {
      const filterParams: any = {};
      if (filter.level !== 'ALL') filterParams.level = filter.level;
      if (filter.module !== 'ALL') filterParams.module = filter.module;
      if (filter.resolved !== 'ALL') filterParams.resolved = filter.resolved === 'RESOLVED';
      filterParams.limit = filter.limit;

      const [logsData, statsData] = await Promise.all([
        logger.getLogs(filterParams),
        logger.getErrorStats()
      ]);

      setLogs(logsData);
      setStats(statsData);
    } catch (error) {
      console.error('Failed to load logs:', error);
      logger.error('SystemLogs', 'load_failed', t('systemLogs.loadingRecords'), null, error as Error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadLogs();

    if (autoRefresh) {
      const interval = setInterval(loadLogs, 30000); // Actualizar cada 30 segundos
      return () => clearInterval(interval);
    }
  }, [filter, autoRefresh]);

  const getLevelIcon = (level: LogLevel) => {
    switch (level) {
      case 'CRITICAL': return <AlertCircle className="h-4 w-4 text-red-600" />;
      case 'ERROR': return <AlertCircle className="h-4 w-4 text-red-500" />;
      case 'WARN': return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case 'INFO': return <Info className="h-4 w-4 text-blue-500" />;
      case 'DEBUG': return <Bug className="h-4 w-4 text-slate-600" />;
      default: return <Info className="h-4 w-4" />;
    }
  };

  const getLevelColor = (level: LogLevel) => {
    switch (level) {
      case 'CRITICAL': return 'bg-red-600 text-white';
      case 'ERROR': return 'bg-red-500 text-white';
      case 'WARN': return 'bg-yellow-500 text-white';
      case 'INFO': return 'bg-blue-500 text-white';
      case 'DEBUG': return 'bg-gray-500 text-white';
      default: return 'bg-gray-200';
    }
  };

  const getModuleIcon = (module: string) => {
    switch (module) {
      case 'Database': return <Database className="h-4 w-4" />;
      case 'CustomerModule':
      case 'InvoiceModule':
      case 'BillModule':
      case 'SupplierModule': return <Activity className="h-4 w-4" />;
      case 'SystemLogger': return <Shield className="h-4 w-4" />;
      default: return <Info className="h-4 w-4" />;
    }
  };

  const formatTimestamp = (timestamp: string) => {
    return new Date(timestamp).toLocaleString(language === 'es' ? 'es-ES' : 'en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const markAsResolved = async (logId: number) => {
    try {
      const success = await logger.markAsResolved(logId, 1);
      if (success) {
        loadLogs();
        logger.info('SystemLogs', 'mark_resolved', `Log ${logId} marcado como resuelto por usuario`);
      }
    } catch (error) {
      console.error('Failed to mark log as resolved:', error);
      logger.error('SystemLogs', 'mark_resolved_failed', 'Error al marcar log como resuelto', { logId }, error as Error);
    }
  };

  const exportLogs = () => {
    try {
      const csv = [
        ['ID', 'Timestamp', 'Level', 'Module', 'Action', 'Message', 'Resolved'],
        ...logs.map(log => [
          log.id,
          log.timestamp,
          log.level,
          log.module,
          log.action,
          log.message.replace(/,/g, ';'), // Escapar comas
          log.resolved ? 'Yes' : 'No'
        ])
      ].map(row => row.join(',')).join('\n');

      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `system_logs_${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      logger.info('SystemLogs', 'export_success', `Logs exportados: ${logs.length} registros`);
    } catch (error) {
      console.error('Failed to export logs:', error);
      logger.error('SystemLogs', 'export_failed', 'Error al exportar logs', null, error as Error);
    }
  };

  const clearOldLogs = async () => {
    if (!window.confirm(t('systemLogs.confirmClear'))) {
      return;
    }

    try {
      const deletedCount = await logger.clearOldLogs(30);
      loadLogs();
      logger.info('SystemLogs', 'cleanup_success', `Limpieza completada: ${deletedCount} logs eliminados`);
    } catch (error) {
      console.error('Failed to clear old logs:', error);
      logger.error('SystemLogs', 'cleanup_failed', 'Error al limpiar logs antiguos', null, error as Error);
    }
  };

  const getUniqueModules = () => {
    const modules = new Set(logs.map(log => log.module));
    return Array.from(modules).sort();
  };

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black tracking-tight text-white">{t('systemLogs.title')}</h1>
          <p className="text-slate-500">{t('systemLogs.subtitle')}</p>
        </div>
        <div className="flex items-center space-x-2">
          <label className="flex items-center space-x-2 text-sm text-slate-400">
            <input
              type="checkbox"
              checked={autoRefresh}
              onChange={(e) => setAutoRefresh(e.target.checked)}
              className="rounded"
            />
            <span>{t('systemLogs.autoRefresh')}</span>
          </label>
        </div>
      </div>

      {/* Estad├¡sticas */}
      {stats && (
        <div className="bg-white/10 rounded-lg p-6">
          <h2 className="text-lg font-semibold text-white mb-4">{t('systemLogs.systemStats')}</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-red-900/20 border border-red-700 p-4 rounded-lg">
              <div className="flex items-center space-x-2">
                <AlertCircle className="h-5 w-5 text-red-400" />
                <div>
                  <div className="text-2xl font-black tracking-tight text-red-400">{stats.totalErrors}</div>
                  <div className="text-sm text-red-300">{t('systemLogs.totalErrors')}</div>
                </div>
              </div>
            </div>

            <div className="bg-yellow-900/20 border border-yellow-700 p-4 rounded-lg">
              <div className="flex items-center space-x-2">
                <AlertTriangle className="h-5 w-5 text-yellow-400" />
                <div>
                  <div className="text-2xl font-black tracking-tight text-yellow-400">{stats.unresolved}</div>
                  <div className="text-sm text-yellow-300">{t('systemLogs.unresolved')}</div>
                </div>
              </div>
            </div>

            <div className="bg-orange-900/20 border border-orange-700 p-4 rounded-lg">
              <div className="flex items-center space-x-2">
                <Clock className="h-5 w-5 text-orange-400" />
                <div>
                  <div className="text-2xl font-black tracking-tight text-orange-400">{stats.last24Hours}</div>
                  <div className="text-sm text-orange-300">{t('systemLogs.last24Hours')}</div>
                </div>
              </div>
            </div>

            <div className="bg-purple-900/20 border border-purple-700 p-4 rounded-lg">
              <div className="flex items-center space-x-2">
                <AlertCircle className="h-5 w-5 text-purple-400" />
                <div>
                  <div className="text-2xl font-black tracking-tight text-purple-400">{stats.criticalCount}</div>
                  <div className="text-sm text-purple-300">{t('systemLogs.criticals')}</div>
                </div>
              </div>
            </div>
          </div>

          {/* Errores por m├│dulo */}
          {Object.keys(stats.byModule).length > 0 && (
            <div className="mt-6">
              <h3 className="text-md font-medium text-white mb-3">{t('systemLogs.errorsByModule')}</h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                {Object.entries(stats.byModule).map(([module, count]) => (
                  <div key={module} className="bg-white/5 p-2 rounded text-center">
                    <div className="text-lg font-bold text-white">{count}</div>
                    <div className="text-xs text-slate-400">{module}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Filtros */}
      <div className="bg-white/10 rounded-lg p-4">
        <div className="flex flex-wrap gap-4 items-center">
          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">{t('systemLogs.level')}</label>
            <select
              className="bg-white/5 border border-white/10 text-white rounded px-3 py-2 text-sm"
              value={filter.level}
              onChange={(e) => setFilter({ ...filter, level: e.target.value as LogLevel | 'ALL' })}
            >
              <option value="ALL">{t('systemLogs.levels.all')}</option>
              <option value="CRITICAL">{t('systemLogs.levels.critical')}</option>
              <option value="ERROR">{t('systemLogs.levels.error')}</option>
              <option value="WARN">{t('systemLogs.levels.warn')}</option>
              <option value="INFO">{t('systemLogs.levels.info')}</option>
              <option value="DEBUG">{t('systemLogs.levels.debug')}</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">{t('systemLogs.module')}</label>
            <select
              className="bg-white/5 border border-white/10 text-white rounded px-3 py-2 text-sm"
              value={filter.module}
              onChange={(e) => setFilter({ ...filter, module: e.target.value })}
            >
              <option value="ALL">{t('systemLogs.all')}</option>
              {getUniqueModules().map(module => (
                <option key={module} value={module}>{module}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">{t('systemLogs.status')}</label>
            <select
              className="bg-white/5 border border-white/10 text-white rounded px-3 py-2 text-sm"
              value={filter.resolved}
              onChange={(e) => setFilter({ ...filter, resolved: e.target.value })}
            >
              <option value="ALL">{t('systemLogs.statuses.all')}</option>
              <option value="UNRESOLVED">{t('systemLogs.statuses.unresolved')}</option>
              <option value="RESOLVED">{t('systemLogs.statuses.resolved')}</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">{t('systemLogs.limit')}</label>
            <select
              className="bg-white/5 border border-white/10 text-white rounded px-3 py-2 text-sm"
              value={filter.limit}
              onChange={(e) => setFilter({ ...filter, limit: parseInt(e.target.value) })}
            >
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
              <option value={200}>200</option>
            </select>
          </div>

          <div className="flex space-x-2 mt-6">
            <button
              onClick={loadLogs}
              disabled={loading}
              className="bg-blue-600 hover:bg-blue-700 disabled:bg-blue-800 text-white px-4 py-2 rounded-lg text-sm flex items-center space-x-2 transition-colors"
            >
              <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
              <span>{t('systemLogs.refresh')}</span>
            </button>

            <button
              onClick={exportLogs}
              className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm flex items-center space-x-2 transition-colors"
            >
              <Download className="h-4 w-4" />
              <span>{t('systemLogs.export')}</span>
            </button>

            <button
              onClick={clearOldLogs}
              className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg text-sm flex items-center space-x-2 transition-colors"
            >
              <Trash2 className="h-4 w-4" />
              <span>{t('systemLogs.clear')}</span>
            </button>
          </div>
        </div>
      </div>

      {/* Lista de Logs */}
      <div className="bg-white/10 rounded-lg">
        <div className="p-4 border-b border-white/10">
          <h2 className="text-lg font-semibold text-white">
            {t('systemLogs.systemRecords')} ({logs.length})
          </h2>
        </div>

        <div className="p-4">
          {loading ? (
            <div className="text-center py-8 text-slate-500">
              <RefreshCw className="h-8 w-8 animate-spin mx-auto mb-2" />
              {t('systemLogs.loadingRecords')}
            </div>
          ) : logs.length === 0 ? (
            <div className="text-center py-8 text-slate-600">
              {t('systemLogs.noRecordsMatch')}
            </div>
          ) : (
            <div className="space-y-2 max-h-[600px] overflow-y-auto">
              {logs.map((log) => (
                <div
                  key={log.id}
                  className={`border rounded-lg p-4 transition-colors ${log.level === 'CRITICAL' ? 'border-red-500 bg-red-900/10' :
                      log.level === 'ERROR' ? 'border-red-400 bg-red-900/5' :
                        log.level === 'WARN' ? 'border-yellow-400 bg-yellow-900/5' :
                          'border-white/10 hover:bg-white/5/50'
                    }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-center space-x-3">
                      {getLevelIcon(log.level)}
                      <span className={`px-2 py-1 rounded text-xs font-medium ${getLevelColor(log.level)}`}>
                        {log.level}
                      </span>
                      <div className="flex items-center space-x-2 text-sm text-slate-500">
                        {getModuleIcon(log.module)}
                        <span>{log.module}</span>
                        <span>ΓÇó</span>
                        <Clock className="h-3 w-3" />
                        <span>{formatTimestamp(log.timestamp)}</span>
                      </div>
                      {log.resolved && (
                        <span className="px-2 py-1 bg-green-900/20 border border-green-700 text-green-300 rounded text-xs flex items-center space-x-1">
                          <CheckCircle className="h-3 w-3" />
                          <span>{t('systemLogs.resolved')}</span>
                        </span>
                      )}
                    </div>

                    <div className="flex space-x-2">
                      {!log.resolved && (log.level === 'ERROR' || log.level === 'CRITICAL') && (
                        <button
                          onClick={() => markAsResolved(log.id)}
                          className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-xs transition-colors"
                        >
                          {t('systemLogs.resolve')}
                        </button>
                      )}
                      <button
                        onClick={() => setExpandedLog(expandedLog === log.id ? null : log.id)}
                        className="bg-gray-600 hover:bg-white/5 text-white px-3 py-1 rounded text-xs transition-colors"
                      >
                        {expandedLog === log.id ? <EyeOff className="h-3 w-3" /> : <Eye className="h-3 w-3" />}
                      </button>
                    </div>
                  </div>

                  <div className="mt-3">
                    <div className="font-medium text-white">
                      {log.action}
                    </div>
                    <div className="text-slate-400 mt-1">{log.message}</div>
                  </div>

                  {expandedLog === log.id && (
                    <div className="mt-4 space-y-3 border-t border-white/10 pt-3">
                      {log.data && (
                        <div>
                          <div className="text-sm font-medium text-slate-400 mb-1">Datos:</div>
                          <pre className="text-xs bg-slate-900 p-3 rounded overflow-x-auto text-slate-400 border border-white/10">
                            {log.data}
                          </pre>
                        </div>
                      )}

                      {log.stack_trace && (
                        <div>
                          <div className="text-sm font-medium text-slate-400 mb-1">Stack Trace:</div>
                          <pre className="text-xs bg-red-900/20 border border-red-700 p-3 rounded overflow-x-auto text-red-200">
                            {log.stack_trace}
                          </pre>
                        </div>
                      )}

                      <div className="text-xs text-slate-600 flex items-center space-x-4">
                        <span>ID: {log.id}</span>
                        <span>Usuario: {log.user_id}</span>
                        {log.session_id && <span>Sesi├│n: {log.session_id.slice(-8)}</span>}
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { MapPin, Save, Plus, Trash2, AlertCircle } from 'lucide-react';
import { getAllFloridaTaxRates, updateFloridaTaxRate } from '@/database/simple-db';
import { useLocale } from '../i18n/useLocale';
import toast from 'react-hot-toast';


interface CountyTaxRate {
    id?: string | number;
    county: string;
    surtaxRate: number; // Discretionary Sales Surtax (e.g., 0.01 for 1%)
    active: boolean;
}

// Initial data based on common Florida counties
const INITIAL_RATES: CountyTaxRate[] = [
    { id: '1', county: 'Miami-Dade', surtaxRate: 0.01, active: true },
    { id: '2', county: 'Broward', surtaxRate: 0.01, active: true },
    { id: '3', county: 'Palm Beach', surtaxRate: 0.01, active: true },
    { id: '4', county: 'Orange', surtaxRate: 0.005, active: true },
    { id: '5', county: 'Hillsborough', surtaxRate: 0.015, active: true },
];

export const TaxRates: React.FC = () => {
    const { t } = useLocale();
    const [rates, setRates] = useState<CountyTaxRate[]>(INITIAL_RATES);
    const [loading, setLoading] = useState<boolean>(true);

    useEffect(() => {
        const fetchRates = () => {
            const dbRates = getAllFloridaTaxRates();
            if (dbRates && dbRates.length > 0) {
                const mappedRates = dbRates.map((r, idx) => ({
                    id: r.id || idx,
                    county: r.county,
                    surtaxRate: r.discretionaryRate,
                    active: true
                }));
                setRates(mappedRates);
            }
            setLoading(false);
        };

        fetchRates();
    }, []);

    const handleRateChange = (id: string | number, newRate: number) => {
        setRates(rates.map(r => r.id === id ? { ...r, surtaxRate: newRate } : r));
    };

    const toggleActive = (id: string | number) => {
        setRates(rates.map(r => r.id === id ? { ...r, active: !r.active } : r));
    };

    const handleSaveAll = async () => {
        const loadingToast = toast.loading(t('taxRates.syncing'));
        try {
            for (const rate of rates) {
                if (rate.id !== undefined) {
                    const res = updateFloridaTaxRate(Number(rate.id), rate.surtaxRate);
                    if (!res.success) throw new Error(res.message);
                }
            }
            toast.success(t('taxRates.syncSuccess'), { id: loadingToast });
        } catch (error: any) {
            toast.error(`${t('common.error')}: ${error.message}`, { id: loadingToast });
        }
    };


    return (
        <div className="p-6 max-w-4xl mx-auto">
            <div className="bg-white dark:bg-white/10 rounded-lg shadow-md border border-gray-100 dark:border-white/10 overflow-hidden">
                <div className="p-6 border-b border-gray-100 dark:border-white/10 flex justify-between items-center bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-gray-800 dark:to-gray-800">
                    <div>
                        <h2 className="text-xl font-black tracking-tight text-gray-800 dark:text-white flex items-center gap-2">
                            <MapPin className="w-6 h-6 text-blue-600" />
                            {t('taxRates.title')}
                        </h2>
                        <p className="text-sm text-slate-600 dark:text-slate-500 mt-1">
                            {t('taxRates.subtitle')}
                        </p>
                    </div>
                    <button
                        onClick={handleSaveAll}
                        className="px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl flex items-center gap-2 transition-all font-bold shadow-lg shadow-blue-900/30 active:scale-95"
                    >
                        <Save className="w-4 h-4" />
                        {t('taxRates.saveChanges')}
                    </button>

                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-gray-50 dark:bg-slate-900/50 text-slate-700 dark:text-slate-500 text-sm uppercase tracking-wider">
                                <th className="p-4 font-semibold border-b dark:border-white/10">{t('taxRates.county')}</th>
                                <th className="p-4 font-semibold border-b dark:border-white/10">{t('taxRates.baseTaxState')}</th>
                                <th className="p-4 font-semibold border-b dark:border-white/10">{t('taxRates.surtaxCounty')}</th>
                                <th className="p-4 font-semibold border-b dark:border-white/10">{t('taxRates.totalTax')}</th>
                                <th className="p-4 font-semibold border-b dark:border-white/10 text-center">{t('taxRates.status')}</th>
                                <th className="p-4 font-semibold border-b dark:border-white/10 text-right">{t('taxRates.actions')}</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                            {rates.map((rate) => (
                                <tr key={rate.id} className="hover:bg-gray-50 dark:hover:bg-white/10/50 transition-colors">
                                    <td className="p-4 font-medium text-gray-800 dark:text-white">
                                        {rate.county}
                                    </td>
                                    <td className="p-4 text-slate-700 dark:text-slate-400">
                                        6.00%
                                    </td>
                                    <td className="p-4">
                                        <div className="flex items-center gap-2">
                                            <input
                                                type="number"
                                                step="0.1"
                                                min="0"
                                                max="5"
                                                value={(rate.surtaxRate * 100).toFixed(2)}
                                                onChange={(e) => rate.id !== undefined && handleRateChange(rate.id, parseFloat(e.target.value) / 100)}
                                                className="w-20 px-2 py-1 text-right border rounded dark:bg-white/5 dark:border-white/10 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                            />
                                            <span className="text-slate-600">%</span>
                                        </div>
                                    </td>
                                    <td className="p-4 font-bold text-blue-600 dark:text-blue-400">
                                        {((0.06 + rate.surtaxRate) * 100).toFixed(2)}%
                                    </td>
                                    <td className="p-4 text-center">
                                        <button
                                            onClick={() => rate.id !== undefined && toggleActive(rate.id)}
                                            className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${rate.active
                                                ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'
                                                : 'bg-gray-100 text-gray-800 dark:bg-white/5 dark:text-slate-500'
                                                }`}
                                        >
                                            {rate.active ? t('taxRates.active') : t('taxRates.inactive')}
                                        </button>
                                    </td>
                                    <td className="p-4 text-right">
                                        <button className="p-2 text-slate-500 hover:text-red-500 transition-colors rounded-full hover:bg-red-50 dark:hover:bg-red-900/20">
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div className="p-4 border-t border-gray-100 dark:border-white/10 bg-yellow-50 dark:bg-yellow-900/10 text-sm text-yellow-800 dark:text-yellow-200 flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
                    <p>
                        <strong>{t('taxRates.importantNote')}:</strong> {t('taxRates.importantNoteDesc')}
                    </p>
                </div>
            </div>
        </div>
    );
};

