    );
};

import React, { useEffect, useState } from 'react';
import { DatabaseService } from '../database/DatabaseService';
import { useLocale } from '../i18n/useLocale';

export const VerifyIronCore: React.FC = () => {
    const { t } = useLocale();
    const [logs, setLogs] = useState<string[]>([]);

    const log = (msg: string) => setLogs(prev => [...prev, msg]);

    useEffect(() => {
        const runTests = async () => {
            log(t('verifyIronCore.starting'));
            try {
                // 1. Columnas
                log("\n" + t('verifyIronCore.verifyingColumns'));
                try {
                    const cols = await DatabaseService.executeQuery("PRAGMA table_info(journal_entries)");
                    log(t('verifyIronCore.columnsDetected') + JSON.stringify(cols.map((c: any) => c.name)));

                    const hasEntryNumber = cols.some((c: any) => c.name === 'entry_number');
                    const hasTxDate = cols.some((c: any) => c.name === 'transaction_date');

                    if (hasEntryNumber && hasTxDate) log(t('verifyIronCore.schemeCorrect'));
                    else log(t('verifyIronCore.schemeIncorrect') + ` EntryNum: ${hasEntryNumber}, TxDate: ${hasTxDate}`);

                } catch (e: any) {
                    log(t('verifyIronCore.errorReadingScheme') + e.message);
                }

                // 2. Triggers
                log("\n" + t('verifyIronCore.verifyingTriggers'));
                try {
                    const triggers = await DatabaseService.executeQuery("SELECT name FROM sqlite_master WHERE type='trigger'");
                    const triggerNames = triggers.map((t: any) => t.name);
                    log(t('verifyIronCore.activeTriggers') + JSON.stringify(triggerNames));

                    if (triggerNames.includes('prevent_journal_update') && triggerNames.includes('prevent_journal_delete')) {
                        log(t('verifyIronCore.triggersInstalled'));
                    } else {
                        log(t('verifyIronCore.triggersMissing'));
                    }
                } catch (e: any) {
                    log(t('verifyIronCore.errorReadingTriggers') + e.message);
                }

                // 3. Condados
                log("\n" + t('verifyIronCore.countingCounties'));
                try {
                    const count = await DatabaseService.executeQuery("SELECT COUNT(*) as c FROM florida_tax_rates");
                    const num = count[0]?.c;
                    log(t('verifyIronCore.countiesFound') + num);
                    if (num >= 50) log(t('verifyIronCore.populationSuccessful'));
                    else log(t('verifyIronCore.populationInsufficient'));
                } catch (e: any) {
                    log(t('verifyIronCore.errorReadingCounties') + e.message);
                }

                // 4. Test Inmutabilidad
                log("\n" + t('verifyIronCore.testingImmutability'));
                try {
                    const countJE = await DatabaseService.executeQuery("SELECT COUNT(*) as c FROM journal_entries");
                    if (countJE[0].c === 0) {
                        log(t('verifyIronCore.emptyTableWarning'));
                        DatabaseService.executeQuery("INSERT INTO journal_entries (total_debit, total_credit, entry_date) VALUES (0,0, '2024-01-01')");
                    }

                    await DatabaseService.executeQuery("UPDATE journal_entries SET description = 'HACKED' WHERE rowid = (SELECT rowid FROM journal_entries LIMIT 1)");
                    log(t('verifyIronCore.criticalFailure'));
                } catch (e: any) {
                    if (e.message.includes("FORENSIC ALERT") || e.message.includes("inmutables") || e.message.includes("immutable")) {
                        log(t('verifyIronCore.immutabilitySuccess') + e.message);
                    } else {
                        log(t('verifyIronCore.unknownFailure') + e.message);
                    }
                }

            } catch (e: any) {
                log(t('verifyIronCore.fatalError') + e.message);
            }
        };

        // Wait 3 seconds for DB init to be sure
        setTimeout(runTests, 3000);
    }, [t]);

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh',
            background: '#0a0a0a', color: '#00ff00', padding: 40, fontFamily: 'monospace',
            whiteSpace: 'pre-wrap', zIndex: 9999, overflow: 'auto', fontSize: '14px'
        }}>
            <h1 style={{ borderBottom: '1px solid #333', paddingBottom: '20px' }}>{t('verifyIronCore.title')}</h1>
            {logs.map((l, i) => <div key={i} style={{ marginBottom: '5px' }}>{l}</div>)}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { CheckCircle, AlertCircle, AlertTriangle, Clock, Loader, Activity, ChevronRight } from 'lucide-react';
import { useLocale } from '../../i18n/useLocale';

// ============================================================================
// INTERFACES Y TIPOS
// ============================================================================

export interface ChecklistItem {
  id: string;
  label: string;
  status: 'pending' | 'passed' | 'warning' | 'error';
  message?: string;
  details?: any;
  action?: {
    label: string;
    onClick: () => void;
  };
}

export interface ValidationResult {
  stepId: number;
  status: 'pending' | 'passed' | 'warning' | 'error';
  checks: ChecklistItem[];
  timestamp: string;
}

interface ClosureChecklistProps {
  periodId: number;
  stepId: number;
  checks: ChecklistItem[];
  autoRun?: boolean;
  onValidationStart?: () => void;
  onValidationComplete?: (result: ValidationResult) => void;
}

// ============================================================================
// COMPONENTE PRINCIPAL
// ============================================================================

export default function ClosureChecklist({
  periodId,
  stepId,
  checks: initialChecks,
  autoRun = false,
  onValidationStart,
  onValidationComplete
}: ClosureChecklistProps) {
  const { t } = useLocale();
  const [checks, setChecks] = useState<ChecklistItem[]>(initialChecks);
  const [isRunning, setIsRunning] = useState(false);
  const [hasRun, setHasRun] = useState(false);

  // Actualizar checks cuando cambian desde el padre
  useEffect(() => {
    setChecks(initialChecks);

    // Si todos los checks tienen estado diferente a pending, marcar como ejecutado
    const allChecked = initialChecks.every(c => c.status !== 'pending');
    if (allChecked) {
      setHasRun(true);
    }
  }, [initialChecks]);

  // Auto-ejecutar validaciones si autoRun est├í habilitado
  useEffect(() => {
    if (autoRun && !hasRun) {
      handleRunValidations();
    }
  }, [autoRun, hasRun]);

  // ============================================================================
  // FUNCIONES DE VALIDACI├ôN
  // ============================================================================

  const handleRunValidations = async () => {
    setIsRunning(true);
    setHasRun(true);

    if (onValidationStart) {
      onValidationStart();
    }

    // Las validaciones reales se ejecutan en los componentes de paso
    const result: ValidationResult = {
      stepId,
      status: determineOverallStatus(checks),
      checks: checks,
      timestamp: new Date().toISOString()
    };

    setIsRunning(false);

    if (onValidationComplete) {
      onValidationComplete(result);
    }
  };

  const determineOverallStatus = (checkList: ChecklistItem[]): 'pending' | 'passed' | 'warning' | 'error' => {
    const hasErrors = checkList.some(c => c.status === 'error');
    const hasWarnings = checkList.some(c => c.status === 'warning');
    const allPassed = checkList.every(c => c.status === 'passed');

    return hasErrors ? 'error' : hasWarnings ? 'warning' : allPassed ? 'passed' : 'pending';
  };

  // ============================================================================
  // FUNCIONES DE UI
  // ============================================================================

  const getStatusIcon = (status: ChecklistItem['status']) => {
    switch (status) {
      case 'passed':
        return <CheckCircle className="w-5 h-5 text-emerald-500" />;
      case 'warning':
        return <AlertTriangle className="w-5 h-5 text-orange-500" />;
      case 'error':
        return <AlertCircle className="w-5 h-5 text-red-500" />;
      case 'pending':
      default:
        return <Clock className="w-5 h-5 text-slate-600" />;
    }
  };

  const getStatusColor = (status: ChecklistItem['status']) => {
    switch (status) {
      case 'passed':
        return 'bg-emerald-900/10 border-emerald-500/20';
      case 'warning':
        return 'bg-orange-900/10 border-orange-500/20';
      case 'error':
        return 'bg-red-900/10 border-red-500/20';
      case 'pending':
      default:
        return 'bg-slate-900/30 border-slate-800/50';
    }
  };

  const getStatusTextColor = (status: ChecklistItem['status']) => {
    switch (status) {
      case 'passed':
        return 'text-emerald-400';
      case 'warning':
        return 'text-orange-400';
      case 'error':
        return 'text-red-400';
      case 'pending':
      default:
        return 'text-slate-400';
    }
  };

  // Calcular resumen
  const summary = {
    total: checks.length,
    passed: checks.filter(c => c.status === 'passed').length,
    warning: checks.filter(c => c.status === 'warning').length,
    error: checks.filter(c => c.status === 'error').length,
    pending: checks.filter(c => c.status === 'pending').length
  };

  // ============================================================================
  // RENDER
  // ============================================================================

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header con resumen */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-900/50 p-6 rounded-2xl border border-slate-800 shadow-xl">
        <div className="space-y-3">
          <h4 className="text-xl font-black text-white tracking-tighter uppercase flex items-center gap-3">
            <Activity className="w-5 h-5 text-blue-500" />
            {t('closure.checklist.title')}
          </h4>
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-500/10 rounded-full border border-emerald-500/20">
              <CheckCircle className="w-3.5 h-3.5 text-emerald-500" />
              <span className="text-xs font-black text-emerald-400 uppercase tracking-widest">({summary.passed} {t('closure.checklist.passed')})</span>
            </div>
            {summary.warning > 0 && (
              <div className="flex items-center gap-1.5 px-3 py-1 bg-orange-500/10 rounded-full border border-orange-500/20">
                <AlertTriangle className="w-3.5 h-3.5 text-orange-500" />
                <span className="text-xs font-bold text-orange-400">{summary.warning} {t('closure.checklist.warnings')}</span>
              </div>
            )}
            {summary.error > 0 && (
              <div className="flex items-center gap-1.5 px-3 py-1 bg-red-500/10 rounded-full border border-red-500/20">
                <AlertCircle className="w-3.5 h-3.5 text-red-500" />
                <span className="text-xs font-bold text-red-400">{summary.error} {t('closure.checklist.errors')}</span>
              </div>
            )}
            {summary.pending > 0 && (
              <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-800/50 rounded-full border border-slate-700/50">
                <Clock className="w-3.5 h-3.5 text-slate-500" />
                <span className="text-xs font-bold text-slate-500">{summary.pending} {t('closure.checklist.pending')}</span>
              </div>
            )}
          </div>
        </div>

        {!autoRun && (
          <button
            onClick={handleRunValidations}
            disabled={isRunning}
            className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-lg shadow-blue-900/20 disabled:bg-slate-800 disabled:text-slate-600 disabled:shadow-none transition-all active:scale-95 flex items-center justify-center gap-2 group"
          >
            {isRunning ? (
              <>
                <Loader className="w-5 h-5 animate-spin" />
                {t('closure.checklist.validating')}
              </>
            ) : (
              <>
                <CheckCircle className="w-5 h-5 group-hover:rotate-12 transition-transform" />
                {t('closure.checklist.runValidations')}
              </>
            )}
          </button>
        )}
      </div>

      {/* Lista de checks */}
      <div className="grid grid-cols-1 gap-3">
        {checks.map((check, index) => (
          <div
            key={check.id}
            className={`p-5 rounded-xl border-2 transition-all duration-300 group hover:translate-x-1 ${getStatusColor(check.status)}`}
          >
            <div className="flex items-start gap-4">
              <div className="flex-shrink-0 mt-1">
                {isRunning && check.status === 'pending' ? (
                  <Loader className="w-6 h-6 text-blue-500 animate-spin" />
                ) : (
                  getStatusIcon(check.status)
                )}
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div className="flex-1 space-y-1">
                    <p className={`text-base font-black tracking-tighter uppercase ${getStatusTextColor(check.status)}`}>
                      {check.label}
                    </p>
                    {check.message && (
                      <p className="text-sm font-medium text-slate-500 italic">
                        {check.message}
                      </p>
                    )}
                  </div>

                  {check.action && check.status !== 'passed' && (
                    <button
                      onClick={check.action.onClick}
                      className="px-4 py-2 bg-slate-950/50 hover:bg-slate-950 text-xs font-bold text-blue-400 border border-blue-500/30 rounded-lg transition-all flex items-center gap-2"
                    >
                      {check.action.label}
                      <ChevronRight className="w-3 h-3" />
                    </button>
                  )}
                </div>

                {check.details && (
                  <details className="mt-4 group/details">
                    <summary className="text-xs font-bold text-slate-500 cursor-pointer hover:text-slate-400 transition-colors list-none flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-slate-700 group-open/details:bg-blue-500" />
                      {t('closure.checklist.technicalAudit')}
                    </summary>
                    <div className="mt-3 p-4 bg-slate-950 rounded-xl border border-slate-800/50 overflow-x-auto">
                      <pre className="text-xs font-mono text-blue-400 font-medium leading-relaxed">
                        {JSON.stringify(check.details, null, 2)}
                      </pre>
                    </div>
                  </details>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Resumen final vertical bar */}
      {hasRun && !isRunning && (
        <div className={`mt-6 p-6 rounded-2xl border-l-8 shadow-2xl animate-in slide-in-from-bottom-4 duration-500 bg-slate-900/80 ${summary.error > 0 ? 'border-red-600' : summary.warning > 0 ? 'border-orange-600' : 'border-emerald-600'
          }`}>
          <div className="flex flex-col md:flex-row items-center justify-between gap-6">
            <div className="text-center md:text-left space-y-2">
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">{t('closure.checklist.stepStatus')}</p>
              <h3 className="text-2xl font-black text-white tracking-tighter uppercase">
                {summary.passed} {t('common.of')} {summary.total} {t('closure.checklist.completedValidations')}
              </h3>
            </div>
            <div className="flex flex-col items-center md:items-end gap-2">
              {summary.error > 0 ? (
                <div className="flex items-center gap-3 px-6 py-3 bg-red-500 text-white rounded-xl font-bold shadow-lg shadow-red-900/20">
                  <AlertCircle className="w-6 h-6" />
                  {t('closure.checklist.errorActionRequired')}
                </div>
              ) : summary.warning > 0 ? (
                <div className="flex items-center gap-3 px-6 py-3 bg-orange-600 text-white rounded-xl font-bold shadow-lg shadow-orange-900/20">
                  <AlertTriangle className="w-6 h-6" />
                  {t('closure.checklist.warningsDetected')}
                </div>
              ) : (
                <div className="flex items-center gap-3 px-6 py-3 bg-emerald-600 text-white rounded-xl font-bold shadow-lg shadow-emerald-900/20">
                  <CheckCircle className="w-6 h-6" />
                  {t('closure.checklist.readyToContinue')}
                </div>
              )}
              <p className="text-xs font-medium text-slate-500">{t('closure.checklist.auditRecorded')}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Download, CheckCircle, AlertTriangle, AlertCircle, FileText, ChevronRight, User, Calendar, DollarSign, TrendingUp, Activity, X } from 'lucide-react';
import { useLocale } from '../../i18n/useLocale';
import { AccountingPeriod } from '../../services/accounting/AccountingPeriodService';
import { ValidationResult } from './ClosureChecklist';

// ============================================================================
// INTERFACES
// ============================================================================

export interface ClosureReportData {
  period: AccountingPeriod;
  validationResults: ValidationResult[];
  summary: {
    totalTransactions: number;
    totalRevenue: number;
    totalExpenses: number;
    netIncome: number;
    totalDebit: number;
    totalCredit: number;
  };
  closedBy: string;
  closedAt: string;
}

interface ClosureReportProps {
  data: ClosureReportData;
  onDownloadPDF: () => void;
  onClose: () => void;
}

// ============================================================================
// COMPONENTE PRINCIPAL
// ============================================================================

export default function ClosureReport({
  data,
  onDownloadPDF,
  onClose
}: ClosureReportProps) {
  const { t } = useLocale();
  const { period, validationResults, summary, closedBy, closedAt } = data;

  // Calcular totales de validaciones
  const totalChecks = validationResults.reduce((sum, result) => sum + result.checks.length, 0);
  const passedChecks = validationResults.reduce(
    (sum, result) => sum + result.checks.filter(c => c.status === 'passed').length,
    0
  );
  const warningChecks = validationResults.reduce(
    (sum, result) => sum + result.checks.filter(c => c.status === 'warning').length,
    0
  );
  const errorChecks = validationResults.reduce(
    (sum, result) => sum + result.checks.filter(c => c.status === 'error').length,
    0
  );

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(amount);
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const getStepName = (stepId: number): string => {
    const names: Record<number, string> = {
      1: t('closure.steps.transactionValidation'),
      2: t('closure.steps.bankReconciliation'),
      3: t('closure.steps.accountingAdjustments'),
      4: t('closure.steps.trialBalance'),
      5: t('closure.steps.confirmation')
    };
    return names[stepId] || `${t('closure.steps.step')} ${stepId}`;
  };

  return (
    <div className="bg-slate-900 rounded-2xl shadow-2xl max-w-5xl mx-auto border border-slate-800 overflow-hidden animate-in zoom-in-95 duration-500">
      {/* Header */}
      <div className="bg-slate-950/80 p-8 border-b border-slate-800 flex items-center justify-between">
        <div className="space-y-1">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-500/10 rounded-lg">
              <FileText className="w-8 h-8 text-blue-500" />
            </div>
            <h2 className="text-3xl font-black text-white tracking-tighter uppercase">{t('closure.report.title')}</h2>
          </div>
          <p className="text-slate-500 font-medium ml-11 text-xs">{period.name}</p>
        </div>
        <div className="flex items-center gap-4">
          <button
            onClick={onDownloadPDF}
            className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl transition-all shadow-lg shadow-blue-900/20 active:scale-95 group"
          >
            <Download className="w-5 h-5 group-hover:translate-y-0.5 transition-transform" />
            {t('closure.report.downloadPdf')}
          </button>
          <button
            onClick={onClose}
            className="p-2.5 bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white rounded-xl transition-all active:scale-95"
          >
            <X className="w-6 h-6" />
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="p-8 space-y-8 max-h-[75vh] overflow-y-auto custom-scrollbar">
        {/* Informaci├│n General Grid */}
        <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-2 bg-slate-950/30 rounded-2xl p-6 border border-slate-800/50 space-y-4">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
              <Activity className="w-4 h-4 text-blue-500" />
              {t('closure.report.periodDetails')}
            </h3>
            <div className="grid grid-cols-2 lg:grid-cols-3 gap-6">
              <div>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.status')}</p>
                <div className="mt-1 inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-500/10 border border-emerald-500/20 rounded-full text-emerald-400 text-xs font-bold">
                  <CheckCircle className="w-3 h-3" />
                  {t('closure.report.closedLocked')}
                </div>
              </div>
              <div>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.type')}</p>
                <p className="text-sm font-bold text-white capitalize">{period.period_type === 'monthly' ? t('closure.report.monthly') : period.period_type}</p>
              </div>
              <div>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.dateRange')}</p>
                <p className="text-sm font-bold text-white">{formatDate(period.start_date)} - {formatDate(period.end_date)}</p>
              </div>
            </div>
          </div>

          <div className="bg-slate-950/30 rounded-2xl p-6 border border-slate-800/50 space-y-4">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
              <User className="w-4 h-4 text-purple-500" />
              {t('closure.report.closingAudit')}
            </h3>
            <div className="space-y-4">
              <div>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.executedBy')}</p>
                <p className="text-sm font-bold text-white">{closedBy || t('closure.report.technicalAdmin')}</p>
              </div>
              <div>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.timestamp')}</p>
                <p className="text-sm font-medium text-slate-400 italic">{closedAt ? formatDate(closedAt) : formatDate(new Date().toISOString())}</p>
              </div>
            </div>
          </div>
        </section>

        {/* Resumen Financiero High Impact */}
        <section className="space-y-4">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider px-2">{t('closure.report.kpis')}</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-slate-900/80 border border-slate-800 p-6 rounded-2xl shadow-xl group hover:border-blue-500/30 transition-all">
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-bold text-blue-500 uppercase tracking-wider">{t('closure.report.totalRevenue')}</p>
                <TrendingUp className="w-4 h-4 text-blue-500" />
              </div>
              <p className="text-2xl font-black text-white tabular-nums tracking-tighter">
                {formatCurrency(summary.totalRevenue)}
              </p>
              <div className="mt-3 w-full bg-slate-950 h-1.5 rounded-full overflow-hidden">
                <div className="bg-blue-500 h-full w-full" />
              </div>
            </div>

            <div className="bg-slate-900/80 border border-slate-800 p-6 rounded-2xl shadow-xl group hover:border-red-500/30 transition-all">
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-bold text-red-500 uppercase tracking-wider">{t('closure.report.totalExpenses')}</p>
                <AlertCircle className="w-4 h-4 text-red-500" />
              </div>
              <p className="text-2xl font-black text-white tabular-nums tracking-tighter">
                {formatCurrency(summary.totalExpenses)}
              </p>
              <div className="mt-3 w-full bg-slate-950 h-1.5 rounded-full overflow-hidden">
                <div className="bg-red-500 h-full" style={{ width: `${(summary.totalExpenses / summary.totalRevenue) * 100}%` }} />
              </div>
            </div>

            <div className="bg-slate-900/80 border border-emerald-500/20 p-6 rounded-2xl shadow-xl group hover:bg-emerald-500/5 transition-all">
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-bold text-emerald-500 uppercase tracking-wider">{t('closure.report.netIncome')}</p>
                <DollarSign className="w-4 h-4 text-emerald-500" />
              </div>
              <p className="text-3xl font-black text-emerald-400 tabular-nums tracking-tighter">
                {formatCurrency(summary.netIncome)}
              </p>
              <p className="text-xs font-medium text-emerald-500/50 mt-2 uppercase">Margin: {((summary.netIncome / summary.totalRevenue) * 100).toFixed(1)}%</p>
            </div>

            <div className="bg-slate-900/80 border border-slate-800 p-6 rounded-2xl shadow-xl">
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.transVolume')}</p>
                <Activity className="w-4 h-4 text-slate-500" />
              </div>
              <p className="text-2xl font-bold text-white tabular-nums">
                {summary.totalTransactions}
              </p>
              <p className="text-[11px] font-medium text-slate-600 mt-2 uppercase">{t('closure.report.entries')}</p>
            </div>
          </div>
        </section>

        {/* Balance de Comprobaci├│n Summary */}
        <section className="bg-slate-950/50 rounded-2xl border border-slate-800 p-8 shadow-inner">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-6 text-center">{t('closure.report.doubleEntryVerification')}</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
            <div className="text-center space-y-1">
              <p className="text-[10px] font-bold text-slate-500 uppercase">{t('closure.report.totalDebits')}</p>
              <p className="text-2xl font-bold text-white font-mono">
                {formatCurrency(summary.totalDebit)}
              </p>
            </div>

            <div className="flex flex-col items-center">
              <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 ${Math.abs(summary.totalDebit - summary.totalCredit) < 0.01
                ? 'bg-emerald-500/10 border-emerald-500 text-emerald-500 shadow-lg shadow-emerald-900/20'
                : 'bg-red-500/10 border-red-500 text-red-500'
                }`}>
                {Math.abs(summary.totalDebit - summary.totalCredit) < 0.01 ? <CheckCircle className="w-6 h-6" /> : <X className="w-6 h-6" />}
              </div>
              <div className="h-0.5 w-16 bg-slate-800 mt-2" />
              <p className={`text-[11px] font-bold mt-2 uppercase tracking-tight ${Math.abs(summary.totalDebit - summary.totalCredit) < 0.01 ? 'text-emerald-500' : 'text-red-500'
                }`}>
                {t('closure.report.difference')}: {formatCurrency(Math.abs(summary.totalDebit - summary.totalCredit))}
              </p>
            </div>

            <div className="text-center space-y-1">
              <p className="text-[10px] font-bold text-slate-500 uppercase">{t('closure.report.totalCredits')}</p>
              <p className="text-2xl font-bold text-white font-mono">
                {formatCurrency(summary.totalCredit)}
              </p>
            </div>
          </div>
        </section>

        {/* Resumen de Validaciones Grid */}
        <section className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">{t('closure.report.auditTrail')} ({totalChecks} {t('closure.report.controls')})</h3>
            <div className="flex gap-4">
              <div className="flex items-center gap-1.5">
                <div className="w-2 h-2 rounded-full bg-emerald-500" />
                <span className="text-xs font-medium text-slate-400 uppercase">{passedChecks} {t('closure.report.ok')}</span>
              </div>
              <div className="flex items-center gap-1.5">
                <div className="w-2 h-2 rounded-full bg-orange-500" />
                <span className="text-xs font-medium text-slate-400 uppercase">{warningChecks} {t('closure.report.wrn')}</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            {validationResults.map((result) => (
              <div key={result.stepId} className="bg-slate-900/40 rounded-xl border border-slate-800/80 overflow-hidden group hover:border-slate-700 transition-all">
                <div className="px-4 py-3 bg-slate-950/60 flex items-center justify-between border-b border-slate-800/50">
                  <h4 className="text-xs font-bold text-white flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${result.status === 'passed' ? 'bg-emerald-500' :
                      result.status === 'warning' ? 'bg-orange-500' : 'bg-red-500'
                      }`} />
                    {getStepName(result.stepId)}
                  </h4>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-tight ${result.status === 'passed' ? 'text-emerald-500 bg-emerald-500/10' :
                    result.status === 'warning' ? 'text-orange-500 bg-orange-500/10' : 'text-red-500 bg-red-500/10'
                    }`}>
                    {result.status}
                  </span>
                </div>
                <div className="p-4 space-y-2">
                  {result.checks.map((check) => (
                    <div key={check.id} className="flex items-center justify-between gap-3 group/item">
                      <div className="flex items-center gap-2 overflow-hidden">
                        {check.status === 'passed' ? (
                          <CheckCircle className="w-3.5 h-3.5 text-emerald-500/50 group-hover/item:text-emerald-500 transition-colors" />
                        ) : check.status === 'warning' ? (
                          <AlertTriangle className="w-3.5 h-3.5 text-orange-500" />
                        ) : (
                          <AlertCircle className="w-3.5 h-3.5 text-red-500" />
                        )}
                        <span className="text-xs font-bold text-slate-400 group-hover/item:text-slate-200 transition-colors truncate">{check.label}</span>
                      </div>
                      <ChevronRight className="w-3 h-3 text-slate-800 group-hover/item:text-slate-600" />
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Notas Section */}
        {period.notes && (
          <section className="bg-slate-950/20 rounded-xl p-6 border border-slate-800/30 italic">
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3">{t('closure.report.additionalNotes')}</h3>
            <p className="text-sm font-medium text-slate-400 leading-relaxed">"{period.notes}"</p>
          </section>
        )}
      </div>

      {/* Action Footer */}
      <div className="bg-slate-950/80 px-8 py-6 flex items-center justify-between border-t border-slate-800">
        <div className="flex items-center gap-2 text-xs font-medium text-slate-500">
          <Activity className="w-3 h-3 text-blue-500" />
          {t('closure.report.reportId')}: CLR-{period.id}-{new Date().getTime().toString().slice(-6)}
        </div>
        <div className="flex items-center gap-4">
          <button
            onClick={onClose}
            className="px-6 py-2.5 text-slate-400 hover:text-white font-bold text-sm transition-colors"
          >
            {t('closure.report.closeDashboard')}
          </button>
          <button
            onClick={onDownloadPDF}
            className="px-8 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-xl shadow-lg shadow-emerald-900/20 active:scale-95 transition-all flex items-center gap-2"
          >
            <Download className="w-4 h-4" />
            {t('closure.report.downloadPdf')}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import {
    RefreshCw,
    Download,
    Printer,
    TrendingUp,
    TrendingDown,
    DollarSign,
    Calendar,
    ChevronRight,
    ArrowRight,
    PieChart,
    ArrowUpCircle,
    ArrowDownCircle,
    FileText,
    History,
    Loader2
} from 'lucide-react';
import { getIncomeStatementReport, IncomeStatementItem } from '@/database/simple-db';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { useLocale } from '@/i18n/useLocale';

export const IncomeStatement: React.FC = () => {
    const { t, language } = useLocale();
    const [month, setMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
    const [data, setData] = useState<IncomeStatementItem[]>([]);
    const [loading, setLoading] = useState(false);

    const loadData = () => {
        setLoading(true);
        try {
            const [y, m] = month.split('-').map(Number);
            const startDate = `${y}-${String(m).padStart(2, '0')}-01`;
            const endDate = new Date(y, m, 0).toISOString().split('T')[0];

            const result = getIncomeStatementReport(startDate, endDate);
            setData(result);
        } catch (error) {
            console.error('Error loading P&L Flow:', error);
        } finally {
            setTimeout(() => setLoading(false), 500);
        }
    };

    useEffect(() => {
        loadData();
    }, [month]);

    const revenue = data.filter(i => i.account_type === 'revenue');
    const expenses = data.filter(i => i.account_type === 'expense');

    const totalRevenue = revenue.reduce((s, i) => s + i.balance, 0);
    const totalExpenses = expenses.reduce((s, i) => s + i.balance, 0);
    const netIncome = totalRevenue - totalExpenses;

    const formatNumber = (num: number) => {
        return new Intl.NumberFormat(language === 'es' ? 'es-ES' : 'en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(num);
    };

    const handleDownloadPDF = () => {
        const doc = new jsPDF();
        const [y, m] = month.split('-').map(Number);
        const monthName = new Date(y, m - 1).toLocaleString(language === 'es' ? 'es-ES' : 'en-US', { month: 'long' });

        doc.setFillColor(15, 23, 42);
        doc.rect(0, 0, 210, 40, 'F');

        doc.setFontSize(22);
        doc.setTextColor(255);
        doc.text('ACCOUNT EXPRESS', 14, 20);
        doc.setFontSize(12);
        doc.text(t('accounting.incomeStatement.pdfHeader'), 14, 30);

        doc.setFontSize(10);
        doc.setTextColor(200);
        doc.text(t('accounting.incomeStatement.fiscalCutoff', { month: monthName.toUpperCase(), year: y.toString() }), 145, 20);
        doc.text(t('accounting.incomeStatement.reportId', { id: Math.random().toString(36).substring(7).toUpperCase() }), 145, 25);

        let finalY = 45;

        const addTableSection = (title: string, items: IncomeStatementItem[], total: number, color: [number, number, number]) => {
            doc.setFontSize(12);
            doc.setTextColor(color[0], color[1], color[2]);
            doc.text(title.toUpperCase(), 14, finalY + 5);

            const body = items.map(i => [
                i.number ? `${i.number} (${i.account_code})` : i.account_code,
                i.account_name,
                formatNumber(i.balance)
            ]);

            autoTable(doc, {
                startY: finalY + 8,
                head: [[t('accounting.incomeStatement.pdfCode'), t('accounting.incomeStatement.pdfAccount'), t('accounting.incomeStatement.pdfAmount')]],
                body: body,
                theme: 'grid',
                headStyles: { fillColor: color, textColor: 255, fontStyle: 'bold' },
                styles: { fontSize: 9 },
                columnStyles: { 0: { cellWidth: 25 }, 2: { halign: 'right' } }
            });

            finalY = (doc as any).lastAutoTable.finalY + 10;
            doc.setFont('helvetica', 'bold');
            doc.text(`${t('accounting.incomeStatement.pdfTotal')} ${title.toUpperCase()}:`, 120, finalY);
            doc.text(`$${formatNumber(total)}`, 195, finalY, { align: 'right' });
            finalY += 15;
        };

        addTableSection(t('accounting.incomeStatement.pdfRevenue'), revenue, totalRevenue, [16, 185, 129]);
        addTableSection(t('accounting.incomeStatement.pdfExpenses'), expenses, totalExpenses, [244, 63, 94]);

        doc.setDrawColor(30, 41, 59);
        doc.setLineWidth(1);
        doc.line(14, finalY, 196, finalY);
        finalY += 15;

        doc.setFontSize(16);
        doc.setTextColor(netIncome >= 0 ? 16 : 244, netIncome >= 0 ? 185 : 63, netIncome >= 0 ? 129 : 94);
        doc.text(t('accounting.incomeStatement.pdfNetIncome'), 14, finalY);
        doc.text(`$${formatNumber(netIncome)}`, 195, finalY, { align: 'right' });

        doc.save(`AEX_P&L_${month}.pdf`);
    };

    return (
        <div className="space-y-10 animate-in fade-in duration-700 pb-20">
            {/* Control Hub */}
            <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-emerald-600/10 rounded-2.5xl border border-emerald-500/20 shadow-emerald-900/10 shadow-lg">
                        <PieChart className="w-10 h-10 text-emerald-500" />
                    </div>
                    <div>
                        <h2 className="text-3xl font-bold text-white tracking-tight">{t('accounting.incomeStatement.title')}</h2>
                        <p className="text-slate-500 font-medium text-xs mt-1 flex items-center gap-2">
                            <FileText className="w-3.5 h-3.5 text-emerald-500" /> {t('accounting.incomeStatement.performance')}
                        </p>
                    </div>
                </div>

                <div className="flex flex-wrap items-center gap-4">
                    <div className="flex items-center gap-4 bg-slate-950 border border-slate-800 p-2 rounded-2xl shadow-inner group">
                        <div className="bg-slate-900 p-2 rounded-xl group-hover:bg-blue-600/10 transition-colors">
                            <Calendar className="w-4 h-4 text-slate-500 group-hover:text-blue-500 transition-colors" />
                        </div>
                        <div className="flex flex-col pr-4">
                            <span className="text-xs font-medium text-slate-500">{t('accounting.incomeStatement.monthCutoff')}</span>
                            <input
                                type="month"
                                value={month}
                                onChange={(e) => setMonth(e.target.value)}
                                className="bg-transparent text-white border-0 p-0 text-sm font-bold outline-none focus:ring-0 cursor-pointer"
                            />
                        </div>
                    </div>

                    <div className="flex gap-2 p-1 bg-slate-950 rounded-2xl border border-slate-800">
                        <button onClick={loadData} disabled={loading} className="p-3 hover:bg-slate-900 text-slate-500 hover:text-white rounded-xl transition-all">
                            <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
                        </button>
                        <button onClick={() => window.print()} className="flex items-center gap-2 px-6 py-3 bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white border border-slate-700 rounded-xl font-bold text-[11px] transition-all">
                            <Printer className="w-4 h-4" /> {t('accounting.incomeStatement.print')}
                        </button>
                        <button onClick={handleDownloadPDF} className="flex items-center gap-2 px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-xl font-bold text-[11px] transition-all shadow-xl shadow-blue-900/30 active:scale-95">
                            <Download className="w-4 h-4" /> {t('accounting.incomeStatement.export')}
                        </button>
                    </div>
                </div>
            </div>

            {/* Financial Flow Visualization */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-7xl mx-auto">
                {/* REVENUE COLUMN */}
                <div className="bg-slate-900/40 border border-slate-800 rounded-[2.5rem] overflow-hidden shadow-2xl backdrop-blur-xl group hover:border-emerald-500/20 transition-all duration-500">
                    <header className="px-10 py-8 bg-slate-950/50 border-b border-slate-800/60 flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
                                <ArrowUpCircle className="w-6 h-6 text-emerald-500" />
                            </div>
                            <h3 className="text-xl font-bold text-white tracking-tight">{t('accounting.incomeStatement.revenue')}</h3>
                        </div>
                        <span className="text-[10px] font-bold text-emerald-500/60 bg-emerald-500/5 px-3 py-1 rounded-full border border-emerald-500/10">NODO 4000</span>
                    </header>

                    <div className="p-10 space-y-4">
                        {loading ? (
                            <div className="py-20 flex flex-col items-center gap-4">
                                <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
                                <p className="text-xs font-medium text-slate-600">{t('accounting.incomeStatement.syncRevenue')}</p>
                            </div>
                        ) : revenue.length === 0 ? (
                            <div className="py-20 text-center opacity-20 italic font-bold text-slate-500 text-xs">{t('accounting.incomeStatement.noRevenue')}</div>
                        ) : (
                            revenue.map((item, i) => (
                                <div key={i} className="flex justify-between items-center group/row p-4 rounded-2xl bg-slate-950/20 border border-transparent hover:border-slate-800 hover:bg-slate-950/40 transition-all">
                                    <div className="flex flex-col gap-1">
                                        <span className="text-xs font-bold text-slate-600 font-mono tracking-tight bg-slate-900/50 px-2 py-0.5 rounded-md border border-slate-800">
                                            {item.number ? `${item.number}` : item.account_code} {item.number && <span className="text-[9px] text-slate-500 font-normal">({item.account_code})</span>}
                                        </span>
                                        <span className="text-sm font-semibold text-slate-300 group-hover/row:text-white transition-colors">{item.account_name}</span>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-lg font-bold text-emerald-400 font-mono">
                                            ${formatNumber(item.balance)}
                                        </span>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>

                    <footer className="p-10 bg-emerald-500/5 border-t border-emerald-500/10 flex justify-between items-center">
                        <div>
                            <p className="text-xs font-bold text-emerald-500 uppercase tracking-wider mb-1">{t('accounting.incomeStatement.totalRevenue')}</p>
                            <p className="text-xs text-slate-500 font-medium">{t('accounting.incomeStatement.auditPeriod')}</p>
                        </div>
                        <p className="text-3xl font-bold text-emerald-400 font-mono tracking-tight">
                            ${formatNumber(totalRevenue)}
                        </p>
                    </footer>
                </div>

                {/* EXPENSES COLUMN */}
                <div className="bg-slate-900/40 border border-slate-800 rounded-[2.5rem] overflow-hidden shadow-2xl backdrop-blur-xl group hover:border-rose-500/20 transition-all duration-500">
                    <header className="px-10 py-8 bg-slate-950/50 border-b border-slate-800/60 flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-rose-500/10 rounded-2xl border border-rose-500/20">
                                <ArrowDownCircle className="w-6 h-6 text-rose-500" />
                            </div>
                            <h3 className="text-xl font-bold text-white tracking-tight">{t('accounting.incomeStatement.expenses')}</h3>
                        </div>
                        <span className="text-[10px] font-bold text-rose-500/60 bg-rose-500/5 px-3 py-1 rounded-full border border-rose-500/10">NODO 5000</span>
                    </header>

                    <div className="p-10 space-y-4">
                        {loading ? (
                            <div className="py-20 flex flex-col items-center gap-4">
                                <Loader2 className="w-8 h-8 text-rose-500 animate-spin" />
                                <p className="text-xs font-medium text-slate-600">{t('accounting.incomeStatement.syncExpenses')}</p>
                            </div>
                        ) : expenses.length === 0 ? (
                            <div className="py-20 text-center opacity-20 italic font-bold text-slate-500 text-xs">{t('accounting.incomeStatement.noExpenses')}</div>
                        ) : (
                            expenses.map((item, i) => (
                                <div key={i} className="flex justify-between items-center group/row p-4 rounded-2xl bg-slate-950/20 border border-transparent hover:border-slate-800 hover:bg-slate-950/40 transition-all">
                                    <div className="flex flex-col gap-1">
                                        <span className="text-xs font-bold text-slate-600 font-mono tracking-tight bg-slate-900/50 px-2 py-0.5 rounded-md border border-slate-800">
                                            {item.number ? `${item.number}` : item.account_code} {item.number && <span className="text-[9px] text-slate-500 font-normal">({item.account_code})</span>}
                                        </span>
                                        <span className="text-sm font-semibold text-slate-300 group-hover/row:text-white transition-colors">{item.account_name}</span>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-lg font-bold text-rose-400 font-mono">
                                            ${formatNumber(item.balance)}
                                        </span>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>

                    <footer className="p-10 bg-rose-500/5 border-t border-rose-500/10 flex justify-between items-center">
                        <div>
                            <p className="text-xs font-bold text-rose-500 uppercase tracking-wider mb-1">{t('accounting.incomeStatement.totalExpenses')}</p>
                            <p className="text-xs text-slate-500 font-medium">{t('accounting.incomeStatement.resourceConsumption')}</p>
                        </div>
                        <p className="text-3xl font-bold text-rose-400 font-mono tracking-tight">
                            ${formatNumber(totalExpenses)}
                        </p>
                    </footer>
                </div>

                {/* BOTTOM RESULT BAR - Full Width */}
                <div className={`lg:col-span-2 relative mt-4 group cursor-pointer transition-all duration-500 transform hover:scale-[1.01]`}>
                    <div className={`absolute inset-0 blur-3xl opacity-20 transition-all group-hover:opacity-40 ${netIncome >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                    <div className={`relative flex flex-col md:flex-row items-center justify-between p-12 rounded-[3.5rem] border-2 shadow-[0_30px_100px_rgba(0,0,0,0.4)] backdrop-blur-3xl transition-all ${netIncome >= 0
                        ? 'bg-slate-900/60 border-emerald-500/30'
                        : 'bg-slate-900/60 border-rose-500/30'
                        }`}>
                        <div className="flex items-center gap-8 mb-6 md:mb-0">
                            <div className={`p-6 rounded-[2rem] border shadow-2xl ${netIncome >= 0 ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-rose-500/10 border-rose-500/20 text-rose-500'
                                }`}>
                                <DollarSign className="w-12 h-12" strokeWidth={3} />
                            </div>
                            <div>
                                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 px-1">{t('accounting.incomeStatement.managementResult')}</h4>
                                <p className="text-4xl font-bold text-white tracking-tight">
                                    {netIncome >= 0 ? t('accounting.incomeStatement.netProfit') : t('accounting.incomeStatement.netLoss')}
                                </p>
                            </div>
                        </div>

                        <div className="text-right">
                            <div className="flex items-baseline gap-2 mb-1 justify-end">
                                <span className={`text-6xl font-bold font-mono tracking-tight ${netIncome >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                                    ${formatNumber(Math.abs(netIncome))}
                                </span>
                            </div>
                            <p className={`text-xs font-bold uppercase tracking-wider ${netIncome >= 0 ? 'text-emerald-500/60' : 'text-rose-500/60'}`}>
                                {t('accounting.incomeStatement.cashFlowRealized')} {netIncome >= 0 ? 'E' : 'D'}
                            </p>
                        </div>
                    </div>
                </div>
            </div >
        </div >

    );
};

import React, { useState } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { FileText, Plus, Trash2, Save, Calculator, AlertCircle, Hash, History, CheckCircle2, XCircle, AlertTriangle } from 'lucide-react';
import { type JournalEntry, type JournalLine } from '../../modules/accounting/Accounting.types';
import { useLocale } from '../../i18n/useLocale';
import { DoubleEntryValidator, type ClassificationWarning } from '../../services/accounting/DoubleEntryValidator';

interface JournalEntryFormProps {
    onCancel?: () => void;
    onSave?: (entry: JournalEntry, lines: JournalLine[]) => void;
}

export const JournalEntryForm: React.FC<JournalEntryFormProps> = ({ onCancel, onSave }) => {
    const { t, language } = useLocale();
    const [description, setDescription] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [lines, setLines] = useState<JournalLine[]>([
        { account_code: '', debit: 0, credit: 0, description: '' },
        { account_code: '', debit: 0, credit: 0, description: '' }
    ]);
    // Warnings de clasificaci├│n preventiva
    const [classificationWarnings, setClassificationWarnings] = useState<ClassificationWarning[]>([]);
    const [forceOverride, setForceOverride] = useState(false);

    const addLine = () => setLines([...lines, { account_code: '', debit: 0, credit: 0, description: '' }]);

    const updateLine = (index: number, field: keyof JournalLine, value: any) => {
        const newLines = [...lines];
        (newLines[index] as any)[field] = value;
        setLines(newLines);
    };

    const removeLine = (index: number) => {
        if (lines.length > 2) {
            setLines(lines.filter((_, i) => i !== index));
        }
    };

    const totalDebit = lines.reduce((sum, l) => sum + Number(l.debit), 0);
    const totalCredit = lines.reduce((sum, l) => sum + Number(l.credit), 0);
    const difference = Math.abs(totalDebit - totalCredit);
    const balanced = difference < 0.01;

    const formatNumber = (num: number) => {
        return new Intl.NumberFormat(language === 'es' ? 'es-ES' : 'en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(num);
    };

    const handleSave = () => {
        // Validaci├│n preventiva de clasificaci├│n
        const classResult = DoubleEntryValidator.validateAccountTypeConsistency(
            lines.map(l => ({
                account_code: l.account_code,
                debit: Number(l.debit),
                credit: Number(l.credit),
                description: l.description
            }))
        );

        // Si hay warnings y el usuario no forz├│, mostrar banner y detener
        if (classResult.warnings.length > 0 && !forceOverride) {
            setClassificationWarnings(classResult.warnings);
            return;
        }

        // Limpiar warnings si se forz├│ o si no hubo
        setClassificationWarnings([]);
        setForceOverride(false);

        if (onSave && balanced && description) {
            onSave({ entry_date: date, description } as JournalEntry, lines);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
            <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-5xl max-h-[92vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-500/5 blur-[120px] pointer-events-none"></div>

                <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
                    <div className="flex items-center gap-6">
                        <div className="p-4 bg-blue-600/10 rounded-2.5xl border border-blue-500/20 shadow-blue-900/10 shadow-lg">
                            <FileText className="w-8 h-8 text-blue-500" />
                        </div>
                        <div>
                            <h2 className="text-3xl font-black text-white tracking-tighter uppercase leading-none">
                                {t('accounting.journalEntry.title')}
                            </h2>
                            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2 flex items-center gap-2">
                                <History className="w-3.5 h-3.5 text-blue-500" /> {t('accounting.journalEntry.subtitle')}
                            </p>
                        </div>
                    </div>
                    <div className="flex items-center gap-6">
                        <div className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 border shadow-lg transition-all ${balanced
                            ? 'bg-emerald-900/20 border-emerald-500/30 text-emerald-400'
                            : 'bg-rose-900/20 border-rose-500/30 text-rose-400 animate-pulse'
                            }`}>
                            {balanced ? <CheckCircle2 className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
                            {balanced ? t('accounting.journalEntry.balanced') : `${t('accounting.journalEntry.imbalance')}: $${formatNumber(difference)}`}
                        </div>
                        {onCancel && (
                            <button onClick={onCancel} className="p-3 bg-slate-950/50 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95">
                                <XCircle className="w-6 h-6" />
                            </button>
                        )}
                    </div>
                </header>

                <div className="flex-1 overflow-hidden flex flex-col">
                    <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">
                        {/* Information Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <div className="md:col-span-2 space-y-3">
                                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 px-1">
                                    <FileText className="w-3.5 h-3.5 text-blue-500" /> {t('accounting.journalEntry.description')}
                                </label>
                                <div className="relative group/input">
                                    <input
                                        className="w-full bg-slate-950/50 text-white px-8 py-5 rounded-[2rem] border border-slate-800/50 focus:border-blue-500/50 focus:shadow-[0_0_25px_rgba(59,130,246,0.1)] outline-none transition-all font-bold text-sm placeholder:text-slate-800"
                                        placeholder={t('accounting.journalEntry.descriptionPlaceholder')}
                                        value={description}
                                        onChange={(e) => setDescription(e.target.value)}
                                    />
                                </div>
                            </div>
                            <div className="space-y-3">
                                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 px-1">
                                    <Calculator className="w-3.5 h-3.5 text-blue-500" /> {t('accounting.journalEntry.date')}
                                </label>
                                <input
                                    type="date"
                                    value={date}
                                    onChange={e => setDate(e.target.value)}
                                    className="w-full bg-slate-950/50 text-white px-8 py-5 rounded-[2rem] border border-slate-800/50 focus:border-blue-500/50 focus:outline-none font-mono font-bold text-sm transition-all"
                                />
                            </div>
                        </div>

                        {/* Entry Lines Table Container */}
                        <div className="bg-slate-950/30 rounded-[2.5rem] border border-slate-800/80 overflow-hidden shadow-inner p-1">
                            <table className="w-full text-sm border-collapse">
                                <thead>
                                    <tr className="bg-slate-950/80 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] border-b border-slate-800">
                                        <th className="py-6 px-8 text-left">{t('accounting.journalEntry.account')}</th>
                                        <th className="py-6 px-8 text-left">{t('accounting.journalEntry.description')}</th>
                                        <th className="py-6 px-8 text-right w-40">{t('accounting.journalEntry.debit')}</th>
                                        <th className="py-6 px-8 text-right w-40">{t('accounting.journalEntry.credit')}</th>
                                        <th className="py-6 px-8 w-16"></th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-800/30">
                                    {lines.map((line, idx) => (
                                        <tr key={idx} className="hover:bg-slate-800/20 transition-colors group">
                                            <td className="p-6">
                                                <input
                                                    placeholder={t('accounting.journalEntry.accountPlaceholder')}
                                                    className="w-full bg-transparent border-b border-slate-800 focus:border-blue-500 outline-none p-3 text-white font-black uppercase tracking-tight text-xs transition-colors"
                                                    value={line.account_code}
                                                    onChange={e => updateLine(idx, 'account_code', e.target.value.toUpperCase())}
                                                />
                                            </td>
                                            <td className="p-6">
                                                <input
                                                    placeholder={t('accounting.journalEntry.descriptionPlaceholder')}
                                                    className="w-full bg-transparent border-b border-slate-800 focus:border-blue-500 outline-none p-3 text-slate-400 font-bold italic text-xs transition-colors"
                                                    value={line.description}
                                                    onChange={e => updateLine(idx, 'description', e.target.value)}
                                                />
                                            </td>
                                            <td className="p-6">
                                                <input
                                                    type="number"
                                                    step="0.01"
                                                    className={`w-full bg-slate-900/50 rounded-2xl border border-slate-800 focus:border-emerald-500/50 outline-none p-4 text-right font-mono font-black text-sm transition-all ${line.debit > 0 ? 'text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.1)]' : 'text-slate-700'}`}
                                                    value={line.debit || ''}
                                                    onFocus={(e) => e.target.select()}
                                                    onChange={e => {
                                                        updateLine(idx, 'debit', Number(e.target.value));
                                                        if (Number(e.target.value) > 0) updateLine(idx, 'credit', 0);
                                                    }}
                                                />
                                            </td>
                                            <td className="p-6">
                                                <input
                                                    type="number"
                                                    step="0.01"
                                                    className={`w-full bg-slate-900/50 rounded-2xl border border-slate-800 focus:border-rose-500/50 outline-none p-4 text-right font-mono font-black text-sm transition-all ${line.credit > 0 ? 'text-rose-400 shadow-[0_0_15px_rgba(244,63,94,0.1)]' : 'text-slate-700'}`}
                                                    value={line.credit || ''}
                                                    onFocus={(e) => e.target.select()}
                                                    onChange={e => {
                                                        updateLine(idx, 'credit', Number(e.target.value));
                                                        if (Number(e.target.value) > 0) updateLine(idx, 'debit', 0);
                                                    }}
                                                />
                                            </td>
                                            <td className="p-6 text-center">
                                                <button
                                                    onClick={() => removeLine(idx)}
                                                    className="p-3 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-2xl transition-all active:scale-90"
                                                >
                                                    <Trash2 className="w-5 h-5" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot className="bg-slate-950/60 font-black">
                                    <tr>
                                        <td colSpan={2} className="p-8">
                                            <button
                                                onClick={addLine}
                                                className="flex items-center gap-3 text-blue-500 hover:text-white bg-blue-500/5 hover:bg-blue-600 px-8 py-4 border border-blue-500/20 rounded-2xl font-black uppercase tracking-widest text-[10px] transition-all shadow-lg active:scale-95"
                                            >
                                                <Plus className="w-4 h-4" /> {t('accounting.journalEntry.addEntry')}
                                            </button>
                                        </td>
                                        <td className="p-8 text-right bg-slate-900/40">
