import React, { useState, useEffect } from 'react';
import {
    CheckCircle,
    AlertTriangle,
    Lock,
    ChevronRight,
    ChevronLeft,
    FileText,
    Calculator,
    ShieldCheck,
    Activity,
    ArrowRight,
    Zap
} from 'lucide-react';
import {
    AccountingPeriod,
    TrialBalanceRow,
    getTrialBalanceReport,
    closePeriod,
    generateClosingEntry
} from '@/database/simple-db';
import { Button } from '../ui/button';
import { Card, CardContent } from '../ui/card';
import { toast } from 'react-hot-toast';
import { useAuth } from '../../contexts/AuthContext';
import { useLocale } from '../../i18n/useLocale';

interface PeriodClosingWizardProps {
    period: AccountingPeriod;
    year: number;
    onClose: () => void;
    onSuccess: () => void;
}

type ClosingStep = 'check' | 'audit' | 'adjust' | 'confirm';

export const PeriodClosingWizard: React.FC<PeriodClosingWizardProps> = ({ period, year, onClose, onSuccess }) => {
    const { user } = useAuth();
    const { t } = useLocale();
    const [step, setStep] = useState<ClosingStep>('check');
    const [trialBalance, setTrialBalance] = useState<TrialBalanceRow[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [shouldGenerateClosingEntry, setShouldGenerateClosingEntry] = useState(period.month === 12); // Auto on December

    const [validations, setValidations] = useState<{ id: string; label: string; status: 'pending' | 'success' | 'warning' }[]>([
        { id: 'ledger-balanced', label: t('periodClosing.validations.ledgerBalanced'), status: 'pending' },
        { id: 'inventory-checks', label: t('periodClosing.validations.inventoryChecks'), status: 'pending' },
        { id: 'tax-reconciled', label: t('periodClosing.validations.taxReconciled'), status: 'pending' },
        { id: 'audit-intact', label: t('periodClosing.validations.auditIntact'), status: 'pending' }
    ]);

    useEffect(() => {
        // Cargar balance de comprobaci├│n para el paso 1
        const tb = getTrialBalanceReport(year, period.month);
        setTrialBalance(tb);

        // Simular validaciones r├ípidas
        const timer = setTimeout(() => {
            setValidations(prev => prev.map(v => ({ ...v, status: 'success' })));
        }, 1500);

        return () => clearTimeout(timer);
    }, [period, year]);

    const totalDebits = trialBalance.reduce((acc, row) => acc + row.period_debit, 0);
    const totalCredits = trialBalance.reduce((acc, row) => acc + row.period_credit, 0);
    const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01;

    const handleFinalClose = async () => {
        if (!user) return;
        setIsLoading(true);
        try {
            // 1. Generar asiento de cierre si el usuario lo pidi├│
            if (shouldGenerateClosingEntry) {
                const fromDate = `${year}-${String(period.month).padStart(2, '0')}-01`;
                const nextMonth = new Date(year, period.month, 0);
                const endDate = nextMonth.toISOString().split('T')[0];

                const closeEntryRes = await generateClosingEntry(fromDate, endDate, user.id);
                if (!closeEntryRes.success) {
                    toast.error(`Error en asiento de cierre: ${closeEntryRes.message}`);
                    setIsLoading(false);
                    return;
                }
                toast.success(t('periodClosing.closingEntrySuccess'));
            }

            // 2. Cerrar periodo
            const res = await closePeriod(period.id!, user.id);
            if (res.success) {
                toast.success(t('periodClosing.periodLockedSuccess', { period: `${period.month}/${year}` }));
                onSuccess();
            } else {
                toast.error(res.message);
            }
        } catch (error) {
            console.error('[PeriodClosingWizard] Error al cerrar periodo:', error);
            toast.error(t('periodClosing.closingError'));
        } finally {
            setIsLoading(false);
        }
    };

    const getMonthName = (m: number) => {
        return new Intl.DateTimeFormat('es-ES', { month: 'long' }).format(new Date(2024, m - 1, 1));
    };

    return (
        <div className="fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4">
            <div className="w-full max-w-4xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-300">

                {/* Header con gradiente */}
                <div className="bg-gradient-to-r from-blue-600/20 via-emerald-600/20 to-blue-600/20 p-8 border-b border-white/5 relative">
                    <div className="flex justify-between items-center">
                        <div>
                            <div className="flex items-center gap-3 mb-1">
                                <span className="px-3 py-1 bg-blue-500/20 border border-blue-500/30 rounded-full text-xs font-bold text-blue-400 leading-none">
                                    {t('periodClosing.wizardTitle')}
                                </span>
                                <Lock className="w-4 h-4 text-amber-500" />
                            </div>
                            <h2 className="text-3xl font-bold text-white tracking-tight">
                                {t('periodClosing.accountingClosing')} <span className="text-emerald-400 capitalize">{getMonthName(period.month)} {year}</span>
                            </h2>
                        </div>
                        <button onClick={onClose} className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-500 hover:text-white">
                            <ChevronLeft className="w-6 h-6" />
                        </button>
                    </div>

                    {/* Progress Indicator */}
                    <div className="flex gap-4 mt-8">
                        {[
                            { id: 'check', label: t('periodClosing.steps.check') },
                            { id: 'audit', label: t('periodClosing.steps.audit') },
                            { id: 'adjust', label: t('periodClosing.steps.adjust') },
                            { id: 'confirm', label: t('periodClosing.steps.confirm') }
                        ].map((s, idx) => {
                            const currentStepIdx = ['check', 'audit', 'adjust', 'confirm'].indexOf(step);
                            const isActive = step === s.id;
                            const isPast = ['check', 'audit', 'adjust', 'confirm'].indexOf(s.id) < currentStepIdx;

                            return (
                                <div key={s.id} className="flex-1 flex items-center gap-2">
                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center font-bold text-xs transition-all ${isActive ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' :
                                        (isPast ? 'bg-emerald-500 text-white' : 'bg-slate-800 text-slate-500')
                                        }`}>
                                        {isPast ? <CheckCircle className="w-4 h-4" /> : idx + 1}
                                    </div>
                                    <span className={`text-xs font-bold ${isActive ? 'text-white' : 'text-slate-500'}`}>
                                        {s.label}
                                    </span>
                                    {idx < 3 && <div className="flex-1 h-px bg-slate-800" />}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="p-10 min-h-[400px]">
                    {step === 'check' && (
                        <div className="space-y-6 animate-in slide-in-from-right-8 duration-300">
                            <div className="flex justify-between items-end">
                                <div>
                                    <h3 className="text-xl font-bold text-white mb-1">{t('periodClosing.financialHealthReview')}</h3>
                                    <p className="text-xs text-slate-500 font-medium">{t('periodClosing.periodTrialBalance')}</p>
                                </div>
                                <div className={`px-4 py-2 rounded-2xl border flex items-center gap-3 ${isBalanced ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-rose-500/10 border-rose-500/20 text-rose-400'}`}>
                                    {isBalanced ? <CheckCircle className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
                                    <span className="text-sm font-bold">{isBalanced ? t('periodClosing.balanced') : t('periodClosing.imbalance')}</span>
                                </div>
                            </div>

                            <div className="bg-slate-950/50 rounded-3xl border border-slate-800 overflow-hidden">
                                <table className="w-full text-left text-sm">
                                    <thead className="bg-slate-950 text-slate-500 font-bold uppercase tracking-wider text-[10px]">
                                        <tr>
                                            <th className="px-6 py-4">{t('periodClosing.codeAccount')}</th>
                                            <th className="px-6 py-4 text-right">{t('periodClosing.periodDebits')}</th>
                                            <th className="px-6 py-4 text-right">{t('periodClosing.periodCredits')}</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-800">
                                        {trialBalance.length > 0 ? trialBalance.slice(0, 5).map(row => (
                                            <tr key={row.account_code}>
                                                <td className="px-6 py-4">
                                                    <span className="text-blue-400 font-mono text-xs">{row.account_code}</span>
                                                    <span className="ml-3 font-semibold text-slate-300">{row.account_name}</span>
                                                </td>
                                                <td className="px-6 py-4 text-right font-mono text-slate-400">${row.period_debit.toLocaleString()}</td>
                                                <td className="px-6 py-4 text-right font-mono text-slate-400">${row.period_credit.toLocaleString()}</td>
                                            </tr>
                                        )) : (
                                            <tr>
                                                <td colSpan={3} className="px-6 py-10 text-center text-slate-600 font-bold text-xs">No se encontraron movimientos</td>
                                            </tr>
                                        )}
                                        {trialBalance.length > 5 && (
                                            <tr>
                                                <td colSpan={3} className="px-6 py-4 text-center text-xs text-slate-600 font-bold">
                                                    Y {trialBalance.length - 5} cuentas adicionales cargadas...
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                    <tfoot className="bg-slate-900/50">
                                        <tr className="font-bold text-white">
                                            <td className="px-6 py-6 text-xs uppercase tracking-wider">{t('periodClosing.controlTotals')}</td>
                                            <td className="px-6 py-6 text-right font-mono text-lg">${totalDebits.toLocaleString()}</td>
                                            <td className="px-6 py-6 text-right font-mono text-lg">${totalCredits.toLocaleString()}</td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>

                            <div className="flex justify-end pt-4">
                                <Button
                                    onClick={() => setStep('audit')}
                                    disabled={!isBalanced}
                                    className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-10 py-6 rounded-2xl shadow-xl shadow-blue-900/20"
                                >
                                    {t('periodClosing.continueAudit')} <ChevronRight className="w-4 h-4 ml-2" />
                                </Button>
                            </div>
                        </div>
                    )}

                    {step === 'audit' && (
                        <div className="space-y-8 animate-in slide-in-from-right-8 duration-300">
                            <div className="text-center max-w-2xl mx-auto">
                                <Activity className="w-12 h-12 text-blue-400 mx-auto mb-4 animate-pulse" />
                                <h3 className="text-2xl font-bold text-white mb-2">{t('periodClosing.opIntegrityValidation')}</h3>
                                <p className="text-slate-500 text-sm">{t('periodClosing.integrityDesc')}</p>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {validations.map(v => (
                                    <div key={v.id} className="p-6 bg-slate-950/50 border border-slate-800 rounded-3xl flex items-center justify-between hover:bg-slate-800 transition-all">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-3 h-3 rounded-full ${v.status === 'success' ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]' :
                                                v.status === 'pending' ? 'bg-blue-500 animate-ping' : 'bg-amber-500'
                                                }`} />
                                            <span className="text-sm font-semibold text-slate-300">{v.label}</span>
                                        </div>
                                        {v.status === 'success' && <ShieldCheck className="w-5 h-5 text-emerald-500" />}
                                    </div>
                                ))}
                            </div>

                            <div className="flex justify-between pt-8">
                                <Button onClick={() => setStep('check')} variant="outline" className="border-slate-800 text-slate-500 hover:text-white px-8 py-6 rounded-2xl font-bold">
                                    <ChevronLeft className="w-4 h-4 mr-2" /> {t('periodClosing.back')}
                                </Button>
                                <Button
                                    onClick={() => setStep('adjust')}
                                    disabled={validations.some(v => v.status === 'pending')}
                                    className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-10 py-6 rounded-2xl shadow-xl shadow-blue-900/40"
                                >
                                    {t('periodClosing.nextAdjustments')} <ArrowRight className="w-4 h-4 ml-2" />
                                </Button>
                            </div>
                        </div>
                    )}

                    {step === 'adjust' && (
                        <div className="space-y-8 animate-in slide-in-from-right-8 duration-300">
                            <div className="p-8 bg-blue-600/5 border border-blue-600/10 rounded-[3rem] text-center">
                                <Zap className="w-12 h-12 text-blue-400 mx-auto mb-4" />
                                <h3 className="text-2xl font-bold text-white mb-2 tracking-tight">{t('periodClosing.autoClosingEntries')}</h3>
                                <p className="text-slate-500 text-sm max-w-lg mx-auto leading-relaxed">
                                    {t('periodClosing.autoClosingDesc')}
                                </p>
                            </div>

                            <div className="flex items-center justify-center p-8 bg-slate-950/30 rounded-3xl border border-slate-800 gap-6">
                                <div
                                    onClick={() => setShouldGenerateClosingEntry(true)}
                                    className={`flex-1 p-6 rounded-2xl border cursor-pointer transition-all text-center ${shouldGenerateClosingEntry ? 'bg-blue-600 border-blue-500 text-white shadow-xl shadow-blue-900/20' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
                                >
                                    <CheckCircle className={`w-6 h-6 mx-auto mb-2 ${shouldGenerateClosingEntry ? 'text-white' : 'text-slate-800'}`} />
                                    <span className="text-xs font-bold uppercase tracking-wider">{t('periodClosing.generateEntry')}</span>
                                </div>
                                <div
                                    onClick={() => setShouldGenerateClosingEntry(false)}
                                    className={`flex-1 p-6 rounded-2xl border cursor-pointer transition-all text-center ${!shouldGenerateClosingEntry ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
                                >
                                    <div className={`w-6 h-6 mx-auto mb-2 rounded-full border-2 ${!shouldGenerateClosingEntry ? 'border-white' : 'border-slate-800'}`} />
                                    <span className="text-xs font-bold uppercase tracking-wider">{t('periodClosing.skipStep')}</span>
                                </div>
                            </div>

                            <div className="flex justify-between pt-4">
                                <Button onClick={() => setStep('audit')} variant="outline" className="border-slate-800 text-slate-500 hover:text-white px-8 py-6 rounded-2xl font-bold">
                                    <ChevronLeft className="w-4 h-4 mr-2" /> {t('periodClosing.back')}
                                </Button>
                                <Button
                                    onClick={() => setStep('confirm')}
                                    className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-10 py-6 rounded-2xl shadow-xl shadow-blue-900/40"
                                >
                                    {t('periodClosing.continueToClosing')} <ArrowRight className="w-4 h-4 ml-2" />
                                </Button>
                            </div>
                        </div>
                    )}

                    {step === 'confirm' && (
                        <div className="space-y-8 animate-in slide-in-from-right-8 duration-300 text-center max-w-xl mx-auto">
                            <div className="p-8 bg-amber-500/10 border border-amber-500/20 rounded-[3rem] mb-6">
                                <AlertTriangle className="w-16 h-16 text-amber-500 mx-auto mb-4" />
                                <h3 className="text-2xl font-bold text-white mb-4 tracking-tight">{t('periodClosing.criticalWarning')}</h3>
                                <p className="text-slate-400 text-sm leading-relaxed font-medium">
                                    {t('periodClosing.warningDesc', { period: `${getMonthName(period.month)} ${year}` })}
                                </p>
                                {shouldGenerateClosingEntry && (
                                    <div className="mt-4 p-3 bg-blue-500/20 rounded-xl text-blue-400 text-xs font-bold flex items-center justify-center gap-2">
                                        <Zap className="w-3 h-3" /> {t('periodClosing.autoEntryGenerated')}
                                    </div>
                                )}
                            </div>

                            <div className="space-y-4">
                                <Button
                                    onClick={handleFinalClose}
                                    disabled={isLoading}
                                    className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-8 rounded-[2rem] shadow-2xl shadow-emerald-900/40 text-lg tracking-tight relative overflow-hidden group"
                                >
                                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
                                    {isLoading ? t('periodClosing.processing') : t('periodClosing.confirm')}
                                </Button>
                                <button onClick={onClose} className="text-xs text-slate-600 font-bold hover:text-white transition-all">
                                    {t('periodClosing.cancel')}
                                </button>
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer simple */}
                <div className="p-6 bg-slate-950/30 border-t border-white/5 flex justify-center items-center gap-2 text-[10px] font-medium text-slate-600">
                    <ShieldCheck className="w-3 h-3 text-emerald-500" />
                    {t('periodClosing.poweredBy')}
                </div>

            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { X, ChevronLeft, ChevronRight, CheckCircle, AlertCircle, Calendar, Flag, Settings, ShieldCheck, ArrowRight, Loader2 } from 'lucide-react';
import { accountingPeriodService } from '../../services/accounting/AccountingPeriodService';
import type { AccountingPeriod } from '../../services/accounting/AccountingPeriodService';
import TransactionValidationStep from './wizard-steps/TransactionValidationStep';
import BankReconciliationStep from './wizard-steps/BankReconciliationStep';
import PayrollValidationStep from './wizard-steps/PayrollValidationStep';
import AdjustmentsStep from './wizard-steps/AdjustmentsStep';
import TrialBalanceStep from './wizard-steps/TrialBalanceStep';
import ConfirmationStep from './wizard-steps/ConfirmationStep';

// ============================================================================
import { useLocale } from '../../i18n/useLocale';

// INTERFACES Y TIPOS
// ============================================================================

interface WizardState {
  currentStep: number;
  totalSteps: number;
  periodId: number;
  validationResults: Map<number, ValidationResult>;
  canProceed: boolean;
  isProcessing: boolean;
}

interface ValidationResult {
  stepId: number;
  status: 'pending' | 'passed' | 'warning' | 'error';
  checks: CheckResult[];
  timestamp: string;
}

interface CheckResult {
  id: string;
  label: string;
  status: 'pending' | 'passed' | 'warning' | 'error';
  message?: string;
  details?: any;
}

interface WizardStep {
  id: number;
  title: string;
  description: string;
  canSkip: boolean;
}

interface PeriodClosureWizardProps {
  periodId: number;
  isOpen: boolean;
  onClose: () => void;
  onComplete: () => void;
}

// ============================================================================
// DEFINICI├ôN DE PASOS
// ============================================================================

//   {
//     id: 6,
//     title: 'Confirmaci├│n y Cierre',
//     description: 'Revisar resumen y confirmar el cierre del per├¡odo',
//     canSkip: false
//   }
// ];

// ============================================================================
// COMPONENTE PRINCIPAL
// ============================================================================

export default function PeriodClosureWizard({
  periodId,
  isOpen,
  onClose,
  onComplete
}: PeriodClosureWizardProps) {
  const { t } = useLocale();

  // ============================================================================
  // DEFINICI├ôN DE PASOS (Inside component to use 't')
  // ============================================================================
  const WIZARD_STEPS: WizardStep[] = [
    {
      id: 1,
      title: t('accounting.closure.steps.transactions.title'),
      description: t('accounting.closure.steps.transactions.desc'),
      canSkip: false
    },
    {
      id: 2,
      title: t('accounting.closure.steps.reconciliation.title'),
      description: t('accounting.closure.steps.reconciliation.desc'),
      canSkip: false
    },
    {
      id: 3,
      title: t('accounting.closure.steps.payroll.title'),
      description: t('accounting.closure.steps.payroll.desc'),
      canSkip: false
    },
    {
      id: 4,
      title: t('accounting.closure.steps.adjustments.title'),
      description: t('accounting.closure.steps.adjustments.desc'),
      canSkip: false
    },
    {
      id: 5,
      title: t('accounting.closure.steps.trialBalance.title'),
      description: t('accounting.closure.steps.trialBalance.desc'),
      canSkip: false
    },
    {
      id: 6,
      title: t('accounting.closure.steps.confirmation.title'),
      description: t('accounting.closure.steps.confirmation.desc'),
      canSkip: false
    }
  ];

  // Estado del wizard
  const [wizardState, setWizardState] = useState<WizardState>({
    currentStep: 1,
    totalSteps: WIZARD_STEPS.length,
    periodId,
    validationResults: new Map(),
    canProceed: false,
    isProcessing: false
  });

  const [period, setPeriod] = useState<AccountingPeriod | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Cargar datos del per├¡odo
  useEffect(() => {
    if (isOpen && periodId) {
      loadPeriodData();
    }
  }, [isOpen, periodId]);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !wizardState.isProcessing) {
        onClose();
      }
      if (e.key === 'ArrowLeft' && wizardState.currentStep > 1 && !wizardState.isProcessing) {
        handlePreviousStep();
      }
      if (e.key === 'ArrowRight' && wizardState.currentStep < wizardState.totalSteps && wizardState.canProceed && !wizardState.isProcessing) {
        handleNextStep();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, wizardState, onClose]);

  const loadPeriodData = () => {
    const periods = accountingPeriodService.getPeriods({ id: periodId });
    if (periods.length > 0) {
      setPeriod(periods[0]);
    } else {
      setError(t('accounting.periods.errorLoading'));
    }
  };

  const handleNextStep = () => {
    if (wizardState.currentStep < wizardState.totalSteps) {
      setWizardState(prev => ({
        ...prev,
        currentStep: prev.currentStep + 1,
        canProceed: false
      }));
    }
  };

  const handlePreviousStep = () => {
    if (wizardState.currentStep > 1) {
      setWizardState(prev => ({
        ...prev,
        currentStep: prev.currentStep - 1
      }));
    }
  };

  const handleStepValidation = (result: ValidationResult) => {
    const newResults = new Map(wizardState.validationResults);
    newResults.set(result.stepId, result);

    const canProceed = result.status === 'passed' || result.status === 'warning';

    setWizardState(prev => ({
      ...prev,
      validationResults: newResults,
      canProceed
    }));
  };

  const handleClosePeriod = async () => {
    setWizardState(prev => ({ ...prev, isProcessing: true }));

    try {
      const result = accountingPeriodService.closePeriod(
        periodId,
        1,
        t('accounting.closure.steps.confirmation.check')
      );

      if (result.success) {
        onComplete();
      } else {
        setError(result.message || t('common.error'));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : t('common.errorUnknown'));
    } finally {
      setWizardState(prev => ({ ...prev, isProcessing: false }));
    }
  };

  if (!isOpen) return null;

  const currentStepData = WIZARD_STEPS[wizardState.currentStep - 1];

  return (
    <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-in fade-in duration-300">
      <div className="bg-slate-900 rounded-3xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col border border-slate-800 overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-8 bg-slate-950/50 border-b border-slate-800">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-500/10 rounded-2xl border border-blue-500/20">
              <Calendar className="w-8 h-8 text-blue-500" />
            </div>
            <div>
              <h2 className="text-2xl font-black text-white tracking-tighter uppercase">
                {t('accounting.closure.title')}: <span className="text-blue-500 font-serif italic lowercase tracking-tight">{period?.name || t('accounting.periods.sync')}</span>
              </h2>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1 flex items-center gap-2">
                <ShieldCheck className="w-3.5 h-3.5" />
                {t('accounting.closure.wizard.integrity')} ΓÇó {period && `${period.start_date} a ${period.end_date}`}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white rounded-xl transition-all active:scale-90"
            disabled={wizardState.isProcessing}
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Stepper Progress */}
        <div className="px-8 py-6 bg-slate-900/50 border-b border-slate-800/50">
          <div className="flex items-center justify-between max-w-4xl mx-auto">
            {WIZARD_STEPS.map((step, index) => (
              <React.Fragment key={step.id}>
                <div className="flex flex-col items-center">
                  <div
                    className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black transition-all duration-300 shadow-lg ${wizardState.currentStep === step.id
                      ? 'bg-blue-600 text-white scale-110 ring-4 ring-blue-500/20'
                      : wizardState.currentStep > step.id
                        ? 'bg-emerald-600 text-white'
                        : 'bg-slate-800 text-slate-500'
                      }`}
                  >
                    {wizardState.currentStep > step.id ? (
                      <CheckCircle className="w-6 h-6" />
                    ) : (
                      step.id
                    )}
                  </div>
                  <span className={`text-[9px] mt-3 font-black uppercase tracking-widest text-center max-w-[80px] ${wizardState.currentStep === step.id ? 'text-blue-400' : 'text-slate-600'
                    }`}>
                    {step.title.split(' ')[0]}
                  </span>
                </div>
                {index < WIZARD_STEPS.length - 1 && (
                  <div
                    className={`h-1 flex-1 mx-2 rounded-full transition-all duration-500 ${wizardState.currentStep > step.id
                      ? 'bg-emerald-600'
                      : 'bg-slate-800'
                      }`}
                  />
                )}
              </React.Fragment>
            ))}
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-8 bg-grid-slate-950/20 custom-scrollbar">
          <div className="mb-8 animate-in slide-in-from-left-4 duration-500">
            <h3 className="text-3xl font-black text-white tracking-tighter uppercase flex items-center gap-3">
              <div className="w-2 h-8 bg-blue-600 rounded-full" />
              {currentStepData.title}
            </h3>
            <p className="text-slate-400 font-bold mt-2 text-lg italic">{currentStepData.description}</p>
          </div>

          {error && (
            <div className="mb-8 p-5 bg-red-900/10 border-2 border-red-500/30 rounded-2xl flex items-start animate-in slide-in-from-top-4 shadow-xl shadow-red-950/20">
              <AlertCircle className="w-6 h-6 text-red-500 mr-4 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-xs font-black text-red-500 uppercase tracking-widest">{t('common.error')}</p>
                <p className="text-sm font-bold text-red-200 mt-1">{error}</p>
              </div>
            </div>
          )}

          {/* Render Step Components with Theme Support */}
          <div className="bg-slate-900/40 rounded-3xl border border-slate-800/50 p-1 shadow-inner backdrop-blur-sm">
            {wizardState.currentStep === 1 && (
              <TransactionValidationStep
                periodId={periodId}
                onValidationComplete={handleStepValidation}
              />
            )}
            {wizardState.currentStep === 2 && (
              <BankReconciliationStep
                periodId={periodId}
                onValidationComplete={handleStepValidation}
              />
            )}
            {wizardState.currentStep === 3 && (
              <PayrollValidationStep
                periodId={periodId}
                onValidationComplete={handleStepValidation}
              />
            )}
            {wizardState.currentStep === 4 && (
              <AdjustmentsStep
                periodId={periodId}
                onValidationComplete={handleStepValidation}
              />
            )}
            {wizardState.currentStep === 5 && (
              <TrialBalanceStep
                periodId={periodId}
                onValidationComplete={handleStepValidation}
              />
            )}
            {wizardState.currentStep === 6 && period && (
              <ConfirmationStep
                periodId={periodId}
                period={period}
                validationResults={Array.from(wizardState.validationResults.values())}
                onComplete={onComplete}
              />
            )}
          </div>
        </div>

        {/* Navigation Footer */}
        <div className="flex items-center justify-between p-8 border-t border-slate-800 bg-slate-950/80">
          <button
            onClick={handlePreviousStep}
            disabled={wizardState.currentStep === 1 || wizardState.isProcessing}
            className="group flex items-center px-6 py-3 text-slate-400 font-black uppercase text-xs tracking-widest bg-slate-900 border border-slate-800 rounded-xl hover:bg-slate-800 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95 shadow-lg"
          >
            <ChevronLeft className="w-5 h-5 mr-2 group-hover:-translate-x-1 transition-transform" />
            {t('accounting.closure.back')}
          </button>

          <div className="text-[11px] font-black text-slate-500 uppercase tracking-[0.3em]">
            {t('accounting.closure.wizard.phase')} {wizardState.currentStep} <span className="mx-2 text-slate-800">/</span> {wizardState.totalSteps}
          </div>

          {wizardState.currentStep < wizardState.totalSteps ? (
            <button
              onClick={handleNextStep}
              disabled={!wizardState.canProceed || wizardState.isProcessing}
              className="flex items-center px-8 py-3.5 text-white bg-blue-600 font-black uppercase text-xs tracking-[0.2em] rounded-xl hover:bg-blue-700 disabled:opacity-20 disabled:grayscale transition-all active:scale-95 shadow-xl shadow-blue-900/30 group"
            >
              {t('accounting.closure.next')}
              <ChevronRight className="w-5 h-5 ml-2 group-hover:translate-x-1 transition-transform" />
            </button>
          ) : (
            <button
              onClick={handleClosePeriod}
              disabled={!wizardState.canProceed || wizardState.isProcessing}
              className="flex items-center px-10 py-4 text-white bg-emerald-600 font-black uppercase text-sm tracking-[0.2em] rounded-2xl hover:bg-emerald-500 disabled:opacity-20 transition-all active:scale-95 shadow-2xl shadow-emerald-900/40 relative overflow-hidden group"
            >
              {wizardState.isProcessing ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin mr-3" />
                  {t('accounting.periods.sync')}
                </>
              ) : (
                <>
                  <Flag className="w-5 h-5 mr-3 group-hover:rotate-12 transition-transform" />
                  {t('accounting.closure.finish')}
                </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { useLocale } from '@/i18n/useLocale';
import {
  Calendar,
  Lock,
  Unlock,
  CheckCircle,
  AlertTriangle,
  Plus,
  Wand2,
  CalendarDays,
  ShieldAlert,
  History,
  ArrowRight,
  Loader2
} from 'lucide-react';
import { accountingPeriodService } from '@/services/accounting/AccountingPeriodService';
import type { AccountingPeriod } from '@/services/accounting/AccountingPeriodService';
import PeriodClosureWizard from './PeriodClosureWizard';

/**
 * PeriodManager
 * 
 * Componente para gestionar per├¡odos contables:
 * - Lista de per├¡odos con estado
 * - Creaci├│n de per├¡odos mensuales
 * - Cierre de per├¡odos
 * - Reapertura (solo admin)
 * - Bloqueo de per├¡odos
 */
export const PeriodManager: React.FC = () => {
  const { t, language } = useLocale();
  const [periods, setPeriods] = useState<AccountingPeriod[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [fiscalYear, setFiscalYear] = useState(new Date().getFullYear());
  const [showWizard, setShowWizard] = useState(false);
  const [wizardPeriodId, setWizardPeriodId] = useState<number | null>(null);

  useEffect(() => {
    loadPeriods();
  }, []);

  const loadPeriods = () => {
    try {
      setLoading(true);
      setError(null);
      const allPeriods = accountingPeriodService.getPeriods();
      setPeriods(allPeriods);
    } catch (err) {
      console.error('Error loading periods:', err);
      setError(err instanceof Error ? err.message : t('accounting.periods.errorLoading'));
    } finally {
      setLoading(false);
    }
  };

  const handleCreateMonthlyPeriods = () => {
    try {
      setLoading(true);
      setError(null);

      const result = accountingPeriodService.createMonthlyPeriods(fiscalYear, 1);

      if (result.success) {
        setSuccess(t('accounting.periods.creationSuccess', { count: result.count || 0, year: fiscalYear.toString() }));
        loadPeriods();
        setShowCreateForm(false);
        setTimeout(() => setSuccess(null), 5000);
      } else {
        setError(result.message);
      }
    } catch (err) {
      console.error('Error creating periods:', err);
      setError(err instanceof Error ? err.message : t('accounting.periods.errorLoading'));
    } finally {
      setLoading(false);
    }
  };

  const handleClosePeriod = (period: AccountingPeriod) => {
    if (!confirm(t('accounting.periods.closureConfirm', { name: period.name }))) {
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const validation = accountingPeriodService.validatePeriodClosure(period.id);

      if (!validation.canClose) {
        const errorMessages = [
          ...validation.errors,
          ...validation.warnings.map(w => `ΓÜá∩╕Å ${w}`)
        ];
        setError(`Imposible procesar cierre:\n${errorMessages.join('\n')}`);
        setLoading(false);
        return;
      }

      const result = accountingPeriodService.closePeriod(period.id, 1);

      if (result.success) {
        setSuccess(t('accounting.periods.closureSuccess', { name: period.name }));
        loadPeriods();
        setTimeout(() => setSuccess(null), 5000);
      } else {
        setError(result.message);
      }
    } catch (err) {
      console.error('Error closing period:', err);
      setError(err instanceof Error ? err.message : 'Fallo en motor de cierre');
    } finally {
      setLoading(false);
    }
  };

  const handleReopenPeriod = (period: AccountingPeriod) => {
    const reason = prompt(t('accounting.periods.auditReason'));
    if (!reason) return;

    try {
      setLoading(true);
      setError(null);

      const result = accountingPeriodService.reopenPeriod(period.id, 1, reason);

      if (result.success) {
        setSuccess(t('accounting.periods.reopenSuccess', { name: period.name }));
        loadPeriods();
        setTimeout(() => setSuccess(null), 5000);
      } else {
        setError(result.message);
      }
    } catch (err) {
      console.error('Error reopening period:', err);
      setError(err instanceof Error ? err.message : 'Error en protocolo de reapertura');
    } finally {
      setLoading(false);
    }
  };

  const handleLockPeriod = (period: AccountingPeriod) => {
    if (!confirm(t('accounting.periods.lockConfirm', { name: period.name }))) {
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const result = accountingPeriodService.lockPeriod(period.id, 1);

      if (result.success) {
        setSuccess(t('accounting.periods.lockSuccess', { name: period.name }));
        loadPeriods();
        setTimeout(() => setSuccess(null), 5000);
      } else {
        setError(result.message);
      }
    } catch (err) {
      console.error('Error locking period:', err);
      setError(err instanceof Error ? err.message : 'Error en bloqueo de seguridad');
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'open':
        return (
          <span className="px-3 py-1 rounded-lg text-xs font-bold bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 flex items-center justify-center gap-1.5 min-w-[100px]">
            <Unlock className="w-3 h-3" />
            {t('accounting.periods.statusOpen')}
          </span>
        );
      case 'closed':
        return (
          <span className="px-3 py-1 rounded-lg text-xs font-bold bg-orange-500/10 text-orange-400 border border-orange-500/20 flex items-center justify-center gap-1.5 min-w-[100px]">
            <CheckCircle className="w-3 h-3" />
            {t('accounting.periods.statusClosed')}
          </span>
        );
      case 'locked':
        return (
          <span className="px-3 py-1 rounded-lg text-xs font-bold bg-red-500/10 text-red-500 border border-red-500/20 flex items-center justify-center gap-1.5 min-w-[100px]">
            <Lock className="w-3 h-3" />
            {t('accounting.periods.statusLocked')}
          </span>
        );
      default:
        return null;
    }
  };

  if (loading && periods.length === 0) {
    return (
      <div className="flex items-center justify-center h-96 flex-col gap-4">
        <Loader2 className="w-12 h-12 text-blue-500 animate-spin" />
        <p className="text-slate-400 font-medium text-xs">{t('accounting.periods.sync')}</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight">
            <CalendarDays className="w-8 h-8 text-blue-500" />
            {t('accounting.periods.title')}
          </h2>
          <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mt-1 flex items-center gap-2">
            <ShieldAlert className="w-3.5 h-3.5 text-blue-500" />
            {t('accounting.periods.subtitle')}
          </p>
        </div>
        <button
          onClick={() => setShowCreateForm(true)}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl flex items-center gap-3 transition-all font-bold shadow-lg shadow-blue-900/40 active:scale-95"
        >
          <Plus className="w-5 h-5" />
          {t('accounting.periods.initYear')}
        </button>
      </div>

      {/* Alerts */}
      {(error || success) && (
        <div className={`p-6 rounded-2xl border-2 animate-in slide-in-from-top-4 ${error ? 'bg-red-900/10 border-red-500/30' : 'bg-emerald-900/10 border-emerald-500/30'
          }`}>
          <div className="flex items-start gap-4">
            {error ? <AlertTriangle className="w-6 h-6 text-red-500" /> : <CheckCircle className="w-6 h-6 text-emerald-500" />}
            <div>
              <p className={`text-xs font-bold uppercase tracking-wider mb-1 ${error ? 'text-red-500' : 'text-emerald-500'}`}>
                {error ? t('common.error') : t('common.success')}
              </p>
              <p className={`text-sm font-bold ${error ? 'text-red-200/80' : 'text-emerald-200/80'}`}>{error || success}</p>
            </div>
          </div>
        </div>
      )}

      {/* Summary Stat Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-slate-900/80 border border-slate-800 p-8 rounded-3xl group hover:border-emerald-500/30 transition-all shadow-xl">
          <div className="flex items-center justify-between mb-4">
            <span className="text-xs font-medium text-slate-500">{t('accounting.periods.openExecution')}</span>
            <Unlock className="w-5 h-5 text-emerald-500 group-hover:rotate-12 transition-transform" />
          </div>
          <div className="text-4xl font-black text-white">{periods.filter(p => p.status === 'open').length}</div>
          <p className="text-[10px] font-black text-slate-500 mt-2 uppercase tracking-wide">{t('accounting.periods.openDesc')}</p>
        </div>

        <div className="bg-slate-900/80 border border-slate-800 p-8 rounded-3xl group hover:border-orange-500/30 transition-all shadow-xl">
          <div className="flex items-center justify-between mb-4">
            <span className="text-xs font-medium text-slate-500">{t('accounting.periods.closedRecords')}</span>
            <CheckCircle className="w-5 h-5 text-orange-500 group-hover:scale-110 transition-transform" />
          </div>
          <div className="text-4xl font-bold text-white">{periods.filter(p => p.status === 'closed').length}</div>
          <p className="text-xs font-medium text-slate-500 mt-2 tracking-tight">{t('accounting.periods.closedDesc')}</p>
        </div>

        <div className="bg-slate-900/80 border border-slate-800 p-8 rounded-3xl group hover:border-red-500/30 transition-all shadow-xl">
          <div className="flex items-center justify-between mb-4">
            <span className="text-xs font-medium text-slate-500">{t('accounting.periods.totalImmutability')}</span>
            <Lock className="w-5 h-5 text-red-500 group-hover:-rotate-12 transition-transform" />
          </div>
          <div className="text-4xl font-bold text-white">{periods.filter(p => p.status === 'locked').length}</div>
          <p className="text-xs font-medium text-slate-500 mt-2 tracking-tight">{t('accounting.periods.lockedDesc')}</p>
        </div>
      </div>

      {/* Table Section */}
      <div className="bg-slate-900/40 border border-slate-800/60 rounded-3xl overflow-hidden shadow-2xl backdrop-blur-sm">
        <div className="px-8 py-6 bg-slate-950/50 border-b border-slate-800 flex items-center justify-between">
          <h2 className="text-lg font-bold text-white tracking-tight">{t('accounting.periods.scheduleTitle')}</h2>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-900 rounded-lg border border-slate-800">
              <div className="w-2 h-2 rounded-full bg-blue-500" />
              <span className="text-xs font-medium text-slate-400">{t('accounting.periods.year')}: {new Date().getFullYear()}</span>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          {periods.length === 0 ? (
            <div className="text-center py-20 bg-grid-slate-950/20">
              <Calendar className="w-20 h-20 text-slate-800 mx-auto mb-6" />
              <p className="text-slate-500 font-bold tracking-wide text-xs">{t('accounting.periods.initSubtitle')}</p>
            </div>
          ) : (
            <table className="w-full">
              <thead>
                <tr className="bg-slate-950/20 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-800">
                  <th className="text-left py-5 px-8">{t('accounting.periods.periodName')}</th>
                  <th className="text-left py-5 px-8">{t('accounting.periods.frequency')}</th>
                  <th className="text-left py-5 px-8">{t('accounting.periods.timeRange')}</th>
                  <th className="text-center py-5 px-8">{t('accounting.periods.legalStatus')}</th>
                  <th className="text-right py-5 px-8">{t('accounting.periods.operationalActions')}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/50">
                {periods.map((period) => (
                  <tr key={period.id} className="hover:bg-slate-800/30 transition-all group">
                    <td className="py-5 px-8">
                      <div className="flex items-center gap-3">
                        <div className={`w-1 h-6 rounded-full ${period.status === 'open' ? 'bg-emerald-500' : period.status === 'closed' ? 'bg-orange-500' : 'bg-red-500'
                          }`} />
                        <span className="text-sm font-bold text-white tracking-tight">{period.name}</span>
                      </div>
                    </td>
                    <td className="py-5 px-8">
                      <span className="text-xs font-medium text-slate-500 bg-slate-950/50 px-2 py-0.5 rounded border border-slate-800">{period.period_type}</span>
                    </td>
                    <td className="py-5 px-8">
                      <div className="flex items-center gap-2 text-xs font-mono text-slate-400">
                        <span>{new Date(period.start_date).toLocaleDateString(language === 'es' ? 'es-ES' : 'en-US')}</span>
                        <ArrowRight className="w-3 h-3 text-slate-700" />
                        <span>{new Date(period.end_date).toLocaleDateString(language === 'es' ? 'es-ES' : 'en-US')}</span>
                      </div>
                    </td>
                    <td className="py-5 px-8">
                      <div className="flex justify-center">
                        {getStatusBadge(period.status)}
                      </div>
                    </td>
                    <td className="py-5 px-8">
                      <div className="flex items-center justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                        {period.status === 'open' && (
                          <>
                            <button
                              onClick={() => {
                                setWizardPeriodId(period.id);
                                setShowWizard(true);
                              }}
                              className="bg-blue-600/10 hover:bg-blue-600 text-blue-500 hover:text-white font-bold text-[11px] px-4 py-2 rounded-xl border border-blue-500/20 transition-all flex items-center gap-2 shadow-lg"
                              disabled={loading}
                            >
                              <Wand2 className="w-3.5 h-3.5" />
                              {t('accounting.periods.closeWizard')}
                            </button>
                            <button
                              onClick={() => handleClosePeriod(period)}
                              className="bg-orange-500/10 hover:bg-orange-600 text-orange-400 hover:text-white font-bold text-[11px] px-4 py-2 rounded-xl border border-orange-500/20 transition-all flex items-center gap-2"
                              disabled={loading}
                            >
                              <CheckCircle className="w-3.5 h-3.5" />
                              {t('accounting.periods.fastClose')}
                            </button>
                          </>
                        )}
                        {period.status === 'closed' && (
                          <>
                            <button
                              onClick={() => handleReopenPeriod(period)}
                              className="bg-emerald-500/10 hover:bg-emerald-600 text-emerald-400 hover:text-white font-bold text-[11px] px-4 py-2 rounded-xl border border-emerald-500/20 transition-all flex items-center gap-2"
                              disabled={loading}
                            >
                              <Unlock className="w-3.5 h-3.5" />
                              {t('accounting.periods.reopen')}
                            </button>
                            <button
                              onClick={() => handleLockPeriod(period)}
                              className="bg-red-900/20 hover:bg-red-600 text-red-500 hover:text-white font-bold text-[11px] px-4 py-2 rounded-xl border border-red-500/30 transition-all flex items-center gap-2"
                              disabled={loading}
                            >
                              <Lock className="w-3.5 h-3.5" />
                              {t('accounting.periods.fullLock')}
                            </button>
                          </>
                        )}
                        {period.status === 'locked' && (
                          <span className="text-xs font-bold text-slate-700 flex items-center gap-2">
                            <History className="w-3 h-3" />
                            {t('accounting.periods.statusFinished')}
                          </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Forms/Modals with Standard Aesthetic */}
      {showCreateForm && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl flex items-center justify-center z-50 p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 rounded-3xl border border-slate-800 p-1 w-full max-w-sm overflow-hidden shadow-2xl">
            <div className="bg-slate-950/50 p-8 space-y-6">
              <div className="text-center space-y-2">
                <div className="w-16 h-16 bg-blue-600/10 rounded-2xl border border-blue-500/20 flex items-center justify-center mx-auto mb-4">
                  <CalendarDays className="w-8 h-8 text-blue-500" />
                </div>
                <h3 className="text-2xl font-bold text-white tracking-tight">{t('accounting.periods.initTitle')}</h3>
                <p className="text-slate-500 font-medium text-xs">{t('accounting.periods.initSubtitle')}</p>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="text-xs font-medium text-slate-600 ml-1">{t('accounting.periods.targetFiscalYear')}</label>
                  <input
                    type="number"
                    value={fiscalYear}
                    onChange={(e) => setFiscalYear(parseInt(e.target.value))}
                    className="w-full mt-2 px-5 py-4 bg-slate-900 border border-slate-800 rounded-2xl text-white font-medium text-lg focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500/50 outline-none transition-all"
                    min="2020"
                    max="2035"
                  />
                </div>

                <div className="flex flex-col gap-3 pt-4">
                  <button
                    onClick={handleCreateMonthlyPeriods}
                    className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold text-sm py-4 rounded-2xl transition-all shadow-xl shadow-blue-900/40 active:scale-95 flex items-center justify-center gap-2"
                    disabled={loading}
                  >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
                    {t('accounting.periods.generatePeriods')}
                  </button>
                  <button
                    onClick={() => setShowCreateForm(false)}
                    className="w-full bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white font-bold text-xs py-4 rounded-2xl transition-all"
                    disabled={loading}
                  >
                    {t('accounting.periods.abortOp')}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {showWizard && wizardPeriodId && (
        <PeriodClosureWizard
          periodId={wizardPeriodId}
          isOpen={showWizard}
          onClose={() => {
            setShowWizard(false);
            setWizardPeriodId(null);
          }}
          onComplete={() => {
            setShowWizard(false);
            setWizardPeriodId(null);
            setSuccess('Per├¡odo consolidado mediante asistente industrial.');
            loadPeriods();
            setTimeout(() => setSuccess(null), 5000);
          }}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import {
    RefreshCw,
    Download,
    ShieldAlert,
    Printer,
    CheckCircle,
    Database,
    Wrench,
    Search,
    FileSpreadsheet,
    Eye,
    X,
    Calendar,
    ArrowRight,
    ArrowDown,
    History,
    ShieldCheck,
    FileText,
    TrendingUp,
    TrendingDown,
    ChevronRight,
    Loader2
} from 'lucide-react';
import {
    getTrialBalanceReport,
    getAccountMovementsDetails,
    validateAccountingIntegrity,
    createChartOfAccount,
    getChartOfAccountByCode,
    createJournalEntry
} from '@/database/simple-db';
import type { TrialBalanceRow } from '../../modules/accounting/Accounting.types';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';

import { useLocale } from '../../i18n/useLocale';

export const TrialBalanceReport: React.FC = () => {
    const { t, language } = useLocale();
    // Estado para filtro de per├¡odo
    const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
    const [data, setData] = useState<TrialBalanceRow[]>([]);
    const [loading, setLoading] = useState(false);

    // Helper para formato de moneda
    const formatCurrency = (value: number): string => {
        return new Intl.NumberFormat(language === 'es' ? 'es-ES' : 'en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(value);
    };

    const formatNumber = (num: number) => {
        return new Intl.NumberFormat(language === 'es' ? 'es-ES' : 'en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(num);
    };

    // UI States
    const [selectedAccount, setSelectedAccount] = useState<string | null>(null);
    const [movements, setMovements] = useState<any[]>([]);
    const [showIntegrityModal, setShowIntegrityModal] = useState(false);
    const [integrityResult, setIntegrityResult] = useState<{ isValid: boolean; errors: string[] } | null>(null);

    const loadData = () => {
        setLoading(true);
        try {
            const [year, month] = period.split('-').map(Number);
            const reportData = getTrialBalanceReport(year, month);
            setData(reportData);
        } catch (error) {
            console.error('Error loading trial balance:', error);
        } finally {
            setTimeout(() => setLoading(false), 300); // Smooth transition
        }
    };

    useEffect(() => {
        loadData();
    }, [period]);

    const handleViewDetails = async (accountCode: string) => {
        const [year, month] = period.split('-').map(Number);
        const start = `${year}-${String(month).padStart(2, '0')}-01`;
        const end = new Date(year, month, 0).toISOString().split('T')[0];

        const details = getAccountMovementsDetails(accountCode, start, end);
        setMovements(details);
        setSelectedAccount(accountCode);
    };

    const handleRunIntegrity = () => {
        setLoading(true);
        setTimeout(() => {
            const result = validateAccountingIntegrity();
            setIntegrityResult(result);
            setShowIntegrityModal(true);
            setLoading(false);
        }, 800);
    };

    // Herramientas de Reparaci├│n
    const handleRepairAccounts = () => {
        const requiredAccounts = [
            { code: '1112', name: 'Banco Operativo', type: 'asset', normal_balance: 'debit', parent: '1100' },
            { code: '1121', name: 'Cuentas por Cobrar - Clientes', type: 'asset', normal_balance: 'debit', parent: '1100' },
            { code: '2121', name: 'Impuesto Ventas por Pagar (FL)', type: 'liability', normal_balance: 'credit', parent: '2100' },
            { code: '3100', name: 'Capital Social', type: 'equity', normal_balance: 'credit', parent: '3000' },
            { code: '4110', name: 'Ventas de Servicios', type: 'revenue', normal_balance: 'credit', parent: '4000' },
            { code: '5240', name: 'Gastos Legales', type: 'expense', normal_balance: 'debit', parent: '5000' }
        ];

        let created = 0;
        requiredAccounts.forEach(acc => {
            if (!getChartOfAccountByCode(acc.code)) {
                createChartOfAccount({
                    account_code: acc.code,
                    account_name: acc.name,
                    account_type: acc.type as any,
                    normal_balance: acc.normal_balance as any,
                    parent_account: acc.parent,
                    is_active: true
                });
                created++;
            }
        });

        if (created > 0) {
            loadData();
        }
    };

    const handleGenerateTestData = () => {
        if (!confirm(t('accounting.trialBalance.repairConfirmation'))) return;
        handleRepairAccounts();
        createJournalEntry({
            entry_date: `${period}-01`,
            description: 'Apertura de Cuenta - Capital Inicial',
            reference_number: 'OPEN-001'
        }, [
            { account_code: '1112', debit_amount: 50000, credit_amount: 0, description: 'Efectivo Inicial' },
            { account_code: '3100', debit_amount: 0, credit_amount: 50000, description: 'Aporte Capital' }
        ]);
        createJournalEntry({
            entry_date: `${period}-10`,
            description: 'Venta de Servicios Corporativos',
            reference_number: 'INV-1002'
        }, [
            { account_code: '1121', debit_amount: 1070, credit_amount: 0, description: 'CxC Cliente A' },
            { account_code: '4110', debit_amount: 0, credit_amount: 1000, description: 'Servicios Web' },
            { account_code: '2121', debit_amount: 0, credit_amount: 70, description: 'FL Sales Tax 7%' }
        ]);
        loadData();
    };

    const totalDebit = data.reduce((s, r) => s + r.period_debit, 0);
    const totalCredit = data.reduce((s, r) => s + r.period_credit, 0);
    const difference = Math.abs(totalDebit - totalCredit);
    const isBalanced = difference < 0.01;

    // Export PDF
    const handleDownloadPDF = () => {
        const doc = new jsPDF('l', 'mm', 'a4');
        doc.setFillColor(15, 23, 42); // slate-950
        doc.rect(0, 0, 297, 40, 'F');
        doc.setFontSize(24);
        doc.setTextColor(255);
        doc.text('ACCOUNT EXPRESS', 14, 20);
        doc.setFontSize(14);
        doc.text(`${t('accounting.trialBalance.title').toUpperCase()} - ${t('accounting.trialBalance.protocol').toUpperCase()}`, 14, 30);
        doc.setFontSize(10);
        doc.text(`${t('accounting.trialBalance.periodLabel')}: ${period}`, 145, 25);
        doc.text(`${t('accounting.trialBalance.sessionID')}: ${Math.random().toString(36).substring(7).toUpperCase()}`, 145, 30);
        const tableData = data.map(row => [
            row.number ? `${row.number} (${row.account_code})` : row.account_code,
            row.account_name,
            row.normal_balance.toUpperCase(),
            formatCurrency(row.initial_balance),
            formatCurrency(row.period_debit),
            formatCurrency(row.period_credit),
            formatCurrency(row.final_balance)
        ]);
        autoTable(doc, {
            startY: 45,
            head: [[
                t('accounting.trialBalance.codeHeader'),
                t('accounting.trialBalance.descHeader'),
                t('accounting.trialBalance.natHeader'),
                t('accounting.trialBalance.prevBalance'),
                t('accounting.trialBalance.debits'),
                t('accounting.trialBalance.credits'),
                t('accounting.trialBalance.closingBalance')
            ]],
            body: tableData,
            theme: 'grid',
            headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
            styles: { fontSize: 8 },
            columnStyles: {
                0: { cellWidth: 25 },
                1: { cellWidth: 'auto' },
                2: { cellWidth: 15, halign: 'center' },
                3: { halign: 'right' },
                4: { halign: 'right' },
                5: { halign: 'right' },
                6: { halign: 'right' }
            }
        });
        const finalY = (doc as any).lastAutoTable.finalY + 15;
        doc.setFontSize(10);
        doc.setTextColor(30);
        doc.text(`${t('accounting.trialBalance.debits').toUpperCase()}: ${formatCurrency(totalDebit)}`, 180, finalY);
        doc.text(`${t('accounting.trialBalance.credits').toUpperCase()}: ${formatCurrency(totalCredit)}`, 180, finalY + 8);
        doc.save(`AEX_TrialBalance_${period}.pdf`);
    };

    const handleDownloadExcel = () => {
        const wsData: string[][] = [
            [`ACCOUNT EXPRESS - ${t('accounting.trialBalance.title').toUpperCase()}`],
            [`${t('accounting.trialBalance.periodLabel')}: ${period}`],
            [
                t('accounting.trialBalance.codeHeader'),
                t('accounting.trialBalance.descHeader'),
                "NAT",
                t('accounting.trialBalance.prevBalance'),
                t('accounting.trialBalance.debits'),
                t('accounting.trialBalance.credits'),
                t('accounting.trialBalance.closingBalance')
            ]
        ];
        data.forEach(row => {
            wsData.push([
                row.number ? `${row.number} (${row.account_code})` : row.account_code,
                row.account_name,
                row.normal_balance.toUpperCase(),
                formatCurrency(row.initial_balance),
                formatCurrency(row.period_debit),
                formatCurrency(row.period_credit),
                formatCurrency(row.final_balance)
            ]);
        });
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(wsData);
        XLSX.utils.book_append_sheet(wb, ws, "Trial Balance");
        XLSX.writeFile(wb, `AEX_Balance_${period}.xlsx`);
    };

    return (
        <div className="space-y-10 animate-in fade-in duration-500 pb-20">
            {/* Legend & Stats Banner */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 p-1 bg-slate-900/50 border border-slate-800/80 rounded-[2rem] shadow-2xl backdrop-blur-xl">
                <div className="p-6 bg-slate-950/80 rounded-[1.8rem] border border-slate-800/50 space-y-3">
                    <div className="flex items-center justify-between">
                        <span className="text-xs font-medium text-slate-500">{t('accounting.trialBalance.openingBalance')}</span>
                        <History className="w-4 h-4 text-slate-600" />
                    </div>
                    <p className="text-xl font-bold text-white">{formatCurrency(data.reduce((s, r) => s + r.initial_balance, 0))}</p>
                </div>
                <div className="p-6 bg-slate-950/40 rounded-[1.8rem] border border-slate-800/20 space-y-3">
                    <div className="flex items-center justify-between">
                        <span className="text-xs font-medium text-emerald-500">{t('accounting.trialBalance.debitFlow')}</span>
                        <TrendingUp className="w-4 h-4 text-emerald-500" />
                    </div>
                    <p className="text-xl font-bold text-emerald-400">{formatCurrency(totalDebit)}</p>
                </div>
                <div className="p-6 bg-slate-950/40 rounded-[1.8rem] border border-slate-800/20 space-y-3">
                    <div className="flex items-center justify-between">
                        <span className="text-xs font-medium text-rose-500">{t('accounting.trialBalance.creditFlow')}</span>
                        <TrendingDown className="w-4 h-4 text-rose-500" />
                    </div>
                    <p className="text-xl font-bold text-rose-400">{formatCurrency(totalCredit)}</p>
                </div>
                <div className={`p-6 rounded-[1.8rem] border-2 space-y-3 ${isBalanced ? 'bg-emerald-900/10 border-emerald-500/20' : 'bg-rose-900/10 border-rose-500/30'}`}>
                    <div className="flex items-center justify-between">
                        <span className="text-xs font-bold uppercase tracking-wider">{t('accounting.trialBalance.integrity')}</span>
                        {isBalanced ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <ShieldAlert className="w-4 h-4 text-rose-500 animate-pulse" />}
                    </div>
                    <p className={`text-xl font-bold ${isBalanced ? 'text-emerald-500' : 'text-rose-500'}`}>{isBalanced ? t('accounting.trialBalance.calibrated') : `${t('accounting.trialBalance.error')}: ` + formatCurrency(difference)}</p>
                </div>
            </div>

            {/* Header section with Premium Controls */}
            <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
                <div className="flex items-center gap-5">
                    <div className="p-4 bg-blue-600/10 rounded-2xl border border-blue-500/20 shadow-blue-900/10 shadow-lg">
                        <FileSpreadsheet className="w-10 h-10 text-blue-500" />
                    </div>
                    <div>
                        <h2 className="text-3xl font-bold text-white tracking-tight">{t('accounting.trialBalance.title')}</h2>
                        <p className="text-slate-500 font-medium text-xs mt-1 flex items-center gap-2">
                            <Database className="w-3.5 h-3.5 text-blue-500" />
                            {t('accounting.trialBalance.subtitle')}
                        </p>
                    </div>
                </div>

                <div className="flex flex-wrap items-center gap-4">
                    {/* Period Selector styled as Control Panel */}
                    <div className="flex items-center gap-4 bg-slate-950 border border-slate-800 p-2 rounded-2xl shadow-inner">
                        <div className="bg-slate-900 p-2 rounded-xl">
                            <Calendar className="w-4 h-4 text-slate-500" />
                        </div>
                        <div className="flex flex-col pr-4">
                            <span className="text-xs font-medium text-slate-500">{t('accounting.trialBalance.periodLabel')}</span>
                            <input
                                type="month"
                                value={period}
                                onChange={(e) => setPeriod(e.target.value)}
                                className="bg-transparent text-white border-0 p-0 text-sm font-bold outline-none focus:ring-0"
                            />
                        </div>
                    </div>

                    <div className="flex gap-2 p-1 bg-slate-950 rounded-2xl border border-slate-800">
                        <button onClick={loadData} disabled={loading} className="p-3 hover:bg-slate-900 text-slate-500 hover:text-white rounded-xl transition-all">
                            <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
                        </button>
                        <button onClick={handleRunIntegrity} className="flex items-center gap-2 px-6 py-3 bg-blue-600/10 hover:bg-blue-600 text-blue-500 hover:text-white border border-blue-500/20 rounded-xl font-bold text-[11px] transition-all">
                            <ShieldCheck className="w-4 h-4" /> {t('accounting.trialBalance.diagnosis')}
                        </button>
                        <button onClick={handleDownloadExcel} className="flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl font-bold text-[11px] transition-all shadow-xl shadow-emerald-900/20">
                            <Download className="w-4 h-4" /> {t('accounting.trialBalance.exportExcel')}
                        </button>
                        <button onClick={handleDownloadPDF} className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold text-[11px] transition-all shadow-xl shadow-indigo-900/20">
                            <Printer className="w-4 h-4" /> {t('accounting.trialBalance.reportPDF')}
                        </button>
                    </div>
                </div>
            </div>

            {/* Main Data Registry */}
            <div className="rounded-[2.5rem] border border-slate-800 overflow-hidden bg-slate-950/20 backdrop-blur-2xl shadow-2xl">
                <table className="w-full text-sm text-left border-collapse">
                    <thead className="bg-slate-950 text-slate-600 font-bold uppercase tracking-wider text-xs border-b border-slate-800">
                        <tr>
                            <th className="px-10 py-6 text-center">N├ÜMERO GAAP / C├ôDIGO</th>
                            <th className="px-10 py-6">{t('accounting.trialBalance.descHeader')}</th>
                            <th className="px-10 py-6 text-center">{t('accounting.trialBalance.natHeader')}</th>
                            <th className="px-10 py-6 text-right">{t('accounting.trialBalance.prevBalance')}</th>
                            <th className="px-10 py-6 text-right">{t('accounting.trialBalance.debits')}</th>
                            <th className="px-10 py-6 text-right">{t('accounting.trialBalance.credits')}</th>
                            <th className="px-10 py-6 text-right">{t('accounting.trialBalance.closingBalance')}</th>
                            <th className="px-10 py-6 text-center">{t('accounting.trialBalance.protocol')}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/40">
                        {loading ? (
                            <tr>
                                <td colSpan={8} className="py-32 text-center">
                                    <div className="flex flex-col items-center gap-4">
                                        <Loader2 className="w-12 h-12 text-blue-500 animate-spin" />
                                        <p className="text-xs font-medium text-slate-500">{t('accounting.trialBalance.syncing')}</p>
                                    </div>
                                </td>
                            </tr>
                        ) : data.length === 0 ? (
                            <tr>
                                <td colSpan={8} className="px-10 py-24 text-center">
                                    <div className="space-y-4 opacity-30">
                                        <Database className="w-20 h-20 mx-auto text-slate-700" />
                                        <p className="font-bold text-xl text-slate-500 tracking-tight">{t('accounting.trialBalance.noMovements')}</p>
                                        <div className="flex justify-center gap-4 pt-4 no-print">
                                            <button onClick={handleRepairAccounts} className="text-xs font-bold text-slate-600 hover:text-white px-4 py-2 border border-slate-800 rounded-lg transition-all">{t('accounting.trialBalance.repairStructure')}</button>
                                            <button onClick={handleGenerateTestData} className="text-xs font-bold text-slate-600 hover:text-white px-4 py-2 border border-slate-800 rounded-lg transition-all">{t('accounting.trialBalance.injectDemo')}</button>
                                        </div>
                                    </div>
                                </td>
                            </tr>
                        ) : (
                            data.map((row, i) => (
                                <tr key={i} className="hover:bg-slate-900/30 transition-all group">
                                    <td className="px-10 py-6">
                                        <span className="font-mono text-xs text-blue-400 font-bold bg-blue-500/5 px-3 py-1.5 rounded-xl border border-blue-500/10 flex flex-col items-center">
                                            <span>{row.number || 'N/A'}</span>
                                            <span className="text-[9px] text-slate-500">{row.account_code}</span>
                                        </span>
                                    </td>
                                    <td className="px-10 py-6">
                                        <div className="space-y-1">
                                            <p className="font-bold text-slate-200 group-hover:text-white transition-colors">{row.account_name}</p>
                                            <div className="flex items-center gap-2">
                                                <span className="text-[10px] text-slate-500 font-medium">{row.account_type}</span>
                                                <ChevronRight className="w-2.5 h-2.5 text-slate-800" />
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-10 py-6 text-center">
                                        <div className={`text-[10px] font-bold px-2 py-0.5 rounded-lg border flex items-center justify-center gap-1.5 min-w-[50px] mx-auto ${row.normal_balance === 'debit'
                                            ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400'
                                            : 'bg-rose-500/10 border-rose-500/30 text-rose-400'
                                            }`}>
                                            <div className={`w-1 h-1 rounded-full ${row.normal_balance === 'debit' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                                            {row.normal_balance === 'debit' ? 'DB' : 'CR'}
                                        </div>
                                    </td>
                                    <td className="px-10 py-6 text-right font-mono text-[11px] text-slate-500 font-bold">
                                        {formatCurrency(row.initial_balance)}
                                    </td>
                                    <td className="px-10 py-6 text-right font-mono font-bold text-emerald-400 text-sm">
                                        {row.period_debit > 0 ? formatCurrency(row.period_debit) : '-'}
                                    </td>
                                    <td className="px-10 py-6 text-right font-mono font-bold text-rose-400 text-sm">
                                        {row.period_credit > 0 ? formatCurrency(row.period_credit) : '-'}
                                    </td>
                                    <td className="px-10 py-6 text-right font-mono font-bold text-slate-100 bg-slate-900/30 group-hover:bg-blue-600/10 transition-colors">
                                        <span className="px-4 py-2 rounded-xl border border-slate-800 text-sm group-hover:border-blue-500/30 transition-all">
                                            {formatCurrency(row.final_balance)}
                                        </span>
                                    </td>
                                    <td className="px-10 py-6 text-center">
                                        <button
                                            onClick={() => handleViewDetails(row.account_code)}
                                            className="p-3 bg-slate-950 hover:bg-blue-600 text-slate-600 hover:text-white rounded-2xl transition-all border border-slate-800 hover:border-blue-500 active:scale-95 group/btn"
                                            title={t('accounting.trialBalance.viewLedger')}
                                        >
                                            <Search className="w-4 h-4 group-hover/btn:scale-110 transition-transform" />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                    <tfoot className="bg-slate-950/80 border-t-2 border-slate-800">
                        <tr>
                            <td colSpan={4} className="px-10 py-10 text-right font-bold uppercase text-xs tracking-wider text-slate-600">{t('accounting.trialBalance.auditConsolidation')}</td>
                            <td className="px-10 py-10 text-right">
                                <p className="text-xs text-emerald-500 font-bold uppercase tracking-wider mb-1.5">{t('accounting.trialBalance.debitConsumption')}</p>
                                <p className="font-mono text-2xl font-bold text-emerald-400 tracking-tight">
                                    {formatCurrency(totalDebit)}
                                </p>
                            </td>
                            <td className="px-10 py-10 text-right">
                                <p className="text-xs text-rose-500 font-bold uppercase tracking-wider mb-1.5">{t('accounting.trialBalance.creditConsumption')}</p>
                                <p className="font-mono text-2xl font-bold text-rose-400 tracking-tight">
                                    {formatCurrency(totalCredit)}
                                </p>
                            </td>
                            <td colSpan={2} className="px-10 py-10 text-center">
                                <div className={`inline-flex flex-col items-center gap-1.5 px-10 py-5 rounded-[2rem] border-2 shadow-2xl transition-all ${isBalanced
                                    ? 'bg-emerald-500/5 border-emerald-500/20 text-emerald-500'
                                    : 'bg-rose-500/5 border-rose-500/40 text-rose-400 animate-pulse'
                                    }`}>
                                    <div className="flex items-center gap-3">
                                        {isBalanced ? <CheckCircle className="w-6 h-6" /> : <ShieldAlert className="w-6 h-6" />}
                                        <span className="font-bold text-sm uppercase tracking-wider">
                                            {isBalanced ? t('accounting.trialBalance.integrityBook') : t('accounting.trialBalance.criticalImbalance')}
                                        </span>
                                    </div>
                                    {!isBalanced && (
                                        <p className="text-xs font-bold text-rose-500/80 uppercase tracking-wide">{t('accounting.trialBalance.diff')}: ${formatNumber(difference)}</p>
                                    )}
                                </div>
                            </td>
                        </tr>
                    </tfoot>
                </table>
            </div>

            {/* Drill-down Modal (Account History) - Modern Backlit Aesthetic */}
            {selectedAccount && (
                <div className="fixed inset-0 z-[200] bg-slate-950/90 backdrop-blur-2xl flex items-center justify-center p-6 animate-in fade-in duration-300">
                    <div className="w-full max-w-6xl bg-slate-900/80 rounded-[3rem] border border-slate-800 shadow-[0_0_150px_rgba(59,130,246,0.1)] h-[85vh] flex flex-col overflow-hidden animate-in slide-in-from-bottom-8 duration-500">
                        <header className="px-12 py-8 bg-slate-950/50 border-b border-slate-800 flex items-center justify-between">
                            <div className="flex items-center gap-6">
                                <div className="p-4 bg-blue-600/10 rounded-[1.5rem] border border-blue-500/20">
                                    <Eye className="w-8 h-8 text-blue-500" />
                                </div>
                                <div>
                                    <h3 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
                                        {t('accounting.trialBalance.auxHistory')}: <span className="bg-gradient-to-r from-blue-400 to-indigo-400 bg-clip-text text-transparent">{selectedAccount}</span>
                                    </h3>
                                    <p className="text-slate-500 text-xs font-medium mt-1 flex items-center gap-2">
                                        <FileText className="w-3.5 h-3.5 text-blue-500" /> {t('accounting.trialBalance.registeredTrans')}
                                    </p>
                                </div>
                            </div>
                            <button onClick={() => setSelectedAccount(null)} className="p-3 bg-slate-800 hover:bg-red-500/20 text-slate-500 hover:text-red-500 rounded-full transition-all active:scale-90 border border-slate-700">
                                <X className="w-6 h-6" />
                            </button>
                        </header>

                        <div className="flex-1 overflow-auto px-4 custom-scrollbar">
                            <table className="w-full text-left">
                                <thead className="sticky top-0 bg-slate-900 border-b border-slate-800 z-10">
                                    <tr className="text-xs font-bold text-slate-600 uppercase tracking-wider">
                                        <th className="px-12 py-6">{t('accounting.trialBalance.effectiveDate')}</th>
                                        <th className="px-12 py-6">{t('accounting.trialBalance.reference')}</th>
                                        <th className="px-12 py-6">{t('accounting.trialBalance.concept')}</th>
                                        <th className="px-12 py-6 text-right">{t('accounting.trialBalance.debitAction')}</th>
                                        <th className="px-12 py-6 text-right">{t('accounting.trialBalance.creditAction')}</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-800/40">
                                    {movements.length === 0 ? (
                                        <tr><td colSpan={5} className="py-40 text-center text-slate-700 font-bold uppercase tracking-wider italic opacity-30">{t('accounting.trialBalance.zeroMovements')}</td></tr>
                                    ) : (
                                        movements.map((move, i) => (
                                            <tr key={i} className="hover:bg-slate-800/30 transition-all group">
                                                <td className="px-12 py-6">
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-1.5 h-1.5 rounded-full bg-blue-500/50" />
                                                        <span className="font-mono text-xs text-slate-400 font-bold">{new Date(move.date).toLocaleDateString(language === 'es' ? 'es-ES' : 'en-US')}</span>
                                                    </div>
                                                </td>
                                                <td className="px-12 py-6 font-bold text-[11px] text-blue-500 tracking-tight">{move.reference}</td>
                                                <td className="px-12 py-6 text-slate-300 font-bold text-sm tracking-tight">{move.description}</td>
                                                <td className="px-12 py-6 text-right font-mono font-bold text-emerald-400 text-lg">
                                                    {move.debit > 0 ? formatNumber(move.debit) : '-'}
                                                </td>
                                                <td className="px-12 py-6 text-right font-mono font-bold text-rose-400 text-lg">
                                                    {move.credit > 0 ? formatNumber(move.credit) : '-'}
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>

                        <footer className="px-12 py-10 bg-slate-950/80 border-t border-slate-800 flex justify-between items-center">
                            <div className="flex gap-4">
                                <div className="px-4 py-2 bg-slate-900 border border-slate-800 rounded-xl">
                                    <span className="text-xs font-medium text-slate-500 block mb-1">{t('accounting.trialBalance.totalRecords')}</span>
                                    <span className="text-white font-bold">{movements.length} {t('accounting.trialBalance.entries')}</span>
                                </div>
                            </div>
                            <div className="flex gap-12">
                                <div className="text-right">
                                    <p className="text-xs font-bold text-emerald-500 uppercase tracking-wider mb-1">{t('accounting.trialBalance.closingDebit')}</p>
                                    <p className="text-3xl font-bold text-emerald-400 tracking-tight">{formatNumber(movements.reduce((a, c) => a + c.debit, 0))}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-xs font-bold text-rose-500 uppercase tracking-wider mb-1">{t('accounting.trialBalance.closingCredit')}</p>
                                    <p className="text-3xl font-bold text-rose-400 tracking-tight">{formatNumber(movements.reduce((a, c) => a + c.credit, 0))}</p>
                                </div>
                            </div>
                        </footer>
                    </div>
                </div>
            )}

            {/* Integrity Diagnosis Modal */}
            {showIntegrityModal && integrityResult && (
                <div className="fixed inset-0 z-[250] bg-slate-950/95 backdrop-blur-xl flex items-center justify-center p-6 animate-in fade-in duration-300">
                    <div className="w-full max-w-2xl bg-slate-900 rounded-[3rem] border border-slate-800 shadow-2xl p-1 overflow-hidden animate-in zoom-in-95 duration-500">
                        <div className="bg-slate-950/50 p-12 space-y-10">
                            <header className="text-center space-y-4">
                                <div className={`w-24 h-24 mx-auto rounded-[2rem] flex items-center justify-center border-4 shadow-2xl ${integrityResult.isValid
                                    ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500 shadow-emerald-900/20'
                                    : 'bg-rose-500/10 border-rose-500/20 text-rose-500 shadow-rose-900/20'
                                    }`}>
                                    {integrityResult.isValid ? <CheckCircle className="w-12 h-12" /> : <ShieldAlert className="w-12 h-12" />}
                                </div>
                                <h3 className="text-3xl font-bold text-white tracking-tight">{t('accounting.trialBalance.netDiagnosis')}</h3>
                                <p className="text-slate-500 font-medium text-xs mt-1">{t('accounting.trialBalance.verification')}</p>
                            </header>

                            <div className="space-y-6">
                                {integrityResult.isValid ? (
                                    <div className="p-8 bg-emerald-500/5 rounded-3xl border border-emerald-500/10 text-center">
                                        <p className="font-bold text-emerald-500 text-lg tracking-tight mb-2">{t('accounting.trialBalance.perfectSync')}</p>
                                        <p className="text-xs font-medium text-emerald-200/40 italic leading-relaxed">
                                            {t('accounting.trialBalance.syncDesc')}
                                        </p>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        <p className="text-xs font-bold text-rose-500 uppercase tracking-wider pl-2 flex items-center gap-2">
                                            <ShieldAlert className="w-3.5 h-3.5" /> {t('accounting.trialBalance.inconsistencyLog')}
                                        </p>
                                        <div className="max-h-56 overflow-auto bg-black/40 p-6 rounded-3xl border border-slate-800 space-y-3 custom-scrollbar">
                                            {integrityResult.errors.map((err, i) => (
                                                <div key={i} className="flex gap-4 p-4 bg-rose-500/5 rounded-2xl border border-rose-500/10 hover:border-rose-500/30 transition-colors">
                                                    <X className="w-4 h-4 text-rose-500 shrink-0 mt-0.5" />
                                                    <p className="text-xs text-rose-200 font-mono font-bold leading-relaxed">{err}</p>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                <button
                                    onClick={() => setShowIntegrityModal(false)}
                                    className="w-full bg-slate-800 hover:bg-slate-700 text-white font-bold text-sm py-6 rounded-3xl transition-all shadow-xl active:scale-95 border border-slate-700"
                                >
                                    {t('accounting.trialBalance.finishScan')}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import ClosureChecklist, { ChecklistItem, ValidationResult } from '../ClosureChecklist';
import { accountingPeriodService } from '../../../services/accounting/AccountingPeriodService';
import { Info, Lightbulb, Settings2, ArrowRight } from 'lucide-react';

interface AdjustmentsStepProps {
  periodId: number;
  onValidationComplete: (result: ValidationResult) => void;
}

import { useLocale } from '../../../i18n/useLocale';

export default function AdjustmentsStep({
  periodId,
  onValidationComplete
}: AdjustmentsStepProps) {
  const { t } = useLocale();
  const [checks, setChecks] = useState<ChecklistItem[]>([
    {
      id: 'depreciation-calculated',
      label: t('accounting.closure.steps.adjustments.checks.depreciation'),
      status: 'pending',
      message: undefined,
      action: {
        label: t('accounting.closure.steps.adjustments.checks.calcDepreciation'),
        onClick: () => window.location.href = '/assets/fixed-assets'
      }
    },
    {
      id: 'adjustment-entries-recorded',
      label: t('accounting.closure.steps.adjustments.checks.entriesRecorded'),
      status: 'pending',
      message: undefined,
      action: {
        label: t('accounting.closure.steps.adjustments.checks.createEntry'),
        onClick: () => window.location.href = '/accounting/journal-entries'
      }
    },
    {
      id: 'accruals-recorded',
      label: t('accounting.closure.steps.adjustments.checks.accruals'),
      status: 'pending',
      message: undefined
    },
    {
      id: 'inventory-reconciled',
      label: t('accounting.closure.steps.adjustments.checks.inventory'),
      status: 'pending',
      message: undefined,
      action: {
        label: t('accounting.closure.steps.adjustments.checks.goToInventory'),
        onClick: () => window.location.href = '/inventory'
      }
    }
  ]);

  useEffect(() => {
    const runValidations = async () => {
      const result = accountingPeriodService.validateAdjustments(periodId);

      const updatedChecks = result.checks.map(check => {
        const originalCheck = checks.find(c => c.id === check.id);
        return {
          ...check,
          action: originalCheck?.action
        };
      });

      setChecks(updatedChecks);

      onValidationComplete({
        stepId: 3,
        status: result.status,
        checks: updatedChecks,
        timestamp: result.timestamp
      });
    };

    runValidations();
  }, [periodId, onValidationComplete, t]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-purple-600/10 border-l-4 border-purple-500 rounded-xl p-5 flex items-start gap-4 shadow-lg shadow-purple-950/20">
        <Settings2 className="w-6 h-6 text-purple-500 mt-0.5 shrink-0" />
        <p className="text-sm font-bold text-purple-200/80 leading-relaxed">
          <span className="text-white font-bold tracking-tight mr-2">{t('accounting.closure.steps.adjustments.phaseTitle')}:</span>
          {t('accounting.closure.steps.adjustments.phaseDesc')}
        </p>
      </div>

      <ClosureChecklist
        periodId={periodId}
        stepId={3}
        checks={checks}
        autoRun={false}
        onValidationComplete={onValidationComplete}
      />

      <div className="bg-slate-900/50 rounded-2xl p-6 border border-slate-800 shadow-inner group">
        <div className="flex items-center gap-2 mb-4">
          <Lightbulb className="w-4 h-4 text-orange-500" />
          <h5 className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-slate-300 transition-colors">{t('accounting.closure.steps.adjustments.bestPractices')}</h5>
        </div>
        <ul className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {t<string[]>('accounting.closure.steps.adjustments.tips').map((tip, i) => (
            <li key={i} className="flex items-center gap-3 text-xs font-medium text-slate-400">
              <div className="w-1.5 h-1.5 rounded-full bg-purple-500/30 group-hover:bg-purple-500 transition-all shadow-lg" />
              {tip}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

