import React, { useState, useEffect } from 'react';
import { RepairHistoryEntry, RepairStats } from '../../types/ai-repair';
import { AIRepairService } from '../../services/ai/AIRepairService';
import { ProductionLogger } from '../../core/logging/ProductionLogger';
import { useLocale } from '../../i18n/useLocale';

interface RepairHistoryPanelProps {
    repairService: AIRepairService;
}

/**
 * Panel de historial de reparaciones ejecutadas
 */
export function RepairHistoryPanel({ repairService }: RepairHistoryPanelProps) {
    const { t } = useLocale();
    const [history, setHistory] = useState<RepairHistoryEntry[]>([]);
    const [stats, setStats] = useState<RepairStats | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        loadHistory();
    }, []);

    const loadHistory = async () => {
        setIsLoading(true);
        try {
            const historyData = await repairService.getRepairHistory(50);
            const statsData = repairService.getStats();

            setHistory(historyData);
            setStats(statsData);

            ProductionLogger.info('RepairHistoryPanel', 'History loaded', {
                count: historyData.length
            });
        } catch (error) {
            ProductionLogger.error('RepairHistoryPanel', 'Failed to load history', error as Error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleRollback = async (repairId: string) => {
        if (!confirm(t('aiAssistant.history.rollbackConfirm'))) {
            return;
        }

        try {
            // await repairService.rollbackToBackupPoint(repairId);
            alert(t('aiAssistant.history.rollbackNotImplemented'));
            await loadHistory();
        } catch (error) {
            ProductionLogger.error('RepairHistoryPanel', 'Rollback failed', error as Error);
            alert(`Error al revertir: ${(error as Error).message}`);
        }
    };

    if (isLoading) {
        return (
            <div className="p-4 text-center text-slate-600">
                {t('aiAssistant.history.loading')}
            </div>
        );
    }

    return (
        <div className="p-4">
            {/* Stats Summary */}
            {stats && (
                <div className="grid grid-cols-4 gap-4 mb-6">
                    <StatCard
                        label={t('aiAssistant.history.totalProposals')}
                        value={stats.totalProposals}
                        icon="≡ƒôè"
                    />
                    <StatCard
                        label={t('aiAssistant.history.executed')}
                        value={stats.executed}
                        icon="Γ£à"
                        color="green"
                    />
                    <StatCard
                        label={t('aiAssistant.history.rejected')}
                        value={stats.rejected}
                        icon="Γ¥î"
                        color="red"
                    />
                    <StatCard
                        label={t('aiAssistant.history.successRate')}
                        value={`${(stats.successRate * 100).toFixed(1)}%`}
                        icon="≡ƒÄ»"
                        color="blue"
                    />
                </div>
            )}

            {/* History List */}
            <div className="space-y-2">
                <h3 className="font-bold text-lg mb-3">{t('aiAssistant.history.title')}</h3>

                {history.length === 0 ? (
                    <div className="text-center text-slate-600 py-8">
                        {t('aiAssistant.history.empty')}
                    </div>
                ) : (
                    history.map((entry) => (
                        <HistoryEntry
                            key={entry.id}
                            entry={entry}
                            onRollback={handleRollback}
                        />
                    ))
                )}
            </div>
        </div>
    );
}

function StatCard({
    label,
    value,
    icon,
    color = 'gray'
}: {
    label: string;
    value: string | number;
    icon: string;
    color?: 'gray' | 'green' | 'red' | 'blue';
}) {
    const colors = {
        gray: 'bg-gray-100 border-gray-300',
        green: 'bg-green-50 border-green-300',
        red: 'bg-red-50 border-red-300',
        blue: 'bg-blue-50 border-blue-300',
    };

    return (
        <div className={`border-2 rounded-lg p-3 ${colors[color]}`}>
            <div className="text-2xl mb-1">{icon}</div>
            <div className="text-2xl font-black tracking-tight">{value}</div>
            <div className="text-sm text-slate-700">{label}</div>
        </div>
    );
}

function HistoryEntry({
    entry,
    onRollback
}: {
    entry: RepairHistoryEntry;
    onRollback: (id: string) => void;
}) {
    const { t } = useLocale();
    const statusColors = {
        pending: 'bg-gray-100',
        approved: 'bg-blue-100',
        rejected: 'bg-red-100',
        executed: 'bg-green-100',
        failed: 'bg-red-200',
        rolled_back: 'bg-orange-100'
    };

    const severityColors = {
        low: 'text-blue-600',
        medium: 'text-yellow-600',
        high: 'text-orange-600',
        critical: 'text-red-600'
    };

    return (
        <div className={`border rounded p-3 ${statusColors[entry.status]}`}>
            <div className="flex items-center justify-between">
                <div className="flex-1">
                    <div className="flex items-center gap-2">
                        <span className={`font-semibold ${severityColors[entry.severity]}`}>
                            {entry.issueTitle}
                        </span>
                        <span className="text-xs text-slate-600">
                            {entry.category}
                        </span>
                    </div>
                    <div className="text-xs text-slate-700 mt-1">
                        {entry.timestamp.toLocaleString()}
                        {entry.userId && ` ΓÇó Usuario ID: ${entry.userId}`}
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <span className="text-xs px-2 py-1 bg-white rounded border">
                        {entry.status}
                    </span>

                    {entry.canRollback && (
                        <button
                            onClick={() => onRollback(entry.id)}
                            className="text-xs px-2 py-1 bg-orange-500 hover:bg-orange-600 text-white rounded"
                        >
                            {t('aiAssistant.history.rollback')}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
}

/**
 * UNIFIED AI ASSISTANT - COMPONENTE PRINCIPAL UNIFICADO
 * 
 * Reemplaza IAPanel.tsx y FinancialAssistantChat.tsx
 * Tres modos: Dashboard, Chat, Guide
 * Acceso exclusivo a vistas _summary (solo lectura)
 */

import React, { useState, useEffect, useRef } from 'react';
import {
    Brain,
    MessageSquare,
    BarChart3,
    BookOpen,
    X,
    Send,
    RefreshCw,
    AlertCircle,
    ChevronRight,
    Search,
    HelpCircle,
    Lightbulb
} from 'lucide-react';
import { AIFactory, AIResponse } from '../../services/ai/AIFactory';
import { SYSTEM_GUIDES, QUICK_OPERATIONS } from '../../knowledge/SystemKnowledge';
import { logger } from '../../core/logging/SystemLogger';
import { useLocale } from '../../i18n/useLocale';

type AssistantMode = 'dashboard' | 'chat' | 'guide';

interface Message {
    id: number;
    role: 'user' | 'assistant';
    content: string;
    timestamp: Date;
    type?: 'query' | 'response' | 'error' | 'guide';
}

interface UnifiedAssistantProps {
    isOpen: boolean;
    onClose: () => void;
    initialMode?: AssistantMode;
    // Real-time data props
    stats?: {
        customers: number;
        invoices: number;
        revenue: number;
        suppliers: number;
        bills: number;
        expenses: number;
    };
    transactionCount?: number;
    auditStatus?: {
        healthy: boolean;
        lastEvent: string;
        integrityScore: number;
    };
    complianceMetrics?: {
        taxCompliance: number;
        dr15Status: string;
        pendingForms: number;
    };
}

export const UnifiedAssistant: React.FC<UnifiedAssistantProps> = ({
    isOpen,
    onClose,
    initialMode = 'dashboard',
    stats,
    transactionCount,
    auditStatus,
    complianceMetrics
}) => {
    const { t } = useLocale();
    const [mode, setMode] = useState<AssistantMode>(initialMode);
    const [messages, setMessages] = useState<Message[]>([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [analysis, setAnalysis] = useState<AIResponse | null>(null);
    const [selectedGuide, setSelectedGuide] = useState<string | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    useEffect(() => {
        if (isOpen && mode === 'dashboard') {
            loadDashboardAnalysis();
        }
    }, [isOpen, mode]);

    // Cargar an├ílisis del dashboard
    const loadDashboardAnalysis = async () => {
        setIsLoading(true);
        try {
            // Sincronizar conocimiento con el estado actual del sistema (Auto-Actualizaci├│n)
            await AIFactory.sync();

            const result = await AIFactory.processQuery('resumen salud financiera');
            setAnalysis(result as any);
            logger.info('UnifiedAssistant', 'dashboard_loaded', 'An├ílisis y sincronizaci├│n completados');
        } catch (error) {
            logger.error('UnifiedAssistant', 'dashboard_error', 'Error cargando an├ílisis', {}, error as Error);
        } finally {
            setIsLoading(false);
        }
    };

    // Procesar consulta de chat
    const handleSendMessage = async () => {
        if (!input.trim()) return;

        const userMessage: Message = {
            id: Date.now(),
            role: 'user',
            content: input,
            timestamp: new Date(),
            type: 'query'
        };

        setMessages(prev => [...prev, userMessage]);
        setInput('');
        setIsLoading(true);

        try {
            const response = await AIFactory.processQuery(input);

            const assistantMessage: Message = {
                id: Date.now() + 1,
                role: 'assistant',
                content: response.content,
                timestamp: new Date(),
                type: 'response'
            };

            setMessages(prev => [...prev, assistantMessage]);
        } catch (error) {
            const errorMessage: Message = {
                id: Date.now() + 1,
                role: 'assistant',
                content: `ΓÜá∩╕Å Error: ${error instanceof Error ? error.message : t('aiAssistant.proposals.rejectError', { error: 'Unknown' })}`,
                timestamp: new Date(),
                type: 'error'
            };
            setMessages(prev => [...prev, errorMessage]);
        } finally {
            setIsLoading(false);
            inputRef.current?.focus();
        }
    };

    // Ejecutar gu├¡a r├ípida
    const handleQuickGuide = (guideKey: string) => {
        const guide = SYSTEM_GUIDES[guideKey];
        if (!guide) return;

        const guideMessage: Message = {
            id: Date.now(),
            role: 'assistant',
            content: formatGuide(guide),
            timestamp: new Date(),
            type: 'guide'
        };

        setMessages(prev => [...prev, guideMessage]);
        setMode('chat');
    };

    const formatGuide = (guide: { title: string; steps: string[]; tips?: string[] }) => {
        let content = `≡ƒôû **${guide.title}**\n\n`;
        content += `**${t('aiAssistant.steps')}:**\n`;
        guide.steps.forEach((step, index) => {
            content += `${index + 1}. ${step}\n`;
        });
        if (guide.tips && guide.tips.length > 0) {
            content += `\n≡ƒÆí **${t('aiAssistant.tips')}:**\n`;
            guide.tips.forEach(tip => {
                content += `ΓÇó ${tip}\n`;
            });
        }
        return content;
    };

    const handleKeyPress = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSendMessage();
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-slate-900 rounded-2xl w-full max-w-4xl h-[90vh] flex flex-col shadow-2xl border border-white/10">

                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-white/10">
                    <div className="flex items-center space-x-3">
                        <div className="p-2 bg-blue-600 rounded-lg">
                            <Brain className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <h2 className="text-xl font-black tracking-tight text-white">{t('aiAssistant.title')}</h2>
                            <p className="text-sm text-slate-500">{t('aiAssistant.readOnly')}</p>
                        </div>
                    </div>

                    {/* Mode Selector */}
                    <div className="flex items-center space-x-2 bg-white/10 rounded-lg p-1">
                        <button
                            onClick={() => setMode('dashboard')}
                            className={`flex items-center space-x-2 px-3 py-2 rounded-md transition-colors ${mode === 'dashboard' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-white'
                                }`}
                        >
                            <BarChart3 className="w-4 h-4" />
                            <span className="text-sm">{t('aiAssistant.dashboard')}</span>
                        </button>
                        <button
                            onClick={() => setMode('chat')}
                            className={`flex items-center space-x-2 px-3 py-2 rounded-md transition-colors ${mode === 'chat' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-white'
                                }`}
                        >
                            <MessageSquare className="w-4 h-4" />
                            <span className="text-sm">{t('aiAssistant.chat')}</span>
                        </button>
                        <button
                            onClick={() => setMode('guide')}
                            className={`flex items-center space-x-2 px-3 py-2 rounded-md transition-colors ${mode === 'guide' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-white'
                                }`}
                        >
                            <BookOpen className="w-4 h-4" />
                            <span className="text-sm">{t('aiAssistant.guides')}</span>
                        </button>
                    </div>

                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-lg transition-colors">
                        <X className="w-5 h-5 text-slate-500" />
                    </button>
                </div>

                {/* Content Area */}
                <div className="flex-1 overflow-hidden">

                    {/* DASHBOARD MODE */}
                    {mode === 'dashboard' && (
                        <div className="h-full overflow-y-auto p-6 space-y-6">
                            {/* Real-time System Metrics */}
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                <div className="bg-white/10 p-4 rounded-xl border border-white/10">
                                    <p className="text-xs text-slate-500 uppercase font-bold mb-1">{t('common.customers')}</p>
                                    <p className="text-2xl font-black tracking-tight text-white">{stats?.customers || 0}</p>
                                </div>
                                <div className="bg-white/10 p-4 rounded-xl border border-white/10">
                                    <p className="text-xs text-slate-500 uppercase font-bold mb-1">{t('common.revenue')}</p>
                                    <p className="text-2xl font-black tracking-tight text-green-400">${stats?.revenue.toLocaleString() || 0}</p>
                                </div>
                                <div className="bg-white/10 p-4 rounded-xl border border-white/10">
                                    <p className="text-xs text-slate-500 uppercase font-bold mb-1">{t('common.expenses')}</p>
                                    <p className="text-2xl font-black tracking-tight text-red-400">${stats?.expenses.toLocaleString() || 0}</p>
                                </div>
                                <div className="bg-white/10 p-4 rounded-xl border border-white/10">
                                    <p className="text-xs text-slate-500 uppercase font-bold mb-1">{t('aiAssistant.auditHealth')}</p>
                                    <p className={`text-2xl font-black tracking-tight ${auditStatus?.healthy ? 'text-blue-400' : 'text-yellow-400'}`}>
                                        {auditStatus?.integrityScore || 0}%
                                    </p>
                                </div>
                            </div>

                            <div className="flex justify-between items-center bg-white/10/50 p-4 rounded-xl border border-white/10">
