                                    >
                                        <Send className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* GUIDE MODE */}
                    {mode === 'guide' && (
                        <div className="h-full overflow-y-auto p-6">
                            <h3 className="text-lg font-semibold text-white mb-6">{t('aiAssistant.systemGuides')}</h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {Object.entries(SYSTEM_GUIDES).map(([key, guide]: [string, { title: string; steps: string[] }]) => (
                                    <button
                                        key={key}
                                        onClick={() => handleQuickGuide(key)}
                                        className="bg-white/10 hover:bg-white/5 p-4 rounded-lg text-left transition-colors border border-white/10"
                                    >
                                        <div className="flex items-start space-x-3">
                                            <div className="p-2 bg-blue-600/20 rounded-lg">
                                                <BookOpen className="w-5 h-5 text-blue-400" />
                                            </div>
                                            <div>
                                                <h4 className="font-medium text-white">{guide.title}</h4>
                                                <p className="text-sm text-slate-500 mt-1">{guide.steps.length} pasos</p>
                                            </div>
                                        </div>
                                    </button>
                                ))}
                            </div>

                            {/* Quick Operations */}
                            <h3 className="text-lg font-semibold text-white mt-8 mb-4">{t('aiAssistant.quickOperations')}</h3>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                {QUICK_OPERATIONS.map((op: { label: string; guide: string }, i: number) => (
                                    <button
                                        key={i}
                                        onClick={() => handleQuickGuide(op.guide)}
                                        className="bg-white/10 hover:bg-white/5 p-3 rounded-lg text-center transition-colors"
                                    >
                                        <Lightbulb className="w-5 h-5 text-yellow-400 mx-auto mb-2" />
                                        <p className="text-sm text-white">{op.label}</p>
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="p-3 border-t border-white/10 text-center">
                    <p className="text-xs text-slate-600">
                        {t('aiAssistant.footerDisclaimer')}
                    </p>
                </div>
            </div>
        </div>
    );
};

