import React from 'react';
import {
    FileText, Clock, CheckCircle2, AlertCircle, Eye,
    Trash2, ArrowUpRight, DollarSign, UserPlus, Users, FilePlus
} from 'lucide-react';
import { deleteARDDocument } from '@/database/simple-db';
import { ARDPaymentModal } from './ARDPaymentModal';
import { ARDPreviewModal } from './ARDPreviewModal';
import { ARDAssignCustomerModal } from './ARDAssignCustomerModal';
import { ARDSaleConversionModal } from './ARDSaleConversionModal';
import { ARDDocument } from '../../modules/ard/ARD.types';
import { useLocale } from '../../i18n/useLocale';

interface ARDDocumentListProps {
    documents: ARDDocument[];
    onRefresh: () => void;
}

export const ARDDocumentList: React.FC<ARDDocumentListProps> = ({ documents, onRefresh }) => {
    const { t } = useLocale();
    const [selectedToConvert, setSelectedToConvert] = React.useState<ARDDocument | null>(null);
    const [selectedToSale, setSelectedToSale] = React.useState<ARDDocument | null>(null);
    const [previewDocument, setPreviewDocument] = React.useState<ARDDocument | null>(null);
    const [assignDocumentId, setAssignDocumentId] = React.useState<string | null>(null);

    const handleDelete = (id: string) => {
        if (confirm(t('ard.confirmDeleteAnalysis'))) {
            deleteARDDocument(id);
            onRefresh();
        }
    };

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'analyzing':
                return <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-lg bg-indigo-500/10 text-indigo-400 text-[9px] font-black uppercase border border-indigo-500/20 animate-pulse">{t('ard.analyzing')}</span>;
            case 'processed':
                return <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-lg bg-emerald-500/10 text-emerald-400 text-[9px] font-black uppercase border border-emerald-500/20">{t('ard.processed')}</span>;
            case 'converted':
                return <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-lg bg-blue-500/10 text-blue-400 text-[9px] font-black uppercase border border-blue-500/20">{t('ard.converted')}</span>;
            default:
                return <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-lg bg-gray-500/10 text-slate-500 text-[9px] font-black uppercase border border-gray-500/20">{status}</span>;
        }
    };

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
    };

    return (
        <div className="card-elite !p-0 overflow-hidden">
            <div className="p-6 border-b border-white/5 flex justify-between items-center bg-white/[0.01]">
                <h3 className="text-table-header">{t('ard.garHistory')}</h3>
                <span className="text-[10px] font-black text-slate-600 uppercase tracking-[0.2em]">{t('ard.numDocuments', { count: documents.length })}</span>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-white/5">
                        <tr className="text-[10px] font-black text-slate-600 uppercase tracking-widest">
                            <th className="px-8 py-5">{t('ard.documentCol')}</th>
                            <th className="px-8 py-5">{t('ard.statusCol')}</th>
                            <th className="px-8 py-5 text-right">{t('ard.amountCol')}</th>
                            <th className="px-8 py-5 text-right">{t('ard.dateCol')}</th>
                            <th className="px-8 py-5 text-center">{t('ard.actionsCol')}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {documents.map((doc) => (
                            <tr key={doc.id} className="hover:bg-indigo-500/[0.02] transition-colors group">
                                <td className="px-8 py-6">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-slate-600 group-hover:text-indigo-400 transition-colors">
                                            <FileText className="w-5 h-5" />
                                        </div>
                                        <div>
                                            <div className="text-white font-bold text-sm">{doc.name}</div>
                                            <div className="text-[10px] font-black text-slate-700 uppercase tracking-widest">{doc.id}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-8 py-6">
                                    {getStatusBadge(doc.status)}
                                </td>
                                <td className="px-8 py-6 text-right">
                                    <div className="text-white font-black tabular-nums">{doc.status === 'processed' || doc.status === 'converted' ? formatCurrency(doc.detected_amount || 0) : '---'}</div>
                                    {(doc.detected_tax || 0) > 0 && <div className="text-[9px] font-bold text-slate-600">Tax: {formatCurrency(doc.detected_tax || 0)}</div>}
                                </td>
                                <td className="px-8 py-6 text-right">
                                    <div className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em]">{doc.detected_date}</div>
                                </td>
                                <td className="px-8 py-6 text-center">
                                    <div className="flex items-center justify-center gap-2">
                                        <button
                                            onClick={() => setPreviewDocument(doc)}
                                            className="p-2 hover:bg-white/5 rounded-lg text-slate-600 hover:text-white transition-colors"
                                            title={t('ard.viewAIAnalysis')}
                                        >
                                            <Eye className="w-4 h-4" />
                                        </button>

                                        <button
                                            onClick={() => setAssignDocumentId(doc.id)}
                                            className={`p-2 rounded-lg transition-all ${doc.customer_id ? 'bg-indigo-500/10 text-indigo-400' : 'text-slate-600 hover:bg-white/5 hover:text-white'}`}
                                            title={doc.customer_id ? t('ard.customerAssigned') : t('ard.assignCustomer')}
                                        >
                                            {doc.customer_id ? <Users className="w-4 h-4" /> : <UserPlus className="w-4 h-4" />}
                                        </button>

                                        {doc.status === 'processed' && (
                                            <>
                                                <button
                                                    onClick={() => setSelectedToSale(doc)}
                                                    className="p-2 bg-blue-500/10 hover:bg-blue-500 text-blue-400 hover:text-white rounded-lg transition-all"
                                                    title={t('ard.convertToInvoice')}
                                                >
                                                    <FilePlus className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => setSelectedToConvert(doc)}
                                                    className="p-2 bg-indigo-500/10 hover:bg-indigo-500 text-indigo-400 hover:text-white rounded-lg transition-all"
                                                    title={t('ard.convertToDirectPayment')}
                                                >
                                                    <ArrowUpRight className="w-4 h-4" />
                                                </button>
                                            </>
                                        )}
                                        <button onClick={() => handleDelete(doc.id)} className="p-2 hover:bg-rose-500/10 rounded-lg text-slate-600 hover:text-rose-400 transition-colors">
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}

                        {documents.length === 0 && (
                            <tr>
                                <td colSpan={5} className="px-8 py-20 text-center">
                                    <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4">
                                        <Clock className="w-8 h-8 text-slate-700" />
                                    </div>
                                    <p className="text-slate-600 font-bold uppercase tracking-widest text-xs">{t('ard.noGarRecords')}</p>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {selectedToConvert && (
                <ARDPaymentModal
                    document={selectedToConvert}
                    onClose={() => setSelectedToConvert(null)}
                    onSuccess={onRefresh}
                />
            )}

            {selectedToSale && (
                <ARDSaleConversionModal
                    document={selectedToSale}
                    onClose={() => setSelectedToSale(null)}
                    onSuccess={onRefresh}
                />
            )}

            {previewDocument && (
                <ARDPreviewModal
                    document={previewDocument}
                    onClose={() => setPreviewDocument(null)}
                />
            )}

            {assignDocumentId && (
                <ARDAssignCustomerModal
                    documentId={assignDocumentId}
                    onClose={() => setAssignDocumentId(null)}
                    onSuccess={onRefresh}
                />
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { Package, RefreshCw, AlertCircle, CheckCircle2, ArrowRightLeft, Info, Search } from 'lucide-react';
import { ARDDocument } from '../../modules/ard/ARD.types';
import { updateProductStock, getProducts, Product } from '@/database/simple-db';
import { toast } from 'react-hot-toast';
import { useLocale } from '../../i18n/useLocale';

interface ARDInventorySyncProps {
    documents: ARDDocument[];
}

export const ARDInventorySync: React.FC<ARDInventorySyncProps> = ({ documents }) => {
    const { t } = useLocale();
    const [searchTerm, setSearchTerm] = useState('');
    const [syncing, setSyncing] = useState<string | null>(null);
    const [showProductPicker, setShowProductPicker] = useState<string | null>(null);
    const [allProducts, setAllProducts] = useState<Product[]>([]);

    React.useEffect(() => {
        setAllProducts(getProducts());
    }, []);

    // Filtramos solo documentos que fueron convertidos y podr├¡an tener impacto en inventario
    const syncableDocs = documents.filter(doc =>
        (doc.status === 'converted' || doc.status === 'processed')
    );

    const handleSync = async (docId: string, productId: number) => {
        setSyncing(docId);
        try {
            // Simulamos un delay de procesamiento
            await new Promise(r => setTimeout(r, 1000));

            const result = updateProductStock(productId, 1, 'add');
            if (result.success) {
                toast.success(t('ard.inventoryUpdatedToast'));
            } else {
                toast.error(result.message);
            }
        } catch (e) {
            toast.error(t('ard.syncErrorToast'));
        } finally {
            setSyncing(null);
            setShowProductPicker(null);
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            {/* Header / Banner */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 p-8 bg-blue-600/5 border border-blue-500/20 rounded-[40px]">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-blue-600/20 rounded-3xl border border-blue-500/30">
                        <Package className="w-8 h-8 text-blue-400" />
                    </div>
                    <div>
                        <h3 className="text-2xl font-black text-white tracking-tight">{t('ard.inventoryEnlace')}</h3>
                        <p className="text-slate-500 font-medium text-sm mt-1">{t('ard.inventorySubtitle')}</p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <div className="text-right">
                        <div className="text-[10px] font-black text-blue-500 uppercase tracking-widest">{t('ard.syncStatus')}</div>
                        <div className="text-white font-black text-xl tabular-nums">{t('ard.pendingSyncDocs', { count: syncableDocs.length })}</div>
                    </div>
                    <div className="p-3 bg-white/5 rounded-2xl border border-white/10 text-blue-400 animate-spin-slow">
                        <RefreshCw className="w-5 h-5" />
                    </div>
                </div>
            </div>

            {/* Informative Note */}
            <div className="p-6 bg-slate-900 border border-white/5 rounded-[32px] flex items-start gap-4 shadow-xl">
                <div className="p-2 bg-indigo-500/10 rounded-xl mt-1">
                    <Info className="w-4 h-4 text-indigo-400" />
                </div>
                <div>
                    <h4 className="text-xs font-black text-white uppercase tracking-widest mb-1">{t('ard.integrationNote')}</h4>
                    <p className="text-[11px] text-slate-600 font-medium leading-relaxed">
                        {t('ard.integrationDesc')}
                    </p>
                </div>
            </div>

            {/* Document Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {syncableDocs.map((doc) => {
                    const analysis = JSON.parse(doc.raw_analysis || '{}');
                    return (
                        <div key={doc.id} className="card-elite hover:border-blue-500/30 transition-all group">
                            <div className="flex items-start justify-between mb-6">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-slate-600 group-hover:text-blue-400 transition-colors">
                                        <ArrowRightLeft className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <div className="text-white font-bold text-sm tracking-tight">{doc.name}</div>
                                        <div className="text-[10px] font-black text-slate-700 uppercase tracking-widest">{doc.id}</div>
                                    </div>
                                </div>
                                <div className={`px-2 py-1 rounded-lg text-[8px] font-black tracking-widest uppercase border ${doc.status === 'converted' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-blue-500/10 text-blue-400 border-blue-500/20'}`}>
                                    {doc.status}
                                </div>
                            </div>

                            <div className="p-4 bg-black/40 rounded-2xl border border-white/5 space-y-3 mb-6">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-600 pb-2 border-b border-white/5">
                                    <span>{t('ard.detectedProductAI')}</span>
                                    <span>{t('ard.quantity')}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-xs text-indigo-400 font-bold uppercase">{analysis.vendor || t('ard.variousCharges')}</span>
                                    <span className="text-xs text-white font-black">1.00 Unit</span>
                                </div>
                            </div>

                            <button
                                onClick={() => setShowProductPicker(doc.id)}
                                disabled={syncing === doc.id}
                                className="w-full py-3 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-black text-[10px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-900/40 disabled:opacity-50"
                            >
                                {syncing === doc.id ? (
                                    <RefreshCw className="w-3 h-3 animate-spin" />
                                ) : (
                                    <RefreshCw className="w-3 h-3" />
                                )}
                                {syncing === doc.id ? t('ard.syncingProgress') : t('ard.syncStockBtn')}
                            </button>

                            {showProductPicker === doc.id && (
                                <div className="mt-4 p-4 bg-slate-800 rounded-2xl border border-white/10 animate-in slide-in-from-top-2">
                                    <h5 className="text-[9px] font-black text-white uppercase mb-3">{t('ard.selectInventoryProduct')}</h5>
                                    <div className="max-h-32 overflow-y-auto space-y-1 custom-scrollbar">
                                        {allProducts.map(p => (
                                            <button
                                                key={p.id}
                                                onClick={() => handleSync(doc.id, p.id)}
                                                className="w-full text-left px-3 py-2 rounded-lg hover:bg-white/5 text-[10px] text-slate-500 hover:text-white transition-colors flex justify-between items-center"
                                            >
                                                <span>{p.name} <span className="opacity-40">({p.sku})</span></span>
                                                <ArrowRightLeft className="w-3 h-3 text-blue-400" />
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    );
                })}

                {syncableDocs.length === 0 && (
                    <div className="col-span-2 py-20 text-center card-elite border-dashed border-2 opacity-50">
                        <Package className="w-12 h-12 text-gray-700 mx-auto mb-4" />
                        <p className="text-slate-600 font-black uppercase tracking-[0.2em] text-xs">{t('ard.noItemsToSync')}</p>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { ScanSearch, FilePlus, Database, CheckCircle2, AlertCircle, Clock, Settings, ArrowRight, RefreshCw, DollarSign, Users, Gem, Package, Rocket, Zap } from 'lucide-react';
import { ARDDocument } from '../../modules/ard/ARD.types';
import { ARDScanner } from './ARDScanner';
import { ARDDocumentList } from './ARDDocumentList';
import { ARDCollectionManager } from './ARDCollectionManager';
import { ARDCustomerPanel } from './ARDCustomerPanel';
import { ARDQualityPanel } from './ARDQualityPanel';
import { ARDInventorySync } from './ARDInventorySync';
import { ARDRoadmap } from './ARDRoadmap';
import { getARDDocuments } from '@/database/simple-db';
import { logger } from '../../core/logging/SystemLogger';
import { useLocale } from '../../i18n/useLocale';

export const ARDModule: React.FC = () => {
    const { t } = useLocale();
    const [activeTab, setActiveTab] = useState<'scan' | 'history' | 'payments' | 'customers' | 'quality' | 'inventory' | 'roadmap'>('scan');
    const [documents, setDocuments] = useState<ARDDocument[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const loadDocuments = async () => {
        try {
            const docs = getARDDocuments();
            setDocuments(docs);
        } catch (e) {
            logger.error('ARD', 'load_failed', 'Fallo al cargar documentos ARD', null, e as Error);
        }
    };

    useEffect(() => {
        loadDocuments();
    }, []);

    useEffect(() => {
        const hasAnalyzing = documents.some(d => d.status === 'analyzing');
        if (hasAnalyzing) {
            const interval = setInterval(loadDocuments, 2000);
            return () => clearInterval(interval);
        }
    }, [documents.some(d => d.status === 'analyzing')]);

    const stats = {
        pending: documents.filter(d => d.status === 'pending' || d.status === 'analyzing').length,
        processed: documents.filter(d => d.status === 'processed').length,
        errors: documents.filter(d => d.status === 'error').length,
        converted: documents.filter(d => d.status === 'converted').length
    };

    return (
        <div className="elite-page-container">
            {/* HEADER ELITE */}
            <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-indigo-600/10 rounded-2.5xl border border-indigo-500/20 shadow-indigo-900/10 shadow-lg group">
                        <ScanSearch className="w-10 h-10 text-indigo-500 group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-white tracking-tight leading-none">{t('ard.title')}</h1>
                        <p className="text-slate-500 font-medium text-sm mt-3 flex items-center gap-2">
                            <Zap className="w-3.5 h-3.5 text-indigo-500 animate-pulse" /> {t('ard.subtitle')}
                        </p>
                    </div>
                </div>

                <div className="flex bg-white/5 p-1 rounded-2xl border border-white/10 overflow-x-auto max-w-full">
                    <button
                        onClick={() => setActiveTab('scan')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'scan' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <FilePlus className="w-4 h-4" /> {t('ard.scanning')}
                    </button>
                    <button
                        onClick={() => setActiveTab('history')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <Database className="w-4 h-4" /> {t('ard.garManagement')}
                    </button>
                    <button
                        onClick={() => setActiveTab('inventory')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'inventory' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <Package className="w-4 h-4" /> {t('ard.inventory')}
                    </button>
                    <button
                        onClick={() => setActiveTab('payments')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'payments' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <DollarSign className="w-4 h-4" /> {t('ard.collections')}
                    </button>
                    <button
                        onClick={() => setActiveTab('customers')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'customers' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <Users className="w-4 h-4" /> {t('ard.customers')}
                    </button>
                    <button
                        onClick={() => setActiveTab('quality')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'quality' ? 'bg-amber-600 text-white shadow-lg shadow-amber-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <Gem className="w-4 h-4" /> {t('ard.quality.label')}
                    </button>
                    <button
                        onClick={() => setActiveTab('roadmap')}
                        className={`px-4 py-2.5 rounded-xl text-[10px] font-bold transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'roadmap' ? 'bg-rose-600 text-white shadow-lg shadow-rose-900/40' : 'text-slate-600 hover:text-white'}`}
                    >
                        <Rocket className="w-4 h-4" /> {t('ard.roadmap.label')}
                    </button>
                </div>
            </div>

            {/* STATS OVERVIEW */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                {[
                    { label: t('ard.enProceso'), val: stats.pending, icon: Clock, color: 'text-sun-orange' },
                    { label: t('ard.analizados'), val: stats.processed, icon: CheckCircle2, color: 'text-emerald-400' },
                    { label: t('ard.errores'), val: stats.errors, icon: AlertCircle, color: 'text-rose-400' },
                    { label: t('ard.convertidos'), val: stats.converted, icon: RefreshCw, color: 'text-blue-400' },
                ].map((stat, i) => (
                    <div key={i} className="card-elite !p-6 flex items-center gap-4 border-l-4 border-l-white/5 hover:border-l-indigo-500/50 transition-all">
                        <div className={`p-3 bg-white/5 rounded-xl ${stat.color}`}>
                            <stat.icon className="w-5 h-5" />
                        </div>
                        <div>
                            <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{stat.label}</span>
                            <div className="text-xl font-black text-white">{stat.val}</div>
                        </div>
                    </div>
                ))}
            </div>

            {/* WORKSPACE AREA */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-12">
                    {activeTab === 'scan' ? (
                        <ARDScanner onDocumentProcessed={loadDocuments} />
                    ) : activeTab === 'history' ? (
                        <ARDDocumentList documents={documents} onRefresh={loadDocuments} />
                    ) : activeTab === 'payments' ? (
                        <ARDCollectionManager documents={documents} onRefresh={loadDocuments} />
                    ) : activeTab === 'customers' ? (
                        <ARDCustomerPanel />
                    ) : activeTab === 'inventory' ? (
                        <ARDInventorySync documents={documents} />
                    ) : activeTab === 'roadmap' ? (
                        <ARDRoadmap />
                    ) : (
                        <ARDQualityPanel />
                    )}
                </div>
            </div>

            {/* FOOTER FASE 5 */}
            <div className="p-4 bg-indigo-500/5 rounded-3xl border border-indigo-500/10 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <Settings className="w-4 h-4 text-indigo-400 animate-spin-slow" />
                    <span className="text-[10px] font-black text-indigo-300 uppercase tracking-widest leading-none">
                        {t('ard.faseStatus')}
                    </span>
                </div>
                <div className="flex items-center gap-1">
                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                    <span className="text-[9px] font-bold text-emerald-500 uppercase tracking-widest">{t('ard.engineReady')}</span>
                </div>
            </div>
        </div>
    );
};

