interface ARDPDFReportProps {
    document: ARDDocument;
    t: (key: string) => string;
}

export const ARDPDFReport: React.FC<ARDPDFReportProps> = ({ document, t }) => {
    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
    };

    const analysis = JSON.parse(document.raw_analysis || '{}');

    return (
        <Document>
            <Page size="A4" style={styles.page}>
                {/* Header */}
                <View style={styles.header}>
                    <View style={styles.logoSection}>
                        <Text style={styles.title}>AccountExpress</Text>
                        <Text style={styles.subtitle}>{t('ard.report.title')}</Text>
                    </View>
                    <View style={styles.dateBox}>
                        <Text style={styles.dateLabel}>{t('ard.report.processingDate')}</Text>
                        <Text style={styles.dateValue}>{new Date(document.uploadDate).toLocaleString()}</Text>
                    </View>
                </View>

                {/* Metadata del Documento */}
                <View style={styles.infoSection}>
                    <Text style={styles.sectionTitle}>{t('ard.report.metadataTitle')}</Text>
                    <View style={styles.grid}>
                        <View style={styles.field}>
                            <Text style={styles.label}>{t('ard.report.trackingId')}</Text>
                            <Text style={styles.value}>{document.id}</Text>
                        </View>
                        <View style={styles.field}>
                            <Text style={styles.label}>{t('ard.report.fileName')}</Text>
                            <Text style={styles.value}>{document.name}</Text>
                        </View>
                        <View style={styles.field}>
                            <Text style={styles.label}>{t('ard.report.detectedType')}</Text>
                            <Text style={styles.value}>{document.type === 'invoice_in' ? t('ard.report.typeInvoice') : t('ard.report.typeReceipt')}</Text>
                        </View>
                        <View style={styles.field}>
                            <Text style={styles.label}>{t('ard.report.originalSize')}</Text>
                            <Text style={styles.value}>{(document.fileSize / 1024).toFixed(2)} KB</Text>
                        </View>
                    </View>
                </View>

                {/* Resultado Financiero IA */}
                <View style={styles.financialCard}>
                    <Text style={styles.sectionTitle}>{t('ard.report.aiExtractionTitle')}</Text>

                    <View style={styles.amountRow}>
                        <View>
                            <Text style={styles.label}>{t('ard.report.totalDetectedAmount')}</Text>
                            <Text style={{ fontSize: 9, color: '#6366F1', marginTop: 2 }}>{t('ard.report.ocrConfidence')}</Text>
                        </View>
                        <Text style={styles.bigAmount}>{formatCurrency(document.detected_amount || 0)}</Text>
                    </View>

                    <View style={styles.taxRow}>
                        <View style={styles.field}>
                            <Text style={styles.label}>{t('ard.report.tax')}</Text>
                            <Text style={styles.value}>{formatCurrency(document.detected_tax || 0)}</Text>
                        </View>
                        <View style={styles.field}>
                            <Text style={styles.label}>{t('ard.report.docDate')}</Text>
                            <Text style={styles.value}>{document.detected_date || t('ard.report.notDetected')}</Text>
                        </View>
                    </View>
                </View>

                {/* Detalles del Vendedor */}
                <View style={[styles.infoSection, { backgroundColor: '#FFFFFF' }]}>
                    <Text style={styles.sectionTitle}>{t('ard.report.issuerEntity')}</Text>
                    <View style={styles.grid}>
                        <View style={[styles.field, { width: '100%' }]}>
                            <Text style={styles.label}>{t('ard.report.vendorEstab')}</Text>
                            <Text style={[styles.value, { fontSize: 14, fontFamily: 'Helvetica-Bold' }]}>
                                {analysis.vendor || t('ard.report.notIdentified')}
                            </Text>
                        </View>
                    </View>
                </View>

                {/* Sello Forense Anti-Tamper */}
                <View style={styles.forensicBox}>
                    <Text style={styles.forensicTitle}>{t('ard.report.forensicSeal')}</Text>
                    <Text style={styles.hash}>
                        HASH: {document.id}_FS_{analysis.vendor?.substring(0, 3).toUpperCase() || 'NA'}_{new Date().getTime()}
                    </Text>
                    <Text style={[styles.hash, { marginTop: 4, color: '#94A3B8' }]}>
                        {t('ard.report.forensicDisclaimer')}
                    </Text>
                </View>

                <Text style={styles.footer}>
                    {t('ard.report.footer')}
                </Text>
            </Page>
        </Document>
    );
};

import React, { useState, useEffect } from 'react';
import { X, FilePlus, User, ArrowRight, ShoppingBag, Tag, Calendar, ShieldCheck } from 'lucide-react';
import { getCustomers, createInvoice, updateARDDocumentStatus, Customer } from '@/database/simple-db';
import { logger } from '../../core/logging/SystemLogger';
import { ARDDocument } from '../../modules/ard/ARD.types';
import { useLocale } from '../../i18n/useLocale';

interface ARDSaleConversionModalProps {
    document: ARDDocument;
    onClose: () => void;
    onSuccess: () => void;
}

export const ARDSaleConversionModal: React.FC<ARDSaleConversionModalProps> = ({ document, onClose, onSuccess }) => {
    const { t } = useLocale();
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [selectedCustomerId, setSelectedCustomerId] = useState<number | ''>(document.customer_id || '');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [invoiceNumber, setInvoiceNumber] = useState(`INV-ARD-${Math.random().toString(36).substr(2, 6).toUpperCase()}`);

    // Extracci├│n de datos del an├ílisis
    const analysis = JSON.parse(document.raw_analysis || '{}');
    const [amount, setAmount] = useState(document.detected_amount || 0);
    const [tax, setTax] = useState(document.detected_tax || 0);
    const [date, setDate] = useState(document.detected_date || new Date().toISOString().split('T')[0]);
    const [description, setDescription] = useState<string>(t('ard.sale.autoGeneratedDesc', { docName: document.name, vendor: analysis.vendor || 'Proveedor/Vendedor no identificado' }));

    useEffect(() => {
        setCustomers(getCustomers());
    }, []);

    const handleConvert = async () => {
        if (!selectedCustomerId) {
            alert(t('ard.sale.assignCustomerAlert'));
            return;
        }

        setIsSubmitting(true);
        try {
            // 1. Preparar datos de la factura
            const invoiceData = {
                customer_id: Number(selectedCustomerId),
                invoice_number: invoiceNumber,
                issue_date: date,
                due_date: new Date(new Date(date).getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
                subtotal: amount - tax,
                tax_amount: tax,
                total_amount: amount,
                status: 'draft' as const,
                notes: t('ard.sale.autoGeneratedNote', { docId: document.id, docName: document.name })
            };

            // 2. Crear ├¡tems de factura (uno gen├⌐rico basado en el an├ílisis)
            const items = [
                {
                    description: description,
                    quantity: 1,
                    unit_price: amount - tax,
                    line_total: amount - tax,
                    taxable: tax > 0
                }
            ];

            // 3. Crear la factura en la base de datos
            const result = createInvoice(invoiceData, items, 1); // Mock User ID 1

            if (result.success) {
                // 4. Actualizar estado del documento ARD
                updateARDDocumentStatus(document.id, 'converted');

                logger.info('ARD', 'conversion_to_sale_success', `Documento ${document.id} convertido a factura ${invoiceNumber}`);
                onSuccess();
                onClose();
            } else {
                alert(t('ard.sale.errorCreatingInvoice', { message: result.message }));
            }
        } catch (e) {
            logger.error('ARD', 'conversion_to_sale_failed', 'Fallo en la conversi├│n a venta', null, e as Error);
            alert(t('ard.sale.criticalError'));
        } finally {
            setIsSubmitting(false);
        }
    };

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
    };

    return (
        <div className="fixed inset-0 z-[250] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-4">
            <div className="w-full max-w-2xl bg-slate-900 border border-white/10 rounded-[32px] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-300">
                {/* Header */}
                <div className="p-8 border-b border-white/5 flex justify-between items-center bg-blue-500/5">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-blue-500/20 rounded-2xl">
                            <ShoppingBag className="w-6 h-6 text-blue-400" />
                        </div>
                        <div>
                            <h3 className="text-xl font-black text-white">{t('ard.sale.modalTitle')}</h3>
                            <p className="text-slate-600 text-xs font-bold uppercase tracking-widest mt-0.5">{t('ard.sale.modalSubtitle')}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-5 h-5 text-slate-500" />
                    </button>
                </div>

                <div className="p-8 space-y-6">
                    {/* Alerta de Integridad */}
                    <div className="flex items-center gap-3 p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl">
                        <ShieldCheck className="w-5 h-5 text-emerald-400" />
                        <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">
                            {t('ard.sale.ocrVerified')}
                        </span>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        {/* Selecci├│n de Cliente */}
                        <div className="col-span-2 space-y-2">
                            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2">
                                <User className="w-3 h-3" /> {t('ard.sale.targetCustomer')}
                            </label>
                            <select
                                value={selectedCustomerId}
                                onChange={(e) => setSelectedCustomerId(Number(e.target.value))}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-4 text-white text-sm focus:outline-none focus:border-blue-500/50 transition-colors"
                            >
                                <option value="">{t('ard.sale.selectCustomerPlaceholder')}</option>
                                {customers.map(c => <option key={c.id} value={c.id} className="bg-slate-900">{c.name}</option>)}
                            </select>
                        </div>

                        {/* N├║mero de Factura */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2">
                                <FilePlus className="w-3 h-3" /> {t('ard.sale.invoiceNumber')}
                            </label>
                            <input
                                type="text"
                                value={invoiceNumber}
                                onChange={(e) => setInvoiceNumber(e.target.value)}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm font-bold focus:outline-none focus:border-blue-500/50"
                            />
                        </div>

                        {/* Fecha */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2">
                                <Calendar className="w-3 h-3" /> {t('ard.sale.saleDate')}
                            </label>
                            <input
                                type="date"
                                value={date}
                                onChange={(e) => setDate(e.target.value)}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm focus:outline-none focus:border-blue-500/50"
                            />
                        </div>

                        {/* Monto Total */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2">
                                <Tag className="w-3 h-3" /> {t('ard.sale.totalAmount')}
                            </label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 font-bold">$</span>
                                <input
                                    type="number"
                                    value={amount}
                                    onChange={(e) => setAmount(Number(e.target.value))}
                                    className="w-full bg-white/5 border border-white/10 rounded-xl pl-8 pr-4 py-3 text-white font-black text-xl focus:outline-none focus:border-blue-500/50"
                                />
                            </div>
                        </div>

                        {/* Impuestos */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2">
                                <Tag className="w-3 h-3" /> {t('ard.sale.tax')}
                            </label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 font-bold">$</span>
                                <input
                                    type="number"
                                    value={tax}
                                    onChange={(e) => setTax(Number(e.target.value))}
                                    className="w-full bg-white/5 border border-white/10 rounded-xl pl-8 pr-4 py-3 text-white font-black text-xl focus:outline-none focus:border-blue-500/50"
                                />
                            </div>
                        </div>

                        {/* Descripci├│n / Concepto */}
                        <div className="col-span-2 space-y-2">
                            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2">
                                <FilePlus className="w-3 h-3" /> {t('ard.sale.conceptDesc')}
                            </label>
                            <textarea
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                rows={2}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm focus:outline-none focus:border-blue-500/50 resize-none"
                            />
                        </div>
                    </div>
                </div>

                {/* Footer Actions */}
                <div className="p-8 bg-white/[0.02] border-t border-white/5 flex gap-4">
                    <button
                        onClick={onClose}
                        className="flex-1 py-4 rounded-2xl bg-white/5 hover:bg-white/10 text-slate-500 font-black text-xs uppercase tracking-widest transition-all"
                    >
                        {t('ard.sale.cancel')}
                    </button>
                    <button
                        onClick={handleConvert}
                        disabled={isSubmitting}
                        className="flex-2 flex items-center justify-center gap-3 px-12 py-4 rounded-2xl bg-blue-600 hover:bg-blue-500 text-white font-black text-xs uppercase tracking-widest transition-all shadow-lg shadow-blue-900/40"
                    >

                        {isSubmitting ? t('ard.sale.processing') : t('ard.sale.complete')}
                        <ArrowRight className="w-4 h-4" />
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useCallback } from 'react';
import { Upload, File, X, Sparkles, Loader2 } from 'lucide-react';
import { saveARDDocument, updateARDDocumentStatus } from '@/database/simple-db';
import { ARDDocument } from '../../modules/ard/ARD.types';
import { useLocale } from '../../i18n/useLocale';
import Tesseract from 'tesseract.js';

interface ARDScannerProps {
    onDocumentProcessed: () => void;
}

export const ARDScanner: React.FC<ARDScannerProps> = ({ onDocumentProcessed }) => {
    const { t } = useLocale();
    const [isDragging, setIsDragging] = useState(false);
    const [uploading, setUploading] = useState(false);

    const processFiles = async (files: FileList | File[]) => {
        setUploading(true);
        try {
            for (const file of Array.from(files)) {
                const id = `ARD-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;

                try {
                    const { data: { text } } = await Tesseract.recognize(file, 'spa', {
                        logger: (info) => console.log(info),
                    });

                    const parsedResult = parseOCRText(text);
                    updateARDDocumentStatus(id, 'processed', parsedResult);
                } catch (error) {
                    console.error('Error al procesar OCR:', error);
                    updateARDDocumentStatus(id, 'error', { error: error instanceof Error ? error.message : 'Error desconocido' });
                }
            }
            onDocumentProcessed();
        } finally {
            setUploading(false);
        }
    };

    const parseOCRText = (text: string): { amount: number; tax: number; vendor: string; date: string } => {
        // Implementar l├│gica para extraer datos como monto, impuesto, proveedor y fecha del texto reconocido
        const amount = extractAmount(text);
        const tax = extractTax(text);
        const vendor = extractVendor(text);
        const date = extractDate(text);

        return { amount, tax, vendor, date };
    };

    const extractAmount = (text: string): number => {
        // L├│gica para extraer el monto del texto
        const match = text.match(/\b\d+(\.\d{1,2})?\b/);
        return match ? parseFloat(match[0]) : 0;
    };

    const extractTax = (text: string): number => {
        // L├│gica para extraer el impuesto del texto (en ingl├⌐s y espa├▒ol)
        const match = text.match(/(?:impuesto|tax|sales tax):\s*(\d+(\.\d{1,2})?)/i);
        return match ? parseFloat(match[1]) : 0;
    };

    const extractVendor = (text: string): string => {
        // L├│gica para extraer el nombre del proveedor del texto (en ingl├⌐s y espa├▒ol)
        const match = text.match(/(?:proveedor|vendor|from|bill to):\s*(.+)/i);
        return match ? match[1].trim() : 'Desconocido';
    };

    const extractDate = (text: string): string => {
        // L├│gica para extraer la fecha del texto
        const match = text.match(/\b\d{4}-\d{2}-\d{2}\b/);
        return match ? match[0] : new Date().toISOString().split('T')[0];
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const files = e.dataTransfer.files;
        if (files && files.length > 0) processFiles(files);
    };

    return (
        <div
            onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
            onDragLeave={() => setIsDragging(false)}
            onDrop={handleDrop}
            className={`
        relative overflow-hidden rounded-[32px] border-2 border-dashed transition-all duration-500 p-12
        flex flex-col items-center justify-center text-center group
        ${isDragging ? 'border-indigo-500 bg-indigo-500/5 scale-[0.99] shadow-inner' : 'border-white/10 bg-white/[0.02] hover:border-white/20'}
        ${uploading ? 'pointer-events-none opacity-80' : 'cursor-pointer'}
      `}
        >
            <div className={`
        w-24 h-24 rounded-full flex items-center justify-center mb-8 transition-all duration-500
        ${uploading ? 'bg-indigo-500 animate-pulse' : 'bg-indigo-500/10 group-hover:bg-indigo-500/20 group-hover:scale-110'}
      `}>
                {uploading ? <Loader2 className="w-10 h-10 text-white animate-spin" /> : <Upload className="w-10 h-10 text-indigo-400" />}
            </div>

            <div className="space-y-2">
                <h3 className="text-2xl font-black text-white tracking-tight">
                    {uploading ? t('ard.analyzingDoc') : t('ard.smartDigitalization')}
                </h3>
                <p className="text-slate-600 font-medium text-sm max-w-sm mx-auto">
                    {uploading
                        ? t('ard.visionEngineProgress')
                        : t('ard.dropFilesHint')}
                </p>
            </div>

            {uploading && (
                <div className="mt-8 flex items-center gap-3 px-6 py-3 bg-indigo-500/10 border border-indigo-500/20 rounded-2xl animate-pulse">
                    <Sparkles className="w-4 h-4 text-indigo-400" />
                    <span className="text-xs font-black text-indigo-300 uppercase tracking-widest">{t('ard.activeIAOCR')}</span>
                </div>
            )}

            {!uploading && (
                <label className="mt-8 px-8 py-3 bg-white text-black font-black text-xs rounded-2xl cursor-pointer hover:bg-slate-200 transition-colors uppercase tracking-widest">
                    {t('ard.selectFile')}
                    <input type="file" className="hidden" multiple onChange={(e) => e.target.files && processFiles(e.target.files)} />
                </label>
            )}

            {/* Glossy Effect */}
            <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-500/10 blur-[100px] rounded-full"></div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import {
  Package,
  ArrowLeft,
  Edit,
  Trash2,
  Calendar,
  DollarSign,
  TrendingDown,
  FileText,
  AlertCircle
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { db } from '@/database/simple-db';
import { getFixedAssetsController } from '@/services/accounting/fixed-assets';
import type { FixedAsset, AssetCategory, DepreciationEntry } from '@/services/accounting/fixed-assets';
import { useLocale } from '@/i18n/useLocale';

interface AssetDetailViewProps {
  asset: FixedAsset;
  onBack: () => void;
  onEdit: (asset: FixedAsset) => void;
  onDispose: (asset: FixedAsset) => void;
}

export const AssetDetailView: React.FC<AssetDetailViewProps> = ({
  asset,
  onBack,
  onEdit,
  onDispose
}) => {
  const { t } = useLocale();
  const [activeTab, setActiveTab] = useState<'overview' | 'depreciation' | 'history'>('overview');
  const [category, setCategory] = useState<AssetCategory | null>(null);
  const [depreciationHistory, setDepreciationHistory] = useState<DepreciationEntry[]>([]);
  const [depreciationSchedule, setDepreciationSchedule] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadAssetDetails();
  }, [asset.id]);

  const loadAssetDetails = async () => {
    try {
      setLoading(true);
      const controller = getFixedAssetsController(db);

      // Load category
      const cat = await controller.getCategoryById(asset.category_id);
      setCategory(cat);

      // Load depreciation history
      const history = await controller.getDepreciationHistory(asset.id);
      setDepreciationHistory(history);

      // Load depreciation schedule (future projections)
      if (asset.status === 'ACTIVE') {
        const schedule = await controller.getDepreciationSchedule(asset.id);
        setDepreciationSchedule(schedule);
      }

    } catch (error) {
      console.error('Error loading asset details:', error);
    } finally {
      setLoading(false);
    }
  };

  const tabs = [
    { id: 'overview' as const, label: t('assets.details.overview'), icon: Package },
    { id: 'depreciation' as const, label: t('assets.details.depreciation'), icon: TrendingDown },
    { id: 'history' as const, label: t('assets.details.history'), icon: FileText }
  ];

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ACTIVE':
        return 'bg-green-900/30 text-green-400 border-green-500/30';
      case 'PENDING':
        return 'bg-yellow-900/30 text-yellow-400 border-yellow-500/30';
      case 'FULLY_DEPRECIATED':
        return 'bg-blue-900/30 text-blue-400 border-blue-500/30';
      case 'DISPOSED':
        return 'bg-slate-700 text-slate-400 border-slate-600';
      default:
        return 'bg-slate-700 text-slate-400 border-slate-600';
    }
  };

  const formatCurrency = (cents: number) => {
    return `$${(cents / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            onClick={onBack}
            variant="ghost"
            className="text-slate-400 hover:text-white"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            {t('common.back')}
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <Package className="w-8 h-8 text-blue-400" />
              {asset.asset_name}
            </h1>
            <p className="text-slate-400 mt-1">
              {t('assets.reports_ui.tag')}: <span className="font-mono text-blue-400">{asset.asset_tag}</span>
              {category && <span className="ml-4">{t('assets.form.category')}: {category.name}</span>}
            </p>
          </div>
        </div>
        <div className="flex gap-3">
          {asset.status !== 'DISPOSED' && (
            <>
              <Button
                onClick={() => onEdit(asset)}
                className="bg-blue-600 hover:bg-blue-700 text-white"
              >
                <Edit className="w-4 h-4 mr-2" />
                {t('common.edit')}
              </Button>
              <Button
                onClick={() => onDispose(asset)}
                className="bg-red-600 hover:bg-red-700 text-white"
              >
                <Trash2 className="w-4 h-4 mr-2" />
                {t('assets.disposal')}
              </Button>
            </>
          )}
        </div>
      </div>

      {/* Status Badge */}
      <div className="flex items-center gap-4">
        <span className={`px-4 py-2 rounded-lg text-sm font-medium border ${getStatusColor(asset.status)}`}>
          {t(`assets.status.${asset.status.toLowerCase()}`)}
        </span>
        {asset.status === 'DISPOSED' && asset.disposal_date && (
          <span className="text-slate-400 text-sm">
            {t('assets.details.disposedOn', { date: formatDate(asset.disposal_date) })}
          </span>
        )}
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-slate-800">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-4 py-2 font-medium transition-colors flex items-center gap-2 ${activeTab === tab.id
              ? 'text-blue-400 border-b-2 border-blue-400'
              : 'text-slate-400 hover:text-white'
              }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="mt-6">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Asset Information */}
            <Card className="bg-slate-900 border-slate-800 text-white">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Package className="w-5 h-5 text-blue-400" />
                  {t('assets.details.assetInfo')}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.form.assetName')}:</span>
                  <span className="font-medium">{asset.asset_name}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.reports_ui.tag')}:</span>
                  <span className="font-mono text-blue-400">{asset.asset_tag}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.form.category')}:</span>
                  <span>{category?.name || 'N/A'}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('common.description')}:</span>
                  <span className="text-right">{asset.description || 'N/A'}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.form.purchaseDate')}:</span>
                  <span>{formatDate(asset.purchase_date)}</span>
                </div>
                {asset.start_depreciation_date && (
                  <div className="flex justify-between py-2 border-b border-slate-800">
                    <span className="text-slate-400">{t('assets.details.startDepreciation')}:</span>
                    <span>{formatDate(asset.start_depreciation_date)}</span>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Financial Information */}
            <Card className="bg-slate-900 border-slate-800 text-white">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <DollarSign className="w-5 h-5 text-green-400" />
                  {t('assets.form.financialInfo')}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.form.purchaseCost')}:</span>
                  <span className="font-mono text-blue-400">{formatCurrency(asset.purchase_cost)}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.form.salvageValue')}:</span>
                  <span className="font-mono">{formatCurrency(asset.salvage_value)}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.details.accumulated')}:</span>
                  <span className="font-mono text-amber-400">
                    {formatCurrency(asset.total_accumulated_depreciation)}
                  </span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.details.currentValue')}:</span>
                  <span className="font-mono text-green-400 text-lg font-bold">
                    {formatCurrency(asset.net_book_value || 0)}
                  </span>
                </div>
                <div className="flex justify-between py-2 border-b border-slate-800">
                  <span className="text-slate-400">{t('assets.form.depreciationMethod')}:</span>
                  <span className="text-sm">{asset.depreciation_method}</span>
                </div>
                <div className="flex justify-between py-2">
                  <span className="text-slate-400">{t('assets.form.usefulLife')}:</span>
                  <span>{asset.useful_life_months} {t('assets.form.months')}</span>
                </div>
              </CardContent>
            </Card>
          </div>
        )}

        {activeTab === 'depreciation' && (
          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <TrendingDown className="w-5 h-5 text-amber-400" />
                {t('assets.details.history')}
              </CardTitle>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div className="text-center py-8 text-slate-400">{t('common.loading')}</div>
              ) : depreciationHistory.length === 0 ? (
                <div className="text-center py-8">
                  <AlertCircle className="w-12 h-12 text-slate-700 mx-auto mb-3" />
                  <p className="text-slate-400">{t('assets.details.noDepreciationHistory')}</p>
                  {asset.status === 'PENDING' && (
                    <p className="text-sm text-slate-500 mt-2">
                      {t('assets.details.activationRequired')}
                    </p>
                  )}
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-slate-800">
                        <th className="text-left py-3 px-4 text-sm font-medium text-slate-400">{t('assets.reports_ui.period')}</th>
                        <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.depreciation')}</th>
                        <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.accumulated')}</th>
                        <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.currentValue')}</th>
                        <th className="text-center py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.partial')}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {depreciationHistory.map((entry) => (
                        <tr key={entry.id} className="border-b border-slate-800 hover:bg-slate-800/50">
                          <td className="py-3 px-4 text-sm">{formatDate(entry.period_date)}</td>
                          <td className="py-3 px-4 text-sm text-right font-mono text-amber-400">
                            {formatCurrency(entry.depreciation_amount)}
                          </td>
                          <td className="py-3 px-4 text-sm text-right font-mono">
                            {formatCurrency(entry.accumulated_depreciation)}
                          </td>
                          <td className="py-3 px-4 text-sm text-right font-mono text-green-400">
                            {formatCurrency(entry.net_book_value)}
                          </td>
                          <td className="py-3 px-4 text-center">
                            {entry.is_partial_month && (
                              <span className="px-2 py-1 rounded text-xs bg-yellow-900/30 text-yellow-400">
