              {/* Future Schedule */}
              {asset.status === 'ACTIVE' && depreciationSchedule.length > 0 && (
                <div className="mt-8">
                  <h3 className="text-lg font-black tracking-tight text-white mb-4 flex items-center gap-2">
                    <Calendar className="w-5 h-5 text-blue-400" />
                    {t('assets.details.futureProjection')}
                  </h3>
                  <div className="overflow-x-auto">
                    <table className="w-full">
                      <thead>
                        <tr className="border-b border-slate-800">
                          <th className="text-left py-3 px-4 text-sm font-medium text-slate-400">{t('assets.reports_ui.period')}</th>
                          <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.estimatedDepreciation')}</th>
                          <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.projectedAccumulated')}</th>
                          <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('assets.details.projectedValue')}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {depreciationSchedule.slice(0, 12).map((entry, idx) => (
                          <tr key={idx} className="border-b border-slate-800 hover:bg-slate-800/50">
                            <td className="py-3 px-4 text-sm text-slate-400">{entry.period}</td>
                            <td className="py-3 px-4 text-sm text-right font-mono text-slate-400">
                              {formatCurrency(entry.depreciation_amount)}
                            </td>
                            <td className="py-3 px-4 text-sm text-right font-mono text-slate-400">
                              {formatCurrency(entry.accumulated_depreciation)}
                            </td>
                            <td className="py-3 px-4 text-sm text-right font-mono text-slate-400">
                              {formatCurrency(entry.net_book_value)}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        )}

        {activeTab === 'history' && (
          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <FileText className="w-5 h-5 text-blue-400" />
                {t('assets.details.transactions')}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {/* Purchase Entry */}
                <div className="p-4 border border-slate-800 rounded-lg">
                  <div className="flex items-start justify-between">
                    <div>
                      <h4 className="font-medium text-white">{t('assets.details.assetPurchase')}</h4>
                      <p className="text-sm text-slate-400 mt-1">
                        {formatDate(asset.purchase_date)}
                      </p>
                    </div>
                    <span className="font-mono text-blue-400">{formatCurrency(asset.purchase_cost)}</span>
                  </div>
                  {asset.purchase_entry_id && (
                    <p className="text-xs text-slate-500 mt-2">
                      Journal Entry ID: {asset.purchase_entry_id}
                    </p>
                  )}
                </div>

                {/* Activation */}
                {asset.start_depreciation_date && (
                  <div className="p-4 border border-slate-800 rounded-lg">
                    <div className="flex items-start justify-between">
                      <div>
                        <h4 className="font-medium text-white">{t('assets.details.activation')}</h4>
                        <p className="text-sm text-slate-400 mt-1">
                          {formatDate(asset.start_depreciation_date)}
                        </p>
                      </div>
                      <span className="px-2 py-1 rounded text-xs bg-green-900/30 text-green-400">
                        {t('assets.details.depreciationStarted')}
                      </span>
                    </div>
                  </div>
                )}

                {/* Disposal */}
                {asset.status === 'DISPOSED' && asset.disposal_date && (
                  <div className="p-4 border border-slate-800 rounded-lg">
                    <div className="flex items-start justify-between">
                      <div>
                        <h4 className="font-medium text-white">{t('assets.disposal')}</h4>
                        {formatDate(asset.disposal_date)} ΓÇó {asset.disposal_method && t(`assets.disposalForm.methods.${asset.disposal_method.toLowerCase()}`)}
                      </div>
                      {asset.disposal_amount && (
                        <span className="font-mono text-slate-400">
                          {formatCurrency(asset.disposal_amount)}
                        </span>
                      )}
                    </div>
                    {asset.disposal_entry_id && (
                      <p className="text-xs text-slate-500 mt-2">
                        Journal Entry ID: {asset.disposal_entry_id}
                      </p>
                    )}
                  </div>
                )}

                {depreciationHistory.length === 0 && !asset.disposal_date && (
                  <div className="text-center py-8">
                    <AlertCircle className="w-12 h-12 text-slate-700 mx-auto mb-3" />
                    <p className="text-slate-400">{t('assets.details.noAdditionalTransactions')}</p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { XCircle, AlertCircle, TrendingUp, TrendingDown, DollarSign, Calendar, CheckCircle, ShieldCheck } from 'lucide-react';
import { Button } from '../ui/button';
import { Card, CardContent } from '../ui/card';
import { getFixedAssetsController } from '../../controllers/FixedAssetsController';
import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import type { FixedAsset } from '../../services/accounting/FixedAssetService';
import { useLocale } from '../../i18n/useLocale';
import { useAuth } from '@/contexts/AuthContext';


interface AssetDisposalFormProps {
    asset: FixedAsset;
    onDispose: () => void;
    onCancel: () => void;
    db: SQLiteEngine;
}

type DisposalMethod = 'SALE' | 'RETIREMENT' | 'TRADE_IN' | 'LOST';

export const AssetDisposalForm: React.FC<AssetDisposalFormProps> = ({
    asset,
    onDispose,
    onCancel,
    db
}) => {
    const { user } = useAuth();
    const { t } = useLocale();
    const [formData, setFormData] = useState({
        disposal_date: new Date().toISOString().split('T')[0],
        disposal_method: 'SALE' as DisposalMethod,
        disposal_proceeds_dollars: 0,
        notes: ''
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Calculate current net book value and potential gain/loss
    const netBookValue = (asset.net_book_value || 0) / 100; // Convert cents to dollars
    const proceeds = formData.disposal_proceeds_dollars;
    const gainLoss = proceeds - netBookValue;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Validation
        if (formData.disposal_method === 'SALE' && proceeds <= 0) {
            setError(t('assets.disposalForm.errorSaleProceeds'));
            return;
        }

        if (new Date(formData.disposal_date) < new Date(asset.purchase_date)) {
            setError(t('assets.disposalForm.errorDate'));
            return;
        }

        if (!user?.id) {
            console.error('[AssetDisposalForm] userId no disponible. Operaci├│n abortada.');
            return;
        }

        setLoading(true);
        try {
            const controller = getFixedAssetsController(db);

            await controller.disposeAsset(asset.id, {
                disposal_date: formData.disposal_date,
                disposal_method: formData.disposal_method,
                disposal_proceeds: Math.round(formData.disposal_proceeds_dollars * 100), // Convert to cents
                notes: formData.notes
            }, user?.id ?? null);

            onDispose();
        } catch (err: any) {
            setError(err.message || t('assets.disposalForm.errorSubmit'));
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (field: keyof typeof formData, value: any) => {
        setFormData(prev => ({ ...prev, [field]: value }));
        setError('');
    };

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
            <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-4xl max-h-[95vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-rose-500/5 blur-[120px] pointer-events-none"></div>

                {/* Header Hub */}
                <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
                    <div className="flex items-center gap-6">
                        <div className="text-rose-500">
                            <TrendingDown className="w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                                {t('assets.disposalForm.title')}
