                                        <div className="flex items-center justify-between relative z-10">
                                            <span className={`text-2xl font-black font-mono tracking-tighter ${gainLoss > 0 ? 'text-emerald-400' : gainLoss < 0 ? 'text-rose-400' : 'text-slate-400'
                                                }`}>
