                                        <p className="text-[9px] font-black text-slate-500 mt-2 uppercase tracking-[0.2em] relative z-10">
                                            {gainLoss > 0 ? t('assets.disposalForm.gain') : gainLoss < 0 ? t('assets.disposalForm.loss') : t('assets.disposalForm.breakEven')}
                                        </p>

                                        {/* Background pattern */}
                                        <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                                            {gainLoss > 0 ? <TrendingUp className="w-16 h-16" /> : <TrendingDown className="w-16 h-16" />}
                                        </div>
                                    </div>
                                </div>

                                {/* Notes */}
                                <div className="md:col-span-2 space-y-3">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1 block">
                                        {t('assets.form.notes')}
                                    </label>
                                    <textarea
                                        value={formData.notes}
                                        onChange={(e) => handleChange('notes', e.target.value)}
                                        rows={3}
                                        className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-rose-500/50 outline-none transition-all font-medium text-sm placeholder:text-slate-800 resize-none"
                                        placeholder={t('assets.disposalForm.notesPlaceholder')}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Journal Entry Preview */}
                        <div className="bg-indigo-600/5 border border-indigo-500/20 rounded-[2rem] p-10 overflow-hidden relative group">
                            <div className="absolute -right-10 -bottom-10 opacity-5 group-hover:opacity-10 transition-opacity">
                                <DollarSign className="w-48 h-48 text-indigo-400" />
                            </div>

                            <div className="relative z-10">
                                <h3 className="text-[11px] font-black text-white uppercase tracking-[0.3em] mb-8 flex items-center gap-4">
                                    <div className="w-8 h-[1px] bg-indigo-500/50"></div>
                                    {t('assets.disposalForm.preview')}
                                    <div className="w-8 h-[1px] bg-indigo-500/50"></div>
                                </h3>

                                <div className="space-y-6">
                                    <JournalLine label="DR Cash (1000)" value={`$${proceeds.toFixed(2)}`} />
                                    <JournalLine label="DR Accumulated Depreciation (1650)" value={`$${(asset.total_accumulated_depreciation / 100).toFixed(2)}`} />
                                    {gainLoss < 0 && (
                                        <JournalLine label={`DR ${t('assets.disposalForm.loss')} (5900)`} value={`$${Math.abs(gainLoss).toFixed(2)}`} highlight="rose" />
                                    )}
                                    <div className="h-[1px] bg-slate-800/50 my-6"></div>
                                    <JournalLine label="CR Fixed Asset (1600)" value={`$${(asset.purchase_cost / 100).toFixed(2)}`} indent />
                                    {gainLoss > 0 && (
                                        <JournalLine label={`CR ${t('assets.disposalForm.gain')} (4900)`} value={`$${gainLoss.toFixed(2)}`} highlight="emerald" indent />
                                    )}
                                </div>
                            </div>
                        </div>
                    </form>
                </div>

                {/* Footer Hub */}
                <footer className="p-10 border-t border-slate-800/50 bg-slate-950/30 flex justify-end gap-6 flex-shrink-0 relative z-10">
                    <button
                        type="button"
                        onClick={onCancel}
                        className="px-10 py-5 text-slate-500 hover:text-white transition-all font-black uppercase tracking-widest text-[10px] hover:bg-slate-900 rounded-2xl border border-transparent hover:border-slate-800"
                        disabled={loading}
                    >
                        {t('common.cancel')}
                    </button>
                    <button
                        form="disposal-form"
                        type="submit"
                        className="bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white px-12 py-5 rounded-2.5xl font-black uppercase tracking-widest text-[11px] transition-all flex items-center justify-center gap-4 shadow-3xl shadow-rose-900/40 hover:-translate-y-1 active:scale-95"
                        disabled={loading}
                    >
                        <span>{loading ? t('common.processing') : t('assets.disposalForm.confirmBtn')}</span>
                    </button>
                </footer>
            </div>
        </div>
    );
};

const JournalLine = ({ label, value, highlight, indent }: any) => (
    <div className={`flex justify-between items-center group/line ${indent ? 'pl-8' : ''}`}>
        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover/line:text-slate-300 transition-colors">{label}</span>
        <span className={`text-sm font-black font-mono tracking-tighter ${highlight === 'rose' ? 'text-rose-400' : highlight === 'emerald' ? 'text-emerald-400' : 'text-white'}`}>{value}</span>
    </div>
);

import React, { useState, useEffect } from 'react';
import { XCircle, Save, Building2, Calendar, DollarSign, Info, AlertCircle, TrendingDown, CheckCircle, ShieldCheck, RefreshCw } from 'lucide-react';
import { Button } from '../ui/button';
import { Card, CardContent } from '../ui/card';
import { getFixedAssetsController } from '../../controllers/FixedAssetsController';
import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import type { AssetCategory } from '../../services/accounting/AssetCategoryService';
import type { AssetPurchaseData, FixedAsset } from '../../services/accounting/FixedAssetService';
import { useLocale } from '../../i18n/useLocale';
import { useAuth } from '@/contexts/AuthContext';


interface AssetFormProps {
    asset: FixedAsset | null;
    onSave: () => void;
    onCancel: () => void;
    db: SQLiteEngine;
}

export const AssetForm: React.FC<AssetFormProps> = ({ asset, onSave, onCancel, db }) => {
    const { user } = useAuth();
    const { t } = useLocale();
    const [categories, setCategories] = useState<AssetCategory[]>([]);
    const [selectedCategory, setSelectedCategory] = useState<AssetCategory | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string>('');

    // Form data in dollars (UI) - will convert to cents for backend
    const [formData, setFormData] = useState({
        asset_name: '',
        description: '',
        category_id: 0,
        purchase_date: new Date().toISOString().split('T')[0],
        purchase_cost_dollars: 0,
        salvage_value_dollars: 0,
        useful_life_months: 0,
        depreciation_method: 'STRAIGHT_LINE' as 'STRAIGHT_LINE' | 'DECLINING_BALANCE_200',
        activate_immediately: false,
        payment_method: 'CASH' as 'CASH' | 'PAYABLE'
    });

    // Load categories on mount
    useEffect(() => {
        loadCategories();
    }, []);

    // Load asset data if editing
    useEffect(() => {
        if (asset) {
            setFormData({
                asset_name: asset.asset_name,
                description: asset.description || '',
                category_id: asset.category_id,
                purchase_date: asset.purchase_date,
                purchase_cost_dollars: asset.purchase_cost / 100,
                salvage_value_dollars: asset.salvage_value / 100,
                useful_life_months: asset.useful_life_months,
                depreciation_method: asset.depreciation_method,
                activate_immediately: false,
                payment_method: 'CASH'
            });
        }
    }, [asset]);

    // Auto-fill defaults when category changes
    useEffect(() => {
        if (formData.category_id && !asset) {
            const category = categories.find(c => c.id === formData.category_id);
            if (category) {
                setSelectedCategory(category);
                setFormData(prev => ({
                    ...prev,
                    useful_life_months: category.default_useful_life_months,
                    depreciation_method: category.default_depreciation_method,
                    salvage_value_dollars: (prev.purchase_cost_dollars * category.default_salvage_value_percent) / 100
                }));
            }
        }
    }, [formData.category_id, categories, asset]);

    const loadCategories = async () => {
        try {
            const controller = getFixedAssetsController(db);
            const cats = await controller.getActiveCategories();
            setCategories(cats);
        } catch (err: any) {
            setError(t('assets.form.errorLoadingCategories') + ': ' + err.message);
        }
    };

    const validateForm = (): boolean => {
        if (!formData.asset_name.trim()) {
            setError(t('assets.form.nameRequired'));
            return false;
        }

        if (!formData.category_id) {
            setError(t('assets.form.categoryRequired'));
            return false;
        }

        if (formData.purchase_cost_dollars <= 0) {
            setError(t('assets.form.costPositive'));
            return false;
        }

        if (formData.salvage_value_dollars >= formData.purchase_cost_dollars) {
            setError(t('assets.form.salvageLessCost'));
            return false;
        }

        if (formData.useful_life_months <= 0) {
            setError(t('assets.form.lifePositive'));
            return false;
        }

        return true;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        if (!user?.id) {
            console.error('[AssetForm] userId no disponible. Operaci├│n abortada.');
            return;
        }

        if (!validateForm()) return;

        setLoading(true);
        try {
            const controller = getFixedAssetsController(db);

            // Convert dollars to cents
            const purchaseData: AssetPurchaseData = {
                asset_name: formData.asset_name,
                description: formData.description,
                category_id: formData.category_id,
                purchase_date: formData.purchase_date,
                purchase_cost: Math.round(formData.purchase_cost_dollars * 100),
                salvage_value: Math.round(formData.salvage_value_dollars * 100),
                useful_life_months: formData.useful_life_months,
                depreciation_method: formData.depreciation_method,
                activate_immediately: formData.activate_immediately,
                payment_method: formData.payment_method
            };

            if (asset) {
                // Update existing asset
                await controller.updateAsset(asset.id, purchaseData);
            } else {
                // Create new asset
                await controller.purchaseAsset(purchaseData, user?.id ?? null);
            }

            onSave();
        } catch (err: any) {
            setError(err.message || t('assets.form.saveError'));
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (field: keyof typeof formData, value: any) => {
        setFormData(prev => ({ ...prev, [field]: value }));
        setError(''); // Clear error when user changes input
    };

    // Calculate preview of monthly depreciation
    const calculatePreviewDepreciation = (): number => {
        const depreciableBase = formData.purchase_cost_dollars - formData.salvage_value_dollars;
        if (formData.useful_life_months <= 0) return 0;

        if (formData.depreciation_method === 'STRAIGHT_LINE') {
            return depreciableBase / formData.useful_life_months;
        } else {
            // Declining balance 200% - first month
            const rate = 2 / formData.useful_life_months;
            return formData.purchase_cost_dollars * rate;
        }
    };

    const monthlyDepreciation = calculatePreviewDepreciation();
    const isEdit = !!asset?.id;

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
            <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-4xl max-h-[95vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-500/5 blur-[120px] pointer-events-none"></div>

                {/* Header Hub */}
                <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
                    <div className="flex items-center gap-6">
                        <div className="text-indigo-500">
                            <Building2 className="w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                                {isEdit ? t('assets.editAsset') : t('assets.addAsset')}
                            </h2>
                            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2 flex items-center gap-2">
                                <ShieldCheck className="w-3.5 h-3.5 text-blue-500" /> {isEdit ? `${t('assets.reports_ui.tag')}: ${asset.asset_tag}` : t('assets.form.purchaseSetup')}
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={onCancel}
                        className="p-3 bg-slate-950/50 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95"
                    >
                        <XCircle className="w-6 h-6" />
                    </button>
                </header>

                <div className="flex-1 overflow-y-auto p-10 space-y-8 relative z-10 custom-scrollbar">
                    {/* Error Alert */}
                    {error && (
                        <div className="bg-rose-500/10 border border-rose-500/50 rounded-2xl p-6 flex items-start gap-4 animate-in slide-in-from-top-2">
                            <AlertCircle className="w-6 h-6 text-rose-500 flex-shrink-0" />
                            <p className="text-rose-200 text-sm font-bold uppercase tracking-tight">{error}</p>
                        </div>
                    )}

                    <form onSubmit={handleSubmit} id="asset-form" className="space-y-10">
                        {/* Basic Information */}
                        <div className="space-y-8">
                            <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-3">
                                <Info className="w-4 h-4 text-indigo-400" />
                                {t('assets.form.basicInfo')}
                            </h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                {/* Asset Name */}
                                <div className="md:col-span-2">
                                    <PremiumInput
                                        label={t('assets.form.assetName')}
                                        required
                                        value={formData.asset_name}
                                        onChange={(v: string) => handleChange('asset_name', v)}
                                        placeholder={t('assets.form.assetNamePlaceholder')}
                                    />
                                </div>

                                {/* Category */}
                                <div className="space-y-3">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1">
                                        {t('assets.form.category')} <span className="text-rose-500">*</span>
                                    </label>
                                    <div className="relative group">
                                        <select
                                            required
                                            value={formData.category_id || ''}
                                            onChange={(e) => handleChange('category_id', parseInt(e.target.value))}
                                            className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-bold uppercase tracking-widest text-[9px] appearance-none disabled:opacity-50"
                                            disabled={isEdit}
                                        >
                                            <option value="">{t('assets.form.selectCategory')}</option>
                                            {categories.map(cat => (
                                                <option key={cat.id} value={cat.id}>
                                                    {cat.name} ({cat.default_useful_life_months / 12} {t('assets.form.years')})
                                                </option>
                                            ))}
                                        </select>
                                        <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-slate-600 font-black">Γû╝</div>
                                    </div>
                                    {selectedCategory && !isEdit && (
                                        <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-xl p-3 mt-2 flex items-center gap-3">
                                            <CheckCircle className="w-3.5 h-3.5 text-emerald-500" />
                                            <p className="text-[9px] font-black text-emerald-400 uppercase tracking-widest">
                                                {t('assets.form.autoFilled', {
                                                    months: selectedCategory.default_useful_life_months,
                                                    method: selectedCategory.default_depreciation_method.replace('_', ' ')
                                                })}
                                            </p>
                                        </div>
                                    )}
                                </div>

                                {/* Purchase Date */}
                                <div className="space-y-3">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1">
                                        {t('assets.form.purchaseDate')} <span className="text-rose-500">*</span>
                                    </label>
                                    <div className="relative group/input">
                                        <Calendar className="absolute left-6 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600 group-focus-within/input:text-blue-500 transition-colors" />
                                        <input
                                            type="date"
                                            required
                                            value={formData.purchase_date}
                                            onChange={(e) => handleChange('purchase_date', e.target.value)}
                                            className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl pl-14 pr-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-bold uppercase tracking-widest text-[10px]"
                                        />
                                    </div>
                                </div>

                                {/* Description */}
                                <div className="md:col-span-2">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1 block mb-3">
                                        {t('common.description')}
                                    </label>
                                    <textarea
                                        value={formData.description}
                                        onChange={(e) => handleChange('description', e.target.value)}
                                        rows={2}
                                        className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-medium text-sm placeholder:text-slate-800 resize-none"
                                        placeholder={t('assets.form.descriptionPlaceholder')}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Financial Information */}
                        <div className="space-y-8 pt-6 border-t border-slate-800/50">
                            <h3 className="text-[10px] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-3">
                                <DollarSign className="w-4 h-4" />
                                {t('assets.form.financialInfo')}
                            </h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                {/* Purchase Cost */}
                                <div>
                                    <PremiumInput
                                        label={t('assets.form.purchaseCost')}
                                        required
                                        type="number"
                                        value={formData.purchase_cost_dollars || ''}
                                        onChange={(v: string) => handleChange('purchase_cost_dollars', parseFloat(v) || 0)}
                                        prefix="$"
                                        mono
                                    />
                                </div>

                                {/* Salvage Value */}
                                <div>
                                    <PremiumInput
                                        label={t('assets.form.salvageValue')}
                                        type="number"
                                        value={formData.salvage_value_dollars || ''}
                                        onChange={(v: string) => handleChange('salvage_value_dollars', parseFloat(v) || 0)}
                                        prefix="$"
                                        mono
                                    />
                                </div>

                                {/* Useful Life */}
                                <div className="space-y-3">
                                    <PremiumInput
                                        label={t('assets.form.usefulLife')}
                                        required
                                        type="number"
                                        value={formData.useful_life_months || ''}
                                        onChange={(v: string) => handleChange('useful_life_months', parseInt(v) || 0)}
                                        placeholder="60"
                                        suffix={t('assets.form.months')}
                                        mono
                                    />
                                    <p className="text-[10px] font-bold text-slate-600 uppercase tracking-widest mt-1 ml-1">
                                        {formData.useful_life_months > 0 && `Γëê ${(formData.useful_life_months / 12).toFixed(1)} ${t('assets.form.years')}`}
                                    </p>
                                </div>

                                {/* Depreciation Method */}
                                <div className="space-y-3">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1">
                                        {t('assets.form.depreciationMethod')}
                                    </label>
                                    <div className="relative group">
                                        <select
                                            value={formData.depreciation_method}
                                            onChange={(e) => handleChange('depreciation_method', e.target.value)}
                                            className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-bold uppercase tracking-widest text-[9px] appearance-none disabled:opacity-50"
                                            disabled={isEdit && asset?.status !== 'PENDING'}
                                        >
                                            <option value="STRAIGHT_LINE">{t('assets.form.methodStraightLine')}</option>
                                            <option value="DECLINING_BALANCE_200">{t('assets.form.methodDeclining')}</option>
                                        </select>
                                        <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-slate-600 font-black">Γû╝</div>
                                    </div>
                                    {isEdit && asset?.status !== 'PENDING' && (
                                        <div className="flex items-center gap-2 mt-1 ml-1">
                                            <span className="text-[9px] font-black text-amber-500 uppercase tracking-widest">≡ƒöÆ {t('assets.form.lockedIRS')}</span>
                                        </div>
                                    )}
                                </div>

                                {/* Payment Method (only for new assets) */}
                                {!isEdit && (
                                    <div className="md:col-span-2 space-y-4">
                                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1 ml-1">
                                            {t('assets.form.paymentMethod')}
                                        </label>
                                        <div className="grid grid-cols-2 gap-6 bg-slate-950/50 p-2 rounded-[1.5rem] border border-slate-800/50 text-white">
                                            {[
                                                { id: 'CASH', label: t('assets.form.paymentCash') },
                                                { id: 'PAYABLE', label: t('assets.form.paymentPayable') }
                                            ].map((method) => (
                                                <button
                                                    key={method.id}
                                                    type="button"
                                                    onClick={() => handleChange('payment_method', method.id)}
                                                    className={`py-4 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${formData.payment_method === method.id
                                                        ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/40'
                                                        : 'text-slate-500 hover:text-slate-300'
                                                        }`}
                                                >
                                                    {method.label}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Depreciation Preview */}
                            {monthlyDepreciation > 0 && (
                                <div className="mt-8 p-10 bg-indigo-500/5 border border-indigo-500/20 rounded-[2rem] relative group overflow-hidden">
                                    <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                                        <TrendingDown className="w-32 h-32 text-indigo-400" />
                                    </div>
                                    <div className="relative z-10">
                                        <div className="flex items-center gap-3 mb-8">
                                            <TrendingDown className="w-5 h-5 text-indigo-400" />
                                            <h4 className="text-[11px] font-black text-indigo-300 uppercase tracking-widest">{t('assets.reports_ui.trend')}</h4>
                                        </div>
                                        <div className="grid grid-cols-3 gap-10">
                                            <MetricItem label={t('assets.reports_ui.avgMonthly')} value={`$${monthlyDepreciation.toFixed(2)}`} mono />
                                            <MetricItem label={t('assets.reports_ui.projected')} value={`$${(monthlyDepreciation * 12).toFixed(2)}`} mono />
                                            <MetricItem
                                                label={t('assets.reports_ui.method')}
                                                value={formData.depreciation_method === 'STRAIGHT_LINE' ? t('assets.reports_ui.linear') : t('assets.reports_ui.accelerated')}
                                                highlight
                                            />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Activation Option (only for new assets) */}
                        {!isEdit && (
                            <div className="pt-8 border-t border-slate-800/50">
                                <label className="flex items-start gap-6 cursor-pointer group bg-slate-950/30 p-8 rounded-[2rem] border border-slate-800/50 hover:border-blue-500/30 transition-all">
                                    <div className="relative mt-1">
                                        <input
                                            type="checkbox"
                                            checked={formData.activate_immediately}
                                            onChange={(e) => handleChange('activate_immediately', e.target.checked)}
                                            className="sr-only"
                                        />
                                        <div className={`w-12 h-6 rounded-full transition-colors duration-300 ${formData.activate_immediately ? 'bg-emerald-600 shadow-[0_0_15px_rgba(16,185,129,0.4)]' : 'bg-slate-800'}`}></div>
                                        <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform duration-300 ${formData.activate_immediately ? 'translate-x-6' : 'translate-x-0'}`}></div>
                                    </div>
                                    <div>
                                        <p className="text-sm font-black text-white uppercase tracking-tight">{t('assets.form.activateImmediately')}</p>
                                        <p className="text-[10px] font-bold text-slate-500 mt-1 uppercase tracking-widest leading-relaxed">
                                            {t('assets.form.activateImmediatelyHint')}
                                        </p>
                                    </div>
                                </label>
                            </div>
                        )}
                    </form>
                </div>

                {/* Footer Actions */}
                <footer className="p-10 border-t border-slate-800/50 bg-slate-950/30 flex justify-end gap-6 flex-shrink-0 relative z-10">
                    <button
                        type="button"
                        onClick={onCancel}
                        className="px-10 py-5 text-slate-500 hover:text-white transition-all font-black uppercase tracking-widest text-[10px] hover:bg-slate-900 rounded-2xl border border-transparent hover:border-slate-800"
                        disabled={loading}
                    >
                        {t('common.cancel')}
                    </button>
                    <button
                        form="asset-form"
                        type="submit"
                        className="bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white px-12 py-5 rounded-2.5xl font-black uppercase tracking-widest text-[11px] transition-all flex items-center justify-center gap-4 shadow-3xl shadow-indigo-900/40 hover:-translate-y-1 active:scale-95"
                        disabled={loading}
                    >
                        {loading ? (
                            <RefreshCw className="h-5 w-5 animate-spin" />
                        ) : (
                            <Save className="w-5 h-5" />
                        )}
                        <span>{loading ? t('common.saving') : isEdit ? t('assets.form.updateBtn') : t('assets.form.createBtn')}</span>
                    </button>
                </footer>
            </div>
        </div>
    );
};

// Subcomponentes Elite
const PremiumInput = ({ label, value, onChange, type = "text", required, placeholder, prefix, suffix, mono }: any) => (
    <div className="space-y-3">
        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1 block">
            {label} {required && <span className="text-rose-500">*</span>}
        </label>
        <div className="relative group/input">
            {prefix && <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-600 font-bold text-xs">{prefix}</div>}
            <input
                type={type}
                value={value}
                onChange={(e) => onChange(e.target.value)}
                className={`w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl py-4 focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[10px] placeholder:text-slate-800 ${prefix ? 'pl-12 pr-6' : 'px-8'} ${suffix ? 'pr-20' : ''} ${mono ? 'font-mono tracking-tighter' : ''}`}
                placeholder={placeholder}
                required={required}
            />
            {suffix && (
                <div className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-600 font-black text-[9px] uppercase tracking-widest">
                    {suffix}
                </div>
            )}
        </div>
    </div>
);

const MetricItem = ({ label, value, mono, highlight }: any) => (
    <div className="text-center">
        <p className="text-[9px] font-black text-slate-600 uppercase tracking-[0.2em] mb-3">{label}</p>
        <p className={`text-xl font-black ${highlight ? 'text-indigo-400' : 'text-white'} ${mono ? 'font-mono italic' : 'tracking-tighter uppercase'}`}>{value}</p>
    </div>
);

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import {
  Package,
  Plus,
  TrendingDown,
  DollarSign,
  Calendar,
  AlertTriangle,
  Play,
  FileText,
  Settings
} from 'lucide-react';
import { getFixedAssetsController } from '@/services/accounting/fixed-assets';
import type { FixedAsset, AssetCategory } from '@/services/accounting/fixed-assets';
import { AssetForm } from './AssetForm';
import { AssetDetailView } from './AssetDetailView';
import { AssetDisposalForm } from './AssetDisposalForm';
import { AssetRegisterReport } from './reports/AssetRegisterReport';
import { DepreciationScheduleReport } from './reports/DepreciationScheduleReport';
import { DisposalSummaryReport } from './reports/DisposalSummaryReport';
import { useLocale } from '@/i18n/useLocale';
import { useAuth } from '@/contexts/AuthContext';


interface FixedAssetsManagerProps {
  db: any; // Database instance passed from App
}

/**
 * FixedAssetsManager
 * 
 * Main dashboard for Fixed Assets module with:
 * - Asset summary KPIs
 * - Asset list with filters
 * - Quick actions (Add Asset, Run Depreciation, Reports)
 * - Category management
 */
export const FixedAssetsManager: React.FC<FixedAssetsManagerProps> = ({ db }) => {
  const { user } = useAuth();
  const { t } = useLocale();
  const [assets, setAssets] = useState<FixedAsset[]>([]);
  const [categories, setCategories] = useState<AssetCategory[]>([]);
  const [summary, setSummary] = useState({
    total_assets: 0,
    active_assets: 0,
    total_cost: 0,
    total_depreciation: 0,
    net_book_value: 0
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'assets' | 'categories' | 'reports'>('assets');
  const [showAssetForm, setShowAssetForm] = useState(false);
  const [editingAsset, setEditingAsset] = useState<FixedAsset | null>(null);
  const [viewingAsset, setViewingAsset] = useState<FixedAsset | null>(null);
  const [disposingAsset, setDisposingAsset] = useState<FixedAsset | null>(null);
  const [activeReport, setActiveReport] = useState<'register' | 'schedule' | 'disposals' | null>(null);

  useEffect(() => {
    if (db) {
      loadData();
    }
  }, [db]);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);

      const controller = getFixedAssetsController(db);

      // Load assets and categories
      const [assetsData, categoriesData, summaryData] = await Promise.all([
        controller.getAllAssets(),
        controller.getCategories(),
        controller.getAssetSummary()
      ]);

      setAssets(assetsData);
      setCategories(categoriesData);
      setSummary(summaryData);

    } catch (err) {
      console.error('Error loading fixed assets:', err);
      setError(err instanceof Error ? err.message : t('fixedAssets.loading'));
    } finally {
      setLoading(false);
    }
  };

  const handleRunDepreciation = async () => {
    try {
      setLoading(true);
      setError(null);

      if (!user?.id) {
        console.error('[FixedAssetsManager] userId no disponible. Operaci├│n abortada.');
        return;
      }

      const controller = getFixedAssetsController(db);
      const now = new Date();

      const result = await controller.runDepreciationBatch(now, user.id);

      setSuccess(`Depreciaci├│n procesada: ${result.total_assets_processed} activos, Total: ${(result.total_depreciation_amount / 100).toFixed(2)}`);

      // Reload data
      await loadData();

      setTimeout(() => setSuccess(null), 5000);

    } catch (err) {
      console.error('Error running depreciation:', err);
      setError(err instanceof Error ? err.message : t('fixedAssets.messages.depreciationError'));
    } finally {
      setLoading(false);
    }
  };

  // View asset detail
  if (viewingAsset) {
    return (
      <AssetDetailView
        asset={viewingAsset}
        onBack={() => setViewingAsset(null)}
        onEdit={(asset) => {
          setViewingAsset(null);
          setEditingAsset(asset);
          setShowAssetForm(true);
        }}
        onDispose={(asset) => {
          setViewingAsset(null);
          setDisposingAsset(asset);
        }}
      />
    );
  }

  if (loading && assets.length === 0) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-slate-400">{t('fixedAssets.loading')}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white flex items-center gap-3">
            <Package className="w-8 h-8 text-blue-400" />
            {t('fixedAssets.management')}
          </h1>
          <p className="text-slate-400 mt-1">{t('fixedAssets.subtitle')}</p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleRunDepreciation}
            disabled={loading || assets.length === 0}
            className="bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white px-6 py-2.5 rounded-xl flex items-center gap-2 transition-all font-bold shadow-lg shadow-emerald-900/40 active:scale-95"
          >
            <Play className="w-4 h-4" />
            {t('fixedAssets.runDepreciation')}
          </button>
          <button
            onClick={() => {
              setEditingAsset(null);
              setShowAssetForm(true);
            }}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl flex items-center gap-2 transition-all font-bold shadow-lg shadow-blue-900/40 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            {t('fixedAssets.newAsset')}
          </button>
        </div>
      </div>

      {/* Alerts */}
      {error && (
        <Alert className="bg-red-950/20 border-red-900/50 text-red-200">
          <AlertTriangle className="w-4 h-4" />
          <AlertTitle>{t('common.error')}</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {success && (
        <Alert className="bg-green-950/20 border-green-900/50 text-green-200">
          <AlertTitle>{t('common.success')}</AlertTitle>
          <AlertDescription>{success}</AlertDescription>
        </Alert>
      )}

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-400 flex items-center gap-2">
              <DollarSign className="w-4 h-4" />
              {t('fixedAssets.totalCost')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black tracking-tight text-blue-400 font-mono">
              ${(summary.total_cost / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
            </div>
            <p className="text-xs text-slate-500 mt-1">{t('fixedAssets.acquisitionCost')}</p>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-400 flex items-center gap-2">
              <TrendingDown className="w-4 h-4" />
              {t('fixedAssets.accumulatedDepreciation')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black tracking-tight text-amber-400 font-mono">
              ${(summary.total_depreciation / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
            </div>
            <p className="text-xs text-slate-500 mt-1">{t('fixedAssets.totalDepreciated')}</p>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-400 flex items-center gap-2">
              <Package className="w-4 h-4" />
              {t('fixedAssets.bookValue')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black tracking-tight text-green-400 font-mono">
              ${(summary.net_book_value / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
            </div>
            <p className="text-xs text-slate-500 mt-1">{t('fixedAssets.netBookValue')}</p>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-slate-400 flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              {t('fixedAssets.activeAssets')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black tracking-tight text-slate-200">
              {summary.active_assets}
            </div>
            <p className="text-xs text-slate-500 mt-1">{t('fixedAssets.inDepreciation')}</p>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-slate-800">
        <button
          onClick={() => setActiveTab('assets')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'assets'
            ? 'text-blue-400 border-b-2 border-blue-400'
            : 'text-slate-400 hover:text-white'
            }`}
        >
          <Package className="w-4 h-4 inline mr-2" />
          {t('fixedAssets.assetList')}
        </button>
        <button
          onClick={() => setActiveTab('categories')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'categories'
            ? 'text-blue-400 border-b-2 border-blue-400'
            : 'text-slate-400 hover:text-white'
            }`}
        >
          <Settings className="w-4 h-4 inline mr-2" />
          {t('fixedAssets.categories')}
        </button>
        <button
          onClick={() => setActiveTab('reports')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'reports'
            ? 'text-blue-400 border-b-2 border-blue-400'
            : 'text-slate-400 hover:text-white'
            }`}
        >
          <FileText className="w-4 h-4 inline mr-2" />
          {t('common.reports')}
        </button>
      </div>

      {/* Tab Content */}
      <div className="mt-6">
        {activeTab === 'assets' && (
          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardHeader>
              <CardTitle>{t('fixedAssets.assetList')}</CardTitle>
            </CardHeader>
            <CardContent>
              {assets.length === 0 ? (
                <div className="text-center py-12">
                  <Package className="w-16 h-16 text-slate-700 mx-auto mb-4" />
                  <p className="text-slate-400">{t('fixedAssets.noAssets')}</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-slate-800">
                        <th className="text-left py-3 px-4 text-sm font-medium text-slate-400">Tag</th>
                        <th className="text-left py-3 px-4 text-sm font-medium text-slate-400">{t('common.name')}</th>
                        <th className="text-left py-3 px-4 text-sm font-medium text-slate-400">{t('common.category')}</th>
                        <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('common.cost')}</th>
                        <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('fixedAssets.accumulatedDepreciation')}</th>
                        <th className="text-right py-3 px-4 text-sm font-medium text-slate-400">{t('fixedAssets.netValue')}</th>
                        <th className="text-center py-3 px-4 text-sm font-medium text-slate-400">{t('common.status')}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {assets.map((asset) => (
                        <tr
                          key={asset.id}
                          onClick={() => setViewingAsset(asset)}
                          className="border-b border-slate-800 hover:bg-slate-800/50 transition-colors cursor-pointer"
                        >
                          <td className="py-3 px-4 text-sm font-mono text-blue-400">{asset.asset_code}</td>
                          <td className="py-3 px-4 text-sm">{asset.name}</td>
                          <td className="py-3 px-4 text-sm text-slate-400">
                            {categories.find(c => c.id === asset.category_id)?.name || 'N/A'}
                          </td>
                          <td className="py-3 px-4 text-sm text-right font-mono">
                            ${((asset.purchase_cost || 0) / 100).toFixed(2)}
                          </td>
                          <td className="py-3 px-4 text-sm text-right font-mono text-amber-400">
                            ${((asset.total_accumulated_depreciation || 0) / 100).toFixed(2)}
                          </td>
                          <td className="py-3 px-4 text-sm text-right font-mono text-green-400">
                            ${((asset.net_book_value || 0) / 100).toFixed(2)}
                          </td>
                          <td className="py-3 px-4 text-center">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${asset.status === 'ACTIVE' ? 'bg-green-900/30 text-green-400' :
                              asset.status === 'FULLY_DEPRECIATED' ? 'bg-blue-900/30 text-blue-400' :
                                'bg-slate-700 text-slate-400'
                              }`}>
                              {asset.status}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </CardContent>
          </Card>
        )}

        {activeTab === 'categories' && (
          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardHeader>
              <CardTitle>{t('fixedAssets.categories')}</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {categories.map((category) => (
                  <div key={category.id} className="p-4 border border-slate-800 rounded-lg hover:border-blue-500/50 transition-colors">
                    <div className="flex items-start justify-between mb-2">
                      <div>
                        <h3 className="font-medium text-white">{category.name}</h3>
                        <p className="text-xs text-slate-500 font-mono">{category.code}</p>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs ${category.is_active ? 'bg-green-900/30 text-green-400' : 'bg-slate-700 text-slate-400'
                        }`}>
                        {category.is_active ? t('fixedAssets.active') : t('fixedAssets.inactive')}
                      </span>
                    </div>
                    <div className="space-y-1 text-sm">
                      <div className="flex justify-between">
                        <span className="text-slate-400">{t('fixedAssets.method')}:</span>
                        <span className="text-slate-200">{category.default_depreciation_method}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-slate-400">{t('fixedAssets.usefulLife')}:</span>
                        <span className="text-slate-200">{category.default_useful_life_months} {t('fixedAssets.months')}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-slate-400">{t('fixedAssets.assetAccount')}:</span>
                        <span className="text-slate-200 font-mono">{category.gl_asset_account}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {activeTab === 'reports' && (
          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardHeader>
              <CardTitle>{t('common.reports')}</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <button
                  onClick={() => setActiveReport('register')}
                  className="p-6 border border-slate-800 rounded-lg hover:border-blue-500/50 hover:bg-slate-800/50 transition-all text-left"
                >
                  <FileText className="w-8 h-8 text-blue-400 mb-3" />
                  <h3 className="font-medium text-white mb-1">{t('fixedAssets.assetRegister')}</h3>
                  <p className="text-sm text-slate-400">{t('fixedAssets.reports.fullList')}</p>
                </button>
                <button
                  onClick={() => setActiveReport('schedule')}
                  className="p-6 border border-slate-800 rounded-lg hover:border-blue-500/50 hover:bg-slate-800/50 transition-all text-left"
                >
                  <Calendar className="w-8 h-8 text-amber-400 mb-3" />
                  <h3 className="font-medium text-white mb-1">{t('fixedAssets.depreciationSchedule')}</h3>
                  <p className="text-sm text-slate-400">{t('fixedAssets.reports.monthlyProjection')}</p>
                </button>
                <button
                  onClick={() => setActiveReport('disposals')}
                  className="p-6 border border-slate-800 rounded-lg hover:border-blue-500/50 hover:bg-slate-800/50 transition-all text-left"
                >
                  <TrendingDown className="w-8 h-8 text-green-400 mb-3" />
                  <h3 className="font-medium text-white mb-1">{t('fixedAssets.disposalSummary')}</h3>
                  <p className="text-sm text-slate-400">{t('fixedAssets.reports.soldOrDisposed')}</p>
                </button>
              </div>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Asset Form Modal */}
      {showAssetForm && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 rounded-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <AssetForm
                asset={editingAsset}
                onSave={async () => {
                  setShowAssetForm(false);
                  setEditingAsset(null);
                  await loadData();
                  setSuccess(editingAsset ? t('fixedAssets.messages.updateSuccess') : t('fixedAssets.messages.createSuccess'));
                  setTimeout(() => setSuccess(null), 3000);
                }}
                onCancel={() => {
                  setShowAssetForm(false);
                  setEditingAsset(null);
                }}
                db={db}
              />
            </div>
          </div>
        </div>
      )}

      {/* Asset Disposal Modal */}
      {disposingAsset && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <AssetDisposalForm
                asset={disposingAsset}
                onDispose={async () => {
                  setDisposingAsset(null);
                  await loadData();
                  setSuccess(t('fixedAssets.messages.disposeSuccess'));
                  setTimeout(() => setSuccess(null), 3000);
                }}
                onCancel={() => setDisposingAsset(null)}
                db={db}
              />
            </div>
          </div>
        </div>
      )}

      {/* Report Modals */}
      {activeReport === 'register' && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 rounded-2xl max-w-6xl w-full max-h-[90vh] overflow-y-auto">
            <AssetRegisterReport
              db={db}
              onClose={() => setActiveReport(null)}
            />
          </div>
        </div>
      )}

      {activeReport === 'schedule' && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 rounded-2xl max-w-6xl w-full max-h-[90vh] overflow-y-auto">
            <DepreciationScheduleReport
              db={db}
              onClose={() => setActiveReport(null)}
            />
          </div>
        </div>
      )}

      {activeReport === 'disposals' && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 rounded-2xl max-w-6xl w-full max-h-[90vh] overflow-y-auto">
            <DisposalSummaryReport
              db={db}
              onClose={() => setActiveReport(null)}
            />
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Download, Printer, Filter, X } from 'lucide-react';
import { Button } from '../../ui/button';
import { Card, CardContent } from '../../ui/card';
import { getFixedAssetsController } from '../../../controllers/FixedAssetsController';
import { SQLiteEngine } from '../../../core/database/SQLiteEngine';
import type { FixedAsset, AssetCategory } from '../../../services/accounting/fixed-assets';
import { useLocale } from '../../../i18n/useLocale';

interface AssetRegisterReportProps {
    db: SQLiteEngine;
    onClose: () => void;
}

export const AssetRegisterReport: React.FC<AssetRegisterReportProps> = ({ db, onClose }) => {
    const { t } = useLocale();
    const [assets, setAssets] = useState<FixedAsset[]>([]);
    const [categories, setCategories] = useState<AssetCategory[]>([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({
        category_id: 0,
        status: 'ALL' as 'ALL' | 'ACTIVE' | 'PENDING' | 'FULLY_DEPRECIATED' | 'DISPOSED'
    });

    useEffect(() => {
        loadData();
    }, [filters]);

    const loadData = async () => {
        try {
            setLoading(true);
            const controller = getFixedAssetsController(db);

            const [assetsData, categoriesData] = await Promise.all([
                controller.getAllAssets(),
                controller.getCategories()
            ]);

            // Apply filters
            let filtered = assetsData;

            if (filters.category_id > 0) {
                filtered = filtered.filter(a => a.category_id === filters.category_id);
            }

            if (filters.status !== 'ALL') {
                filtered = filtered.filter(a => a.status === filters.status);
            }

            setAssets(filtered);
            setCategories(categoriesData);
        } catch (err) {
            console.error('Error loading asset register:', err);
        } finally {
            setLoading(false);
        }
    };

    const exportToCSV = () => {
        const headers = [
            t('assets.reports_ui.csv.tag'),
            t('assets.reports_ui.csv.name'),
            t('assets.reports_ui.csv.category'),
            t('assets.reports_ui.csv.date'),
            t('assets.reports_ui.csv.cost'),
            t('assets.reports_ui.csv.accDep'),
            t('assets.reports_ui.csv.nbv'),
            t('assets.reports_ui.csv.status')
        ];

        const rows = assets.map(asset => {
            const category = categories.find(c => c.id === asset.category_id);
            return [
                asset.asset_tag,
                asset.asset_name,
                category?.name || 'N/A',
                asset.purchase_date,
                (asset.purchase_cost / 100).toFixed(2),
                (asset.total_accumulated_depreciation / 100).toFixed(2),
                ((asset.net_book_value || 0) / 100).toFixed(2),
                t(`assets.status.${asset.status.toLowerCase()}`)
            ];
        });

        const csvContent = [
            headers.join(','),
            ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `asset-register-${new Date().toISOString().split('T')[0]}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    };

    const handlePrint = () => {
        window.print();
    };

    // Calculate totals
    const totals = assets.reduce(
        (acc, asset) => ({
            cost: acc.cost + asset.purchase_cost,
            depreciation: acc.depreciation + asset.total_accumulated_depreciation,
            bookValue: acc.bookValue + (asset.net_book_value || 0)
        }),
        { cost: 0, depreciation: 0, bookValue: 0 }
    );

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500 mx-auto mb-4"></div>
                    <p className="text-slate-400">{t('assets.reports_ui.loading')}</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between print:hidden">
                <div>
                    <h2 className="text-2xl font-black text-white">{t('assets.reports.register')}</h2>
                    <p className="text-slate-500 text-sm mt-1">
                        {t('assets.reports_ui.subtitleRegister', { date: new Date().toLocaleDateString() })}
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button
                        onClick={exportToCSV}
                        className="bg-emerald-600 hover:bg-emerald-700 text-white"
                    >
                        <Download className="w-4 h-4 mr-2" />
                        {t('assets.reports_ui.export')}
                    </Button>
                    <Button
                        onClick={handlePrint}
                        className="bg-blue-600 hover:bg-blue-700 text-white"
                    >
                        <Printer className="w-4 h-4 mr-2" />
                        {t('assets.reports_ui.print')}
                    </Button>
                    <button
                        onClick={onClose}
                        className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-500 hover:text-white"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Filters */}
            <Card className="bg-slate-900 border-slate-800 print:hidden">
                <CardContent className="p-4">
                    <div className="flex items-center gap-4">
                        <Filter className="w-5 h-5 text-slate-400" />
                        <div className="flex gap-4 flex-1">
                            <select
                                value={filters.category_id}
                                onChange={(e) => setFilters({ ...filters, category_id: parseInt(e.target.value) })}
                                className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-white text-sm"
                            >
                                <option value={0}>{t('assets.reports_ui.allCategories')}</option>
                                {categories.map(cat => (
                                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                                ))}
                            </select>

                            <select
                                value={filters.status}
                                onChange={(e) => setFilters({ ...filters, status: e.target.value as any })}
                                className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-white text-sm"
                            >
                                <option value="ALL">{t('assets.reports_ui.allStatus')}</option>
                                <option value="ACTIVE">{t('assets.status.active')}</option>
                                <option value="PENDING">{t('assets.status.pending')}</option>
                                <option value="FULLY_DEPRECIATED">{t('assets.status.fully_depreciated')}</option>
                                <option value="DISPOSED">{t('assets.status.disposed')}</option>
                            </select>
                        </div>
                        <div className="text-sm text-slate-400">
                            {t('assets.reports_ui.assetCount', { count: assets.length })}
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Report Content */}
            <Card className="bg-slate-900 border-slate-800">
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="border-b border-slate-800 bg-slate-950">
                                    <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.tag')}</th>
                                    <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.name')}</th>
                                    <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.form.category')}</th>
                                    <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.form.purchaseDate')}</th>
                                    <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.cost')}</th>
                                    <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.accDep')}</th>
                                    <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.nbv')}</th>
                                    <th className="text-center py-3 px-4 text-xs font-black text-slate-400 uppercase print:hidden">{t('assets.details.status')}</th>
                                </tr>
                            </thead>
                            <tbody>
                                {assets.map((asset) => {
                                    const category = categories.find(c => c.id === asset.category_id);
                                    return (
                                        <tr key={asset.id} className="border-b border-slate-800 hover:bg-slate-800/30">
                                            <td className="py-3 px-4 text-sm font-mono text-blue-400">{asset.asset_tag}</td>
                                            <td className="py-3 px-4 text-sm text-white">{asset.asset_name}</td>
                                            <td className="py-3 px-4 text-sm text-slate-400">{category?.name || 'N/A'}</td>
                                            <td className="py-3 px-4 text-sm text-slate-400">{asset.purchase_date}</td>
                                            <td className="py-3 px-4 text-sm text-right font-mono">
                                                ${(asset.purchase_cost / 100).toFixed(2)}
                                            </td>
                                            <td className="py-3 px-4 text-sm text-right font-mono text-amber-400">
                                                ${(asset.total_accumulated_depreciation / 100).toFixed(2)}
                                            </td>
                                            <td className="py-3 px-4 text-sm text-right font-mono text-emerald-400">
                                                ${((asset.net_book_value || 0) / 100).toFixed(2)}
                                            </td>
                                            <td className="py-3 px-4 text-center print:hidden">
                                                <span className={`px-2 py-1 rounded-lg text-xs font-medium ${asset.status === 'ACTIVE' ? 'bg-emerald-900/30 text-emerald-400' :
                                                    asset.status === 'FULLY_DEPRECIATED' ? 'bg-blue-900/30 text-blue-400' :
                                                        asset.status === 'DISPOSED' ? 'bg-rose-900/30 text-rose-400' :
                                                            'bg-slate-700 text-slate-400'
                                                    }`}>
                                                    {t(`assets.status.${asset.status.toLowerCase()}`)}
                                                </span>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                            <tfoot>
                                <tr className="border-t-2 border-slate-700 bg-slate-950">
                                    <td colSpan={4} className="py-4 px-4 text-sm font-black text-white">
                                        {t('common.total')} ({t('assets.reports_ui.assetCount', { count: assets.length })})
                                    </td>
                                    <td className="py-4 px-4 text-sm text-right font-mono font-black text-white">
                                        ${(totals.cost / 100).toFixed(2)}
                                    </td>
                                    <td className="py-4 px-4 text-sm text-right font-mono font-black text-amber-400">
                                        ${(totals.depreciation / 100).toFixed(2)}
                                    </td>
                                    <td className="py-4 px-4 text-sm text-right font-mono font-black text-emerald-400">
                                        ${(totals.bookValue / 100).toFixed(2)}
                                    </td>
                                    <td className="print:hidden"></td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </CardContent>
            </Card>

            {/* Print Header (only visible when printing) */}
            <div className="hidden print:block text-center mb-4">
                <h1 className="text-2xl font-black tracking-tight">{t('assets.reports.register')}</h1>
                <p className="text-sm text-slate-700">{t('common.generatedOn')} {new Date().toLocaleString()}</p>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Download, Calendar, TrendingDown, X } from 'lucide-react';
import { Button } from '../../ui/button';
import { Card, CardContent } from '../../ui/card';
import { getFixedAssetsController } from '../../../controllers/FixedAssetsController';
import { SQLiteEngine } from '../../../core/database/SQLiteEngine';
import { useLocale } from '../../../i18n/useLocale';

interface DepreciationScheduleReportProps {
    db: SQLiteEngine;
    onClose: () => void;
}

interface MonthlyProjection {
    month: string;
    total_depreciation: number;
    asset_count: number;
}

export const DepreciationScheduleReport: React.FC<DepreciationScheduleReportProps> = ({ db, onClose }) => {
    const { t } = useLocale();
    const [schedule, setSchedule] = useState<MonthlyProjection[]>([]);
    const [loading, setLoading] = useState(true);
    const [months, setMonths] = useState(12);

    useEffect(() => {
        loadSchedule();
    }, [months]);

    const loadSchedule = async () => {
        try {
            setLoading(true);
            const controller = getFixedAssetsController(db);

            // Get all active assets
            const assets = await controller.getAllAssets();
            const activeAssets = assets.filter(a => a.status === 'ACTIVE');

            // Project depreciation for next N months
            const projections: MonthlyProjection[] = [];
            const startDate = new Date();

            for (let i = 0; i < months; i++) {
                const monthDate = new Date(startDate);
                monthDate.setMonth(monthDate.getMonth() + i);

                let monthTotal = 0;
                let assetCount = 0;

                // Calculate depreciation for each asset for this month
                for (const asset of activeAssets) {
                    const depreciableBase = asset.purchase_cost - asset.salvage_value;
                    const monthlyDep = depreciableBase / asset.useful_life_months;

                    const monthsElapsed = Math.floor(
                        (monthDate.getTime() - new Date(asset.purchase_date).getTime()) / (1000 * 60 * 60 * 24 * 30)
                    );

                    if (monthsElapsed >= 0 && monthsElapsed < asset.useful_life_months) {
                        monthTotal += monthlyDep;
                        assetCount++;
                    }
                }

                projections.push({
                    month: monthDate.toLocaleDateString(undefined, { year: 'numeric', month: 'short' }),
                    total_depreciation: Math.round(monthTotal),
                    asset_count: assetCount
                });
            }

            setSchedule(projections);
        } catch (err) {
            console.error('Error loading depreciation schedule:', err);
        } finally {
            setLoading(false);
        }
    };

    const exportToCSV = () => {
        const headers = [
            t('assets.reports_ui.csv.month'),
            t('assets.reports_ui.csv.depreciation'),
            t('assets.reports_ui.csv.assets')
        ];
        const rows = schedule.map(item => [
            item.month,
            (item.total_depreciation / 100).toFixed(2),
            item.asset_count.toString()
        ]);

        const csvContent = [
            headers.join(','),
            ...rows.map(row => row.join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `depreciation-schedule-${new Date().toISOString().split('T')[0]}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    };

    const totalProjected = schedule.reduce((sum, item) => sum + item.total_depreciation, 0);

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500 mx-auto mb-4"></div>
                    <p className="text-slate-400">{t('assets.reports_ui.loadingDepreciation')}</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-black text-white flex items-center gap-3">
                        <TrendingDown className="w-8 h-8 text-amber-400" />
                        {t('assets.reports.depreciation')}
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">
                        {t('assets.reports_ui.subtitleDepreciation', { months })}
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button
                        onClick={exportToCSV}
                        className="bg-emerald-600 hover:bg-emerald-700 text-white"
                    >
                        <Download className="w-4 h-4 mr-2" />
                        {t('assets.reports_ui.export')}
                    </Button>
                    <button
                        onClick={onClose}
                        className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-500 hover:text-white"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Period Selector */}
            <Card className="bg-slate-900 border-slate-800">
                <CardContent className="p-4">
                    <div className="flex items-center gap-4">
                        <Calendar className="w-5 h-5 text-slate-400" />
                        <label className="text-sm text-slate-400 font-bold">{t('assets.reports_ui.periodSelector')}</label>
                        <select
                            value={months}
                            onChange={(e) => setMonths(parseInt(e.target.value))}
                            className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-white text-sm"
                        >
                            <option value={6}>{t('common.periodMonths', { months: 6 })}</option>
                            <option value={12}>{t('common.periodMonths', { months: 12 })}</option>
                            <option value={24}>{t('common.periodMonths', { months: 24 })}</option>
                            <option value={36}>{t('common.periodMonths', { months: 36 })}</option>
                            <option value={60}>{t('common.periodMonths', { months: 60 })}</option>
                        </select>
                    </div>
                </CardContent>
            </Card>

            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <Card className="bg-slate-900 border-slate-800">
                    <CardContent className="p-6">
                        <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">{t('assets.reports_ui.projected')}</p>
                        <p className="text-2xl font-black text-amber-400 font-mono">
                            ${(totalProjected / 100).toFixed(2)}
                        </p>
                    </CardContent>
                </Card>
                <Card className="bg-slate-900 border-slate-800">
                    <CardContent className="p-6">
                        <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">{t('assets.reports_ui.avgMonthly')}</p>
                        <p className="text-2xl font-black text-white font-mono">
                            ${(totalProjected / months / 100).toFixed(2)}
                        </p>
                    </CardContent>
                </Card>
                <Card className="bg-slate-900 border-slate-800">
                    <CardContent className="p-6">
                        <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">{t('assets.reports_ui.period')}</p>
                        <p className="text-2xl font-black text-indigo-400">
                            {t('common.periodMonths', { months })}
                        </p>
                    </CardContent>
                </Card>
            </div>

            {/* Schedule Table */}
            <Card className="bg-slate-900 border-slate-800">
                <CardContent className="p-0">
                    <div className="overflow-x-auto max-h-[500px] overflow-y-auto">
                        <table className="w-full">
                            <thead className="sticky top-0 bg-slate-950 z-10">
                                <tr className="border-b border-slate-800">
                                    <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.csv.month')}</th>
                                    <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.csv.depreciation')}</th>
                                    <th className="text-center py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.csv.assets')}</th>
                                    <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('common.percentOfTotal')}</th>
                                </tr>
                            </thead>
                            <tbody>
                                {schedule.map((item, index) => (
                                    <tr key={index} className="border-b border-slate-800 hover:bg-slate-800/30">
                                        <td className="py-3 px-4 text-sm text-white font-medium">{item.month}</td>
                                        <td className="py-3 px-4 text-sm text-right font-mono text-amber-400">
                                            ${(item.total_depreciation / 100).toFixed(2)}
                                        </td>
                                        <td className="py-3 px-4 text-sm text-center text-slate-400">
                                            {item.asset_count}
                                        </td>
                                        <td className="py-3 px-4 text-sm text-right text-slate-400">
                                            {totalProjected > 0 ? ((item.total_depreciation / totalProjected) * 100).toFixed(1) : '0.0'}%
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>

            {/* Visual Chart (Simplified Bar Chart) */}
            <Card className="bg-slate-900 border-slate-800">
                <CardContent className="p-6">
                    <h3 className="text-lg font-black text-white mb-4">{t('assets.reports_ui.trend')}</h3>
                    <div className="space-y-2">
                        {schedule.map((item, index) => {
                            const maxDep = Math.max(...schedule.map(s => s.total_depreciation));
                            const width = maxDep > 0 ? (item.total_depreciation / maxDep) * 100 : 0;

                            return (
                                <div key={index} className="flex items-center gap-3">
                                    <div className="w-20 text-xs text-slate-400 font-mono">{item.month}</div>
                                    <div className="flex-1 bg-slate-950 rounded-lg h-8 relative overflow-hidden">
                                        <div
                                            className="absolute inset-y-0 left-0 bg-gradient-to-r from-amber-500 to-amber-400 rounded-lg transition-all"
                                            style={{ width: `${width}%` }}
                                        ></div>
                                        <div className="absolute inset-0 flex items-center justify-end pr-3">
                                            <span className="text-xs font-bold text-white mix-blend-difference">
                                                ${(item.total_depreciation / 100).toFixed(0)}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Download, TrendingUp, TrendingDown, X, Calendar } from 'lucide-react';
import { Button } from '../../ui/button';
import { Card, CardContent } from '../../ui/card';
import { getFixedAssetsController } from '../../../controllers/FixedAssetsController';
import { SQLiteEngine } from '../../../core/database/SQLiteEngine';
import type { AssetDisposal } from '../../../services/accounting/AssetDisposalService';
import { useLocale } from '../../../i18n/useLocale';

interface DisposalSummaryReportProps {
    db: SQLiteEngine;
    onClose: () => void;
}

export const DisposalSummaryReport: React.FC<DisposalSummaryReportProps> = ({ db, onClose }) => {
    const { t } = useLocale();
    const [disposals, setDisposals] = useState<AssetDisposal[]>([]);
    const [loading, setLoading] = useState(true);
    const [year, setYear] = useState(new Date().getFullYear());

    useEffect(() => {
        loadDisposals();
    }, [year]);

    const loadDisposals = async () => {
        try {
            setLoading(true);
            const controller = getFixedAssetsController(db);

            // Get all disposals for the selected year
            const allDisposals = await controller.getAllDisposals();

            const yearDisposals = allDisposals.filter(d => {
                const disposalYear = new Date(d.disposal_date).getFullYear();
                return disposalYear === year;
            });

            setDisposals(yearDisposals);
        } catch (err) {
            console.error('Error loading disposal summary:', err);
        } finally {
            setLoading(false);
        }
    };

    const exportToCSV = () => {
        const headers = [
            t('assets.reports_ui.csv.assetId'),
            t('assets.reports_ui.csv.disposalDate'),
            t('assets.reports_ui.csv.method'),
            t('assets.reports_ui.csv.cost'),
            t('assets.reports_ui.csv.accDep'),
            t('assets.reports_ui.csv.nbv'),
            t('assets.reports_ui.csv.proceeds'),
            t('assets.reports_ui.csv.gainLoss')
        ];

        const rows = disposals.map(disposal => [
            disposal.asset_id,
            disposal.disposal_date,
            t(`assets.disposalForm.methods.${disposal.disposal_method.toLowerCase()}`),
            (disposal.original_cost / 100).toFixed(2),
            (disposal.accumulated_depreciation / 100).toFixed(2),
            (disposal.net_book_value / 100).toFixed(2),
            (disposal.disposal_proceeds / 100).toFixed(2),
            (disposal.gain_loss / 100).toFixed(2)
        ]);

        const csvContent = [
            headers.join(','),
            ...rows.map(row => row.join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `disposal-summary-${year}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    };

    // Calculate summary stats
    const summary = disposals.reduce(
        (acc, disposal) => {
            const gainLoss = disposal.gain_loss;
            return {
                totalProceeds: acc.totalProceeds + disposal.disposal_proceeds,
                totalOriginalCost: acc.totalOriginalCost + disposal.original_cost,
                totalGains: acc.totalGains + (gainLoss > 0 ? gainLoss : 0),
                totalLosses: acc.totalLosses + (gainLoss < 0 ? Math.abs(gainLoss) : 0),
                netGainLoss: acc.netGainLoss + gainLoss,
                byMethod: {
                    ...acc.byMethod,
                    [disposal.disposal_method]: (acc.byMethod[disposal.disposal_method] || 0) + 1
                }
            };
        },
        {
            totalProceeds: 0,
            totalOriginalCost: 0,
            totalGains: 0,
            totalLosses: 0,
            netGainLoss: 0,
            byMethod: {} as Record<string, number>
        }
    );

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500 mx-auto mb-4"></div>
                    <p className="text-slate-400">{t('assets.reports_ui.loadingDisposal')}</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-black text-white">{t('assets.reports.disposal')}</h2>
                    <p className="text-slate-500 text-sm mt-1">
                        {t('assets.reports_ui.subtitleDisposal', { year })}
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button
                        onClick={exportToCSV}
                        className="bg-emerald-600 hover:bg-emerald-700 text-white"
                        disabled={disposals.length === 0}
                    >
                        <Download className="w-4 h-4 mr-2" />
                        {t('assets.reports_ui.export')}
                    </Button>
                    <button
                        onClick={onClose}
                        className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-500 hover:text-white"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Year Selector */}
            <Card className="bg-slate-900 border-slate-800">
                <CardContent className="p-4">
                    <div className="flex items-center gap-4">
                        <Calendar className="w-5 h-5 text-slate-400" />
                        <label className="text-sm text-slate-400 font-bold">{t('common.year')}:</label>
                        <select
                            value={year}
                            onChange={(e) => setYear(parseInt(e.target.value))}
                            className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-white text-sm"
                        >
                            {Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i).map(y => (
                                <option key={y} value={y}>{y}</option>
                            ))}
                        </select>
                        <span className="text-sm text-slate-400">
                            {t('assets.reports_ui.disposalCount', { count: disposals.length })}
                        </span>
                    </div>
                </CardContent>
            </Card>

            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <Card className="bg-slate-900 border-slate-800">
                    <CardContent className="p-6">
                        <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">{t('assets.reports_ui.totalProceeds')}</p>
                        <p className="text-2xl font-black text-white font-mono">
                            ${(summary.totalProceeds / 100).toFixed(2)}
                        </p>
                    </CardContent>
                </Card>
                <Card className="bg-slate-900 border-slate-800 border-t-4 border-emerald-500">
                    <CardContent className="p-6">
                        <div className="flex items-center gap-2 mb-1">
                            <TrendingUp className="w-4 h-4 text-emerald-400" />
                            <p className="text-xs text-slate-400 uppercase tracking-wider">{t('assets.reports_ui.totalGains')}</p>
                        </div>
                        <p className="text-2xl font-black text-emerald-400 font-mono">
                            ${(summary.totalGains / 100).toFixed(2)}
                        </p>
                    </CardContent>
                </Card>
                <Card className="bg-slate-900 border-slate-800 border-t-4 border-rose-500">
                    <CardContent className="p-6">
                        <div className="flex items-center gap-2 mb-1">
                            <TrendingDown className="w-4 h-4 text-rose-400" />
                            <p className="text-xs text-slate-400 uppercase tracking-wider">{t('assets.reports_ui.totalLosses')}</p>
                        </div>
                        <p className="text-2xl font-black text-rose-400 font-mono">
                            ${(summary.totalLosses / 100).toFixed(2)}
                        </p>
                    </CardContent>
                </Card>
                <Card className={`bg-slate-900 border-slate-800 border-t-4 ${summary.netGainLoss >= 0 ? 'border-emerald-500' : 'border-rose-500'
                    }`}>
                    <CardContent className="p-6">
                        <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">{t('assets.reports_ui.netGainLoss')}</p>
                        <p className={`text-2xl font-black font-mono ${summary.netGainLoss >= 0 ? 'text-emerald-400' : 'text-rose-400'
                            }`}>
                            {summary.netGainLoss >= 0 ? '+' : ''}${(summary.netGainLoss / 100).toFixed(2)}
                        </p>
                    </CardContent>
                </Card>
            </div>

            {/* By Method Summary */}
            <Card className="bg-slate-900 border-slate-800">
                <CardContent className="p-6">
                    <h3 className="text-lg font-black text-white mb-4">{t('assets.reports_ui.byMethod')}</h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {Object.entries(summary.byMethod).map(([method, count]) => (
                            <div key={method} className="p-4 bg-slate-950 rounded-lg border border-slate-800">
                                <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">
                                    {t(`assets.disposalForm.methods.${method.toLowerCase()}`)}
                                </p>
                                <p className="text-2xl font-black text-white">{count}</p>
                            </div>
                        ))}
                    </div>
                </CardContent>
            </Card>

            {/* Disposals Table */}
            {disposals.length > 0 ? (
                <Card className="bg-slate-900 border-slate-800">
                    <CardContent className="p-0">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead>
                                    <tr className="border-b border-slate-800 bg-slate-950">
                                        <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('common.date')}</th>
                                        <th className="text-left py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.method')}</th>
                                        <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.cost')}</th>
                                        <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.accDep')}</th>
                                        <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.nbv')}</th>
                                        <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.proceeds')}</th>
                                        <th className="text-right py-3 px-4 text-xs font-black text-slate-400 uppercase">{t('assets.reports_ui.gainLoss')}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {disposals.map((disposal) => (
                                        <tr key={disposal.id} className="border-b border-slate-800 hover:bg-slate-800/30">
                                            <td className="py-3 px-4 text-sm text-white">{disposal.disposal_date}</td>
                                            <td className="py-3 px-4 text-sm text-slate-400">
                                                {t(`assets.disposalForm.methods.${disposal.disposal_method.toLowerCase()}`)}
                                            </td>
                                            <td className="py-3 px-4 text-sm text-right font-mono">
                                                ${(disposal.original_cost / 100).toFixed(2)}
                                            </td>
                                            <td className="py-3 px-4 text-sm text-right font-mono text-amber-400">
                                                ${(disposal.accumulated_depreciation / 100).toFixed(2)}
                                            </td>
                                            <td className="py-3 px-4 text-sm text-right font-mono">
                                                ${(disposal.net_book_value / 100).toFixed(2)}
                                            </td>
                                            <td className="py-3 px-4 text-sm text-right font-mono">
                                                ${(disposal.disposal_proceeds / 100).toFixed(2)}
                                            </td>
                                            <td className={`py-3 px-4 text-sm text-right font-mono font-bold ${disposal.gain_loss >= 0 ? 'text-emerald-400' : 'text-rose-400'
                                                }`}>
                                                {disposal.gain_loss >= 0 ? '+' : ''}${(disposal.gain_loss / 100).toFixed(2)}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot>
                                    <tr className="border-t-2 border-slate-700 bg-slate-950">
                                        <td colSpan={5} className="py-4 px-4 text-sm font-black text-white">
                                            {t('common.total')} ({t('assets.reports_ui.disposalCount', { count: disposals.length })})
                                        </td>
                                        <td className="py-4 px-4 text-sm text-right font-mono font-black text-white">
                                            ${(summary.totalProceeds / 100).toFixed(2)}
                                        </td>
                                        <td className={`py-4 px-4 text-sm text-right font-mono font-black ${summary.netGainLoss >= 0 ? 'text-emerald-400' : 'text-rose-400'
                                            }`}>
                                            {summary.netGainLoss >= 0 ? '+' : ''}${(summary.netGainLoss / 100).toFixed(2)}
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </CardContent>
                </Card>
            ) : (
                <Card className="bg-slate-900 border-slate-800">
                    <CardContent className="p-12 text-center">
                        <TrendingDown className="w-16 h-16 text-slate-700 mx-auto mb-4" />
                        <p className="text-slate-400 font-bold">{t('assets.reports_ui.noDisposals', { year })}</p>
                        <p className="text-xs text-slate-500 mt-2">{t('assets.reports_ui.noDisposalsHint')}</p>
                    </CardContent>
                </Card>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { AuditChainService } from '@/core/audit/AuditChainService';
import { getDBEngine } from '@/database/simple-db';
import { Shield, ShieldAlert, ShieldCheck, RefreshCw, Activity } from 'lucide-react';
import { useLocale } from '@/i18n/useLocale';

interface AuditStatus {
    status: 'secure' | 'compromised' | 'verifying' | 'unknown';
    lastHash: string;
    totalEvents: number;
    lastVerified: Date;
    errors: string[];
}

export const AuditTrailMonitor: React.FC = () => {
    const { t } = useLocale();
    const [status, setStatus] = useState<AuditStatus>({
        status: 'unknown',
        lastHash: '...',
        totalEvents: 0,
        lastVerified: new Date(),
        errors: []
    });

    const verifyChain = async () => {
        setStatus(prev => ({ ...prev, status: 'verifying' }));
        try {
            const report = await AuditChainService.performFullAudit();

            setStatus({
                status: report.valid ? 'secure' : 'compromised',
                lastHash: report.lastHash || '...',
                totalEvents: report.totalChecked || 0,
                lastVerified: new Date(),
                errors: report.valid ? [] : [report.details]
            });
        } catch (err) {
            setStatus(prev => ({
                ...prev,
                status: 'unknown',
                errors: [err instanceof Error ? err.message : 'Error verificando cadena']
            }));
        }
    };

    useEffect(() => {
        verifyChain();
    }, []);

    return (
        <Card className="bg-slate-900 border-white/5 text-white">
            <CardHeader className="pb-2 border-b border-white/5/50">
                <div className="flex items-center justify-between">
                    <CardTitle className="text-lg flex items-center gap-2">
                        <Activity className="w-5 h-5 text-blue-400" />
                        {t('auditTrail.title')}
                    </CardTitle>
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={verifyChain}
                        className={`h-8 w-8 p-0 ${status.status === 'verifying' ? 'animate-spin' : ''}`}
                    >
                        <RefreshCw className="w-4 h-4" />
                    </Button>
                </div>
            </CardHeader>
            <CardContent className="pt-4">
                <div className="flex items-center gap-4 mb-6">
                    <div className={`
                        w-16 h-16 rounded-full flex items-center justify-center border-4
                        ${status.status === 'secure' ? 'border-green-500/20 bg-green-500/10' : ''}
                        ${status.status === 'compromised' ? 'border-red-500/20 bg-red-500/10' : ''}
                        ${status.status === 'verifying' ? 'border-blue-500/20 bg-blue-500/10 animate-pulse' : ''}
                        ${status.status === 'unknown' ? 'border-white/10 bg-white/10' : ''}
                    `}>
                        {status.status === 'secure' && <ShieldCheck className="w-8 h-8 text-green-500" />}
                        {status.status === 'compromised' && <ShieldAlert className="w-8 h-8 text-red-500" />}
                        {(status.status === 'verifying' || status.status === 'unknown') && <Shield className="w-8 h-8 text-slate-500" />}
                    </div>
                    <div>
                        <h3 className="font-bold text-lg">
                            {status.status === 'secure' && t('auditTrail.status.secure')}
                            {status.status === 'compromised' && t('auditTrail.status.compromised')}
                            {status.status === 'verifying' && t('auditTrail.status.verifying')}
                            {status.status === 'unknown' && t('auditTrail.status.unknown')}
                        </h3>
                        {status.status === 'secure' && <p className="text-xs text-green-400">{t('auditTrail.verification.success')}</p>}
                        {status.status === 'compromised' && <p className="text-xs text-red-400">{t('auditTrail.verification.errors').replace('{count}', status.errors.length.toString())}</p>}
                        {status.status === 'verifying' && <p className="text-xs text-blue-400">{t('auditTrail.verification.calculating')}</p>}
                    </div>
                </div>

                <div className="space-y-2 text-xs font-mono text-slate-600 bg-black/30 p-3 rounded">
                    <div className="flex justify-between">
                        <span>{t('auditTrail.table.description')}:</span>
                        <span className="text-white">{status.totalEvents}</span>
                    </div>
                    <div className="flex justify-between">
                        <span>{t('auditTrail.details')}:</span>
                        <span className="text-white">{status.lastHash}</span>
                    </div>
                    <div className="flex justify-between">
                        <span>{t('auditTrail.table.timestamp')}:</span>
                        <span className="text-white">{status.lastVerified.toLocaleTimeString()}</span>
                    </div>
                </div>

                {status.status === 'compromised' && (
                    <div className="mt-4 bg-red-900/20 border border-red-900/50 p-2 rounded text-xs text-red-300">
                        <ul className="list-disc pl-4 space-y-1">
                            {status.errors.map((err, i) => <li key={i}>{err}</li>)}
                        </ul>
                    </div>
                )}
            </CardContent>
        </Card>
    );
};

import React, { useState, useEffect } from 'react';
