                                                    className="w-full text-left p-4 hover:bg-slate-800 border-b border-slate-800 last:border-0 text-xs text-slate-300"
                                                >
                                                    <span className="font-black text-white">{acc.account_code}</span> ΓÇö {acc.account_name}
