                        <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Criterio Determin├¡stico</div>
                    </div>
                </div>
            </div>

            {/* Rules List */}
            <div className="bg-slate-900/30 border border-slate-800/50 rounded-[2.5rem] overflow-hidden backdrop-blur-md">
                <table className="w-full border-collapse">
