const StatusBadge = ({ status }: { status: string }) => {
  const config: any = {
    completed: { label: 'CERTIFICADO', color: 'text-emerald-500', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20', icon: CheckCircle },
    rolled_back: { label: 'REVERTIDO', color: 'text-rose-500', bg: 'bg-rose-500/10', border: 'border-rose-500/20', icon: XCircle },
    pending: { label: 'SINCRO-PEND', color: 'text-amber-500', bg: 'bg-amber-500/10', border: 'border-amber-500/20', icon: Clock },
  };

  const { label, color, bg, border, icon: Icon } = config[status] || { label: status, color: 'text-slate-400', bg: 'bg-slate-500/10', border: 'border-slate-500/20', icon: Target };

  return (
    <span className={`inline-flex items-center gap-2.5 px-3 py-1.5 rounded-xl border text-[9px] font-black uppercase tracking-widest ${bg} ${color} ${border} shadow-lg shadow-black/20`}>
      <Icon className="w-3.5 h-3.5" />
      {label}
    </span>
  );
};

import React, { useState, useEffect } from 'react';
import {
    ShieldAlert, Clock, ArrowRight, CheckCircle2, AlertCircle,
    Search, Filter, ChevronRight, Calculator, MoreHorizontal, Activity
} from 'lucide-react';
import { db, getChartOfAccounts, ChartOfAccount } from '@/database/simple-db';
import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import toast from 'react-hot-toast';
import { useLocale } from '../../i18n/useLocale';
import { useAuth } from '../../contexts/AuthContext';
import { ClassificationMemoryService, MemorySuggestion } from '../../services/banking/ClassificationMemoryService';
import { TRANSACTION_STATES } from '../../constants/bankingStates';

interface QuarantinedTransaction {
    id: number;
    transaction_id: number;
    date: string;
    description: string;
    amount: number;
    current_state: string;
    risk_score: number;
    suggested_category: string;
    quarantine_started_at: string;
    sla_deadline: string;
    merchant_pattern?: string;
}

export const QuarantinePanel: React.FC = () => {
    const { t } = useLocale();
    const { user } = useAuth();
    const [transactions, setTransactions] = useState<QuarantinedTransaction[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedTx, setSelectedTx] = useState<QuarantinedTransaction | null>(null);
    const [chartOfAccounts, setChartOfAccounts] = useState<ChartOfAccount[]>([]);

    // Modal states
    const [memorySuggestions, setMemorySuggestions] = useState<MemorySuggestion[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredAccounts, setFilteredAccounts] = useState<ChartOfAccount[]>([]);
    const [selectedAccount, setSelectedAccount] = useState<ChartOfAccount | null>(null);
    const [notes, setNotes] = useState('');

    useEffect(() => {
        loadQuarantineData();
        setChartOfAccounts(getChartOfAccounts());
    }, []);

    useEffect(() => {
        if (selectedTx) {
            loadSuggestions(selectedTx.description);
            setSearchQuery('');
            setSelectedAccount(null);
            setNotes('');
        }
    }, [selectedTx]);

    const loadSuggestions = async (description: string) => {
        const memory = await ClassificationMemoryService.getSuggestions(description);
        setMemorySuggestions(memory);
    };

    const handleSearchChange = (query: string) => {
        setSearchQuery(query);
        if (query.length > 1) {
            const filtered = chartOfAccounts.filter(a =>
                a.account_name.toLowerCase().includes(query.toLowerCase()) ||
                a.account_code.includes(query)
            ).slice(0, 5);
            setFilteredAccounts(filtered);
        } else {
            setFilteredAccounts([]);
        }
    };

    const loadQuarantineData = async () => {
        setLoading(true);
        try {
            const engine = new SQLiteEngine();
            engine.setDB(db);

            const rows = await engine.select(`
        SELECT 
          ts.id,
          ts.transaction_id,
          bt.transaction_date as date,
          bt.description,
          bt.amount,
          ts.current_state,
          ts.risk_score,
          rk.suggested_category,
          rk.merchant_name as merchant_pattern,
          ts.quarantine_started_at,
          ts.sla_deadline
        FROM transaction_states ts
        JOIN bank_transactions bt ON ts.transaction_id = bt.id
        LEFT JOIN risk_keywords rk ON ts.risk_keyword_id = rk.id
        WHERE ts.current_state IN ('${TRANSACTION_STATES.HIGH_RISK_PERSONAL}', '${TRANSACTION_STATES.PENDING_SUPERVISOR}')
          AND ts.is_verified = 0
        ORDER BY ts.sla_deadline ASC
      `);

            setTransactions(rows as any);
        } catch (error) {
            console.error('Error loading quarantine data:', error);
            toast.error('Error al cargar zona de cuarentena');
        } finally {
            setLoading(false);
        }
    };

    const calculateSLAPercentage = (start: string, deadline: string) => {
        const startTime = new Date(start).getTime();
        const endTime = new Date(deadline).getTime();
        const now = new Date().getTime();

        if (!start || !deadline) return 0;

        const total = endTime - startTime;
        const elapsed = now - startTime;

        const percentage = Math.min(100, Math.max(0, (elapsed / total) * 100));
        return percentage;
    };

    const getSLABarColor = (percentage: number) => {
        if (percentage < 50) return 'bg-emerald-500';
        if (percentage < 80) return 'bg-amber-500';
        return 'bg-red-500';
    };

    const extractReference = (description: string) => {
        const match = description.match(/CONF#\s*(\S+)/i);
        return match ? match[1] : 'ΓÇö';
    };

    const handleReclassify = async () => {
        if (!selectedTx || !selectedAccount || !user) return;

        const loadingToast = toast.loading('Procesando reclasificaci├│n...');
        try {
            const engine = new SQLiteEngine();
            engine.setDB(db);

            // 1. Guardar en memoria de aprendizaje
            await ClassificationMemoryService.saveConfirmation(
                selectedTx.description,
                selectedAccount.account_code,
                selectedAccount.account_name,
                user.id
            );

            // 2. Marcar como verificado y cambiar estado
            await engine.run(`
                UPDATE transaction_states 
                SET current_state = ?, 
                    is_verified = 1,
                    verified_at = CURRENT_TIMESTAMP,
                    verified_by = ?
                WHERE id = ?
            `, [TRANSACTION_STATES.VERIFIED, user.id, selectedTx.id]);

            // 3. Registrar en log de auditor├¡a
            await engine.run(`
                INSERT INTO quarantine_audit_log (
                    transaction_id, state_id, action_type, performed_by, 
                    previous_state, new_state, new_category, justification
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            `, [
                selectedTx.transaction_id,
                selectedTx.id,
                TRANSACTION_STATES.RECLASSIFIED,
                user.id,
                selectedTx.current_state,
                TRANSACTION_STATES.VERIFIED,
                selectedAccount.account_code,
                notes || 'Manual reclassification'
            ]);

            toast.success('Transacci├│n reclasificada con ├⌐xito', { id: loadingToast });
            setSelectedTx(null);
            loadQuarantineData();

            // Actualizar badge del sidebar
            window.dispatchEvent(new CustomEvent('quarantine-updated'));

        } catch (error) {
            console.error('Error in reclassification:', error);
            toast.error('Error al reclasificar', { id: loadingToast });
        }
    };

    const getSuggestedAccounts = (category: string) => {
        if (category === 'PERSONAL_EXPENSE' || category === 'OWNERS_DRAW') {
            return chartOfAccounts.filter(a => a.account_code.startsWith('3') || a.account_name.toLowerCase().includes('draw') || a.account_name.toLowerCase().includes('personal'));
        }
        if (category === 'TRANSPORT_INCOME') {
            return chartOfAccounts.filter(a => a.account_code.startsWith('4') && (a.account_name.toLowerCase().includes('uber') || a.account_name.toLowerCase().includes('servicios')));
        }
        return chartOfAccounts.slice(0, 5);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-900/50 p-6 rounded-3xl border border-slate-800 backdrop-blur-md">
                <div className="flex items-center gap-4">
                    <div className="p-4 bg-red-500/10 rounded-2xl border border-red-500/20">
                        <ShieldAlert className="w-8 h-8 text-red-500" />
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-white tracking-tighter uppercase">Zona de Cuarentena</h1>
                        <p className="text-slate-400 text-sm font-medium flex items-center gap-2">
                            <Clock className="w-4 h-4 text-amber-500" />
                            Auditor├¡a Forense: {transactions.length} transacciones bajo revisi├│n de 72h SLA
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <div className="px-4 py-2 bg-slate-800 rounded-xl border border-slate-700 flex items-center gap-2">
                        <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                        <span className="text-xs font-bold text-slate-300 uppercase tracking-widest">Motor v2.0 Activo</span>
                    </div>
                </div>
            </div>

            {loading ? (
                <div className="flex items-center justify-center p-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
                </div>
            ) : transactions.length === 0 ? (
                <div className="bg-slate-900/30 border-2 border-dashed border-slate-800 rounded-3xl p-20 text-center">
                    <CheckCircle2 className="w-16 h-16 text-emerald-500/30 mx-auto mb-4" />
                    <h3 className="text-xl font-bold text-slate-400">Todo en orden</h3>
                    <p className="text-slate-500">No hay transacciones interceptadas en las ├║ltimas 72 horas.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
                    <div className="xl:col-span-2 space-y-4">
                        {transactions.map(tx => {
                            const slaPercent = calculateSLAPercentage(tx.quarantine_started_at, tx.sla_deadline);
                            const isSelected = selectedTx?.id === tx.id;

                            return (
                                <div
                                    key={tx.id}
                                    onClick={() => setSelectedTx(tx)}
                                    className={`
                    group relative overflow-hidden bg-slate-900 rounded-2xl border transition-all duration-300 cursor-pointer
                    ${isSelected ? 'border-blue-500 shadow-lg shadow-blue-500/10 ring-1 ring-blue-500/50' : 'border-slate-800 hover:border-slate-700 hover:bg-slate-900/80'}
                  `}
                                >
                                    <div className="p-5 flex flex-col md:flex-row gap-6 items-center">
                                        <div className="flex-shrink-0 text-center md:text-left md:w-32">
                                            <div className="text-xs font-black text-slate-500 uppercase tracking-widest mb-1">{tx.date}</div>
                                            <div className={`text-xl font-black ${tx.amount < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                                                ${Math.abs(tx.amount).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                                            </div>
                                        </div>

                                        <div className="flex-1 min-w-0">
                                            <div className="text-sm font-bold text-white truncate group-hover:text-blue-400 transition-colors uppercase">
                                                {tx.description}
                                            </div>
                                            <div className="flex items-center gap-3 mt-1.5">
                                                <span className="px-2 py-0.5 bg-slate-800 text-slate-400 rounded-md text-[10px] font-black uppercase tracking-tighter flex items-center gap-1">
                                                    <Search className="w-2.5 h-2.5" />
                                                    Pattern: {tx.merchant_pattern || 'No Match'}
                                                </span>
                                                <span className="px-2 py-0.5 bg-blue-500/10 text-blue-400 rounded-md text-[10px] font-black uppercase tracking-tighter flex items-center gap-1 italic">
                                                    Ref: {extractReference(tx.description)}
                                                </span>
                                            </div>
                                        </div>

                                        <div className="w-full md:w-48 space-y-2">
                                            <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-500">
                                                <span>SLA Time</span>
                                                <span>{slaPercent.toFixed(0)}%</span>
                                            </div>
                                            <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                                                <div
                                                    className={`h-full transition-all duration-1000 ${getSLABarColor(slaPercent)}`}
                                                    style={{ width: `${slaPercent}%` }}
                                                ></div>
                                            </div>
                                        </div>

                                        <div className="flex flex-col items-center gap-2">
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    setSelectedTx(tx);
                                                }}
                                                className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg
                                                    ${isSelected ? 'bg-blue-600 text-white' : 'bg-amber-500/10 border border-amber-500/20 text-amber-500 group-hover:bg-amber-500 group-hover:text-black'}
                                                `}
                                            >
                                                Clasificar
                                            </button>
                                            <ChevronRight className={`w-4 h-4 transition-all ${isSelected ? 'text-blue-500 translate-x-1' : 'text-slate-700'}`} />
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    <div className="xl:col-span-1">
                        <div className="sticky top-6 bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
                            {!selectedTx ? (
                                <div className="p-10 text-center space-y-4">
                                    <div className="w-16 h-16 bg-slate-800/50 rounded-2xl flex items-center justify-center mx-auto border border-slate-700">
                                        <AlertCircle className="w-8 h-8 text-slate-600" />
                                    </div>
                                    <div className="text-sm font-bold text-slate-500 uppercase tracking-widest">
                                        Selecciona una transacci├│n para auditar
                                    </div>
                                </div>
                            ) : (
                                <div className="animate-in slide-in-from-right-4 duration-300">
                                    <div className="p-6 border-b border-slate-800 bg-gradient-to-br from-blue-600/5 to-transparent">
                                        <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-2">
                                            <Calculator className="w-5 h-5 text-blue-500" />
                                            Resoluci├│n de Auditor├¡a
                                        </h3>
                                    </div>

                                    <div className="p-6 space-y-6">
                                        {/* Secci├│n 1 ΓÇö Descriptor bancario */}
                                        <div className="p-4 bg-slate-800/30 rounded-2xl border border-slate-800">
                                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Descriptor Original</div>
                                            <div className="text-xs font-mono text-slate-300 break-words leading-relaxed">
                                                {selectedTx.description}
                                            </div>
                                        </div>

                                        {/* Secci├│n 2 ΓÇö Sugerencias */}
                                        <div className="space-y-3">
                                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Sugerencias Disponibles</div>
                                            <div className="space-y-2">
                                                {/* Coincidencias de Memoria */}
                                                {memorySuggestions.map((s, idx) => (
                                                    <button
                                                        key={`mem-${idx}`}
                                                        onClick={() => {
                                                            setSelectedAccount(chartOfAccounts.find(a => a.account_code === s.accountCode) || null);
                                                            setSearchQuery(s.accountName);
                                                        }}
                                                        className="w-full flex items-center justify-between p-3 bg-emerald-500/10 hover:bg-emerald-600/20 rounded-xl border border-emerald-500/20 text-emerald-400 transition-all text-xs"
                                                    >
                                                        <div className="text-left">
                                                            <div className="font-black">{s.accountName} ({s.accountCode})</div>
                                                            <div className="text-[8px] uppercase opacity-70">Usado antes ({s.useCount} veces)</div>
                                                        </div>
                                                        <CheckCircle2 size={14} />
                                                    </button>
                                                ))}

                                                {/* Sugerencias de Motor IA */}
                                                {getSuggestedAccounts(selectedTx.suggested_category).map((a, idx) => (
                                                    <button
                                                        key={`ia-${idx}`}
                                                        onClick={() => {
                                                            setSelectedAccount(a);
                                                            setSearchQuery(a.account_name);
                                                        }}
                                                        className="w-full flex items-center justify-between p-3 bg-blue-500/10 hover:bg-blue-600/20 rounded-xl border border-blue-500/20 text-blue-400 transition-all text-xs"
                                                    >
                                                        <div className="text-left">
                                                            <div className="font-black">{a.account_name} ({a.account_code})</div>
                                                            <div className="text-[8px] uppercase opacity-70">Sugerido por IA</div>
                                                        </div>
                                                        <Activity size={12} className="animate-pulse" />
                                                    </button>
                                                ))}
                                            </div>
                                        </div>

                                        {/* Secci├│n 3 ΓÇö Buscador Libre */}
                                        <div className="space-y-3">
                                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Codificaci├│n Contable</div>
                                            <div className="relative">
                                                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                                                    <Search size={14} className="text-slate-500" />
                                                </div>
                                                <input
                                                    type="text"
                                                    value={searchQuery}
                                                    onChange={(e) => handleSearchChange(e.target.value)}
                                                    placeholder="Buscar cuenta o c├│digo..."
                                                    className="w-full bg-slate-950 text-white pl-10 pr-4 py-4 rounded-xl border border-slate-800 text-xs font-bold focus:outline-none focus:border-blue-500 transition-all"
                                                />
                                                {filteredAccounts.length > 0 && (
                                                    <div className="absolute z-20 w-full mt-2 bg-slate-900 border border-slate-800 rounded-xl shadow-2xl overflow-hidden">
                                                        {filteredAccounts.map(account => (
                                                            <button
                                                                key={account.id}
                                                                onClick={() => {
                                                                    setSelectedAccount(account);
                                                                    setSearchQuery(account.account_name);
                                                                    setFilteredAccounts([]);
                                                                }}
                                                                className="w-full text-left p-3 hover:bg-slate-800 text-xs text-slate-300 hover:text-white border-b border-slate-800 last:border-0"
                                                            >
                                                                <span className="font-black">{account.account_code}</span> ΓÇö {account.account_name}
                                                            </button>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                            {selectedAccount && (
                                                <div className="flex items-center gap-2 px-3 py-2 bg-blue-600/20 rounded-lg border border-blue-500/30">
                                                    <CheckCircle2 size={12} className="text-blue-400" />
                                                    <span className="text-[10px] font-black text-blue-400 uppercase">Seleccionado: {selectedAccount.account_code}</span>
                                                </div>
                                            )}
                                        </div>

                                        {/* Secci├│n 4 ΓÇö Nota */}
                                        <div className="space-y-2">
                                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Justificaci├│n (Opcional)</div>
                                            <textarea
                                                value={notes}
                                                onChange={(e) => setNotes(e.target.value)}
                                                rows={2}
                                                className="w-full bg-slate-950 text-slate-300 p-4 rounded-xl border border-slate-800 text-xs font-medium focus:outline-none focus:border-blue-500 transition-all resize-none"
                                                placeholder="Agregar nota sobre esta reclasificaci├│n..."
                                            />
                                        </div>

                                        <div className="pt-4">
                                            <button
                                                disabled={!selectedAccount}
                                                onClick={handleReclassify}
                                                className={`
                                                    w-full py-5 rounded-2xl font-black uppercase tracking-widest text-[10px] transition-all
                                                    ${selectedAccount
                                                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/40 hover:-translate-y-1'
                                                        : 'bg-slate-800 text-slate-600 cursor-not-allowed'}
                                                `}
                                            >
                                                Certificar y Clasificar
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Check, X, AlertCircle, CheckCircle, Download, RefreshCw } from 'lucide-react';
import {
  BankTransaction,
  AccountingTransaction,
  Match,
  ReconciliationResult,
  bankReconciliationService
} from '../../services/banking/BankReconciliationService';

interface ReconciliationMatcherProps {
  bankTransactions: BankTransaction[];
  accountingTransactions: AccountingTransaction[];
  onComplete: (result: ReconciliationResult) => void;
}

export const ReconciliationMatcher: React.FC<ReconciliationMatcherProps> = ({
  bankTransactions,
  accountingTransactions,
  onComplete
}) => {
  const [result, setResult] = useState<ReconciliationResult | null>(null);
  const [selectedBankTx, setSelectedBankTx] = useState<number | null>(null);
  const [selectedAccountingTx, setSelectedAccountingTx] = useState<number | null>(null);
  const [manualMatches, setManualMatches] = useState<Match[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // Ejecutar reconciliaci├│n autom├ítica al montar
  useEffect(() => {
    handleAutoReconcile();
  }, [bankTransactions, accountingTransactions]);

  const handleAutoReconcile = () => {
    setIsProcessing(true);
    try {
      const reconciliationResult = bankReconciliationService.reconcile(
        bankTransactions,
        accountingTransactions
      );
      setResult(reconciliationResult);
    } catch (error) {
      console.error('Error en reconciliaci├│n autom├ítica:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleManualMatch = () => {
    if (!selectedBankTx || !selectedAccountingTx || !result) return;

    const newMatch = bankReconciliationService.createManualMatch(
      selectedBankTx,
      selectedAccountingTx,
      'Match manual creado por usuario'
    );

    // Agregar match manual
    const updatedMatches = [...result.matches, newMatch];
    
    // Remover de no coincididos
    const updatedUnmatchedBank = result.unmatchedBankTxs.filter(tx => tx.id !== selectedBankTx);
    const updatedUnmatchedAccounting = result.unmatchedAccountingTxs.filter(
      tx => tx.id !== selectedAccountingTx
    );

    // Actualizar resultado
    const updatedResult: ReconciliationResult = {
      ...result,
      matches: updatedMatches,
      unmatchedBankTxs: updatedUnmatchedBank,
      unmatchedAccountingTxs: updatedUnmatchedAccounting,
      summary: {
        ...result.summary,
        matchedCount: updatedMatches.length,
        unmatchedCount: updatedUnmatchedBank.length + updatedUnmatchedAccounting.length,
        matchRate: bankTransactions.length > 0 
          ? (updatedMatches.length / bankTransactions.length) * 100 
          : 0
      }
    };

    setResult(updatedResult);
    setManualMatches([...manualMatches, newMatch]);
    setSelectedBankTx(null);
    setSelectedAccountingTx(null);
  };

  const handleRemoveMatch = (matchIndex: number) => {
    if (!result) return;

    const removedMatch = result.matches[matchIndex];
    const updatedMatches = result.matches.filter((_, i) => i !== matchIndex);

    // Restaurar a no coincididos
    const bankTx = bankTransactions.find(tx => tx.id === removedMatch.bankTxId);
    const accountingTx = accountingTransactions.find(tx => tx.id === removedMatch.accountingTxId);

    const updatedUnmatchedBank = bankTx 
      ? [...result.unmatchedBankTxs, bankTx]
      : result.unmatchedBankTxs;
    
    const updatedUnmatchedAccounting = accountingTx
      ? [...result.unmatchedAccountingTxs, accountingTx]
      : result.unmatchedAccountingTxs;

    const updatedResult: ReconciliationResult = {
      ...result,
      matches: updatedMatches,
      unmatchedBankTxs: updatedUnmatchedBank,
      unmatchedAccountingTxs: updatedUnmatchedAccounting,
      summary: {
        ...result.summary,
        matchedCount: updatedMatches.length,
        unmatchedCount: updatedUnmatchedBank.length + updatedUnmatchedAccounting.length,
        matchRate: bankTransactions.length > 0 
          ? (updatedMatches.length / bankTransactions.length) * 100 
          : 0
      }
    };

    setResult(updatedResult);
  };

  const handleDownloadReport = () => {
    if (!result) return;

    const report = bankReconciliationService.generateReport(
      result,
      `${new Date().toLocaleDateString('es-ES')}`
    );

    const blob = new Blob([report], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `conciliacion-bancaria-${new Date().toISOString().split('T')[0]}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleComplete = () => {
    if (result) {
      onComplete(result);
    }
  };

  if (isProcessing) {
    return (
      <div className="flex items-center justify-center p-8">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-600" />
        <span className="ml-3 text-lg">Procesando reconciliaci├│n...</span>
      </div>
    );
  }

  if (!result) {
    return (
      <div className="flex items-center justify-center p-8">
        <AlertCircle className="w-8 h-8 text-yellow-600" />
        <span className="ml-3 text-lg">No hay datos para reconciliar</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Resumen */}
      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-xl font-semibold mb-4">Resumen de Reconciliaci├│n</h2>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <div className="text-center">
            <div className="text-2xl font-black tracking-tight text-blue-600">
              {result.summary.totalBankTransactions}
            </div>
            <div className="text-sm text-slate-700">Transacciones Bancarias</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-black tracking-tight text-purple-600">
              {result.summary.totalAccountingTransactions}
            </div>
            <div className="text-sm text-slate-700">Registros Contables</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-black tracking-tight text-green-600">
              {result.summary.matchedCount}
            </div>
            <div className="text-sm text-slate-700">Coincidencias</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-black tracking-tight text-orange-600">
              {result.summary.unmatchedCount}
            </div>
            <div className="text-sm text-slate-700">Sin Coincidencia</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-black tracking-tight text-red-600">
              {result.summary.discrepancyCount}
            </div>
            <div className="text-sm text-slate-700">Discrepancias</div>
          </div>
        </div>
        <div className="mt-4 text-center">
          <div className="text-3xl font-bold text-green-600">
            {result.summary.matchRate.toFixed(1)}%
          </div>
          <div className="text-sm text-slate-700">Tasa de Coincidencia</div>
        </div>
      </div>

      {/* Coincidencias */}
      <div className="bg-white rounded-lg shadow p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold flex items-center">
            <CheckCircle className="w-5 h-5 text-green-600 mr-2" />
            Coincidencias ({result.matches.length})
          </h3>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-600 uppercase">
                  Tipo
                </th>
                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-600 uppercase">
                  Confianza
                </th>
                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-600 uppercase">
                  Raz├│n
                </th>
                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-600 uppercase">
                  Banco ID
                </th>
                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-600 uppercase">
                  Contable ID
                </th>
                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-[0.2em] text-slate-600 uppercase">
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {result.matches.map((match, index) => (
                <tr key={index} className="hover:bg-gray-50">
                  <td className="px-4 py-3 whitespace-nowrap">
                    <span
                      className={`px-2 py-1 text-xs font-semibold rounded ${
                        match.matchType === 'exact'
                          ? 'bg-green-100 text-green-800'
                          : match.matchType === 'fuzzy'
                          ? 'bg-yellow-100 text-yellow-800'
                          : 'bg-blue-100 text-blue-800'
                      }`}
                    >
                      {match.matchType.toUpperCase()}
                    </span>
                  </td>
                  <td className="px-4 py-3 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                        <div
                          className={`h-2 rounded-full ${
                            match.confidence >= 90
                              ? 'bg-green-600'
                              : match.confidence >= 70
                              ? 'bg-yellow-600'
                              : 'bg-orange-600'
                          }`}
                          style={{ width: `${match.confidence}%` }}
                        />
                      </div>
                      <span className="text-sm">{match.confidence}%</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-900">{match.reason}</td>
                  <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">
                    #{match.bankTxId}
                  </td>
                  <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">
                    #{match.accountingTxId}
                  </td>
                  <td className="px-4 py-3 whitespace-nowrap text-sm">
                    <button
                      onClick={() => handleRemoveMatch(index)}
                      className="text-red-600 hover:text-red-800"
                      title="Eliminar coincidencia"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Matching Manual */}
      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="text-lg font-semibold mb-4">Matching Manual</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Transacciones Bancarias Sin Coincidencia */}
          <div>
            <h4 className="font-medium mb-2 text-blue-600">
              Transacciones Bancarias ({result.unmatchedBankTxs.length})
            </h4>
            <div className="border rounded-lg max-h-64 overflow-y-auto">
              {result.unmatchedBankTxs.map(tx => (
                <div
                  key={tx.id}
                  onClick={() => setSelectedBankTx(tx.id)}
                  className={`p-3 border-b cursor-pointer hover:bg-blue-50 ${
                    selectedBankTx === tx.id ? 'bg-blue-100 border-blue-500' : ''
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="font-medium text-sm">{tx.description}</div>
                      <div className="text-xs text-slate-600">{tx.date}</div>
                      {tx.reference && (
                        <div className="text-xs text-slate-600">Ref: {tx.reference}</div>
                      )}
                    </div>
                    <div
                      className={`font-semibold ${
                        tx.type === 'credit' ? 'text-green-600' : 'text-red-600'
                      }`}
                    >
                      {tx.type === 'credit' ? '+' : '-'}${tx.amount.toFixed(2)}
                    </div>
                  </div>
                </div>
              ))}
              {result.unmatchedBankTxs.length === 0 && (
                <div className="p-4 text-center text-slate-600 text-sm">
                  No hay transacciones bancarias sin coincidencia
                </div>
              )}
            </div>
          </div>

          {/* Transacciones Contables Sin Coincidencia */}
          <div>
            <h4 className="font-medium mb-2 text-purple-600">
              Registros Contables ({result.unmatchedAccountingTxs.length})
            </h4>
            <div className="border rounded-lg max-h-64 overflow-y-auto">
              {result.unmatchedAccountingTxs.map(tx => (
                <div
                  key={tx.id}
                  onClick={() => setSelectedAccountingTx(tx.id)}
                  className={`p-3 border-b cursor-pointer hover:bg-purple-50 ${
                    selectedAccountingTx === tx.id ? 'bg-purple-100 border-purple-500' : ''
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="font-medium text-sm">{tx.description}</div>
                      <div className="text-xs text-slate-600">{tx.entry_date}</div>
                      <div className="text-xs text-slate-600">Cuenta: {tx.account_code}</div>
                      {tx.reference && (
                        <div className="text-xs text-slate-600">Ref: {tx.reference}</div>
                      )}
                    </div>
                    <div
                      className={`font-semibold ${
                        tx.type === 'credit' ? 'text-green-600' : 'text-red-600'
                      }`}
                    >
                      {tx.type === 'credit' ? '+' : '-'}${tx.amount.toFixed(2)}
                    </div>
                  </div>
                </div>
              ))}
              {result.unmatchedAccountingTxs.length === 0 && (
                <div className="p-4 text-center text-slate-600 text-sm">
                  No hay registros contables sin coincidencia
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Bot├│n de Match Manual */}
        <div className="mt-4 text-center">
          <button
            onClick={handleManualMatch}
            disabled={!selectedBankTx || !selectedAccountingTx}
            className={`px-6 py-2 rounded-lg font-medium ${
              selectedBankTx && selectedAccountingTx
                ? 'bg-blue-600 text-white hover:bg-blue-700'
                : 'bg-gray-300 text-slate-600 cursor-not-allowed'
            }`}
          >
            <Check className="w-4 h-4 inline mr-2" />
            Crear Match Manual
          </button>
          {selectedBankTx && selectedAccountingTx && (
            <div className="mt-2 text-sm text-slate-700">
              Coincidiendo transacci├│n bancaria #{selectedBankTx} con registro contable #
              {selectedAccountingTx}
            </div>
          )}
        </div>
      </div>

      {/* Discrepancias */}
      {result.discrepancies.length > 0 && (
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold mb-4 flex items-center">
            <AlertCircle className="w-5 h-5 text-red-600 mr-2" />
            Discrepancias ({result.discrepancies.length})
          </h3>
          <div className="space-y-3">
            {result.discrepancies.map((disc, index) => (
              <div
                key={index}
                className="border-l-4 border-red-500 bg-red-50 p-4 rounded"
              >
                <div className="flex items-start">
                  <AlertCircle className="w-5 h-5 text-red-600 mr-3 mt-0.5" />
                  <div className="flex-1">
                    <div className="font-medium text-red-900">
                      {disc.type.replace(/_/g, ' ').toUpperCase()}
                    </div>
                    <div className="text-sm text-red-800 mt-1">{disc.description}</div>
                    {disc.difference && (
                      <div className="text-sm text-red-700 mt-1">
                        Diferencia: ${Math.abs(disc.difference).toFixed(2)}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Acciones */}
      <div className="flex justify-between items-center">
        <button
          onClick={handleAutoReconcile}
          className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 flex items-center"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Volver a Reconciliar
        </button>
        <div className="space-x-3">
          <button
            onClick={handleDownloadReport}
            className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 flex items-center inline-flex"
          >
            <Download className="w-4 h-4 mr-2" />
            Descargar Reporte
          </button>
          <button
            onClick={handleComplete}
            className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 inline-flex items-center"
          >
            <CheckCircle className="w-4 h-4 mr-2" />
            Completar Reconciliaci├│n
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Search, CheckCircle2, ListChecks, Activity } from 'lucide-react';
import { getDBEngine, getChartOfAccounts, ChartOfAccount } from '@/database/simple-db';
import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { TRANSACTION_STATES } from '../../constants/bankingStates';
import { ClassificationMemoryService, MemorySuggestion } from '../../services/banking/ClassificationMemoryService';
import { useAuth } from '../../contexts/AuthContext';
import toast from 'react-hot-toast';
import { DatabaseService } from '../../database/DatabaseService';

interface ImportedTransaction {
    id: number;
    transaction_id: number;
    date: string;
    description: string;
    amount: number;
    state_id: number;
}

interface TransactionClassifierProps {
    accountId: number;
}

export const TransactionClassifier: React.FC<TransactionClassifierProps> = ({ accountId }) => {
    const { user } = useAuth();
    const [transactions, setTransactions] = useState<ImportedTransaction[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedTx, setSelectedTx] = useState<ImportedTransaction | null>(null);
    const [chartOfAccounts, setChartOfAccounts] = useState<ChartOfAccount[]>([]);
    const [memorySuggestions, setMemorySuggestions] = useState<MemorySuggestion[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredAccounts, setFilteredAccounts] = useState<ChartOfAccount[]>([]);
    const [selectedAccount, setSelectedAccount] = useState<ChartOfAccount | null>(null);
    const [notes, setNotes] = useState('');
    const [selectedTxIds, setSelectedTxIds] = useState<Set<number>>(new Set());
    const [isAutoSuggested, setIsAutoSuggested] = useState(false);

    useEffect(() => {
        loadTransactions();
        setChartOfAccounts(getChartOfAccounts());
    }, [accountId]);

    useEffect(() => {
        if (selectedTx) {
            loadSuggestions(selectedTx.description);
            setSearchQuery('');
            setSelectedAccount(null);
            setNotes('');
            setIsAutoSuggested(false);
        }
    }, [selectedTx]);

    const loadTransactions = async () => {
        setLoading(true);
        try {
            const engine = getDBEngine();
            const rows = await engine.select(`
                SELECT 
                    ts.id as state_id,
                    bt.id as transaction_id,
                    bt.transaction_date as date,
                    bt.description,
                    bt.amount
                FROM bank_transactions bt
                JOIN transaction_states ts ON ts.transaction_id = bt.id
                WHERE bt.bank_account_id = ?
                  AND ts.current_state = ?
                  AND ts.is_verified = 0
                ORDER BY bt.transaction_date DESC
            `, [accountId, TRANSACTION_STATES.IMPORTED]);
            setTransactions(rows as any);
        } catch (error) {
            console.error('Error loading transactions:', error);
            toast.error('Error al cargar transacciones');
        } finally {
            setLoading(false);
        }
    };

    const loadSuggestions = async (description: string) => {
        const memory = await ClassificationMemoryService.getSuggestions(description);
        setMemorySuggestions(memory);

        // Auto-select the first suggestion if available
        if (memory.length > 0 && !selectedAccount) {
            const bestSuggestion = memory[0];
            const account = chartOfAccounts.find(a => a.account_code === bestSuggestion.accountCode);
            if (account) {
                setSelectedAccount(account);
                setSearchQuery(account.account_name);
                setIsAutoSuggested(true);
            }
        }
    };

    const handleSearchChange = (query: string) => {
        setSearchQuery(query);
        setIsAutoSuggested(false); // Manually typing clears auto-suggest flag
        if (query.length > 1) {
            const filtered = chartOfAccounts.filter(a =>
                a.account_name.toLowerCase().includes(query.toLowerCase()) ||
                a.account_code.includes(query)
            ).slice(0, 5);
            setFilteredAccounts(filtered);
        } else {
            setFilteredAccounts([]);
        }
    };

    const toggleTxSelection = (id: number) => {
        const next = new Set(selectedTxIds);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        setSelectedTxIds(next);
    };

    const selectAllVisible = () => {
        if (selectedTxIds.size === transactions.length) {
            setSelectedTxIds(new Set());
        } else {
            setSelectedTxIds(new Set(transactions.map(t => t.state_id)));
        }
    };

    const handleClassify = async () => {
        const targetIds = selectedTxIds.size > 0
            ? Array.from(selectedTxIds)
            : (selectedTx ? [selectedTx.state_id] : []);

        if (targetIds.length === 0 || !selectedAccount || !user) return;

        const loadingToast = toast.loading(targetIds.length > 1
            ? `Clasificando y generando asientos para ${targetIds.length} transacciones...`
            : 'Certificando clasificaci├│n y generando asiento...');

        try {
            const engine = getDBEngine();
            const getGlCodeForBank = (bankId: number) => {
                const map: Record<number, string> = { 1: '1112', 2: '1113' };
                return map[bankId] || '1112';
            };

            const bankAccountCode = getGlCodeForBank(accountId);
            let successCount = 0;

            for (const stateId of targetIds) {
                // 1. Obtener detalles de la transacci├│n para el asiento
                const txRes = await engine.select(`
                    SELECT bt.* FROM bank_transactions bt 
                    JOIN transaction_states ts ON ts.transaction_id = bt.id
                    WHERE ts.id = ?
                `, [stateId]);

                if (txRes.length === 0) continue;
                const tx = txRes[0] as any;

                // 2. Guardar en memoria (solo para la principal si es single)
                if (targetIds.length === 1) {
                    await ClassificationMemoryService.saveConfirmation(
                        tx.description,
                        selectedAccount.account_code,
                        selectedAccount.account_name,
                        user.id
                    );
                }

                // 3. GENERAR ASIENTO
                const amountCents = Math.abs(tx.amount);
                const entryLines = tx.amount < 0 ? [
                    { account_code: selectedAccount.account_code, debit: amountCents, credit: 0, description: tx.description },
                    { account_code: bankAccountCode, debit: 0, credit: amountCents, description: tx.description }
                ] : [
                    { account_code: bankAccountCode, debit: amountCents, credit: 0, description: tx.description },
                    { account_code: selectedAccount.account_code, debit: 0, credit: amountCents, description: tx.description }
                ];

                await DatabaseService.insertJournalEntry({
                    description: `Clasificaci├│n: ${tx.description}`,
                    date: tx.transaction_date,
                    userId: user.id || 1,
                    items: entryLines
                });

                // 4. Actualizar estado y marcar como matched
                await engine.run(`
                    UPDATE transaction_states 
                    SET current_state = ?, 
                        is_verified = 1,
                        assigned_account_code = ?,
                        assigned_account_name = ?,
                        verified_at = CURRENT_TIMESTAMP,
                        verified_by = ?
                    WHERE id = ?
                `, [TRANSACTION_STATES.VERIFIED, selectedAccount.account_code, selectedAccount.account_name, user.id, stateId]);

                await engine.run(`UPDATE bank_transactions SET status = 'matched' WHERE id = ?`, [tx.id]);
                successCount++;
            }

            toast.success(`${successCount} transacciones clasificadas y contabilizadas correctamente`, { id: loadingToast });

            setSelectedTx(null);
            setSelectedTxIds(new Set());
            setSelectedAccount(null);
            setSearchQuery('');
            setIsAutoSuggested(false);
            loadTransactions();
            // Notificar a otros componentes
            window.dispatchEvent(new CustomEvent('bank-import-complete'));
        } catch (error) {
            console.error('Error classifying:', error);
            toast.error('Fallo en la certificaci├│n contable: ' + (error as Error).message, { id: loadingToast });
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center gap-4 bg-slate-900/50 p-6 rounded-3xl border border-slate-800">
                <div className="p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
                    <ListChecks className="w-8 h-8 text-emerald-500" />
                </div>
                <div>
                    <h1 className="text-3xl font-black text-white tracking-tighter uppercase">Clasificador de Transacciones</h1>
                    <p className="text-slate-400 text-sm">{transactions.length} transacciones pendientes de clasificar</p>
                </div>
            </div>

            {loading ? (
                <div className="flex items-center justify-center p-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-500"></div>
                </div>
            ) : transactions.length === 0 ? (
                <div className="bg-slate-900/30 border-2 border-dashed border-slate-800 rounded-3xl p-20 text-center">
                    <CheckCircle2 className="w-16 h-16 text-emerald-500/30 mx-auto mb-4" />
                    <h3 className="text-xl font-bold text-slate-400">Todo clasificado</h3>
                    <p className="text-slate-500">No hay transacciones pendientes para esta cuenta.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
                    <div className="xl:col-span-2 space-y-4">
                        <div className="flex items-center justify-between px-2 mb-2">
                            <button
                                onClick={selectAllVisible}
                                className="text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-emerald-500 transition-colors"
                            >
                                {selectedTxIds.size === transactions.length ? 'Desmarcar todos' : 'Seleccionar todos'}
                            </button>
                        </div>
                        {transactions.map(tx => (
                            <div
                                key={tx.state_id}
                                className={`group bg-slate-900 rounded-2xl border transition-all duration-300 p-5 flex items-center gap-6
                                ${selectedTxIds.has(tx.state_id) ? 'bg-emerald-500/5 border-emerald-500/30' :
                                        selectedTx?.state_id === tx.state_id
                                            ? 'border-emerald-500 shadow-lg shadow-emerald-500/10 ring-1 ring-emerald-500/50'
                                            : 'border-slate-800 hover:border-slate-700'}`}
                            >
                                <div className="flex items-center h-full">
                                    <input
                                        type="checkbox"
                                        checked={selectedTxIds.has(tx.state_id)}
                                        onChange={() => toggleTxSelection(tx.state_id)}
                                        className="w-5 h-5 rounded-lg border-2 border-slate-700 bg-slate-950 checked:bg-emerald-600 checked:border-emerald-500 focus:ring-0 transition-all cursor-pointer"
                                    />
                                </div>
                                <div
                                    onClick={() => setSelectedTx(tx)}
                                    className="flex-1 flex items-center gap-6 cursor-pointer"
                                >
                                    <div className="w-32 flex-shrink-0">
                                        <div className="text-xs font-black text-slate-500 uppercase tracking-widest mb-1">{tx.date}</div>
                                        <div className={`text-xl font-black ${tx.amount < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                                            ${Math.abs(tx.amount).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                                        </div>
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="text-sm font-bold text-white truncate uppercase group-hover:text-emerald-400 transition-colors">
                                            {tx.description}
                                        </div>
                                    </div>
                                    <button className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all
                                    ${selectedTx?.state_id === tx.state_id
                                            ? 'bg-emerald-600 text-white'
                                            : 'bg-emerald-500/10 border border-emerald-500/20 text-emerald-500'}`}>
                                        Clasificar
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="xl:col-span-1">
                        <div className="sticky top-6 bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
                            {!selectedTx ? (
                                <div className="p-10 text-center space-y-4">
                                    <div className="w-16 h-16 bg-slate-800/50 rounded-2xl flex items-center justify-center mx-auto border border-slate-700">
                                        <ListChecks className="w-8 h-8 text-slate-600" />
                                    </div>
                                    <div className="text-sm font-bold text-slate-500 uppercase tracking-widest">
                                        Seleccion├í una transacci├│n
                                    </div>
                                </div>
                            ) : (
                                <div className="animate-in slide-in-from-right-4 duration-300">
                                    <div className="p-6 border-b border-slate-800">
                                        <h3 className="text-lg font-black text-white uppercase tracking-tighter">Asignar Cuenta Contable</h3>
                                    </div>
                                    <div className="p-6 space-y-6">
                                        <div className="p-4 bg-slate-800/30 rounded-2xl border border-slate-800">
                                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">
                                                {selectedTxIds.size > 1 ? `${selectedTxIds.size} Transacciones Seleccionadas` : 'Descripci├│n'}
                                            </div>
                                            <div className="text-xs font-mono text-slate-300 break-words">
                                                {selectedTxIds.size > 1 ? (
                                                    <div className="space-y-1">
                                                        {transactions.filter(t => selectedTxIds.has(t.state_id)).slice(0, 3).map(t => (
                                                            <div key={t.state_id} className="truncate">ΓÇó {t.description}</div>
                                                        ))}
                                                        {selectedTxIds.size > 3 && <div>... y {selectedTxIds.size - 3} m├ís</div>}
                                                    </div>
                                                ) : (
                                                    selectedTx.description
                                                )}
                                            </div>
                                        </div>

                                        {memorySuggestions.length > 0 && (
                                            <div className="space-y-2">
                                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Usadas antes</div>
                                                {memorySuggestions.map((s, idx) => (
                                                    <button key={idx}
                                                        onClick={() => {
                                                            setSelectedAccount(chartOfAccounts.find(a => a.account_code === s.accountCode) || null);
                                                            setSearchQuery(s.accountName);
