interface TransactionPreviewProps {
    transactions: NormalizedTransaction[];
    onConfirm: (selectedIds: number[]) => void;
    onCancel: () => void;
    loading?: boolean;
}

export const TransactionPreview: React.FC<TransactionPreviewProps> = ({ transactions, onConfirm, onCancel, loading }) => {
    // Selection state (default all selected)
    // We'll use index as temporary ID since normalized transactions might not have unique IDs yet
    const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set(transactions.map((_, i) => i)));

    const summary = useMemo(() => {
        let totalAmount = 0;
        let validCount = 0;
        const errorCount = 0;

        transactions.forEach((t, i) => {
            if (selectedIndices.has(i)) {
                totalAmount += t.amount; // Cents
                validCount++;
            }
        });

        return { totalAmount, validCount, errorCount };
    }, [transactions, selectedIndices]);

    const toggleSelection = (index: number) => {
        const newSet = new Set(selectedIndices);
        if (newSet.has(index)) newSet.delete(index);
        else newSet.add(index);
        setSelectedIndices(newSet);
    };

    const toggleAll = () => {
        if (selectedIndices.size === transactions.length) {
            setSelectedIndices(new Set());
        } else {
            setSelectedIndices(new Set(transactions.map((_, i) => i)));
        }
    };

    if (transactions.length === 0) {
        return (
            <div className="text-center p-8 text-slate-400">
                No hay transacciones para previsualizar.
                <Button variant="ghost" onClick={onCancel} className="mt-4">Volver</Button>
            </div>
        );
    }

    return (
        <div className="space-y-6 animate-in slide-in-from-right duration-300">
            {/* Header / Summary */}
            <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-sm">
                <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
                    <div>
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            ≡ƒôï Vista Previa de Importaci├│n
                        </h3>
                        <p className="text-sm text-slate-400">
                            Revisa y confirma las transacciones antes de guardarlas.
                        </p>
                    </div>

                    <div className="flex gap-6 text-sm">
                        <div>
                            <span className="text-slate-500 block text-xs uppercase font-bold">Transacciones</span>
                            <span className="text-white font-mono text-xl">{summary.validCount} <span className="text-slate-500 text-sm">/ {transactions.length}</span></span>
                        </div>
                        <div>
                            <span className="text-slate-500 block text-xs uppercase font-bold">Total (USD)</span>
                            <span className={`font-mono text-xl ${summary.totalAmount >= 0 ? 'text-green-400' : 'text-slate-300'}`}>
                                ${(summary.totalAmount / 100).toFixed(2)}
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Grid */}
            <Card className="bg-slate-900 border-slate-800 overflow-hidden flex flex-col md:max-h-[600px] h-[500px]">
                <div className="bg-slate-950 border-b border-slate-800 p-3 flex justify-between items-center sticky top-0 z-10">
                    <div className="flex items-center gap-2">
                        <input
                            type="checkbox"
                            checked={selectedIndices.size === transactions.length && transactions.length > 0}
                            onChange={toggleAll}
                            className="rounded border-slate-700 bg-slate-900"
                        />
                        <span className="text-xs text-slate-300 font-bold uppercase tracking-wider">Seleccionar Todo</span>
                    </div>
                    <span className="text-xs text-slate-500">
                        {selectedIndices.size} seleccionados
                    </span>
                </div>

                <div className="overflow-auto flex-1">
                    <table className="w-full text-sm text-left text-slate-400">
                        <thead className="text-xs uppercase bg-slate-950 text-slate-300 sticky top-0 z-0">
                            <tr>
                                <th className="w-10 px-4 py-3 text-center"></th>
                                <th className="px-4 py-3">Fecha</th>
                                <th className="px-4 py-3">Descripci├│n</th>
                                <th className="px-4 py-3 text-right">Monto</th>
                                <th className="px-4 py-3 text-center">Estado</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800">
                            {transactions.map((t, i) => {
                                const isSelected = selectedIndices.has(i);
                                return (
                                    <tr
                                        key={i}
                                        className={`hover:bg-slate-800/50 transition-colors ${!isSelected ? 'opacity-50' : ''}`}
                                        onClick={() => toggleSelection(i)}
                                    >
                                        <td className="px-4 py-3 text-center">
                                            <input
                                                type="checkbox"
                                                checked={isSelected}
                                                onChange={() => { }} // handled by row click
                                                className="rounded border-slate-700 bg-slate-900 pointer-events-none"
                                            />
                                        </td>
                                        <td className="px-4 py-3 font-mono text-xs text-white">
                                            {t.transaction_date}
                                        </td>
                                        <td className="px-4 py-3 text-slate-300">
                                            {t.description}
                                            {t.reference_number && <span className="ml-2 text-xs text-slate-500 bg-slate-800 px-1 rounded">{t.reference_number}</span>}
                                        </td>
                                        <td className={`px-4 py-3 text-right font-mono font-medium ${t.amount < 0 ? 'text-slate-300' : 'text-green-400'}`}>
                                            {(t.amount / 100).toFixed(2)}
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] bg-green-500/10 text-green-400 border border-green-500/20">
                                                <CheckCircle className="w-3 h-3" /> V├ílido
                                            </span>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </Card>

            {/* Actions */}
            <div className="flex justify-end gap-4 pt-4 border-t border-slate-800">
                <Button variant="outline" onClick={onCancel} disabled={loading} className="border-slate-700 hover:bg-slate-800 text-slate-300">
                    <X className="w-4 h-4 mr-2" /> Cancelar
                </Button>
                <Button
                    onClick={() => onConfirm(Array.from(selectedIndices))}
                    disabled={loading || selectedIndices.size === 0}
                    className="bg-blue-600 hover:bg-blue-500 text-white font-bold px-8 shadow-lg shadow-blue-900/20"
                >
                    {loading ? <span className="animate-spin mr-2">ΓÅ│</span> : <ArrowRight className="w-4 h-4 mr-2" />}
                    Confirmar Importaci├│n ({summary.validCount})
                </Button>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription } from '@/components/ui/alert';
import {
  ArrowLeft,
  Edit,
  CheckCircle,
  XCircle,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  DollarSign,
  Calendar,
  BarChart3
} from 'lucide-react';
import {
  getBudgetSummary,
  getBudgetExecutionStatus,
  approveBudget,
  type Budget
} from '@/database/simple-db';
import { BudgetLinesTable } from './BudgetLinesTable';
import { BudgetVarianceReport } from './reports/BudgetVarianceReport';
import { BudgetPerformanceChart } from './reports/BudgetPerformanceChart';
import { useLocale } from '@/i18n/useLocale';

interface BudgetDetailViewProps {
  budget: Budget;
  onEdit: (budget: Budget) => void;
  onDelete: () => void;
  onBack: () => void;
  canEdit?: boolean;
  canDelete?: boolean;
  canApprove?: boolean;
}

export const BudgetDetailView: React.FC<BudgetDetailViewProps> = ({
  budget,
  onEdit,
  onDelete,
  onBack,
  canEdit = false,
  canDelete = false,
  canApprove = false
}) => {
  const { t, language, formatCurrency } = useLocale();
  const [activeTab, setActiveTab] = useState<'overview' | 'lines' | 'reports' | 'charts'>('overview');
  const [summary, setSummary] = useState<any>(null);
  const [executionStatus, setExecutionStatus] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, [budget.id]);

  const loadData = () => {
    try {
      setLoading(true);
      const summaryData = getBudgetSummary(budget.id);
      const statusData = getBudgetExecutionStatus(budget.id);
      setSummary(summaryData);
      setExecutionStatus(statusData);
    } catch (err) {
      console.error('Error loading budget details:', err);
      setError(t('budgets.errorLoadingDetails'));
    } finally {
      setLoading(false);
    }
  };

  const handleApproveBudget = () => {
    if (!confirm(t('budgets.confirmApprove'))) {
      return;
    }

    const result = approveBudget(budget.id, 1); // TODO: Get user ID from auth
    if (result.success) {
      setSuccess(t('budgets.approveSuccess'));
      setTimeout(() => {
        window.location.reload(); // Reload to update status
      }, 1500);
    } else {
      setError(result.message);
    }
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      DRAFT: { label: t('budgets.status.draft'), color: 'bg-slate-800 text-slate-300 border border-slate-700', icon: AlertTriangle },
      APPROVED: { label: t('budgets.status.approved'), color: 'bg-blue-900/40 text-blue-300 border border-blue-800', icon: CheckCircle },
      ACTIVE: { label: t('budgets.status.active'), color: 'bg-green-900/40 text-green-300 border border-green-800', icon: CheckCircle },
      CLOSED: { label: t('budgets.status.closed'), color: 'bg-red-900/40 text-red-300 border border-red-800', icon: XCircle }
    };

    const badge = badges[status as keyof typeof badges] || badges.DRAFT;
    const Icon = badge.icon;

    return (
      <span className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-sm font-medium ${badge.color}`}>
        <Icon className="h-4 w-4" />
        {badge.label}
      </span>
    );
  };

  const getExecutionStatusBadge = (status: string) => {
    const badges = {
      on_track: { label: t('budgets.executionStatus.onTrack'), color: 'bg-green-900/40 text-green-300 border border-green-800', icon: CheckCircle },
      at_risk: { label: t('budgets.executionStatus.atRisk'), color: 'bg-yellow-900/40 text-yellow-300 border border-yellow-800', icon: AlertTriangle },
      over_budget: { label: t('budgets.executionStatus.overBudget'), color: 'bg-red-900/40 text-red-300 border border-red-800', icon: XCircle }
    };

    const badge = badges[status as keyof typeof badges] || badges.on_track;
    const Icon = badge.icon;

    return (
      <span className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-sm font-medium ${badge.color}`}>
        <Icon className="h-4 w-4" />
        {badge.label}
      </span>
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-slate-400">{t('common.loading')}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={onBack} className="text-slate-400 hover:text-white hover:bg-slate-800">
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h2 className="text-2xl font-black tracking-tight text-white">{budget.budget_name}</h2>
            <p className="text-slate-400">{t('budgets.fiscalYear')} {budget.fiscal_year}</p>
          </div>
        </div>
        <div className="flex gap-2">
          {budget.status === 'DRAFT' && canEdit && (
            <>
              <Button variant="outline" onClick={() => onEdit(budget)} className="border-slate-700 text-slate-300 hover:bg-slate-800">
                <Edit className="h-4 w-4 mr-2" />
                {t('common.edit')}
              </Button>
              {canApprove && (
                <Button onClick={handleApproveBudget} className="bg-green-600 hover:bg-green-700 text-white">
                  <CheckCircle className="h-4 w-4 mr-2" />
                  {t('budgets.approve')}
                </Button>
              )}
            </>
          )}
        </div>
      </div>

      {/* Alerts */}
      {error && (
        <Alert variant="destructive" className="bg-red-900/20 border-red-900 text-red-200">
          <AlertTriangle className="h-4 w-4 text-red-400" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {success && (
        <Alert className="bg-green-900/20 border-green-900 text-green-200">
          <AlertDescription className="text-green-300">{success}</AlertDescription>
        </Alert>
      )}

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-400">{t('common.status')}</p>
                <div className="mt-2">{getStatusBadge(budget.status)}</div>
              </div>
              <Calendar className="h-8 w-8 text-blue-500" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-400">{t('budgets.totalBudgeted')}</p>
                <p className="text-2xl font-black tracking-tight text-white">
                  {summary ? formatCurrency(summary.total_budgeted / 100) : formatCurrency(0)}
                </p>
              </div>
              <DollarSign className="h-8 w-8 text-green-500" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-400">{t('budgets.totalActual')}</p>
                <p className="text-2xl font-black tracking-tight text-white">
                  {summary ? formatCurrency(summary.total_actual / 100) : formatCurrency(0)}
                </p>
              </div>
              <TrendingUp className="h-8 w-8 text-purple-500" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-400">{t('budgets.variance')}</p>
                <p className={`text-2xl font-black tracking-tight ${summary && summary.total_variance > 0 ? 'text-red-400' : 'text-green-400'}`}>
                  {summary ? formatCurrency(Math.abs(summary.total_variance / 100)) : formatCurrency(0)}
                </p>
                <p className="text-xs text-slate-500 mt-1">
                  {summary && summary.total_variance > 0 ? t('budgets.overBudget') : t('budgets.underBudget')}
                </p>
              </div>
              {summary && summary.total_variance > 0 ? (
                <TrendingUp className="h-8 w-8 text-red-500" />
              ) : (
                <TrendingDown className="h-8 w-8 text-green-500" />
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Execution Status */}
      {executionStatus && (
        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardHeader>
            <CardTitle>{t('budgets.executionStatus.title')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div>
                <p className="text-sm font-medium text-slate-400 mb-2">{t('budgets.executionStatus.general')}</p>
                {getExecutionStatusBadge(executionStatus.status)}
              </div>
              <div>
                <p className="text-sm font-medium text-slate-400 mb-1">{t('budgets.executionStatus.timeProgress')}</p>
                <div className="flex items-baseline gap-2">
                  <p className="text-2xl font-black tracking-tight text-white">{executionStatus.period_progress_percent.toFixed(1)}%</p>
                  <p className="text-sm text-slate-500">{t('budgets.executionStatus.ofPeriod')}</p>
                </div>
                <p className="text-xs text-slate-500 mt-1">
                  {executionStatus.days_elapsed} {t('budgets.executionStatus.daysElapsed')}, {executionStatus.days_remaining} {t('budgets.executionStatus.daysRemaining')}
                </p>
              </div>
              <div>
                <p className="text-sm font-medium text-slate-400 mb-1">{t('budgets.executionStatus.budgetConsumption')}</p>
                <div className="flex items-baseline gap-2">
                  <p className="text-2xl font-black tracking-tight text-white">{executionStatus.budget_consumed_percent.toFixed(1)}%</p>
                  <p className="text-sm text-slate-500">{t('budgets.executionStatus.consumed')}</p>
                </div>
              </div>
              <div>
                <p className="text-sm font-medium text-slate-400 mb-1">{t('budgets.executionStatus.pace')}</p>
                <div className="flex items-center gap-2">
                  {executionStatus.pace_indicator === 'ahead' && (
                    <span className="text-red-400 font-semibold">{t('budgets.executionStatus.paceAhead')}</span>
                  )}
                  {executionStatus.pace_indicator === 'on_pace' && (
                    <span className="text-green-400 font-semibold">{t('budgets.executionStatus.paceOnTrack')}</span>
                  )}
                  {executionStatus.pace_indicator === 'behind' && (
                    <span className="text-blue-400 font-semibold">{t('budgets.executionStatus.paceBehind')}</span>
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Tabs */}
      <div className="border-b border-slate-800">
        <nav className="-mb-px flex space-x-8">
          <button
            onClick={() => setActiveTab('overview')}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${activeTab === 'overview'
              ? 'border-blue-500 text-blue-400'
              : 'border-transparent text-slate-400 hover:text-slate-300 hover:border-slate-600'
              }`}
          >
            {t('budgets.tabs.overview')}
          </button>
          <button
            onClick={() => setActiveTab('lines')}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${activeTab === 'lines'
              ? 'border-blue-500 text-blue-400'
              : 'border-transparent text-slate-400 hover:text-slate-300 hover:border-slate-600'
              }`}
          >
            {t('budgets.lines')}
          </button>
          <button
            onClick={() => setActiveTab('reports')}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${activeTab === 'reports'
              ? 'border-blue-500 text-blue-400'
              : 'border-transparent text-slate-400 hover:text-slate-300 hover:border-slate-600'
              }`}
          >
            {t('budgets.reports.variance')}
          </button>
          <button
            onClick={() => setActiveTab('charts')}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${activeTab === 'charts'
              ? 'border-blue-500 text-blue-400'
              : 'border-transparent text-slate-400 hover:text-slate-300 hover:border-slate-600'
              }`}
          >
            {t('budgets.tabs.charts')}
          </button>
        </nav>
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && summary && (
        <Card className="bg-slate-900 border-slate-800 text-white">
          <CardHeader>
            <CardTitle>{t('common.generalInfo')}</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h3 className="font-semibold text-white mb-3">{t('budgets.budgetDetails')}</h3>
                <dl className="space-y-2">
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.period')}:</dt>
                    <dd className="font-medium text-slate-200">
                      {new Date(budget.start_date).toLocaleDateString(language === 'es' ? 'es-ES' : 'en-US')} - {new Date(budget.end_date).toLocaleDateString(language === 'es' ? 'es-ES' : 'en-US')}
                    </dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.department')}:</dt>
                    <dd className="font-medium text-slate-200">{budget.department || 'N/A'}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.linesCount')}:</dt>
                    <dd className="font-medium text-slate-200">{summary.lines_count}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.alertThreshold')}:</dt>
                    <dd className="font-medium text-slate-200">{budget.alert_threshold_percentage || 10}%</dd>
                  </div>
                </dl>
              </div>

              <div>
                <h3 className="font-semibold text-white mb-3">{t('budgets.lineAnalysis')}</h3>
                <dl className="space-y-2">
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.overBudget')}:</dt>
                    <dd className="font-medium text-red-400">{summary.lines_over_budget}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.underBudget')}:</dt>
                    <dd className="font-medium text-green-400">{summary.lines_under_budget}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.onBudget')}:</dt>
                    <dd className="font-medium text-white">{summary.lines_on_budget}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-slate-400">{t('budgets.activeAlerts')}:</dt>
                    <dd className="font-medium text-orange-400">{summary.alert_count}</dd>
                  </div>
                </dl>
              </div>
            </div>

            {budget.notes && (
              <div className="pt-4 border-t border-slate-800">
                <h3 className="font-semibold text-white mb-2">{t('common.notes')}</h3>
                <p className="text-slate-300">{budget.notes}</p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {activeTab === 'lines' && (
        <BudgetLinesTable budgetId={budget.id} />
      )}

      {activeTab === 'reports' && (
        <BudgetVarianceReport budgetId={budget.id} />
      )}

      {activeTab === 'charts' && (
        <BudgetPerformanceChart budgetId={budget.id} />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Plus, Trash2, AlertTriangle, Save, XCircle, Target, ShieldCheck, Loader2 } from 'lucide-react';
import {
  createBudget,
  updateBudget,
  getChartOfAccounts,
  type Budget,
  type BudgetLine
} from '@/database/simple-db';
import { BudgetLineEditor } from './BudgetLineEditor';
import { useLocale } from '@/i18n/useLocale';

interface BudgetFormProps {
  budget: Budget | null;
  onSave: () => void;
  onCancel: () => void;
}

export const BudgetForm: React.FC<BudgetFormProps> = ({ budget, onSave, onCancel }) => {
  const { t } = useLocale();
  const isEditing = !!budget;

  // Form state
  const [budgetName, setBudgetName] = useState(budget?.budget_name || '');
  const [fiscalYear, setFiscalYear] = useState(budget?.fiscal_year || new Date().getFullYear());
  const [startDate, setStartDate] = useState(budget?.start_date || `${new Date().getFullYear()}-01-01`);
  const [endDate, setEndDate] = useState(budget?.end_date || `${new Date().getFullYear()}-12-31`);
  const [department, setDepartment] = useState(budget?.department || '');
  const [notes, setNotes] = useState(budget?.notes || '');
  const [alertThreshold, setAlertThreshold] = useState(budget?.alert_threshold_percentage || 10);

  // Budget lines
  const [lines, setLines] = useState<Partial<BudgetLine>[]>([]);

  // UI state
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);

  // Auto-calculate fiscal year from start date
  useEffect(() => {
    if (startDate) {
      const year = new Date(startDate).getFullYear();
      setFiscalYear(year);
    }
  }, [startDate]);

  // Calculate total budget amount
  const totalBudgetAmount = lines.reduce((sum, line) => sum + (line.annual_amount || 0), 0);

  const validate = (): boolean => {
    const errors: string[] = [];

    if (!budgetName.trim()) {
      errors.push(t('budgets.validation.nameRequired'));
    }

    if (!startDate) {
      errors.push(t('budgets.validation.startDateRequired'));
    }

    if (!endDate) {
      errors.push(t('budgets.validation.endDateRequired'));
    }

    if (startDate && endDate && new Date(startDate) >= new Date(endDate)) {
      errors.push(t('budgets.validation.endDateAfterStartDate'));
    }

    if (lines.length === 0) {
      errors.push(t('budgets.validation.linesRequired'));
    }

    // Validate lines
    lines.forEach((line, index) => {
      if (!line.account_number) {
        errors.push(t('budgets.validation.lineAccountRequired', { index: index + 1 }));
      }
      if (!line.annual_amount || line.annual_amount <= 0) {
        errors.push(t('budgets.validation.lineAmountPositive', { index: index + 1 }));
      }
    });

    setValidationErrors(errors);
    return errors.length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const budgetData = {
        budget_name: budgetName,
        fiscal_year: fiscalYear,
        start_date: startDate,
        end_date: endDate,
        status: 'DRAFT' as const,
        total_budget_amount: totalBudgetAmount,
        department: department || undefined,
        notes: notes || undefined,
        alert_threshold_percentage: alertThreshold,
        created_by: 1 // TODO: Get from auth context
      };

      if (isEditing) {
        const result = updateBudget(budget.id, budgetData, lines as Partial<BudgetLine>[]);
        if (!result.success) {
          throw new Error(result.message);
        }
      } else {
        const result = await createBudget(budgetData, lines as Omit<BudgetLine, 'id' | 'budget_id' | 'created_at'>[]);
        if (!result.success) {
          throw new Error(result.message);
        }
      }

      onSave();
    } catch (err) {
      console.error('Error saving budget:', err);
      setError(err instanceof Error ? err.message : t('common.error'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
      <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-5xl max-h-[95vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-500/5 blur-[120px] pointer-events-none"></div>

        {/* Header Hub */}
        <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
          <div className="flex items-center gap-6">
            <div className="text-blue-500">
              <Target className="w-8 h-8" />
            </div>
            <div>
              <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                {isEditing ? t('budgets.editBudget') : t('budgets.newBudget')}
              </h2>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2 flex items-center gap-2">
                <ShieldCheck className="w-3.5 h-3.5 text-blue-500" /> Fiscal Protocol v3.0
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onCancel}
            className="p-3 bg-slate-950/50 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95"
          >
            <XCircle className="w-6 h-6" />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-10 space-y-12 relative z-10 custom-scrollbar">
          {/* Error Feedback */}
          {(validationErrors.length > 0 || error) && (
            <div className="bg-rose-500/10 border border-rose-500/30 rounded-[2rem] p-8 space-y-4 animate-in shake duration-500">
              <div className="flex items-center gap-4">
                <AlertTriangle className="w-6 h-6 text-rose-500" />
                <p className="text-[11px] font-black text-rose-500 uppercase tracking-widest leading-none">
                  {t('common.error') || 'ERROR DE VALIDACI├ôN'}
                </p>
              </div>
              <ul className="list-disc list-inside space-y-1">
                {validationErrors.map((err, idx) => (
                  <li key={idx} className="text-[11px] font-bold text-rose-200/70 uppercase tracking-tight">{err}</li>
                ))}
                {error && <li className="text-[11px] font-bold text-rose-200/70 uppercase tracking-tight">{error}</li>}
              </ul>
            </div>
          )}

          {/* Primary Info Block */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            <div className="md:col-span-2 space-y-4">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">
                {t('budgets.budgetName')} *
              </label>
              <input
                type="text"
                value={budgetName}
                onChange={(e) => setBudgetName(e.target.value)}
                placeholder={t('budgets.placeholders.budgetName')}
                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2.5xl px-8 py-5 text-white focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[11px] placeholder:text-slate-800"
                required
              />
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">{t('budgets.startDate')} *</label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2.5xl px-8 py-5 text-white focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[11px]"
                required
              />
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">{t('budgets.endDate')} *</label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2.5xl px-8 py-5 text-white focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[11px]"
                required
              />
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">{t('budgets.department')}</label>
              <input
                type="text"
                value={department}
                onChange={(e) => setDepartment(e.target.value)}
                placeholder={t('budgets.placeholders.department')}
                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2.5xl px-8 py-5 text-white focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[11px] placeholder:text-slate-800"
              />
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">{t('budgets.fiscalYear')}</label>
              <div className="w-full bg-slate-950/30 border border-slate-800/30 rounded-2.5xl px-8 py-5 text-slate-600 font-black uppercase tracking-widest text-[11px]">
                {fiscalYear}
              </div>
            </div>
          </div>

          {/* Editor Section */}
          <div className="pt-12 border-t border-slate-800/50">
            <BudgetLineEditor
              lines={lines}
              onChange={setLines}
              totalAmount={totalBudgetAmount}
            />
          </div>
        </div>

        {/* Footer Action Hub */}
        <footer className="p-10 border-t border-slate-800/50 bg-slate-950/30 flex justify-end gap-6 flex-shrink-0 relative z-10">
          <button
            type="button"
            onClick={onCancel}
            disabled={loading}
            className="px-10 py-5 text-slate-500 hover:text-white transition-all font-black uppercase tracking-widest text-[10px] hover:bg-slate-900 rounded-2xl border border-transparent hover:border-slate-800"
          >
            {t('common.cancel')}
          </button>
          <button
            onClick={handleSubmit}
            disabled={loading || lines.length === 0}
            className="bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:opacity-50 text-white px-12 py-5 rounded-2.5xl font-black uppercase tracking-widest text-[11px] transition-all flex items-center justify-center gap-4 shadow-3xl shadow-blue-900/40 hover:-translate-y-1 active:scale-95"
          >
            {loading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <Save className="w-5 h-5" />
                <span>{isEditing ? t('budgets.updateBudget') : t('budgets.createBudget')}</span>
              </>
            )}
          </button>
        </footer>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { ChevronDown, ChevronRight, AlertTriangle, TrendingUp, TrendingDown } from 'lucide-react';
import {
  getBudgetLines,
  getBudgetVarianceAnalysis,
  type BudgetLine,
  type BudgetVarianceAnalysis
} from '@/database/simple-db';
import { useLocale } from '@/i18n/useLocale';

interface BudgetLinesTableProps {
  budgetId: number;
}

export const BudgetLinesTable: React.FC<BudgetLinesTableProps> = ({ budgetId }) => {
  const { t } = useLocale();
  const [lines, setLines] = useState<BudgetLine[]>([]);
  const [varianceData, setVarianceData] = useState<BudgetVarianceAnalysis[]>([]);
  const [expandedLines, setExpandedLines] = useState<Set<number>>(new Set());
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, [budgetId]);

  const loadData = () => {
    try {
      setLoading(true);
      const linesData = getBudgetLines(budgetId);
      const varianceAnalysis = getBudgetVarianceAnalysis(budgetId);
      setLines(linesData);
      setVarianceData(varianceAnalysis);
    } catch (error) {
      console.error('Error loading budget lines:', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleExpand = (lineId: number) => {
    const newExpanded = new Set(expandedLines);
    if (newExpanded.has(lineId)) {
      newExpanded.delete(lineId);
    } else {
      newExpanded.add(lineId);
    }
    setExpandedLines(newExpanded);
  };

  const getVarianceColor = (variancePercent: number): string => {
    if (Math.abs(variancePercent) < 5) return 'text-slate-400';
    return variancePercent > 0 ? 'text-red-400' : 'text-green-400';
  };

  const getVarianceBgColor = (variancePercent: number): string => {
    if (Math.abs(variancePercent) < 5) return 'bg-slate-800/50';
    return variancePercent > 0 ? 'bg-red-900/10' : 'bg-green-900/10';
  };

  if (loading) {
    return (
      <Card className="bg-slate-900 border-slate-800 text-white">
        <CardContent className="py-12">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
            <p className="mt-4 text-slate-400">{t('common.loading')}</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="bg-slate-900 border-slate-800 text-white">
      <CardHeader>
        <CardTitle>{t('budgets.linesWithVariance')}</CardTitle>
      </CardHeader>
      <CardContent>
        {lines.length === 0 ? (
          <div className="text-center py-8 text-slate-500">
            <p>{t('budgets.noLines')}</p>
          </div>
        ) : (
          <div className="overflow-x-auto rounded-lg border border-slate-800">
            <table className="w-full">
              <thead className="bg-slate-950">
                <tr>
                  <th className="text-left py-3 px-4 font-semibold text-slate-400 w-8"></th>
                  <th className="text-left py-3 px-4 font-semibold text-slate-400">{t('budgets.account')}</th>
                  <th className="text-left py-3 px-4 font-semibold text-slate-400">{t('budgets.account')}</th>
                  <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.budgetedYTD')}</th>
                  <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.actualYTD')}</th>
                  <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.variance')}</th>
                  <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.variancePercent')}</th>
                  <th className="text-center py-3 px-4 font-semibold text-slate-400">{t('common.status')}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {lines.map((line) => {
                  const variance = varianceData.find(v => v.account_number === line.account_number);
                  const isExpanded = expandedLines.has(line.id);
                  const hasAlert = variance && Math.abs(variance.ytd_variance_percent) > 10;

                  return (
                    <React.Fragment key={line.id}>
                      {/* Main Row */}
                      <tr
                        className={`hover:bg-slate-800/60 transition-colors ${hasAlert ? 'bg-yellow-900/10' : 'bg-slate-900'
                          }`}
                      >
                        <td className="py-3 px-4">
                          <button
                            onClick={() => toggleExpand(line.id)}
                            className="text-slate-500 hover:text-white"
                          >
                            {isExpanded ? (
                              <ChevronDown className="h-4 w-4" />
                            ) : (
                              <ChevronRight className="h-4 w-4" />
                            )}
                          </button>
                        </td>
                        <td className="py-3 px-4 font-medium text-slate-200">
                          {line.account_number}
                        </td>
                        <td className="py-3 px-4 text-slate-300">
                          {variance?.account_name || 'N/A'}
                        </td>
                        <td className="py-3 px-4 text-right font-medium text-slate-200">
                          ${variance ? (variance.ytd_budget / 100).toLocaleString('en-US', { minimumFractionDigits: 2 }) : '0.00'}
                        </td>
                        <td className="py-3 px-4 text-right font-medium text-slate-200">
                          ${variance ? (variance.ytd_actual / 100).toLocaleString('en-US', { minimumFractionDigits: 2 }) : '0.00'}
                        </td>
                        <td className={`py-3 px-4 text-right font-medium ${variance ? getVarianceColor(variance.ytd_variance_percent) : 'text-slate-200'}`}>
                          {variance ? (
                            <>
                              {variance.ytd_variance > 0 ? '+' : ''}
                              ${(variance.ytd_variance / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                            </>
                          ) : (
                            '$0.00'
                          )}
                        </td>
                        <td className={`py-3 px-4 text-right font-medium ${variance ? getVarianceColor(variance.ytd_variance_percent) : 'text-slate-200'}`}>
                          {variance ? (
                            <>
                              {variance.ytd_variance_percent > 0 ? '+' : ''}
                              {variance.ytd_variance_percent.toFixed(1)}%
                            </>
                          ) : (
                            '0.0%'
                          )}
                        </td>
                        <td className="py-3 px-4 text-center">
                          {hasAlert && (
                            <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-black uppercase tracking-[0.2em] bg-yellow-900/40 text-yellow-300 border border-yellow-800">
                              <AlertTriangle className="h-3 w-3" />
                              {t('budgets.alert')}
                            </span>
                          )}
                          {variance && !hasAlert && Math.abs(variance.ytd_variance_percent) < 5 && (
                            <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-black uppercase tracking-[0.2em] bg-green-900/40 text-green-300 border border-green-800">
                              {t('budgets.onTrack')}
                            </span>
                          )}
                        </td>
                      </tr>

                      {/* Expanded Period Breakdown */}
                      {isExpanded && variance && (
                        <tr>
                          <td colSpan={8} className="py-4 px-8 bg-slate-950">
                            <div className="space-y-2">
                              <h4 className="font-semibold text-slate-300 mb-3">{t('budgets.periodBreakdown')}</h4>
                              <div className="overflow-x-auto border border-slate-800 rounded">
                                <table className="w-full text-sm">
                                  <thead>
                                    <tr className="border-b border-slate-800 bg-slate-900">
                                      <th className="text-left py-2 px-3 font-medium text-slate-400">{t('budgets.period')}</th>
                                      <th className="text-right py-2 px-3 font-medium text-slate-400">{t('budgets.budgeted')}</th>
                                      <th className="text-right py-2 px-3 font-medium text-slate-400">{t('budgets.actual')}</th>
                                      <th className="text-right py-2 px-3 font-medium text-slate-400">{t('budgets.variance')}</th>
                                      <th className="text-right py-2 px-3 font-medium text-slate-400">{t('budgets.variancePercent')}</th>
                                      <th className="text-center py-2 px-3 font-medium text-slate-400">{t('common.status')}</th>
                                    </tr>
                                  </thead>
                                  <tbody>
                                    {variance.periods.map((period) => (
                                      <tr key={period.period_number} className={`border-b border-slate-800 ${getVarianceBgColor(period.variance_percent)}`}>
                                        <td className="py-2 px-3 text-slate-300">{period.period_name}</td>
                                        <td className="py-2 px-3 text-right text-slate-200">
                                          ${(period.budgeted / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                                        </td>
                                        <td className="py-2 px-3 text-right text-slate-200">
                                          ${(period.actual / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                                        </td>
                                        <td className={`py-2 px-3 text-right font-medium ${getVarianceColor(period.variance_percent)}`}>
                                          {period.variance > 0 ? '+' : ''}
                                          ${(period.variance / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                                        </td>
                                        <td className={`py-2 px-3 text-right font-medium ${getVarianceColor(period.variance_percent)}`}>
                                          {period.variance_percent > 0 ? '+' : ''}
                                          {period.variance_percent.toFixed(1)}%
                                        </td>
                                        <td className="py-2 px-3 text-center">
                                          {period.is_favorable ? (
                                            <TrendingDown className="h-4 w-4 text-green-500 mx-auto" />
                                          ) : (
                                            <TrendingUp className="h-4 w-4 text-red-500 mx-auto" />
                                          )}
                                        </td>
                                      </tr>
                                    ))}
                                  </tbody>
                                </table>
                              </div>
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import {
  DollarSign,
  Plus,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  FileText,
  BarChart3,
  Calendar
} from 'lucide-react';
import {
  getBudgets,
  getBudgetSummary,
  getBudgetExecutionStatus,
  type Budget
} from '@/database/simple-db';
import { useAuth } from '@/contexts/AuthContext';
import { BudgetList } from './BudgetList';
import { BudgetForm } from './BudgetForm';
import { BudgetDetailView } from './BudgetDetailView';
import { useLocale } from '@/i18n/useLocale';

/**
 * BudgetManager
 * 
 * Main container for Budget Management module with:
 * - Budget summary KPIs
 * - Budget list with filters
 * - Quick actions (Create Budget, Reports)
 * - Budget detail view
 */
export const BudgetManager: React.FC = () => {
  const { t } = useLocale();
  const { user } = useAuth();
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<'list' | 'create' | 'detail'>('list');
  const [selectedBudget, setSelectedBudget] = useState<Budget | null>(null);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);

  // Filters
  const [filterStatus, setFilterStatus] = useState<string>('');
  const [filterYear, setFilterYear] = useState<number>(new Date().getFullYear());

  // Permission checks
  const canCreate = user ? ['admin', 'contador'].includes(user.role) : false;
  const canEdit = user ? ['admin', 'contador'].includes(user.role) : false;
  const canDelete = user ? ['admin'].includes(user.role) : false;
  const canApprove = user ? ['admin', 'contador'].includes(user.role) : false;
  const canView = user ? ['admin', 'contador', 'auditor'].includes(user.role) : false;

  // Summary stats
  const [stats, setStats] = useState({
    total_budgets: 0,
    active_budgets: 0,
    total_budgeted: 0,
    total_actual: 0,
    budgets_at_risk: 0
  });

  useEffect(() => {
    loadData();
  }, [filterStatus, filterYear]);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);

      // Load budgets with filters (include user context for role-based access)
      const filters: any = {};
      if (filterYear) filters.fiscal_year = filterYear;
      if (filterStatus) filters.status = filterStatus;
      if (user) {
        filters.userId = user.id;
        filters.role = user.role;
      }

      const budgetsData = getBudgets(filters);
      setBudgets(budgetsData);

      // Calculate summary stats
      const activeBudgets = budgetsData.filter(b => b.status === 'ACTIVE');
      let totalBudgeted = 0;
      let totalActual = 0;
      let budgetsAtRisk = 0;

      for (const budget of activeBudgets) {
        const summary = getBudgetSummary(budget.id);
        if (summary) {
          totalBudgeted += summary.total_budgeted;
          totalActual += summary.total_actual;

          const status = getBudgetExecutionStatus(budget.id);
          if (status && (status.status === 'at_risk' || status.status === 'over_budget')) {
            budgetsAtRisk++;
          }
        }
      }

      setStats({
        total_budgets: budgetsData.length,
        active_budgets: activeBudgets.length,
        total_budgeted: totalBudgeted,
        total_actual: totalActual,
        budgets_at_risk: budgetsAtRisk
      });

    } catch (err) {
      console.error('Error loading budgets:', err);
      setError(err instanceof Error ? err.message : t('budgets.loading'));
    } finally {
      setLoading(false);
    }
  };

  const handleCreateBudget = () => {
    if (!canCreate) {
      setError(t('budgets.noPermissionCreate'));
      return;
    }
    setEditingBudget(null);
    setActiveView('create');
  };

  const handleEditBudget = (budget: Budget) => {
    if (!canEdit) {
      setError(t('budgets.noPermissionEdit'));
      return;
    }
    setEditingBudget(budget);
    setActiveView('create');
  };

  const handleViewBudget = (budget: Budget) => {
    setSelectedBudget(budget);
    setActiveView('detail');
  };

  const handleBudgetSaved = () => {
    setSuccess(t('budgets.saveSuccess'));
    setActiveView('list');
    loadData();
    setTimeout(() => setSuccess(null), 3000);
  };

  const handleBudgetDeleted = () => {
    setSuccess(t('budgets.deleteSuccess'));
    setActiveView('list');
    loadData();
    setTimeout(() => setSuccess(null), 3000);
  };

  const handleBackToList = () => {
    setActiveView('list');
    setSelectedBudget(null);
    setEditingBudget(null);
  };

  if (loading && budgets.length === 0) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-slate-700">{t('budgets.loading')}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-white">{t('budgets.title')}</h1>
          <p className="text-slate-400 mt-1">{t('budgets.subtitle')}</p>
        </div>
        {activeView === 'list' && canCreate && (
          <Button onClick={handleCreateBudget} className="flex items-center gap-2">
            <Plus className="h-4 w-4" />
            {t('budgets.newBudget')}
          </Button>
        )}
        {activeView !== 'list' && (
          <Button onClick={handleBackToList} variant="outline">
            {t('common.back')}
          </Button>
        )}
      </div>

      {/* Alerts */}
      {error && (
        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertTitle>{t('common.error')}</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {success && (
        <Alert className="bg-green-50 border-green-200">
          <AlertTitle className="text-green-800">{t('common.success')}</AlertTitle>
          <AlertDescription className="text-green-700">{success}</AlertDescription>
        </Alert>
      )}

      {/* Summary KPIs - Only show in list view */}
      {activeView === 'list' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardContent className="pt-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-slate-400">{t('budgets.totalBudgets')}</p>
                  <p className="text-2xl font-black tracking-tight text-white">{stats.total_budgets}</p>
                </div>
                <FileText className="h-8 w-8 text-blue-500" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardContent className="pt-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-slate-400">{t('budgets.activeBudgets')}</p>
                  <p className="text-2xl font-black tracking-tight text-green-400">{stats.active_budgets}</p>
                </div>
                <Calendar className="h-8 w-8 text-green-500" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardContent className="pt-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-slate-400">{t('budgets.totalBudgeted')}</p>
                  <p className="text-2xl font-black tracking-tight text-white">
                    ${(stats.total_budgeted / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                  </p>
                </div>
                <DollarSign className="h-8 w-8 text-blue-500" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardContent className="pt-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-slate-400">{t('budgets.totalExecuted')}</p>
                  <p className="text-2xl font-black tracking-tight text-white">
                    ${(stats.total_actual / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                  </p>
                </div>
                <TrendingUp className="h-8 w-8 text-purple-500" />
              </div>
            </CardContent>
          </Card>

          <Card className="bg-slate-900 border-slate-800 text-white">
            <CardContent className="pt-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-slate-400">{t('budgets.budgetsAtRisk')}</p>
                  <p className="text-2xl font-black tracking-tight text-red-400">{stats.budgets_at_risk}</p>
                </div>
                <AlertTriangle className="h-8 w-8 text-red-500" />
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Main Content */}
      {activeView === 'list' && (
        <BudgetList
          budgets={budgets}
          onViewBudget={handleViewBudget}
          onEditBudget={handleEditBudget}
          onDeleteBudget={handleBudgetDeleted}
          filterStatus={filterStatus}
          filterYear={filterYear}
          onFilterStatusChange={setFilterStatus}
          onFilterYearChange={setFilterYear}
        />
      )}

      {activeView === 'create' && (
        <BudgetForm
          budget={editingBudget}
          onSave={handleBudgetSaved}
          onCancel={handleBackToList}
        />
      )}

      {activeView === 'detail' && selectedBudget && (
        <BudgetDetailView
          budget={selectedBudget}
          onEdit={handleEditBudget}
          onDelete={handleBudgetDeleted}
          onBack={handleBackToList}
          canEdit={canEdit}
          canDelete={canDelete}
          canApprove={canApprove}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { getBudgetVarianceAnalysis, type BudgetVarianceAnalysis } from '@/database/simple-db';
import { Download, Filter } from 'lucide-react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { useLocale } from '@/i18n/useLocale';

interface BudgetVarianceReportProps {
  budgetId: number;
}

export const BudgetVarianceReport: React.FC<BudgetVarianceReportProps> = ({ budgetId }) => {
  const { t } = useLocale();
  const [varianceData, setVarianceData] = useState<BudgetVarianceAnalysis[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<'ALL' | 'OVER_BUDGET' | 'UNDER_BUDGET'>('ALL');

  useEffect(() => {
    loadData();
  }, [budgetId]);

  const loadData = () => {
    try {
      setLoading(true);
      const data = getBudgetVarianceAnalysis(budgetId);
      setVarianceData(data);
    } catch (error) {
      console.error('Error loading variance report:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredData = varianceData.filter(item => {
    if (filterType === 'OVER_BUDGET') return item.ytd_variance > 0;
    if (filterType === 'UNDER_BUDGET') return item.ytd_variance < 0;
    return true;
  });

  const totalVariance = filteredData.reduce((acc, item) => acc + item.ytd_variance, 0);

  const exportToCSV = () => {
    const headers = [
      t('budgets.account'),
      t('budgets.account'),
      t('budgets.budgetedYTD'),
      t('budgets.actualYTD'),
      t('budgets.variance'),
      t('budgets.variancePercent')
    ];
    const rows = filteredData.map(item => {
      const row = [
        item.account_number,
        '"' + item.account_name + '"',
        (item.ytd_budget / 100).toFixed(2),
        (item.ytd_actual / 100).toFixed(2),
        (item.ytd_variance / 100).toFixed(2),
        item.ytd_variance_percent.toFixed(2) + '%'
      ];
      return row.join(',');
    });

    const csvContent = [
      headers.join(','),
      ...rows
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.download !== undefined) {
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', 'reporte_varianza_' + budgetId + '.csv');
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const exportToPDF = () => {
    const doc = new jsPDF();

    // T├¡tulo del reporte
    doc.setFontSize(18);
    doc.text(t('budgets.reports.title'), 14, 22);

    // Fecha de generaci├│n
    doc.setFontSize(11);
    doc.setTextColor(100);
    const date = new Date().toLocaleDateString(t('common.localeCode') === 'es' ? 'es-ES' : 'en-US');
    doc.text(t('budgets.reports.generated') + ' ' + date, 14, 30);

    // Resumen
    doc.setFontSize(12);
    doc.setTextColor(0);
    doc.text(t('budgets.reports.totalVariance') + ' $' + (totalVariance / 100).toLocaleString('en-US', { minimumFractionDigits: 2 }), 14, 40);

    // Tabla de datos
    const tableColumn = [
      t('budgets.account'),
      t('accounting.accountName'),
      t('budgets.budgeted'),
      t('budgets.actual'),
      t('budgets.variance'),
      "%"
    ];
    const tableRowsBuffer: any[] = [];

    filteredData.forEach(item => {
      const budgetData = [
        item.account_number,
        item.account_name,
        '$' + (item.ytd_budget / 100).toFixed(2),
        '$' + (item.ytd_actual / 100).toFixed(2),
        '$' + (item.ytd_variance / 100).toFixed(2),
        item.ytd_variance_percent.toFixed(1) + '%'
      ];
      tableRowsBuffer.push(budgetData);
    });

    autoTable(doc, {
      head: [tableColumn],
      body: tableRowsBuffer,
      startY: 45,
      theme: 'grid',
      styles: { fontSize: 8 },
      headStyles: { fillColor: [41, 128, 185] }
    });

    doc.save('reporte_varianza_' + budgetId + '.pdf');
  };

  if (loading) {
    return (
      <Card className="bg-slate-900 border-slate-800 text-white">
        <CardContent className="py-12 text-center text-slate-400">
          {t('common.loading')}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="bg-slate-900 border-slate-800 text-white">
      <CardHeader>
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <CardTitle>{t('budgets.reports.title')}</CardTitle>
          <div className="flex gap-2">
            <div className="flex items-center bg-slate-800 rounded-md border border-slate-700 p-1">
              <Filter className="h-4 w-4 text-slate-400 ml-2 mr-1" />
              <select
                value={filterType}
                onChange={(e) => setFilterType(e.target.value as any)}
                className="bg-transparent border-none text-sm text-white focus:ring-0 cursor-pointer py-1"
              >
                <option value="ALL">{t('common.all')}</option>
                <option value="OVER_BUDGET">{t('budgets.overBudget')}</option>
                <option value="UNDER_BUDGET">{t('budgets.underBudget')}</option>
              </select>
            </div>
            <Button variant="outline" size="sm" onClick={exportToCSV} className="border-slate-700 text-slate-300 hover:bg-slate-800">
              <Download className="h-4 w-4 mr-2" />
              CSV
            </Button>
            <Button variant="outline" size="sm" onClick={exportToPDF} className="border-slate-700 text-slate-300 hover:bg-slate-800">
              <Download className="h-4 w-4 mr-2" />
              PDF
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {/* Summary Header */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <div className="bg-slate-800 p-4 rounded-lg border border-slate-700">
            <p className="text-sm font-medium text-slate-400">{t('budgets.reports.totalVarianceYTD')}</p>
            <div className="flex items-center gap-2 mt-1">
              <span className={`text-2xl font-black tracking-tight ${totalVariance > 0 ? 'text-red-400' : 'text-green-400'}`}>
                ${Math.abs(totalVariance / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
              </span>
              <span className="text-sm text-slate-500">
                {totalVariance > 0 ? t('budgets.overBudget') : t('budgets.underBudget')}
              </span>
            </div>
          </div>
        </div>

        {/* Variance Table */}
        <div className="overflow-x-auto rounded-lg border border-slate-800">
          <table className="w-full text-sm">
            <thead className="bg-slate-950">
              <tr>
                <th className="text-left py-3 px-4 font-semibold text-slate-400">{t('budgets.account')}</th>
                <th className="text-left py-3 px-4 font-semibold text-slate-400">{t('budgets.account')}</th>
                <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.budgeted')}</th>
                <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.actual')}</th>
                <th className="text-right py-3 px-4 font-semibold text-slate-400">{t('budgets.variance')}</th>
                <th className="text-right py-3 px-4 font-semibold text-slate-400">%</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {filteredData.map((item) => (
                <tr key={item.account_number} className="hover:bg-slate-800/60 transition-colors">
                  <td className="py-3 px-4 font-medium text-slate-200">{item.account_number}</td>
                  <td className="py-3 px-4 text-slate-300">{item.account_name}</td>
                  <td className="py-3 px-4 text-right text-slate-200">
                    ${(item.ytd_budget / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                  </td>
                  <td className="py-3 px-4 text-right text-slate-200">
                    ${(item.ytd_actual / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                  </td>
                  <td className={`py-3 px-4 text-right font-medium ${item.ytd_variance > 0 ? 'text-red-400' : 'text-green-400'}`}>
                    ${(item.ytd_variance / 100).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                  </td>
                  <td className={`py-3 px-4 text-right font-medium ${item.ytd_variance > 0 ? 'text-red-400' : 'text-green-400'}`}>
                    {item.ytd_variance_percent.toFixed(1)}%
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {filteredData.length === 0 && (
          <div className="text-center py-8 text-slate-500">
            <p>{t('budgets.reports.noDataWithFilters')}</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

import React, { useState, useEffect } from 'react';
import {
  BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import {
  Users,
  DollarSign,
  TrendingUp,
  Clock,
  Award,
  Zap,
  Activity,
  ArrowUpRight,
  ArrowDownRight,
  Target,
  Users2
} from 'lucide-react';
import { getCustomers, getInvoices } from '@/database/simple-db';
import { useLocale } from '../../i18n/useLocale';

interface CustomerStats {
  totalCustomers: number;
  newThisMonth: number;
  totalRevenue: number;
  averageOrderValue: number;
  totalAR: number;
  overdueAR: number;
}

interface TopCustomer {
  id: number;
  name: string;
  revenue: number;
  invoiceCount: number;
  averageOrder: number;
}

interface ARAgingBucket {
  range: string;
  amount: number;
  count: number;
  color: string;
}

export const CustomerDashboard: React.FC = () => {
  const { t } = useLocale();
  const [stats, setStats] = useState<CustomerStats>({
    totalCustomers: 0,
    newThisMonth: 0,
    totalRevenue: 0,
    averageOrderValue: 0,
    totalAR: 0,
    overdueAR: 0
  });
  const [topCustomers, setTopCustomers] = useState<TopCustomer[]>([]);
  const [arAging, setArAging] = useState<ARAgingBucket[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCustomerData();
  }, []);

  const loadCustomerData = () => {
    try {
      setLoading(true);
      const customers = getCustomers();
      const invoices = getInvoices();
      const now = new Date();
      const firstDayOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

      const newCustomers = customers.filter(c => new Date(c.created_at) >= firstDayOfMonth);
      let totalRevenue = 0;
      let overdueAR = 0;

      const unpaidInvoices = invoices.filter(inv => inv.status !== 'paid' && inv.status !== 'cancelled');
      unpaidInvoices.forEach(inv => {
        if (inv.due_date && new Date(inv.due_date) < now) {
          overdueAR += inv.total_amount;
        }
      });

      invoices.forEach(inv => totalRevenue += inv.total_amount);
      const totalAR = unpaidInvoices.reduce((sum, inv) => sum + inv.total_amount, 0);

      setStats({
        totalCustomers: customers.length,
        newThisMonth: newCustomers.length,
        totalRevenue,
        averageOrderValue: invoices.length > 0 ? totalRevenue / invoices.length : 0,
        totalAR,
        overdueAR
      });

      const customerRevenue: Record<number, { name: string; revenue: number; count: number }> = {};
      invoices.forEach(inv => {
        if (!customerRevenue[inv.customer_id]) {
          const customer = customers.find(c => c.id === inv.customer_id);
          customerRevenue[inv.customer_id] = { name: customer?.name || t('customerDashboard.unknownCustomer'), revenue: 0, count: 0 };
        }
        customerRevenue[inv.customer_id].revenue += inv.total_amount;
        customerRevenue[inv.customer_id].count += 1;
      });

      setTopCustomers(Object.entries(customerRevenue)
        .map(([id, data]) => ({
          id: Number(id),
          name: data.name,
          revenue: data.revenue,
          invoiceCount: data.count,
          averageOrder: data.revenue / data.count
        }))
        .sort((a, b) => b.revenue - a.revenue)
        .slice(0, 10));

      const aging: ARAgingBucket[] = [
        { range: t('customerDashboard.aging.current'), amount: 0, count: 0, color: '#3b82f6' },
        { range: t('customerDashboard.aging.31-60'), amount: 0, count: 0, color: '#f59e0b' },
        { range: t('customerDashboard.aging.61-90'), amount: 0, count: 0, color: '#ef4444' },
        { range: t('customerDashboard.aging.90+'), amount: 0, count: 0, color: '#7f1d1d' }
      ];

      unpaidInvoices.forEach(inv => {
        if (inv.due_date) {
          const daysOverdue = Math.floor((now.getTime() - new Date(inv.due_date).getTime()) / (1000 * 60 * 60 * 24));
          if (daysOverdue <= 30) { aging[0].amount += inv.total_amount; aging[0].count++; }
          else if (daysOverdue <= 60) { aging[1].amount += inv.total_amount; aging[1].count++; }
          else if (daysOverdue <= 90) { aging[2].amount += inv.total_amount; aging[2].count++; }
          else { aging[3].amount += inv.total_amount; aging[3].count++; }
        }
      });
      setArAging(aging);
    } catch (error) {
      console.error('Error loading customer data:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-screen bg-slate-950">
      <div className="w-16 h-16 border-4 border-blue-600/20 border-t-emerald-500 rounded-full animate-spin mb-6"></div>
      <span className="text-xs font-black text-slate-500 uppercase tracking-[0.4em] animate-pulse">{t('customerDashboard.syncing')}</span>
    </div>
  );

  return (
    <div className="elite-page-container pb-20">
      {/* Header Hub */}
      <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-emerald-600/10 rounded-2.5xl border border-emerald-500/20 shadow-emerald-900/10 shadow-lg">
            <Users2 className="w-10 h-10 text-emerald-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none uppercase">{t('customerDashboard.title')}</h1>
            <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2 uppercase">
              <Zap className="w-3.5 h-3.5 text-emerald-500 animate-pulse" /> {t('customerDashboard.subtitle')}
            </p>
          </div>
        </div>
      </div>

      {/* Stats Matrix */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        <EliteStatCard title={t('customerDashboard.totalPortfolio')} value={stats.totalCustomers.toString()} label={t('customerDashboard.newThisMonth', { count: stats.newThisMonth })} icon={Users} color="blue" />
        <EliteStatCard title={t('customerDashboard.grossRevenue')} value={formatCurrency(stats.totalRevenue)} label={`${t('customerDashboard.avgTicket')}: ${formatCurrency(stats.averageOrderValue)}`} icon={DollarSign} color="emerald" />
        <EliteStatCard title={t('customerDashboard.receivables')} value={formatCurrency(stats.totalAR)} label={`${((stats.totalAR / stats.totalRevenue) * 100).toFixed(1)}% ${t('customerDashboard.ofIncome')}`} icon={Clock} color="amber" />
        <EliteStatCard title={t('customerDashboard.overdueAR')} value={formatCurrency(stats.overdueAR)} label={`${((stats.overdueAR / stats.totalAR) * 100).toFixed(1)}% ${t('customerDashboard.atRisk')}`} icon={TrendingUp} color="rose" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-10">
        {/* Top Customers Vertical Chart */}
        <AnalysisBox title={t('customerDashboard.portfolioLeaders')} subtitle={t('customerDashboard.top10Volume')}>
          <ResponsiveContainer width="100%" height={400}>
            <BarChart data={topCustomers} layout="vertical" margin={{ right: 40, left: 20 }}>
              <defs>
                <linearGradient id="barCustomer" x1="0" y1="0" x2="1" y2="0">
                  <stop offset="0%" stopColor="#10b981" stopOpacity={0.8} />
                  <stop offset="100%" stopColor="#10b981" stopOpacity={0.2} />
                </linearGradient>
              </defs>
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" stroke="#475569" fontSize={10} fontWeight="900" width={140} axisLine={false} tickLine={false} />
              <Tooltip
                cursor={{ fill: 'rgba(255,255,255,0.02)' }}
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem' }}
                itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: '900' }}
                formatter={(v: any) => formatCurrency(v)}
              />
              <Bar dataKey="revenue" fill="url(#barCustomer)" radius={[0, 8, 8, 0]} barSize={26} />
            </BarChart>
          </ResponsiveContainer>
        </AnalysisBox>

        {/* AR Aging Pie */}
        <AnalysisBox title={t('customerDashboard.debtAging')} subtitle={t('customerDashboard.pendingDistribution')}>
          <div className="flex flex-col lg:flex-row items-center justify-center gap-10 h-full">
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={arAging}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={110}
                  paddingAngle={10}
                  dataKey="amount"
                  stroke="none"
                >
                  {arAging.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} opacity={0.8} />
                  ))}
                </Pie>
                <Tooltip
                  contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1rem' }}
                  itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: '900' }}
                />
              </PieChart>
            </ResponsiveContainer>

            <div className="space-y-4 min-w-[200px]">
              {arAging.map((bucket, idx) => (
                <div key={idx} className="flex flex-col">
                  <div className="flex items-center justify-between mb-1">
                    <div className="flex items-center gap-2">
                      <div className="w-2 h-2 rounded-full" style={{ backgroundColor: bucket.color }}></div>
                      <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{bucket.range}</span>
                    </div>
                    <span className="text-[10px] font-black text-white font-mono">{formatCurrency(bucket.amount)}</span>
                  </div>
                  <div className="w-full h-1 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                    <div className="h-full opacity-50" style={{ width: `${(bucket.amount / stats.totalAR * 100) || 0}%`, backgroundColor: bucket.color }}></div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </AnalysisBox>
      </div>

      {/* Detailed Matrix Mapping */}
      <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl overflow-hidden relative group">
        <div className="absolute top-0 right-0 w-64 h-64 bg-slate-700/5 blur-[100px] pointer-events-none"></div>
        <header className="flex items-center justify-between mb-12">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-blue-600/10 rounded-xl flex items-center justify-center border border-blue-500/20">
              <Target className="w-5 h-5 text-blue-500" />
            </div>
            <div>
              <h3 className="text-lg font-black text-white tracking-tight leading-none">{t('customerDashboard.eliteMapping')}</h3>
              <p className="text-xs text-slate-500 font-medium mt-1">{t('customerDashboard.performanceDetail')}</p>
            </div>
          </div>
        </header>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-950/50">
              <tr>
                {[t('customerDashboard.ranking'), t('customerDashboard.legalName'), t('customerDashboard.totalRevenue'), t('customerDashboard.invoices'), t('customerDashboard.average'), t('customerDashboard.impact')].map(h => (
                  <th key={h} className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {topCustomers.map((customer, idx) => (
                <tr key={customer.id} className="hover:bg-white/[0.02] transition-colors group/row">
                  <td className="px-8 py-5">
                    <span className="w-6 h-6 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center text-[10px] font-black text-slate-500 group-hover/row:border-blue-500 group-hover/row:text-white transition-all">{idx + 1}</span>
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex flex-col">
                      <span className="text-sm font-black text-white leading-none">{customer.name}</span>
                      <span className="text-[9px] font-black text-blue-500 uppercase tracking-widest mt-1.5 opacity-60">ID: CUX-{customer.id.toString().padStart(4, '0')}</span>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-sm font-mono font-black text-emerald-400 group-hover/row:scale-105 transition-transform origin-left">{formatCurrency(customer.revenue)}</td>
                  <td className="px-8 py-5 text-sm font-black text-slate-300 font-mono italic">{customer.invoiceCount}</td>
                  <td className="px-8 py-5 text-sm font-mono text-slate-500">{formatCurrency(customer.averageOrder)}</td>
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="flex-1 h-1.5 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                        <div className="h-full bg-blue-600 shadow-[0_0_10px_rgba(59,130,246,0.3)] transition-all duration-1000" style={{ width: `${(customer.revenue / stats.totalRevenue * 100) || 0}%` }}></div>
                      </div>
                      <span className="text-[10px] font-black text-slate-500 w-10 text-right">{((customer.revenue / stats.totalRevenue) * 100).toFixed(1)}%</span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const EliteStatCard = ({ title, value, icon: Icon, color, label }: any) => {
  const themes: any = {
    blue: 'text-blue-500 bg-blue-600/10 border-blue-500/20 shadow-blue-900/10',
    emerald: 'text-emerald-500 bg-emerald-600/10 border-emerald-500/20 shadow-emerald-900/10',
    rose: 'text-rose-500 bg-rose-600/10 border-rose-500/20 shadow-rose-900/10',
    amber: 'text-amber-500 bg-amber-600/10 border-amber-500/20 shadow-amber-900/10',
  };

  return (
    <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] shadow-2xl group hover:-translate-y-1 transition-all relative overflow-hidden">
      <div className="relative z-10">
        <div className="flex items-center justify-between mb-8">
          <div className={`p-3 rounded-2xl border ${themes[color]} group-hover:scale-110 transition-transform`}>
            <Icon className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{title}</span>
        </div>
        <div className="text-2xl font-black text-white tracking-tight mb-2 font-mono tabular-nums leading-none">{value}</div>
        <p className="text-[9px] font-black text-slate-600 uppercase tracking-[0.2em]">{label}</p>
      </div>
      <div className={`absolute -right-4 -bottom-4 w-24 h-24 blur-3xl opacity-0 group-hover:opacity-10 transition-all ${themes[color]}`}></div>
    </div>
  );
};

const AnalysisBox = ({ title, subtitle, children }: any) => (
  <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl relative group overflow-hidden">
    <div className="absolute top-0 left-0 w-64 h-64 bg-white/5 blur-[100px] pointer-events-none"></div>
    <header className="mb-10 relative z-10">
      <h3 className="text-lg font-black text-white tracking-tight">{title}</h3>
      <p className="text-xs text-slate-500 font-medium mt-1">{subtitle}</p>
    </header>
    <div className="relative z-10 h-[300px] flex items-center justify-center">
      {children}
    </div>
  </div>
);

import React, { useState, useEffect } from 'react';
import {
  LineChart, Line, BarChart, Bar,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, AreaChart, Area
} from 'recharts';
import {
  TrendingUp,
  TrendingDown,
  DollarSign,
  PieChart as PieChartIcon,
  Activity,
  Calendar,
  Zap,
  ArrowUpRight,
  ArrowDownRight,
  Filter,
  Download,
  Maximize2
} from 'lucide-react';
import { getMonthlyFinancialSummary } from '@/database/simple-db';
import { Button } from '../ui/button';
import { useLocale } from '../../i18n/useLocale';

export const FinancialDashboard: React.FC = () => {
  const { t } = useLocale();
  const [monthlyData, setMonthlyData] = useState<any[]>([]);
  const [selectedPeriod, setSelectedPeriod] = useState<'6m' | '12m' | 'ytd'>('12m');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadFinancialData();
  }, [selectedPeriod]);

  const loadFinancialData = () => {
    try {
      setLoading(true);
      const data = getMonthlyFinancialSummary();
      const formattedData = data.map(item => ({
        month: getMonthName(item.month),
        ingresos: item.revenue,
        gastos: item.expenses,
        utilidad: item.revenue - item.expenses,
        margen: item.revenue > 0 ? ((item.revenue - item.expenses) / item.revenue * 100).toFixed(1) : 0
      }));

      let filteredData = formattedData;
      if (selectedPeriod === '6m') filteredData = formattedData.slice(-6);
      else if (selectedPeriod === 'ytd') filteredData = formattedData.slice(0, new Date().getMonth() + 1);

      setMonthlyData(filteredData);
    } catch (error) {
      console.error('Error loading financial data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getMonthName = (monthNum: string): string => {
    const months = [
      t('financialDashboard.months.jan'),
      t('financialDashboard.months.feb'),
      t('financialDashboard.months.mar'),
      t('financialDashboard.months.abr'),
      t('financialDashboard.months.may'),
      t('financialDashboard.months.jun'),
      t('financialDashboard.months.jul'),
      t('financialDashboard.months.ago'),
      t('financialDashboard.months.sep'),
      t('financialDashboard.months.oct'),
      t('financialDashboard.months.nov'),
      t('financialDashboard.months.dic')
    ];
    return months[parseInt(monthNum) - 1] || monthNum;
  };

  const calculateKPIs = () => {
    if (monthlyData.length < 2) return { totalRevenue: 0, totalExpenses: 0, netProfit: 0, profitMargin: 0, revenueChange: 0, expenseChange: 0, profitChange: 0 };
    const currentMonth = monthlyData[monthlyData.length - 1];
    const previousMonth = monthlyData[monthlyData.length - 2];
    const totalRevenue = monthlyData.reduce((sum, m) => sum + m.ingresos, 0);
    const totalExpenses = monthlyData.reduce((sum, m) => sum + m.gastos, 0);
    const netProfit = totalRevenue - totalExpenses;
    const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue * 100) : 0;
    const revenueChange = previousMonth.ingresos > 0 ? ((currentMonth.ingresos - previousMonth.ingresos) / previousMonth.ingresos * 100) : 0;
    const expenseChange = previousMonth.gastos > 0 ? ((currentMonth.gastos - previousMonth.gastos) / previousMonth.gastos * 100) : 0;
    const profitChange = previousMonth.utilidad > 0 ? ((currentMonth.utilidad - previousMonth.utilidad) / previousMonth.utilidad * 100) : 0;
    return { totalRevenue, totalExpenses, netProfit, profitMargin, revenueChange, expenseChange, profitChange };
  };

  const kpis = calculateKPIs();
  const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-slate-950">
        <div className="w-16 h-16 border-4 border-blue-600/20 border-t-blue-500 rounded-full animate-spin mb-6 shadow-[0_0_20px_rgba(59,130,246,0.3)]"></div>
        <span className="text-xs font-black text-slate-500 uppercase tracking-[0.4em] animate-pulse">{t('financialDashboard.syncing')}</span>
      </div>
    );
  }

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      {/* Header Hub */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight leading-none uppercase">
            <Activity className="w-8 h-8 text-indigo-500" />
            {t('financialDashboard.title')}
          </h1>
          <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2 uppercase">
            <Zap className="w-3.5 h-3.5 text-indigo-500 animate-pulse" /> {t('financialDashboard.subtitle')}
          </p>
        </div>

        {/* Control Hub */}
        <div className="flex items-center gap-4">
          <div className="flex gap-2 p-1.5 bg-slate-950/40 border border-slate-800/50 rounded-2xl">
            {(['6m', 'ytd', '12m'] as const).map((period) => (
              <button
                key={period}
                onClick={() => setSelectedPeriod(period)}
                className={`px-6 py-2 rounded-xl text-[9px] font-bold uppercase tracking-widest transition-all ${selectedPeriod === period
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/40'
                  : 'text-slate-500 hover:text-slate-300'
                  }`}
              >
                {t(`financialDashboard.periods.${period}`)}
              </button>
            ))}
          </div>
          <Button variant="outline" className="h-10 w-10 rounded-xl border-slate-800 bg-slate-900/50 hover:bg-slate-800 text-slate-400">
            <Filter className="w-3.5 h-3.5" />
          </Button>
          <Button className="h-10 px-6 rounded-xl bg-slate-900/50 border border-slate-800 hover:bg-slate-800 text-white font-bold uppercase tracking-widest text-[9px] gap-2">
            <Download className="w-3.5 h-3.5" /> {t('financialDashboard.export')}
          </Button>
        </div>
      </div>

      {/* KPI Cards Matrix */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        <PremiumKPICard title={t('financialDashboard.revenue')} value={formatCurrency(kpis.totalRevenue)} change={kpis.revenueChange} icon={DollarSign} color="blue" />
        <PremiumKPICard title={t('financialDashboard.operating')} value={formatCurrency(kpis.totalExpenses)} change={kpis.expenseChange} icon={TrendingDown} color="rose" inverse />
        <PremiumKPICard title={t('financialDashboard.profit')} value={formatCurrency(kpis.netProfit)} change={kpis.profitChange} icon={TrendingUp} color="emerald" />
        <PremiumKPICard title={t('financialDashboard.margin')} value={`${kpis.profitMargin.toFixed(1)}%`} change={kpis.profitChange} icon={PieChartIcon} color="amber" />
      </div>

      {/* Main Analysis Hub */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-10">
        <AnalysisBox title={t('financialDashboard.incomeVsExpenses')} subtitle={t('financialDashboard.monthlyCashFlow')}>
          <ResponsiveContainer width="100%" height={350}>
            <BarChart data={monthlyData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="barRev" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#3b82f6" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0.1} />
                </linearGradient>
                <linearGradient id="barExp" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#ef4444" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#ef4444" stopOpacity={0.1} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
              <XAxis dataKey="month" stroke="#475569" fontSize={10} fontWeight="900" axisLine={false} tickLine={false} dy={10} />
              <YAxis stroke="#475569" fontSize={10} fontWeight="900" axisLine={false} tickLine={false} tickFormatter={(v) => `$${v / 1000}k`} />
              <Tooltip
                cursor={{ fill: 'rgba(255,255,255,0.03)' }}
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)' }}
                itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: '900', textTransform: 'uppercase' }}
              />
              <Bar dataKey="ingresos" fill="url(#barRev)" name={t('financialDashboard.revenueLabel')} radius={[6, 6, 0, 0]} barSize={24} />
              <Bar dataKey="gastos" fill="url(#barExp)" name={t('financialDashboard.expensesLabel')} radius={[6, 6, 0, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </AnalysisBox>

        <AnalysisBox title={t('financialDashboard.profitTrend')} subtitle={t('financialDashboard.profitMarginPerformance')}>
          <ResponsiveContainer width="100%" height={350}>
            <AreaChart data={monthlyData}>
              <defs>
                <linearGradient id="areaUtil" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                  <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
              <XAxis dataKey="month" stroke="#475569" fontSize={10} fontWeight="900" axisLine={false} tickLine={false} dy={10} />
              <YAxis stroke="#475569" fontSize={10} fontWeight="900" axisLine={false} tickLine={false} tickFormatter={(v) => `$${v / 1000}k`} />
              <Tooltip
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem' }}
                itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: '900' }}
              />
              <Area type="monotone" dataKey="utilidad" stroke="#10b981" strokeWidth={4} fill="url(#areaUtil)" name={t('financialDashboard.profitLabel')} />
            </AreaChart>
          </ResponsiveContainer>
        </AnalysisBox>
      </div>

      {/* Summary Matrix */}
      <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl overflow-hidden relative group">
        <div className="absolute top-0 right-0 w-64 h-64 bg-slate-700/5 blur-[100px] pointer-events-none"></div>
        <header className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-xl font-black text-white tracking-tighter uppercase">{t('financialDashboard.monthlyAuditLog')}</h3>
            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-1">{t('financialDashboard.historicalSync')}</p>
          </div>
          <button className="p-3 bg-slate-950 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-colors">
            <Maximize2 className="w-4 h-4 text-slate-500" />
          </button>
        </header>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-950/50">
              <tr>
                {[t('financialDashboard.months.jan'), t('financialDashboard.revenueLabel'), t('financialDashboard.expensesLabel'), t('financialDashboard.profitLabel'), t('financialDashboard.margin') + ' %'].map(h => (
                  <th key={h} className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {monthlyData.map((row, idx) => (
                <tr key={idx} className="hover:bg-white/[0.02] transition-colors group/row">
                  <td className="px-8 py-5 text-sm font-black text-white">{row.month}</td>
                  <td className="px-8 py-5 text-sm font-mono text-slate-400">${row.ingresos.toLocaleString()}</td>
                  <td className="px-8 py-5 text-sm font-mono text-slate-400">${row.gastos.toLocaleString()}</td>
                  <td className={`px-8 py-5 text-sm font-black font-mono ${row.utilidad >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {formatCurrency(row.utilidad)}
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="flex-1 h-1.5 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                        <div className="h-full bg-indigo-600 shadow-[0_0_10px_rgba(79,70,229,0.3)] transition-all duration-1000" style={{ width: `${Math.max(0, row.margen)}%` }}></div>
                      </div>
                      <span className="text-[10px] font-black text-slate-300 w-10">{row.margen}%</span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const PremiumKPICard = ({ title, value, change, icon: Icon, color, inverse }: any) => {
  const isPositive = change >= 0;
  const isGood = inverse ? !isPositive : isPositive;

  const themes: any = {
    blue: 'text-blue-500 bg-blue-500/10 border-blue-500/20 shadow-blue-900/10',
    rose: 'text-rose-500 bg-rose-500/10 border-rose-500/20 shadow-rose-900/10',
    emerald: 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20 shadow-emerald-900/10',
    amber: 'text-amber-500 bg-amber-500/10 border-amber-500/20 shadow-amber-900/10',
  };

  return (
    <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden group hover:border-slate-700 transition-all">
      <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 blur-[50px] -mr-16 -mt-16 group-hover:bg-white/10 transition-all duration-700"></div>

      <div className="relative z-10">
        <div className="flex items-start justify-between mb-8">
          <div className={`p-4 rounded-2.5xl border ${themes[color]} group-hover:scale-110 transition-transform duration-500`}>
            <Icon className="w-7 h-7" />
          </div>
          <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl border text-[10px] font-black uppercase ${isGood ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
            }`}>
            {isPositive ? <ArrowUpRight className="w-3.5 h-3.5" /> : <ArrowDownRight className="w-3.5 h-3.5" />}
            {Math.abs(change).toFixed(1)}%
          </div>
        </div>

        <div>
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 block">{title}</span>
          <div className="text-3xl font-bold text-white tracking-tight font-mono tabular-nums leading-none mb-4">{value}</div>
          <div className="w-full h-1 bg-slate-950 rounded-full border border-slate-800">
            <div className={`h-full rounded-full ${isGood ? 'bg-emerald-500/50' : 'bg-rose-500/50'}`} style={{ width: '65%' }}></div>
          </div>
        </div>
      </div>
    </div>
  );
};

const AnalysisBox = ({ title, subtitle, children }: any) => (
  <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl relative group overflow-hidden">
    <div className="absolute top-0 left-0 w-64 h-64 bg-white/5 blur-[100px] pointer-events-none"></div>
    <header className="mb-10 relative z-10">
      <h3 className="text-lg font-bold text-white tracking-tight">{title}</h3>
      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">{subtitle}</p>
    </header>
    <div className="relative z-10">
      {children}
    </div>
  </div>
);

import React, { useState, useEffect } from 'react';
import {
  BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import {
  Package,
  AlertTriangle,
  TrendingUp,
  DollarSign,
  ShoppingCart,
  Archive,
  Zap,
  Activity,
  Boxes,
  ArrowRight,
  ChevronRight,
  ShieldCheck,
  Maximize2
} from 'lucide-react';
import { getProducts, getInvoices } from '@/database/simple-db';
import { useLocale } from '../../i18n/useLocale';

interface InventoryStats {
  totalProducts: number;
  totalValue: number;
  lowStockCount: number;
  outOfStockCount: number;
  averageValue: number;
}

interface LowStockProduct {
  id: number;
  name: string;
  sku: string;
  stock: number;
  min_stock: number;
  price: number;
  category: string;
}

interface TopProduct {
  name: string;
  quantity: number;
  revenue: number;
}

export const InventoryDashboard: React.FC = () => {
  const { t } = useLocale();
  const [stats, setStats] = useState<InventoryStats>({
    totalProducts: 0,
    totalValue: 0,
    lowStockCount: 0,
    outOfStockCount: 0,
    averageValue: 0
  });
  const [lowStockProducts, setLowStockProducts] = useState<LowStockProduct[]>([]);
  const [topProducts, setTopProducts] = useState<TopProduct[]>([]);
  const [categoryDistribution, setCategoryDistribution] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadInventoryData();
  }, []);

  const loadInventoryData = () => {
    try {
      setLoading(true);
      const products = getProducts();
      const invoices = getInvoices();

      const totalValue = products.reduce((sum, p) => sum + (p.stock_quantity * p.price), 0);
      const lowStock = products.filter(p => p.stock_quantity <= (p.min_stock_level || 10));
      const outOfStock = products.filter(p => p.stock_quantity === 0);

      setStats({
        totalProducts: products.length,
        totalValue,
        lowStockCount: lowStock.length,
        outOfStockCount: outOfStock.length,
        averageValue: products.length > 0 ? totalValue / products.length : 0
      });

      setLowStockProducts(lowStock.slice(0, 10).map(p => ({
        id: p.id,
        name: p.name,
        sku: p.sku,
        stock: p.stock_quantity,
        min_stock: p.min_stock_level || 10,
        price: p.price,
        category: p.category?.name || t('inventoryDashboard.uncategorized')
      })));

      const productSales: Record<number, { name: string; quantity: number; revenue: number }> = {};
      invoices.forEach(invoice => {
        if (invoice.items && Array.isArray(invoice.items)) {
          invoice.items.forEach((item: any) => {
            if (!productSales[item.product_id]) {
              productSales[item.product_id] = { name: item.product_name || t('inventoryDashboard.product'), quantity: 0, revenue: 0 };
            }
            productSales[item.product_id].quantity += item.quantity;
            productSales[item.product_id].revenue += item.quantity * item.unit_price;
          });
        }
      });

      setTopProducts(Object.values(productSales).sort((a, b) => b.quantity - a.quantity).slice(0, 10));

      const categoryMap: Record<string, { value: number; count: number }> = {};
      products.forEach(p => {
        const catName = p.category?.name || t('inventoryDashboard.uncategorized') || 'Uncategorized';
        if (!categoryMap[catName]) categoryMap[catName] = { value: 0, count: 0 };
        categoryMap[catName].value += p.stock_quantity * p.price;
        categoryMap[catName].count++;
      });

      setCategoryDistribution(Object.entries(categoryMap)
        .map(([name, data]) => ({ name, value: data.value, count: data.count }))
        .sort((a, b) => b.value - a.value).slice(0, 8));
    } catch (error) {
      console.error('Error loading inventory data:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;
  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#14b8a6', '#f97316'];

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-screen bg-slate-950">
      <div className="w-16 h-16 border-4 border-blue-600/20 border-t-amber-500 rounded-full animate-spin mb-6"></div>
      <span className="text-xs font-black text-slate-500 uppercase tracking-[0.4em] animate-pulse">{t('inventoryDashboard.scanning')}</span>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      {/* Header Hub */}
      <div className="mb-8 border-b border-slate-800 pb-6">
        <div className="flex items-center gap-4">
          <div className="p-3.5 bg-slate-900/50 rounded-xl border border-white/5 shadow-2xl backdrop-blur-xl group">
            <Boxes className="w-7 h-7 text-amber-500 group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none uppercase">
              {t('inventoryDashboard.title')}
            </h1>
            <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2 uppercase">
              <Zap className="w-3.5 h-3.5 text-amber-500 animate-pulse" /> {t('inventoryDashboard.subtitle')}
            </p>
          </div>
        </div>
      </div>

      {/* Stats Matrix */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        <EliteStatCard title={t('inventoryDashboard.totalProducts')} value={stats.totalProducts.toString()} label={t('inventoryDashboard.skusInWarehouse')} icon={Package} color="blue" />
        <EliteStatCard title={t('inventoryDashboard.accumulatedValue')} value={formatCurrency(stats.totalValue)} label={`${t('inventoryDashboard.avg')}: ${formatCurrency(stats.averageValue)}`} icon={DollarSign} color="emerald" />
        <EliteStatCard title={t('inventoryDashboard.criticalStock')} value={stats.lowStockCount.toString()} label={t('inventoryDashboard.requireReorder')} icon={AlertTriangle} color="amber" />
        <EliteStatCard title={t('inventoryDashboard.stockOut')} value={stats.outOfStockCount.toString()} label={t('inventoryDashboard.outOfStockProducts')} icon={Archive} color="rose" />
      </div>

      {/* Critical Stock Alert - Protocol Red */}
      {lowStockProducts.length > 0 && (
        <div className="bg-slate-900 border-2 border-amber-500/30 rounded-[3rem] p-10 relative overflow-hidden shadow-2xl shadow-amber-900/10 group">
          <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/5 blur-[100px] pointer-events-none"></div>
          <div className="flex items-center justify-between mb-10 relative z-10">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-amber-500/10 rounded-xl border border-amber-500/20 animate-pulse">
                <AlertTriangle className="w-6 h-6 text-amber-500" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-white tracking-tighter uppercase">{t('inventoryDashboard.replenishmentProtocol')}</h3>
                <p className="text-[10px] text-amber-500 font-black uppercase tracking-widest mt-1.5 opacity-80">
                  {t('inventoryDashboard.imminentOutageAlert', { count: lowStockProducts.length })}
                </p>
              </div>
            </div>
            <button className="flex items-center gap-2 px-6 py-3 bg-amber-600 hover:bg-amber-500 text-white rounded-xl font-black uppercase tracking-widest text-[10px] transition-all shadow-lg shadow-amber-950/40 active:scale-95">
              {t('inventoryDashboard.generatePurchaseOrders')} <ArrowRight className="w-4 h-4" />
            </button>
          </div>

          <div className="overflow-x-auto relative z-10">
            <table className="w-full text-left">
              <thead className="bg-slate-950/50">
                <tr>
                  {[t('inventoryDashboard.skuCode'), t('inventoryDashboard.productName'), t('inventoryDashboard.category'), t('inventoryDashboard.current'), t('inventoryDashboard.minimum'), t('inventoryDashboard.deficit')].map(h => (
                    <th key={h} className="px-6 py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/50">
                {lowStockProducts.map((p) => (
                  <tr key={p.id} className="hover:bg-amber-500/[0.03] transition-colors group/row">
                    <td className="px-6 py-4 text-xs font-mono font-black text-amber-500 group-hover/row:scale-105 transition-transform origin-left">{p.sku}</td>
                    <td className="px-6 py-4 text-sm font-black text-white">{p.name}</td>
                    <td className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase">{p.category}</td>
                    <td className="px-6 py-4 text-sm font-black text-amber-400 font-mono italic">{p.stock}</td>
                    <td className="px-6 py-4 text-sm font-black text-slate-600 font-mono">{p.min_stock}</td>
                    <td className="px-6 py-4">
                      <span className="px-3 py-1.5 bg-rose-500/10 border border-rose-500/20 text-rose-400 text-[10px] font-black rounded-lg shadow-sm">
                        -{Math.max(p.min_stock * 2 - p.stock, 0)} UNID
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Analysis Matrix */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-10">
        <AnalysisBox title={t('inventoryDashboard.movementVelocity')} subtitle={t('inventoryDashboard.top10Rotation')}>
          <ResponsiveContainer width="100%" height={350}>
            <BarChart data={topProducts} layout="vertical" margin={{ right: 40, left: 20 }}>
              <defs>
                <linearGradient id="barRotation" x1="0" y1="0" x2="1" y2="0">
                  <stop offset="0%" stopColor="#3b82f6" stopOpacity={0.8} />
                  <stop offset="100%" stopColor="#3b82f6" stopOpacity={0.2} />
                </linearGradient>
              </defs>
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" stroke="#475569" fontSize={10} fontWeight="900" width={140} axisLine={false} tickLine={false} />
              <Tooltip
                cursor={{ fill: 'rgba(59,130,246,0.03)' }}
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem' }}
                itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: '900' }}
              />
              <Bar dataKey="quantity" fill="url(#barRotation)" radius={[0, 8, 8, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </AnalysisBox>

        <AnalysisBox title={t('inventoryDashboard.capitalByCategory')} subtitle={t('inventoryDashboard.monetaryValueDistribution')}>
          <div className="flex flex-col lg:flex-row items-center justify-center gap-10 h-full w-full px-6">
            <ResponsiveContainer width="100%" height={280}>
              <PieChart>
                <Pie
                  data={categoryDistribution}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                  stroke="none"
                >
                  {categoryDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} opacity={0.85} />
                  ))}
                </Pie>
                <Tooltip
                  contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1rem' }}
                  itemStyle={{ color: '#fff', fontSize: '10px', fontWeight: '900' }}
                  formatter={(v: any) => formatCurrency(v)}
                />
              </PieChart>
            </ResponsiveContainer>

            <div className="space-y-3 min-w-[200px] w-full lg:w-auto">
              {categoryDistribution.map((cat, idx) => (
                <div key={idx} className="flex flex-col group/cat cursor-default">
                  <div className="flex items-center justify-between mb-1">
                    <div className="flex items-center gap-2">
                      <div className="w-2 h-2 rounded-full shadow-[0_0_8px_currentColor]" style={{ backgroundColor: COLORS[idx % COLORS.length], color: COLORS[idx % COLORS.length] }}></div>
                      <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest group-hover/cat:text-white transition-colors">{cat.name}</span>
                    </div>
                    <span className="text-[10px] font-black text-white font-mono opacity-80">{formatCurrency(cat.value)}</span>
                  </div>
                  <div className="w-full h-1 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                    <div className="h-full opacity-60" style={{ width: `${(cat.value / stats.totalValue * 100) || 0}%`, backgroundColor: COLORS[idx % COLORS.length] }}></div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </AnalysisBox>
      </div>

      <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl relative overflow-hidden group">
        <header className="flex items-center justify-between mb-12 relative z-10">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-emerald-600/10 rounded-xl flex items-center justify-center border border-emerald-500/20">
              <ShieldCheck className="w-5 h-5 text-emerald-500" />
            </div>
            <div>
              <h3 className="text-xl font-black text-white tracking-tighter uppercase leading-none">{t('inventoryDashboard.valuationCertification')}</h3>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-2">{t('inventoryDashboard.abcInventory')}</p>
            </div>
          </div>
          <button className="p-3 bg-slate-950 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-all text-slate-600 hover:text-white">
            <Maximize2 className="w-4 h-4" />
          </button>
        </header>

        <div className="overflow-x-auto relative z-10">
          <table className="w-full text-left">
            <thead className="bg-slate-950/50">
              <tr>
                {['#', t('inventoryDashboard.productId'), t('inventoryDashboard.totalRevenue'), t('inventoryDashboard.qtySold'), t('inventoryDashboard.avgTicket')].map(h => (
                  <th key={h} className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {topProducts.map((p, idx) => (
                <tr key={idx} className="hover:bg-white/[0.02] transition-colors group/row">
                  <td className="px-8 py-5">
                    <span className="w-6 h-6 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center text-[10px] font-black text-slate-500 group-hover/row:text-emerald-400 group-hover/row:border-emerald-500/30 transition-all">{idx + 1}</span>
                  </td>
                  <td className="px-8 py-5 text-sm font-black text-white group-hover/row:translate-x-1 transition-transform">{p.name}</td>
                  <td className="px-8 py-5 text-sm font-mono font-black text-emerald-400">{formatCurrency(p.revenue)}</td>
                  <td className="px-8 py-5 text-sm font-black text-slate-300 font-mono italic">{p.quantity.toLocaleString()}</td>
                  <td className="px-8 py-5 text-sm font-mono text-slate-500">{formatCurrency(p.revenue / p.quantity)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const EliteStatCard = ({ title, value, icon: Icon, color, label }: any) => {
  const themes: any = {
    blue: 'text-blue-500 bg-blue-600/10 border-blue-500/20 shadow-blue-900/10',
    emerald: 'text-emerald-500 bg-emerald-600/10 border-emerald-500/20 shadow-emerald-900/10',
    rose: 'text-rose-500 bg-rose-600/10 border-rose-500/20 shadow-rose-900/10',
    amber: 'text-amber-500 bg-amber-600/10 border-amber-500/20 shadow-amber-900/10',
  };

  return (
    <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] shadow-2xl group hover:-translate-y-1 transition-all relative overflow-hidden">
      <div className="relative z-10">
        <div className="flex items-center justify-between mb-8">
          <div className={`p-3 rounded-2xl border ${themes[color]} group-hover:scale-110 transition-transform`}>
            <Icon className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{title}</span>
        </div>
        <div className="text-4xl font-black text-white tracking-tighter mb-2 font-mono tabular-nums leading-none">{value}</div>
        <p className="text-[9px] font-black text-slate-600 uppercase tracking-[0.2em]">{label}</p>
      </div>
      <div className={`absolute -right-4 -bottom-4 w-24 h-24 blur-3xl opacity-0 group-hover:opacity-10 transition-all ${themes[color]}`}></div>
    </div>
  );
};

const AnalysisBox = ({ title, subtitle, children }: any) => (
  <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl relative group overflow-hidden">
    <div className="absolute top-0 left-0 w-64 h-64 bg-white/5 blur-[100px] pointer-events-none"></div>
    <header className="mb-10 relative z-10">
      <h3 className="text-xl font-black text-white tracking-tighter uppercase">{title}</h3>
      <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-2">{subtitle}</p>
    </header>
    <div className="relative z-10 min-h-[300px] flex items-center justify-center">
      {children}
    </div>
  </div>
);

import React, { useState, useEffect } from 'react';
import {
  BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import {
  Users,
  DollarSign,
  TrendingUp,
  Calendar,
  AlertCircle,
  Zap,
  Activity,
  ArrowUpRight,
  ShieldCheck,
  Cpu,
  Fingerprint
} from 'lucide-react';
import { useLocale } from '../../i18n/useLocale';

interface PayrollStats {
  totalEmployees: number;
  activeEmployees: number;
  totalPayroll: number;
  averageSalary: number;
  nextPayrollDate: string;
  lastPayrollAmount: number;
}

interface DepartmentData {
  name: string;
  employees: number;
  totalSalary: number;
  averageSalary: number;
}

interface MonthlyPayroll {
  month: string;
  amount: number;
  employees: number;
}

export const PayrollDashboard: React.FC = () => {
  const { t, language } = useLocale();
  const [stats, setStats] = useState<PayrollStats>({
    totalEmployees: 0,
    activeEmployees: 0,
    totalPayroll: 0,
    averageSalary: 0,
    nextPayrollDate: '',
    lastPayrollAmount: 0
  });
  const [departmentData, setDepartmentData] = useState<DepartmentData[]>([]);
  const [monthlyPayroll, setMonthlyPayroll] = useState<MonthlyPayroll[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPayrollData();
  }, [language]);

  const loadPayrollData = () => {
    try {
      setLoading(true);
      const mockStats: PayrollStats = {
        totalEmployees: 25,
        activeEmployees: 23,
        totalPayroll: 125000,
        averageSalary: 5435,
        nextPayrollDate: getNextPayrollDate(),
        lastPayrollAmount: 124500
      };

      const mockDepartments: DepartmentData[] = [
        { name: t('payrollDashboard.department') + ' A', employees: 5, totalSalary: 35000, averageSalary: 7000 },
        { name: t('payrollDashboard.department') + ' B', employees: 8, totalSalary: 40000, averageSalary: 5000 },
        { name: t('payrollDashboard.department') + ' C', employees: 7, totalSalary: 28000, averageSalary: 4000 },
        { name: t('payrollDashboard.department') + ' D', employees: 3, totalSalary: 18000, averageSalary: 6000 },
        { name: t('payrollDashboard.department') + ' E', employees: 2, totalSalary: 14000, averageSalary: 7000 }
      ];

      setStats(mockStats);
      setDepartmentData(mockDepartments);
      setMonthlyPayroll(generateMockMonthlyData());
    } catch (error) {
      console.error('Error loading payroll data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getNextPayrollDate = (): string => {
    const today = new Date();
    const currentDay = today.getDate();
    const date = currentDay < 15
      ? new Date(today.getFullYear(), today.getMonth(), 15)
      : new Date(today.getFullYear(), today.getMonth() + 1, 0);
    return date.toLocaleDateString(language === 'es' ? 'es-ES' : 'en-US');
  };

  const generateMockMonthlyData = (): MonthlyPayroll[] => {
    const months = [
      t('financialDashboard.months.jan'),
      t('financialDashboard.months.feb'),
      t('financialDashboard.months.mar'),
      t('financialDashboard.months.abr'),
      t('financialDashboard.months.may'),
      t('financialDashboard.months.jun'),
      t('financialDashboard.months.jul'),
      t('financialDashboard.months.ago'),
      t('financialDashboard.months.sep'),
      t('financialDashboard.months.oct'),
      t('financialDashboard.months.nov'),
      t('financialDashboard.months.dic')
    ];

    try {
      const { dbExec } = require('../../database/simple-db');
      const res = dbExec(`
        SELECT
          strftime('%Y', pay_date) as yr,
          strftime('%m', pay_date) as mo,
          COALESCE(SUM(total_gross), 0) as amount
        FROM payroll_periods
        WHERE status IN ('closed', 'paid')
        GROUP BY yr, mo
        ORDER BY yr DESC, mo DESC
        LIMIT 12
      `);

      if (res && res[0]?.values?.length > 0) {
        return res[0].values
          .slice()
          .reverse()
          .map((row: any[]) => ({
            month: months[parseInt(row[1]) - 1] ?? row[1],
            amount: row[2] ?? 0,
            employees: stats.activeEmployees
          }));
      }
    } catch {
      // fallback to empty below
    }

    // Sin datos: retorna los ├║ltimos 12 meses con cero (sin aleatorios)
    const currentMonth = new Date().getMonth();
    return Array.from({ length: 12 }, (_, i) => {
      const monthIndex = (currentMonth - 11 + i + 12) % 12;
      return { month: months[monthIndex], amount: 0, employees: 0 };
    });
  };

  const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-screen bg-slate-950">
      <div className="w-16 h-16 border-4 border-emerald-600/20 border-t-emerald-500 rounded-full animate-spin mb-6 shadow-[0_0_20px_rgba(16,185,129,0.3)]"></div>
      <span className="text-xs font-black text-slate-500 uppercase tracking-[0.4em] animate-pulse">{t('payrollDashboard.processing')}</span>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      <div className="mb-8 border-b border-slate-800 pb-6">
        <div className="flex items-center gap-4">
          <div className="p-3.5 bg-slate-900/50 rounded-xl border border-white/5 shadow-2xl backdrop-blur-xl group">
            <Activity className="w-7 h-7 text-emerald-500 group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none uppercase">
              {t('payrollDashboard.title')}
            </h1>
            <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2 uppercase">
              <Zap className="w-3.5 h-3.5 text-emerald-500 animate-pulse" /> {t('payrollDashboard.subtitle')}
            </p>
          </div>
        </div>
      </div>

      {/* Stats Matrix */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        <EliteStatCard title={t('payrollDashboard.humanCapital')} value={stats.totalEmployees.toString()} label={`${stats.activeEmployees} ${t('payrollDashboard.activeTokens')}`} icon={Users} color="blue" />
        <EliteStatCard title={t('payrollDashboard.monthlyLiability')} value={formatCurrency(stats.totalPayroll)} label={`${t('payrollDashboard.avg')}: ${formatCurrency(stats.averageSalary)}`} icon={DollarSign} color="emerald" />
        <EliteStatCard title={t('payrollDashboard.nextCycle')} value={stats.nextPayrollDate} label={`${t('payrollDashboard.prev')}: ${formatCurrency(stats.lastPayrollAmount)}`} icon={Calendar} color="amber" />
        <EliteStatCard title={t('payrollDashboard.projectedAnnualCost')} value={formatCurrency(stats.totalPayroll * 12)} label={t('payrollDashboard.plImpact')} icon={TrendingUp} color="emerald" />
      </div>

      {/* Analysis Matrix */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-10">
        <AnalysisBox title={t('payrollDashboard.operationalDistribution')} subtitle={t('payrollDashboard.salaryLoadByDept')}>
          <ResponsiveContainer width="100%" height={350}>
            <BarChart data={departmentData} margin={{ top: 20, right: 30, left: 10, bottom: 0 }}>
              <defs>
                <linearGradient id="barDept" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#10b981" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#10b981" stopOpacity={0.1} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
              <XAxis dataKey="name" stroke="#475569" fontSize={9} fontWeight="900" axisLine={false} tickLine={false} dy={10} />
              <YAxis stroke="#475569" fontSize={9} fontWeight="900" axisLine={false} tickLine={false} tickFormatter={(v) => `$${v / 1000}k`} />
              <Tooltip
                cursor={{ fill: 'rgba(16,185,129,0.03)' }}
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem' }}
                itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: '900' }}
              />
              <Bar dataKey="totalSalary" fill="url(#barDept)" radius={[6, 6, 0, 0]} barSize={32} />
            </BarChart>
          </ResponsiveContainer>
        </AnalysisBox>

        <AnalysisBox title={t('payrollDashboard.growthVector')} subtitle={t('payrollDashboard.historicalEvolution')}>
          <ResponsiveContainer width="100%" height={350}>
            <LineChart data={monthlyPayroll}>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
              <XAxis dataKey="month" stroke="#475569" fontSize={9} fontWeight="900" axisLine={false} tickLine={false} dy={10} />
              <YAxis stroke="#475569" fontSize={9} fontWeight="900" axisLine={false} tickLine={false} tickFormatter={(v) => `$${v / 1000}k`} />
              <Tooltip
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem' }}
                itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: '900' }}
              />
              <Line
                type="monotone"
                dataKey="amount"
                stroke="#10b981"
                strokeWidth={4}
                dot={{ fill: '#10b981', strokeWidth: 2, r: 6, stroke: '#0f172a' }}
                activeDot={{ r: 9, stroke: '#10b981', strokeWidth: 2, fill: '#0f172a' }}
              />
            </LineChart>
          </ResponsiveContainer>
        </AnalysisBox>
      </div>

      {/* Detailed Matrix Table */}
      <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl overflow-hidden relative group">
        <header className="flex items-center justify-between mb-12">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-emerald-600/10 rounded-xl flex items-center justify-center border border-emerald-500/20">
              <ShieldCheck className="w-5 h-5 text-emerald-500" />
            </div>
            <div>
              <h3 className="text-xl font-black text-white tracking-tighter uppercase leading-none">{t('payrollDashboard.payrollCertification')}</h3>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-2">{t('payrollDashboard.auditByCostCenter')}</p>
            </div>
          </div>
          <button className="p-3 bg-slate-950 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-all">
            <Cpu className="w-4 h-4 text-slate-500" />
          </button>
        </header>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-950/50">
              <tr>
                {[t('payrollDashboard.department'), t('payrollDashboard.workforce'), t('payrollDashboard.monthlyCost'), t('payrollDashboard.avgSalary'), t('payrollDashboard.impact'), t('payrollDashboard.annualCost')].map(h => (
                  <th key={h} className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {departmentData.map((dept, idx) => (
                <tr key={idx} className="hover:bg-white/[0.02] transition-colors group/row">
                  <td className="px-8 py-5">
                    <span className="text-sm font-black text-white leading-none uppercase tracking-tighter">{dept.name}</span>
                  </td>
                  <td className="px-8 py-5 text-sm font-black text-slate-300 font-mono italic">{dept.employees} pax</td>
                  <td className="px-8 py-5 text-sm font-mono font-black text-emerald-400">{formatCurrency(dept.totalSalary)}</td>
                  <td className="px-8 py-5 text-sm font-mono text-slate-500">{formatCurrency(dept.averageSalary)}</td>
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="flex-1 h-1 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                        <div className="h-full bg-emerald-600 shadow-[0_0_10px_rgba(16,185,129,0.3)] transition-all duration-1000" style={{ width: `${(dept.totalSalary / stats.totalPayroll * 100) || 0}%` }}></div>
                      </div>
                      <span className="text-[10px] font-black text-slate-500 w-10 text-right">{((dept.totalSalary / stats.totalPayroll) * 100).toFixed(1)}%</span>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-sm font-black text-slate-400 font-mono group-hover/row:text-white transition-colors">{formatCurrency(dept.totalSalary * 12)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const EliteStatCard = ({ title, value, icon: Icon, color, label }: any) => {
  const themes: any = {
    blue: 'text-blue-500 bg-blue-600/10 border-blue-500/20 shadow-blue-900/10',
    emerald: 'text-emerald-500 bg-emerald-600/10 border-emerald-500/20 shadow-emerald-900/10',
    rose: 'text-rose-500 bg-rose-600/10 border-rose-500/20 shadow-rose-900/10',
    amber: 'text-amber-500 bg-amber-600/10 border-amber-500/20 shadow-amber-900/10',
    indigo: 'text-emerald-500 bg-emerald-600/10 border-emerald-500/20 shadow-emerald-900/10',
  };

  return (
    <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] shadow-2xl group hover:-translate-y-1 transition-all relative overflow-hidden">
      <div className="relative z-10">
        <div className="flex items-center justify-between mb-8">
          <div className={`p-3 rounded-2xl border ${themes[color]} group-hover:scale-110 transition-transform`}>
            <Icon className="w-6 h-6" />
          </div>
          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{title}</span>
        </div>
        <div className="text-3xl font-black text-white tracking-tight mb-2 font-mono tabular-nums leading-none">{value}</div>
        <p className="text-[9px] font-black text-slate-600 uppercase tracking-widest">{label}</p>
      </div>
      <div className={`absolute -right-4 -bottom-4 w-24 h-24 blur-3xl opacity-0 group-hover:opacity-10 transition-all ${themes[color]}`}></div>
    </div>
  );
};

const AnalysisBox = ({ title, subtitle, children }: any) => (
  <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl relative group overflow-hidden">
    <div className="absolute top-0 left-0 w-64 h-64 bg-white/5 blur-[100px] pointer-events-none"></div>
    <header className="mb-10 relative z-10">
      <h3 className="text-xl font-black text-white tracking-tighter uppercase">{title}</h3>
      <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-2">{subtitle}</p>
    </header>
    <div className="relative z-10 min-h-[300px] flex items-center justify-center">
      {children}
    </div>
  </div>
);

import React, { useState, useEffect } from 'react';
import {
    BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import {
    Building2,
    DollarSign,
    TrendingDown,
    Clock,
    Award,
    Zap,
    Activity,
    ArrowUpRight,
    ArrowDownRight,
    Target,
    ShieldAlert,
    Maximize2
} from 'lucide-react';
import { getSuppliers, getBills } from '@/database/simple-db';
import { useLocale } from '../../i18n/useLocale';

interface SupplierStats {
    totalSuppliers: number;
    newThisMonth: number;
    totalExpenses: number;
    averageBillValue: number;
    totalAP: number;
    overdueAP: number;
}

interface TopSupplier {
    id: number;
    name: string;
    expenses: number;
    billCount: number;
    averageBill: number;
}

interface APAgingBucket {
    range: string;
    amount: number;
    count: number;
    color: string;
}

export const SupplierDashboard: React.FC = () => {
    const { t } = useLocale();
    const [stats, setStats] = useState<SupplierStats>({
        totalSuppliers: 0,
        newThisMonth: 0,
        totalExpenses: 0,
        averageBillValue: 0,
        totalAP: 0,
        overdueAP: 0
    });
    const [topSuppliers, setTopSuppliers] = useState<TopSupplier[]>([]);
    const [apAging, setApAging] = useState<APAgingBucket[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadSupplierData();
    }, []);

    const loadSupplierData = () => {
        try {
            setLoading(true);
            const suppliers = getSuppliers();
            const bills = getBills();
            const now = new Date();
            const firstDayOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

            const newSuppliers = suppliers.filter(s => new Date(s.created_at) >= firstDayOfMonth);
            let totalExpenses = 0;
            let overdueAP = 0;

            const unpaidBills = bills.filter(bill => bill.status !== 'paid' && bill.status !== 'cancelled');
            unpaidBills.forEach(bill => {
                if (bill.due_date && new Date(bill.due_date) < now) {
                    overdueAP += bill.total_amount;
                }
            });

            bills.forEach(bill => totalExpenses += bill.total_amount);
            const totalAP = unpaidBills.reduce((sum, bill) => sum + bill.total_amount, 0);

            setStats({
                totalSuppliers: suppliers.length,
                newThisMonth: newSuppliers.length,
                totalExpenses,
                averageBillValue: bills.length > 0 ? totalExpenses / bills.length : 0,
                totalAP,
                overdueAP
            });

            const supplierExpenses: Record<number, { name: string; expenses: number; count: number }> = {};
            bills.forEach(bill => {
                if (!supplierExpenses[bill.supplier_id]) {
                    const supplier = suppliers.find(s => s.id === bill.supplier_id);
                    supplierExpenses[bill.supplier_id] = { name: supplier?.name || t('supplierDashboard.unknownSupplier'), expenses: 0, count: 0 };
                }
                supplierExpenses[bill.supplier_id].expenses += bill.total_amount;
                supplierExpenses[bill.supplier_id].count++;
            });

            setTopSuppliers(Object.entries(supplierExpenses)
                .map(([id, data]) => ({
                    id: Number(id),
                    name: data.name,
                    expenses: data.expenses,
                    billCount: data.count,
                    averageBill: data.expenses / data.count
                }))
                .sort((a, b) => b.expenses - a.expenses)
                .slice(0, 10));

            const aging: APAgingBucket[] = [
                { range: t('supplierDashboard.aging.current'), amount: 0, count: 0, color: '#3b82f6' },
                { range: t('supplierDashboard.aging.31-60'), amount: 0, count: 0, color: '#f59e0b' },
                { range: t('supplierDashboard.aging.61-90'), amount: 0, count: 0, color: '#ef4444' },
                { range: t('supplierDashboard.aging.90+'), amount: 0, count: 0, color: '#7f1d1d' }
            ];

            unpaidBills.forEach(bill => {
                if (bill.due_date) {
                    const daysOverdue = Math.floor((now.getTime() - new Date(bill.due_date).getTime()) / (1000 * 60 * 60 * 24));
                    if (daysOverdue <= 30) { aging[0].amount += bill.total_amount; aging[0].count++; }
                    else if (daysOverdue <= 60) { aging[1].amount += bill.total_amount; aging[1].count++; }
                    else if (daysOverdue <= 90) { aging[2].amount += bill.total_amount; aging[2].count++; }
                    else { aging[3].amount += bill.total_amount; aging[3].count++; }
                }
            });
            setApAging(aging);
        } catch (error) {
            console.error('Error loading supplier data:', error);
        } finally {
            setLoading(false);
        }
    };

    const formatCurrency = (val: number) => `$${val.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

    if (loading) return (
        <div className="flex flex-col items-center justify-center h-screen bg-slate-950">
            <div className="w-16 h-16 border-4 border-blue-600/20 border-t-rose-500 rounded-full animate-spin mb-6"></div>
            <span className="text-xs font-black text-slate-500 uppercase tracking-[0.4em] animate-pulse">{t('supplierDashboard.analyzing')}</span>
        </div>
    );

    return (
        <div className="space-y-10 animate-in fade-in duration-700 pb-20">
            {/* Header Hub */}
            <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-rose-600/10 rounded-2.5xl border border-rose-500/20 shadow-rose-900/10 shadow-lg group">
                        <Building2 className="w-10 h-10 text-rose-500 group-hover:-rotate-6 transition-transform duration-500" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-white tracking-tight leading-none uppercase">{t('supplierDashboard.title')}</h1>
                        <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2 uppercase">
                            <Zap className="w-3.5 h-3.5 text-rose-500 animate-pulse" /> {t('supplierDashboard.subtitle')}
                        </p>
                    </div>
                </div>
            </div>

            {/* Stats Matrix */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                <EliteStatCard title={t('supplierDashboard.totalPartners')} value={stats.totalSuppliers.toString()} label={t('supplierDashboard.newThisMonth', { count: stats.newThisMonth })} icon={Building2} color="blue" />
                <EliteStatCard title={t('supplierDashboard.capitalOutflow')} value={formatCurrency(stats.totalExpenses)} label={`${t('supplierDashboard.avgTicket')}: ${formatCurrency(stats.averageBillValue)}`} icon={DollarSign} color="rose" />
                <EliteStatCard title={t('supplierDashboard.accountsPayable')} value={formatCurrency(stats.totalAP)} label={`${((stats.totalAP / stats.totalExpenses) * 100).toFixed(1)}% ${t('supplierDashboard.ofExpense')}`} icon={Clock} color="amber" />
                <EliteStatCard title={t('supplierDashboard.criticalAP')} value={formatCurrency(stats.overdueAP)} label={`${((stats.overdueAP / stats.totalAP) * 100).toFixed(1)}% ${t('supplierDashboard.overdue')}`} icon={TrendingDown} color="emerald" />
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-2 gap-10">
                {/* Top Suppliers Vertical Chart */}
                <AnalysisBox title={t('supplierDashboard.costConcentration')} subtitle={t('supplierDashboard.top10Volume')}>
                    <ResponsiveContainer width="100%" height={400}>
                        <BarChart data={topSuppliers} layout="vertical" margin={{ right: 40, left: 20 }}>
                            <defs>
                                <linearGradient id="barSupplier" x1="0" y1="0" x2="1" y2="0">
                                    <stop offset="0%" stopColor="#ef4444" stopOpacity={0.8} />
                                    <stop offset="100%" stopColor="#ef4444" stopOpacity={0.2} />
                                </linearGradient>
                            </defs>
                            <XAxis type="number" hide />
                            <YAxis dataKey="name" type="category" stroke="#475569" fontSize={10} fontWeight="900" width={140} axisLine={false} tickLine={false} />
                            <Tooltip
                                cursor={{ fill: 'rgba(239,68,68,0.02)' }}
                                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1.2rem' }}
                                itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: '900' }}
                                formatter={(v: any) => formatCurrency(v)}
                            />
                            <Bar dataKey="expenses" fill="url(#barSupplier)" radius={[0, 8, 8, 0]} barSize={26} />
                        </BarChart>
                    </ResponsiveContainer>
                </AnalysisBox>

                {/* AP Aging Pie */}
                <AnalysisBox title={t('supplierDashboard.debtAging')} subtitle={t('supplierDashboard.pendingDistribution')}>
                    <div className="flex flex-col lg:flex-row items-center justify-center gap-10 h-full">
                        <ResponsiveContainer width="100%" height={300}>
                            <PieChart>
                                <Pie
                                    data={apAging}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={80}
                                    outerRadius={110}
                                    paddingAngle={10}
                                    dataKey="amount"
                                    stroke="none"
                                >
                                    {apAging.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={entry.color} opacity={0.8} />
                                    ))}
                                </Pie>
                                <Tooltip
                                    contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '1rem' }}
                                    itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: '900' }}
                                />
                            </PieChart>
                        </ResponsiveContainer>

                        <div className="space-y-4 min-w-[200px]">
                            {apAging.map((bucket, idx) => (
                                <div key={idx} className="flex flex-col">
                                    <div className="flex items-center justify-between mb-1">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: bucket.color }}></div>
                                            <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{bucket.range}</span>
                                        </div>
                                        <span className="text-[10px] font-black text-white font-mono">{formatCurrency(bucket.amount)}</span>
                                    </div>
                                    <div className="w-full h-1 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                                        <div className="h-full opacity-50" style={{ width: `${(bucket.amount / stats.totalAP * 100) || 0}%`, backgroundColor: bucket.color }}></div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </AnalysisBox>
            </div>

            {/* Detailed Matrix Mapping */}
            <div className="bg-slate-900 border border-slate-800 rounded-[3rem] p-10 shadow-2xl overflow-hidden relative group">
                <div className="absolute top-0 right-0 w-64 h-64 bg-slate-700/5 blur-[100px] pointer-events-none"></div>
                <header className="flex items-center justify-between mb-12">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-rose-600/10 rounded-xl flex items-center justify-center border border-rose-500/20">
                            <Target className="w-5 h-5 text-rose-500" />
                        </div>
                        <div>
                            <h3 className="text-xl font-black text-white tracking-tighter uppercase leading-none">{t('supplierDashboard.eliteMapping')}</h3>
                            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-2">{t('supplierDashboard.performanceDetail')}</p>
                        </div>
                    </div>
                    <button className="p-3 bg-slate-950 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-all text-slate-600 hover:text-white">
                        <ShieldAlert className="w-4 h-4" />
                    </button>
                </header>

                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-slate-950/50">
                            <tr>
                                {[t('supplierDashboard.ranking'), t('supplierDashboard.supplierLegalName'), t('supplierDashboard.totalExpense'), t('supplierDashboard.bills'), t('customerDashboard.avgTicket'), t('supplierDashboard.impact')].map(h => (
                                    <th key={h} className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest">{h}</th>
                                ))}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800/50">
                            {topSuppliers.map((supplier, idx) => (
                                <tr key={supplier.id} className="hover:bg-white/[0.02] transition-colors group/row">
                                    <td className="px-8 py-5">
                                        <span className="w-6 h-6 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center text-[10px] font-black text-slate-500 group-hover/row:border-rose-500 group-hover/row:text-white transition-all">{idx + 1}</span>
                                    </td>
                                    <td className="px-8 py-5">
                                        <div className="flex flex-col">
                                            <span className="text-sm font-black text-white leading-none">{supplier.name}</span>
                                            <span className="text-[9px] font-black text-rose-500 uppercase tracking-widest mt-1.5 opacity-60">ID: SPX-{supplier.id.toString().padStart(4, '0')}</span>
                                        </div>
                                    </td>
                                    <td className="px-8 py-5 text-sm font-mono font-black text-rose-400 group-hover/row:scale-105 transition-transform origin-left">{formatCurrency(supplier.expenses)}</td>
                                    <td className="px-8 py-5 text-sm font-black text-slate-300 font-mono italic">{supplier.billCount}</td>
                                    <td className="px-8 py-5 text-sm font-mono text-slate-500">{formatCurrency(supplier.averageBill)}</td>
                                    <td className="px-8 py-5">
                                        <div className="flex items-center gap-4">
                                            <div className="flex-1 h-1.5 bg-slate-950 rounded-full overflow-hidden border border-slate-800">
                                                <div className="h-full bg-rose-600 shadow-[0_0_10px_rgba(239,68,68,0.3)] transition-all duration-1000" style={{ width: `${(supplier.expenses / stats.totalExpenses * 100) || 0}%` }}></div>
                                            </div>
                                            <span className="text-[10px] font-black text-slate-500 w-10 text-right">{((supplier.expenses / stats.totalExpenses) * 100).toFixed(1)}%</span>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

const EliteStatCard = ({ title, value, icon: Icon, color, label }: any) => {
    const themes: any = {
        blue: 'text-blue-500 bg-blue-600/10 border-blue-500/20 shadow-blue-900/10',
        rose: 'text-rose-500 bg-rose-600/10 border-rose-500/20 shadow-rose-900/10',
        emerald: 'text-emerald-500 bg-emerald-600/10 border-emerald-500/20 shadow-emerald-900/10',
        amber: 'text-amber-500 bg-amber-600/10 border-amber-500/20 shadow-amber-900/10',
    };

    return (
