import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { AlertTriangle, TrendingUp, Package, ArrowRight, Zap } from 'lucide-react';
import { getProducts, getKardexMovements, Product, KardexEntry } from '@/database/simple-db';
import { useLocale } from '@/i18n/useLocale';

export const InventoryDashboard: React.FC<{
    OnNavigateToKardex: (filters?: { alert?: string }) => void
}> = ({ OnNavigateToKardex }) => {
    const { t } = useLocale();
    const [lowStockProducts, setLowStockProducts] = useState<Product[]>([]);
    const [recentMovements, setRecentMovements] = useState<KardexEntry[]>([]);
    const [stats, setStats] = useState({
        totalValue: 0,
        totalItems: 0,
        lowStockCount: 0
    });

    useEffect(() => {
        loadData();
    }, []);

    const loadData = () => {
        try {
            const products = getProducts();
            const movements = getKardexMovements({}); // Get all/recent

            // Calculate stats
            let totalVal = 0;
            let totalQty = 0;
            const lowStock: Product[] = [];

            products.forEach(p => {
                const cost = p.cost ?? 0;
                const qty = p.stock_quantity ?? 0;
                const min = p.min_stock_level ?? 0;

                totalVal += (qty * cost);
                totalQty += qty;
                if (qty <= min) {
                    lowStock.push(p);
                }
            });

            setStats({
                totalValue: totalVal,
                totalItems: totalQty,
                lowStockCount: lowStock.length
            });

            setLowStockProducts(lowStock);
            setRecentMovements(movements.slice(0, 5)); // Top 5 recent

        } catch (error) {
            console.error("Error loading inventory dashboard", error);
        }
    };

    return (
        <div className="space-y-12 animate-in fade-in duration-700 pb-20">
