          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{t('payroll.review.status')}</label>
            <select
              value={filterStatus}
              onChange={e => setFilterStatus(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white font-black uppercase tracking-widest text-[10px] outline-none focus:border-emerald-500"
            >
              <option value="">{t('payroll.review.allStatuses')}</option>
              <option value="draft">{t('payroll.review.draft')}</option>
              <option value="approved">{t('payroll.review.approved')}</option>
              <option value="paid">{t('payroll.review.paid')}</option>
              <option value="voided">{t('payroll.review.voided')}</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{t('payroll.review.year')}</label>
            <select
              value={filterYear}
              onChange={e => setFilterYear(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white font-black uppercase tracking-widest text-[10px] outline-none focus:border-emerald-500"
            >
              <option value="">{t('payroll.review.allYears')}</option>
              {years.map(y => (
                <option key={y} value={y}>{y}</option>
              ))}
            </select>
          </div>
          <div className="flex items-end">
            <button
              onClick={loadPayrolls}
              className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-black px-8 py-4 rounded-2xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-[10px] shadow-xl shadow-emerald-900/40 hover:-translate-y-1"
            >
              <Filter className="w-4 h-4 fill-white" />
              {t('payroll.review.applyFilters')}
            </button>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-slate-900 border border-slate-800 rounded-[3rem] shadow-2xl overflow-hidden">
        <table className="w-full">
          <thead className="bg-slate-950 border-b border-slate-800">
            <tr>
              <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.employee')}</th>
              <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.review.payPeriodCol')}</th>
              <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.review.payDateCol')}</th>
              <th className="px-6 py-4 text-right text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.review.grossPayCol')}</th>
              <th className="px-6 py-4 text-right text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.review.netPayCol')}</th>
              <th className="px-6 py-4 text-center text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.review.statusCol')}</th>
              <th className="px-6 py-4 text-center text-[10px] font-black text-slate-500 uppercase tracking-widest">{t('payroll.review.actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/40">
            {payrolls.map(p => (
              <tr key={p.id} className="hover:bg-white/[0.02] transition-colors">
                <td className="px-6 py-4 text-sm font-black text-white">{getEmployeeName(p.employee_id)}</td>
                <td className="px-6 py-4 text-xs font-black text-slate-400">{p.pay_period_start} - {p.pay_period_end}</td>
                <td className="px-6 py-4 text-xs font-black text-slate-400">{p.pay_date}</td>
                <td className="px-6 py-4 text-sm font-black text-white text-right">{formatCurrency(p.gross_pay)}</td>
                <td className="px-6 py-4 text-sm font-black text-emerald-400 text-right">{formatCurrency(p.net_pay)}</td>
                <td className="px-6 py-4 text-center">
                  <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full border ${getStatusColor(p.status)}`}>
                    {getStatusLabel(p.status)}
                  </span>
                </td>
                <td className="px-6 py-4 text-center">
                  <div className="flex items-center justify-center gap-2">
                    {onViewPaystub && (
                      <button
                        onClick={() => onViewPaystub(p.id!)}
                        className="p-2 hover:bg-blue-500/20 text-blue-400 rounded-lg transition-colors"
                        title={t('payroll.review.viewPaystub')}
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                    )}
                    {p.status !== 'voided' && (
                      <button
                        onClick={() => handleVoid(p.id!)}
                        className="p-2 hover:bg-rose-500/20 text-rose-400 rounded-lg transition-colors"
                        title={t('payroll.review.voidPayroll')}
                      >
                        <XCircle className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
            {payrolls.length === 0 && (
              <tr>
                <td colSpan={7} className="px-6 py-16 text-center text-slate-600 text-xs font-black uppercase tracking-widest">
                  {t('payroll.review.noPayrollsFound')}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default PayrollReview;

import React, { useState, useEffect } from 'react';
import {
    Settings,
    Save,
    Plus,
    Trash2,
    DollarSign,
    Percent,
    Calculator,
    AlertCircle,
    Zap
} from 'lucide-react';
import {
    getPayrollSettings,
    updatePayrollSetting,
    getTaxBrackets,
    createTaxBracket,
    updateTaxBracket,
    deleteTaxBracket,
    PayrollSetting,
    TaxBracket
} from '@/database/simple-db';
import { toast } from 'react-hot-toast';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { useLocale } from '@/i18n/useLocale';

export const PayrollSettings: React.FC = () => {
    const { t } = useLocale();
    const [settings, setSettings] = useState<PayrollSetting[]>([]);
    const [brackets, setBrackets] = useState<TaxBracket[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [showBracketForm, setShowBracketForm] = useState(false);
    const [editingBracket, setEditingBracket] = useState<TaxBracket | null>(null);

    // Form state for tax bracket
    const [bracketForm, setBracketForm] = useState({
        min_income: 0,
        max_income: undefined as number | undefined,
        fixed_amount: 0,
        percentage: 0
    });

    const loadData = () => {
        setSettings(getPayrollSettings());
        setBrackets(getTaxBrackets());
    };

    useEffect(() => {
        loadData();
    }, []);

    const handleSettingUpdate = async (key: string, value: string) => {
        setIsLoading(true);
        try {
            const result = updatePayrollSetting(key, value);
            if (result.success) {
                toast.success(result.message);
                loadData();
            } else {
                toast.error(result.message);
            }
        } catch (error) {
            toast.error('Error al actualizar configuraci├│n');
        } finally {
            setIsLoading(false);
        }
    };

    const handleBracketSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            let result;
            if (editingBracket) {
                result = updateTaxBracket(editingBracket.id!, bracketForm);
            } else {
                result = createTaxBracket(bracketForm);
            }

            if (result.success) {
                toast.success(result.message);
                loadData();
                setShowBracketForm(false);
                setEditingBracket(null);
                resetBracketForm();
            } else {
                toast.error(result.message);
            }
        } catch (error) {
            toast.error('Error al procesar rango de impuesto');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDeleteBracket = async (id: number) => {
        if (!confirm('┬┐Eliminar este rango de impuesto?')) return;

        try {
            const result = deleteTaxBracket(id);
            if (result.success) {
                toast.success(result.message);
                loadData();
            } else {
                toast.error(result.message);
            }
        } catch (error) {
            toast.error('Error al eliminar rango');
        }
    };

    const resetBracketForm = () => {
        setBracketForm({
            min_income: 0,
            max_income: undefined,
            fixed_amount: 0,
            percentage: 0
        });
    };

    const startEditBracket = (bracket: TaxBracket) => {
        setEditingBracket(bracket);
        setBracketForm({
            min_income: bracket.min_income,
            max_income: bracket.max_income || undefined,
            fixed_amount: bracket.fixed_amount,
            percentage: bracket.percentage
        });
        setShowBracketForm(true);
    };

    return (
        <div className="space-y-6">
            {/* Header Hub */}
            <div className="mb-8 border-b border-slate-800 pb-6">
                <div className="flex items-center gap-4">
                    <div className="p-3.5 bg-slate-900/50 rounded-xl border border-white/5 shadow-2xl backdrop-blur-xl group">
                        <Settings className="w-7 h-7 text-emerald-500 group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div>
                        <h2 className="text-2xl font-bold text-white tracking-tight">
                            Configuraci├│n de N├│mina
                        </h2>
                        <p className="text-slate-500 text-[13px] flex items-center gap-2 mt-1">
                            <Zap className="w-3.5 h-3.5 text-emerald-500 animate-pulse" /> Tasas, Impuestos y Par├ímetros
                        </p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Configuraciones Generales */}
                <Card className="bg-slate-900 border-slate-800">
                    <CardHeader className="border-b border-slate-800">
                        <CardTitle className="text-white text-lg font-black">{t('payroll.settings.generalSettings')}</CardTitle>
                    </CardHeader>
                    <CardContent className="p-6 space-y-6">
                        {settings.map(setting => (
                            <div key={setting.id} className="space-y-2">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                                    {setting.description || setting.setting_key}
                                </label>
                                <div className="flex gap-2">
                                    <input
                                        type="text"
                                        defaultValue={setting.setting_value}
                                        onBlur={(e) => {
                                            if (e.target.value !== setting.setting_value) {
                                                handleSettingUpdate(setting.setting_key, e.target.value);
                                            }
                                        }}
                                        className="flex-1 bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white outline-none focus:border-emerald-500"
                                    />
                                    <div className="p-2 bg-slate-800 rounded-xl">
                                        {setting.setting_key.includes('rate') ? (
                                            <Percent className="w-4 h-4 text-slate-500" />
                                        ) : (
                                            <DollarSign className="w-4 h-4 text-slate-500" />
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </CardContent>
                </Card>

                {/* Rangos de Impuesto */}
                <Card className="bg-slate-900 border-slate-800">
                    <CardHeader className="border-b border-slate-800 flex flex-row items-center justify-between">
                        <CardTitle className="text-white text-lg font-black">{t('payroll.settings.taxBrackets')}</CardTitle>
                        <Button
                            onClick={() => { setShowBracketForm(true); setEditingBracket(null); resetBracketForm(); }}
                            size="sm"
                            className="bg-emerald-600 hover:bg-emerald-700 font-black"
                        >
                            <Plus className="w-4 h-4 mr-2" /> Nuevo Rango
                        </Button>
                    </CardHeader>
                    <CardContent className="p-0">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-950 text-slate-500 font-black uppercase tracking-widest text-[10px]">
                                <tr>
                                    <th className="px-4 py-3">Desde</th>
                                    <th className="px-4 py-3">Hasta</th>
                                    <th className="px-4 py-3">Cuota Fija</th>
                                    <th className="px-4 py-3">%</th>
                                    <th className="px-4 py-3">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-800">
                                {brackets.map(bracket => (
                                    <tr key={bracket.id} className="hover:bg-white/[0.02]">
                                        <td className="px-4 py-3 font-mono text-white">${bracket.min_income.toLocaleString()}</td>
                                        <td className="px-4 py-3 font-mono text-slate-400">
                                            {bracket.max_income ? `$${bracket.max_income.toLocaleString()}` : 'En adelante'}
                                        </td>
                                        <td className="px-4 py-3 font-mono text-slate-300">${bracket.fixed_amount.toLocaleString()}</td>
                                        <td className="px-4 py-3 font-mono text-emerald-400">{(bracket.percentage * 100).toFixed(1)}%</td>
                                        <td className="px-4 py-3">
                                            <div className="flex gap-1">
                                                <button
                                                    onClick={() => startEditBracket(bracket)}
                                                    className="p-1.5 hover:bg-emerald-500/20 text-emerald-400 rounded-lg"
                                                >
                                                    <Calculator className="w-3.5 h-3.5" />
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteBracket(bracket.id!)}
                                                    className="p-1.5 hover:bg-rose-500/20 text-rose-400 rounded-lg"
                                                >
                                                    <Trash2 className="w-3.5 h-3.5" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                {brackets.length === 0 && (
                                    <tr>
                                        <td colSpan={5} className="px-4 py-8 text-center text-slate-600 italic">No hay rangos configurados</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </CardContent>
                </Card>
            </div>

            {/* Formulario de Rango de Impuesto */}
            {showBracketForm && (
                <Card className="bg-slate-900 border-slate-800 shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
                    <CardHeader className="border-b border-slate-800">
                        <CardTitle className="text-white text-lg font-black">
                            {editingBracket ? 'Editar Rango de Impuesto' : 'Nuevo Rango de Impuesto'}
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-6">
                        <form onSubmit={handleBracketSubmit} className="space-y-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Ingreso M├¡nimo</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        value={bracketForm.min_income}
                                        onChange={(e) => setBracketForm(prev => ({ ...prev, min_income: parseFloat(e.target.value) || 0 }))}
                                        required
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white outline-none focus:border-emerald-500"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Ingreso M├íximo (opcional)</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        value={bracketForm.max_income || ''}
                                        onChange={(e) => setBracketForm(prev => ({ ...prev, max_income: e.target.value ? parseFloat(e.target.value) : undefined }))}
                                        placeholder="Dejar vac├¡o para 'en adelante'"
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white outline-none focus:border-emerald-500"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Cuota Fija</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        value={bracketForm.fixed_amount}
                                        onChange={(e) => setBracketForm(prev => ({ ...prev, fixed_amount: parseFloat(e.target.value) || 0 }))}
                                        required
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white outline-none focus:border-emerald-500"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Porcentaje (0.0 - 1.0)</label>
                                    <input
                                        type="number"
                                        step="0.001"
                                        min="0"
                                        max="1"
                                        value={bracketForm.percentage}
                                        onChange={(e) => setBracketForm(prev => ({ ...prev, percentage: parseFloat(e.target.value) || 0 }))}
                                        required
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white outline-none focus:border-emerald-500"
                                    />
                                </div>
                            </div>

                            <div className="p-4 bg-amber-500/5 border border-amber-500/10 rounded-2xl flex gap-3">
                                <AlertCircle className="w-5 h-5 text-amber-500 shrink-0" />
                                <div>
                                    <h4 className="text-xs font-black text-amber-500 uppercase mb-1">Nota sobre Rangos</h4>
                                    <p className="text-[10px] text-slate-500 leading-normal">
                                        Los rangos no deben solaparse. El porcentaje debe estar entre 0.0 y 1.0 (ej: 0.15 = 15%).
                                    </p>
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-4 border-t border-slate-800">
                                <Button
                                    type="button"
                                    variant="ghost"
                                    onClick={() => { setShowBracketForm(false); setEditingBracket(null); }}
                                    className="text-slate-400 hover:text-white"
                                >
                                    Cancelar
                                </Button>
                                <Button
                                    type="submit"
                                    disabled={isLoading}
                                    className="bg-emerald-600 hover:bg-emerald-700 text-white font-black px-8"
                                >
                                    {isLoading ? 'Procesando...' : editingBracket ? 'Actualizar Rango' : 'Crear Rango'}
                                </Button>
                            </div>
                        </form>
                    </CardContent>
                </Card>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ShoppingCart, Plus, Save, Trash2, XCircle, ShieldCheck } from 'lucide-react';
import { getSuppliers, getActiveProducts, createPurchaseOrder, Supplier, Product } from '@/database/simple-db';
import { toast } from 'react-hot-toast';
import { useLocale } from '../../i18n/useLocale';

interface PurchaseOrderItemRow {
    product_id: number;
    product_name: string;
    quantity: number;
    unit_price: number;
}

export const PurchaseOrderForm: React.FC<{ onCancel?: () => void, onSuccess?: () => void }> = ({ onCancel, onSuccess }) => {
    const { t } = useLocale();
    const [suppliers, setSuppliers] = useState<Supplier[]>([]);
    const [products, setProducts] = useState<Product[]>([]);

    const [formData, setFormData] = useState({
        supplier_id: 0,
        order_date: new Date().toISOString().split('T')[0],
        expected_date: '',
        notes: ''
    });

    const [items, setItems] = useState<PurchaseOrderItemRow[]>([]);

    // UI State for new item row
    const [newItem, setNewItem] = useState({
        product_id: 0,
        quantity: 1,
        unit_price: 0
    });

    useEffect(() => {
        setSuppliers(getSuppliers());
        setProducts(getActiveProducts());
    }, []);

    // Update unit price when product selected
    useEffect(() => {
        if (newItem.product_id) {
            const prod = products.find(p => p.id === newItem.product_id);
            if (prod) {
                // Use cost if available, otherwise price as fallback or 0
                setNewItem(prev => ({ ...prev, unit_price: prod.cost || 0 }));
            }
        }
    }, [newItem.product_id, products]);

    const handleAddItem = () => {
        if (!newItem.product_id || newItem.quantity <= 0) return;

        const prod = products.find(p => p.id === newItem.product_id);
        if (!prod) return;

        setItems(prev => [...prev, {
            product_id: newItem.product_id,
            product_name: prod.name,
            quantity: newItem.quantity,
            unit_price: newItem.unit_price
        }]);

        // Reset new item input
        setNewItem({ product_id: 0, quantity: 1, unit_price: 0 });
    };

    const handleRemoveItem = (index: number) => {
        setItems(prev => prev.filter((_, i) => i !== index));
    };

    const calculateTotals = () => {
        const subtotal = items.reduce((sum, item) => sum + (item.quantity * item.unit_price), 0);
        return { subtotal, total: subtotal }; // Buying usually doesn't calculate tax automatically without complex logic
    };

    const handleSave = () => {
        if (!formData.supplier_id) {
            toast.error(t('poForm.validation.selectSupplier'));
            return;
        }
        if (items.length === 0) {
            toast.error(t('poForm.validation.addItems'));
            return;
        }

        const totals = calculateTotals();

        // Generate a simple PO Number
        const orderNumber = `PO-${Date.now().toString().slice(-6)}`;

        const result = createPurchaseOrder({
            supplier_id: formData.supplier_id,
            order_number: orderNumber,
            order_date: formData.order_date,
            expected_date: formData.expected_date || undefined,
            status: 'draft',
            total_amount: totals.total,
            notes: formData.notes,
            items: items.map(i => ({
                product_id: i.product_id,
                quantity: i.quantity,
                unit_price: i.unit_price
            }))
        });

        if (result.success) {
            toast.success(t('poForm.success.created'));
            if (onSuccess) onSuccess();
        } else {
            toast.error(t('poForm.error.create') + result.message);
        }
    };

    const { total } = calculateTotals();

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-6 overflow-hidden">
            <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-[0_0_50px_rgba(0,0,0,0.5)] w-full max-w-5xl max-h-[95vh] overflow-hidden flex flex-col relative animate-in zoom-in duration-300">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-500/5 blur-[120px] pointer-events-none"></div>

                {/* Header Hub */}
                <header className="flex items-center justify-between p-10 border-b border-slate-800/50 flex-shrink-0 relative z-10">
                    <div className="flex items-center gap-6">
                        <div className="text-blue-500">
                            <ShoppingCart className="w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
                                {t('poForm.title')}
                            </h2>
                            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2 flex items-center gap-2">
                                <ShieldCheck className="w-3.5 h-3.5 text-blue-500" /> Procurement Protocol v4.0
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={onCancel}
                        className="p-3 bg-slate-950/50 border border-slate-800 rounded-2xl text-slate-500 hover:text-white transition-all shadow-lg active:scale-95"
                    >
                        <XCircle className="w-6 h-6" />
                    </button>
                </header>

                <div className="flex-1 overflow-y-auto p-10 space-y-12 relative z-10 custom-scrollbar">
                    {/* Header Info */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {/* Supplier */}
                        <div className="space-y-3">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1 block">
                                {t('poForm.supplier')}
                            </label>
                            <div className="relative group">
                                <select
                                    className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-bold uppercase tracking-widest text-[10px] appearance-none"
                                    value={formData.supplier_id}
                                    onChange={e => setFormData({ ...formData, supplier_id: Number(e.target.value) })}
                                >
                                    <option value={0}>{t('poForm.selectSupplier')}</option>
                                    {suppliers.map(s => (
                                        <option key={s.id} value={s.id}>{s.name}</option>
                                    ))}
                                </select>
                                <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-slate-600 font-black">Γû╝</div>
                            </div>
                        </div>

                        {/* Issue Date */}
                        <div className="space-y-3">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1 block">
                                {t('poForm.issueDate')}
                            </label>
                            <input
                                type="date"
                                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[10px]"
                                value={formData.order_date}
                                onChange={e => setFormData({ ...formData, order_date: e.target.value })}
                            />
                        </div>

                        {/* Expected Date */}
                        <div className="space-y-3">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1 ml-1 block">
                                {t('poForm.expectedDate')}
                            </label>
                            <input
                                type="date"
                                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl px-6 py-4 text-white focus:border-blue-500/50 outline-none transition-all font-black uppercase tracking-widest text-[10px]"
                                value={formData.expected_date}
                                onChange={e => setFormData({ ...formData, expected_date: e.target.value })}
                            />
                        </div>
                    </div>

                    {/* Items Section */}
                    <div className="space-y-6">
                        <h3 className="text-[11px] font-black text-white uppercase tracking-[0.3em] flex items-center gap-4">
                            <div className="w-8 h-[1px] bg-blue-500/50"></div>
                            {t('poForm.items') || 'ART├ìCULOS DEL PEDIDO'}
                            <div className="w-8 h-[1px] bg-blue-500/50"></div>
                        </h3>

                        <div className="bg-slate-950/30 border border-slate-800/50 rounded-[2rem] overflow-hidden">
                            {/* Table Header */}
                            <div className="grid grid-cols-[1fr,150px,150px,200px,80px] gap-4 p-8 bg-slate-900/50 border-b border-slate-800/50 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                                <div>{t('poForm.col.product')}</div>
                                <div className="text-right">{t('poForm.col.quantity')}</div>
                                <div className="text-right">{t('poForm.col.unitCost')}</div>
                                <div className="text-right">{t('poForm.col.total')}</div>
                                <div></div>
                            </div>

                            {/* Table Body */}
                            <div className="divide-y divide-slate-800/30">
                                {items.map((item, idx) => (
                                    <div key={idx} className="grid grid-cols-[1fr,150px,150px,200px,80px] gap-4 p-8 items-center group hover:bg-white/5 transition-colors">
                                        <div className="text-[11px] font-black text-white uppercase tracking-wider">{item.product_name}</div>
                                        <div className="text-sm font-black text-white text-right font-mono tracking-tighter">{item.quantity}</div>
                                        <div className="text-sm font-black text-white text-right font-mono tracking-tighter group-hover:text-blue-400 transition-colors">
                                            ${item.unit_price.toFixed(2)}
                                        </div>
                                        <div className="text-base font-black text-blue-400 text-right font-mono tracking-tighter">
                                            ${(item.quantity * item.unit_price).toFixed(2)}
                                        </div>
                                        <div className="flex justify-center">
                                            <button
                                                onClick={() => handleRemoveItem(idx)}
                                                className="p-3 bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 rounded-xl transition-all active:scale-90 opacity-0 group-hover:opacity-100"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                ))}

                                {/* Add New Item Interaction */}
                                <div className="p-10 bg-blue-500/5 border-t border-blue-500/10 grid grid-cols-[1fr,120px,180px,120px] gap-6 items-end">
                                    <div className="space-y-3">
                                        <label className="text-[9px] font-black text-blue-400/70 uppercase tracking-widest ml-1">{t('poForm.col.product')}</label>
                                        <div className="relative group">
                                            <select
                                                className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-6 py-4 text-white focus:border-blue-500 outline-none transition-all font-bold uppercase tracking-widest text-[10px] appearance-none"
                                                value={newItem.product_id}
                                                onChange={e => setNewItem({ ...newItem, product_id: Number(e.target.value) })}
                                            >
                                                <option value={0}>{t('poForm.addProductPlaceholder')}</option>
                                                {products.map(p => (
                                                    <option key={p.id} value={p.id}>{p.sku} - {p.name}</option>
                                                ))}
                                            </select>
                                            <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-slate-600 font-black">Γû╝</div>
                                        </div>
                                    </div>

                                    <div className="space-y-3">
                                        <label className="text-[9px] font-black text-blue-400/70 uppercase tracking-widest ml-1 text-right block">{t('poForm.col.quantity')}</label>
                                        <input
                                            type="number"
                                            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-6 py-4 text-white focus:border-blue-500 outline-none transition-all font-mono font-black text-sm text-right"
                                            placeholder="1"
                                            min="1"
                                            value={newItem.quantity}
                                            onChange={e => setNewItem({ ...newItem, quantity: Number(e.target.value) })}
                                        />
                                    </div>

                                    <div className="space-y-3">
                                        <label className="text-[9px] font-black text-blue-400/70 uppercase tracking-widest ml-1 text-right block">{t('poForm.col.unitCost')}</label>
                                        <div className="relative group">
                                            <span className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-600 font-bold">$</span>
                                            <input
                                                type="number"
                                                className="w-full bg-slate-900 border border-slate-800 rounded-2xl pl-12 pr-6 py-4 text-white focus:border-blue-500 outline-none transition-all font-mono font-black text-sm text-right"
                                                placeholder="0.00"
                                                min="0"
                                                step="0.01"
                                                value={newItem.unit_price}
                                                onChange={e => setNewItem({ ...newItem, unit_price: Number(e.target.value) })}
                                            />
                                        </div>
                                    </div>

                                    <button
                                        onClick={handleAddItem}
                                        disabled={!newItem.product_id}
                                        className="h-[58px] bg-blue-600 hover:bg-blue-500 disabled:opacity-20 text-white rounded-2xl transition-all shadow-xl shadow-blue-900/40 flex items-center justify-center group/btn"
                                    >
                                        <Plus className="w-6 h-6 group-hover/btn:scale-125 transition-transform" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Summary & Notes */}
                    <div className="grid grid-cols-1 md:grid-cols-[1fr,350px] gap-12 pt-8">
                        {/* Notes */}
                        <div className="space-y-4">
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">{t('poForm.notesLabel')}</label>
                            <textarea
                                className="w-full bg-slate-950/50 border border-slate-800/50 rounded-[2.5rem] px-8 py-8 text-white focus:border-blue-500 outline-none transition-all font-medium text-sm placeholder:text-slate-800 resize-none"
                                placeholder={t('poForm.notesPlaceholder')}
                                value={formData.notes}
                                onChange={e => setFormData({ ...formData, notes: e.target.value })}
                                rows={4}
                            />
                        </div>

                        {/* Grand Total */}
                        <div className="bg-white/5 border border-white/10 rounded-[2.5rem] p-10 flex flex-col justify-center items-center relative overflow-hidden group">
                            <div className="absolute -right-10 -bottom-10 opacity-5 group-hover:opacity-10 transition-opacity">
                                <ShoppingCart className="w-48 h-48 text-white" />
                            </div>

                            <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] mb-4 relative z-10">{t('poForm.totalOrder') || 'TOTAL DEL PEDIDO'}</p>
                            <div className="text-5xl font-black text-white tracking-tighter font-mono relative z-10">
                                <span className="text-2xl text-blue-500 mr-2">$</span>
                                {total.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </div>

                            <div className="w-20 h-1 bg-blue-500 rounded-full mt-8 relative z-10 opacity-50"></div>
                        </div>
                    </div>
                </div>

                {/* Footer Hub */}
                <footer className="p-10 border-t border-slate-800/50 bg-slate-950/30 flex justify-end gap-6 flex-shrink-0 relative z-10">
                    <button
                        type="button"
                        onClick={onCancel}
                        className="px-10 py-5 text-slate-500 hover:text-white transition-all font-black uppercase tracking-widest text-[10px] hover:bg-slate-900 rounded-2xl border border-transparent hover:border-slate-800"
                    >
                        {t('common.cancel')}
                    </button>
                    <button
                        onClick={handleSave}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-12 py-5 rounded-2.5xl font-black uppercase tracking-widest text-[11px] transition-all flex items-center justify-center gap-4 shadow-3xl shadow-blue-900/40 hover:-translate-y-1 active:scale-95"
                    >
                        <Save className="w-5 h-5" />
                        <span>{t('poForm.saveDraft')}</span>
                    </button>
                </footer>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { PieChart, Search, Calendar, RefreshCw, AlertCircle, ArrowLeftRight, FileBarChart } from 'lucide-react';
import { getAccountLedger, getChartOfAccounts } from '@/database/simple-db';
import { ReportExporter } from './ReportExporter';
import { logger } from '../../core/logging/SystemLogger';
import { useLocale } from '../../i18n/useLocale';

export const AccountLedger: React.FC = () => {
    const { t } = useLocale();
    const [accounts, setAccounts] = useState<any[]>([]);
    const [selectedAccount, setSelectedAccount] = useState<string>('');
    const [data, setData] = useState<any>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [dateRange, setDateRange] = useState({
        from: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
        to: new Date().toISOString().split('T')[0]
    });

    useEffect(() => {
        const list = getChartOfAccounts();
        setAccounts(list);
        if (list.length > 0) setSelectedAccount(list[0].account_code);
    }, []);

    const loadData = async () => {
        if (!selectedAccount) return;
        try {
            setLoading(true);
            setError(null);
            const result = getAccountLedger(selectedAccount, dateRange.from, dateRange.to);
            setData(result);
            logger.info('AccountLedger', 'load_success', `Auxiliar cargado: ${selectedAccount}`);
        } catch (e) {
            setError(t('reportsDashboard.accountLedger.loadError') || 'Error loading account ledger');
            logger.error('AccountLedger', 'load_failed', 'Fallo al cargar ledger', { accountCode: selectedAccount }, e as Error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadData();
    }, [selectedAccount, dateRange]);

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
    };

    const getExportData = () => {
        if (!data) return { headers: [], rows: [], fileName: '' };
        const rows = data.transactions.map((tx: any) => [
            tx.entry_date,
            tx.reference || '',
            tx.description,
            formatCurrency(tx.debit_amount),
            formatCurrency(tx.credit_amount),
            formatCurrency(tx.running_balance)
        ]);

        // Add Summary Row
        rows.push(['---', '---', t('reportsDashboard.accountLedger.periodTotals') || 'PERIOD TOTALS', formatCurrency(data.totalDebit), formatCurrency(data.totalCredit), '']);

        return {
            headers: [t('common.date'), t('accounting.reference') || 'Ref', t('common.description'), t('accounting.debit'), t('accounting.credit'), t('accounting.balance') || 'Balance'],
            rows,
            fileName: `Auxiliar_${selectedAccount}_${dateRange.from}_a_${dateRange.to}`
        };
    };

    return (
        <div className="space-y-8 animate-fade-in px-2">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-4">
                        <div className="p-3 bg-blue-500/10 rounded-2xl border border-blue-500/20">
                            <PieChart className="w-8 h-8 text-blue-400" />
                        </div>
                        {t('reportsDashboard.accountLedger.title')}
                    </h2>
                    <p className="text-slate-500 mt-2 font-medium">{t('reportsDashboard.accountLedger.subtitle')}</p>
                </div>

                <div className="flex flex-wrap items-center gap-3">
                    <div className="flex items-center gap-2 bg-white/5 px-4 py-2.5 rounded-2xl border border-white/10">
                        <Search className="w-4 h-4 text-slate-600" />
                        <select
                            value={selectedAccount}
                            onChange={(e) => setSelectedAccount(e.target.value)}
                            className="bg-transparent text-white text-xs font-black focus:outline-none cursor-pointer max-w-[200px]"
                        >
                            {accounts.map(acc => (
                                <option key={acc.account_code} value={acc.account_code} className="bg-slate-900 text-white">
                                    {acc.number ? `${acc.number} - ` : ''}{acc.account_code} - {acc.account_name}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div className="flex items-center gap-2 bg-white/5 px-4 py-2.5 rounded-2xl border border-white/10">
                        <Calendar className="w-4 h-4 text-blue-400" />
                        <input
                            type="date"
                            value={dateRange.from}
                            onChange={(e) => setDateRange(prev => ({ ...prev, from: e.target.value }))}
                            className="bg-transparent text-white text-xs font-black focus:outline-none underline decoration-blue-500/30"
                        />
                        <span className="text-slate-600 text-xs uppercase font-black">{t('reportsDashboard.accountLedger.dateFrom') || 'TO'}</span>
                        <input
                            type="date"
                            value={dateRange.to}
                            onChange={(e) => setDateRange(prev => ({ ...prev, to: e.target.value }))}
                            className="bg-transparent text-white text-xs font-black focus:outline-none underline decoration-blue-500/30"
                        />
                    </div>

                    <button onClick={loadData} className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/10 transition-colors">
                        <RefreshCw className={`w-5 h-5 text-slate-500 ${loading ? 'animate-spin' : ''}`} />
                    </button>
                </div>
            </div>

            {data && data.account && (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    {/* Info Cards */}
                    <div className="lg:col-span-12 grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="card-elite !p-6 flex flex-col justify-between border-l-4 border-l-blue-500">
                            <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{t('reportsDashboard.accountLedger.startingBalance')}</span>
                            <div className="text-2xl font-black text-white mt-1">{formatCurrency(data.startingBalance)}</div>
                        </div>
                        <div className="card-elite !p-6 flex flex-col justify-between border-l-4 border-l-emerald-500">
                            <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{t('reportsDashboard.accountLedger.netMovements')}</span>
                            <div className="text-2xl font-black text-emerald-400 mt-1">{formatCurrency(data.totalDebit - data.totalCredit)}</div>
                        </div>
                        <div className="card-elite !p-6 flex flex-col justify-between border-l-4 border-l-white">
                            <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{t('reportsDashboard.accountLedger.endingBalance')}</span>
                            <div className="text-2xl font-black text-white mt-1">{formatCurrency(data.endingBalance)}</div>
                        </div>
                    </div>

                    {/* Ledger Table */}
                    <div className="lg:col-span-8">
                        <div className="card-elite !p-0">
                            <div className="p-6 border-b border-white/5 flex justify-between items-center">
                                <h3 className="text-table-header">{t('reportsDashboard.accountLedger.ledgerTitle')}</h3>
                                <div className="flex items-center gap-2">
                                    <span className="badge-elite bg-blue-500/10 text-blue-400 border-blue-500/20">{data.account.number || data.account.account_code}</span>
                                    <span className="text-xs font-black text-white">{data.account.account_name}</span>
                                </div>
                            </div>

                            <div className="overflow-x-auto">
                                <table className="w-full text-left">
                                    <thead className="bg-white/5">
                                        <tr className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                                            <th className="px-6 py-4">{t('common.date')}</th>
                                            <th className="px-6 py-4">{t('accounting.reference') || 'Referencia'}</th>
                                            <th className="px-6 py-4">{t('common.description')}</th>
                                            <th className="px-6 py-4 text-right">{t('accounting.debit')}</th>
                                            <th className="px-6 py-4 text-right">{t('accounting.credit')}</th>
                                            <th className="px-6 py-4 text-right">{t('accounting.balance') || 'Saldo'}</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-white/5">
                                        {data.transactions.map((tx: any, i: number) => (
                                            <tr key={i} className="hover:bg-white/5 transition-all group">
                                                <td className="px-6 py-4 text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">{tx.entry_date}</td>
                                                <td className="px-6 py-4 text-xs font-black text-blue-400 uppercase">{tx.reference || '---'}</td>
                                                <td className="px-6 py-4 text-xs text-white max-w-[250px] truncate" title={tx.description}>{tx.description}</td>
                                                <td className="px-6 py-4 text-right text-xs font-bold text-white">{tx.debit_amount > 0 ? formatCurrency(tx.debit_amount) : '---'}</td>
                                                <td className="px-6 py-4 text-right text-xs font-bold text-white">{tx.credit_amount > 0 ? formatCurrency(tx.credit_amount) : '---'}</td>
                                                <td className="px-6 py-4 text-right text-xs font-black text-emerald-400 tabular-nums">{formatCurrency(tx.running_balance)}</td>
                                            </tr>
                                        ))}

                                        {data.transactions.length === 0 && (
                                            <tr>
                                                <td colSpan={6} className="px-6 py-20 text-center">
                                                    <FileBarChart className="w-12 h-12 text-slate-700 mx-auto mb-4 opacity-20" />
                                                    <p className="text-slate-600 font-bold uppercase tracking-widest text-xs">{t('reportsDashboard.accountLedger.noMovements') || 'No movements in this period'}</p>
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                    <tfoot className="bg-white/5">
                                        <tr className="text-xs font-black text-white">
                                            <td colSpan={3} className="px-6 py-4 text-right uppercase tracking-widest text-slate-600">{t('reportsDashboard.accountLedger.periodTotals')}</td>
                                            <td className="px-6 py-4 text-right">{formatCurrency(data.totalDebit)}</td>
                                            <td className="px-6 py-4 text-right">{formatCurrency(data.totalCredit)}</td>
                                            <td className="px-6 py-4 text-right text-emerald-400">{formatCurrency(data.endingBalance)}</td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        </div>
                    </div>

                    {/* Export & Actions Side */}
                    <div className="lg:col-span-4 space-y-6">
                        <div className="card-elite !p-6">
                            <h3 className="text-table-header mb-6">{t('common.tools')}</h3>
                            <ReportExporter
                                data={getExportData()}
                                header={{
                                    title: t('reportsDashboard.accountLedger.ledgerTitle'),
                                    subtitle: `${data.account.account_code} - ${data.account.account_name}`,
                                    dateRange: `${dateRange.from} ${t('reportsDashboard.accountLedger.dateFrom')} ${dateRange.to}`
                                }}
                            />
                        </div>

                        <div className="card-elite !p-6 space-y-4">
                            <div className="flex items-center gap-3">
                                <ArrowLeftRight className="w-5 h-5 text-blue-400" />
                                <h3 className="text-sm font-black text-white uppercase tracking-widest">{t('reportsDashboard.accountLedger.nature')}</h3>
                            </div>
                            <div className="flex justify-between items-center text-xs">
                                <span className="text-slate-600">{t('reportsDashboard.accountLedger.normalBalance')}:</span>
                                <span className="badge-elite bg-blue-500/10 text-blue-400 uppercase">{data.account.normal_balance}</span>
                            </div>
                            <div className="flex justify-between items-center text-xs">
                                <span className="text-slate-600">{t('accounting.accountType')}:</span>
                                <span className="badge-elite bg-white/5 text-white uppercase">{data.account.account_type}</span>
                            </div>
