            case '31-60': return 'bg-sun-orange/10 text-sun-orange border-sun-orange/20';
            case '61-90': return 'bg-rose-500/10 text-rose-400 border-rose-500/20';
            case '90+': return 'bg-rose-600 text-white border-rose-600';
