import React, { useState } from 'react';
import { FileDown, FileText, Table as TableIcon, Share2, Printer, CheckCircle, AlertCircle } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { getCompanyData } from '@/database/simple-db';
import { getCompanyLogoUrl } from '../../utils/logoUtils';
import { logger } from '../../core/logging/SystemLogger';
import { useLocale } from '../../i18n/useLocale';

// Extend jsPDF with autotable types
declare module 'jspdf' {
    interface jsPDF {
        autoTable: (options: any) => jsPDF;
    }
}

interface ExportHeader {
    title: string;
    subtitle?: string;
    dateRange?: string;
    entityName?: string;
}

interface ExportData {
    headers: string[];
    rows: any[][];
    fileName: string;
    footer?: string[];
}

interface ReportExporterProps {
    data: ExportData;
    header: ExportHeader;
    variant?: 'minimal' | 'full';
}

export const ReportExporter: React.FC<ReportExporterProps> = ({ data, header, variant = 'full' }) => {
    const { t } = useLocale();
    const [exporting, setExporting] = useState<string | null>(null);
    const [status, setStatus] = useState<{ type: 'success' | 'error', msg: string } | null>(null);

    const showStatus = (type: 'success' | 'error', msg: string) => {
        setStatus({ type, msg });
        setTimeout(() => setStatus(null), 3000);
    };

    const exportToPDF = async () => {
        try {
            setExporting('pdf');
            const doc = new jsPDF({
                orientation: 'p',
                unit: 'mm',
                format: 'a4'
            });

            const company = getCompanyData();
            const logoUrl = getCompanyLogoUrl();

            // Header background
            doc.setFillColor(3, 7, 18); // deep-bg
            doc.rect(0, 0, 210, 40, 'F');

            // Logo or Name
            if (logoUrl) {
                try {
                    doc.addImage(logoUrl, 'PNG', 15, 10, 30, 20);
                } catch (e) {
                    doc.setTextColor(255, 255, 255);
                    doc.setFontSize(18);
                    doc.text(company?.company_name || 'AccountExpress', 15, 22);
                }
            } else {
                doc.setTextColor(255, 255, 255);
                doc.setFontSize(18);
                doc.text(company?.company_name || 'AccountExpress', 15, 22);
            }

            // Title and Subtitle
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(16);
            doc.text(header.title, 195, 20, { align: 'right' });

            doc.setFontSize(10);
            doc.setTextColor(156, 163, 175); // text-muted
            doc.text(header.subtitle || company?.legal_name || '', 195, 26, { align: 'right' });
            doc.text(header.dateRange || `${t('common.date')}: ${new Date().toLocaleDateString()}`, 195, 32, { align: 'right' });

            // Body Table
            doc.autoTable({
                startY: 45,
                head: [data.headers],
                body: data.rows,
                theme: 'striped',
                headStyles: {
                    fillColor: [16, 185, 129], // emerald-primary
                    textColor: [255, 255, 255],
                    fontSize: 10,
                    fontStyle: 'bold',
                    halign: 'left'
                },
                alternateRowStyles: { fillColor: [249, 250, 251] },
                styles: { fontSize: 9, cellPadding: 3 },
                margin: { left: 15, right: 15 },
                didDrawPage: (dataArg: any) => {
                    // Footer on each page
                    doc.setFontSize(8);
                    doc.setTextColor(156, 163, 175);
                    doc.text(
                        `${t('common.page') || 'Page'} ${dataArg.pageNumber} - AccountExpress Florida Compliance`,
                        105,
                        290,
                        { align: 'center' }
                    );
                }
            });

            doc.save(`${data.fileName}.pdf`);
            showStatus('success', t('reportsDashboard.common.pdfSuccess') || 'PDF generated successfully');
            logger.info('ReportExporter', 'pdf_success', `Exportado PDF: ${data.fileName}`);
        } catch (error) {
            console.error(error);
            showStatus('error', t('reportsDashboard.common.pdfError') || 'Error generating PDF');
            logger.error('ReportExporter', 'pdf_error', 'Fallo exportaci├│n PDF', null, error as Error);
        } finally {
            setExporting(null);
        }
    };

    const exportToExcel = () => {
        try {
            setExporting('excel');
            const ws = XLSX.utils.aoa_to_sheet([data.headers, ...data.rows]);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, 'Reporte');
            XLSX.writeFile(wb, `${data.fileName}.xlsx`);
            showStatus('success', t('reportsDashboard.common.excelSuccess') || 'Excel generated successfully');
            logger.info('ReportExporter', 'excel_success', `Exportado Excel: ${data.fileName}`);
        } catch (error) {
            showStatus('error', t('reportsDashboard.common.excelError') || 'Error generating Excel');
            logger.error('ReportExporter', 'excel_error', 'Fallo exportaci├│n Excel', null, error as Error);
        } finally {
            setExporting(null);
        }
    };

    if (variant === 'minimal') {
        return (
            <div className="flex gap-2">
                <button onClick={exportToPDF} title="PDF" className="p-2 hover:bg-white/10 rounded-lg text-rose-400">
                    <FileText className={`w-5 h-5 ${exporting === 'pdf' ? 'animate-pulse' : ''}`} />
                </button>
                <button onClick={exportToExcel} title="Excel" className="p-2 hover:bg-white/10 rounded-lg text-emerald-400">
                    <TableIcon className={`w-5 h-5 ${exporting === 'excel' ? 'animate-pulse' : ''}`} />
                </button>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            <div className="flex flex-wrap items-center gap-3">
                <button
                    onClick={exportToPDF}
                    disabled={!!exporting}
                    className="btn-elite-secondary !py-2 !px-4 flex items-center gap-2 text-sm"
                >
                    <FileText className={`w-4 h-4 text-rose-400 ${exporting === 'pdf' ? 'animate-spin' : ''}`} />
                    {t('common.export')} PDF
                </button>

                <button
                    onClick={exportToExcel}
                    disabled={!!exporting}
                    className="btn-elite-secondary !py-2 !px-4 flex items-center gap-2 text-sm"
                >
                    <TableIcon className={`w-4 h-4 text-emerald-400 ${exporting === 'excel' ? 'animate-spin' : ''}`} />
                    {t('common.export')} Excel
                </button>

                <button
                    onClick={() => window.print()}
                    className="btn-elite-secondary !py-2 !px-4 flex items-center gap-2 text-sm"
                >
                    <Printer className="w-4 h-4 text-blue-400" />
                    {t('common.print') || 'Print'}
                </button>
            </div>

            {status && (
                <div className={`flex items-center gap-2 text-xs font-black uppercase tracking-widest animate-fade-in ${status.type === 'success' ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {status.type === 'success' ? <CheckCircle className="w-3.5 h-3.5" /> : <AlertCircle className="w-3.5 h-3.5" />}
                    {status.msg}
                </div>
            )}
        </div>
    );
};

/**
 * System Integrity Gate - El Portero
 * Verifica la integridad del sistema antes de permitir el acceso
 * Nivel NASA: No permite continuar si hay problemas cr├¡ticos
 */

import React, { useEffect, useState } from 'react';
import { IntegrityService } from '../../services/integrity/IntegrityService';
import { SystemIntegrityReport } from '../../types/integrity.types';
import { SystemRepairPanel } from './SystemRepairPanel';
import { SystemWarningBanner } from './SystemWarningBanner';
import { Loader2, Shield } from 'lucide-react';
import { useLocale } from '../../i18n/useLocale';

interface Props {
    children: React.ReactNode;
}

export const SystemIntegrityGate: React.FC<Props> = ({ children }) => {
    const { t } = useLocale();
    const [checking, setChecking] = useState(true);
    const [report, setReport] = useState<SystemIntegrityReport | null>(null);
    const [repairing, setRepairing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showWarningBanner, setShowWarningBanner] = useState(true);
    const [showWarningDetails, setShowWarningDetails] = useState(false);

    useEffect(() => {
        runIntegrityChecks();
    }, []);

    const runIntegrityChecks = async () => {
        setChecking(true);
        setError(null);

        try {
            const service = new IntegrityService();
            // Timeout de 5s ΓÇö si el check se cuelga (BackupService, etc.) la app sigue funcionando
            const timeoutResult: SystemIntegrityReport = {
                timestamp: new Date().toISOString(),
                overallStatus: 'healthy',
                checks: [],
                criticalFailures: 0,
                warnings: 0
            };
            const timeoutPromise = new Promise<SystemIntegrityReport>(
                resolve => setTimeout(() => resolve(timeoutResult), 5000)
            );
            const result = await Promise.race([service.runAllChecks(), timeoutPromise]);
            setReport(result);
        } catch (err) {
            setError((err as Error).message);
        } finally {
            setChecking(false);
        }
    };

    const handleRepair = async (checkId: string) => {
        if (!report) return;

        setRepairing(true);
        try {
            const service = new IntegrityService();
            const success = await service.repairCheck(checkId);

            // Si se repar├│ exitosamente, recargar la p├ígina
            if (success) {
                setTimeout(() => {
                    window.location.reload();
                }, 1000);
            } else {
                // Si no se pudo reparar, re-ejecutar verificaciones
                await runIntegrityChecks();
                setRepairing(false);
            }
        } catch (err) {
            setError(`Error reparando: ${(err as Error).message}`);
            setRepairing(false);
        }
    };

    const handleRepairAll = async () => {
        if (!report) return;

        setRepairing(true);
        try {
            const service = new IntegrityService();
            const result = await service.repairAll();

            // Si se repar├│ al menos un check, recargar la p├ígina para reinicializar todo
            if (result.repaired > 0) {
                // Mostrar mensaje de ├⌐xito antes de recargar
                setTimeout(() => {
                    window.location.reload();
                }, 1000);
            } else {
                // Si no se pudo reparar nada, re-ejecutar verificaciones
                await runIntegrityChecks();
            }
        } catch (err) {
            setError(`Error reparando sistema: ${(err as Error).message}`);
            setRepairing(false);
        }
    };

    // Pantalla de carga inicial
    if (checking) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 flex items-center justify-center">
                <div className="text-center">
                    <Shield className="w-20 h-20 text-blue-400 mx-auto mb-4 animate-pulse" />
                    <h2 className="text-2xl font-black tracking-tight text-white mb-2">{t('security.messages.verifyingIntegrity')}</h2>
                    <p className="text-blue-300 mb-4">{t('security.messages.nasaLevel')}</p>
                    <Loader2 className="w-8 h-8 text-blue-400 animate-spin mx-auto" />
                </div>
            </div>
        );
    }

    // Error fatal
    if (error && !report) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-red-900 via-red-800 to-slate-900 flex items-center justify-center p-4">
                <div className="max-w-md bg-white rounded-2xl shadow-2xl p-8 text-center">
                    <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Shield className="w-10 h-10 text-red-600" />
                    </div>
                    <h2 className="text-2xl font-black tracking-tight text-gray-900 mb-2">{t('security.messages.criticalError')}</h2>
                    <p className="text-slate-700 mb-6">{error}</p>
                    <button
                        onClick={runIntegrityChecks}
                        className="px-6 py-3 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 transition-colors"
                    >
                        {t('security.actions.retry')}
                    </button>
                </div>
            </div>
        );
    }

    // Sistema con problemas cr├¡ticos
    if (report && report.overallStatus === 'critical') {
        return (
            <SystemRepairPanel
                report={report}
                onRepair={handleRepair}
                onRepairAll={handleRepairAll}
                onRetry={runIntegrityChecks}
                repairing={repairing}
            />
        );
    }

    // Sistema con advertencias (permitir continuar pero mostrar aviso)
    if (report && report.overallStatus === 'degraded') {
        // Si el usuario quiere ver detalles, mostrar el panel completo
        if (showWarningDetails) {
            return (
                <SystemRepairPanel
                    report={report}
                    onRepair={handleRepair}
                    onRepairAll={handleRepairAll}
                    onRetry={runIntegrityChecks}
                    repairing={repairing}
                    allowContinue={true}
                    onContinue={() => setShowWarningDetails(false)}
                />
            );
        }

        // Mostrar banner de advertencia en la parte superior
        return (
            <>
                {showWarningBanner && (
                    <SystemWarningBanner
                        report={report}
                        onDismiss={() => setShowWarningBanner(false)}
                        onViewDetails={() => setShowWarningDetails(true)}
                    />
                )}
                {children}
            </>
        );
    }

    // Sistema saludable - permitir acceso
    return <>{children}</>;
};

/**
 * Check 1: Integridad Estructural del Schema
 * Verifica que todas las tablas cr├¡ticas existan
 */

import { IntegrityCheck, CheckResult } from '../../../types/integrity.types';
import { getDB } from '@/database/simple-db';

export class SchemaIntegrityCheck implements IntegrityCheck {
    id = 'schema-integrity';
    name = 'Integridad Estructural';
    description = 'Verifica que todas las tablas cr├¡ticas del sistema existan';
    severity = 'critical' as const;
    status = 'pending' as const;

    private readonly CRITICAL_TABLES = [
        'journal_entries',
        'audit_chain',
        'florida_tax_rates',
        'tax_transactions',
        'users',
        'user_roles',
        'customers',
        'suppliers',
        'invoices',
        'bills',
        'products',
        'fixed_assets',
        'asset_depreciation',
        'sys_migrations'
    ];

    async execute(): Promise<CheckResult> {
        const db = getDB();

        if (!db) {
            return {
                passed: false,
                message: 'Base de datos no inicializada',
                canAutoRepair: true,
                repairAction: async () => {
                    const { SchemaRepairService } = await import('../../../database/SchemaRepairService');
                    const { getDBEngine } = await import('../../../database/simple-db');

                    try {
                        // Usar la instancia ├║nica del motor que gestiona la persistencia real
                        const engine = getDBEngine();
                        const repair = new SchemaRepairService(engine);
                        await repair.repairSchema();

                        // Forzar sincronizaci├│n si es necesaria
                        if (typeof engine.sync === 'function') {
                            await engine.sync();
                        }
                    } catch (e) {
                        // Fallback si el motor no est├í inicializado (raro en arranque, pero posible)
                        console.warn('DB Engine not ready, trying init...', e);
                        const { initDB } = await import('../../../database/simple-db');
                        const { SQLiteEngine } = await import('../../../core/database/SQLiteEngine');

                        await initDB();
                        // Re-intentar obtener el motor
                        const engine = getDBEngine();
                        const repair = new SchemaRepairService(engine);
                        await repair.repairSchema();
                        if (typeof engine.sync === 'function') await engine.sync();
                    }

                    // Esperar un momento para asegurar que IndexedDB termine
                    await new Promise(resolve => setTimeout(resolve, 1000));
                }
            };
        }

        try {
            const result = db.exec(`
                SELECT name FROM sqlite_master 
                WHERE type='table' AND name NOT LIKE 'sqlite_%'
            `);

            const existingTables = result[0]?.values.map((row: any) => row[0] as string) || [];
            const missingTables = this.CRITICAL_TABLES.filter(
                table => !existingTables.includes(table)
            );

            if (missingTables.length === 0) {
                return {
                    passed: true,
                    message: `Γ£à Todas las ${this.CRITICAL_TABLES.length} tablas cr├¡ticas existen`,
                    canAutoRepair: false
                };
            }

            return {
                passed: false,
                message: `Γ¥î Faltan ${missingTables.length} tablas cr├¡ticas`,
                details: {
                    missingTables,
                    existingTables: existingTables.length,
                    requiredTables: this.CRITICAL_TABLES.length
                },
                canAutoRepair: true,
                repairAction: async () => {
                    const { SchemaRepairService } = await import('../../../database/SchemaRepairService');
                    const { getDBEngine, initDB } = await import('../../../database/simple-db');

                    try {
                        let engine;
                        try {
                            engine = getDBEngine();
                        } catch (e) {
                            await initDB();
                            engine = getDBEngine();
                        }

                        const repair = new SchemaRepairService(engine);
                        await repair.repairSchema();

                        // CR├ìTICO: Forzar persistencia
                        if (typeof engine.sync === 'function') {
                            await engine.sync();
                        }

                        // Forzar exportaci├│n explicita a IndexedDB
                        try {
                            const { forceSaveDB } = await import('../../../database/simple-db');
                            if (forceSaveDB) await forceSaveDB();
                        } catch (e) {
                            console.warn('Force save failed', e);
                        }
                    } catch (e) {
                        console.error("Critical Repair Fail", e);
                    }

                    // Esperar un momento para asegurar que IndexedDB termine
                    await new Promise(resolve => setTimeout(resolve, 1000));
                }
            };
        } catch (error) {
            return {
                passed: false,
                message: `Γ¥î Error verificando schema: ${(error as Error).message}`,
                canAutoRepair: false
            };
        }
    }
}

import React, { useState, useEffect } from 'react';
import { RecoveryService, BackupMetadata } from '../../services/RecoveryService';
import { useLocale } from '@/i18n/useLocale';

/**
 * BackupRecoveryPanel Component (Iron Clad Upgrade - Phase 1, Day 6)
 * 
 * UI for restoring database from cloud or local backups.
 * Features:
 * - List available cloud backups
 * - Restore from cloud with progress
 * - Restore from local file
 * - Safety backup before restoration
 * - Recovery statistics
 */

export function BackupRecoveryPanel() {
    const { t, language } = useLocale();
    const [backups, setBackups] = useState<BackupMetadata[]>([]);
    const [loading, setLoading] = useState(false);
    const [restoring, setRestoring] = useState(false);
    const [progress, setProgress] = useState({ percent: 0, message: '' });
    const [stats, setStats] = useState<any>(null);

    useEffect(() => {
        loadBackups();
        loadStats();
    }, []);

    const loadBackups = async () => {
        setLoading(true);
        try {
            const availableBackups = await RecoveryService.listAvailableBackups();
            setBackups(availableBackups);
        } catch (error: any) {
            console.error('Error loading backups:', error);
            alert(`Γ¥î ${t('settings.restoreError')}: ${error.message}`);
        } finally {
            setLoading(false);
        }
    };

    const loadStats = async () => {
        try {
            const recoveryStats = await RecoveryService.getRecoveryStats();
            setStats(recoveryStats);
        } catch (error) {
            console.error('Error loading stats:', error);
        }
    };

    const restoreFromCloud = async (filename: string) => {
        const confirmed = window.confirm(
            `ΓÜá∩╕Å ${t('settings.securityWarning').toUpperCase()}: ${t('settings.overwriteWarning')}\n\n` +
            `${t('settings.backupPrompt')}\n\n` +
            `┬┐${t('settings.restoreAction')} ${filename}?`
        );

        if (!confirmed) return;

        setRestoring(true);
        setProgress({ percent: 0, message: t('settings.restoringHint') });

        try {
            await RecoveryService.restoreFromCloud(filename, {
                skipSafetyBackup: false,
                onProgress: (percent, message) => {
                    setProgress({ percent, message });
                }
            });

            alert(`Γ£à ${t('settings.restoreSuccess')}!\n\nLa aplicaci├│n se recargar├í.`);
            window.location.reload();

        } catch (error: any) {
            alert(`Γ¥î ${t('settings.restoreError')}:\n\n${error.message}`);
        } finally {
            setRestoring(false);
            setProgress({ percent: 0, message: '' });
        }
    };

    const restoreFromFiles = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFiles = Array.from(event.target.files || []);
        if (selectedFiles.length === 0) return;

        const fileNames = selectedFiles.map(f => f.name).join(', ');
        const confirmed = window.confirm(
            `ΓÜá∩╕Å ${t('settings.securityWarning').toUpperCase()}: ${t('settings.overwriteWarning')}\n\n` +
            `${t('settings.backupPrompt')}\n\n` +
            `┬┐${t('settings.restoreAction')} ${fileNames}?`
        );

        if (!confirmed) {
            event.target.value = ''; // Reset file input
            return;
        }

        setRestoring(true);
        try {
            for (const file of selectedFiles) {
                setProgress({ percent: 0, message: `${t('settings.restoringHint')}: ${file.name}` });
                await RecoveryService.restoreFromFile(file, {
                    skipSafetyBackup: false,
                    onProgress: (percent, message) => {
                        setProgress({ percent, message: `${file.name}: ${message}` });
                    }
                });
            }

            alert(`Γ£à ${t('settings.restoreSuccess')}!\n\nLa aplicaci├│n se recargar├í.`);
            window.location.reload();

        } catch (error: any) {
            alert(`Γ¥î ${t('settings.restoreError')}:\n\n${error.message}`);
        } finally {
            setRestoring(false);
            setProgress({ percent: 0, message: '' });
            event.target.value = ''; // Reset file input
        }
    };

    const formatFileSize = (bytes: number): string => {
        if (bytes < 1024) return `${bytes} B`;
        if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
        return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    };

    const formatDate = (date: Date): string => {
        return new Intl.DateTimeFormat(language === 'es' ? 'es-ES' : 'en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        }).format(date);
    };

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <h2 style={styles.title}>≡ƒöä {t('settings.recovery')}</h2>
                <p style={styles.subtitle}>
                    {t('settings.subtitle')}
                </p>
            </div>

            {stats && (
                <div style={styles.statsBox}>
                    <div style={styles.stat}>
                        <span style={styles.statLabel}>{t('settings.availableBackups')}</span>
                        <span style={styles.statValue}>{stats.cloudBackupsAvailable}</span>
                    </div>
                    <div style={styles.stat}>
                        <span style={styles.statLabel}>{t('settings.lastSync')}:</span>
                        <span style={styles.statValue}>
                            {stats.latestBackup ? formatDate(stats.latestBackup.created) : 'N/A'}
                        </span>
                    </div>
                    <div style={styles.stat}>
                        <span style={styles.statLabel}>{t('settings.hasSafetyBackup')}</span>
                        <span style={styles.statValue}>
                            {stats.hasSafetyBackup ? `Γ£à ${t('settings.available')}` : `Γ¥î ${t('settings.notAvailable')}`}
                        </span>
                    </div>
                </div>
            )}

            {restoring && (
                <div style={styles.progressBox}>
                    <div style={styles.progressBar}>
                        <div style={{ ...styles.progressFill, width: `${progress.percent}%` }}></div>
                    </div>
                    <p style={styles.progressText}>
                        {progress.message} ({progress.percent}%)
                    </p>
                </div>
            )}

            <div style={styles.section}>
                <div style={styles.sectionHeader}>
                    <h3 style={styles.sectionTitle}>Γÿü∩╕Å {t('settings.backup')}</h3>
                    <button
                        onClick={loadBackups}
                        disabled={loading || restoring}
                        style={{ ...styles.button, ...styles.buttonSmall }}
                    >
                        {loading ? `≡ƒöä ${t('settings.update')}...` : `≡ƒöä ${t('settings.update')}`}
                    </button>
                </div>

                {loading ? (
                    <p style={styles.loadingText}>{t('settings.loadingBackups')}</p>
                ) : backups.length === 0 ? (
                    <div style={styles.emptyState}>
                        <p style={styles.emptyText}>
                            ≡ƒô¡ {t('settings.noBackups')}
                        </p>
                        <small style={styles.emptyHint}>
                            {t('settings.noBackupsHint')}
                        </small>
                    </div>
                ) : (
                    <div style={styles.backupList}>
                        {backups.map((backup, index) => (
                            <div key={backup.filename} style={styles.backupItem}>
                                <div style={styles.backupInfo}>
                                    <div style={styles.backupName}>
                                        {index === 0 && <span style={styles.badge}>{t('settings.mostRecent')}</span>}
                                        ≡ƒôª {backup.filename}
                                    </div>
                                    <div style={styles.backupMeta}>
                                        <span>{formatDate(backup.created)}</span>
                                        <span>ΓÇó</span>
                                        <span>{formatFileSize(backup.size)}</span>
                                    </div>
                                </div>
                                <button
                                    onClick={() => restoreFromCloud(backup.filename)}
                                    disabled={restoring}
                                    style={{ ...styles.button, ...styles.buttonPrimary }}
                                >
                                    ≡ƒöä {t('settings.restoreAction')}
                                </button>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div style={styles.divider}></div>

            <div style={styles.section}>
                <h3 style={styles.sectionTitle}>≡ƒÆ╛ {t('settings.restoreLocal')}</h3>
                <p style={styles.sectionText}>
                    {t('settings.loadBackup')}
                </p>
                <label style={styles.fileInputLabel}>
                    <input
                        type="file"
                        accept=".aex"
                        multiple
                        onChange={restoreFromFiles}
                        disabled={restoring}
                        style={styles.fileInput}
                    />
                    <span style={{ ...styles.button, ...styles.buttonSecondary }}>
                        ≡ƒôü {t('settings.selectFile')}
                    </span>
                </label>
            </div>

            <div style={styles.warningBox}>
                <h4 style={styles.warningTitle}>ΓÜá∩╕Å {t('settings.securityWarning')}</h4>
                <ul style={styles.warningList}>
                    {t<string[]>('settings.warningItems').map((item, i) => (
                        <li key={i}>{item}</li>
                    ))}
                </ul>
            </div>
        </div>
    );
}

