interface TaxRate {
  id: number;
  tax_year: number;
  rate_key: string;
  rate_value: number;
  description: string;
}

export const TaxRatesAdmin: React.FC = () => {
  const [rates, setRates] = useState<TaxRate[]>([]);

  useEffect(() => {
    const load = async () => {
      if (!dbEngine) return;
      const result = await dbEngine.select(
        'SELECT * FROM tax_rates_config ORDER BY tax_year DESC, rate_key ASC'
      );
      setRates(result as TaxRate[]);
    };
    load();
  }, []);

  return (
    <div className="p-6">
      <h2 className="text-xl font-bold text-gray-800 mb-4">Tasas Fiscales por A├▒o</h2>
