export const getNavigationPath = (targetId: string, lang: 'es' | 'en' = 'es'): string => {
    const findPath = (items: MenuItemConfig[], parentLabel?: string): string | null => {
        for (const item of items) {
            if (item.id === targetId) {
                return parentLabel ? `${parentLabel} > ${item.id}` : item.id;
            }
            if (item.children) {
                const result = findPath(item.children, item.id);
                if (result) return result;
            }
        }
        return null;
    };

    return findPath(NAVIGATION_CONFIG) || targetId;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { translationEngine } from '@/features/i18n/TranslationEngine';
import { useLanguage } from '@/i18n/LanguageContext';
import UserService from '../services/UserService';
import { createUser, getUserByUsername, hasUsers } from '@/database/simple-db';
import type { User as DBUser } from '../types/user.types';

interface User {
    id: number;
    username: string;
    email: string;
    full_name: string;
    display_name: string;
    role: string;
    role_id: number;
    role_level?: number;
    permissions?: Record<string, string[]>;
    googleId?: string;
    picture?: string;
}

interface GoogleUserInfo {
    email: string;
    name: string;
    picture: string;
    sub: string;
}

interface AuthContextType {
    user: User | null;
    login: (username: string, password: string) => Promise<boolean>;
    loginWithGoogle: (googleUser: GoogleUserInfo) => Promise<boolean>;
    logout: () => void;
    isAuthenticated: boolean;
    refreshUser: () => Promise<void>;
    hasPermission: (module: string, action: string) => boolean;
    checkSystemHasUsers: () => boolean;
    forceAdminBypass: () => void;
}


const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);

    // Verificar sesi├│n guardada al cargar
    useEffect(() => {
        const savedData = localStorage.getItem('accountexpress_user');
        if (savedData) {
            try {
                const parsed = JSON.parse(savedData);

                // Check format: New (with expiry) or Legacy (active user)
                if (parsed.expiresAt) {
                    if (Date.now() < parsed.expiresAt) {
                        setUser(parsed.user);
                    } else {
                        console.warn('Session expired (8h limit).');
                        localStorage.removeItem('accountexpress_user');
                    }
                } else if (parsed.id) { // Legacy user object
                    // Migrate legacy session to 8h expiry
                    setUser(parsed);
                    const sessionData = {
                        user: parsed,
                        expiresAt: Date.now() + 8 * 60 * 60 * 1000
                    };
                    localStorage.setItem('accountexpress_user', JSON.stringify(sessionData));
                }
            } catch (error) {
                console.error('Error loading saved session:', error);
                localStorage.removeItem('accountexpress_user');
            }
        }
    }, []);

    const login = async (username: string, password: string): Promise<boolean> => {
        try {
            // Autenticar con UserService (base de datos real)
            // NOTA: Los accesos hardcodeados (demo/admin) han sido eliminados por pol├¡tica de seguridad (NIST/ISO 27001).
            // Todo acceso debe pasar por la base de datos cifrada o OAuth2.
            const result = await UserService.authenticateUser(username, password);

            if (result.success && result.data) {
                const dbUser = result.data;

                // Mapear usuario de BD a formato de AuthContext
                const userData: User = {
                    id: dbUser.id,
                    username: dbUser.username,
                    email: dbUser.email,
                    full_name: dbUser.full_name,
                    display_name: dbUser.display_name,
                    role: dbUser.role_name || 'user',
                    role_id: dbUser.role_id,
                    role_level: dbUser.role_level,
                    permissions: (dbUser as any).permissions_json ? JSON.parse((dbUser as any).permissions_json) : {}
                };

                setUser(userData);
                localStorage.setItem('accountexpress_user', JSON.stringify({
                    user: userData,
                    expiresAt: Date.now() + 8 * 60 * 60 * 1000
                }));
                return true;
            }

            return false;
        } catch (error) {
            console.error('Login error:', error);
            return false;
        }
    };

    const loginWithGoogle = async (googleUser: GoogleUserInfo): Promise<boolean> => {
        try {
            console.log('Procesando login de Google:', googleUser);

            // Buscar si el usuario ya existe por email
            const existingUser = getUserByUsername(googleUser.email);

            if (existingUser) {
                // Usuario existe, hacer login
                const userData: User = {
                    id: existingUser.id,
                    username: existingUser.username,
                    email: existingUser.email,
                    full_name: existingUser.full_name,
                    display_name: existingUser.display_name,
                    role: existingUser.role_name || 'user',
                    role_id: existingUser.role_id,
                    role_level: existingUser.role_level,
                    permissions: (existingUser as any).permissions_json ? JSON.parse((existingUser as any).permissions_json) : {},
                    googleId: googleUser.sub,
                    picture: googleUser.picture
                };

                setUser(userData);
                localStorage.setItem('accountexpress_user', JSON.stringify({
                    user: userData,
                    expiresAt: Date.now() + 8 * 60 * 60 * 1000
                }));
                return true;
            } else {
                // Usuario no existe, determinar rol seg├║n si es el primer usuario
                const roles = UserService.getRoles();
                const isFirstUser = !hasUsers();

                // Si es el primer usuario ΓåÆ Admin, si no ΓåÆ Vendedor
                let assignedRole;
                if (isFirstUser) {
                    assignedRole = roles.find(r => r.name === 'admin');
                    console.log('≡ƒÄ» Primer usuario del sistema - Asignando rol de Administrador');
                } else {
                    assignedRole = roles.find(r => r.name === 'vendedor');
                    console.log('≡ƒæñ Usuario adicional - Asignando rol de Vendedor');
                }

                // Fallback a viewer si no se encuentra el rol
                if (!assignedRole) {
                    assignedRole = roles.find(r => r.name === 'viewer') || roles[roles.length - 1];
                }

                if (!assignedRole) {
                    console.error('No hay roles disponibles en el sistema');
                    return false;
                }

                // Crear usuario nuevo
                console.log('≡ƒô¥ Creando usuario de Google:', {
                    email: googleUser.email,
                    name: googleUser.name,
                    role: assignedRole.name
                });

                const result = await createUser({
                    username: googleUser.email,
                    email: googleUser.email,
                    full_name: googleUser.name,
                    password: `google_${googleUser.sub}_${Date.now()}`, // Password aleatorio (no se usar├í)
                    display_name: googleUser.name,
                    role_id: assignedRole.id,
                    picture: googleUser.picture
                });

                console.log('≡ƒôè Resultado de creaci├│n de usuario:', result);

                if (result.success && result.userId) {
                    const userData: User = {
                        id: result.userId,
                        username: googleUser.email,
                        email: googleUser.email,
                        full_name: googleUser.name,
                        display_name: googleUser.name,
                        role: assignedRole.name,
                        role_id: assignedRole.id,
                        role_level: assignedRole.level,
                        permissions: assignedRole.permissions_json ? JSON.parse(assignedRole.permissions_json) : {},
                        googleId: googleUser.sub,
                        picture: googleUser.picture
                    };

                    setUser(userData);
                    localStorage.setItem('accountexpress_user', JSON.stringify({
                        user: userData,
                        expiresAt: Date.now() + 8 * 60 * 60 * 1000
                    }));

                    // Sync Language Preference for New Users - Forzado a ES
                    translationEngine.setLanguage('es');
                    console.log(`≡ƒîì Idioma sincronizado: es`);

                    console.log(`Γ£à Usuario de Google creado exitosamente con rol: ${assignedRole.name}`, userData);
                    return true;
                }

                // Si la creaci├│n falla, propagar el error
                console.error('Γ¥î Error al crear usuario de Google:', {
                    mensaje: result.message,
                    datos: { email: googleUser.email, role: assignedRole.name }
                });
                throw new Error(result.message || 'Error desconocido al crear usuario');
            }
        } catch (error) {
            console.error('Γ¥î CRITICAL: Error en login de Google:', error);
            // Propagar el error para que LoginForm lo muestre
            throw error;
        }
    };

    const checkSystemHasUsers = () => {
        return hasUsers();
    };

    const forceAdminBypass = () => {
        const userData: User = {
            id: 1,
            username: 'admin',
            email: 'admin@dev.local',
            full_name: 'Super Administrador (Bypass)',
            display_name: 'Admin Global',
            role: 'admin',
            role_id: 1,
            role_level: 100,
            permissions: {}
        };
        setUser(userData);
        localStorage.setItem('accountexpress_user', JSON.stringify({
            user: userData,
            expiresAt: Date.now() + 8 * 60 * 60 * 1000
        }));
        console.warn('ΓÜá∩╕Å DEV BYPASS ACTIVATED - Logged in as Admin');
    };




    const logout = () => {
        try {
            setUser(null);
            localStorage.removeItem('accountexpress_user');
            localStorage.removeItem('gdrive_token'); // Ensure this is also cleared

            // Clear everything else
            localStorage.clear();
            sessionStorage.clear();

            console.log('Sesi├│n cerrada correctamente');
        } catch (error) {
            console.error('Error durante cierre de sesi├│n:', error);
        } finally {
            // Force hard reload to login page
            window.location.href = '/';
            // Fallback reload if router doesn't pick it up
            setTimeout(() => {
                window.location.reload();
            }, 100);
        }
    };

    const refreshUser = async () => {
        if (!user) return;

        try {
            const dbUser = UserService.getUserByUsername(user.username);
            if (dbUser) {
                const userData: User = {
                    id: dbUser.id,
                    username: dbUser.username,
                    email: dbUser.email,
                    full_name: dbUser.full_name,
                    display_name: dbUser.display_name,
                    role: dbUser.role_name || 'user',
                    role_id: dbUser.role_id,
                    role_level: dbUser.role_level,
                    permissions: (dbUser as any).permissions_json ? JSON.parse((dbUser as any).permissions_json) : {},
                    googleId: user.googleId,
                    picture: user.picture
                };
                setUser(userData);
                localStorage.setItem('accountexpress_user', JSON.stringify(userData));
            }
        } catch (error) {
            console.error('Error refreshing user:', error);
        }
    };

    const hasPermission = (module: string, action: string): boolean => {
        if (!user || !user.permissions) return false;
        if (user.role === 'admin') return true;

        const modulePerms = user.permissions[module];
        if (!modulePerms) return false;

        return modulePerms.includes(action);
    };

    return (
        <AuthContext.Provider value={{
            user,
            login,
            loginWithGoogle,
            checkSystemHasUsers,
            logout,
            isAuthenticated: !!user,
            refreshUser,
            hasPermission,
            forceAdminBypass
        }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth debe usarse dentro de AuthProvider');
    }
    return context;
};

import { logger } from './logging/SystemLogger';

/**
 * SERVICIO DE LIMPIEZA NUCLEAR
 * Elimina todos los rastros de datos para permitir un inicio desde cero absoluto.
 */
export class NuclearCleanExecution {
    static async execute(): Promise<void> {
        logger.emergency('System', 'nuclear_clean_start', 'Γÿó∩╕Å INICIANDO LIMPIEZA NUCLEAR COMPLETA');

        try {
            // 1. Limpiar LocalStorage
            localStorage.clear();
            logger.info('System', 'storage_clear', 'LocalStorage eliminado');

            // 2. Limpiar SessionStorage
            sessionStorage.clear();
            logger.info('System', 'session_clear', 'SessionStorage eliminado');

            // 3. Eliminar IndexedDB
            const dbs = await window.indexedDB.databases();
            for (const dbInfo of dbs) {
                if (dbInfo.name) {
                    window.indexedDB.deleteDatabase(dbInfo.name);
                }
            }
            logger.info('System', 'idb_clear', 'Bases de datos IndexedDB eliminadas');

            // 4. Eliminar archivos SQLite en OPFS
            if (typeof navigator !== 'undefined' && navigator.storage && 'getDirectory' in navigator.storage) {
                const opfsRoot = await navigator.storage.getDirectory();
                try {
                    await opfsRoot.removeEntry('accountexpress.db');
                    logger.success('System', 'opfs_clear', 'Archivo SQLite eliminado de OPFS');
                } catch (e) {
                    logger.debug('System', 'opfs_skip', 'No se encontr├│ archivo en OPFS para eliminar');
                }
            }

            // 5. Desregistrar Service Workers
            if ('serviceWorker' in navigator) {
                const registrations = await navigator.serviceWorker.getRegistrations();
                for (const reg of registrations) {
                    await reg.unregister();
                }
                logger.info('System', 'sw_clear', 'Service Workers desregistrados');
            }

            // 6. Limpiar Caches de la API del Navegador
            if ('caches' in window) {
                const cacheNames = await caches.keys();
                for (const name of cacheNames) {
                    await caches.delete(name);
                }
                logger.info('System', 'cache_clear', 'Caches del navegador eliminadas');
            }

            logger.success('System', 'nuclear_clean_success', 'Γÿó∩╕Å LIMPIEZA NUCLEAR COMPLETADA CON ├ëXITO');

        } catch (error: any) {
            logger.critical('System', 'nuclear_clean_failed', 'Fallo en la limpieza nuclear', { error: error.message });
            throw error;
        }
    }
}

/**
 * ARQUITECTURA MULTICAPA - RESILIENT STORAGE
 * 
 * Sistema de almacenamiento resiliente con m├║ltiples capas de fallback
 */

export interface StorageLayer {
  name: string;
  available: boolean;
  priority: number;
  read(key: string): Promise<any>;
  write(key: string, data: any): Promise<void>;
  delete(key: string): Promise<void>;
}

export class ResilientStorage {
  private layers: StorageLayer[] = [];

  constructor() {
    this.initializeLayers();
  }

  private initializeLayers() {
    // Capa 1: OPFS (Origin Private File System)
    this.layers.push({
      name: 'OPFS',
      available: 'navigator' in globalThis && 'storage' in navigator,
      priority: 1,
      read: this.readFromOPFS.bind(this),
      write: this.writeToOPFS.bind(this),
      delete: this.deleteFromOPFS.bind(this)
    });

    // Capa 2: IndexedDB
    this.layers.push({
      name: 'IndexedDB',
      available: 'indexedDB' in globalThis,
      priority: 2,
      read: this.readFromIndexedDB.bind(this),
      write: this.writeToIndexedDB.bind(this),
      delete: this.deleteFromIndexedDB.bind(this)
    });

    // Capa 3: LocalStorage (fallback)
    this.layers.push({
      name: 'LocalStorage',
      available: 'localStorage' in globalThis,
      priority: 3,
      read: this.readFromLocalStorage.bind(this),
      write: this.writeToLocalStorage.bind(this),
      delete: this.deleteFromLocalStorage.bind(this)
    });
  }

  async read(key: string): Promise<any> {
    const availableLayers = this.layers
      .filter(layer => layer.available)
      .sort((a, b) => a.priority - b.priority);

    for (const layer of availableLayers) {
      try {
        const data = await layer.read(key);
        if (data !== null && data !== undefined) {
          return data;
        }
      } catch (error) {
        console.warn(`ResilientStorage: Error reading from ${layer.name}`, error);
      }
    }

    return null;
  }

  async write(key: string, data: any): Promise<void> {
    const availableLayers = this.layers
      .filter(layer => layer.available)
      .sort((a, b) => a.priority - b.priority);

    let success = false;

    for (const layer of availableLayers) {
      try {
        await layer.write(key, data);
        success = true;
        break;
      } catch (error) {
        console.warn(`ResilientStorage: Error writing to ${layer.name}`, error);
      }
    }

    if (!success) {
