import { SQLiteEngine } from '../database/SQLiteEngine';
import { db as globalDb } from '@/database/simple-db';
import { logger } from '../../utils/logger';


interface AuditEvent {
    eventType: string;
    entityTable: string;
    entityId: string;
    userId: string;
    content: any;
    resolve?: (value?: any) => void;
    reject?: (reason?: any) => void;
}

export class AuditChainService {
    private engine: SQLiteEngine;
    private worker: Worker;
    private queue: AuditEvent[] = [];
    private processing = false;
    private static instance: AuditChainService;


    constructor(engine: SQLiteEngine) {
        this.engine = engine;
        // Initialize worker
        this.worker = new Worker(new URL('../../workers/encryption.worker.ts', import.meta.url), { type: 'module' });
    }

    /**
     * Intercepts a write operation to log it into the immutable audit chain.
     * Queues the event to ensure strict sequential processing (Chain Integrity).
     */
    async logEvent(event: AuditEvent): Promise<any> {
        return new Promise((resolve, reject) => {
            // Add to queue with queue-specific resolver
            this.queue.push({ ...event, resolve, reject });
            this.processQueue();
        });
    }

    /**
     * Processes queue sequentially.
     * One item at a time is processed to ensure PreviousHash is stable.
     */
    private async processQueue() {
        if (this.processing || this.queue.length === 0) return;

        this.processing = true;
        const currentEvent = this.queue.shift();

        if (!currentEvent) {
            this.processing = false;
            return; // Should happen if queue empty
        }

        try {
            const result = await this.processSingleEvent(currentEvent);
            if (currentEvent.resolve) currentEvent.resolve(result);
        } catch (error) {
            console.error('[Audit] Fatal Chain Error', error);
            if (currentEvent.reject) currentEvent.reject(error);
            // Critical decision: If audit fails, do we clear the queue? 
            // Yes, because subsequent items might depend on this one's success if inside same transaction logic on generic level.
            // But usually this service is called transactionally. 
            // If this fails, the caller sees the error and aborts transaction.
        } finally {
            this.processing = false;
            // Next
            if (this.queue.length > 0) {
                this.processQueue();
            }
        }
    }

    private async processSingleEvent(event: AuditEvent): Promise<any> {
        // 1. Get Previous Hash (LATEST committed)
        // Note: In strict isolation 'BEGIN IMMEDIATE', we are safe from other writers, 
        // but we need to ensure we read the very last one inserted even in this session?
        // Yes, `SELECT ... ORDER BY id DESC LIMIT 1` sees uncommitted writes within the same transaction context in SQLite.
        const lastRecord = await this.engine.select("SELECT chain_hash FROM audit_chain ORDER BY id DESC LIMIT 1");
        const previousHash = lastRecord[0]?.chain_hash || 'GENESIS_HASH';

        // 2. Delegate Hashing to Worker
        let newHash: string;
        try {
            newHash = await this.calculateHashInWorker(previousHash, event.content);
        } catch (workerError) {
            console.error('[Audit] Worker Hashing Failed', workerError);
            throw new Error('AUDIT_INTEGRITY_FAILURE: Could not verify hash integrity via Worker.');
        }

        if (!newHash || newHash.length < 32) {
            throw new Error('AUDIT_INTEGRITY_FAILURE: Invalid hash generated.');
        }

        // 3. Insert
        await this.engine.run(`
                INSERT INTO audit_chain 
                (event_type, entity_table, entity_id, user_id, content_payload, content_hash, previous_hash, chain_hash)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            `, [
            event.eventType,
            event.entityTable,
            event.entityId,
            event.userId,
            JSON.stringify(event.content),
            newHash,
            previousHash,
            newHash
        ]);

        console.log(`[Audit] Sealed: ${event.eventType} | Chain: ${previousHash.substring(0, 4)}->${newHash.substring(0, 4)}`);

        // Return for compatibility
        return {
            id: lastRecord[0]?.id || 0,
            previous_hash: previousHash,
            current_hash: newHash,
            event_type: event.eventType,
            event_data: JSON.stringify(event.content),
            user_id: parseInt(event.userId),
            timestamp: new Date().toISOString(),
            nonce: 0
        };
    }


    private calculateHashInWorker(previousHash: string, content: any): Promise<string> {
        return new Promise((resolve, reject) => {
            const id = Math.random().toString(36).substr(2, 9);

            const handler = (e: MessageEvent) => {
                if (e.data.id === id) {
                    this.worker.removeEventListener('message', handler);
                    if (e.data.type === 'HASH_SUCCESS') {
                        resolve(e.data.payload);
                    } else {
                        reject(new Error(e.data.error || 'Worker Unknown Error'));
                    }
                }
            };

            this.worker.addEventListener('message', handler);
            this.worker.addEventListener('error', (err) => {
                this.worker.removeEventListener('message', handler);
                reject(err);
            });

            this.worker.postMessage({
                type: 'HASH_CHAIN',
                id,
                payload: { previousHash, content }
            });

            // Timeout safely
            setTimeout(() => {
                this.worker.removeEventListener('message', handler);
                reject(new Error('Audit Worker Timed Out (>3000ms)'));
            }, 3000);
        });
    }

    /**
     * Get recent audit log entries
     * @param limit Max entries to return
     */
    async getAuditLog(limit: number = 50): Promise<any[]> {
        const records = await this.engine.select(`
            SELECT id, event_type, entity_table, entity_id, user_id, 
                   content_payload, chain_hash, previous_hash,
                   datetime(created_at, 'localtime') as created_at
            FROM audit_chain
            ORDER BY id DESC
            LIMIT ?
        `, [limit]);

        return records.map((r: any) => ({
            id: r.id,
            event_type: r.event_type,
            entity_table: r.entity_table,
            entity_id: r.entity_id,
            user_id: r.user_id,
            payload: r.content_payload ? JSON.parse(r.content_payload) : {},
            chain_hash: r.chain_hash,
            previous_hash: r.previous_hash,
            created_at: r.created_at || new Date().toISOString()
        }));
    }

    terminate() {
        this.worker.terminate();
    }

    /**
     * Compatibility: addEvent (used by useInvoiceForm.ts)
     */
    async addEvent(eventType: string, eventData: any, userId: number = 1): Promise<any> {
        return this.logEvent({
            eventType,
            entityTable: 'GENERIC', // Or extract from data if needed
            entityId: eventData.invoiceId || '0',
            userId: userId.toString(),
            content: eventData
        });
    }

    /**
     * Compatibility: ensureTable
     */
    async ensureTable(): Promise<void> {
        // Table is already handled in SQLiteEngine/simple-db, but we provide it for safety
        await this.engine.exec(`
            CREATE TABLE IF NOT EXISTS audit_chain (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_type TEXT,
                entity_table TEXT,
                entity_id TEXT,
                user_id TEXT,
                content_payload TEXT,
                content_hash TEXT,
                previous_hash TEXT,
                chain_hash TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        `);
    }


    /**
     * Singleton management for legacy components
     */
    public static getInstance(): AuditChainService {
        if (!AuditChainService.instance) {
            const engine = new SQLiteEngine();
            // @ts-ignore
            engine.setDB(globalDb);
            AuditChainService.instance = new AuditChainService(engine);
        }
        return AuditChainService.instance;
    }

    /**
     * Compatibility: logAction (used by simple-db.ts)
     */
    public static async logAction(event: any): Promise<void> {
        const instance = AuditChainService.getInstance();
        await instance.logEvent({
            eventType: event.action || 'SQL_EVENT',
            entityTable: event.table || 'GENERIC',
            entityId: event.id?.toString() || '0',
            userId: event.userId?.toString() || '1',
            content: event.payload || event
        });
    }

    /**
     * Compatibility: performFullAudit (used by LiveVerification.tsx)
     */
    public static async performFullAudit(): Promise<any> {
        const instance = AuditChainService.getInstance();
        const logs = await instance.getAuditLog(100);

        let valid = true;
        let details = 'Verification Successful';

        // Simple sequential check
        for (let i = 0; i < logs.length - 1; i++) {
            if (logs[i].previous_hash !== logs[i + 1].chain_hash) {
                valid = false;
                details = `Chain break at entry ${logs[i].id}`;
                break;
            }
        }

        return {
            valid,
            timestamp: new Date().toISOString(),
            details,
            totalChecked: logs.length
        };
    }

    /**
     * Compatibility: getLastValidHash (used by Dashboard.tsx)
     */
    public static async getLastValidHash(): Promise<string> {
        const instance = AuditChainService.getInstance();
        const logs = await instance.getAuditLog(1);
        return logs[0]?.chain_hash || 'GENESIS_HASH';
    }

    /**
     * Compatibility: getAuditTrail (used by AuditTrailTable.tsx)
     */
    public static async getAuditTrail(options: any = {}): Promise<any[]> {
        const instance = AuditChainService.getInstance();
        return await instance.getAuditLog(options.limit || 50);
    }

    /**
     * Helper for delta calculation
     */
    public static computeDelta(oldData: any, newData: any): any {
        const delta: any = {};
        for (const key in newData) {
            if (newData[key] !== oldData[key]) {
                delta[key] = { from: oldData[key], to: newData[key] };
            }
        }
        return delta;
    }
}

import { v4 as uuidv4 } from 'uuid';
import { ExternalTimestampService } from '../../services/ExternalTimestampService';

// Define strict interfaces for the system
export interface AuditEvent {
    id: string;
    timestamp: string;
    action: string;
    userId: number;
    entityType?: string;
    entityId?: number;
    changes?: unknown;
    critical?: boolean;
}

export interface StoredAuditEvent extends AuditEvent {
    changes_hash: string;
    previous_hash: string | null;
    ip_address: string;
    user_agent: string;
    session_id: string;
    external_signature?: string | null;
    witness_status?: 'PENDING' | 'VERIFIED' | 'NO_EXTERNAL_WITNESS' | 'FAILED';
}

/**
 * SISTEMA DE AUDITOR├ìA POR LOTES - NEXT GEN
 * Integridad Forense Nivel NASA con RFC 3161
 */
export class BatchAuditSystem {
    private pendingEvents: any[] = [];
    private batchSize = 100;
    private batchInterval = 30000; // 30 seconds
    private processing = false;
    private retryAttempts = 0;
    private maxRetries = 3;

    // Fail Secure Flag
    private systemLocked = false;

    constructor() {
        this.startBatchProcessor();
        this.ensureSchema();
    }

    // Registrar evento de auditor├¡a
    public logEvent(event: { action: string; userId?: number; entityType?: string; entityId?: number; changes?: any; critical?: boolean }) {
        if (this.systemLocked) {
            throw new Error('SECURITY_LOCKDOWN: Audit System Failed (RFC 3161 Unreachable). Writes are suspended.');
        }

        const auditEvent: StoredAuditEvent = {
            id: this.generateId(),
            timestamp: new Date().toISOString(),
            action: event.action,
            userId: event.userId || 1,
            entityType: event.entityType,
            entityId: event.entityId,
            changes: event.changes,
            ip_address: this.getClientIP(),
            user_agent: navigator.userAgent,
            session_id: this.getSessionId(),
            changes_hash: '',
            previous_hash: null,
            witness_status: 'PENDING'
        };

        this.pendingEvents.push(auditEvent);

        // Procesar inmediatamente si es cr├¡tico
        if (event.critical) {
            this.processBatch(true);
        }
    }

    /**
     * Asegura que el esquema de base de datos soporte los nuevos campos forenses
     */
    private async ensureSchema() {
        try {
            const simpleDb = await import('../../database/simple-db');
            const db = simpleDb.db;
            if (!db) return;

            db.exec(`
        CREATE TABLE IF NOT EXISTS audit_chain (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          event TEXT NOT NULL,
          user_id INTEGER NOT NULL,
          entity_type TEXT,
          entity_id INTEGER,
          changes_hash TEXT NOT NULL,
          previous_hash TEXT,
          timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
          ip_address TEXT,
          user_agent TEXT,
          session_id TEXT,
          external_signature TEXT,
          witness_status TEXT
        )
      `);

            try {
                db.exec("ALTER TABLE audit_chain ADD COLUMN external_signature TEXT");
            } catch { }
            try {
                db.exec("ALTER TABLE audit_chain ADD COLUMN witness_status TEXT");
            } catch { }

        } catch (e) {
            console.error('Audit schema init failed:', e);
        }
    }

    // Procesar lote de eventos
    private async processBatch(force = false) {
        if (this.processing || (this.pendingEvents.length === 0 && !force)) return;
        if (this.systemLocked) return; // Stay locked

        this.processing = true;

        const batch = this.pendingEvents.splice(0, this.batchSize);
        if (batch.length === 0) {
            this.processing = false;
            return;
        }

        try {
            // 1. Calcular hashes locales
            const lastHash = await this.getLastHash();
            let previousHash = lastHash;

            for (const event of batch) {
                event.previous_hash = previousHash;
                event.changes_hash = await this.calculateHash(event);
                previousHash = event.changes_hash;
            }

            // 2. Witnessing con RFC 3161 (External Timestamp)
            const batchRootHash = batch[batch.length - 1].changes_hash;
            let externalSignature: string | null = null;
            let witnessStatus: StoredAuditEvent['witness_status'] = 'PENDING';

            try {
                // Execute with Exponential Backoff
                externalSignature = await this.executeWithBackoff(async () => {
                    const result = await ExternalTimestampService.getTrustedTimestamp(batchRootHash);
                    if (!result) throw new Error('TSA Verification Failed');
                    return result;
                });
                witnessStatus = 'VERIFIED';
                this.retryAttempts = 0;
            } catch (error) {
                console.error('ΓÜá∩╕Å External Witness failed after retries:', error);
                this.retryAttempts++;
                witnessStatus = 'FAILED';

                // NASA Standard: Lockdown after max retries
                if (this.retryAttempts >= this.maxRetries) {
                    this.systemLocked = true;
                    console.error('Γ¢ö SYSTEM LOCKED: Integrity Compromised or TSA Unreachable.');
                    // Alert User? (In real app, trigger UI modal)
                }
            }

            // Apply signature
            batch[batch.length - 1].external_signature = externalSignature;
            batch[batch.length - 1].witness_status = witnessStatus;

            // 3. Persistencia
            await this.saveBatch(batch);

            console.log(`Γ£à Batch audit processed: ${batch.length} events. Status: ${witnessStatus}`);

        } catch (error) {
            console.error('Γ¥î Batch audit CRITICAL failure:', error);
            // Re-queue events at the start to ensure no data loss
            this.pendingEvents.unshift(...batch);
        } finally {
            this.processing = false;
        }
    }

    /**
     * Ejecuta una promesa con Exponential Backoff (1s, 2s, 4s)
     * Rapid retry for demo/responsiveness, logic scalable.
     */
    private async executeWithBackoff<T>(fn: () => Promise<T>): Promise<T> {
        const delays = [1000, 2000, 4000];

        for (let i = 0; i <= delays.length; i++) {
            try {
                return await fn();
            } catch (error) {
                if (i === delays.length) throw error;
                console.warn(`ΓÅ│ RFC 3161 Retry ${i + 1}/${delays.length} in ${delays[i]}ms...`);
                await new Promise(resolve => setTimeout(resolve, delays[i]));
            }
        }
        throw new Error('Unreachable');
    }

    // Calcular hash criptogr├ífico (SHA-256)
    private async calculateHash(event: StoredAuditEvent): Promise<string> {
        // Canonical JSON structure
        const payload = {
            id: event.id,
            prev: event.previous_hash,
            date: event.timestamp,
            act: event.action,
            uid: event.userId,
            ent: event.entityId,
            chg: event.changes
        };

        const data = JSON.stringify(payload);

        if (typeof crypto !== 'undefined' && 'subtle' in crypto) {
            const encoder = new TextEncoder();
            const dataBuffer = encoder.encode(data);
            const hashBuffer = await crypto.subtle.digest('SHA-256', dataBuffer);
            return Array.from(new Uint8Array(hashBuffer))
                .map(b => b.toString(16).padStart(2, '0'))
                .join('');
        } else {
            return this.simpleHash(data);
        }
    }

    // Hash simple para fallback
    private simpleHash(str: string): string {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return Math.abs(hash).toString(16).padStart(8, '0');
    }

    // Obtener ├║ltimo hash de la cadena
    private async getLastHash(): Promise<string | null> {
        try {
            const simpleDb = await import('../../database/simple-db');
            const db = simpleDb.db;
            if (!db) return null;

            const result = db.exec(
                "SELECT changes_hash FROM audit_chain ORDER BY id DESC LIMIT 1"
            );

            if (result && result.length > 0 && result[0].values && result[0].values.length > 0) {
                return result[0].values[0][0] as string;
            }
            return null;
        } catch {
            return null;
        }
    }

    // Guardar lote en base de datos
    private async saveBatch(batch: StoredAuditEvent[]) {
        const simpleDb = await import('../../database/simple-db');
        const db = simpleDb.db;
        if (!db) throw new Error('Database not available');

        db.exec('BEGIN TRANSACTION');
        try {
            const stmt = db.prepare(`
        INSERT INTO audit_chain 
        (event, user_id, entity_type, entity_id, changes_hash, previous_hash, timestamp, ip_address, user_agent, session_id, external_signature, witness_status)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);

            for (const event of batch) {
                stmt.run([
                    event.action,
                    event.userId,
                    event.entityType || null,
                    event.entityId || null,
                    event.changes_hash,
                    event.previous_hash,
                    event.timestamp,
                    event.ip_address,
                    event.user_agent,
                    event.session_id,
                    event.external_signature || null,
                    event.witness_status || 'PENDING'
                ]);
            }
            stmt.free();
            db.exec('COMMIT');
        } catch (e) {
            db.exec('ROLLBACK');
            throw e;
        }
    }

    private startBatchProcessor() {
        setInterval(() => {
            this.processBatch();
        }, this.batchInterval);
    }

    private generateId() {
        return uuidv4();
    }

    private getClientIP() {
        return 'localhost';
    }

    private getSessionId() {
        return sessionStorage.getItem('session_id') || 'anonymous';
    }
}

export const batchAuditSystem = new BatchAuditSystem();

/**
 * DataHealthCheckService - Servicio de Salud y Monitoreo de Datos
 * 
 * Monitorea continuamente:
 * - Integridad referencial
 * - Consistencia de datos
 * - Anomal├¡as
 * - Degradaci├│n de rendimiento
