                // @ts-ignore
                this.sqlite3.bind_collection(stmt, params as unknown as never[]);
            }

            // Execute
            // @ts-ignore
            await this.sqlite3.step(stmt);
        } finally {
            // @ts-ignore
            if (stmt) await this.sqlite3.finalize(stmt);
        }
