     * Sanitation Step 4.2
     */
    static async backupDB(manual: boolean = false): Promise<void> {
        if (!DatabaseService.dbInstance) return;

        const isAutoEnabled = localStorage.getItem('auto_backup_enabled') === 'true';
        if (!manual && !isAutoEnabled) return;

        try {
            const dbData = DatabaseService.dbInstance.export();
            const blob = new Blob([dbData], { type: 'application/x-sqlite3' });
            const url = URL.createObjectURL(blob);

            const now = new Date();
            const dateStr = now.toISOString().split('T')[0];
            const timeStr = now.getHours().toString().padStart(2, '0') + now.getMinutes().toString().padStart(2, '0');
            const filename = `account-express-backup-${dateStr}-${timeStr}.sqlite`;

            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            const type = manual ? 'manual' : 'auto';
            const logMsg = manual ? `Backup manual creado: ${filename}` : `Backup autom├ítico creado: ${filename}`;

            logger.info('BackupService', 'backup_success', logMsg, { filename, size: dbData.byteLength });

            // Registrar en la tabla de logs (Sanitation Step 4.2)
            try {
                const ts = new Date().toISOString();
                const size = dbData.byteLength;
                DatabaseService.dbInstance.run(
                    `INSERT INTO backups_log (timestamp, filename, size, type, success) VALUES (?, ?, ?, ?, 1)`,
                    [ts, filename, size, type]
                );
            } catch (dbError) {
                console.error('Error logging backup to DB:', dbError);
                logger.error('DatabaseService', 'backup_log_failed', 'Resumen: No se pudo registrar en la tabla logs', { error: String(dbError) });
            }

        } catch (error) {
            logger.error('BackupService', 'backup_error', 'Fallo cr├¡tico al crear backup', null, error as Error);
        }
    }

    /**
     * Inicia el timer de backups autom├íticos (cada 5 min)
     * Sanitation Step 4.1
     */
    static startAutoBackupTimer(): void {
        logger.info('DatabaseService', 'auto_timer_init', 'Iniciando temporizador de backups autom├íticos (5 min)');

        // Ejecutar cada 5 minutos (300,000 ms)
        setInterval(() => {
            DatabaseService.backupDB(false);
        }, 300000);
    }
}

import { db, DB_NAME } from './simple-db';
import { logger } from '../utils/logger';

export interface DiagnosticReport {
    timestamp: Date;
    errors: string[];
    warnings: string[];
    recommendations: string[];
    rawState: any;
}

export interface FixResult {
    success: boolean;
    backupId?: string;
    timestamp: Date;
    checksum: string;
}

export class ForensicDatabaseDiagnostic {
    /**
     * Realiza un an├ílisis profundo de la base de datos buscando inconsistencias y errores de integridad.
     */
    static async performDeepAnalysis(): Promise<DiagnosticReport> {
        const report: DiagnosticReport = {
            timestamp: new Date(),
            errors: [],
            warnings: [],
            recommendations: [],
            rawState: {}
        };

        if (!db) {
            report.errors.push('Database instance not available for analysis');
            return report;
        }

        try {
            // 1. CAPTURAR ESTADO ACTUAL
            const tablesRes = db.exec("SELECT name FROM sqlite_master WHERE type='table'");
            const tables = tablesRes.length > 0 ? tablesRes[0].values.map((v: any[]) => v[0] as string) : [];
            report.rawState.tables = tables;

            // 2. VERIFICAR FK
            const fkCheck = db.exec('PRAGMA foreign_key_check;');
            if (fkCheck.length > 0) {
                const violations = fkCheck[0].values.map((row: any) => `Violation in table ${row[0]}, rowid ${row[1]}, target ${row[2]}`);
                report.errors.push(...violations);
            }

            // 3. VERIFICAR INTEGRIDAD F├ìSICA
            const integrityCheck = db.exec('PRAGMA integrity_check;');
            if (integrityCheck[0].values[0][0] !== 'ok') {
                report.errors.push(`Physical integrity failure: ${integrityCheck[0].values[0][0]}`);
            }

            // 4. GENERAR RECOMENDACIONES
            if (report.errors.length > 0) {
                report.recommendations.push('NUCLEAR_REBUILD_REQUIRED');
            } else {
                report.recommendations.push('SYSTEM_STABLE');
            }

        } catch (error: any) {
            report.errors.push(`Analysis failed: ${error.message}`);
        }

        return report;
    }

    /**
     * Ejecuta el fix definitivo: Reconstrucci├│n nuclear desde cero para limpiar estados corruptos.
     */
    static async executeDefinitiveFix(): Promise<FixResult> {
        logger.emergency('EJECUTANDO FIX DEFINITIVO PARA ERROR FK - MODO NUCLEAR', undefined, undefined, 'Forensic', 'start');

        if (!db) throw new Error('Database not initialized');

        try {
            // FASE 1: NUCLEAR REBUILD
            await this.nuclearRebuild();

            // FASE 2: VERIFICACI├ôN DE 3 PASOS
            await this.threeStepVerification();

            const checksum = await this.generateSystemChecksum();

            logger.success('SISTEMA RECONSTRUIDO Y VALIDADO TRAS FIX NUCLEAR', undefined, 'Forensic', 'success');

            return {
                success: true,
                timestamp: new Date(),
                checksum: checksum
            };

        } catch (error: any) {
            logger.critical('FALLA EN EL FIX DEFINITIVO NUCLEAR', { error: error.message }, undefined, 'Forensic', 'failed');
            throw error;
        }
    }

    private static async nuclearRebuild(): Promise<void> {
        if (!db) return;

        logger.warn('Iniciando Nuclear Rebuild: Eliminando todos los artefactos...', undefined, 'Forensic', 'cleanup');

        // 1. Desactivar FK
        db.run('PRAGMA foreign_keys = OFF;');

        // 2. Obtener y eliminar todas las tablas, vistas e ├¡ndices
        const objects = db.exec("SELECT type, name FROM sqlite_master WHERE type IN ('table', 'view', 'index') AND name NOT LIKE 'sqlite_%'");

        if (objects.length > 0) {
            for (const row of objects[0].values) {
                const type = row[0] as string;
                const name = row[1] as string;
                try {
                    db.run(`DROP ${type.toUpperCase()} IF EXISTS "${name}"`);
                    logger.debug(`Eliminado ${type}: ${name}`, undefined, 'Forensic', 'cleanup');
                } catch (e) { }
            }
        }

        // 3. VACUUM para limpiar el archivo
        db.run('VACUUM;');

        // 4. Crear schema garantizado con UUIDs y orden estricto
        await this.createGuaranteedSchema();
    }

    private static async createGuaranteedSchema(): Promise<void> {
        if (!db) return;

        logger.info('Creando schema garantizado con arquitectura a prueba de fallos...', undefined, 'Forensic', 'schema');

        const creationOrder = [
            // FASE A: Metadatos y Versi├│n
            `CREATE TABLE system_metadata (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        key TEXT UNIQUE NOT NULL,
        value TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )`,

            // FASE A.1: Datos de la Empresa (Vital para la identidad del sistema)
            `CREATE TABLE company_data (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        company_name TEXT NOT NULL,
        legal_name TEXT NOT NULL,
        tax_id TEXT NOT NULL,
        address TEXT NOT NULL,
        city TEXT NOT NULL,
        state TEXT NOT NULL DEFAULT 'FL',
        zip_code TEXT NOT NULL,
        phone TEXT NOT NULL,
        email TEXT NOT NULL,
        is_active BOOLEAN DEFAULT 1,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )`,

            `INSERT OR IGNORE INTO company_data (id, company_name, legal_name, tax_id, address, city, state, zip_code, phone, email) 
       VALUES (1, 'Mi Empresa', 'Empresa Reconstruida', '00-0000000', 'Direcci├│n Temporal', 'Miami', 'FL', '33101', '000-000-0000', 'admin@empresa.com')`,

            // FASE B: Cat├ílogos con UUIDs (Prevenir colisiones y facilitar migraciones)
            `CREATE TABLE customers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        uuid TEXT UNIQUE NOT NULL,
        name TEXT NOT NULL,
        county TEXT NOT NULL,
        tax_id TEXT,
        email TEXT,
        is_active BOOLEAN DEFAULT 1,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )`,

            `CREATE TABLE products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        uuid TEXT UNIQUE NOT NULL,
        sku TEXT UNIQUE NOT NULL,
        name TEXT NOT NULL,
        unit_price REAL NOT NULL DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )`,

            // FASE C: Transacciones con DEFERRABLE constraints
            `CREATE TABLE invoices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        uuid TEXT UNIQUE NOT NULL,
        number TEXT UNIQUE NOT NULL,
        type TEXT NOT NULL CHECK(type IN ('sale', 'purchase')),
        customer_uuid TEXT NOT NULL,
        date DATE NOT NULL DEFAULT CURRENT_DATE,
        total REAL NOT NULL DEFAULT 0,
        status TEXT DEFAULT 'draft',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (customer_uuid) REFERENCES customers(uuid) DEFERRABLE INITIALLY DEFERRED
      )`,

            `CREATE TABLE invoice_lines (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_uuid TEXT NOT NULL,
        product_uuid TEXT NOT NULL,
        quantity REAL NOT NULL DEFAULT 1,
        unit_price REAL NOT NULL DEFAULT 0,
        line_total REAL NOT NULL DEFAULT 0,
        FOREIGN KEY (invoice_uuid) REFERENCES invoices(uuid) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
        FOREIGN KEY (product_uuid) REFERENCES products(uuid) DEFERRABLE INITIALLY DEFERRED
      )`,

            // ├ìNDICES
            `CREATE INDEX idx_invoices_customer ON invoices(customer_uuid)`,
            `CREATE INDEX idx_lines_invoice ON invoice_lines(invoice_uuid)`
        ];

        db.run('BEGIN TRANSACTION;');
        try {
            for (const sql of creationOrder) {
                db.run(sql);
            }
            db.run('COMMIT;');
        } catch (e: any) {
            db.run('ROLLBACK;');
            throw new Error(`Failed to create guaranteed schema: ${e.message}`);
        }
    }

    private static async threeStepVerification(): Promise<void> {
        if (!db) return;

        // 1. Estructura
        const tablesCount = db.exec("SELECT COUNT(*) FROM sqlite_master WHERE type='table'")[0].values[0][0] as number;
        if (tablesCount < 3) throw new Error('Verification failed: Missing tables');

        // 2. Relaciones (Reactivar y checkear)
        db.run('PRAGMA foreign_keys = ON;');
        const fkCheck = db.exec('PRAGMA foreign_key_check;');
        if (fkCheck.length > 0) throw new Error('Verification failed: Foreign key violations detected after rebuild');

        // 3. Coherencia
        const integrity = db.exec('PRAGMA integrity_check;');
        if (integrity[0].values[0][0] !== 'ok') throw new Error('Verification failed: Data integrity error');
    }

    private static async generateSystemChecksum(): Promise<string> {
        if (!db) return 'unknown';
        // Checksum simplificado basado en el esquema
        const res = db.exec("SELECT group_concat(name) FROM sqlite_master");
        return `v2_${res[0].values[0][0]}`;
    }
}

import { logger } from '../core/logging/SystemLogger';

const DB_NAME = 'AccountExpressDB';
const STORE_NAME = 'sqlite_store';
const KEY_NAME = 'main_db';

// NASA Standard: Key must reside in volatile memory only
let encryptionKey: CryptoKey | null = null;

export const setEncryptionKey = (key: CryptoKey) => {
    encryptionKey = key;
    logger.info('Persistence', 'key_set', 'Clave de cifrado establecida en memoria vol├ítil');
};

/**
 * Genera una clave de sistema b├ísica si no hay una de usuario.
 * NASA Standard: Derivaci├│n determinista para persistencia local b├ísica.
 */
async function ensureEncryptionKey(): Promise<CryptoKey> {
    if (encryptionKey) return encryptionKey;

    const encoder = new TextEncoder();
    const systemSecret = "AccountExpress_SolidState_2025";
    const salt = encoder.encode("NASA_JPL_COMPLIANCE");

    const keyMaterial = await crypto.subtle.importKey(
        'raw',
        encoder.encode(systemSecret),
        'PBKDF2',
        false,
        ['deriveKey']
    );

    encryptionKey = await crypto.subtle.deriveKey(
        {
            name: 'PBKDF2',
            salt: salt,
            iterations: 100000,
            hash: 'SHA-256'
        },
        keyMaterial,
        {
            name: 'AES-GCM',
            length: 256
        },
        false,
        ['encrypt', 'decrypt']
    );

    logger.info('Persistence', 'system_key_initialized', 'Clave de sistema inicializada para cifrado b├ísico');
    return encryptionKey;
}

/**
 * Cifra datos usando AES-256-GCM
 */
async function encryptData(data: Uint8Array, key: CryptoKey): Promise<Uint8Array> {
    const iv = crypto.getRandomValues(new Uint8Array(12)); // 96-bit IV recommended for GCM
    const encrypted = await crypto.subtle.encrypt(
        {
            name: 'AES-GCM',
            iv: iv
        },
        key,
        data as unknown as BufferSource
    );

    // Concatenate IV + Encrypted Data
    const result = new Uint8Array(iv.length + encrypted.byteLength);
    result.set(iv);
    result.set(new Uint8Array(encrypted), iv.length);
    return result;
}

/**
 * Descifra datos usando AES-256-GCM
 */
async function decryptData(data: Uint8Array, key: CryptoKey): Promise<Uint8Array> {
    const iv = data.slice(0, 12);
    const ciphertext = data.slice(12);

    return new Uint8Array(await crypto.subtle.decrypt(
        {
            name: 'AES-GCM',
            iv: iv
        },
        key,
        ciphertext as unknown as BufferSource
    ));
}

export async function saveDatabase(data: Uint8Array): Promise<void> {
    return new Promise(async (resolve, reject) => {
        let blobToSave = data;

        // Apply Encryption
        const key = await ensureEncryptionKey();
        try {
            blobToSave = await encryptData(data, key);
            logger.info('Persistence', 'save_encrypted', 'Guardando DB cifrada', { size: blobToSave.length });
        } catch (cryptoError) {
            logger.error('Persistence', 'encrypt_fail', 'Fallo cr├¡tico al cifrar DB. Abortando guardado.', cryptoError);
            reject(new Error('CRITICAL_SECURITY_FAILURE: Encryption failed. Write aborted.'));
            return;
        }

        const request = indexedDB.open(DB_NAME, 1);

        request.onupgradeneeded = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME);
            }
        };

        request.onsuccess = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            const transaction = db.transaction(STORE_NAME, 'readwrite');
            const store = transaction.objectStore(STORE_NAME);

            const putRequest = store.put(blobToSave, KEY_NAME);

            putRequest.onsuccess = () => {
                logger.info('Persistence', 'save_success', 'Base de datos guardada en IndexedDB', { size: blobToSave.length, encrypted: !!encryptionKey });
                resolve();
            };

            putRequest.onerror = () => {
                logger.error('Persistence', 'save_error', 'Error guardando en IndexedDB', putRequest.error);
                reject(putRequest.error);
            };
        };

        request.onerror = () => {
            logger.error('Persistence', 'open_error', 'Error abriendo IndexedDB', request.error);
            reject(request.error);
        };
    });
}

/**
 * Carga la base de datos desde IndexedDB
 */
export async function loadDatabase(): Promise<Uint8Array | null> {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);

        request.onupgradeneeded = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME);
            }
        };

        request.onsuccess = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            const transaction = db.transaction(STORE_NAME, 'readonly');
            const store = transaction.objectStore(STORE_NAME);

            const getRequest = store.get(KEY_NAME);

            getRequest.onsuccess = async () => {
                const result = getRequest.result as Uint8Array;
                if (result) {
                    const key = await ensureEncryptionKey();
                    try {
                        // Intentar descifrar
                        const decrypted = await decryptData(result, key);
                        logger.info('Persistence', 'load_success', 'DB cargada y descifrada correctamente');
                        resolve(decrypted);
                    } catch (e) {
                        // RETRO-COMPATIBILIDAD: Si falla el cifrado, ver si es SQLite plano
                        const header = new TextDecoder().decode(result.slice(0, 16));
                        if (header.startsWith('SQLite')) {
                            logger.info('Persistence', 'load_plain_migration', 'DB en texto plano detectada. Migrando a cifrado en el pr├│ximo guardado.');
                            resolve(result);
                        } else {
                            logger.error('Persistence', 'decrypt_fail', 'Error al descifrar DB. Datos corruptos o clave incompatible.', e);
                            resolve(null);
                        }
                    }
                } else {
                    logger.warn('Persistence', 'load_empty', 'No se encontr├│ base de datos en IndexedDB');
                    resolve(null);
                }
            };

            getRequest.onerror = () => {
                logger.error('Persistence', 'load_error', 'Error leyendo de IndexedDB', getRequest.error);
                reject(getRequest.error);
            };
        };

        request.onerror = () => {
            resolve(null);
        };
    });
}

