import initSqlJs from 'sql.js';
import { BasicEncryption } from '../core/security/BasicEncryption';
import { logger } from '../core/logging/SystemLogger';
import { ViewManager } from './views/ViewManager';
import { DatabaseInitializer } from './DatabaseInitializer';
import { DatabaseService } from './DatabaseService';
import { SQLiteEngine } from '../core/database/SQLiteEngine';
import { MigrationEngine } from '../core/migrations/MigrationEngine';
import { verifyRoles } from '../utils/verifyRoles';
import { MassiveSeeder } from './seeding/MassiveSeeder';
import { AuditChainService as AuditTrailService } from '../core/audit/AuditChainService';
import { EngineBridge } from '../core/database/EngineBridge';

// Tipo ligero para la API que usamos de sql.js (exec/run/prepare)
type SQLJSDB = {
  exec: (sql: string, params?: any[]) => any;
  run: (sql: string, params?: any[]) => any;
  prepare?: (sql: string) => any;
};

// Mantener `db` como `any` para compatibilidad con llamadas y wrappers externos
let db: any = null;
let sqlJsDb: SQLJSDB | null = null;

// Instancia global de SQLiteEngine (wrapper tipado sobre sql.js)
let dbEngine: SQLiteEngine | null = null;

// Exportar la instancia de db para acceso externo
export { db };
export const getDB = () => db;

export const dbExec = (sql: string, params?: any[]) => {
  if (!db) return null;
  if (!params || params.length === 0) {
    return db.exec(sql);
  }
  const stmt = db.prepare(sql);
  try {
    stmt.bind(params);


    const columns = stmt.getColumnNames();
    const values: any[][] = [];

    while (stmt.step()) {
      values.push(stmt.get());
    }
    return [{ columns, values }];
  } finally {
    stmt.free();
  }
};

export const dbRun = (sql: string, params?: any[]) => {
  if (!db) throw new Error('Database not initialized');
  if (!params || params.length === 0) {
    return db.run(sql);
  }
  const stmt = db.prepare(sql);
  try {
    return stmt.run(params);
  } finally {
    stmt.free();
  }
};

// Exportar la instancia de dbEngine para servicios tipados
export { dbEngine };

/**
 * Obtiene la instancia de SQLiteEngine
 * @throws Error si la base de datos no ha sido inicializada
 */
export const getDBEngine = (): SQLiteEngine => {
  if (!dbEngine) {
    if (EngineBridge.hasEngine()) {
      return EngineBridge.getEngine();
    }
    throw new Error('Database engine not initialized. Call initDB() first.');
  }
  return dbEngine;
};

