/**
 * Registra la disposici├│n (venta/baja) de un activo
 */
export function disposeAsset(
  id: number,
  disposalDate: string,
  disposalValue: number,
  disposal├üreason: string,
  userId: number
): { success: boolean; message: string } {
  if (!db) return { success: false, message: 'Database not initialized' };

  try {
    const asset = getFixedAssetById(id);
    if (!asset) return { success: false, message: 'Activo no encontrado' };

    db.run('BEGIN TRANSACTION');

    // Actualizar activo
    db.run(`
      UPDATE fixed_assets SET
        status = 'disposed',
        disposal_date = ?,
        disposal_value = ?,
        disposal_├üreason = ?,
        updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `, [disposalDate, disposalValue, disposal├üreason, id]);

    // Calcular ganancia/p├⌐rdida
    const netBookValue = (asset.current_value || asset.purchase_cost) - (asset.accumulated_depreciation || 0);
    const gainLoss = disposalValue - netBookValue;

    // TODO: Crear asiento contable de disposici├│n
    // D├⌐bito: Efectivo (disposalValue)
    // D├⌐bito: Depreciaci├│n Acumulada (accumulated_depreciation)
    // D├⌐bito/Cr├⌐dito: Ganancia/P├⌐rdida en venta
    // Cr├⌐dito: Activo Fijo (purchase_cost)

    db.run('COMMIT');
    return {
      success: true,
      message: `Activo dado de baja. ${gainLoss >= 0 ? 'Ganancia' : 'P├⌐rdida'}: $${Math.abs(gainLoss).toFixed(2)}`
    };
  } catch (e: any) {
    db?.run('ROLLBACK');
    return { success: false, message: e.message };
  }
}

