  db = null;
  dbEngine = null;
  isInitialized = false;
  logger.info('Database', 'reset', 'Base de datos reiniciada');
};

/**
 * Configura el auto-guardado peri├│dico de la base de datos.
 * Tambi├⌐n guarda al cerrar la ventana.
 */
function setupAutoSave(): void {
  setInterval(async () => {
    if (!db) return;
    try {
      await forceSaveDB();
    } catch (e) {
      // Silencioso para evitar spam en consola en producci├│n
    }
  }, 30000);

  // Guardar al cerrar la ventana
  if (typeof window !== 'undefined') {
    window.addEventListener('beforeunload', () => {
      forceSaveDB().catch(() => { });
    });
  }
}

export const initDB = async (password?: string): Promise<any> => {
  if (isInitialized && db) {
    return db;
  }

  try {
    logger.info('Database', 'init_start', 'Iniciando inicializaci├│n de base de datos SQLite');

    // Configurar cifrado si se proporciona contrase├▒a
    if (password && BasicEncryption.isSupported()) {
      encryptionEnabled = true;
      currentPassword = password;
      logger.info('Database', 'encryption_enabled', 'Cifrado habilitado con Web Crypto API');
    }

    // Inicializar sql.js
    const SQL = await initSqlJs({
      locateFile: (file: string) => {
        // En entorno de pruebas (Node.js), usar ruta de node_modules
        if (typeof process !== 'undefined' && process.env.NODE_ENV === 'test') {
          return `./node_modules/sql.js/dist/${file}`;
        }
        // En navegador, normalizar nombres y usar ruta absoluta
        const normalizedFile = file.replace('-browser', '');
        return `/${normalizedFile}`;
      }
    });

    logger.info('Database', 'sqljs_loaded', 'SQL.js cargado y base de datos inicializada');

    let dbData: Uint8Array | null = null;

    // Cargar datos existentes
    const { loadDatabase } = await import('./PersistenceLayer');
    dbData = await loadDatabase();
    // Fallback a localStorage si no hay en IndexedDB
    if (!dbData) {
      try {
        dbData = await loadFromLocalStorage();
      } catch (e) {
        console.warn('LocalStorage load failed', e);
      }
    }

    if (!db) {
      db = new SQL.Database(dbData || undefined);
    }

    // Crear instancia de SQLiteEngine y configurarla con la instancia de sql.js
    dbEngine = new SQLiteEngine();
    dbEngine.setDB(db);

    // Registrar en el puente para evitar dependencias circulares
    EngineBridge.setEngine(dbEngine);

    logger.info('Database', 'engine_initialized', 'SQLiteEngine wrapper creado exitosamente');

    // Configurar servicios adicionales
    setupAutoSave();

    // DEV: Exponer engine en window para verificaci├│n en consola del browser
    if (typeof window !== 'undefined') {
      // Bloqueo de resets autom├íticos restantes (Hardening Final)
      (window as any).NO_RESET = true;
      logger.info('System', 'hardening_complete', 'Sistema saneado: Persistencia ON, Cifrado ON, Backups ON');

      (window as any).__dbEngine = dbEngine;
      (window as any).__db = db;
      (window as any).__runSQL = (sql: string, params?: any[]) => {
        try {
          const result = db.exec(sql, params);
          return result;
        } catch (e) {
          return { error: String(e) };
        }
      };
    }

  } catch (error) {
    logger.error('Database', 'init_failed', 'Error fatal en inicializaci├│n', { error });
  } finally {
    isInitialized = true;
  }

  return db;
};

