export const enableEncryption = async (password: string): Promise<boolean> => {
  if (!db || encryptionEnabled || !BasicEncryption.isSupported()) {
    return false;
  }

  try {
    encryptionEnabled = true;
    currentPassword = password;

    // Guardar base de datos cifrada
    await saveDatabase();

    return true;
  } catch (error) {
