// Generar asiento autom├ítico para factura de venta
export const generateSalesJournalEntry = async (invoice: Invoice, userId?: number): Promise<{ success: boolean; message: string; entryId?: number }> => {
  if (!invoice.customer) {
    return { success: false, message: 'Informaci├│n del cliente requerida' };
  }

  const details: Partial<JournalDetail>[] = [
    // D├⌐bito: Cuentas por Cobrar
    {
      account_code: '1121',
      debit_amount: invoice.total_amount,
      credit_amount: 0,
      description: `Factura ${invoice.invoice_number} - ${invoice.customer.name} `
    },
    // Cr├⌐dito: Ventas
    {
      account_code: '4110',
      debit_amount: 0,
      credit_amount: invoice.subtotal,
      description: `Venta - Factura ${invoice.invoice_number} `
    }
  ];

  // Si hay impuestos, agregar l├¡nea de impuestos por pagar
  if (invoice.tax_amount > 0) {
    details.push({
      account_code: '2121',
      debit_amount: 0,
      credit_amount: invoice.tax_amount,
      description: `Impuesto Florida - Factura ${invoice.invoice_number} `
    });
  }

  return createJournalEntry({
    entry_date: invoice.issue_date,
    reference_number: `INV - ${invoice.invoice_number} `,
    description: `Venta a ${invoice.customer.name} - Factura ${invoice.invoice_number} `
  }, details, userId);
};

// Generar asiento autom├ítico para factura de compra
