// Generar Aging Report (Antig├╝edad de Cuentas)
export const getAgingReport = (type: 'receivable' | 'payable'): {
  total: number,
  buckets: { [key: string]: { amount: number, percentage: number } },
  details: { name: string, amount: number, days: number, bucket: string }[]
} => {
  if (!db) return { total: 0, buckets: {}, details: [] };

  try {
    const table = type === 'receivable' ? 'invoices' : 'bills';
    const entityTable = type === 'receivable' ? 'customers' : 'suppliers';
    const entityIdField = type === 'receivable' ? 'customer_id' : 'supplier_id';

    const result = db.exec(`
SELECT
e.name,
  t.total_amount,
  t.due_date,
  (julianday('now') - julianday(t.due_date)) as days_overdue
      FROM ${table} t
      JOIN ${entityTable} e ON t.${entityIdField} = e.id
      WHERE t.status IN('pending', 'partial', 'overdue')
    `);

    if (!result[0]) return { total: 0, buckets: {}, details: [] };

    const buckets: any = {
      'current': { amount: 0, percentage: 0 },
      '1-30': { amount: 0, percentage: 0 },
      '31-60': { amount: 0, percentage: 0 },
      '61-90': { amount: 0, percentage: 0 },
      '90+': { amount: 0, percentage: 0 }
    };

    let total = 0;
    const details: any[] = [];

    const columns = (result[0].columns || (result[0] as any).lc);
    result[0].values.forEach((row: any) => {
      const name = row[0] as string;
      const amount = Number(row[1]) || 0;
      const days = Math.floor(Number(row[3]) || 0);

      let bucket = 'current';
      if (days > 90) bucket = '90+';
      else if (days > 60) bucket = '61-90';
      else if (days > 30) bucket = '31-60';
      else if (days > 0) bucket = '1-30';

      buckets[bucket].amount += amount;
      total += amount;

      details.push({ name, amount, days, bucket });
    });

    // Calcular porcentajes
    if (total > 0) {
      Object.keys(buckets).forEach(key => {
        buckets[key].percentage = (buckets[key].amount / total) * 100;
      });
    }

    return { total, buckets, details };

  } catch (error) {
    console.error('Error generating aging report:', error);
    return { total: 0, buckets: {}, details: [] };
  }
};

// Obtener Auxiliar de Cuenta (Account Ledger)
export const getAccountLedger = (accountCode: string, fromDate: string, toDate: string): {
  account: any,
  startingBalance: number,
  transactions: any[],
  endingBalance: number,
  totalDebit: number,
  totalCredit: number
} => {
  if (!db) return { account: null, startingBalance: 0, transactions: [], endingBalance: 0, totalDebit: 0, totalCredit: 0 };

  try {
    // 1. Obtener info de la cuenta
    const accResult = db.exec(`SELECT * FROM chart_of_accounts WHERE account_code = ? `, [accountCode]);
    if (!accResult[0]) return { account: null, startingBalance: 0, transactions: [], endingBalance: 0, totalDebit: 0, totalCredit: 0 };

    const account: any = {};
    (accResult[0].columns || (accResult[0] as any).lc).forEach((col: any, i: any) => account[col] = accResult[0].values[0][i]);

    // 2. Calcular saldo inicial (antes de fromDate)
    const startBalResult = db.exec(`
      SELECT
COALESCE(SUM(debit_amount), 0) as debits,
  COALESCE(SUM(credit_amount), 0) as credits
      FROM journal_details jd
      JOIN journal_entries je ON jd.journal_entry_id = je.id
      WHERE jd.account_code = ? AND je.entry_date < ?
  `, [accountCode, fromDate]);

    const startDebits = Number(startBalResult[0].values[0][0]);
    const startCredits = Number(startBalResult[0].values[0][1]);
    const startingBalance = account.normal_balance === 'debit' ? (startDebits - startCredits) : (startCredits - startDebits);

    // 3. Obtener transacciones en el periodo
    const txResult = db.exec(`
      SELECT
je.entry_date,
  je.reference,
  jd.description,
  jd.debit_amount,
  jd.credit_amount,
  je.id as journal_id
      FROM journal_details jd
      JOIN journal_entries je ON jd.journal_entry_id = je.id
      WHERE jd.account_code = ? AND je.entry_date BETWEEN ? AND ?
  ORDER BY je.entry_date ASC, je.id ASC
    `, [accountCode, fromDate, toDate]);

    const transactions: any[] = [];
    let runningBalance = startingBalance;
    let totalDebit = 0;
    let totalCredit = 0;

    if (txResult[0]) {
      const cols = (txResult[0].columns || (txResult[0] as any).lc);
      txResult[0].values.forEach((row: any) => {
        const tx: any = {};
        cols.forEach((col: any, i: any) => tx[col] = row[i]);

        totalDebit += tx.debit_amount;
        totalCredit += tx.credit_amount;

        if (account.normal_balance === 'debit') {
          runningBalance += (tx.debit_amount - tx.credit_amount);
        } else {
          runningBalance += (tx.credit_amount - tx.debit_amount);
        }

        tx.running_balance = runningBalance;
        transactions.push(tx);
      });
    }

    return {
      account,
      startingBalance,
      transactions,
      endingBalance: runningBalance,
      totalDebit,
      totalCredit
    };

  } catch (error) {
    console.error('Error generating account ledger:', error);
    return { account: null, startingBalance: 0, transactions: [], endingBalance: 0, totalDebit: 0, totalCredit: 0 };
  }
};

export function getCompanyData(): CompanyData | null {
  try {
    logger.info('CompanyData', 'get_start', 'Obteniendo datos de la empresa');

    if (!db) {
      throw new Error('Base de datos no inicializada');
    }

    const result = db.exec(`
SELECT * FROM company_data WHERE is_active = 1 LIMIT 1
    `);

    if (result.length === 0 || result[0].values.length === 0) {
      logger.warn('CompanyData', 'not_found', 'No se encontraron datos de empresa');
      return null;
    }

    const row = result[0].values[0];
    const columns = (result[0].columns || (result[0] as any).lc);
    // Guard: columns puede ser undefined con algunas versiones de sql.js
    if (!columns || !Array.isArray(columns)) {
      logger.warn('CompanyData', 'columns_missing', '(result[0].columns || (result[0] as any).lc) es undefined ΓÇö retornando null');
      return null;
    }
    const company = rowToEntity<CompanyData>(columns, row);

    // Asegurar que los campos nuevos tengan valores v├ílidos si no vienen de DB
    if (!company.fiscal_year_end) company.fiscal_year_end = '12-31';
    if (company.netIncreaseInCash === undefined) company.netIncreaseInCash = 0;

    // Normalizaci├│n de tipos num├⌐ricos (sql.js a veces devuelve strings o nulls que deben ser 0)
    company.sales_commission_rate = Number(company.sales_commission_rate) || 0;
    company.sales_commission_percentage = Number(company.sales_commission_percentage) || 0;
    company.discount_amount = Number(company.discount_amount) || 0;
    company.discount_percentage = Number(company.discount_percentage) || 0;
    company.shipping_rate = Number(company.shipping_rate) || 0;
    company.shipping_percentage = Number(company.shipping_percentage) || 0;

    logger.info('CompanyData', 'get_success', 'Datos de empresa obtenidos', { company_name: company.company_name });
    return company;

  } catch (error) {
    logger.error('CompanyData', 'get_failed', 'Error al obtener datos de empresa', null, error as Error);
    throw error;
  }
}

export async function updateCompanyData(companyData: Partial<CompanyData>): Promise<{ success: boolean; message: string; warnings?: string[] }> {
  try {
    logger.info('CompanyData', 'update_start', 'Actualizando datos de empresa', companyData);

    if (!db) {
      throw new Error('Base de datos no inicializada');
    }

    // Verificar si hay datos contables asociados
    const warnings: string[] = [];
    const accountingDataCheck = checkAccountingDataAssociation();

    if (accountingDataCheck.hasData) {
      warnings.push('├ó┼í┬á├»┬╕┬Å ADVERTENCIA: Esta empresa tiene datos contables asociados');
      warnings.push(`├░┼╕ΓÇ£┼á ${accountingDataCheck.invoices} facturas, ${accountingDataCheck.customers} clientes, ${accountingDataCheck.suppliers} proveedores`);

      // Si se est├í cambiando el nombre de la empresa y hay datos contables
      if (companyData.company_name || companyData.legal_name) {
        warnings.push('≡ƒöä Cambiar el nombre puede afectar reportes y documentos existentes');
        warnings.push('≡ƒôï Se recomienda crear un respaldo antes de continuar');
      }
    }

    // ΓöÇΓöÇ UPSERT LOGIC ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // Verificar existencia de fila usando COUNT directo (sin rowToEntity)
    const rowCount = db.exec("SELECT COUNT(*) FROM company_data")[0]?.values[0]?.[0] as number ?? 0;

    // Helper: patr├│n correcto sql.js para DML con params posicionales
    // db.run(sql, params) NO vincula par├ímetros en esta versi├│n ΓÇö requiere Statement API
    const sqlRun = (sql: string, params: any[]): void => {
      const stmt = db.prepare(sql);
      try { stmt.run(params); } finally { stmt.free(); }
    };

    if (rowCount === 0) {
      // CASO 1: No existe fila ΓÇö INSERT directo con datos del usuario
      logger.warn('CompanyData', 'upsert_insert', 'No existe fila ΓÇö creando con datos del usuario');
      sqlRun(`
        INSERT INTO company_data (
          company_name, legal_name, tax_id,
          address, city, state, zip_code,
          phone, email, website,
          fiscal_year_start, currency, language,
          timezone, date_format, fiscal_year_end,
          is_active, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)
      `, [
        companyData.company_name || 'Mi Empresa LLC',
        companyData.legal_name || 'Mi Empresa LLC',
        companyData.tax_id || '00-0000000',
        companyData.address || '',
        companyData.city || '',
        companyData.state || 'FL',
        companyData.zip_code || '',
        companyData.phone || '',
        companyData.email || '',
        companyData.website || null,
        companyData.fiscal_year_start || '01-01',
        companyData.currency || 'USD',
        companyData.language || 'es',
        companyData.timezone || 'America/New_York',
        companyData.date_format || 'MM/DD/YYYY',
        companyData.fiscal_year_end || '12-31',
        new Date().toISOString()
      ]);
      logger.info('CompanyData', 'upsert_insert_ok', 'Empresa creada correctamente');
      try { await forceSaveDB(); } catch (_) { }
      return { success: true, message: 'Datos de empresa creados correctamente' };
    }

    // CASO 2: Existe fila ΓÇö obtenerla y hacer UPDATE
    const currentData = getCompanyData();
    if (!currentData) {
      // Fallback: getCompanyData() fall├│ a pesar de que rowCount > 0
      logger.warn('CompanyData', 'update_fallback', 'getCompanyData() null con row presente ΓÇö UPDATE simple WHERE is_active=1');
      sqlRun(`
        UPDATE company_data SET
          company_name = ?, legal_name = ?, tax_id = ?,
          address = ?, city = ?, state = ?, zip_code = ?,
          phone = ?, email = ?, updated_at = ?
        WHERE is_active = 1
      `, [
        companyData.company_name || '',
        companyData.legal_name || '',
        companyData.tax_id || '',
        companyData.address || '',
        companyData.city || '',
        companyData.state || 'FL',
        companyData.zip_code || '',
        companyData.phone || '',
        companyData.email || '',
        new Date().toISOString()
      ]);
      try { await forceSaveDB(); } catch (_) { }
      return { success: true, message: 'Datos de empresa actualizados correctamente' };
    }

    // Preparar datos para actualizaci├│n
    // Filtrar undefined/null/'' para que currentData sirva como fallback
    const cleanInput = Object.fromEntries(
      Object.entries(companyData).filter(([, v]) => v !== undefined && v !== null && v !== '')
    );
    const updateData = {
      ...currentData,
      ...cleanInput,
      updated_at: new Date().toISOString()
    };

    // UPDATE completo con Statement API (patr├│n correcto sql.js)
    sqlRun(`
      UPDATE company_data SET
        company_name = ?,
        legal_name = ?,
        tax_id = ?,
        address = ?,
        city = ?,
        state = ?,
        zip_code = ?,
        phone = ?,
        email = ?,
        website = ?,
        logo_path = ?,
        fiscal_year_start = ?,
        currency = ?,
        language = ?,
        timezone = ?,
        sales_commission_rate = ?,
        sales_commission_percentage = ?,
        discount_amount = ?,
        discount_percentage = ?,
        shipping_rate = ?,
        shipping_percentage = ?,
        reposition_policy_days = ?,
        late_fee_amount = ?,
        late_fee_percentage = ?,
        annual_interest_rate = ?,
        grace_period_days = ?,
        documentation_cost = ?,
        other_costs = ?,
        chart_of_accounts_name = ?,
        date_format = ?,
        fiscal_year_end = ?,
        netIncreaseInCash = ?,
        updated_at = ?
      WHERE id = ? AND is_active = 1
    `, [
      updateData.company_name,
      updateData.legal_name,
      updateData.tax_id,
      updateData.address,
      updateData.city,
      updateData.state,
      updateData.zip_code,
      updateData.phone,
      updateData.email,
      updateData.website || null,
      updateData.logo_path || null,
      updateData.fiscal_year_start || '01-01',
      updateData.currency || 'USD',
      updateData.language || 'es',
      updateData.timezone || 'America/New_York',
      updateData.sales_commission_rate || 0,
      updateData.sales_commission_percentage || 0,
      updateData.discount_amount || 50,
      updateData.discount_percentage || 0,
      updateData.shipping_rate || 0,
      updateData.shipping_percentage || 0,
      updateData.reposition_policy_days || 32,
      updateData.late_fee_amount || 0,
      updateData.late_fee_percentage || 0,
      updateData.annual_interest_rate || 0,
      updateData.grace_period_days || 0,
      updateData.documentation_cost || 0,
      updateData.other_costs || 0,
      updateData.chart_of_accounts_name || 'Plan de Cuenta Ejemplo',
      updateData.date_format || 'MM/DD/YYYY',
      updateData.fiscal_year_end || '12-31',
      updateData.netIncreaseInCash || 0,
      updateData.updated_at,
      currentData.id
    ]);

    // Registrar en auditor├¡a
    const auditData = {
      old_name: currentData.company_name,
      new_name: updateData.company_name,
      changes: Object.keys(companyData),
      has_accounting_data: accountingDataCheck.hasData
    };

    logAuditEvent('company_data', currentData.id, 'UPDATE', JSON.stringify(currentData), JSON.stringify(updateData));

    logger.info('CompanyData', 'update_success', 'Datos de empresa actualizados', {
      company_id: currentData.id,
      changes: Object.keys(companyData),
      warnings_count: warnings.length
    });

    // Persistencia Inmediata
    await forceSaveDB();

    return {
      success: true,
      message: 'Datos de la empresa actualizados correctamente',
      warnings: warnings.length > 0 ? warnings : undefined
    };


  } catch (error) {
    logger.error('CompanyData', 'update_failed', 'Error al actualizar datos de empresa', null, error as Error);
    return {
      success: false,
      message: `Error al actualizar datos de empresa: ${error instanceof Error ? error.message : 'Error desconocido'} `
    };
  }
}

