    const columns = (result[0].columns || (result[0] as any).lc);
    return result[0].values.map((row: any) => {
      const obj: any = {};
      columns.forEach((col: any, i: any) => obj[col] = row[i]);
      return obj;
    });
  } catch (e) {
    console.error('Error fetching ARD customer summary:', e);
    return [];
  }
