        totalTaxCollected: Number(row[3]) || 0,
        countyBreakdown,
        exemptSales: Number(row[4]) || 0,
        adjustments,
        netTaxDue: Number(row[5]) || 0,
        dueDate: new Date(row[6] as string),
        filedBy: row[7] as number || undefined,
        filedAt: row[8] ? new Date(row[8] as string) : undefined,
