/**
 * Actualiza un m├⌐todo de pago existente
 */
export function updatePaymentMethod(id: number, methodData: Partial<PaymentMethod>): { success: boolean; message: string } {
  if (!db) {
    return { success: false, message: 'Base de datos no disponible' };
  }

  try {
    logger.info('PaymentMethods', 'update_start', 'Actualizando m├⌐todo de pago', { id, ...methodData });

    // Verificar que el m├⌐todo existe
    const existingResult = db.exec(`
      SELECT id, method_name FROM payment_methods WHERE id = ?
  `, [id]);

    if (existingResult.length === 0 || existingResult[0].values.length === 0) {
      return { success: false, message: 'M├⌐todo de pago no encontrado' };
    }

    const currentName = existingResult[0].values[0][1] as string;

    // Si se est├í cambiando el nombre, verificar que no exista otro con el mismo nombre
    if (methodData.method_name && methodData.method_name !== currentName) {
      const duplicateResult = db.exec(`
        SELECT id FROM payment_methods WHERE method_name = ? AND id != ?
  `, [methodData.method_name, id]);

      if (duplicateResult.length > 0 && duplicateResult[0].values.length > 0) {
        return { success: false, message: `Ya existe un m├⌐todo de pago con el nombre "${methodData.method_name}"` };
      }
    }

    // Construir la consulta de actualizaci├│n din├ímicamente
    const updateFields: string[] = [];
    const updateValues: any[] = [];

    if (methodData.method_name !== undefined) {
      updateFields.push('method_name = ?');
      updateValues.push(methodData.method_name);
    }

    if (methodData.method_type !== undefined) {
      updateFields.push('method_type = ?');
      updateValues.push(methodData.method_type);
    }

    if (methodData.is_active !== undefined) {
      updateFields.push('is_active = ?');
      updateValues.push(methodData.is_active ? 1 : 0);
    }

    if (methodData.requires_reference !== undefined) {
      updateFields.push('requires_reference = ?');
      updateValues.push(methodData.requires_reference ? 1 : 0);
    }

    if (updateFields.length === 0) {
      return { success: false, message: 'No hay campos para actualizar' };
    }

    updateValues.push(id);

    // Ejecutar actualizaci├│n
    db.exec(`
      UPDATE payment_methods 
      SET ${updateFields.join(', ')}
      WHERE id = ?
  `, updateValues);

    // Registrar en auditor├¡a
    db.exec(`
      INSERT INTO audit_log(table_name, record_id, action, new_values, user_id, audit_hash)
VALUES(?, ?, ?, ?, ?, ?)
    `, [
      'payment_methods',
      id,
      'UPDATE',
      JSON.stringify(methodData),
      1,
      generateSimpleHash(methodData)
    ]);

    logger.info('PaymentMethods', 'update_success', 'M├⌐todo de pago actualizado correctamente', { id });

    // Auto-save
    setTimeout(() => saveDatabase(), 1000);


    return {
      success: true,
      message: 'M├⌐todo de pago actualizado correctamente'
    };

  } catch (error) {
    logger.error('PaymentMethods', 'update_failed', 'Error al actualizar m├⌐todo de pago', { id, ...methodData }, error as Error);
    return {
      success: false,
      message: `Error al actualizar m├⌐todo de pago: ${error instanceof Error ? error.message : 'Error desconocido'} `
    };
  }
}

/**
 * Elimina un m├⌐todo de pago (soft delete - marca como inactivo)
 */
export function deletePaymentMethod(id: number): { success: boolean; message: string } {
  if (!db) {
    return { success: false, message: 'Base de datos no disponible' };
  }

  try {
    logger.info('PaymentMethods', 'delete_start', 'Eliminando m├⌐todo de pago', { id });

    // Verificar que el m├⌐todo existe
    const existingResult = db.exec(`
      SELECT id, method_name FROM payment_methods WHERE id = ?
  `, [id]);

    if (existingResult.length === 0 || existingResult[0].values.length === 0) {
      return { success: false, message: 'M├⌐todo de pago no encontrado' };
    }

    const methodName = existingResult[0].values[0][1] as string;

    // Verificar si el m├⌐todo est├í siendo usado en pagos
    const usageResult = db.exec(`
      SELECT COUNT(*) as count FROM(
    SELECT 1 FROM payments WHERE payment_method = ?
      UNION ALL
        SELECT 1 FROM supplier_payments WHERE payment_method = ?
      )
  `, [methodName.toLowerCase().replace(' ', '_'), methodName.toLowerCase().replace(' ', '_')]);

    const usageCount = usageResult[0].values[0][0] as number;

    if (usageCount > 0) {
      // Si est├í en uso, solo marcar como inactivo
      db.exec(`
        UPDATE payment_methods 
        SET is_active = 0
        WHERE id = ?
  `, [id]);

      logger.info('PaymentMethods', 'delete_soft', 'M├⌐todo de pago marcado como inactivo (en uso)', { id, methodName });

      return {
        success: true,
        message: `M├⌐todo de pago "${methodName}" desactivado(estaba en uso en ${usageCount} transacciones)`
      };
    } else {
      // Si no est├í en uso, eliminar completamente
      db.exec(`
        DELETE FROM payment_methods WHERE id = ?
  `, [id]);

      // Registrar en auditor├¡a
      db.exec(`
        INSERT INTO audit_log(table_name, record_id, action, old_values, user_id, audit_hash)
VALUES(?, ?, ?, ?, ?, ?)
      `, [
        'payment_methods',
        id,
        'DELETE',
        JSON.stringify({ method_name: methodName }),
        1,
        generateSimpleHash({ method_name: methodName })
      ]);

      logger.info('PaymentMethods', 'delete_hard', 'M├⌐todo de pago eliminado completamente', { id, methodName });

      return {
        success: true,
        message: `M├⌐todo de pago "${methodName}" eliminado correctamente`
      };
    }

  } catch (error) {
    logger.error('PaymentMethods', 'delete_failed', 'Error al eliminar m├⌐todo de pago', { id }, error as Error);
    return {
      success: false,
      message: `Error al eliminar m├⌐todo de pago: ${error instanceof Error ? error.message : 'Error desconocido'} `
    };
  }
}

