/**
 * Verifica si se puede eliminar un m├⌐todo de pago
 */
export function canDeletePaymentMethod(id: number): { canDelete: boolean; reason?: string } {
  if (!db) {
    return { canDelete: false, reason: 'Base de datos no disponible' };
  }

  try {
    // Verificar que el m├⌐todo existe
    const existingResult = db.exec(`
      SELECT method_name FROM payment_methods WHERE id = ?
  `, [id]);

    if (existingResult.length === 0 || existingResult[0].values.length === 0) {
      return { canDelete: false, reason: 'M├⌐todo de pago no encontrado' };
    }

    const methodName = existingResult[0].values[0][0] as string;

    // Verificar si est├í siendo usado
    const usageResult = db.exec(`
      SELECT COUNT(*) as count FROM(
    SELECT 1 FROM payments WHERE payment_method = ?
      UNION ALL
        SELECT 1 FROM supplier_payments WHERE payment_method = ?
      )
    `, [methodName.toLowerCase().replace(' ', '_'), methodName.toLowerCase().replace(' ', '_')]);

    const usageCount = usageResult[0].values[0][0] as number;

    if (usageCount > 0) {
      return {
        canDelete: false,
        reason: `El m├⌐todo de pago est├í siendo usado en ${usageCount} transacciones. Solo se puede desactivar.`
      };
    }

    return { canDelete: true };

  } catch (error) {
    logger.error('PaymentMethods', 'can_delete_failed', 'Error al verificar si se puede eliminar m├⌐todo de pago', { id }, error as Error);
    return { canDelete: false, reason: 'Error al verificar el m├⌐todo de pago' };
  }
}
