/**
 * Crear una nueva cuenta bancaria
 */
export async function createBankAccount(data: Omit<BankAccount, 'id' | 'created_at'>): Promise<{ success: boolean; message: string; id?: number }> {
  if (!db) return { success: false, message: 'Base de datos no disponible' };

  try {
    const stmt = db.prepare(`
      INSERT INTO bank_accounts(
        account_name, bank_name, account_number, account_type,
        routing_number, balance, currency, is_active, notes
      ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);

    stmt.run([
      data.account_name,
      data.bank_name,
      data.account_number,
      data.account_type,
      data.routing_number || null,
      data.balance || 0,
      data.currency || 'USD',
      data.is_active ? 1 : 0,
      data.notes || null
    ]);

    const idResult = db.exec("SELECT last_insert_rowid()");
    const id = idResult[0].values[0][0] as number;

    // Auditor├¡a
    const auditStmt = db.prepare(`
      INSERT INTO audit_log(table_name, record_id, action, new_values, user_id, audit_hash)
      VALUES(?, ?, ?, ?, ?, ?)
    `);
    auditStmt.run([
      'bank_accounts',
      id,
      'INSERT',
      JSON.stringify(data),
      1,
      generateSimpleHash(data)
    ]);
    auditStmt.free();

    logger.info('BankAccounts', 'create_success', 'Cuenta bancaria creada', { id });

    // Limpieza y Persistencia
    stmt.free();
    await forceSaveDB();

    return { success: true, message: 'Cuenta bancaria creada correctamente', id };
  } catch (error) {
    logger.error('BankAccounts', 'create_failed', 'Error al crear cuenta bancaria', null, error as Error);
    return { success: false, message: error instanceof Error ? error.message : 'Error desconocido' };
  }
}

/**
 * Actualiza una cuenta bancaria existente
 */
export async function updateBankAccount(id: number, data: Partial<BankAccount>): Promise<{ success: boolean; message: string }> {
  if (!db) return { success: false, message: 'Base de datos no disponible' };

  try {
    const updateFields: string[] = [];
    const updateValues: any[] = [];

    // Lista de campos actualizables
    const fields = ['account_name', 'bank_name', 'account_number', 'account_type', 'routing_number', 'balance', 'currency', 'is_active', 'notes'];

    fields.forEach(field => {
      if ((data as any)[field] !== undefined) {
        updateFields.push(`${field} = ?`);
        let val = (data as any)[field];
        if (typeof val === 'boolean') val = val ? 1 : 0;
        updateValues.push(val);
      }
    });

    if (updateFields.length === 0) {
      return { success: false, message: 'No hay datos para actualizar' };
    }

    updateValues.push(id);

    const stmt = db.prepare(`UPDATE bank_accounts SET ${updateFields.join(', ')} WHERE id = ? `);
    stmt.run(updateValues);

    // Auditor├¡a
    const updateAuditStmt = db.prepare(`
      INSERT INTO audit_log(table_name, record_id, action, new_values, user_id, audit_hash)
      VALUES(?, ?, ?, ?, ?, ?)
    `);
    updateAuditStmt.run([
      'bank_accounts',
      id,
      'UPDATE',
      JSON.stringify(data),
      1,
      generateSimpleHash(data)
    ]);
    updateAuditStmt.free();
    stmt.free();

    logger.info('BankAccounts', 'update_success', 'Cuenta bancaria actualizada', { id });

    // Persistencia Inmediata
    await forceSaveDB();

    return { success: true, message: 'Cuenta bancaria actualizada correctamente' };
  } catch (error) {
    logger.error('BankAccounts', 'update_failed', 'Error al actualizar cuenta bancaria', { id }, error as Error);
    return { success: false, message: error instanceof Error ? error.message : 'Error desconocido' };
  }
}

/**
 * Elimina una cuenta bancaria (o la desactiva si tiene saldo)
 */
export function deleteBankAccount(id: number): { success: boolean; message: string } {
  if (!db) return { success: false, message: 'Base de datos no disponible' };

  try {
    // Verificar saldo
    const account = getBankAccountById(id);
    if (!account) return { success: false, message: 'Cuenta no encontrada' };

    const hasBalance = account.balance !== 0;
    const txCount = getBankAccountTransactionCount(id);

    // L├│gica de discriminaci├│n:
    if (txCount === 0 && !hasBalance) {
      // Hard Delete: La cuenta nunca se us├│ y no tiene saldo. Limpieza f├¡sica.
      const hardDeleteStmt = db.prepare("DELETE FROM bank_accounts WHERE id = ?");
      hardDeleteStmt.run([id]);
      hardDeleteStmt.free();
    } else {
      // Soft Delete: La cuenta tiene historia o saldo. Preservamos para auditor├¡a.
      const softDeleteStmt = db.prepare("UPDATE bank_accounts SET is_active = 0 WHERE id = ?");
      softDeleteStmt.run([id]);
      softDeleteStmt.free();
    }

    // Auditor├¡a
    const deleteAuditStmt = db.prepare(`
      INSERT INTO audit_log(table_name, record_id, action, old_values, user_id, audit_hash)
      VALUES(?, ?, ?, ?, ?, ?)
    `);
    deleteAuditStmt.run([
      'bank_accounts',
      id,
      'DELETE',
      JSON.stringify(account),
      1,
      generateSimpleHash(account)
    ]);
    deleteAuditStmt.free();

    logger.info('BankAccounts', 'delete_success', 'Cuenta bancaria desactivada/eliminada', { id });
    // Auto-save
    setTimeout(() => saveDatabase(), 1000);

    return {
      success: true,
      message: hasBalance
        ? 'Cuenta desactivada (ten├¡a saldo activo ΓÇö no se puede eliminar definitivamente)'
        : 'Cuenta bancaria eliminada correctamente'
    };
  } catch (error) {
    logger.error('BankAccounts', 'delete_failed', 'Error al eliminar cuenta bancaria', { id }, error as Error);
    return { success: false, message: error instanceof Error ? error.message : 'Error desconocido' };
  }
}

