  if (!db) return [];

  try {
    let query = 'SELECT * FROM payroll WHERE employee_id = ?';
    const params: any[] = [employeeId];

    if (year) {
      query += ' AND strftime("%Y", pay_date) = ?';
      params.push(year.toString());
