          </div>

          {/* Botones */}
          <div className="flex gap-4 justify-end">
            <button
              type="button"
              onClick={onCancel}
              className="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg transition-colors"
            >
              {t('quotes.form.cancel')}
            </button>
            <button
              type="submit"
              className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors flex items-center gap-2"
            >
              <Save className="w-5 h-5" />
              {quote ? t('quotes.form.update') : t('quotes.form.create')} {t('quotes.form.quote')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Quote } from '@/database/simple-db';
import { FileText, Eye, Edit, Trash2, CheckCircle, XCircle, Clock, ArrowRight, Zap, Plus } from 'lucide-react';
import { useLocale } from '../../../i18n/useLocale';

interface QuoteListProps {
  quotes: Quote[];
  onView: (quote: Quote) => void;
  onEdit: (quote: Quote) => void;
  onDelete: (id: number) => void;
  onConvert: (id: number) => void;
}

export const QuoteList: React.FC<QuoteListProps> = ({
  quotes,
  onView,
  onEdit,
  onDelete,
  onConvert
}) => {
  const { t } = useLocale();
  const [filterStatus, setFilterStatus] = useState<string>('all');

  const filteredQuotes = quotes.filter(quote => {
    if (filterStatus === 'all') return true;
    return quote.status === filterStatus;
  });

  const getStatusBadge = (status: string) => {
    const badges = {
      draft: { label: t('quotes.status.draft'), color: 'bg-slate-600', icon: FileText },
      sent: { label: t('quotes.status.sent'), color: 'bg-blue-600', icon: Clock },
      accepted: { label: t('quotes.status.accepted'), color: 'bg-green-600', icon: CheckCircle },
      rejected: { label: t('quotes.status.rejected'), color: 'bg-red-600', icon: XCircle },
      expired: { label: t('quotes.status.expired'), color: 'bg-orange-600', icon: Clock },
      converted: { label: t('quotes.status.converted'), color: 'bg-purple-600', icon: ArrowRight }
    };

    const badge = badges[status as keyof typeof badges] || badges.draft;
    const Icon = badge.icon;

    return (
      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold text-white ${badge.color}`}>
        <Icon className="w-3.5 h-3.5" />
        {badge.label}
      </span>
    );
  };

  const handleConvert = (quote: Quote) => {
    if (quote.status !== 'accepted') {
      alert(t('quotes.alerts.onlyAccepted'));
      return;
    }

    if (confirm(t('quotes.alerts.confirmConvert', { number: quote.quote_number }))) {
      onConvert(quote.id);
    }
  };

  return (
    <div className="elite-page-container">
      {/* Header Hub */}
      <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-blue-600/10 rounded-2.5xl border border-blue-500/20 shadow-blue-900/10 shadow-lg group">
            <FileText className="w-10 h-10 text-blue-500 group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none">{t('quotes.title') || 'Cotizaciones'}</h1>
            <p className="text-slate-500 font-medium text-sm mt-3 flex items-center gap-2">
              <Zap className="w-3.5 h-3.5 text-blue-500 animate-pulse" /> {t('quotes.subtitle') || 'Gesti├│n de propuestas comerciales'}
            </p>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="card-elite-flat">
        <div className="flex items-center gap-4">
          <label className="text-sm font-medium text-slate-300">{t('quotes.filterStatus')}:</label>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2 bg-slate-900 border border-slate-700 rounded-lg text-white focus:ring-2 focus:ring-blue-500"
          >
            <option value="all">{t('quotes.status.all')}</option>
            <option value="draft">{t('quotes.status.draft')}</option>
            <option value="sent">{t('quotes.status.sent')}</option>
            <option value="accepted">{t('quotes.status.accepted')}</option>
            <option value="rejected">{t('quotes.status.rejected')}</option>
            <option value="expired">{t('quotes.status.expired')}</option>
            <option value="converted">{t('quotes.status.converted')}</option>
          </select>
          <span className="text-sm text-slate-400">
            {t('quotes.count', { count: filteredQuotes.length })}
          </span>
        </div>
      </div>

      {/* Lista de Cotizaciones */}
      {filteredQuotes.length === 0 ? (
        <div className="bg-slate-800 p-12 rounded-lg border border-slate-700 text-center">
          <FileText className="w-16 h-16 text-slate-600 mx-auto mb-4" />
          <p className="text-slate-400 text-lg">{t('quotes.emptyList')}</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {filteredQuotes.map(quote => (
            <div
              key={quote.id}
              className="bg-slate-800 p-6 rounded-lg border border-slate-700 hover:border-blue-500 transition-all"
            >
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-4 mb-3">
                    <h3 className="text-xl font-bold tracking-tight text-white">
                      {quote.quote_number}
                    </h3>
                    {getStatusBadge(quote.status)}
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                    <div>
                      <span className="text-slate-400">{t('quotes.customer')}:</span>
                      <p className="text-white font-medium">{(quote as any).customer_name || 'N/A'}</p>
                    </div>
                    <div>
                      <span className="text-slate-400">{t('quotes.issueDate')}:</span>
                      <p className="text-white font-medium">
                        {new Date(quote.issue_date).toLocaleDateString()}
                      </p>
                    </div>
                    <div>
                      <span className="text-slate-400">{t('quotes.expirationDate')}:</span>
                      <p className="text-white font-medium">
                        {new Date(quote.expiration_date).toLocaleDateString()}
                      </p>
                    </div>
                    <div>
                      <span className="text-slate-400">{t('quotes.total')}:</span>
                      <p className="text-white font-bold text-lg">
                        ${quote.total_amount.toFixed(2)}
                      </p>
                    </div>
                  </div>

                  {quote.notes && (
                    <div className="mt-3 text-sm text-slate-400">
                      <span className="font-medium">{t('quotes.notes')}:</span> {quote.notes}
                    </div>
                  )}
                </div>

                <div className="flex gap-2 ml-4">
                  <button
                    onClick={() => onView(quote)}
                    className="p-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
                    title={t('quotes.actions.view')}
                  >
                    <Eye className="w-5 h-5" />
                  </button>

                  {quote.status !== 'converted' && (
                    <>
                      <button
                        onClick={() => onEdit(quote)}
                        className="p-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg transition-colors"
                        title={t('quotes.actions.edit')}
                      >
                        <Edit className="w-5 h-5" />
                      </button>

                      {quote.status === 'accepted' && (
                        <button
                          onClick={() => handleConvert(quote)}
                          className="p-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors"
                          title={t('quotes.actions.convert')}
                        >
                          <ArrowRight className="w-5 h-5" />
                        </button>
                      )}

                      <button
                        onClick={() => {
                          if (confirm(t('quotes.alerts.confirmDelete'))) {
                            onDelete(quote.id);
                          }
                        }}
                        className="p-2 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-colors"
                        title={t('quotes.actions.delete')}
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CreditCard, Calendar, DollarSign, FileText, Search, Plus, Check, X, Zap } from 'lucide-react';
import { useAuth } from '../../../contexts/AuthContext';
import { Invoice, Customer, getPaymentMethods, PaymentMethod, createPayment, Payment } from '@/database/simple-db';
import { useLocale } from '../../../i18n/useLocale';

interface CustomerPayment {
  id: number;
  invoice_id: number;
  customer_id: number;
  amount: number;
  payment_date: string;
  payment_method: string;
  reference: string;
  notes?: string;
  created_at: string;
}

interface CustomerPaymentsProps {
  invoices: Invoice[];
  customers: Customer[];
  onPaymentCreated: () => void;
}

export const CustomerPayments: React.FC<CustomerPaymentsProps> = ({
  invoices,
  customers,
  onPaymentCreated
}) => {
  const { t } = useLocale();
  const { user } = useAuth();
  const [payments, setPayments] = useState<CustomerPayment[]>([]);
  const [pendingInvoices, setPendingInvoices] = useState<Invoice[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([]);
  const [showPaymentForm, setShowPaymentForm] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'pending' | 'paid'>('pending');
  const [isLoading, setIsLoading] = useState(false);

  const [paymentForm, setPaymentForm] = useState({
    amount: '',
    payment_date: new Date().toISOString().split('T')[0],
    payment_method: '',
    reference: '',
    notes: ''
  });

  useEffect(() => {
    loadPendingInvoices();
    loadPayments();
    loadPaymentMethods();
  }, [invoices]);

  const loadPaymentMethods = () => {
    try {
      const methods = getPaymentMethods();
      setPaymentMethods(methods);

      // Si hay m├⌐todos disponibles, seleccionar el primero por defecto
      if (methods.length > 0 && !paymentForm.payment_method) {
        setPaymentForm(prev => ({ ...prev, payment_method: methods[0].method_name }));
      }
    } catch (error) {
      console.error('Error loading payment methods:', error);
    }
  };

  const loadPendingInvoices = () => {
    // Filtrar facturas pendientes (asumiendo que las pagadas tienen status 'paid')
    const pending = invoices.filter(invoice =>
      invoice.status !== 'paid'
    );
    setPendingInvoices(pending);
  };

  const loadPayments = () => {
    // En una implementaci├│n real, esto vendr├¡a de la base de datos
    // Por ahora simulamos algunos pagos
    const mockPayments: CustomerPayment[] = [];
    setPayments(mockPayments);
  };

  const getCustomerName = (customerId: number) => {
    const customer = customers.find(c => c.id === customerId);
    return customer ? customer.name : t('invoiceList.unknownCustomer');
  };

  const filteredInvoices = pendingInvoices.filter(invoice => {
    const customerName = getCustomerName(invoice.customer_id).toLowerCase();
    const matchesSearch = customerName.includes(searchTerm.toLowerCase()) ||
      invoice.invoice_number.toLowerCase().includes(searchTerm.toLowerCase());

    if (filterStatus === 'all') return matchesSearch;
    if (filterStatus === 'pending') return matchesSearch && invoice.status !== 'paid';
    if (filterStatus === 'paid') return matchesSearch && invoice.status === 'paid';

    return matchesSearch;
  });

  const handlePaymentSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedInvoice) return;

    setIsLoading(true);
    try {
      // Map form data to database Payment interface
      const paymentData: Partial<Payment> = {
        customer_id: selectedInvoice.customer_id,
        invoice_id: selectedInvoice.id,
        amount: parseFloat(paymentForm.amount),
        payment_date: paymentForm.payment_date,
        payment_method: paymentForm.payment_method as any, // Cast string to union type
        reference_number: paymentForm.reference,
        notes: paymentForm.notes
      };

      const result = createPayment(paymentData, user?.id || 1); // TODO: Get real userId from context

      if (!result.success) {
        throw new Error(result.message);
      }

      // Update local state with the created payment structure
      const payment: CustomerPayment = {
        id: result.paymentId || Date.now(),
        invoice_id: selectedInvoice.id,
        customer_id: selectedInvoice.customer_id,
        amount: parseFloat(paymentForm.amount),
        payment_date: paymentForm.payment_date,
        payment_method: paymentForm.payment_method,
        reference: paymentForm.reference,
        notes: paymentForm.notes,
        created_at: new Date().toISOString()
      };

      setPayments(prev => [...prev, payment]);
      setShowPaymentForm(false);
      setSelectedInvoice(null);
      setPaymentForm({
        amount: '',
        payment_date: new Date().toISOString().split('T')[0],
        payment_method: paymentMethods.length > 0 ? paymentMethods[0].method_name : '',
        reference: '',
        notes: ''
      });

      onPaymentCreated();
    } catch (error) {
      console.error('Error creating payment:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handlePayInvoice = (invoice: Invoice) => {
    setSelectedInvoice(invoice);
    setPaymentForm(prev => ({
      ...prev,
      amount: invoice.total_amount.toString(),
      payment_method: paymentMethods.length > 0 ? paymentMethods[0].method_name : ''
    }));
    setShowPaymentForm(true);
  };

  return (
    <div className="elite-page-container">
      {/* Header Hub */}
      <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
        <div className="flex items-center gap-6">
          <div className="p-4 bg-emerald-600/10 rounded-2.5xl border border-emerald-500/20 shadow-emerald-900/10 shadow-lg group">
            <CreditCard className="w-10 h-10 text-emerald-500 group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight leading-none">{t('customerPayments.title')}</h1>
            <p className="text-slate-500 font-medium text-sm mt-3 flex items-center gap-2">
              <Zap className="w-3.5 h-3.5 text-emerald-500 animate-pulse" /> {t('customerPayments.subtitle')}
            </p>
          </div>
        </div>
      </div>

      {/* Filters and Search */}
      <div className="card-elite-flat">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
              <input
                type="text"
                placeholder={t('customerPayments.searchPlaceholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>
          </div>
          <div className="flex gap-2">
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
              className="px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="pending" className="text-black">{t('customerPayments.pendingInvoices')}</option>
              <option value="paid" className="text-black">{t('invoiceList.paid')}</option>
              <option value="all" className="text-black">{t('invoiceList.allStatuses')}</option>
            </select>
          </div>
        </div>
      </div>

      {/* Pending Invoices List */}
      <div className="card-elite-flat overflow-hidden p-0">
        <div className="px-8 py-5 border-b border-slate-800 bg-slate-900/50">
          <h3 className="text-xl font-bold text-white tracking-tight">{t('customerPayments.pendingInvoices')}</h3>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-slate-900">
              <tr>
                <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                  {t('customerPayments.invoice')}
                </th>
                <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                  {t('invoiceForm.customer')}
                </th>
                <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                  {t('common.date')}
                </th>
                <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                  {t('common.amount')}
                </th>
                <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                  {t('customerPayments.daysOverdue')}
                </th>
                <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-wider text-slate-500">
                  {t('common.actions')}
                </th>
              </tr>
            </thead>
            <tbody className="bg-white/10 divide-y divide-gray-700">
              {filteredInvoices.map((invoice) => {
                const daysOverdue = Math.floor(
                  (new Date().getTime() - new Date(invoice.issue_date).getTime()) / (1000 * 60 * 60 * 24)
                );

                return (
                  <tr key={invoice.id} className="hover:bg-white/5">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <FileText className="w-4 h-4 text-slate-500 mr-2" />
                        <span className="text-sm font-medium text-white">
                          {invoice.invoice_number}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-white">
                        {getCustomerName(invoice.customer_id)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-400">
                      {new Date(invoice.issue_date).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm font-medium text-white">
                        ${invoice.total_amount.toFixed(2)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${daysOverdue > 30
                        ? 'bg-red-100 text-red-800'
                        : daysOverdue > 0
                          ? 'bg-yellow-100 text-yellow-800'
                          : 'bg-green-100 text-green-800'
                        }`}>
                        {daysOverdue > 0 ? t('common.days', { n: daysOverdue }) : t('customerPayments.upToDate')}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <button
                        onClick={() => handlePayInvoice(invoice)}
                        className="inline-flex items-center px-3 py-1 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                      >
                        <CreditCard className="w-4 h-4 mr-1" />
                        {t('customerPayments.registerPayment')}
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {filteredInvoices.length === 0 && (
            <div className="text-center py-8">
              <FileText className="mx-auto h-12 w-12 text-slate-500" />
              <h3 className="mt-2 text-sm font-medium text-white">{t('customerPayments.noInvoices')}</h3>
              <p className="mt-1 text-sm text-slate-400">
                {filterStatus === 'pending'
                  ? t('customerPayments.noPendingInvoices')
                  : t('customerPayments.noFilteredInvoices')
                }
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Modal de formulario de pago */}
      {showPaymentForm && selectedInvoice && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full z-50">
          <div className="relative top-20 mx-auto p-5 border w-96 shadow-lg rounded-md bg-white/10 border-white/10">
            <div className="mt-3">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-black text-white tracking-tight">
                  {t('customerPayments.modalTitle')}
                </h3>
                <button
                  onClick={() => setShowPaymentForm(false)}
                  className="text-slate-500 hover:text-slate-400"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="mb-4 p-3 bg-white/5 rounded-md">
                <p className="text-sm text-slate-400">
                  <strong className="text-white">{t('customerPayments.invoice')}:</strong> {selectedInvoice.invoice_number}
                </p>
                <p className="text-sm text-slate-400">
                  <strong className="text-white">{t('invoiceForm.customer')}:</strong> {getCustomerName(selectedInvoice.customer_id)}
                </p>
                <p className="text-sm text-slate-400">
                  <strong className="text-white">{t('invoiceList.totalAmount')}:</strong> ${selectedInvoice.total_amount.toFixed(2)}
                </p>
              </div>

              <form onSubmit={handlePaymentSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('customerPayments.amountToPay')}
                  </label>
                  <div className="relative">
                    <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
                    <input
                      type="number"
                      step="0.01"
                      value={paymentForm.amount}
                      onChange={(e) => setPaymentForm(prev => ({ ...prev, amount: e.target.value }))}
                      className="w-full pl-10 pr-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('customerPayments.paymentDate')}
                  </label>
                  <div className="relative">
                    <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-500 w-4 h-4" />
                    <input
                      type="date"
                      value={paymentForm.payment_date}
                      onChange={(e) => setPaymentForm(prev => ({ ...prev, payment_date: e.target.value }))}
                      className="w-full pl-10 pr-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('customerPayments.paymentMethod')}
                  </label>
                  <select
                    value={paymentForm.payment_method}
                    onChange={(e) => setPaymentForm(prev => ({ ...prev, payment_method: e.target.value }))}
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    required
                  >
                    <option value="" className="text-black">{t('customerPayments.selectMethod')}</option>
                    {paymentMethods.map((method) => (
                      <option key={method.id} value={method.method_name} className="text-black">
                        {method.method_name}
                      </option>
                    ))}
                  </select>
                  {paymentMethods.length === 0 && (
                    <p className="mt-1 text-sm text-red-600">
                      {t('customerPayments.noMethods')}
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('customerPayments.referenceNumber')}
                  </label>
                  <input
                    type="text"
                    value={paymentForm.reference}
                    onChange={(e) => setPaymentForm(prev => ({ ...prev, reference: e.target.value }))}
                    placeholder={t('customerPayments.referencePlaceholder')}
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-white mb-1">
                    {t('customerPayments.notes')}
                  </label>
                  <textarea
                    value={paymentForm.notes}
                    onChange={(e) => setPaymentForm(prev => ({ ...prev, notes: e.target.value }))}
                    rows={3}
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-white placeholder-gray-400 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder={t('customerPayments.notesPlaceholder')}
                  />
                </div>

                <div className="flex justify-end space-x-3 pt-4">
                  <button
                    type="button"
                    onClick={() => setShowPaymentForm(false)}
                    className="px-4 py-2 border border-white/10 rounded-md text-sm font-medium text-slate-400 hover:bg-white/5 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                  >
                    {t('customerForm.close')}
                  </button>
                  <button
                    type="submit"
                    disabled={isLoading}
                    className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50"
                  >
                    {isLoading ? t('customerPayments.processing') : t('customerPayments.registerPayment')}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { TrendingUp, Users, DollarSign, Clock, Filter, Printer, Download, Zap } from 'lucide-react';
import { getInvoices, Invoice, getCustomers, Customer } from '@/database/simple-db';
import { useLocale } from '../../../i18n/useLocale';

export const ReceivableReports: React.FC = () => {
    const { t, formatCurrency } = useLocale();
    const [loading, setLoading] = useState(false);
    const [receivables, setReceivables] = useState<any[]>([]);

    useEffect(() => {
        const invoices = getInvoices();
        const customers = getCustomers();

        // Calculate aging
        const now = new Date();
        const pending = invoices.filter(inv => inv.status !== 'paid' && inv.status !== 'cancelled');

        const reportData = customers.map(customer => {
            const customerInvoices = pending.filter(inv => inv.customer_id === customer.id);
            const totalDue = customerInvoices.reduce((sum, inv) => sum + (inv.total_amount || 0), 0);

            const aging = {
                current: 0,
                days30: 0,
                days60: 0,
                days90plus: 0
            };

            customerInvoices.forEach(inv => {
                const dueDate = new Date(inv.due_date || inv.issue_date);
                const diffDays = Math.floor((now.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));

                if (diffDays <= 0) aging.current += inv.total_amount || 0;
                else if (diffDays <= 30) aging.days30 += inv.total_amount || 0;
                else if (diffDays <= 60) aging.days60 += inv.total_amount || 0;
                else aging.days90plus += inv.total_amount || 0;
            });

            return {
                ...customer,
                totalDue,
                aging
            };
        }).filter(c => c.totalDue > 0);

        setReceivables(reportData);
    }, []);

    return (
        <div className="elite-page-container">
            {/* Header Hub */}
            <div className="flex flex-col xl:flex-row items-center justify-between gap-8 border-b border-slate-800 pb-10">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-blue-600/10 rounded-2.5xl border border-blue-500/20 shadow-blue-900/10 shadow-lg group">
                        <TrendingUp className="w-10 h-10 text-blue-500 group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-white tracking-tight leading-none">{t('receivableReports.title')}</h1>
                        <p className="text-slate-500 font-medium text-sm mt-2 flex items-center gap-2">
                            <Zap className="w-3.5 h-3.5 text-blue-500 animate-pulse" /> {t('receivableReports.subtitle')}
                        </p>
                    </div>
                </div>
                <div className="flex gap-4 no-print">
                    <button
                        className="flex items-center gap-2 px-6 py-3.5 bg-slate-950 border border-slate-800 text-slate-300 rounded-2xl font-bold text-sm transition-all hover:bg-slate-900 hover:text-white"
                        onClick={() => window.print()}
                    >
                        <Printer className="w-4 h-4" /> {t('receivableReports.print')}
                    </button>
                    <button
                        className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold text-sm transition-all shadow-xl shadow-blue-900/40 hover:-translate-y-1"
                    >
                        <Download className="w-4 h-4" /> {t('receivableReports.export')}
                    </button>
                </div>
            </div>

            <div className="elite-grid-stats">
                <StatCard title={t('receivableReports.totalReceivable')} value={formatCurrency(receivables.reduce((s, r) => s + r.totalDue, 0))} icon={DollarSign} color="blue" />
                <StatCard title={t('receivableReports.customersWithDebt')} value={receivables.length.toString()} icon={Users} color="purple" />
                <StatCard title={t('receivableReports.overdue90')} value={formatCurrency(receivables.reduce((s, r) => s + r.aging.days90plus, 0))} icon={Clock} color="rose" />
                <StatCard title={t('receivableReports.collectionsToday')} value={formatCurrency(receivables.reduce((s, r) => s + r.aging.current, 0))} icon={TrendingUp} color="emerald" />
            </div>

            <Card className="card-elite-flat overflow-hidden p-0">
                <div className="bg-slate-900 border-b border-slate-800 flex flex-row items-center justify-between py-5 px-8">
                    <h3 className="text-xl font-bold text-white tracking-tight">{t('receivableReports.portfolioDetail')}</h3>
                    <button className="flex items-center gap-2 text-slate-400 hover:text-white transition-colors text-sm font-medium"><Filter className="w-4 h-4" /> {t('receivableReports.filter')}</button>
                </div>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-slate-900/50 text-slate-500 text-[10px] font-bold uppercase tracking-wider border-b border-slate-800">
                                <tr>
                                    <th className="px-6 py-4">{t('receivableReports.table.customer')}</th>
                                    <th className="px-6 py-4 text-right">{t('receivableReports.table.current')}</th>
                                    <th className="px-6 py-4 text-right">{t('receivableReports.table.days1_30')}</th>
                                    <th className="px-6 py-4 text-right">{t('receivableReports.table.days31_60')}</th>
                                    <th className="px-6 py-4 text-right">{t('receivableReports.table.days61_plus')}</th>
                                    <th className="px-6 py-4 text-right">{t('receivableReports.table.totalDebt')}</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-800">
                                {receivables.map((data, idx) => (
                                    <tr key={idx} className="hover:bg-slate-900/40 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="text-standard-body font-bold text-white">{data.name}</div>
                                            <div className="text-[10px] text-slate-500 font-mono tracking-tighter uppercase">{data.id}</div>
                                        </td>
                                        <td className="px-6 py-4 text-right font-mono text-emerald-400 font-bold">{formatCurrency(data.aging.current)}</td>
                                        <td className="px-6 py-4 text-right font-mono text-amber-400 font-bold">{formatCurrency(data.aging.days30)}</td>
                                        <td className="px-6 py-4 text-right font-mono text-orange-500 font-bold">{formatCurrency(data.aging.days60)}</td>
                                        <td className="px-6 py-4 text-right font-mono text-rose-500 font-bold">{formatCurrency(data.aging.days90plus)}</td>
                                        <td className="px-6 py-4 text-right font-mono text-white text-lg font-black">{formatCurrency(data.totalDue)}</td>
                                    </tr>
                                ))}
                                {receivables.length === 0 && (
                                    <tr>
                                        <td colSpan={6} className="px-6 py-12 text-center text-slate-500 font-medium italic">
                                            {t('receivableReports.table.empty')}
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
};

const StatCard = ({ title, value, icon: Icon, color }: any) => {
    const colorMap: any = {
        blue: 'text-blue-400 bg-blue-500/10 border-blue-500/20',
        purple: 'text-purple-400 bg-purple-500/10 border-purple-500/20',
        rose: 'text-rose-400 bg-rose-500/10 border-rose-500/20',
        emerald: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
    };

    return (
        <Card className="card-elite-flat">
            <CardContent className="p-0">
                <div className="flex items-center justify-between mb-4">
                    <div className={`p-2.5 rounded-xl border ${colorMap[color]}`}>
                        <Icon className="w-5 h-5" />
                    </div>
                </div>
                <div>
                    <div className="text-2xl font-black text-white tracking-tight">{value}</div>
                    <div className="text-slate-500 text-xs font-bold uppercase tracking-wider mt-1.5">{title}</div>
                </div>
            </CardContent>
        </Card>
    );
};

import React, { useState } from 'react';
import { Plus, Save, X, Calculator, User, MapPin } from 'lucide-react';
import { Customer, Product } from '@/database/simple-db';
import { useLocale } from '../../../i18n/useLocale';
// Note: We use the simple-db types for UI compatibility, 
// but the submission will go to the robust InvoiceService.

interface SalesInvoiceFormProps {
    onSubmit: (data: any) => Promise<void>;
    onCancel?: () => void;
    customers: Customer[];
    products: Product[];
    currentUserId: number;
}

interface ItemData {
    product_id: number | '';
    description: string;
    quantity: number;
    unit_price: number;
    taxable: boolean;
    cost: number;
}

const FLORIDA_COUNTIES = [
    'Miami-Dade', 'Broward', 'Palm Beach', 'Orange', 'Hillsborough', 'Duval', 'Pinellas', 'Lee', 'Polk', 'Brevard'
]; // Simplified list for MVP

export const SalesInvoiceForm: React.FC<SalesInvoiceFormProps> = ({
    onSubmit,
    onCancel,
    customers,
    products,
    currentUserId
}) => {
    const [formData, setFormData] = useState({
        customer_id: '' as number | '',
        county: 'Miami-Dade', // Default or derived from customer
        notes: ''
    });

    const [items, setItems] = useState<ItemData[]>([
        { product_id: '', description: '', quantity: 1, unit_price: 0, taxable: true, cost: 0 }
    ]);

    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleCustomerChange = (customerId: number) => {
        const cust = customers.find(c => c.id === customerId);
        setFormData(prev => ({
            ...prev,
            customer_id: customerId,
            county: cust?.florida_county && FLORIDA_COUNTIES.includes(cust.florida_county) ? cust.florida_county : prev.county
        }));
    };

    const handleItemChange = (index: number, field: keyof ItemData, value: any) => {
        const newItems = [...items];
        newItems[index] = { ...newItems[index], [field]: value };

        // Auto-fill from product
        if (field === 'product_id' && value) {
            const product = products.find(p => p.id === parseInt(value));
            if (product) {
                newItems[index].description = product.name;
                newItems[index].unit_price = product.price;
                // Cost is internal, usually hidden, but needed for profit analysis
                newItems[index].cost = product.cost || 0;
                // We assume taxable status might come from product in future, defaulting true
            }
        }
        setItems(newItems);
    };

    const addItem = () => {
        setItems([...items, { product_id: '', description: '', quantity: 1, unit_price: 0, taxable: true, cost: 0 }]);
    };

    const removeItem = (index: number) => {
        if (items.length > 1) {
            setItems(items.filter((_, i) => i !== index));
        }
    };

    const calculateEstimation = () => {
        // accurate tax calculation happens on backend, this is just a UI estimate
        const subtotal = items.reduce((acc, item) => acc + (item.quantity * item.unit_price), 0);
        return subtotal;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.customer_id) {
            setError("El cliente es requerido");
            return;
        }

        setIsSubmitting(true);
        setError(null);

        try {
            await onSubmit({
                customerId: formData.customer_id,
                county: formData.county,
                userId: currentUserId,
                lines: items.map(i => ({
                    // The Schema lines: { productId: number, description: string... } 
                    // If productId is empty, we must ensure the backend handles it or enforce it. 
                    // Creating 'Ad-hoc' items on the fly might not be supported yet by stock deduction logic.
                    // Let's enforce Product Selection for V1 safety or handle ad-hoc logic.
                    // The Schema says: productId: z.number()
                    productId: i.product_id ? Number(i.product_id) : 0, // 0 might fail FK. 
                    description: i.description,
                    quantity: Number(i.quantity),
                    unitPrice: Number(i.unit_price),
                    taxable: i.taxable,
                    cost: Number(i.cost)
                }))
            });
        } catch (e: any) {
            setError(e.message || "Transacci├│n Fallida");
            setIsSubmitting(false);
        }
    };

    const subtotal = calculateEstimation();

    return (
        <div className="bg-white/10 rounded-lg p-6 border border-white/10 shadow-xl">
            <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-black tracking-tight text-white flex items-center gap-2">
                    <span className="p-2 bg-blue-600 rounded-lg"><Calculator className="w-5 h-5 text-white" /></span>
                    Nueva Venta (Producci├│n)
                </h2>
                {onCancel && (
                    <button onClick={onCancel} className="text-slate-500 hover:text-white">
                        <X className="w-6 h-6" />
                    </button>
                )}
            </div>

            {error && (
                <div className="mb-4 p-3 bg-red-900/50 border border-red-500 text-red-200 rounded text-sm">
                    Error: {error}
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-6">
                {/* Header Data */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-900/50 p-4 rounded-lg">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Cliente</label>
                        <div className="relative">
                            <User className="absolute left-3 top-2.5 w-4 h-4 text-slate-600" />
                            <select
                                value={formData.customer_id}
                                onChange={(e) => handleCustomerChange(Number(e.target.value))}
                                className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded text-white focus:border-blue-500 outline-none"
                            >
                                <option value="">Seleccionar Cliente...</option>
                                {customers.map(c => (
                                    <option key={c.id} value={c.id}>{c.business_name || c.name}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Jurisdicci├│n Fiscal (Condado)</label>
                        <div className="relative">
                            <MapPin className="absolute left-3 top-2.5 w-4 h-4 text-slate-600" />
                            <select
                                value={formData.county}
                                onChange={(e) => setFormData(prev => ({ ...prev, county: e.target.value }))}
                                className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded text-white focus:border-blue-500 outline-none"
                            >
                                {FLORIDA_COUNTIES.map(c => (
                                    <option key={c} value={c}>{c}</option>
                                ))}
                            </select>
                        </div>
                        <p className="text-xs text-slate-600 mt-1">Determines Surtax Rate (e.g., Miami-Dade 1%)</p>
                    </div>
                </div>

                {/* Lines */}
                <div>
                    <div className="flex justify-between items-center mb-2">
                        <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Art├¡culos</label>
                        <button type="button" onClick={addItem} className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1">
                            <Plus className="w-3 h-3" /> Agregar L├¡nea
                        </button>
                    </div>
                    <div className="space-y-2">
                        {items.map((item, index) => (
                            <div key={index} className="grid grid-cols-12 gap-2 items-start bg-slate-900 p-2 rounded border border-white/5">
                                <div className="col-span-4">
                                    <select
