        const sizeUncompressed = rawBytes.length;

        // 2. Compress
        const compressedBytes = BackupCompressor.compress(rawBytes);

        // 3. Encrypt
        const password = options.password || 'default-system-key'; // Should be from Vault
        // BasicEncryption.encrypt returns {encrypted, salt, iv}
        const { encrypted, salt, iv } = await BasicEncryption.encrypt(compressedBytes, password);
        const combinedEncrypted = BasicEncryption.combineEncryptedData(encrypted, salt, iv);

        // 4. Calculate Checksum
        const checksum = await BasicEncryption.hash(combinedEncrypted);

        // 5. Get Last Audit Hash
        // Assuming AuditChain has getLastHash exposed or we query it. 
        // We already have audit_chain table in dump, but for metadata we want the latest.
        const lastAudit = await this.engine.select('SELECT current_hash FROM audit_chain ORDER BY id DESC LIMIT 1');
        const auditHash = (lastAudit[0] as any)?.current_hash || 'GENESIS';

        // 6. Build Metadata
        const metadata = {
            version: '1.0.0',
            createdAt: new Date().toISOString(),
            checksum,
            auditHash,
            tablesIncluded: tablesToBackup,
            sizeUncompressed,
            sizeCompressed: combinedEncrypted.length,
            description: options.description || 'Auto-generated backup',
            isEncrypted: true
        };

        // 7. Validate Metadata
        const validMetadata = BackupMetadataSchema.parse(metadata);

        // 8. Register in DB (Audit & Backup table)
        await this.auditChain.addEvent('backup_created', { checksum, size: validMetadata.sizeCompressed });

        // Insert into backup_versions
        await this.engine.run(`
        INSERT INTO backup_versions (version, created_at, checksum, audit_hash, size_bytes, description)
        VALUES (?, ?, ?, ?, ?, ?)
    `, [validMetadata.version, validMetadata.createdAt, checksum, auditHash, validMetadata.sizeCompressed, validMetadata.description]);

        // @ts-ignore
        return {
            metadata: validMetadata,
            data: combinedEncrypted
        } as any;
    }

    async restoreBackup(backupFile: Uint8Array, password: string): Promise<boolean> {
        // 1. Verify Checksum
        const calculatedChecksum = await BasicEncryption.hash(backupFile);
        // In a real file scenario, we would parse container first to get metadata.
        // Here we assume backupFile IS the data blob for simplicity of the method signature 
        // or we changed signature to accept container. 
        // Let's assume the blob passed IS the encrypted data we returned in createBackup.data

        // 2. Decrypt
        const { salt, iv, encrypted } = BasicEncryption.separateEncryptedData(backupFile);
        const compressedBytes = await BasicEncryption.decrypt(encrypted, salt, iv, password);

        // 3. Decompress
        const jsonString = BackupCompressor.decompress(compressedBytes);
        const dbDump = JSON.parse(jsonString) as Record<string, any[]>;

        // 4. Import Atomic Transaction
        await this.engine.executeTransaction(async () => {
            for (const [table, rows] of Object.entries(dbDump)) {
                if (rows.length === 0) continue;

                // Clear table first? Strategy: Full Restore usually creates clean state.
                // WARNING: Destructive.
                // Assuming 'DELETE FROM table'
                try {
                    await (this.engine as any).exec(`DELETE FROM ${table}`);

                    if (rows.length > 0) {
                        const keys = Object.keys(rows[0]);
                        const placeholders = keys.map(() => '?').join(',');
                        const columns = keys.join(',');
                        const stmt = `INSERT INTO ${table} (${columns}) VALUES (${placeholders})`; // Not prepared correctly for engine.run loop but close enough for concept

                        // Optimized batch insert if engine supported it, else loop
                        for (const row of rows) {
                            await this.engine.run(`INSERT INTO ${table} (${columns}) VALUES (${placeholders})`, Object.values(row));
                        }
                    }
                } catch (e) {
                    console.error(`Error restoring table ${table}`, e);
                    throw e; // Trigger Rollback
                }
            }
        });

        // 5. Audit
        await this.auditChain.addEvent('backup_restored', { checksum: calculatedChecksum });

        return true;
    }
}

import { z } from 'zod';
import { FloridaTaxConfigModel } from '@/database/models/FloridaTaxConfig';
import {
    TaxCalculationResultSchema,
    type TaxCalculationResult,
    type FloridaTaxRate
} from './TaxCalculation.types';

// Esquema de entrada para el c├ílculo
const CalculationInputSchema = z.object({
    subtotal: z.number().nonnegative("El subtotal no puede ser negativo"),
    county: z.string().min(1, "El condado es requerido"),
    date: z.date().default(() => new Date())
}).strict();

export class FloridaTaxCalculator {

    /**
     * Calcula el impuesto para un subtotal dado y un condado.
     * Utiliza la configuraci├│n est├ítica de FloridaTaxConfigModel por ahora.
     * 
     * @param subtotal Monto sobre el cual calcular el impuesto
     * @param county Condado de Florida
     * @param date Fecha de la transacci├│n (para vigencia de tasas)
     * @returns Resultado del c├ílculo validado por Zod
     */
    public calculate(subtotal: number, county: string, date: Date = new Date()): TaxCalculationResult {
        // 1. Validar entradas
        const input = CalculationInputSchema.parse({ subtotal, county, date });

        // 2. Obtener configuraci├│n de tasa
        // TODO: En el futuro, esto consultar├í un repositorio con soporte de fechas (effective_from)
        const taxConfig = FloridaTaxConfigModel.getTaxByCounty(input.county);

        if (!taxConfig) {
            throw new Error(`Configuraci├│n de impuestos no encontrada para el condado: ${input.county}`);
        }

        // 3. Validar vigencia (Simulado con la fecha de la config est├ítica si fuera necesario, 
        // pero por ahora asumimos que la config est├ítica es la vigente)
        // En una implementaci├│n completa verificar├¡amos input.date vs taxConfig.effective_date

        // 4. Realizar c├ílculos matem├íticos
        // Usamos aritm├⌐tica simple pero cuidadosa con el redondeo
        const rawTaxAmount = input.subtotal * taxConfig.total_rate;

        // Redondeo est├índar bancario/comercial (Half Up) a 2 decimales
        const taxAmount = Math.round((rawTaxAmount + Number.EPSILON) * 100) / 100;
        const total = Math.round((input.subtotal + taxAmount + Number.EPSILON) * 100) / 100;

        // 5. Construir resultado
        const result = {
            subtotal: input.subtotal,
            county: taxConfig.county,
            appliedRate: taxConfig.total_rate,
            taxAmount: taxAmount,
            total: total,
            calculatedAt: new Date(),
            isDr15Required: taxConfig.dr15_required && taxAmount > 0 // Simplificaci├│n de regla
        };

        // 6. Validar salida con Zod y retornar
        return TaxCalculationResultSchema.parse(result);
    }

    /**
     * M├⌐todo auxiliar para obtener la tasa pura, ├║til para UI o pre-c├ílculos
     */
    public getRateForCounty(county: string): number {
        const config = FloridaTaxConfigModel.getTaxByCounty(county);
        if (!config) {
            throw new Error(`Condado inv├ílido: ${county}`);
        }
        return config.total_rate;
    }
}

import { z } from 'zod';
import { FloridaTaxCalculator } from './FloridaTaxCalculator';

// Documentaci├│n DOR Florida: Regla 12A-1.097
// Requisitos de facturaci├│n para Sales and Use Tax

export const ComplianceInvoiceItemSchema = z.object({
    description: z.string().min(1, "Item description is required"),
    quantity: z.number().positive("Quantity must be positive"),
    unitPrice: z.number().nonnegative("Unit price must be non-negative"),
    taxable: z.boolean(),
    lineTotal: z.number()
}).strict();

export const ComplianceInvoiceSchema = z.object({
    invoiceNumber: z.string().min(1, "Invoice number is required"),
    date: z.date(),
    customer: z.object({
        name: z.string().min(1, "Customer name is required"),
        county: z.string().min(1, "Florida county is required for surtax calculation"),
        taxExemptNumber: z.string().optional()
    }),
    items: z.array(ComplianceInvoiceItemSchema).min(1, "Invoice must have at least one item"),
    subtotal: z.number(),
    taxAmount: z.number().min(0),
    totalAmount: z.number(),
    countyRate: z.number().min(0).max(0.15).optional() // Optional sanity check for rate
}).strict();

export interface ValidationResult {
    isValid: boolean;
    errors: string[];
    warnings: string[];
}

export class InvoiceComplianceValidator {
    private taxCalculator: FloridaTaxCalculator;

    constructor() {
        this.taxCalculator = new FloridaTaxCalculator();
    }

    /**
     * Valida una factura para asegurar cumplimiento con normas de Florida DOR.
     * @param invoice Datos de la factura
     */
    public validate(invoice: unknown): ValidationResult {
        const result: ValidationResult = {
            isValid: true,
            errors: [] as string[],
            warnings: [] as string[]
        };

        // 1. Validaci├│n de Estructura (Schema)
        const parseResult = ComplianceInvoiceSchema.safeParse(invoice);
        if (!parseResult.success) {
            result.isValid = false;
            result.errors.push(...parseResult.error.issues.map(e => `${e.path.join('.')}: ${e.message}`));
            return result; // Si la estructura est├í mal, no seguimos con l├│gica
        }

        const data = parseResult.data;

        // 2. Validaci├│n L├│gica de Negocio (Florida Tax Rule)

        // Verificar Subtotal
        const calculatedSubtotal = data.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
        if (Math.abs(calculatedSubtotal - data.subtotal) > 0.01) {
            result.isValid = false;
            result.errors.push(`Subtotal mismatch: declared ${data.subtotal}, calculated ${calculatedSubtotal}`);
        }

        // Verificar Math de Tax (Aproximado)
        // Para validaci├│n exacta, necesitar├¡amos recalcular con el tax calculator
        // Vamos a asumir que si el items es taxable, aplica tax.

        let calculatedTaxBase = 0;
        data.items.forEach(item => {
            if (item.taxable) {
                calculatedTaxBase += item.quantity * item.unitPrice;
            }
        });

        // Si el cliente es exento, tax debe ser 0
        if (data.customer.taxExemptNumber) {
            if (data.taxAmount > 0) {
                result.errors.push(`Tax Exempt customer has tax amount > 0`);
                result.isValid = false;
            }
        } else {
            // Validar que el impuesto no est├⌐ groseramente mal (e.g. negativo o > 20%)
            if (data.taxAmount < 0) {
                result.errors.push("Tax amount cannot be negative");
                result.isValid = false;
            }
        }

        // Verificar Total
        if (Math.abs((data.subtotal + data.taxAmount) - data.totalAmount) > 0.01) {
            result.isValid = false;
            result.errors.push(`Total amount mismatch: declared ${data.totalAmount}, calculated ${data.subtotal + data.taxAmount}`);
        }

        // 3. Validar Condado (Florida Specific)
        const validCounties = [
            "Miami-Dade", "Broward", "Palm Beach", "Orange", "Hillsborough", "Duval", "Pinellas",
            "Lee", "Polk", "Brevard", "Volusia", "Pasco", "Seminole", "Sarasota", "Manatee",
            "Collier", "Osceola", "Marion", "St. Lucie", "Escambia", "Leon", "Alachua", "St. Johns",
            "Clay", "Okaloosa", "Lake", "Hernando", "Charlotte", "Santa Rosa", "Martin", "Bay",
            "Indian River", "Citrus", "Sumter", "Flagler", "Highlands", "Nassau", "Monroe", "Putnam",
            "Columbia", "Walton", "Jackson", "Gadsden", "Suwannee", "Levy", "Okeechobee", "Hendry",
            "DeSoto", "Wakulla", "Hardee", "Baker", "Washington", "Taylor", "Holmes", "Madison",
            "Gilchrist", "Dixie", "Gulf", "Union", "Calhoun", "Hamilton", "Jefferson", "Glades",
            "Franklin", "Lafayette", "Liberty"
        ];

        // Normalizaci├│n simple para check
        const normalizedCounty = validCounties.find(c => c.toLowerCase() === data.customer.county.toLowerCase());
        if (!normalizedCounty) {
            result.warnings.push(`County '${data.customer.county}' not recognized in standard Florida list. Surtax calculation might be inaccurate.`);
        }

        return result;
    }
}

import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { type SystemConfig, type UserRole, type FiscalSettings } from './System.types';

export class SystemService {
    private engine: SQLiteEngine;

    constructor(engine: SQLiteEngine) {
        this.engine = engine;
    }

    // --- Config ---
    async setConfig(key: string, value: string, category: string = 'general'): Promise<void> {
        await (this.engine as any).run(`
            INSERT INTO system_config (key, value, category) VALUES (?, ?, ?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=CURRENT_TIMESTAMP
        `, [key, value, category]);
    }

    async getConfig(key: string): Promise<string | null> {
        const row = await this.engine.select('SELECT value FROM system_config WHERE key = ?', [key]);
        return row.length > 0 ? row[0].value : null;
    }

    // --- Roles ---
    async createRole(role: UserRole): Promise<number> {
        const permsJson = JSON.stringify(role.permissions);
        const res = await (this.engine as any).run(`
            INSERT INTO user_roles (name, description, permissions) VALUES (?, ?, ?)
        `, [role.name, role.description, permsJson]);
        return res.lastID;
    }

    async getRoles(): Promise<UserRole[]> {
        const rows = await this.engine.select('SELECT * FROM user_roles');
        return rows.map((r: any) => ({
            ...r,
            permissions: JSON.parse(r.permissions || '[]')
        }));
    }

    // --- Fiscal ---
    async getFiscalSettings(): Promise<FiscalSettings | null> {
        const rows = await this.engine.select('SELECT * FROM fiscal_settings ORDER BY id DESC LIMIT 1');
        if (rows.length === 0) return null;
        return {
            ...(rows[0] as any),
            active: Boolean(rows[0].active)
        } as FiscalSettings;
    }

    async updateFiscalSettings(settings: FiscalSettings): Promise<void> {
        // Simple singleton strategy: Insert new row for history, or update latest.
        // Let's update if exists.
        const current = await this.getFiscalSettings();
        if (current && current.id) {
            await (this.engine as any).run(`
                UPDATE fiscal_settings 
                SET tax_year_start=?, tax_frequency=?, sales_tax_method=?, default_tax_rate=?, dr15_filing_day=?, active=?
                WHERE id=?
            `, [settings.tax_year_start, settings.tax_frequency, settings.sales_tax_method, settings.default_tax_rate, settings.dr15_filing_day, settings.active, current.id]);
        } else {
            await (this.engine as any).run(`
                INSERT INTO fiscal_settings (tax_year_start, tax_frequency, sales_tax_method, default_tax_rate, dr15_filing_day, active)
                VALUES (?, ?, ?, ?, ?, ?)
            `, [settings.tax_year_start, settings.tax_frequency, settings.sales_tax_method, settings.default_tax_rate, settings.dr15_filing_day, settings.active]);
        }
    }
}

export class FloridaTaxCalculator {
    // Tasas por condado (Hardcoded por seguridad, pero idealmente vendr├¡an de DB)
    private static COUNTY_RATES: Record<string, number> = {
        'Miami-Dade': 0.01,
        'Broward': 0.01,
        'Palm Beach': 0.01,
        'Orange': 0.005,
        'Hillsborough': 0.015,
        'Duval': 0.015,
        'Pinellas': 0.01
    };

    private static FLORIDA_STATE_RATE = 0.06;

    /**
     * Calcula el impuesto completo para una transacci├│n
     */
    static calculateTax(amount: number, county: string, date: Date = new Date()): {
        stateTax: number;
        countyTax: number;
        totalTax: number;
        effectiveRate: number;
    } {
        // Validar condado
        const countyRate = this.COUNTY_RATES[county] || 0.00; // Default a 0 si no se encuentra (safe fallback)

        // Calcular componentes
        const stateTax = Number((amount * this.FLORIDA_STATE_RATE).toFixed(2));

        // El surtax del condado aplica solo a los primeros $5000 de una compra de propiedad tangible personal
        // Pero para simplificaci├│n en este MVP asumiremos regla general plana
        const countyTax = Number((amount * countyRate).toFixed(2));

        const totalTax = Number((stateTax + countyTax).toFixed(2));
        const effectiveRate = this.FLORIDA_STATE_RATE + countyRate;

        return {
            stateTax,
            countyTax,
            totalTax,
            effectiveRate
        };
    }

    /**
     * Valida si la tasa aplicada es correcta
     */
    static validateCompliance(amount: number, taxCharged: number, county: string): boolean {
        const calculated = this.calculateTax(amount, county);
        // Permitir peque├▒a diferencia por redondeo ($0.01)
        return Math.abs(calculated.totalTax - taxCharged) <= 0.01;
    }
}

import { db } from '@/database/simple-db';
import { logger } from '../utils/logger';
import { BackupService } from '../services/backup/BackupService';

export class IntegrityMonitor {
    private static timeoutId: any = null;
    private static readonly CHECK_INTERVAL = 300000; // 5 minutos (antes 60s)

    /**
     * Inicia el monitoreo continuo de integridad del sistema.
     */
    static startContinuousMonitoring(): void {
        if (this.timeoutId) return;

        logger.info('Monitor de Integridad 24/7 activado (Fondo).', undefined, 'Monitor', 'startup');

        const scheduleNextCheck = () => {
            this.timeoutId = setTimeout(() => {
                if (typeof window !== 'undefined' && 'requestIdleCallback' in window) {
                    (window as any).requestIdleCallback(async () => {
                        await this.performPulseCheck();
                        scheduleNextCheck();
                    }, { timeout: 5000 });
                } else {
                    // Fallback para entornos sin requestIdleCallback
                    this.performPulseCheck().then(scheduleNextCheck);
                }
            }, this.CHECK_INTERVAL);
        };

        // Ejecutar chequeo inicial de forma no bloqueante
        if (typeof window !== 'undefined' && 'requestIdleCallback' in window) {
            (window as any).requestIdleCallback(() => this.performPulseCheck());
        } else {
            this.performPulseCheck();
        }

        scheduleNextCheck();
    }

    /**
     * Detiene el monitoreo.
     */
    static stopMonitoring(): void {
        if (this.timeoutId) {
            clearTimeout(this.timeoutId);
            this.timeoutId = null;
            logger.warn('Monitor de Integridad detenido manualmente.', undefined, 'Monitor', 'shutdown');
        }
    }

    /**
     * Ejecuta un chequeo de pulso en todos los subsistemas cr├¡ticos.
     */
    private static async performPulseCheck(): Promise<void> {
        try {
            // 1. Salud de la Base de Datos (Integridad y FK)
            const dbStatus = await BackupService.runIntegrityTestSuite(db);

            if (!dbStatus.passed) {
                logger.emergency('FALLA DE INTEGRIDAD DETECTADA POR MONITOR CONTINUO', { failures: dbStatus.failures }, undefined, 'Monitor', 'integrity_failure');
                // Aqu├¡ se podr├¡a disparar una reparaci├│n autom├ítica si estuviera configurada
            }

            // 2. Monitoreo de Alertas de IA
            // En un sistema real, aqu├¡ auditar├¡amos las ├║ltimas respuestas de la IA 
            // buscando patrones de 'documentaci├│n' prohibidos.

            // 3. Verificaci├│n de Almacenamiento
            this.checkLocalPersistence();

            if (dbStatus.passed) {
                logger.debug('Pulso de integridad estable.', undefined, 'Monitor', 'pulse');
            }

        } catch (error: any) {
            logger.error('Error durante el ciclo de monitoreo', { error: error.message }, error, 'Monitor', 'cycle_error');
        }
    }

    private static checkLocalPersistence(): void {
        const nav = navigator as any;
        if (typeof nav !== 'undefined' && nav.storage && nav.storage.estimate) {
            nav.storage.estimate().then((estimate: any) => {
                const usagePercent = ((estimate.usage || 0) / (estimate.quota || 1)) * 100;
                if (usagePercent > 90) {
                    logger.warn('Espacio de almacenamiento cr├¡tico (>90%)', { usagePercent }, 'Monitor', 'storage_low');
                }
            });
        }
    }
}

import React, { useEffect, useState } from 'react';
import { getDBEngine } from '@/database/simple-db';

interface QueryResult {
    query: string;
    label: string;
    columns: string[];
    rows: any[][];
    error?: string;
    duration: number;
}

const VERIFICATION_QUERIES = [
    {
        label: 'PASO 1 ΓÇö import_hash en bank_transactions',
        query: `SELECT 
      COUNT(*) as total, 
      COUNT(import_hash) as con_hash, 
      COUNT(*) - COUNT(import_hash) as sin_hash 
    FROM bank_transactions`
    },
    {
        label: 'PASO 2 ΓÇö Deduplicaci├│n (duplicados detectados)',
        query: `SELECT 
      import_hash, 
      COUNT(*) as repeticiones 
    FROM bank_transactions 
    WHERE import_hash IS NOT NULL 
    GROUP BY import_hash 
    HAVING COUNT(*) > 1`
    },
    {
        label: 'PASO 3 ΓÇö Estado de transacciones',
        query: `SELECT 
      current_state, 
      auto_classified, 
      COUNT(*) as cantidad 
    FROM transaction_states 
    GROUP BY current_state, auto_classified`
    },
    {
        label: 'DIAGN├ôSTICO ΓÇö Tablas en la base de datos',
        query: `SELECT name FROM sqlite_master WHERE type='table' ORDER BY name`
    },
    {
        label: 'DIAGN├ôSTICO ΓÇö bank_transactions (primeras 10)',
        query: `SELECT id, transaction_date, description, amount, import_hash FROM bank_transactions LIMIT 10`
    }
];

export const DiagnosticSQL: React.FC = () => {
    const [results, setResults] = useState<QueryResult[]>([]);
    const [loading, setLoading] = useState(true);
    const [status, setStatus] = useState('Inicializando...');

    useEffect(() => {
        const runQueries = async () => {
            setStatus('Obteniendo engine de base de datos...');

            // Wait for DB engine to be ready
            let engine;
            for (let i = 0; i < 10; i++) {
                try {
                    engine = getDBEngine();
                    break;
                } catch (e) {
                    setStatus(`Esperando DB (intento ${i + 1}/10)...`);
                    await new Promise(r => setTimeout(r, 1000));
                }
            }

            if (!engine) {
                setStatus('ERROR: No se pudo obtener el engine de base de datos');
                setLoading(false);
                return;
            }

            setStatus('Engine disponible. Ejecutando queries...');
            const queryResults: QueryResult[] = [];

            for (const q of VERIFICATION_QUERIES) {
                const start = Date.now();
                try {
                    const rows = await engine.select(q.query);
                    const duration = Date.now() - start;
                    const columns = rows.length > 0 ? Object.keys(rows[0]) : [];
                    const rowData = rows.map(r => columns.map(c => r[c]));
                    queryResults.push({ query: q.query, label: q.label, columns, rows: rowData, duration });
                } catch (e: any) {
                    const duration = Date.now() - start;
                    queryResults.push({ query: q.query, label: q.label, columns: [], rows: [], error: String(e), duration });
                }
            }

            setResults(queryResults);
            setLoading(false);
            setStatus('Γ£à Todas las queries ejecutadas');
        };

        // Small delay to let the DB initialize
        setTimeout(runQueries, 2000);
    }, []);

    return (
        <div style={{ fontFamily: 'monospace', background: '#0a0a0a', color: '#e2e8f0', minHeight: '100vh', padding: '24px' }}>
            <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
                <h1 style={{ color: '#60a5fa', fontSize: '20px', fontWeight: 'bold', marginBottom: '8px' }}>
                    ≡ƒö¼ VERIFICACI├ôN SQL ΓÇö M├ôDULO BANCARIO
                </h1>
                <p style={{ color: '#64748b', fontSize: '12px', marginBottom: '24px' }}>{status}</p>

                {loading && (
                    <div style={{ color: '#fbbf24', padding: '16px', border: '1px solid #d97706', borderRadius: '8px', marginBottom: '16px' }}>
                        ΓÅ│ Ejecutando queries... Por favor espera.
                    </div>
                )}

                {results.map((result, i) => (
                    <div key={i} style={{ marginBottom: '32px', border: '1px solid #1e293b', borderRadius: '8px', overflow: 'hidden' }}>
                        {/* Header */}
                        <div style={{ background: '#1e293b', padding: '12px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ color: '#a78bfa', fontWeight: 'bold', fontSize: '13px' }}>{result.label}</span>
                            <span style={{ color: '#64748b', fontSize: '11px' }}>{result.duration}ms</span>
                        </div>

                        {/* Query */}
                        <div style={{ background: '#0f172a', padding: '12px 16px', borderBottom: '1px solid #1e293b' }}>
                            <pre style={{ color: '#94a3b8', fontSize: '11px', margin: 0, whiteSpace: 'pre-wrap' }}>{result.query.trim()}</pre>
                        </div>

                        {/* Error */}
                        {result.error && (
                            <div style={{ background: '#450a0a', padding: '12px 16px', color: '#f87171' }}>
                                Γ¥î ERROR: {result.error}
                            </div>
                        )}

                        {/* Results Table */}
                        {!result.error && (
                            <div style={{ padding: '16px' }}>
                                {result.rows.length === 0 ? (
                                    <div style={{ color: '#22c55e', fontSize: '13px' }}>
                                        Γ£à 0 filas devueltas (tabla vac├¡a o sin duplicados)
                                    </div>
                                ) : (
                                    <div>
                                        <div style={{ color: '#64748b', fontSize: '11px', marginBottom: '8px' }}>{result.rows.length} fila(s)</div>
                                        <table style={{ borderCollapse: 'collapse', width: '100%', fontSize: '12px' }}>
                                            <thead>
                                                <tr>
                                                    {result.columns.map((col, ci) => (
                                                        <th key={ci} style={{ padding: '8px 12px', textAlign: 'left', background: '#1e293b', color: '#94a3b8', fontWeight: 'bold', borderBottom: '1px solid #334155' }}>
                                                            {col}
                                                        </th>
                                                    ))}
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {result.rows.map((row, ri) => (
                                                    <tr key={ri} style={{ borderBottom: '1px solid #1e293b' }}>
                                                        {row.map((cell, ci) => (
                                                            <td key={ci} style={{ padding: '8px 12px', color: '#e2e8f0', fontFamily: 'monospace' }}>
                                                                {cell === null ? <span style={{ color: '#475569' }}>NULL</span> : String(cell)}
                                                            </td>
                                                        ))}
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                                {/* Raw JSON */}
                                <details style={{ marginTop: '12px' }}>
                                    <summary style={{ color: '#64748b', fontSize: '11px', cursor: 'pointer' }}>Ver JSON raw</summary>
                                    <pre style={{ color: '#475569', fontSize: '10px', marginTop: '8px', background: '#0f172a', padding: '12px', borderRadius: '4px', overflow: 'auto' }}>
                                        {JSON.stringify({ columns: result.columns, rows: result.rows }, null, 2)}
                                    </pre>
                                </details>
                            </div>
                        )}
                    </div>
                ))}
            </div>
        </div>
    );
};

/**
 * P├ígina de Health Check
 * Endpoint p├║blico para verificar el estado del sistema
 * Accesible en /health
 */

import React, { useEffect, useState } from 'react';
import { getHealthStatus, HealthCheckResponse } from '../api/health';
import { Activity, CheckCircle, XCircle, AlertTriangle } from 'lucide-react';
import { useLocale } from '../i18n/useLocale';

export const HealthCheckPage: React.FC = () => {
    const { t } = useLocale();
    const [health, setHealth] = useState<HealthCheckResponse | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        loadHealth();
    }, []);

    const loadHealth = async () => {
        setLoading(true);
        setError(null);
        try {
            const result = await getHealthStatus();
            setHealth(result);
        } catch (err) {
            setError((err as Error).message);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <div className="text-center">
                    <Activity className="w-12 h-12 text-blue-600 animate-pulse mx-auto mb-4" />
                    <p className="text-gray-600">{t('systemStatus.verifying')}</p>
                </div>
