                            {t('common.refresh')}
                        </button>
                    </div>
                </div>

                {/* Summary */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                    <div className="bg-white rounded-lg p-4 shadow">
                        <p className="text-sm text-gray-600">{t('systemStatus.totalChecksLabel')}</p>
