                        <div className="px-6 py-4 bg-gray-50 border-t border-gray-200">
                            <pre className="text-xs overflow-x-auto">
                                {JSON.stringify(health, null, 2)}
                            </pre>
                        </div>
                    </details>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Activity, Shield } from 'lucide-react';
import { DatabaseService } from '../database/DatabaseService';
import { TaxService } from '../services/TaxService';
import { BackupService } from '../services/backup/BackupService';
import { AuditChainService as ForensicAuditService } from '../core/audit/AuditChainService';
import { ForensicSentinelDashboard } from '../components/forensic/ForensicSentinelDashboard';

export const LiveVerification: React.FC = () => {
    const [results, setResults] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);

    const addResult = (label: string, value: any, status: 'pass' | 'fail' | 'info') => {
        setResults(prev => [...prev, { label, value: typeof value === 'string' ? value : JSON.stringify(value), status }]);
    };

    const runVerification = async () => {
        setLoading(true);
        setResults([]); // Clear previous

        // DELAY to ensure DB ready
        await new Promise(r => setTimeout(r, 1000));

        // 1. County Count
        try {
            const res = await DatabaseService.executeQuery("SELECT COUNT(*) as c FROM florida_tax_rates");
            const count = res[0]?.c;
            addResult("1. Florida Counties Count", `${count} (Expected: 67)`, count === 67 ? 'pass' : 'fail');
        } catch (e: any) {
            addResult("County Check Failed", e.message, 'fail');
        }

        // 2. Tax Calculation
        try {
            const tax = await TaxService.calculateFloridaSalesTax(10000, 'MIAMI-DADE', new Date().toISOString());
            addResult("2. Tax Calculation (Miami-Dade $100)", `${tax.taxAmount} cents (Expected: 700)`, tax.taxAmount === 700 ? 'pass' : 'fail');
        } catch (e: any) {
            addResult("Tax Calc Failed", e.message, 'fail');
        }

        // 3. Tax Transactions Check & Seed
        try {
            const res = await DatabaseService.executeQuery("SELECT COUNT(*) as c FROM tax_transactions");
            let count = res[0]?.c;
            addResult("3a. Tax Transactions Initial Count", count, count > 0 ? 'pass' : 'info');

            if (count === 0) {
                // Inject dummy
                try {
                    const tax = await TaxService.calculateFloridaSalesTax(10000, 'ORANGE', new Date().toISOString());
                    await TaxService.recordTaxTransaction({
                        invoiceId: 99999,
                        countyCode: 'ORANGE',
                        taxableAmount: 10000,
                        taxAmount: tax.taxAmount,
                        effectiveRate: tax.totalRate,
                        transactionDate: new Date().toISOString(),
                        verificationHash: tax.verificationHash
                    });
                    addResult("3b. Data Injection", "Injected 1 Test Transaction for Dashboard", 'pass');

                    // Re-check
                    const res2 = await DatabaseService.executeQuery("SELECT COUNT(*) as c FROM tax_transactions");
                    count = res2[0]?.c;
                    addResult("3c. Tax Transactions Count (After Inject)", count, count > 0 ? 'pass' : 'fail');

                } catch (e: any) {
                    addResult("Injection Failed", e.message, 'fail');
                }
            }
        } catch (e: any) {
            addResult("Tax Transaction Check Failed", e.message, 'fail');
        }

        // 4. Backup Service
        try {
            // Mock DB export if running in node? No, we are in browser.
            const backupJson = await BackupService.createBackup();
            const parsed = JSON.parse(backupJson);
            const valid = parsed.version === '1.0' && parsed.database && parsed.checksum;
            addResult("4. Backup Generation", `Size: ${backupJson.length} chars. Valid Format: ${valid}`, valid ? 'pass' : 'fail');
        } catch (e: any) {
            addResult("Backup Failed", e.message, 'fail');
        }

        // 5. Migration Check (Task 5.1 & 5.2 Fix)
        try {
            const res = await DatabaseService.executeQuery("SELECT MAX(version) as v FROM sys_migrations");
            const v = res[0]?.v;
            addResult("5. Migration Status", `Current Version: ${v} (Expected: >=7)`, v >= 7 ? 'pass' : 'fail');
        } catch (e: any) {
            addResult("Migration Check Failed", "sys_migrations table missing or empty? " + e.message, 'fail');
        }

        // 6. Fiscal Tables Existence (Task 2.1)
        try {
            const resA = await DatabaseService.executeQuery("SELECT name FROM sqlite_master WHERE type='table' AND name IN ('fixed_assets', 'asset_depreciation')");
            const found = resA.map((r: any) => r.name).join(', ');
            const pass = resA.length === 2;
            addResult("6. Fiscal Tables", `Found: ${found} (Expected: fixed_assets, asset_depreciation)`, pass ? 'pass' : 'fail');
        } catch (e: any) {
            addResult("Table Check Failed", e.message, 'fail');
        }

        // 7. Forensic Deep Scan (Task 6.1)
        try {
            const audit = await ForensicAuditService.performFullAudit();
            addResult("7. Forensic Deep Scan", audit.valid ? "Chain, Content & Seal Verified" : `FAILED: ${audit.errorType} - ${audit.details}`, audit.valid ? 'pass' : 'fail');
        } catch (e: any) {
            addResult("Forensic Audit Crashed", e.message, 'fail');
        }

        setLoading(false);
    };

    useEffect(() => {
        // Run once on mount
        runVerification();
    }, []);

    return (
        <div className="p-10 bg-slate-900 text-white min-h-screen font-sans">
            <div className="max-w-3xl mx-auto">
                <h1 className="text-3xl font-black mb-2 text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-emerald-400">
                    IRON CORE VERIFICATION
                </h1>
                <div className="mb-10">
                    <h2 className="text-xl font-black mb-4 text-blue-400 flex items-center gap-2 tracking-tighter uppercase">
                        <Activity className="w-5 h-5" />
                        NASA FORENSIC SENTINEL TELEMETRY
                    </h2>
                    <ForensicSentinelDashboard />
                </div>

                <h2 className="text-xl font-black mb-4 text-slate-400 flex items-center gap-2 tracking-tighter uppercase">
                    <Shield className="w-5 h-5" />
                    SIMPLE SYSTEM DIAGNOSTICS
                </h2>

                <div className="space-y-4">
                    {results.map((r, i) => (
                        <div key={i} className={`p-4 rounded-xl border-l-4 flex justify-between items-center bg-slate-800/50 backdrop-blur-sm ${r.status === 'pass' ? 'border-emerald-500' :
                            r.status === 'fail' ? 'border-rose-500' : 'border-blue-500'
                            }`}>
                            <div>
                                <div className={`text-sm font-black uppercase tracking-[0.15em] mb-1 ${r.status === 'pass' ? 'text-emerald-400' :
                                    r.status === 'fail' ? 'text-rose-400' : 'text-blue-400'
                                    }`}>
                                    {r.label}
                                </div>
                                <div className="font-mono text-slate-200 text-sm">{r.value}</div>
                            </div>

                            <div className={`px-3 py-1 rounded text-xs font-black uppercase ${r.status === 'pass' ? 'bg-emerald-500/20 text-emerald-400' :
                                r.status === 'fail' ? 'bg-rose-500/20 text-rose-400' : 'bg-blue-500/20 text-blue-400'
                                }`}>
                                {r.status.toUpperCase()}
                            </div>
                        </div>
                    ))}
                </div>

                <button
                    onClick={runVerification}
                    disabled={loading}
                    className="mt-8 px-6 py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-black tracking-tighter uppercase transition-all w-full border border-slate-600 text-white"
                >
                    {loading ? 'Processing...' : 'Rerun Verification'}
                </button>
            </div>
        </div>
    );
};

/**
 * Dashboard de Estado del Sistema (Admin)
 * Vista completa del estado del sistema con m├⌐tricas y controles
 * Nivel NASA: Monitoreo en tiempo real para administradores
 */

import React, { useEffect, useState } from 'react';
import { getHealthStatus, HealthCheckResponse } from '../api/health';
import { IntegrityService } from '../services/integrity/IntegrityService';
import { useLocale } from '../i18n/useLocale';
import {
    Activity,
    CheckCircle,
    XCircle,
    AlertTriangle,
    RefreshCw,
    Wrench,
    Shield,
    Clock,
    TrendingUp,
    Database
} from 'lucide-react';

export const SystemStatusDashboard: React.FC = () => {
    const { t } = useLocale();
    const [health, setHealth] = useState<HealthCheckResponse | null>(null);
    const [loading, setLoading] = useState(true);
    const [repairing, setRepairing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
    const [autoRefresh, setAutoRefresh] = useState(false);

    useEffect(() => {
        loadHealth();
    }, []);

    useEffect(() => {
        if (!autoRefresh) return;

        const interval = setInterval(() => {
            loadHealth();
        }, 30000); // Actualizar cada 30 segundos

        return () => clearInterval(interval);
    }, [autoRefresh]);

    const loadHealth = async () => {
        setLoading(true);
        setError(null);
        try {
            const result = await getHealthStatus();
            setHealth(result);
            setLastUpdate(new Date());
        } catch (err) {
            setError((err as Error).message);
        } finally {
            setLoading(false);
        }
    };

    const handleRepairAll = async () => {
        setRepairing(true);
        try {
            const service = new IntegrityService();
            await service.repairAll();
            await loadHealth();
        } catch (err) {
            setError(`Error reparando: ${(err as Error).message}`);
        } finally {
            setRepairing(false);
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'healthy': return 'bg-green-500';
            case 'degraded': return 'bg-yellow-500';
            case 'critical': return 'bg-red-500';
            default: return 'bg-gray-500';
        }
    };

    const getStatusTextColor = (status: string) => {
        switch (status) {
            case 'healthy': return 'text-green-600';
            case 'degraded': return 'text-yellow-600';
            case 'critical': return 'text-red-600';
            default: return 'text-gray-600';
        }
    };

    if (loading && !health) {
        return (
            <div className="min-h-screen bg-slate-950 flex items-center justify-center">
                <div className="text-center">
                    <Activity className="w-12 h-12 text-blue-400 animate-pulse mx-auto mb-4" />
                    <p className="text-slate-300">{t('systemStatus.loading')}</p>
                </div>
            </div>
        );
    }

    if (error && !health) {
        return (
            <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
                <div className="max-w-md bg-slate-900 rounded-2xl shadow-2xl p-8 border border-slate-800">
                    <XCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
                    <h1 className="text-2xl font-black text-white text-center mb-2 tracking-tighter uppercase">{t('common.error')}</h1>
                    <p className="text-slate-400 text-center">{error}</p>
                    <button
                        onClick={loadHealth}
                        className="mt-6 w-full px-4 py-2 bg-blue-600 text-white rounded-lg font-semibold hover:bg-blue-700 transition-colors"
                    >
                        {t('common.retry')}
                    </button>
                </div>
            </div>
        );
    }

    if (!health) return null;

    return (
        <div className="min-h-screen bg-slate-950 p-6">
            <div className="max-w-7xl mx-auto space-y-6">
                {/* Header */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <div className={`w-12 h-12 rounded-full ${getStatusColor(health.status)} flex items-center justify-center`}>
                            <Shield className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <h1 className="text-3xl font-black text-white tracking-tighter uppercase">{t('systemStatus.title')}</h1>
                            <p className="text-slate-400 text-sm mt-1">
                                Iron Core v{health.version} ΓÇó {t('systemStatus.lastUpdate')} {lastUpdate.toLocaleTimeString()}
                            </p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <label className="flex items-center gap-2 text-sm text-slate-300">
                            <input
                                type="checkbox"
                                checked={autoRefresh}
                                onChange={(e) => setAutoRefresh(e.target.checked)}
                                className="rounded"
                            />
                            {t('systemStatus.autoRefresh')} (30s)
                        </label>
                        <button
                            onClick={loadHealth}
                            disabled={loading}
                            className="px-4 py-2 bg-slate-800 text-white rounded-lg font-semibold hover:bg-slate-700 disabled:opacity-50 transition-colors flex items-center gap-2"
                        >
                            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
                            {t('common.refresh')}
                        </button>
                        {health.summary.failed > 0 && (
                            <button
                                onClick={handleRepairAll}
                                disabled={repairing}
                                className="px-4 py-2 bg-blue-600 text-white rounded-lg font-semibold hover:bg-blue-700 disabled:opacity-50 transition-colors flex items-center gap-2"
                            >
                                <Wrench className="w-4 h-4" />
                                {repairing ? t('systemStatus.repairing') : t('systemStatus.repairAll')}
                            </button>
                        )}
                    </div>
                </div>

                {/* Status Overview */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
                    <div className="bg-slate-900 rounded-xl p-6 border border-slate-800">
                        <div className="flex items-center gap-3 mb-2">
                            <div className={`w-3 h-3 rounded-full ${getStatusColor(health.status)}`}></div>
                            <p className="text-sm text-slate-400">{t('systemStatus.generalStatus')}</p>
                        </div>
                        <p className={`text-2xl font-black uppercase tracking-tighter ${getStatusTextColor(health.status)}`}>
                            {t(`systemStatus.status.${health.status}`)}
                        </p>
                    </div>

                    <div className="bg-slate-900 rounded-xl p-6 border border-slate-800">
                        <div className="flex items-center gap-3 mb-2">
                            <CheckCircle className="w-5 h-5 text-green-500" />
                            <p className="text-sm text-slate-400">{t('systemStatus.passedChecks')}</p>
                        </div>
                        <p className="text-2xl font-black text-green-500 tracking-tighter tabular-nums">{health.summary.passed}</p>
                    </div>

                    <div className="bg-slate-900 rounded-xl p-6 border border-slate-800">
                        <div className="flex items-center gap-3 mb-2">
                            <XCircle className="w-5 h-5 text-red-500" />
                            <p className="text-sm text-slate-400">{t('systemStatus.failedChecks')}</p>
                        </div>
                        <p className="text-2xl font-black text-red-500 tracking-tighter tabular-nums">{health.summary.failed}</p>
                    </div>

                    <div className="bg-slate-900 rounded-xl p-6 border border-slate-800">
                        <div className="flex items-center gap-3 mb-2">
                            <AlertTriangle className="w-5 h-5 text-yellow-500" />
