/**
 * Backup Location Service - NIVEL NASA
 * Permite al usuario elegir d├│nde guardar y desde d├│nde restaurar backups
 * Soporta: Disco Local, Pendrive, Google Drive, Descargas
 */

import { logger } from '../core/logging/SystemLogger';
import { GDriveSyncService } from './GDriveSyncService';

export type BackupLocation = 'downloads' | 'local-disk' | 'google-drive' | 'custom';

export interface BackupDestination {
    type: BackupLocation;
    handle?: FileSystemDirectoryHandle; // Para File System Access API
    path?: string; // Para mostrar al usuario
}

export class BackupLocationService {
    private static lastUsedLocation: BackupDestination | null = null;

    /**
     * Verifica si File System Access API est├í disponible
     */
    static isFileSystemAccessSupported(): boolean {
        return 'showSaveFilePicker' in window && 'showDirectoryPicker' in window;
    }

    /**
     * Permite al usuario elegir d├│nde guardar el backup
     */
    static async chooseBackupLocation(): Promise<BackupDestination | null> {
        try {
            if (!this.isFileSystemAccessSupported()) {
                logger.warn('BackupLocation', 'api_not_supported', 'File System Access API no disponible');
                return { type: 'downloads' }; // Fallback a descargas
            }

            // Mostrar selector de directorio
            const dirHandle = await window.showDirectoryPicker({
                mode: 'readwrite',
                startIn: 'documents'
            });

            const destination: BackupDestination = {
                type: 'custom',
                handle: dirHandle,
                path: dirHandle.name
            };

            this.lastUsedLocation = destination;
            logger.info('BackupLocation', 'location_selected', `Usuario seleccion├│: ${dirHandle.name}`);

            return destination;
        } catch (e: any) {
            if (e.name === 'AbortError') {
                logger.info('BackupLocation', 'cancelled', 'Usuario cancel├│ selecci├│n');
                return null;
            }
            logger.error('BackupLocation', 'selection_error', 'Error seleccionando ubicaci├│n', null, e);
            return null;
        }
    }

    /**
     * Guarda el backup en la ubicaci├│n elegida
     */
    static async saveBackup(
        data: string,
        filename: string,
        destination?: BackupDestination
    ): Promise<boolean> {
        const dest = destination || this.lastUsedLocation || { type: 'downloads' };

        try {
            switch (dest.type) {
                case 'google-drive':
                    return await this.saveToGoogleDrive(data, filename);

                case 'custom':
                case 'local-disk':
                    if (dest.handle) {
                        return await this.saveToFileSystem(data, filename, dest.handle);
                    }
                    // Fallback a descargas si no hay handle
                    return await this.saveToDownloads(data, filename);

                case 'downloads':
                default:
                    return await this.saveToDownloads(data, filename);
            }
        } catch (e) {
            logger.error('BackupLocation', 'save_failed', 'Error guardando backup', null, e as Error);
            return false;
        }
    }

    /**
     * Guarda en Google Drive
     */
    private static async saveToGoogleDrive(data: string, filename: string): Promise<boolean> {
        try {
            const blob = new Blob([data], { type: 'application/json' });
            return await GDriveSyncService.uploadBackup(blob, filename);
        } catch (e) {
            logger.error('BackupLocation', 'gdrive_failed', 'Error guardando en Google Drive', null, e as Error);
            return false;
        }
    }

    /**
     * Guarda usando File System Access API
     */
    private static async saveToFileSystem(
        data: string,
        filename: string,
        dirHandle: FileSystemDirectoryHandle
    ): Promise<boolean> {
        try {
            // Crear archivo en el directorio seleccionado
            const fileHandle = await dirHandle.getFileHandle(filename, { create: true });

            // Obtener writable stream con safe fallback
            const writable = await (fileHandle.createWritable?.() ?? Promise.reject(new Error('createWritable not available')));

            // Escribir datos
            await writable.write(data);
            await writable.close();

            logger.info('BackupLocation', 'saved_to_disk', `Backup guardado en: ${dirHandle.name}/${filename}`);
            return true;
        } catch (e) {
            logger.error('BackupLocation', 'filesystem_failed', 'Error guardando en disco', null, e as Error);
            return false;
        }
    }

    /**
     * Guarda en carpeta de Descargas (m├⌐todo tradicional)
     */
    private static async saveToDownloads(data: string, filename: string): Promise<boolean> {
        try {
            const blob = new Blob([data], { type: 'application/json' });
            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);

            URL.revokeObjectURL(url);

            logger.info('BackupLocation', 'saved_to_downloads', `Backup descargado: ${filename}`);
            return true;
        } catch (e) {
            logger.error('BackupLocation', 'download_failed', 'Error descargando backup', null, e as Error);
            return false;
        }
    }

    /**
     * Permite al usuario elegir un archivo de backup para restaurar
     */
    static async chooseBackupFile(): Promise<File | null> {
        try {
            if (!this.isFileSystemAccessSupported()) {
                // Fallback a input file tradicional
                return await this.chooseFileTraditional();
            }

            // Usar File System Access API
            const [fileHandle] = await window.showOpenFilePicker({
                types: [
                    {
                        description: 'AccountExpress Backup',
                        accept: {
                            'application/json': ['.aex', '.json']
                        }
                    }
                ],
                multiple: false
            });

            const file = await fileHandle.getFile();
            logger.info('BackupLocation', 'file_selected', `Usuario seleccion├│: ${file.name}`);

            return file;
        } catch (e: any) {
            if (e.name === 'AbortError') {
                logger.info('BackupLocation', 'cancelled', 'Usuario cancel├│ selecci├│n de archivo');
                return null;
            }
            logger.error('BackupLocation', 'file_selection_error', 'Error seleccionando archivo', null, e);
            return null;
        }
    }

    /**
     * M├⌐todo tradicional para elegir archivo (fallback)
     */
    private static async chooseFileTraditional(): Promise<File | null> {
        return new Promise((resolve) => {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.aex,.json';
            input.style.display = 'none';

            // Adjuntar al DOM ANTES de hacer click ΓÇö cr├¡tico para Chrome/Firefox
            document.body.appendChild(input);

            let settled = false;

            const cleanup = (file: File | null) => {
                if (settled) return;
                settled = true;
                // Peque├▒o delay antes de remover para que el evento termine de propagarse
                setTimeout(() => {
                    if (document.body.contains(input)) {
                        document.body.removeChild(input);
                    }
                }, 100);
                resolve(file);
            };

            input.addEventListener('change', (e) => {
                const file = (e.target as HTMLInputElement).files?.[0] ?? null;
                cleanup(file);
            });

            // Detectar cancelaci├│n real: el foco vuelve a window despu├⌐s de cerrar el picker
            // sin haber disparado 'change'
            const onWindowFocus = () => {
                window.removeEventListener('focus', onWindowFocus);
                // Esperar un tick para que 'change' dispare primero si hubo selecci├│n
                setTimeout(() => {
                    cleanup(null);  // Si ya se liquid├│ con un archivo, este cleanup no hace nada
                }, 300);
            };

            window.addEventListener('focus', onWindowFocus);

            input.click();
        });
    }

    /**
     * Detecta dispositivos externos (pendrives, discos externos)
     * Nota: Requiere permisos y solo funciona en navegadores compatibles
     */
    static async detectExternalDevices(): Promise<string[]> {
        try {
            if ('storage' in navigator && 'estimate' in (navigator as any).storage) {
                // Intentar detectar dispositivos montados
                // Nota: Esta API es limitada por seguridad del navegador
                const estimate = await (navigator as any).storage.estimate();
                logger.info('BackupLocation', 'storage_info', 'Informaci├│n de almacenamiento', estimate);
            }

            // Por ahora, retornamos lista vac├¡a
            // La detecci├│n real de pendrives requiere permisos especiales
            return [];
        } catch (e) {
            logger.warn('BackupLocation', 'detection_failed', 'No se pudo detectar dispositivos externos');
            return [];
        }
    }

    /**
     * Obtiene la ├║ltima ubicaci├│n usada
     */
    static getLastUsedLocation(): BackupDestination | null {
        return this.lastUsedLocation;
    }

    /**
     * Limpia la ├║ltima ubicaci├│n usada
     */
    static clearLastUsedLocation(): void {
        this.lastUsedLocation = null;
    }
}

/**
 * External Timestamp Service
 * Provides RFC 3161 compliant timestamp authority integration
 * 
 * In production, this would connect to a real TSA (Time Stamping Authority)
 * For testing and development, provides mock timestamps
 */
export class ExternalTimestampService {
    /**
     * Gets a trusted timestamp from an external authority
     * @param data - The data to timestamp (usually a hash)
     * @returns Promise<string | null> - The timestamp token or null if unavailable
     */
    static async getTrustedTimestamp(dataHash: string): Promise<string | null> {
        // In test mode, return mock timestamp
        if (process.env.NODE_ENV === 'test' || process.env.TEST_MODE === 'true') {
            return `MOCK_TIMESTAMP_${Date.now()}_${dataHash.substring(0, 8)}`;
        }

        try {
            // 1. Create ASN.1 DER encoded TimeStampReq
            const requestBytes = this.createTimeStampRequest(dataHash);

            // 2. Send to FreeTSA.org
            const response = await fetch('https://freetsa.org/tsr', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/timestamp-query',
                    'Content-Length': requestBytes.byteLength.toString()
                },
                body: new Blob([requestBytes.buffer as ArrayBuffer])
            });

            if (!response.ok) {
                throw new Error(`TSA responded with ${response.status} ${response.statusText}`);
            }

            // 3. Get binary response (TimeStampResp)
            const arrayBuffer = await response.arrayBuffer();
            const responseBytes = new Uint8Array(arrayBuffer);

            // 4. Return as Base64 string for storage
            return this.arrayBufferToBase64(responseBytes);

        } catch (error) {
            console.error('Failed to get external timestamp from FreeTSA:', error);
            // Fallback: don't break the app, but log weakness
            return null;
        }
    }

    /**
     * Verifies a timestamp token
     * Note: Real verification requires parsing the CMS SignedData (TimeStampResp),
     * checking the signature against the TSA CA certificate, and comparing the hash.
     * This is complex to implement without a heavy crypto lib.
     * For MVP, we check structure sanity.
     */
    static async verifyTimestamp(tokenBase64: string, originalHash: string): Promise<boolean> {
        // In test mode, accept mock timestamps
        if (process.env.NODE_ENV === 'test' || process.env.TEST_MODE === 'true') {
            return tokenBase64.startsWith('MOCK_TIMESTAMP_');
        }

        // Basic sanity check for Base64 + ASN.1 structure header
        try {
            if (!tokenBase64 || tokenBase64.length < 100) return false;
            // Decode base64 to check 1st byte (should be 0x30 for SEQUENCE)
            const binaryString = atob(tokenBase64);
            return binaryString.charCodeAt(0) === 0x30;
        } catch {
            return false;
        }
    }

    // --- HELPER: ASN.1 DER Encoder for TimeStampReq ---

    private static createTimeStampRequest(hashHex: string): Uint8Array {
        // SHA-256 OID: 2.16.840.1.101.3.4.2.1
        // DER encoded OID: 06 09 60 86 48 01 65 03 04 02 01
        const sha256Oid = [0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01];

        // Convert hex hash to bytes
        const hashBytes = this.hexToBytes(hashHex); // Should be 32 bytes for SHA-256

        // MessageImprint ::= SEQUENCE { hashAlgorithm, hashedMessage }
        // AlgorithmIdentifier ::= SEQUENCE { algorithm OID, parameters NULL }
        const algoIdWithNull = [
            0x30, 0x0d, // SEQUENCE (13 bytes)
            ...sha256Oid,
            0x05, 0x00  // NULL
        ];

        const hashedMessage = [
            0x04, hashBytes.length, // OCTET STRING
            ...hashBytes
        ];

        const messageImprintPayload = [...algoIdWithNull, ...hashedMessage];
        const messageImprint = [
            0x30, messageImprintPayload.length, // SEQUENCE
            ...messageImprintPayload
        ];

        // Nonce (Random Integer)
        const nonceVal = Math.floor(Math.random() * 2147483647);
        // Simplified encoding for positive 32-bit int (assume 4 bytes needed max, simplistic DER)
        const nonceBytes = this.intToBytes(nonceVal);
        const nonce = [
            0x02, nonceBytes.length, // INTEGER
            ...nonceBytes
        ];

        // Certificates Request: TRUE (Boolean)
        const certReq = [0x01, 0x01, 0xff];

        // Version: 1 (Integer)
        const version = [0x02, 0x01, 0x01];

        // TimeStampReq ::= SEQUENCE
        const reqPayload = [...version, ...messageImprint, ...nonce, ...certReq];
        const request = new Uint8Array([
            0x30, // SEQUENCE TAG
            ...this.encodeLength(reqPayload.length),
            ...reqPayload
        ]);

        return request;
    }

    // --- UTILS ---

    private static hexToBytes(hex: string): number[] {
        const bytes: number[] = [];
        for (let c = 0; c < hex.length; c += 2)
            bytes.push(parseInt(hex.substr(c, 2), 16));
        return bytes;
    }

    private static intToBytes(num: number): number[] {
        const arr: number[] = [
            (num >> 24) & 0xff,
            (num >> 16) & 0xff,
            (num >> 8) & 0xff,
            num & 0xff,
        ];
        // Remove leading zeros for minimal encoding compliance (roughly)
        while (arr.length > 1 && arr[0] === 0) arr.shift();
        // If high bit is set, prepend 00 to make it positive in 2's complement
        if (arr[0] & 0x80) arr.unshift(0);
        return arr;
    }

    private static encodeLength(len: number): number[] {
        if (len < 128) return [len];
        const lenBytes: number[] = [];
        while (len > 0) {
            lenBytes.unshift(len & 0xff);
            len = len >> 8;
        }
        return [0x80 | lenBytes.length, ...lenBytes];
    }

    private static arrayBufferToBase64(buffer: Uint8Array): string {
        let binary = '';
        const len = buffer.byteLength;
        for (let i = 0; i < len; i++) {
            binary += String.fromCharCode(buffer[i]);
        }
        return btoa(binary);
    }
}

import { DatabaseService } from '../database/DatabaseService';
import { BasicEncryption } from '../core/security/BasicEncryption';
import { CurrencyUtils } from '../lib/currency';

export interface AuditResult {
    valid: boolean;
    brokenBlockId?: number;
    errorType?: 'HASH_MISMATCH' | 'BROKEN_LINK' | 'MISSING_DATA' | 'TAMPERING_DETECTED';
    details?: string;
}

export class ForensicAuditService {

    /**
     * Realiza una auditor├¡a completa de la cadena de bloques (Audit Chain).
     * Verifica continuidad de enlaces y recalcula hashes contra datos reales.
     */
    static async performFullAudit(): Promise<AuditResult> {
        try {
            const chain = await DatabaseService.executeQuery("SELECT * FROM audit_chain ORDER BY id ASC");
            if (chain.length === 0) return { valid: true };

            let previousHash = 'GENESIS_BLOCK';

            for (const block of chain) {
                // 1. Verificaci├│n de Enlace (Link Check)
                if (block.previous_hash !== previousHash) {
                    return {
                        valid: false,
                        brokenBlockId: block.id,
                        errorType: 'BROKEN_LINK',
                        details: `El bloque ${block.id} apunta a un hash previo incorrecto.`
                    };
                }

                // 2. Verificaci├│n de Integridad de Datos (Data Check)
                // Obtenemos los datos originales de la tabla fuente
                // NOTA: Asumimos 'journal_entries' por ahora.
                if (block.table_name === 'journal_entries') {
                    const records = await DatabaseService.executeQuery(`SELECT * FROM journal_entries WHERE id = ?`, [block.record_id]);
                    if (records.length === 0) {
                        return {
                            valid: false,
                            brokenBlockId: block.id,
                            errorType: 'MISSING_DATA',
                            details: `Registro fuente ID ${block.record_id} desapareci├│ de journal_entries.`
                        };
                    }
                    const record = records[0];

                    // Reconstrucci├│n del Data Hash verificable (Sincronizado con journal_details)
                    const lines = await DatabaseService.executeQuery(`SELECT account_code, debit_amount, credit_amount FROM journal_details WHERE journal_entry_id = ? ORDER BY id ASC`, [record.id]);

                    if (lines.length > 0) {
                        const itemsPayload = lines.map((l: any) => ({
                            code: l.account_code,
                            debit: l.debit_amount,
                            credit: l.credit_amount
                        }));

                        const payloadObj = {
                            entryNumber: record.entry_number,
                            description: record.description,
                            total: record.total_debit,
                            items: itemsPayload
                        };

                        const calculatedDataHash = await BasicEncryption.hash(new TextEncoder().encode(JSON.stringify(payloadObj)));

                        if (calculatedDataHash !== block.data_hash) {
                            return {
                                valid: false,
                                brokenBlockId: block.id,
                                errorType: 'HASH_MISMATCH',
                                details: `DATA TAMPERING: El contenido de l├¡neas del asiento no coincide con el hash inmutable.`
                            };
                        }
                    }


                    // Verificaci├│n de Sello (Seal Check)
                    // chainPayload = previousHash + dataHash + transactionDate
                    // transactionDate est├í en record.transaction_date.

                    const transactionDate = record.transaction_date || record.entry_date; // Fallback
                    const payload = previousHash + block.data_hash + transactionDate;
                    const calculatedHash = await BasicEncryption.hash(new TextEncoder().encode(payload));

                    if (calculatedHash !== block.current_hash) {
                        return {
                            valid: false,
                            brokenBlockId: block.id,
                            errorType: 'HASH_MISMATCH',
                            details: `El hash calculado no coincide con el almacenado. Posible manipulaci├│n de fecha o hash.`
                        };
                    }
                }

                previousHash = block.current_hash;
            }

            return { valid: true };

        } catch (error: any) {
            return {
                valid: false,
                errorType: 'TAMPERING_DETECTED',
                details: `Error de ejecuci├│n en auditor├¡a: ${error.message}`
            };
        }
    }
}

