import { DatabaseService } from '../database/DatabaseService';
import { logger } from '../core/logging/SystemLogger';
import { BasicEncryption } from '../core/security/BasicEncryption';

/**
 * ForensicSentinel (NASA Level Objective 2)
 * Proactive integrity monitor. Detects data tampering and provides self-healing paths.
 */
export class ForensicSentinel {

    /**
     * Scans the entire audit chain and verifies consistency.
     */
    static async fullIntegrityAudit(): Promise<{
        healthy: boolean;
        tamperedRecords: any[];
    }> {
        const chain = await DatabaseService.executeQuery("SELECT * FROM audit_chain ORDER BY id ASC");
        const tamperedRecords: { type: string; [key: string]: any }[] = [];

        let expectedPreviousHash = 'GENESIS_BLOCK';

        for (const record of chain) {
            // 1. Verify Hash Chaining
            if (record.previous_hash !== expectedPreviousHash) {
                tamperedRecords.push({
                    type: 'CHAIN_BREAK',
                    recordId: record.id,
                    expected: expectedPreviousHash,
                    actual: record.previous_hash
                });
            }

            // 2. Verify Record Content (Bit-level check)
            // This is the "NASA" part: Re-execute the hash for the current record in the real table
            const currentData = await DatabaseService.executeQuery(
                `SELECT * FROM ${record.table_name} WHERE id = ?`,
                [record.record_id]
            );

            if (currentData.length > 0) {
                const dataHash = await BasicEncryption.hash(new TextEncoder().encode(JSON.stringify(currentData[0])));
                // Note: sealGenericRecord uses stringified payload. 
                // A true sentinel might need deeper payload matching.

                // For now, we verify the chain metadata integrity
                const chainPayload = record.previous_hash + record.data_hash + record.table_name + record.record_id + record.logic_clock;
                const recalculateHash = await BasicEncryption.hash(new TextEncoder().encode(chainPayload));

                if (recalculateHash !== record.current_hash) {
                    tamperedRecords.push({
                        type: 'METADATA_TAMPERING',
                        recordId: record.id,
                        tableName: record.table_name
                    });
                }
            }

            expectedPreviousHash = record.current_hash;
        }

        const healthy = tamperedRecords.length === 0;
        if (!healthy) {
            logger.error('Sentinel', 'tampering_detected', `Detected ${tamperedRecords.length} compromises in the Forensic Audit Chain!`);
        }

        return { healthy, tamperedRecords };
    }

    /**
     * Forensic Replay (NASA Level Objective 2.2)
     * Reconstructs a record's state by replaying its forensic history.
     */
    static async repairRecord(tableName: string, recordId: number): Promise<boolean> {
        try {
            logger.info('Sentinel', 'repair_start', `Repairing ${tableName}:${recordId}`);

            // Find the last valid state in the audit chain
            const history = await DatabaseService.executeQuery(
                "SELECT payload FROM audit_chain WHERE table_name = ? AND record_id = ? ORDER BY logic_clock DESC LIMIT 1",
                [tableName, recordId]
            );

            if (history.length === 0) {
                throw new Error('No forensic history found for this record.');
            }

            const lastValidState = JSON.parse(history[0].payload || '{}');

            // Self-Heal: Updata the table with the forensic truth
            const columns = Object.keys(lastValidState).filter(k => k !== 'id');
            const setClause = columns.map(col => `${col} = ?`).join(', ');
            const values = columns.map(col => lastValidState[col]);
            values.push(recordId);

            await DatabaseService.executeQuery(
                `UPDATE ${tableName} SET ${setClause} WHERE id = ?`,
                values
            );

            logger.info('Sentinel', 'repair_success', `Record ${recordId} in ${tableName} successfully healed.`);
            return true;
        } catch (e) {
            logger.error('Sentinel', 'repair_failed', `Failed to heal record ${recordId}`, null, e as Error);
            return false;
        }
    }

    /**
     * Health Telemetry Provider
     */
    static async getHealthStats() {
        const chainStats = await DatabaseService.executeQuery("SELECT COUNT(*) as count, MAX(logic_clock) as last_clock FROM audit_chain");
        const tamperedCount = (await this.fullIntegrityAudit()).tamperedRecords.length;

        return {
            status: tamperedCount === 0 ? 'HEALTHY' : 'COMPROMISED',
            forensicEvents: chainStats[0].count,
            lastClock: chainStats[0].last_clock,
            integrityScore: Math.max(0, 100 - (tamperedCount * 5)), // Industrial metric
            uptime: performance.now()
        };
    }
}

/**
 * PersistentStorageService (Iron Clad Upgrade - Phase 1, Day 4-5)
 * 
 * Manages browser persistent storage to protect OPFS from automatic cleanup.
 * Implements navigator.storage.persist() API and quota management.
 * 
 * Features:
 * - Request persistent storage permission
 * - Monitor storage quota
 * - Warn users of low space
 * - Provide storage statistics
 */

export class PersistentStorageService {
    private static readonly MIN_REQUIRED_SPACE = 500 * 1024 * 1024; // 500MB
    private static readonly WARNING_THRESHOLD = 0.9; // 90% usage

    /**
     * Requests persistent storage from the browser.
     * This prevents the browser from automatically clearing OPFS data.
     * 
     * @returns Promise<boolean> - true if persistence granted
     */
    static async requestPersistence(): Promise<boolean> {
        if (!navigator.storage || !navigator.storage.persist) {
            console.warn('ΓÜá∩╕Å Persistent Storage API not supported in this browser');
            return false;
        }

        try {
            // Check if already persistent with safe fallback
            const isPersisted = await (navigator.storage?.persisted?.() ?? Promise.resolve(false));
            if (isPersisted) {
                console.log('Γ£à Storage is already persistent');
                return true;
            }

            // Request persistence
            const granted = await navigator.storage.persist();

            if (granted) {
                console.log('Γ£à Persistencia solicitada ΓåÆ concedida');
                return true;
            } else {
                console.warn('ΓÜá∩╕Å Persistencia solicitada ΓåÆ denegada');
                return false;
            }

        } catch (error) {
            console.error('Γ¥î Error requesting persistent storage:', error);
            return false;
        }
    }

    /**
     * Checks if storage is currently persistent.
     * 
     * @returns Promise<boolean>
     */
    static async isPersistent(): Promise<boolean> {
        if (!navigator.storage || !navigator.storage.persisted) {
            return false;
        }

        try {
            return await navigator.storage.persisted();
        } catch (error) {
            console.error('Γ¥î Error checking persistence status:', error);
            return false;
        }
    }

    /**
     * Gets current storage quota and usage.
     * 
     * @returns Promise<{ usage: number; quota: number; available: number; percentUsed: number }>
     */
    static async checkQuota(): Promise<{
        usage: number;
        quota: number;
        available: number;
        percentUsed: number;
        usageMB: number;
        quotaMB: number;
        availableMB: number;
    }> {
        if (!navigator.storage || !navigator.storage.estimate) {
            throw new Error('Storage Estimation API not supported in this browser');
        }

        try {
            const estimate = await navigator.storage.estimate();
            const usage = estimate.usage || 0;
            const quota = estimate.quota || 0;
            const available = quota - usage;
            const percentUsed = quota > 0 ? (usage / quota) * 100 : 0;

            return {
                usage,
                quota,
                available,
                percentUsed,
                usageMB: Math.floor(usage / (1024 * 1024)),
                quotaMB: Math.floor(quota / (1024 * 1024)),
                availableMB: Math.floor(available / (1024 * 1024))
            };

        } catch (error) {
            console.error('Γ¥î Error checking storage quota:', error);
            throw error;
        }
    }

    /**
     * Checks if there is sufficient space available.
     * 
     * @param minRequired - Minimum required space in bytes (default: 500MB)
     * @returns Promise<boolean>
     */
    static async hasSufficientSpace(minRequired: number = this.MIN_REQUIRED_SPACE): Promise<boolean> {
        try {
            const { available } = await this.checkQuota();
            return available >= minRequired;
        } catch (error) {
            console.error('Γ¥î Error checking available space:', error);
            return false;
        }
    }

    /**
     * Warns user if storage space is low.
     * 
     * @param minRequired - Minimum required space in bytes (default: 500MB)
     * @returns Promise<void>
     */
    static async warnIfLowSpace(minRequired: number = this.MIN_REQUIRED_SPACE): Promise<void> {
        try {
            const quota = await this.checkQuota();

            // Check if below minimum required
            if (quota.available < minRequired) {
                const message = `ΓÜá∩╕Å ADVERTENCIA: Espacio de almacenamiento insuficiente\n\n` +
                    `Disponible: ${quota.availableMB}MB\n` +
                    `Requerido: ${Math.floor(minRequired / (1024 * 1024))}MB\n\n` +
                    `Por favor libera espacio o configura respaldo en la nube.`;

                console.warn(message);
                return;
            }

            // Check if above warning threshold
            if (quota.percentUsed > this.WARNING_THRESHOLD * 100) {
                const message = `ΓÜá∩╕Å ADVERTENCIA: Almacenamiento casi lleno\n\n` +
                    `Uso: ${quota.percentUsed.toFixed(1)}%\n` +
                    `Disponible: ${quota.availableMB}MB de ${quota.quotaMB}MB\n\n` +
                    `Considera liberar espacio o configurar respaldo en la nube.`;

                console.warn(message);
            }

        } catch (error) {
            console.error('Γ¥î Error checking storage space:', error);
        }
    }

    /**
     * Gets a human-readable storage status report.
     * 
     * @returns Promise<string>
     */
    static async getStorageReport(): Promise<string> {
        try {
            const isPersistent = await this.isPersistent();
            const quota = await this.checkQuota();

            const report = `
≡ƒôè STORAGE STATUS REPORT
ΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöü
≡ƒöÆ Persistent Storage: ${isPersistent ? 'Γ£à ENABLED' : 'Γ¥î DISABLED'}
≡ƒÆ╛ Usage: ${quota.usageMB}MB / ${quota.quotaMB}MB (${quota.percentUsed.toFixed(1)}%)
≡ƒôª Available: ${quota.availableMB}MB
ΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöü

