import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { FixedAssetService, FixedAsset } from './FixedAssetService';
import { AssetCategoryService } from './AssetCategoryService';
import { DepreciationService } from './DepreciationService';
import { DatabaseService } from '../../database/DatabaseService';

/**
 * Asset Disposal Model
 */
export interface AssetDisposal {
    id: number;
    asset_id: number;
    disposal_date: string;
    disposal_method: 'SALE' | 'RETIREMENT' | 'TRADE_IN' | 'LOST';
    original_cost: number; // in cents
    accumulated_depreciation: number; // in cents
    net_book_value: number; // in cents
    disposal_proceeds: number; // in cents
    gain_loss: number; // in cents
    journal_entry_id?: number;
    notes?: string;
    created_at: string;
}

export interface DisposalData {
    disposal_date: string; // ISO date
    disposal_method: 'SALE' | 'RETIREMENT' | 'TRADE_IN' | 'LOST';
    disposal_proceeds: number; // in cents (amount received, 0 for retirement/lost)
    notes?: string;
}

/**
 * AssetDisposalService
 * 
 * Handles asset disposal workflow:
 * - Calculate final depreciation up to disposal date
 * - Calculate gain/loss on disposal
 * - Create disposal journal entry
 * - Update asset status to DISPOSED
 */
export class AssetDisposalService {
    private assetService: FixedAssetService;
    private categoryService: AssetCategoryService;
    private depreciationService: DepreciationService;

    constructor(private db: SQLiteEngine) {
        this.assetService = new FixedAssetService(db);
        this.categoryService = new AssetCategoryService(db);
        this.depreciationService = new DepreciationService(db);
    }

    /**
     * Dispose of an asset (sale, retirement, trade-in, or loss)
     * 
     * Workflow:
     * 1. Calculate final depreciation up to disposal date
     * 2. Calculate gain/loss (proceeds - net book value)
     * 3. Create 4-line disposal journal entry
     * 4. Update asset status to DISPOSED
     * 5. Record disposal details
     */
    async disposeAsset(
        assetId: number,
        disposalData: DisposalData,
        userId: number | null
    ): Promise<number> {
        if (userId === null || userId === undefined) {
            throw new Error('[AssetDisposalService] userId requerido. Operaci├│n abortada.');
        }
        const asset = await this.assetService.getAssetById(assetId);
        if (!asset) {
            throw new Error(`Asset ${assetId} not found`);
        }

        if (asset.status === 'DISPOSED') {
            throw new Error('Asset is already disposed');
        }

        if (asset.status === 'PENDING') {
            throw new Error('Asset must be activated before disposal');
        }

        // Validate disposal date
        const disposalDate = new Date(disposalData.disposal_date);
        const purchaseDate = new Date(asset.purchase_date);

        if (disposalDate < purchaseDate) {
            throw new Error('Disposal date cannot be before purchase date');
        }

        // 1. Calculate final depreciation up to disposal date
        const finalDepreciation = await this.calculateFinalDepreciation(asset, disposalDate, userId);

        // Refresh asset data after depreciation
        const updatedAsset = await this.assetService.getAssetById(assetId);
        if (!updatedAsset) {
            throw new Error('Failed to refresh asset data');
        }

        // 2. Calculate gain/loss
        const netBookValue = updatedAsset.net_book_value || (updatedAsset.purchase_cost - updatedAsset.total_accumulated_depreciation);
        const gainLoss = disposalData.disposal_proceeds - netBookValue;

        // 3. Create disposal journal entry
        const category = await this.categoryService.getCategoryById(updatedAsset.category_id);
        if (!category) {
            throw new Error(`Category ${updatedAsset.category_id} not found`);
        }

        const journalEntryId = await this.createDisposalJournalEntry(
            updatedAsset,
            disposalData,
            netBookValue,
            gainLoss,
            category.gl_asset_account,
            category.gl_accumulated_dep_account,
            userId
        );

        // 4. Record disposal
        const disposalResult = await this.db.run(
            `INSERT INTO asset_disposals 
            (asset_id, disposal_date, disposal_method, original_cost, accumulated_depreciation, 
             net_book_value, disposal_proceeds, gain_loss, journal_entry_id, notes)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [
                assetId,
                disposalData.disposal_date,
                disposalData.disposal_method,
                updatedAsset.purchase_cost,
                updatedAsset.total_accumulated_depreciation,
                netBookValue,
                disposalData.disposal_proceeds,
                gainLoss,
                journalEntryId,
                disposalData.notes
            ]
        );

        // Get the last inserted ID
        const idResult = await this.db.select('SELECT last_insert_rowid() as id');
        const disposalId = idResult[0].id as number;

        // 5. Update asset status
        await this.db.run(
            `UPDATE fixed_assets 
            SET status = 'DISPOSED', 
                disposal_date = ?, 
                disposal_method = ?, 
                disposal_amount = ?, 
                disposal_entry_id = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?`,
            [
                disposalData.disposal_date,
                disposalData.disposal_method,
                disposalData.disposal_proceeds,
                journalEntryId,
                assetId
            ]
        );

        return disposalId;
    }

    /**
     * Get disposal by ID
     */
    async getDisposalById(id: number): Promise<AssetDisposal | null> {
        const disposals = await this.db.select(
            'SELECT * FROM asset_disposals WHERE id = ?',
            [id]
        );
        return disposals.length > 0 ? (disposals[0] as AssetDisposal) : null;
    }

    /**
     * Get disposal for an asset
     */
    async getDisposalForAsset(assetId: number): Promise<AssetDisposal | null> {
        const disposals = await this.db.select(
            'SELECT * FROM asset_disposals WHERE asset_id = ?',
            [assetId]
        );
        return disposals.length > 0 ? (disposals[0] as AssetDisposal) : null;
    }

    /**
     * Get all disposals with optional date range filter
     */
    async getAllDisposals(
        startDate?: string,
        endDate?: string
    ): Promise<AssetDisposal[]> {
        let query = 'SELECT * FROM asset_disposals WHERE 1=1';
        const params: any[] = [];

        if (startDate) {
            query += ' AND disposal_date >= ?';
            params.push(startDate);
        }
        if (endDate) {
            query += ' AND disposal_date <= ?';
            params.push(endDate);
        }

        query += ' ORDER BY disposal_date DESC';

        return (await this.db.select(query, params)) as any;
    }

    /**
     * Get disposal summary for a period
     */
    async getDisposalSummary(year?: number) {
        let query = `
            SELECT 
                COUNT(*) as total_disposals,
                SUM(disposal_proceeds) as total_proceeds,
                SUM(gain_loss) as total_gain_loss,
                SUM(CASE WHEN gain_loss > 0 THEN gain_loss ELSE 0 END) as total_gains,
                SUM(CASE WHEN gain_loss < 0 THEN gain_loss ELSE 0 END) as total_losses
            FROM asset_disposals
        `;

        const params: any[] = [];

        if (year) {
            query += ` WHERE strftime('%Y', disposal_date) = ?`;
            params.push(year.toString());
        }

        const result = await this.db.select(query, params);
        return result[0];
    }

    /**
     * Calculate final depreciation up to disposal date
     * Ensures asset is depreciated through the month of disposal
     */
    private async calculateFinalDepreciation(
        asset: FixedAsset,
        disposalDate: Date,
        userId: number
    ): Promise<number> {
        if (!asset.start_depreciation_date) {
            return 0; // No depreciation started
        }

        const startDate = new Date(asset.start_depreciation_date);

        // Get last depreciation entry
        const history = await this.depreciationService.getDepreciationHistory(asset.id);

        let lastDepreciationDate: Date;
        if (history.length > 0) {
            lastDepreciationDate = new Date(history[history.length - 1].period_date);
        } else {
            lastDepreciationDate = new Date(startDate.getFullYear(), startDate.getMonth() - 1, 1);
        }

        // Calculate depreciation for each month between last entry and disposal
        let periodDate = new Date(lastDepreciationDate);
        periodDate.setMonth(periodDate.getMonth() + 1);
        periodDate.setDate(1);

        const disposalMonth = disposalDate.getMonth();
        const disposalYear = disposalDate.getFullYear();

        let totalDepreciated = 0;

        while (
            periodDate.getFullYear() < disposalYear ||
            (periodDate.getFullYear() === disposalYear && periodDate.getMonth() <= disposalMonth)
        ) {
            // Check if entry already exists
            const existing = await this.depreciationService.getDepreciationForPeriod(
                asset.id,
                this.formatPeriodDate(periodDate)
            );

            if (!existing) {
                const entry = await this.depreciationService.calculateDepreciationForAsset(
                    asset.id,
                    periodDate,
                    userId
                );

                if (entry) {
                    totalDepreciated += entry.depreciation_amount;
                }
            }

            // Move to next month
            periodDate.setMonth(periodDate.getMonth() + 1);
        }

        return totalDepreciated;
    }

    /**
     * Create disposal journal entry (4-line entry)
     * 
     * For SALE:
     * DR: Cash (1000) - proceeds
     * DR: Accumulated Depreciation (1650) - accumulated
     * DR/CR: Gain/Loss (4900/5900) - difference
     * CR: Fixed Asset (1600) - original cost
     * 
     * For RETIREMENT/LOST (no proceeds):
     * DR: Accumulated Depreciation (1650)
     * DR: Loss on Disposal (5900)
     * CR: Fixed Asset (1600)
     */
    private async createDisposalJournalEntry(
        asset: FixedAsset,
        disposalData: DisposalData,
        netBookValue: number,
        gainLoss: number,
        assetAccount: number,
        accumulatedDepAccount: number,
        userId: number
    ): Promise<number> {
        const items: Array<{ account_code: string; debit: number; credit: number; description?: string }> = [];

        // Line 1: DR Cash (if proceeds exist)
        if (disposalData.disposal_proceeds > 0) {
            items.push({
                account_code: '1000',
                debit: disposalData.disposal_proceeds / 100,
                credit: 0,
                description: `${asset.asset_tag} - Proceeds`
            });
        }

        // Line 2: DR Accumulated Depreciation
        items.push({
            account_code: accumulatedDepAccount.toString(),
            debit: asset.total_accumulated_depreciation / 100,
            credit: 0,
            description: `${asset.asset_tag} - Accumulated Dep.`
        });

        // Line 3: DR/CR Gain or Loss
        if (gainLoss > 0) {
            // Gain
            items.push({
                account_code: '4900', // Gain on Sale of Assets
                debit: 0,
                credit: gainLoss / 100,
                description: `${asset.asset_tag} - Gain on Disposal`
            });
        } else if (gainLoss < 0) {
            // Loss
            items.push({
                account_code: '5900', // Loss on Sale of Assets
                debit: Math.abs(gainLoss) / 100,
                credit: 0,
                description: `${asset.asset_tag} - Loss on Disposal`
            });
        }

        // Line 4: CR Fixed Asset (original cost)
        items.push({
            account_code: assetAccount.toString(),
            debit: 0,
            credit: asset.purchase_cost / 100,
            description: `${asset.asset_tag} - Asset Retirement`
        });

        const entryNumber = await DatabaseService.insertJournalEntry({
            description: `Disposal of ${asset.asset_tag} - ${asset.asset_name} (${disposalData.disposal_method})`,
            date: disposalData.disposal_date,
            items,
            userId
        });

        // Get journal entry ID
        const entries = await this.db.select(
            'SELECT id FROM journal_entries WHERE entry_number = ?',
            [entryNumber]
        );

        return entries[0].id as number;
    }

    /**
     * Format period date as YYYY-MM-01
     */
    private formatPeriodDate(date: Date): string {
        const year = date.getFullYear();
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        return `${year}-${month}-01`;
    }
}

import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { FixedAssetService, FixedAsset } from './FixedAssetService';
import { AssetCategoryService } from './AssetCategoryService';
import { DepreciationCalculator, DepreciationParams } from './DepreciationCalculator';
import { DatabaseService } from '../../database/DatabaseService';
import { WorkerOrchestrator } from '../../core/workers/WorkerOrchestrator';

/**
 * Depreciation Entry Model
 */
export interface DepreciationEntry {
    id: number;
    asset_id: number;
    period_date: string;
    depreciation_amount: number; // in cents
    accumulated_depreciation: number; // in cents
    net_book_value: number; // in cents
    calculation_method: string;
    is_partial_month: boolean;
    journal_entry_id?: number;
    created_at: string;
}

export interface DepreciationBatchResult {
    period_date: string;
    total_assets_processed: number;
    total_depreciation_amount: number; // in cents
    entries_created: number;
    errors: Array<{ asset_id: number; error: string }>;
}

/**
 * DepreciationService
 * 
 * Handles automated depreciation calculations and journal entry creation.
 * Supports:
 * - Monthly batch processing for all active assets
 * - Manual calculation for specific assets
 * - Historical depreciation schedule generation
 */
export class DepreciationService {
    private assetService: FixedAssetService;
    private categoryService: AssetCategoryService;
    private static orchestrator: WorkerOrchestrator | null = null;

    private getOrchestrator(): WorkerOrchestrator {
        if (!DepreciationService.orchestrator) {
            DepreciationService.orchestrator = new WorkerOrchestrator();
        }
        return DepreciationService.orchestrator;
    }

    constructor(private db: SQLiteEngine) {
        this.assetService = new FixedAssetService(db);
        this.categoryService = new AssetCategoryService(db);
    }

    /**
     * Run monthly depreciation batch
     * Processes all ACTIVE assets for the specified period
     * 
     * @param periodDate First day of the month to depreciate (YYYY-MM-01)
     * @param userId User ID for journal entries
     */
    async runMonthlyDepreciationBatch(
        periodDate: Date,
        userId: number | null
    ): Promise<DepreciationBatchResult> {
        if (userId === null || userId === undefined) {
            throw new Error('[DepreciationService] userId requerido. Operaci├│n abortada.');
        }
        const periodDateStr = this.formatPeriodDate(periodDate);

        // Get all active assets
        const activeAssets = await this.assetService.getActiveAssets();

        const result: DepreciationBatchResult = {
            period_date: periodDateStr,
            total_assets_processed: 0,
            total_depreciation_amount: 0,
            entries_created: 0,
            errors: []
        };

        // Process each asset
        for (const asset of activeAssets) {
            try {
                // Skip if start_depreciation_date is after period_date
                if (asset.start_depreciation_date &&
                    new Date(asset.start_depreciation_date) > periodDate) {
                    continue;
                }

                // Check if already has entry for this period
                const existing = await this.getDepreciationForPeriod(asset.id, periodDateStr);
                if (existing) {
                    continue; // Skip already processed
                }

                const entry = await this.calculateDepreciationForAsset(asset.id, periodDate, userId);

                if (entry) {
                    result.total_assets_processed++;
                    result.total_depreciation_amount += entry.depreciation_amount;
                    result.entries_created++;
                }
            } catch (error: any) {
                result.errors.push({
                    asset_id: asset.id,
                    error: error.message || 'Unknown error'
                });
            }
        }

        return result;
    }

    /**
     * Calculate depreciation for a specific asset in a specific period
     */
    async calculateDepreciationForAsset(
        assetId: number,
        periodDate: Date,
        userId: number | null
    ): Promise<DepreciationEntry | null> {
        if (userId === null || userId === undefined) {
            throw new Error('[DepreciationService] userId requerido. Operaci├│n abortada.');
        }
        const asset = await this.assetService.getAssetById(assetId);
        if (!asset) {
            throw new Error(`Asset ${assetId} not found`);
        }

        if (asset.status !== 'ACTIVE') {
            throw new Error(`Asset ${assetId} is not active (status: ${asset.status})`);
        }

        // Check if already fully depreciated
        if (asset.net_book_value !== undefined &&
            asset.net_book_value <= asset.salvage_value) {
            return null; // No more depreciation needed
        }

        // Determine if this is the first month (partial month check)
        const purchaseDate = new Date(asset.purchase_date);
        const startDate = asset.start_depreciation_date
            ? new Date(asset.start_depreciation_date)
            : periodDate;

        const isPartialMonth = DepreciationCalculator.isFirstMonthPartial(purchaseDate, periodDate);

        // Prepare depreciation parameters
        const params: DepreciationParams = {
            cost: asset.purchase_cost,
            salvageValue: asset.salvage_value,
            usefulLifeMonths: asset.useful_life_months,
            currentBookValue: asset.net_book_value || asset.purchase_cost,
            isPartialMonth
        };

        // Calculate depreciation (Using Worker)
        const workerResult = await this.getOrchestrator().executeTask<any>('ACCOUNTING', {
            operation: 'single_depreciation',
            asset: {
                id: asset.id,
                purchase_cost: asset.purchase_cost,
                salvage_value: asset.salvage_value,
                useful_life_months: asset.useful_life_months,
                net_book_value: asset.net_book_value || asset.purchase_cost,
                depreciation_method: asset.depreciation_method.replace('_200', ''), // Normalize name for worker
                purchase_date: asset.purchase_date
            },
            periodDate: periodDate.toISOString()
        });

        const depreciationAmount = workerResult.depreciationAmount;

        // Calculate new accumulated depreciation
        const newAccumulated = asset.total_accumulated_depreciation + depreciationAmount;
        const newBookValue = asset.purchase_cost - newAccumulated;

        // Create journal entry
        const category = await this.categoryService.getCategoryById(asset.category_id);
        if (!category) {
            throw new Error(`Category ${asset.category_id} not found`);
        }

        const journalEntryId = await this.createDepreciationJournalEntry(
            asset,
            periodDate,
            depreciationAmount,
            category.gl_expense_account,
            category.gl_accumulated_dep_account,
            userId
        );

        // Insert depreciation entry
        const entryResult = await this.db.run(
            `INSERT INTO asset_depreciation 
            (asset_id, period_date, depreciation_amount, accumulated_depreciation, 
             net_book_value, calculation_method, is_partial_month, journal_entry_id)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            [
                asset.id,
                this.formatPeriodDate(periodDate),
                depreciationAmount,
                newAccumulated,
                newBookValue,
                asset.depreciation_method,
                isPartialMonth ? 1 : 0,
                journalEntryId
            ]
        );

        // Update asset's accumulated depreciation and net book value
        await this.assetService.updateDepreciationTotals(asset.id, newAccumulated);

        // Get the last inserted ID and fetch the entry
        const idResult = await this.db.select('SELECT last_insert_rowid() as id');
        return await this.getDepreciationById(idResult[0].id as number);
    }

    /**
     * Get depreciation history for an asset
     */
    async getDepreciationHistory(assetId: number): Promise<DepreciationEntry[]> {
        return (await this.db.select(
            `SELECT * FROM asset_depreciation 
            WHERE asset_id = ? 
            ORDER BY period_date ASC`,
            [assetId]
        )) as any;
    }

    /**
     * Get depreciation for a specific period
     */
    async getDepreciationForPeriod(
        assetId: number,
        periodDate: string
    ): Promise<DepreciationEntry | null> {
        const entries = await this.db.select(
            'SELECT * FROM asset_depreciation WHERE asset_id = ? AND period_date = ?',
            [assetId, periodDate]
        );
        return entries.length > 0 ? (entries[0] as DepreciationEntry) : null;
    }

    /**
     * Get depreciation entry by ID
     */
    async getDepreciationById(id: number): Promise<DepreciationEntry | null> {
        const entries = await this.db.select(
            'SELECT * FROM asset_depreciation WHERE id = ?',
            [id]
        );
        return entries.length > 0 ? (entries[0] as DepreciationEntry) : null;
    }

    /**
     * Generate future depreciation schedule for an asset
     * Useful for budgeting and forecasting
     */
    async generateDepreciationSchedule(assetId: number): Promise<Array<{
        period: string;
        depreciation: number;
        accumulated: number;
        book_value: number;
    }>> {
        const asset = await this.assetService.getAssetById(assetId);
        if (!asset) {
            throw new Error(`Asset ${assetId} not found`);
        }

        const startDate = asset.start_depreciation_date
            ? new Date(asset.start_depreciation_date)
            : new Date(asset.purchase_date);

        // Use DepreciationCalculator to project schedule
        const schedule = DepreciationCalculator.projectSchedule(
            asset.purchase_cost,
            asset.salvage_value,
            asset.useful_life_months,
            asset.depreciation_method,
            startDate
        );

        // Format for output
        return schedule.map(entry => ({
            period: entry.period.toISOString().substr(0, 10),
            depreciation: entry.depreciation,
            accumulated: entry.accumulated,
            book_value: entry.bookValue
        }));
    }

    /**
     * Get depreciation summary for a period
     */
    async getDepreciationSummary(periodDate: string) {
        const result = await this.db.select(`
            SELECT 
                COUNT(*) as total_entries,
                SUM(depreciation_amount) as total_depreciation,
                AVG(depreciation_amount) as avg_depreciation
            FROM asset_depreciation
            WHERE period_date = ?
        `, [periodDate]);

        return result[0];
    }

    /**
     * Create depreciation journal entry
     * DR: Depreciation Expense (5400)
     * CR: Accumulated Depreciation (1650)
     */
    private async createDepreciationJournalEntry(
        asset: FixedAsset,
        periodDate: Date,
        depreciationAmountCents: number,
        expenseAccount: number,
        accumulatedDepAccount: number,
        userId: number
    ): Promise<number> {
        const depreciationDollars = depreciationAmountCents / 100;
        const periodStr = periodDate.toISOString().substr(0, 7); // YYYY-MM

        const entryNumber = await DatabaseService.insertJournalEntry({
            description: `Depreciation ${periodStr} - ${asset.asset_tag} - ${asset.asset_name}`,
            date: this.formatPeriodDate(periodDate),
            items: [
                {
                    account_code: expenseAccount.toString(),
                    debit: depreciationDollars,
                    credit: 0,
                    description: `${asset.asset_tag} - Expense`
                },
                {
                    account_code: accumulatedDepAccount.toString(),
                    debit: 0,
                    credit: depreciationDollars,
                    description: `${asset.asset_tag} - Accumulated`
                }
            ],
            userId
        });

        // Get journal entry ID
        const entries = await this.db.select(
            'SELECT id FROM journal_entries WHERE entry_number = ?',
            [entryNumber]
        );

        return entries[0].id as number;
    }

    /**
     * Format period date as YYYY-MM-01
     */
    private formatPeriodDate(date: Date): string {
        const year = date.getFullYear();
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        return `${year}-${month}-01`;
    }
}

import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { AssetCategoryService, AssetCategory } from './AssetCategoryService';
import { DatabaseService } from '../../database/DatabaseService';
import { saveDatabase, forceSaveDB } from '@/database/simple-db';



/**
 * Fixed Asset Model
 */
export interface FixedAsset {
    id: number;
    asset_code: string;  // Usando esquema de simple-db.ts
    name: string;        // Usando esquema de simple-db.ts
    // Backwards-compatible aliases used by UI components
    asset_name: string; // alias of 'name'
    asset_tag: string;
    purchase_date: string; // alias of 'acquisition_date' / acquisition_date
    purchase_cost: number; // alias of 'acquisition_cost'
    description?: string;
    category_id: number;
    acquisition_date: string;  // Usando esquema de simple-db.ts
    acquisition_cost: number;  // Usando esquema de simple-db.ts (in cents)
    salvage_value: number; // in cents
    vendor_id?: number;
    useful_life_months: number;
    depreciation_method: 'STRAIGHT_LINE' | 'DECLINING_BALANCE_200';
    start_depreciation_date?: string;
    status: 'PENDING' | 'ACTIVE' | 'FULLY_DEPRECIATED' | 'DISPOSED';
    disposal_date?: string;
    disposal_method?: 'SALE' | 'RETIREMENT' | 'TRADE_IN' | 'LOST';
    disposal_amount?: number; // in cents
    total_accumulated_depreciation: number; // in cents (mapped from accumulated_depreciation)
    net_book_value?: number; // in cents (mapped from current_value)
    purchase_entry_id?: number;
    disposal_entry_id?: number;
    created_at: string;
    updated_at: string;
}

export interface AssetPurchaseData {
    asset_name: string;
    description?: string;
    category_id: number;
    purchase_date: string; // ISO date
    purchase_cost: number; // in cents
    salvage_value?: number; // in cents
    vendor_id?: number;
    useful_life_months?: number; // Override category default
    depreciation_method?: 'STRAIGHT_LINE' | 'DECLINING_BALANCE_200'; // Override
    activate_immediately?: boolean;
    payment_method: 'CASH' | 'PAYABLE'; // For journal entry
}

export interface AssetFilters {
    status?: 'PENDING' | 'ACTIVE' | 'FULLY_DEPRECIATED' | 'DISPOSED';
    category_id?: number;
    purchase_date_from?: string;
    purchase_date_to?: string;
    search?: string;
}

/**
 * FixedAssetService
 * 
 * Manages the complete lifecycle of fixed assets:
 * - Purchase/acquisition
 * - Activation and depreciation start
 * - Status tracking
 * - Disposal
 */
export class FixedAssetService {
    private categoryService: AssetCategoryService;

    private mapDbAsset(raw: any): FixedAsset {
        return {
            // Keep all existing properties from raw
            ...raw,
            // Legacy aliases for UI compatibility
            asset_name: raw.name || raw.asset_name || undefined,
            asset_tag: raw.asset_tag || raw.asset_code || undefined,
            purchase_date: raw.acquisition_date || raw.purchase_date || undefined,
            purchase_cost: raw.acquisition_cost || raw.purchase_cost || undefined,
            // Ensure numeric defaults where appropriate
            acquisition_cost: raw.acquisition_cost || raw.purchase_cost || 0,
            acquisition_date: raw.acquisition_date || raw.purchase_date || '',
        } as FixedAsset;
    }

    constructor(private db: SQLiteEngine) {
        this.categoryService = new AssetCategoryService(db);
    }

    /**
     * Purchase a new fixed asset
     * Creates the asset record and optionally creates the purchase journal entry
     */
    async purchaseAsset(data: AssetPurchaseData, userId: number | null): Promise<number> {
        if (userId === null || userId === undefined) {
            throw new Error('[FixedAssetService] userId requerido. Operaci├│n abortada.');
        }
        // Validate category exists
        const category = await this.categoryService.getCategoryById(data.category_id);
        if (!category) {
            throw new Error(`Category ID ${data.category_id} not found`);
        }

        // Use category defaults if not overridden
        const usefulLifeMonths = data.useful_life_months || category.default_useful_life_months;
        const depreciationMethod = data.depreciation_method || category.default_depreciation_method;
        const salvageValue = data.salvage_value ||
            Math.round(data.purchase_cost * (category.default_salvage_value_percent / 100));

        // Validate purchase cost
        if (data.purchase_cost <= 0) {
            throw new Error('Purchase cost must be greater than zero');
        }

        if (salvageValue >= data.purchase_cost) {
            throw new Error('Salvage value cannot be >= purchase cost');
        }

        // Generate asset tag
        const assetCode = await this.generateAssetTag(category.code);

        // Create purchase journal entry
        let purchaseEntryId: number | undefined;
        if (data.payment_method) {
            purchaseEntryId = await this.createPurchaseJournalEntry(
                data.asset_name,
                data.purchase_cost,
                data.purchase_date,
                category,
                data.payment_method,
                userId
            );
        }

        // Calculate initial net book value
        const netBookValue = data.purchase_cost;

        // Insert asset (usando nombres de columnas de simple-db.ts)
        const result = await this.db.run(
            `INSERT INTO fixed_assets 
            (asset_code, name, description, category_id, purchase_date, purchase_cost, 
             salvage_value, vendor_id, useful_life_months, depreciation_method, 
             net_book_value, purchase_entry_id, status)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [
                assetCode,
                data.asset_name,
                data.description,
                data.category_id,
                data.purchase_date,
                data.purchase_cost,
                salvageValue,
                data.vendor_id,
                usefulLifeMonths,
                depreciationMethod,
                netBookValue,
                purchaseEntryId,
                'PENDING'
            ]
        );

        // Get the last inserted ID
        const idResult = await this.db.select('SELECT last_insert_rowid() as id');
        const assetId = idResult[0].id as number;

        // Activate immediately if requested
        if (data.activate_immediately) {
            await this.activateAsset(assetId);
        }

        // Persistencia forzada
        await saveDatabase();


        return assetId;
    }


    /**
     * Activate an asset to begin depreciation
     */
    async activateAsset(assetId: number): Promise<void> {
        const asset = await this.getAssetById(assetId);
        if (!asset) {
            throw new Error(`Asset ID ${assetId} not found`);
        }

        if (asset.status !== 'PENDING') {
            throw new Error(`Asset must be in PENDING status to activate (current: ${asset.status})`);
        }

        // Set start_depreciation_date to first day of next month after purchase
        const purchaseDate = new Date(asset.purchase_date);
        const startDate = new Date(purchaseDate.getFullYear(), purchaseDate.getMonth() + 1, 1);

        await this.db.run(
            `UPDATE fixed_assets 
            SET status = 'ACTIVE', start_depreciation_date = ?, updated_at = CURRENT_TIMESTAMP
            WHERE id = ?`,
            [startDate.toISOString().split('T')[0], assetId]
        );

        // Persistencia forzada
        await saveDatabase();

    }


    /**
     * Get asset by ID
     */
    async getAssetById(assetId: number): Promise<FixedAsset | null> {
        const assets = await this.db.select(
            'SELECT * FROM fixed_assets WHERE id = ?',
            [assetId]
        );
        return assets.length > 0 ? this.mapDbAsset(assets[0]) : null;
    }

    /**
     * Get all assets with optional filters
     */
    async getAllAssets(filters?: AssetFilters): Promise<FixedAsset[]> {
        let query = 'SELECT * FROM fixed_assets WHERE 1=1';
        const params: any[] = [];

        if (filters) {
            if (filters.status) {
                query += ' AND status = ?';
                params.push(filters.status);
            }
            if (filters.category_id) {
                query += ' AND category_id = ?';
                params.push(filters.category_id);
            }
            if (filters.purchase_date_from) {
                query += ' AND purchase_date >= ?';
                params.push(filters.purchase_date_from);
            }
            if (filters.purchase_date_to) {
                query += ' AND purchase_date <= ?';
                params.push(filters.purchase_date_to);
            }
            if (filters.search) {
                query += ' AND (asset_name LIKE ? OR asset_tag LIKE ? OR description LIKE ?)';
                const searchTerm = `%${filters.search}%`;
                params.push(searchTerm, searchTerm, searchTerm);
            }
        }

        query += ' ORDER BY created_at DESC';

        const rows = await this.db.select(query, params);
        return rows.map((r: any) => this.mapDbAsset(r));
    }

    /**
     * Get only active assets (for depreciation batch)
     */
    async getActiveAssets(): Promise<FixedAsset[]> {
        const rows = await this.db.select(
            'SELECT * FROM fixed_assets WHERE status = ? ORDER BY purchase_date',
            ['ACTIVE']
        );
        return rows.map((r: any) => this.mapDbAsset(r));
    }

    /**
     * Update asset details
     * Note: Cannot change depreciation_method after activation (IRS compliance)
     */
    async updateAsset(assetId: number, data: Partial<AssetPurchaseData>): Promise<void> {
        const asset = await this.getAssetById(assetId);
        if (!asset) {
            throw new Error(`Asset ID ${assetId} not found`);
        }

        // Prevent changing depreciation method if already activated
        if (asset.status !== 'PENDING' && data.depreciation_method) {
            throw new Error(
                'Cannot change depreciation method after asset activation (IRS compliance)'
            );
        }

        // Build dynamic UPDATE
        const updates: string[] = [];
        const values: any[] = [];

        if (data.asset_name !== undefined) {
            updates.push('asset_name = ?');
            values.push(data.asset_name);
        }
        if (data.description !== undefined) {
            updates.push('description = ?');
            values.push(data.description);
        }
        if (data.salvage_value !== undefined) {
            updates.push('salvage_value = ?');
            values.push(data.salvage_value);
        }
        if (data.vendor_id !== undefined) {
            updates.push('vendor_id = ?');
            values.push(data.vendor_id);
        }
        if (data.useful_life_months !== undefined && asset.status === 'PENDING') {
            updates.push('useful_life_months = ?');
            values.push(data.useful_life_months);
        }
        if (data.depreciation_method !== undefined && asset.status === 'PENDING') {
            updates.push('depreciation_method = ?');
            values.push(data.depreciation_method);
        }

        updates.push('updated_at = CURRENT_TIMESTAMP');
        values.push(assetId);

        if (updates.length > 1) {
            await this.db.run(
                `UPDATE fixed_assets SET ${updates.join(', ')} WHERE id = ?`,
                values
            );

            // Persistencia forzada
            await forceSaveDB();
        }
    }


    /**
     * Update accumulated depreciation and net book value
     * Called by DepreciationService after each period
     */
    async updateDepreciationTotals(
        assetId: number,
        accumulatedDepreciation: number
    ): Promise<void> {
        const asset = await this.getAssetById(assetId);
        if (!asset) {
            throw new Error(`Asset ID ${assetId} not found`);
        }

        const netBookValue = asset.purchase_cost - accumulatedDepreciation;

        // Check if fully depreciated
        let status = asset.status;
        if (netBookValue <= asset.salvage_value && status === 'ACTIVE') {
            status = 'FULLY_DEPRECIATED';
        }

        await this.db.run(
            `UPDATE fixed_assets 
            SET total_accumulated_depreciation = ?, net_book_value = ?, status = ?, 
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?`,
            [accumulatedDepreciation, netBookValue, status, assetId]
        );

        // Persistencia forzada
        await saveDatabase();

    }


    /**
     * Generate unique asset tag based on category code and year
     * Format: {CATEGORY}-{YEAR}-{SEQUENCE}
     * Example: VEH-2026-001
     */
    private async generateAssetTag(categoryCode: string): Promise<string> {
        const year = new Date().getFullYear();
        const prefix = `${categoryCode}-${year}`;

        // Find max sequence number for this prefix
        const result = await this.db.select(
            `SELECT asset_tag FROM fixed_assets 
            WHERE asset_tag LIKE ? 
            ORDER BY asset_tag DESC 
            LIMIT 1`,
            [`${prefix}-%`]
        );

        let sequence = 1;
        if (result.length > 0) {
            const lastTag = result[0].asset_tag as string;
            const lastSeq = parseInt(lastTag.split('-')[2] || '0');
            sequence = lastSeq + 1;
        }

        return `${prefix}-${sequence.toString().padStart(3, '0')}`;
    }

    /**
     * Create purchase journal entry
     * DR: Fixed Assets (1600)
     * CR: Cash (1000) or Accounts Payable (2000)
     */
    private async createPurchaseJournalEntry(
        assetName: string,
        costInCents: number,
        purchaseDate: string,
        category: AssetCategory,
        paymentMethod: 'CASH' | 'PAYABLE',
        userId: number
    ): Promise<number> {
        const costDollars = costInCents / 100;
        const creditAccount = paymentMethod === 'CASH' ? '1000' : '2000';

        const entryNumber = await DatabaseService.insertJournalEntry({
            description: `Purchase of fixed asset: ${assetName}`,
            date: purchaseDate,
            items: [
                {
                    account_code: category.gl_asset_account.toString(),
                    debit: costDollars,
                    credit: 0,
                    description: `${assetName} - Asset`
                },
                {
                    account_code: creditAccount,
                    debit: 0,
                    credit: costDollars,
                    description: `${assetName} - Payment`
                }
            ],
            userId
        });

        // Get journal entry ID
        const entries = await this.db.select(
            'SELECT id FROM journal_entries WHERE entry_number = ?',
            [entryNumber]
        );

        return entries[0].id as number;
    }

    /**
     * Get asset summary statistics
     */
    async getAssetSummary(): Promise<{
        total_assets: number;
        active_assets: number;
        total_cost: number;
        total_depreciation: number;
        net_book_value: number;
    }> {
        const result = await this.db.select(`
            SELECT 
                COUNT(*) as total_assets,
                SUM(CASE WHEN status = 'ACTIVE' THEN 1 ELSE 0 END) as active_assets,
                COALESCE(SUM(purchase_cost), 0) as total_cost,
                COALESCE(SUM(total_accumulated_depreciation), 0) as total_depreciation,
                COALESCE(SUM(net_book_value), 0) as net_book_value
            FROM fixed_assets
            WHERE status != 'DISPOSED'
        `);

        return result[0] as any;
    }
}

// Servicio de autocompletado de direcciones usando API gratuita de Nominatim (OpenStreetMap)
import { ZIP_CODE_DATABASE, ZipCodeData, searchAddresses as searchZipCodes, findByZipCode } from '../data/zipCodes';
import { ExponentialBackoff } from '../core/resilience/ExponentialBackoff';
import { ProductionLogger } from '../core/logging/ProductionLogger';

export interface AddressSuggestion {
  id: string;
  display_name: string;
  city: string;
  state: string;
  stateCode: string;
  zipCode: string;
  county: string;
  lat?: number;
  lon?: number;
}

export interface AddressDetails {
  street: string;
  city: string;
  state: string;
  zipCode: string;
  county?: string;
  fullAddress: string;
}

class AddressService {
  private cache = new Map<string, AddressSuggestion[]>();
  private readonly NOMINATIM_BASE_URL = 'https://nominatim.openstreetmap.org/search';
  private readonly REQUEST_DELAY = 1000; // 1 segundo entre requests para respetar l├¡mites
  private lastRequestTime = 0;

  // Delay para respetar l├¡mites de la API gratuita
  private async respectRateLimit(): Promise<void> {
    const now = Date.now();
    const timeSinceLastRequest = now - this.lastRequestTime;
    if (timeSinceLastRequest < this.REQUEST_DELAY) {
      await new Promise(resolve => setTimeout(resolve, this.REQUEST_DELAY - timeSinceLastRequest));
    }
    this.lastRequestTime = Date.now();
  }

  // Buscar direcciones con autocompletado usando API gratuita + datos locales
  async searchAddresses(query: string): Promise<AddressSuggestion[]> {
    if (!query || query.length < 2) return [];

    ProductionLogger.debug('AddressService', 'Searching addresses', { query });

    // Verificar cache
    const cacheKey = query.toLowerCase().trim();
    if (this.cache.has(cacheKey)) {
      ProductionLogger.debug('AddressService', 'Returning cached results');
      return this.cache.get(cacheKey)!;
    }

    try {
      // Buscar en datos locales primero (siempre r├ípido)
      ProductionLogger.debug('AddressService', 'Searching local data');
      const localResults = searchZipCodes(query);
      ProductionLogger.debug('AddressService', 'Local results found', { count: localResults.length });
      
      const localSuggestions: AddressSuggestion[] = localResults.slice(0, 6).map((item, index) => ({
        id: `local-${item.zipCode}-${index}`,
        display_name: `${item.city}, ${item.stateCode} ${item.zipCode}`,
        city: item.city,
        state: item.state,
        stateCode: item.stateCode,
        zipCode: item.zipCode,
        county: item.county
      }));

      // Para queries cortas (2-3 caracteres), devolver solo resultados locales para mejor rendimiento
      if (query.length <= 3) {
        ProductionLogger.debug('AddressService', 'Returning local results for short query', { count: localSuggestions.length });
        if (localSuggestions.length > 0) {
          this.cache.set(cacheKey, localSuggestions);
        }
        return localSuggestions;
      }

      // Para queries m├ís largas, intentar API externa tambi├⌐n
      let apiSuggestions: AddressSuggestion[] = [];
      try {
        ProductionLogger.debug('AddressService', 'Searching external API');
        await this.respectRateLimit();
        
        apiSuggestions = await this.searchWithNominatim(query);
        ProductionLogger.debug('AddressService', 'API results found', { count: apiSuggestions.length });
      } catch (apiError) {
        ProductionLogger.warn('AddressService', 'API search failed, using local results only', { error: apiError });
      }
      
      // Combinar resultados, priorizando diversidad geogr├ífica
      const combinedResults = this.combineResultsWithDiversity(localSuggestions, apiSuggestions);

      ProductionLogger.debug('AddressService', 'Returning combined results', { count: combinedResults.length });
      
      // Guardar en cache
      if (combinedResults.length > 0) {
        this.cache.set(cacheKey, combinedResults);
      }
      
      return combinedResults;
      
    } catch (error) {
      ProductionLogger.error('AddressService', 'Error searching addresses', error as Error);
      
      // En caso de error, devolver solo resultados locales
      const fallbackResults = searchZipCodes(query).slice(0, 8).map((item, index) => ({
        id: `fallback-${item.zipCode}-${index}`,
        display_name: `${item.city}, ${item.stateCode} ${item.zipCode}`,
        city: item.city,
        state: item.state,
        stateCode: item.stateCode,
        zipCode: item.zipCode,
        county: item.county
      }));
      
      ProductionLogger.info('AddressService', 'Returning fallback results', { count: fallbackResults.length });
      return fallbackResults;
    }
  }

  // Combinar resultados priorizando diversidad geogr├ífica
  private combineResultsWithDiversity(
    localResults: AddressSuggestion[], 
    apiResults: AddressSuggestion[]
  ): AddressSuggestion[] {
    const combined: AddressSuggestion[] = [];
    const seenStates = new Set<string>();
    const seenCities = new Set<string>();
    
    // Agregar resultados locales primero
    for (const local of localResults) {
      if (combined.length < 6) {
        combined.push(local);
        seenStates.add(local.stateCode);
        seenCities.add(`${local.city}-${local.stateCode}`);
      }
    }
    
    // Agregar resultados de API, priorizando diversidad de estados
    for (const api of apiResults) {
      if (combined.length >= 6) break;
      
      const cityKey = `${api.city}-${api.stateCode}`;
      
      // Evitar duplicados exactos
      if (seenCities.has(cityKey)) continue;
      
      // Priorizar estados diferentes
      if (!seenStates.has(api.stateCode) || combined.length < 4) {
        combined.push(api);
        seenStates.add(api.stateCode);
        seenCities.add(cityKey);
      }
    }
    
    return combined;
  }

  // Buscar usando la API gratuita de Nominatim con exponential backoff
  private async searchWithNominatim(query: string): Promise<AddressSuggestion[]> {
    const backoff = new ExponentialBackoff({
      maxRetries: 3,
      baseDelay: 1000,
      maxDelay: 8000,
      shouldRetry: (error: Error) => {
        // Retry on network errors and 5xx server errors
        return error.message.includes('NetworkError') ||
               error.message.includes('ETIMEDOUT') ||
               error.message.includes('ECONNREFUSED') ||
               error.message.includes('500') ||
               error.message.includes('502') ||
               error.message.includes('503') ||
               error.message.includes('504');
      }
    });

    try {
      return await backoff.execute(async () => {
        // Construir URL de b├║squeda
        const params = new URLSearchParams({
          q: `${query}, United States`,
          format: 'json',
          addressdetails: '1',
          limit: '5',
          countrycodes: 'us',
          'accept-language': 'en'
        });

        const response = await fetch(`${this.NOMINATIM_BASE_URL}?${params}`, {
          headers: {
            'User-Agent': 'AccountExpress/1.0 (Business Application)'
          }
        });

        if (!response.ok) {
          throw new Error(`Nominatim API error: ${response.status}`);
        }

        const data = await response.json();
        ProductionLogger.debug('AddressService', 'Nominatim API response', { resultCount: data.length });

        // Procesar resultados de la API
        const suggestions: AddressSuggestion[] = [];
        
        for (const item of data) {
          if (item.address && item.address.state && item.address.country_code === 'us') {
            const stateCode = this.getStateCode(item.address.state);
            const city = item.address.city || item.address.town || item.address.village || item.address.hamlet;
            const county = item.address.county;
            const postcode = item.address.postcode;

            if (city && stateCode) {
              suggestions.push({
                id: `nominatim-${item.place_id}`,
                display_name: `${city}, ${stateCode}${postcode ? ' ' + postcode : ''}`,
                city: city,
                state: item.address.state,
                stateCode: stateCode,
                zipCode: postcode || '',
                county: county ? county.replace(' County', '') : '',
                lat: parseFloat(item.lat),
                lon: parseFloat(item.lon)
              });
            }
          }
        }

        return suggestions;
      }, 'AddressService.searchWithNominatim');
      
    } catch (error) {
      ProductionLogger.error('AddressService', 'Nominatim API failed after retries', error as Error);
      return [];
    }
  }

  // Obtener detalles completos de una direcci├│n
  async getAddressDetails(suggestion: AddressSuggestion): Promise<AddressDetails> {
    try {
      const details: AddressDetails = {
        street: '', // El usuario deber├í completar la calle manualmente
        city: suggestion.city,
        state: suggestion.stateCode,
        zipCode: suggestion.zipCode,
        county: suggestion.county,
        fullAddress: suggestion.display_name
      };

      return details;
    } catch (error) {
      ProductionLogger.error('AddressService', 'Error getting address details', error as Error);
      throw error;
    }
  }

  // Buscar por c├│digo postal espec├¡fico con exponential backoff
  async searchByZipCode(zipCode: string): Promise<AddressSuggestion | null> {
    ProductionLogger.debug('AddressService', 'Searching by zip code', { zipCode });
    
    // Primero buscar en datos locales
    const localResult = findByZipCode(zipCode);
    if (localResult) {
      ProductionLogger.debug('AddressService', 'Found in local data');
      return {
        id: localResult.zipCode,
        display_name: `${localResult.city}, ${localResult.stateCode} ${localResult.zipCode}`,
        city: localResult.city,
        state: localResult.state,
        stateCode: localResult.stateCode,
        zipCode: localResult.zipCode,
        county: localResult.county
      };
    }

    // Si no se encuentra localmente, buscar en API con backoff
    const backoff = new ExponentialBackoff({
      maxRetries: 3,
      baseDelay: 1000,
      maxDelay: 8000
    });

    try {
      await this.respectRateLimit();
      
      return await backoff.execute(async () => {
        const params = new URLSearchParams({
          q: `${zipCode}, United States`,
          format: 'json',
          addressdetails: '1',
          limit: '1',
          countrycodes: 'us'
        });

        const response = await fetch(`${this.NOMINATIM_BASE_URL}?${params}`, {
          headers: {
            'User-Agent': 'AccountExpress/1.0 (Business Application)'
          }
        });

        if (!response.ok) {
          throw new Error(`Nominatim API error: ${response.status}`);
        }

        const data = await response.json();
        if (data.length === 0) return null;

        const item = data[0];
        if (item.address && item.address.state) {
          const stateCode = this.getStateCode(item.address.state);
          const city = item.address.city || item.address.town || item.address.village;
          const county = item.address.county;

          if (city && stateCode) {
            ProductionLogger.debug('AddressService', 'Found via API');
            return {
              id: `api-${item.place_id}`,
              display_name: `${city}, ${stateCode} ${zipCode}`,
              city: city,
              state: item.address.state,
              stateCode: stateCode,
              zipCode: zipCode,
              county: county ? county.replace(' County', '') : ''
            };
          }
        }

        return null;
      }, 'AddressService.searchByZipCode');
    } catch (error) {
      ProductionLogger.error('AddressService', 'Error searching by zip code', error as Error);
      return null;
    }
  }

  // Convertir nombre de estado a c├│digo
  private getStateCode(stateName: string): string {
    const stateMap: Record<string, string> = {
      'alabama': 'AL', 'alaska': 'AK', 'arizona': 'AZ', 'arkansas': 'AR', 'california': 'CA',
      'colorado': 'CO', 'connecticut': 'CT', 'delaware': 'DE', 'florida': 'FL', 'georgia': 'GA',
      'hawaii': 'HI', 'idaho': 'ID', 'illinois': 'IL', 'indiana': 'IN', 'iowa': 'IA',
      'kansas': 'KS', 'kentucky': 'KY', 'louisiana': 'LA', 'maine': 'ME', 'maryland': 'MD',
      'massachusetts': 'MA', 'michigan': 'MI', 'minnesota': 'MN', 'mississippi': 'MS', 'missouri': 'MO',
      'montana': 'MT', 'nebraska': 'NE', 'nevada': 'NV', 'new hampshire': 'NH', 'new jersey': 'NJ',
      'new mexico': 'NM', 'new york': 'NY', 'north carolina': 'NC', 'north dakota': 'ND', 'ohio': 'OH',
      'oklahoma': 'OK', 'oregon': 'OR', 'pennsylvania': 'PA', 'rhode island': 'RI', 'south carolina': 'SC',
      'south dakota': 'SD', 'tennessee': 'TN', 'texas': 'TX', 'utah': 'UT', 'vermont': 'VT',
      'virginia': 'VA', 'washington': 'WA', 'west virginia': 'WV', 'wisconsin': 'WI', 'wyoming': 'WY',
      'district of columbia': 'DC'
    };

    return stateMap[stateName.toLowerCase()] || stateName.toUpperCase().substring(0, 2);
  }

  // Validar c├│digo postal
  isValidZipCode(zipCode: string): boolean {
    return /^\d{5}(-\d{4})?$/.test(zipCode);
  }

  // Obtener condado de Florida si aplica
  getFloridaCounty(county: string, city: string): string {
    // Mapeo de condados de Florida
    const floridaCounties = [
      'Alachua', 'Baker', 'Bay', 'Bradford', 'Brevard', 'Broward', 'Calhoun',
      'Charlotte', 'Citrus', 'Clay', 'Collier', 'Columbia', 'DeSoto', 'Dixie',
      'Duval', 'Escambia', 'Flagler', 'Franklin', 'Gadsden', 'Gilchrist',
      'Glades', 'Gulf', 'Hamilton', 'Hardee', 'Hendry', 'Hernando', 'Highlands',
      'Hillsborough', 'Holmes', 'Indian River', 'Jackson', 'Jefferson', 'Lafayette',
      'Lake', 'Lee', 'Leon', 'Levy', 'Liberty', 'Madison', 'Manatee', 'Marion',
      'Martin', 'Miami-Dade', 'Monroe', 'Nassau', 'Okaloosa', 'Okeechobee',
      'Orange', 'Osceola', 'Palm Beach', 'Pasco', 'Pinellas', 'Polk', 'Putnam',
      'Santa Rosa', 'Sarasota', 'Seminole', 'St. Johns', 'St. Lucie', 'Sumter',
      'Suwannee', 'Taylor', 'Union', 'Volusia', 'Wakulla', 'Walton', 'Washington'
    ];

    // Limpiar el nombre del condado
    const cleanCounty = county.replace(/\s+(County|Parish)$/i, '');
    
    // Buscar coincidencia exacta
    const match = floridaCounties.find(fc => 
      fc.toLowerCase() === cleanCounty.toLowerCase()
    );

    if (match) return match;

    // Mapeo especial para ciudades conocidas
    const cityToCounty: Record<string, string> = {
      'miami': 'Miami-Dade',
      'orlando': 'Orange',
      'tampa': 'Hillsborough',
      'jacksonville': 'Duval',
      'fort lauderdale': 'Broward',
      'west palm beach': 'Palm Beach',
      'tallahassee': 'Leon',
      'gainesville': 'Alachua',
      'pensacola': 'Escambia',
      'sarasota': 'Sarasota',
      'naples': 'Collier',
      'fort myers': 'Lee'
    };

    return cityToCounty[city.toLowerCase()] || 'Miami-Dade';
  }

  // Limpiar cache
  clearCache(): void {
    this.cache.clear();
  }
}

