    private static normalize(str: string): string {
        return str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    }

    static searchConcept(query: string, lang: 'es' | 'en' = 'es'): AccountingConcept | undefined {
        const normalizedQuery = this.normalize(query);
        for (const concept of Object.values(this.CONCEPTS)) {
            const keywords = [...concept.search_keywords.es, ...concept.search_keywords.en];
            for (const kw of keywords) {
                if (normalizedQuery.includes(this.normalize(kw))) return concept;
            }
        }
        return undefined;
    }

    static getProcedure(query: string, lang: 'es' | 'en' = 'es'): string[] | undefined {
        const normalizedQuery = this.normalize(query);
        const keywords = {
            es: ['venta', 'credito', 'factura', 'conciliacion', 'banco', 'cierre'],
            en: ['sale', 'credit', 'invoice', 'reconciliation', 'bank', 'close']
        };

        for (const [key, proc] of Object.entries(this.PROCEDURES)) {
            const nameEs = this.normalize(proc.es.name);
            const nameEn = this.normalize(proc.en.name);
            if (normalizedQuery.includes(nameEs) || normalizedQuery.includes(nameEn)) {
                return proc[lang].steps;
            }
        }

        // B├║squeda espec├¡fica por palabras clave si falla el nombre
        if (normalizedQuery.includes('venta') || normalizedQuery.includes('sale')) return this.PROCEDURES['credit_sale'][lang].steps;
        if (normalizedQuery.includes('concilia') || normalizedQuery.includes('reconcil')) return this.PROCEDURES['bank_reconciliation'][lang].steps;

        return undefined;
    }

    static getConceptKey(concept: AccountingConcept, lang: 'es' | 'en' = 'es'): string | undefined {
        return concept[lang].name;
    }

    static getAllTopics(lang: 'es' | 'en' = 'es'): string[] {
        return [
            ...Object.values(this.CONCEPTS).map(c => c[lang].name),
            ...Object.values(this.PROCEDURES).map(p => p[lang].name)
        ];
    }
}

/**
 * AnomalyDetector (Iron Clad Upgrade - Phase 3, Day 1)
 * 
 * Servicio de IA que detecta anomal├¡as contables autom├íticamente y genera propuestas.
 * 
 * Anomal├¡as detectadas:
 * - Asientos descuadrados (partida doble violada)
 * - Facturas vencidas no cobradas
 * - Transacciones duplicadas
 * - Gastos inusuales (outliers)
 * - Cuentas con saldo negativo inesperado
 */

import { db, getDBEngine } from '@/database/simple-db';
import { DraftProposalService } from '../DraftProposalService';
import { logger } from '../../core/logging/SystemLogger';

export class AnomalyDetector {
    private static get engine() {
        return getDBEngine();
    }

    /**
     * Ejecuta todas las detecciones de anomal├¡as
     */
    static async detectAll(): Promise<void> {
        logger.info('AnomalyDetector', 'scan_start', 'Iniciando escaneo de anomal├¡as');

        try {
            await Promise.all([
                this.detectUnbalancedEntries(),
                this.detectOverdueInvoices(),
                this.detectDuplicateTransactions(),
                this.detectUnusualExpenses(),
                this.detectNegativeBalances()
            ]);

            logger.info('AnomalyDetector', 'scan_complete', 'Escaneo completado');
        } catch (error) {
            logger.error('AnomalyDetector', 'scan_failed', 'Error en escaneo', null, error as Error);
        }
    }

    /**
     * Detecta asientos contables descuadrados
     */
    static async detectUnbalancedEntries(): Promise<void> {
        if (!db) return;

        try {
            // Buscar asientos donde d├⌐bitos != cr├⌐ditos
            const unbalanced = await this.engine.select(`
        SELECT 
          je.id,
          je.entry_date as date,
          je.description,
          SUM(jd.debit_amount) as total_debits,
          SUM(jd.credit_amount) as total_credits
        FROM journal_entries je
        LEFT JOIN journal_details jd ON je.id = jd.journal_entry_id
        WHERE je.status != 'voided'
        GROUP BY je.id
        HAVING ABS(SUM(jd.debit_amount) - SUM(jd.credit_amount)) > 0.01
        ORDER BY je.entry_date DESC
        LIMIT 10
      `);

            for (const entry of unbalanced) {
                const difference = entry.total_debits - entry.total_credits;

                await DraftProposalService.createProposal(
                    'accounting',
                    'CORRECT_JOURNAL_ENTRY',
                    {
                        journalEntryId: entry.id,
                        date: entry.date,
                        description: entry.description,
                        totalDebits: entry.total_debits,
                        totalCredits: entry.total_credits,
                        difference: difference,
                        suggestedCorrection: {
                            account: difference > 0 ? 'Suspense Account (Credit)' : 'Suspense Account (Debit)',
                            amount: Math.abs(difference),
                            type: difference > 0 ? 'credit' : 'debit'
                        }
                    },
                    `Asiento descuadrado detectado: D├⌐bitos ($${entry.total_debits.toFixed(2)}) != Cr├⌐ditos ($${entry.total_credits.toFixed(2)}). Diferencia: $${Math.abs(difference).toFixed(2)}`
                );

                logger.warn('AnomalyDetector', 'unbalanced_entry', `Asiento ${entry.id} descuadrado por $${Math.abs(difference).toFixed(2)}`);
            }

            if (unbalanced.length > 0) {
                logger.info('AnomalyDetector', 'unbalanced_found', `${unbalanced.length} asientos descuadrados detectados`);
            }
        } catch (error) {
            logger.error('AnomalyDetector', 'unbalanced_check_failed', 'Error al detectar asientos descuadrados', null, error as Error);
        }
    }

    /**
     * Detecta facturas vencidas no cobradas
     */
    static async detectOverdueInvoices(): Promise<void> {
        if (!db) return;

        try {
            const today = new Date().toISOString().split('T')[0];

            // Buscar facturas vencidas con saldo pendiente
            const overdue = await this.engine.select(`
        SELECT 
          i.id,
          i.invoice_number,
          i.customer_id,
          i.issue_date,
          i.due_date,
          i.total_amount,
          0 as amount_paid, -- Fallback since amount_paid column is missing
          i.total_amount as balance_due,
          julianday('${today}') - julianday(i.due_date) as days_overdue
        FROM invoices i
        WHERE i.status = 'sent'
        AND i.due_date < '${today}'
        AND i.total_amount > 0.01
        ORDER BY days_overdue DESC
        LIMIT 20
      `);

            for (const invoice of overdue) {
                // Solo crear propuesta si est├í muy vencida (>30 d├¡as)
                if (invoice.days_overdue > 30) {
                    await DraftProposalService.createProposal(
                        'accounting',
                        'SEND_PAYMENT_REMINDER',
                        {
                            invoiceId: invoice.id,
                            invoiceNumber: invoice.invoice_number,
                            customerId: invoice.customer_id,
                            dueDate: invoice.due_date,
                            balanceDue: invoice.balance_due,
                            daysOverdue: Math.floor(invoice.days_overdue),
                            suggestedAction: 'send_reminder_email'
                        },
                        `Factura ${invoice.invoice_number} vencida hace ${Math.floor(invoice.days_overdue)} d├¡as. Saldo pendiente: $${invoice.balance_due.toFixed(2)}`
                    );
                }
            }

            if (overdue.length > 0) {
                logger.info('AnomalyDetector', 'overdue_found', `${overdue.length} facturas vencidas detectadas`);
            }
        } catch (error) {
            logger.error('AnomalyDetector', 'overdue_check_failed', 'Error al detectar facturas vencidas', null, error as Error);
        }
    }

    /**
     * Detecta transacciones duplicadas
     */
    static async detectDuplicateTransactions(): Promise<void> {
        if (!db) return;

        try {
            // Buscar transacciones con mismo monto, fecha y descripci├│n
            const duplicates = await this.engine.select(`
        SELECT 
          transaction_date as date,
          description,
          amount,
          COUNT(*) as count,
          GROUP_CONCAT(id) as transaction_ids
        FROM bank_transactions
        WHERE status != 'voided'
        AND transaction_date >= date('now', '-90 days')
        GROUP BY transaction_date, description, amount
        HAVING COUNT(*) > 1
        ORDER BY count DESC, transaction_date DESC
        LIMIT 10
      `);

            for (const dup of duplicates) {
                const ids = dup.transaction_ids.split(',');

                await DraftProposalService.createProposal(
                    'accounting',
                    'REVIEW_DUPLICATES',
                    {
                        date: dup.date,
                        description: dup.description,
                        amount: dup.amount,
                        count: dup.count,
                        transactionIds: ids,
                        suggestedAction: 'review_and_void_duplicates'
                    },
                    `${dup.count} transacciones duplicadas detectadas: ${dup.description} por $${dup.amount.toFixed(2)} el ${dup.date}`
                );
            }

            if (duplicates.length > 0) {
                logger.info('AnomalyDetector', 'duplicates_found', `${duplicates.length} grupos de duplicados detectados`);
            }
        } catch (error) {
            logger.error('AnomalyDetector', 'duplicate_check_failed', 'Error al detectar duplicados', null, error as Error);
        }
    }

    /**
     * Detecta gastos inusuales (outliers)
     */
    static async detectUnusualExpenses(): Promise<void> {
        if (!db) return;

        try {
            // Calcular promedio y desviaci├│n est├índar de gastos por categor├¡a
            const stats = await this.engine.select(`
        SELECT 
          ca.account_name as category,
          AVG(jd.debit_amount) as avg_amount,
          COUNT(*) as count
        FROM journal_details jd
        JOIN chart_of_accounts ca ON jd.account_code = ca.account_code
        WHERE ca.account_type = 'expense'
        AND jd.debit_amount > 0
        GROUP BY ca.account_name
        HAVING COUNT(*) >= 5
      `);

            for (const stat of stats) {
                // Buscar gastos que sean 3x el promedio
                const threshold = stat.avg_amount * 3;

                const outliers = await this.engine.select(`
          SELECT 
            je.id,
            je.entry_date as date,
            je.description,
            jd.debit_amount as amount,
            ca.account_name as category
          FROM journal_details jd
          JOIN journal_entries je ON jd.journal_entry_id = je.id
          JOIN chart_of_accounts ca ON jd.account_code = ca.account_code
          WHERE ca.account_name = ?
          AND jd.debit_amount > ?
          AND je.entry_date >= date('now', '-90 days')
          AND je.status != 'voided'
          ORDER BY jd.debit_amount DESC
          LIMIT 5
        `, [stat.category, threshold]);

                for (const expense of outliers) {
                    await DraftProposalService.createProposal(
                        'accounting',
                        'REVIEW_UNUSUAL_EXPENSE',
                        {
                            expenseId: expense.id,
                            date: expense.date,
                            description: expense.description,
                            amount: expense.amount,
                            category: expense.category,
                            averageAmount: stat.avg_amount,
                            threshold: threshold,
                            suggestedAction: 'verify_expense_legitimacy'
                        },
                        `Gasto inusual detectado: $${expense.amount.toFixed(2)} en ${expense.category} (promedio: $${stat.avg_amount.toFixed(2)})`
                    );
                }
            }
        } catch (error) {
            logger.error('AnomalyDetector', 'unusual_check_failed', 'Error al detectar gastos inusuales', null, error as Error);
        }
    }

    /**
     * Detecta cuentas con saldo negativo inesperado
     */
    static async detectNegativeBalances(): Promise<void> {
        if (!db) return;

        try {
            // Buscar cuentas de activo con saldo negativo
            const negative = await this.engine.select(`
        SELECT 
          a.id,
          a.account_code as code,
          a.account_name as name,
          a.account_type as type,
          SUM(jd.debit_amount - jd.credit_amount) as balance
        FROM chart_of_accounts a
        LEFT JOIN journal_details jd ON a.account_code = jd.account_code
        LEFT JOIN journal_entries je ON jd.journal_entry_id = je.id
        WHERE (je.status IS NULL OR je.status != 'voided')
        AND a.account_type IN ('asset', 'expense')
        GROUP BY a.id, a.account_code, a.account_name, a.account_type
        HAVING balance < -0.01
        ORDER BY balance ASC
        LIMIT 10
      `);

            for (const account of negative) {
                await DraftProposalService.createProposal(
                    'accounting',
                    'REVIEW_NEGATIVE_BALANCE',
                    {
                        accountId: account.id,
                        accountCode: account.code,
                        accountName: account.name,
                        accountType: account.type,
                        balance: account.balance,
                        suggestedAction: 'review_account_transactions'
                    },
                    `Cuenta ${account.code} - ${account.name} tiene saldo negativo: $${account.balance.toFixed(2)}`
                );
            }

            if (negative.length > 0) {
                logger.info('AnomalyDetector', 'negative_found', `${negative.length} cuentas con saldo negativo detectadas`);
            }
        } catch (error) {
            logger.error('AnomalyDetector', 'negative_check_failed', 'Error al detectar saldos negativos', null, error as Error);
        }
    }

    /**
     * Programa escaneo autom├ítico cada hora
     */
    static scheduleAutoScan(): void {
        // Ejecutar inmediatamente
        this.detectAll();

        // Luego cada hora
        setInterval(() => {
            this.detectAll();
        }, 60 * 60 * 1000); // 1 hora

        logger.info('AnomalyDetector', 'auto_scan_scheduled', 'Escaneo autom├ítico programado cada hora');
    }
}

import { SystemKnowledge } from '../../knowledge/SystemKnowledge';
import { DatabaseService } from '../database/DatabaseService';
import { AssistantContext, KnowledgeSnippet } from './types';
import { AI_SECURITY_CONFIG } from '../../config/ai-security';

export class ContextBuilder {
    private dbService: DatabaseService;

    constructor() {
        this.dbService = DatabaseService.getInstance();
    }

    async buildContext(userQuery: string, userId: number): Promise<AssistantContext> {
        console.log(`[ContextBuilder] Building context for user ${userId}, query: "${userQuery}"`);

        // 1. AN├üLISIS DE INTENCI├ôN
        const topics = await this.extractTopicsAndIntent(userQuery);

        // 2. CONOCIMIENTO LOCAL RELEVANTE
        const localKnowledge = await this.searchLocalKnowledge(topics);

        // 3. DATOS DE VISTAS _summary (SOLO LECTURA)
        const relevantData = await this.queryRelevantSummaries(topics, userId);

        // 4. CONTEXTO DEL USUARIO
        const userContext = await this.getUserContext(userId);

        // 5. ESTADO DEL SISTEMA
        const systemState = await this.getSystemState();

        // 6. HISTORIAL DE CONVERSACI├ôN
        const conversationHistory = await this.getConversationHistory(userId);

        return {
            timestamp: new Date().toISOString(),
            userQuery,
            detectedTopics: topics,
            localKnowledge,
            relevantData: this.sanitizeForAPI(relevantData),
            userPermissions: userContext,
            systemState,
            conversationHistory
        };
    }

    private async extractTopicsAndIntent(query: string): Promise<string[]> {
        const topics: string[] = [];

        // Detectar temas contables
        const accountingTerms = {
            'depreciaci├│n': ['depreciaci├│n', 'amortizaci├│n', 'activo fijo', 'vida ├║til'],
            'impuestos': ['impuesto', 'tax', 'florida', 'condado', 'DR-15', 'surtax'],
            'inventario': ['inventario', 'stock', 'lote', 'SKU', 'rotaci├│n'],
            'facturaci├│n': ['factura', 'invoice', 'cliente', 'proveedor', 'pago'],
            'contabilidad': ['asiento', 'd├⌐bito', 'cr├⌐dito', 'balance', 'partida doble']
        };

        const queryLower = query.toLowerCase();

        // Buscar coincidencias
        Object.entries(accountingTerms).forEach(([topic, keywords]) => {
            if (keywords.some(keyword => queryLower.includes(keyword))) {
                topics.push(topic);
            }
        });

        return topics.length > 0 ? topics : ['general'];
    }

    private async searchLocalKnowledge(topics: string[]): Promise<KnowledgeSnippet[]> {
        const snippets: KnowledgeSnippet[] = [];

        // Buscar en conocimiento del sistema
        for (const topic of topics) {
            const results = await SystemKnowledge.searchByTopic(topic);
            snippets.push(...results.map(result => ({
                source: 'system_knowledge' as any,
                content: result.content,
                relevance: result.relevance,
                lastUpdated: result.lastUpdated
            })));
        }

        return snippets
            .sort((a, b) => b.relevance - a.relevance)
            .slice(0, 10);
    }

    private async queryRelevantSummaries(topics: string[], userId: number): Promise<any[]> {
        const queries: string[] = [];

        // Construir consultas seguras basadas en temas
        // Construir consultas seguras basadas en temas
        if (topics.includes('inventario')) {
            queries.push('SELECT name, stock_quantity, min_stock_level FROM products ORDER BY stock_quantity ASC LIMIT 10');
        }

        if (topics.includes('impuestos')) {
            queries.push('SELECT * FROM tax_summary_florida');
        }

        if (topics.includes('facturaci├│n')) {
            queries.push('SELECT * FROM v_facturas_reales');
        }

        if (topics.includes('contabilidad')) {
            queries.push('SELECT * FROM v_facturas_reales');
        }

        if (queries.length === 0) {
            return [];
        }

        try {
            const results: any[] = [];
            for (const query of queries) {
                const data = await this.dbService.executeSafeQuery(query, []);
                results.push(...data);
            }
            return results;
        } catch (error) {
            return [];
        }
    }

    private sanitizeForAPI(data: any[]): any[] {
        return data.map(item => {
            const sanitized = { ...item };
            const sensitiveFields = [
                'email', 'phone', 'tax_id', 'address', 'social_security',
                'credit_card', 'password', 'birth_date', 'full_name'
            ];

            sensitiveFields.forEach(field => {
                if (sanitized[field] !== undefined) delete sanitized[field];
            });

            return sanitized;
        });
    }

    private async getUserContext(userId: number) {
        return {
            userId,
            roles: ['admin'], // Simplificado para desarrollo
            allowedViews: AI_SECURITY_CONFIG.allowedTables
        };
    }

    private async getSystemState() {
        const health = await this.dbService.checkHealth();
        const backup = await this.dbService.getLastBackup();

        return {
            databaseStatus: health.healthy ? 'healthy' as any : 'offline' as any,
            lastBackup: backup?.timestamp || 'never',
            taxPeriodActive: new Date().getDate() <= 20
        };
    }

    private async getConversationHistory(userId: number) {
        try {
            const data = await this.dbService.executeSafeQuery(
                'SELECT query, response, timestamp FROM ai_conversations WHERE user_id = ? ORDER BY timestamp DESC LIMIT 5',
                [userId]
            );
            return data.map(row => ({
                query: row.query,
                response: row.response,
                timestamp: row.timestamp
            }));
        } catch (error) {
            console.warn('[ContextBuilder] Could not fetch history', error);
            return [];
        }
    }
}

import { db } from '@/database/simple-db';
import { FloridaTaxCalculator } from '../../modules/tax/FloridaTaxCalculator';

export class ContextManager {
    // SELECCIONAR DATOS RELEVANTES BASADO EN PREGUNTA
    static async getRelevantContext(question: string): Promise<any> {
        const questionType = this.analyzeQuestionType(question);

        switch (questionType) {
            case 'CLIENT_QUERY':
                return this.getClientContext(question);
            case 'INVOICE_QUERY':
                return this.getInvoiceContext(question);
            case 'TAX_QUERY':
                return this.getTaxContext(question);
            case 'INVENTORY_QUERY':
                return this.getInventoryContext(question);
            default:
                return this.getGeneralContext();
        }
    }

    private static analyzeQuestionType(question: string): string {
        const lower = question.toLowerCase();
        if (lower.includes('impuesto') || lower.includes('tax') || lower.includes('florida') || lower.includes('dr15') || lower.includes('dr-15')) return 'TAX_QUERY';
        if (lower.includes('cliente') || lower.includes('quien')) return 'CLIENT_QUERY';
        if (lower.includes('factura') || lower.includes('ventas') || lower.includes('ingreso')) return 'INVOICE_QUERY';
        if (lower.includes('inventario') || lower.includes('stock') || lower.includes('producto')) return 'INVENTORY_QUERY';
        return 'GENERAL_QUERY';
    }

    // OBTENER CONTEXTO ESPEC├ìFICO PARA IMPUESTOS FLORIDA
    private static async getTaxContext(question: string): Promise<any> {
        if (!db) return {};

        // Obtener tasas vigentes
        const rates = db.exec(`SELECT * FROM florida_tax_rates`);

        // Obtener el resumen de la vista optimizada
        const summary = db.exec(`SELECT * FROM tax_summary_florida`);

        // Calcular conformidad b├ísica (simulada aqu├¡ con datos reales)
        const compliance = FloridaTaxCalculator.validateCompliance(100, 7, 'Miami-Dade');

        return {
            taxRates: rates[0]?.values,
            taxTransactions: summary[0]?.values,
            complianceStatus: compliance ? 'OK' : 'CHECK_NEEDED',
            explanation: 'Tasas vigentes extra├¡das de florida_tax_rates y resumen de tax_summary_florida'
        };
    }

    private static async getClientContext(question: string): Promise<any> {
        if (!db) return {};
        const clients = db.exec(`SELECT * FROM v_clientes_reales`);
        const suppliers = db.exec(`SELECT * FROM v_proveedores_reales`);
        return {
            clientSummary: clients[0]?.values,
            supplierSummary: suppliers[0]?.values
        };
    }

    private static async getInvoiceContext(question: string): Promise<any> {
        if (!db) return {};
        const invoices = db.exec(`SELECT * FROM v_facturas_reales`);
        return { invoiceSummary: invoices[0]?.values };
    }

    private static async getInventoryContext(question: string): Promise<any> {
        if (!db) return {};
        const inventory = db.exec(`SELECT * FROM inventory_summary`);
        return { inventorySummary: inventory[0]?.values };
    }

    private static async getGeneralContext(): Promise<any> {
        if (!db) return {};
        const financial = db.exec(`SELECT * FROM financial_summary`);
        return { financialSnapshot: financial[0]?.values };
    }
}

import { EmbeddingsService } from '@/services/ai/EmbeddingsService';
import { SQLiteEngine } from '@/core/database/SQLiteEngine';
import floridaTaxRates from '@/knowledge/florida-tax-rates.json';
import { ProductionLogger } from '@/core/logging/ProductionLogger';

/**
 * FullDatabaseIndexer - Indexa TODOS los datos del sistema en RAG
 * 
 * Crea embeddings de:
 * - Todas las tablas
 * - Todos los registros
 * - Relaciones entre datos
 */
export class FullDatabaseIndexer {
    private db: SQLiteEngine;
    private embeddings: EmbeddingsService;
    private index: Map<string, IndexedRecord> = new Map();

    constructor(db: SQLiteEngine) {
        this.db = db;
        this.embeddings = new EmbeddingsService();
    }

    /**
     * Index entire database
     */
    async indexEverything(): Promise<void> {
        ProductionLogger.info('FullDatabaseIndexer', 'Starting full database indexing...');

        await this.embeddings.initialize();

        // Index all main tables
        await this.indexChartOfAccounts();
        await this.indexCustomers();
        await this.indexVendors();
        await this.indexProducts();
        await this.indexInvoices();
        await this.indexJournalEntries();
        await this.indexLedgerLines();
        await this.indexAssets();
        await this.indexEmployees();
        await this.indexSystemConfig();

        ProductionLogger.info('FullDatabaseIndexer', `Γ£à Indexed ${this.index.size} records`);
    }

    /**
     * Search across all indexed data
     */
    async search(query: string, limit: number = 10): Promise<SearchResult[]> {
        const queryEmbedding = await this.embeddings.embed(query);
        const results: SearchResult[] = [];

        // Calculate similarity for all indexed records
        for (const [id, record] of this.index.entries()) {
            const similarity = this.embeddings.cosineSimilarity(queryEmbedding, record.embedding);

            results.push({
                id,
                table: record.table,
                data: record.data,
                textRepresentation: record.text,
                similarity
            });
        }

        // Sort by similarity and return top results
        results.sort((a, b) => b.similarity - a.similarity);
        return results.slice(0, limit);
    }

    /**
     * Get context from search results
     */
    async getContextForQuery(query: string): Promise<string> {
        const results = await this.search(query, 5);

        if (results.length === 0) {
            return 'No relevant data found in system.';
        }

        const contextLines = results.map((r, idx) => {
            return `[${idx + 1}] ${r.table}: ${r.textRepresentation} (relevance: ${(r.similarity * 100).toFixed(1)}%)`;
        });

        return `Relevant data from your system:\n${contextLines.join('\n')}`;
    }

    // ==========================================
    // TABLE INDEXERS
    // ==========================================

    private async indexChartOfAccounts(): Promise<void> {
        const accounts = await this.db.select('SELECT * FROM chart_of_accounts');

        for (const account of accounts) {
            const text = `Account ${account.code}: ${account.name} (${account.type}, Normal Balance: ${account.normal_balance})`;
            await this.indexRecord('chart_of_accounts', account.code, account, text);
        }
    }

    private async indexCustomers(): Promise<void> {
        const customers = await this.db.select('SELECT * FROM customers');

        for (const customer of customers) {
            const text = `Customer: ${customer.business_name || customer.name}, Email: ${customer.email}, Phone: ${customer.phone}, County: ${customer.county}`;
            await this.indexRecord('customers', customer.id, customer, text);
        }
    }

    private async indexVendors(): Promise<void> {
        const vendors = await this.db.select('SELECT * FROM vendors');

        for (const vendor of vendors) {
            const text = `Vendor: ${vendor.business_name || vendor.name}, Email: ${vendor.email}, Type: ${vendor.type}`;
            await this.indexRecord('vendors', vendor.id, vendor, text);
        }
    }

    private async indexProducts(): Promise<void> {
        const products = await this.db.select('SELECT * FROM products');

        for (const product of products) {
            const text = `Product: ${product.name}, SKU: ${product.sku}, Price: $${product.price_cents / 100}, Category: ${product.category}`;
            await this.indexRecord('products', product.id, product, text);
        }
    }

    private async indexInvoices(): Promise<void> {
        const invoices = await this.db.select(`
            SELECT i.*, c.business_name as customer_name 
            FROM invoices i
            LEFT JOIN customers c ON i.customer_id = c.id
            LIMIT 1000
        `);

        for (const invoice of invoices) {
            const text = `Invoice #${invoice.invoice_number}: Customer ${invoice.customer_name}, Date: ${invoice.invoice_date}, Total: $${invoice.total / 100}, Status: ${invoice.status}`;
            await this.indexRecord('invoices', invoice.id, invoice, text);
        }
    }

    private async indexJournalEntries(): Promise<void> {
        const entries = await this.db.select(`
            SELECT * FROM journal_entries 
            WHERE status = 'POSTED'
            ORDER BY created_at DESC
            LIMIT 500
        `);

        for (const entry of entries) {
            const text = `Journal Entry: ${entry.description}, Date: ${entry.entry_date}, Type: ${entry.entry_type}, Reference: ${entry.reference_number}`;
            await this.indexRecord('journal_entries', entry.id, entry, text);
        }
    }

    private async indexLedgerLines(): Promise<void> {
        const lines = await this.db.select(`
            SELECT ll.*, coa.code as account_code, coa.name as account_name
            FROM ledger_lines ll
            JOIN chart_of_accounts coa ON ll.account_code = coa.code
            LIMIT 1000
        `);

        for (const line of lines) {
            const amount = line.amount_cents / 100;
            const type = line.line_type === 'DEBIT' ? 'Debit' : 'Credit';
            const text = `${type} ${line.account_code} ${line.account_name}: $${amount}`;
            await this.indexRecord('ledger_lines', line.id, line, text);
        }
    }

    private async indexAssets(): Promise<void> {
        try {
            const assets = await this.db.select('SELECT * FROM fixed_assets LIMIT 500');

            for (const asset of assets) {
                const text = `Asset: ${asset.name}, Cost: $${asset.cost_cents / 100}, Method: ${asset.depreciation_method}, Life: ${asset.useful_life_years} years`;
                await this.indexRecord('fixed_assets', asset.id, asset, text);
            }
        } catch (error) {
            // Table might not exist
            ProductionLogger.warn('FullDatabaseIndexer', 'fixed_assets table not found');
        }
    }

    private async indexEmployees(): Promise<void> {
        try {
            const employees = await this.db.select('SELECT * FROM employees');

            for (const employee of employees) {
                const text = `Employee: ${employee.first_name} ${employee.last_name}, Position: ${employee.position}, Salary: $${employee.salary_cents / 100}`;
                await this.indexRecord('employees', employee.id, employee, text);
            }
        } catch (error) {
            // Table might not exist
            ProductionLogger.warn('FullDatabaseIndexer', 'employees table not found');
        }
    }

    private async indexSystemConfig(): Promise<void> {
        const configs = await this.db.select('SELECT * FROM system_config');

        for (const config of configs) {
            const text = `System Config: ${config.key} = ${config.value}`;
            await this.indexRecord('system_config', config.key, config, text);
        }
    }

    // ==========================================
    // HELPER METHODS
    // ==========================================

    private async indexRecord(table: string, id: any, data: any, text: string): Promise<void> {
        const embedding = await this.embeddings.embed(text);

        const recordId = `${table}:${id}`;
        this.index.set(recordId, {
            table,
            id,
            data,
            text,
            embedding
        });
    }

    /**
     * Re-index specific table (for updates)
     */
    async reindexTable(tableName: string): Promise<void> {
        // Remove old entries for this table
        for (const [key, value] of this.index.entries()) {
            if (value.table === tableName) {
                this.index.delete(key);
            }
        }

        // Re-index
        switch (tableName) {
            case 'chart_of_accounts': await this.indexChartOfAccounts(); break;
            case 'customers': await this.indexCustomers(); break;
            case 'vendors': await this.indexVendors(); break;
            case 'products': await this.indexProducts(); break;
            case 'invoices': await this.indexInvoices(); break;
            case 'journal_entries': await this.indexJournalEntries(); break;
            // Add more as needed
        }

        ProductionLogger.info('FullDatabaseIndexer', `Re-indexed ${tableName}`);
    }

    /**
     * Get index stats
     */
    getStats(): IndexStats {
        const tableStats = new Map<string, number>();

        for (const record of this.index.values()) {
            const count = tableStats.get(record.table) || 0;
            tableStats.set(record.table, count + 1);
        }

        return {
            totalRecords: this.index.size,
            byTable: Object.fromEntries(tableStats)
        };
    }
}

// ==========================================
// TYPE DEFINITIONS
// ==========================================

interface IndexedRecord {
    table: string;
    id: any;
    data: any;
    text: string;
    embedding: number[];
}

interface SearchResult {
    id: string;
    table: string;
    data: any;
    textRepresentation: string;
    similarity: number;
}

interface IndexStats {
    totalRecords: number;
    byTable: Record<string, number>;
}

