import { db } from '@/database/simple-db';
import { IAnalysisService, AIResponse, DeepSeekAIResponse } from './types';

// Translation map for entities
const ENTITY_TRANSLATIONS: Record<string, { es: string, en: string, pluralEs: string, pluralEn: string }> = {
    'customer': { es: 'cliente', en: 'customer', pluralEs: 'clientes', pluralEn: 'customers' },
    'supplier': { es: 'proveedor', en: 'supplier', pluralEs: 'proveedores', pluralEn: 'suppliers' },
    'product': { es: 'producto', en: 'product', pluralEs: 'productos', pluralEn: 'products' },
    'invoice': { es: 'factura', en: 'invoice', pluralEs: 'facturas', pluralEn: 'invoices' },
    'asset': { es: 'activo', en: 'asset', pluralEs: 'activos', pluralEn: 'assets' },
    'expense': { es: 'gasto', en: 'expense', pluralEs: 'gastos', pluralEn: 'expenses' },
    'revenue': { es: 'ingreso', en: 'revenue', pluralEs: 'ingresos', pluralEn: 'revenues' },
    'account': { es: 'cuenta', en: 'account', pluralEs: 'cuentas', pluralEn: 'accounts' }
};

export class LocalAIService implements IAnalysisService {
    async analyzeFinancialHealth(): Promise<AIResponse> {
        return this.generateResponse("Financial analysis not implemented.");
    }

    async explainTaxCalculation(taxData: any): Promise<AIResponse> {
        return this.generateResponse("Tax calculation not implemented.");
    }

    async processQuery(question: string, userId: number = 1): Promise<DeepSeekAIResponse> {
        try {
            const result = await this.answer(question);
            return this.wrapResponse(question, result);
        } catch (error) {
            return this.wrapResponse(question, "Error processing query.");
        }
    }

    async generateNarrativeAnalysis(data: any[], context: { intent: string; entity: string; query: string; language?: 'es' | 'en' }): Promise<string> {
        const { intent, entity, language = 'es' } = context;

        let total = data.length;
        if (data.length === 1 && (data[0].count !== undefined || data[0].total !== undefined)) {
            total = Number(data[0].count || data[0].total || 0);
        }

        const trans = ENTITY_TRANSLATIONS[entity] || { es: entity, en: entity, pluralEs: entity + 's', pluralEn: entity + 's' };
        const entityName = total === 1 ? trans[language] : (language === 'es' ? trans.pluralEs : trans.pluralEn);

        if (total === 0) {
            return language === 'es'
                ? `He analizado tu solicitud sobre **${trans.pluralEs}**, pero actualmente no hay registros reales en la base de datos.`
                : `I have analyzed your request regarding **${trans.pluralEn}**, but there are currently no real records in the database.`;
        }

        let analysis = "";

        switch (intent) {
            case 'count_entities':
                const sampleNamesCount = data.slice(0, 3).map(d => d.name || d.business_name || d.description).filter(Boolean);
                if (language === 'es') {
                    const plural = total === 1 ? '' : 's';
                    analysis = `Actualmente el sistema cuenta con un total de **${total}** ${entityName} registrado${plural}. `;
                    if (sampleNamesCount.length > 0) analysis += `Entre ellos se encuentran **${sampleNamesCount.join(', ')}**. `;
                    analysis += `\n\n┬┐Deseas ver la lista completa?`;
                } else {
                    analysis = `The system currently has a total of **${total}** registered ${entityName}. `;
                    if (sampleNamesCount.length > 0) analysis += `These include **${sampleNamesCount.join(', ')}**. `;
                    analysis += `\n\nWould you like to see the full list?`;
                }
                break;

            case 'valuation':
                const valSum = data.length === 1 && (data[0].total !== undefined || data[0].count !== undefined)
                    ? Number(data[0].total || data[0].count)
                    : 0;
                if (language === 'es') {
                    analysis = `La valuaci├│n calculada para **${entityName}** es de **$${valSum.toLocaleString()}**. Este c├ílculo se basa en los precios y cantidades actuales.`;
                } else {
                    analysis = `The calculated valuation for **${entityName}** is **$${valSum.toLocaleString()}**. This calculation is based on current prices and quantities.`;
                }
                break;

            case 'find_best':
                const best = data[0];
                const nameBest = best.name || best.description || best.business_name || best.invoice_number || (language === 'es' ? "registro" : "record");
                const totalMetric = best.total_metric || best.total_spent || best.total_amount || best.amount || 0;
                if (language === 'es') {
                    analysis = `Tras analizar los registros, he identificado que el mejor resultado corresponde a **${nameBest}**. Registra un volumen de **$${Number(totalMetric).toLocaleString()}**.`;
                } else {
                    analysis = `After analyzing the records, I have identified that the best result corresponds to **${nameBest}**. It has a volume of **$${Number(totalMetric).toLocaleString()}**.`;
                }
                break;

            case 'sum_metrics':
                const sum = data.length === 1 && (data[0].total !== undefined || data[0].count !== undefined)
                    ? Number(data[0].total || data[0].count)
                    : data.reduce((acc, curr) => acc + (Number(curr.total) || Number(curr.amount) || Number(curr.total_amount) || 0), 0);
                if (language === 'es') {
                    analysis = `El an├ílisis de m├⌐tricas acumuladas para **${entityName}** arroja un total global de **$${sum.toLocaleString()}**.`;
                } else {
                    analysis = `The accumulated metrics analysis for **${entityName}** shows a global total of **$${sum.toLocaleString()}**.`;
                }
                break;

            default:
                if (language === 'es') {
                    analysis = `He encontrado **${total}** registros de ${entityName}. Los datos est├ín listos para tu revisi├│n detallada.`;
                } else {
                    analysis = `I found **${total}** records of ${entityName}. The data is ready for your detailed review.`;
                }
                break;
        }

        return analysis;
    }

    private async answer(question: string): Promise<string> {
        return `Processing: "${question}"`;
    }

    private wrapResponse(query: string, text: string): DeepSeekAIResponse {
        return {
            id: `local_${Date.now()}`,
            timestamp: new Date().toISOString(),
            query: query,
            response: {
                intent: 'DATA_ANALYSIS',
                information: text,
                action: 'Narrative Generated',
                explanation: 'Local narrative engine processed',
                considerations: 'Based on real database records'
            },
            rawResponse: text,
            contextUsed: { topics: [], dataPoints: 1, knowledgeSnippets: 0 },
            metadata: { model: 'Local-Narrative-Engine', tokensUsed: 0, processingTime: 0, fallbackUsed: false }
        };
    }

    private generateResponse(text: string): AIResponse {
        return {
            content: text,
            intent: 'N/A',
            information: text,
            action: 'N/A',
            explanation: text,
            considerations: 'N/A',
            metadata: { model: 'Local-Narrative', processingTime: 0, dataSource: 'N/A' }
        };
    }
}

import { SemanticQueryAnalyzer, QueryAnalysis } from './SemanticQueryAnalyzer';
import { IntelligentSQLGenerator } from './IntelligentSQLGenerator';
import { QuerySecurityMonitor } from './QuerySecurityMonitor';
import { AccountingKnowledgeBase } from './AccountingKnowledgeBase';
import { LocalAIService } from './LocalAIService';
import { EngineBridge } from '../../core/database/EngineBridge';

export interface AssistantResponse {
    success: boolean;
    content: string;
    data: any;
    metadata: {
        query: string;
        timestamp: string;
        intent: string;
        confidence: number;
        dataSource: string;
        processingTime: number;
        method?: string;
        language?: 'es' | 'en';
    };
    suggestions: string[];
    requiresAttention: boolean;
}

export class ModernConversationalAssistant {
    private analyzer: SemanticQueryAnalyzer | null = null;
    private sqlGenerator: IntelligentSQLGenerator | null = null;
    private securityMonitor: QuerySecurityMonitor;
    private knowledgeBase: AccountingKnowledgeBase;
    private localAI: LocalAIService;
    private isInitialized: boolean = false;

    constructor() {
        this.securityMonitor = new QuerySecurityMonitor();
        this.knowledgeBase = new AccountingKnowledgeBase();
        this.localAI = new LocalAIService();
    }

    async initialize() {
        if (this.isInitialized) return;
        try {
            this.analyzer = await SemanticQueryAnalyzer.getInstance();
            this.sqlGenerator = new IntelligentSQLGenerator(EngineBridge.getEngine());
            this.isInitialized = true;
            console.log("Γ£à ModernConversationalAssistant Initialized.");
        } catch (error) {
            console.error("ΓÜá∩╕Å Error initializing ModernConversationalAssistant:", error);
        }
    }

    async processQuery(userQuery: string, userId: number = 1): Promise<AssistantResponse> {
        const startTime = Date.now();

        try {
            if (!this.isInitialized) await this.initialize();

            const analyzer = this.analyzer || await SemanticQueryAnalyzer.getInstance();
            const analysis = await analyzer.analyzeQuery(userQuery);
            const lang = analysis.language;

            // 1. Emergency Fallback if confidence is zero
            if (analysis.confidence === 0 || (analysis.intent.key === 'UNKNOWN' && analysis.entity.key === 'UNKNOWN')) {
                return this.emergencyFallback(userQuery, startTime, lang);
            }

            // 2. Knowledge Path (EXPLAIN or HOW_TO)
            if (analysis.intent.key === 'EXPLAIN' || analysis.intent.key === 'HOW_TO') {
                return await this.handleKnowledgeQuery(userQuery, analysis, startTime);
            }

            // 3. Special mapping for verbs if entity is ambiguous
            if (analysis.entity.key === 'UNKNOWN' || analysis.entity.key === 'INVOICE' || analysis.entity.key === 'EXPENSE') {
                const lower = userQuery.toLowerCase();
                if (lower.match(/\b(vendi|venta|sold|sale)\b/)) {
                    analysis.entity.key = 'INVOICE';
                    if (analysis.intent.key === 'UNKNOWN') analysis.intent.key = 'SUM';
                } else if (lower.match(/\b(compre|compra|bought|purchase)\b/)) {
                    analysis.entity.key = 'EXPENSE';
                    if (analysis.intent.key === 'UNKNOWN') analysis.intent.key = 'SUM';
                }
            }

            // 4. Data Path
            if (analysis.entity.key !== 'UNKNOWN') {
                return await this.handleDataQuery(userQuery, analysis, startTime);
            }

            return await this.handleGeneralQuery(userQuery, analysis, startTime);

        } catch (error: any) {
            console.error('Γ¥î Critical error in processQuery:', error);
            return this.generateErrorResponse(userQuery, error, startTime);
        }
    }

    private async handleKnowledgeQuery(query: string, analysis: QueryAnalysis, startTime: number): Promise<AssistantResponse> {
        const lang = analysis.language;
        let content = "";

        if (analysis.intent.key === 'EXPLAIN') {
            const concept = AccountingKnowledgeBase.searchConcept(query, lang);
            if (concept) {
                const data = concept[lang];
                content = `≡ƒº« **${data.name}**\n\n${data.definition}\n\n**${lang === 'es' ? 'Ejemplo' : 'Example'}:** ${data.example || 'N/A'}`;
                if (data.florida_specific) {
                    content += `\n\n≡ƒî┤ **${lang === 'es' ? 'Nota para Florida' : 'Florida Note'}:** ${data.florida_specific}`;
                }
            }
        } else if (analysis.intent.key === 'HOW_TO') {
            const steps = AccountingKnowledgeBase.getProcedure(query, lang);
            if (steps) {
                const title = lang === 'es' ? 'Procedimiento' : 'Procedure';
                content = `≡ƒôû **${title}:**\n\n` + steps.map((s, i) => `${i + 1}. ${s}`).join('\n');
            }
        }

        if (!content) return await this.handleGeneralQuery(query, analysis, startTime);

        return {
            success: true,
            content,
            data: null,
            metadata: {
                query,
                timestamp: new Date().toISOString(),
                intent: analysis.intent.key,
                confidence: analysis.confidence,
                dataSource: 'AccountingKnowledgeBase',
                processingTime: Date.now() - startTime,
                language: lang
            },
            suggestions: lang === 'es'
                ? ["┬┐Puedes darme m├ís detalles?", "Ver reportes relacionados"]
                : ["Can you give me more details?", "View related reports"],
            requiresAttention: false
        };
    }

    private async handleDataQuery(query: string, analysis: QueryAnalysis, startTime: number): Promise<AssistantResponse> {
        const lang = analysis.language;
        try {
            if (!this.sqlGenerator) this.sqlGenerator = new IntelligentSQLGenerator(EngineBridge.getEngine());
            const sqlResult = await this.sqlGenerator.generateSQL(analysis);
            const security = QuerySecurityMonitor.validateQuery(sqlResult.sql);

            if (!security.isValid) {
                return this.generateErrorResponse(query, new Error(`Security: ${security.reason}`), startTime, lang);
            }

            const data = await this.executeRawQuery(sqlResult.sql);
            const narrative = await this.localAI.generateNarrativeAnalysis(data, {
                intent: analysis.intent.key === 'SUM' ? 'sum_metrics' :
                    analysis.intent.key === 'COUNT' ? 'count_entities' :
                        analysis.intent.key === 'FIND_MAX' ? 'find_best' : 'default',
                entity: analysis.entity.key.toLowerCase(),
                query: query,
                language: lang
            });

            return {
                success: true,
                content: narrative,
                data: data,
                metadata: {
                    query,
                    timestamp: new Date().toISOString(),
                    intent: analysis.intent.key,
                    confidence: analysis.confidence,
                    dataSource: 'Database',
                    processingTime: Date.now() - startTime,
                    language: lang
                },
                suggestions: lang === 'es'
                    ? ["Ver tabla de datos", "Exportar a Excel"]
                    : ["View data table", "Export to Excel"],
                requiresAttention: false
            };
        } catch (e: any) {
            return this.handleGeneralQuery(query, analysis, startTime);
        }
    }

    private async handleGeneralQuery(query: string, analysis: QueryAnalysis, startTime: number): Promise<AssistantResponse> {
        const lang = analysis.language;
        const localRes = await this.localAI.processQuery(query);
        return {
            success: true,
            content: localRes.response.information,
            data: null,
            metadata: {
                query,
                timestamp: localRes.timestamp,
                intent: 'GENERAL_AI',
                confidence: analysis.confidence,
                dataSource: localRes.metadata.model || 'LocalAI',
                processingTime: Date.now() - startTime,
                language: lang
            },
            suggestions: lang === 'es'
                ? ["┬┐Qu├⌐ m├ís puedes hacer?", "Ayuda del sistema"]
                : ["What else can you do?", "System help"],
            requiresAttention: false
        };
    }

    private async executeRawQuery(query: string): Promise<any[]> {
        const { db } = await import('../../database/simple-db');
        if (!db) return [];
        try {
            const result = db.exec(query);
            if (!result || result.length === 0 || !result[0].values) return [];
            const columns = result[0].columns;
            const rows = result[0].values;
            return rows.map((row: any[]) => {
                const obj: any = {};
                columns.forEach((col: string, index: number) => {
                    obj[col] = row[index];
                });
                return obj;
            });
        } catch (e) {
            return [];
        }
    }

