import { DatabaseService } from '../database/DatabaseService';
import { DeepSeekAIResponse } from './types';

export type QueryIntentType = 'CUSTOMER_COUNT' | 'CUSTOMER_RANKING' | 'TOP_SUPPLIER' | 'INVOICE_SUMMARY' | 'TOP_PRODUCT' | 'GENERAL_QUERY';

export interface QueryIntent {
    type: QueryIntentType;
    priority: 'HIGH' | 'MEDIUM' | 'LOW';
}

export class NaturalLanguageQueryProcessor {
    private static dbService = DatabaseService.getInstance();

    private static intentMap: Record<QueryIntentType, string> = {
        'CUSTOMER_COUNT': 'v_clientes_reales',
        'CUSTOMER_RANKING': 'v_clientes_reales',
        'TOP_SUPPLIER': 'v_proveedores_reales',
        'INVOICE_SUMMARY': 'v_facturas_reales',
        'TOP_PRODUCT': 'v_facturas_reales', // Fallback temporal
        'GENERAL_QUERY': 'v_facturas_reales' // Fallback seguro
    };

    static analyzeIntent(question: string): QueryIntent {
        const lowerQ = question.toLowerCase();

        if (lowerQ.includes('cliente') && (lowerQ.includes('cuanto') || lowerQ.includes('cu├ínto') || lowerQ.includes('cuantos') || lowerQ.includes('cu├íntos') || lowerQ.includes('cantidad'))) {
            return { type: 'CUSTOMER_COUNT', priority: 'HIGH' };
        }
        if (lowerQ.includes('cliente') && (lowerQ.includes('ranking') || lowerQ.includes('mejor') || lowerQ.includes('importante'))) {
            return { type: 'CUSTOMER_RANKING', priority: 'HIGH' };
        }
        if (lowerQ.includes('proveedor') && (lowerQ.includes('mayor') || lowerQ.includes('mejor') || lowerQ.includes('principal'))) {
            return { type: 'TOP_SUPPLIER', priority: 'HIGH' };
        }
        if (lowerQ.includes('factura') && (lowerQ.includes('compra') || lowerQ.includes('venta') || lowerQ.includes('resumen'))) {
            return { type: 'INVOICE_SUMMARY', priority: 'MEDIUM' };
        }
        if (lowerQ.includes('articulo') || lowerQ.includes('art├¡culo') || lowerQ.includes('producto')) {
            if (lowerQ.includes('mas') || lowerQ.includes('m├ís') || lowerQ.includes('vendido')) {
                return { type: 'TOP_PRODUCT', priority: 'MEDIUM' };
            }
        }

        return { type: 'GENERAL_QUERY', priority: 'LOW' };
    }

    static async getRealData(intent: QueryIntent): Promise<any[]> {
        const view = this.intentMap[intent.type];
        try {
            return await this.dbService.executeSafeQuery(`SELECT * FROM ${view} LIMIT 10`);
        } catch (error) {
            console.warn(`[QueryProcessor] Could not fetch data for view ${view}`, error);
            return [];
        }
    }
}

import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { SchemaContext, TableMetadata, RelationshipMetadata } from '../../types/ai-context';
import { ProductionLogger } from '../../core/logging/ProductionLogger';

/**
 * SchemaCrawler - Fase 1 del DAC (Truth Discovery)
 * 
 * Este servicio se encarga de interrogar a la base de datos real para generar
 * un contexto din├ímico que la IA puede consumir.
 */
export class SchemaCrawler {
    private db: SQLiteEngine;

    constructor(db: SQLiteEngine) {
        this.db = db;
    }

    /**
     * Genera el contexto completo de la base de datos
     */
    public async crawl(): Promise<SchemaContext> {
        ProductionLogger.info('SchemaCrawler', 'Starting schema crawl...');
        const startTime = Date.now();

        try {
            // 1. Obtener lista de tablas (excluyendo tablas de sistema de SQLite)
            const tablesRes = await this.db.select(`
                SELECT name FROM sqlite_master 
                WHERE type='table' AND name NOT LIKE 'sqlite_%'
            `);
            const tableNames = tablesRes.map(t => t.name as string);

            const tables: TableMetadata[] = [];
            const relationships: RelationshipMetadata[] = [];

            for (const tableName of tableNames) {
                // 2. Obtener metadatos de columnas
                const columnsRes = await this.db.select(`PRAGMA table_info(${tableName})`);
                const columns = columnsRes.map(c => ({
                    name: c.name as string,
                    type: c.type as string,
                    notNull: c.notnull === 1,
                    pk: c.pk === 1,
                    defaultValue: c.dflt_value
                }));

                // 3. Obtener conteo de filas
                const countRes = await this.db.select(`SELECT COUNT(*) as count FROM ${tableName}`);
                const rowCount = countRes[0]?.count || 0;

                // 4. Identificar entidad de negocio (Mapeo heur├¡stico inicial)
                const businessEntity = this.inferBusinessEntity(tableName);

                tables.push({
                    name: tableName,
                    columns,
                    rowCount,
                    businessEntity
                });

                // 5. Obtener claves for├íneas para relaciones
                const fkRes = await this.db.select(`PRAGMA foreign_key_list(${tableName})`);
                for (const fk of fkRes) {
                    relationships.push({
                        fromTable: tableName,
                        fromColumn: fk.from as string,
                        toTable: fk.table as string,
                        toColumn: fk.to as string
                    });
                }
            }

            // 6. Obtener Logic Clock actual para frescura de datos
            let currentLogicClock = 0;
            try {
                const logicClockRes = await this.db.select("SELECT MAX(logic_clock) as max_clock FROM journal_entries");
                currentLogicClock = logicClockRes[0]?.max_clock || 0;
            } catch (e) {
                // Columna podr├¡a no existir si la migraci├│n 008 a├║n no se ha ejecutado
                ProductionLogger.debug('SchemaCrawler', 'Columna logic_clock no encontrada, usando valor por defecto 0');
            }

            const context: SchemaContext = {
                version: '1.0.0-dynamic',
                generatedAt: new Date().toISOString(),
                tables,
                relationships,
                stats: {
                    totalTables: tables.length,
                    logicClock: currentLogicClock
                }
            };

            ProductionLogger.info('SchemaCrawler', `Crawl completed in ${Date.now() - startTime}ms`, {
                tablesFound: tables.length,
                relationshipsFound: relationships.length
            });

            return context;

        } catch (error) {
            ProductionLogger.error('SchemaCrawler', 'Failed to crawl schema', error as Error);
            throw error;
        }
    }

    /**
     * Infiere la entidad de negocio bas├índose en el nombre de la tabla
     */
    private inferBusinessEntity(tableName: string): string {
        const mappings: Record<string, string> = {
            'customers': 'CUSTOMER',
            'suppliers': 'SUPPLIER',
            'products': 'PRODUCT',
            'invoices': 'INVOICE',
            'bills': 'EXPENSE',
            'chart_of_accounts': 'ACCOUNT',
            'fixed_assets': 'ASSET',
            'journal_entries': 'JOURNAL',
            'florida_tax_rates': 'TAX_CONFIG',
            'tax_transactions': 'TAX_LEDGER'
        };
        return mappings[tableName] || 'UNKNOWN';
    }

    /**
     * Guarda el contexto en la base de datos para persistencia
     */
    public async persistContext(context: SchemaContext): Promise<void> {
        const json = JSON.stringify(context);
        await this.db.run(`
            INSERT OR REPLACE INTO system_config (key, value, updated_at) 
            VALUES ('ai_schema_context', ?, CURRENT_TIMESTAMP)
        `, [json]);

        // Generar y persistir resumen legible (Fase 5 DAC)
        const summaryMd = this.generateMarkdownSummary(context);
        await this.db.run(`
            INSERT OR REPLACE INTO system_config (key, value, updated_at) 
            VALUES ('ai_schema_summary_md', ?, CURRENT_TIMESTAMP)
        `, [summaryMd]);

        ProductionLogger.info('SchemaCrawler', 'Schema context and Markdown summary persisted');
    }

    /**
     * Genera un resumen en Markdown del esquema actual
     */
    private generateMarkdownSummary(context: SchemaContext): string {
        const lines: string[] = [
            `# ≡ƒºá AI Database Dictionary (Dynamic)`,
            `*Generated at: ${context.generatedAt}*`,
            `*Logic Clock: ${context.stats.logicClock}*`,
            '',
            '## ≡ƒôè Resumen de Tablas',
            '| Entidad | Tabla F├¡sica | Columnas | Registros |',
            '| :--- | :--- | :--- | :--- |'
        ];

        context.tables.forEach(t => {
            lines.push(`| ${t.businessEntity} | \`${t.name}\` | ${t.columns.length} | ${t.rowCount} |`);
        });

        lines.push('', '## ≡ƒôæ Detalle de Estructura');

        context.tables.forEach(t => {
            lines.push(`### ≡ƒö╣ ${t.name} (${t.businessEntity})`);
            lines.push('| Columna | Tipo | PK | Not Null | Default |');
            lines.push('| :--- | :--- | :--- | :--- | :--- |');
            t.columns.forEach(c => {
                lines.push(`| \`${c.name}\` | ${c.type} | ${c.pk ? 'Γ£à' : ''} | ${c.notNull ? 'Γ£à' : ''} | ${c.defaultValue || '-'} |`);
            });
            lines.push('');
        });

        lines.push('', '## ≡ƒöù Relaciones detectadas');
        context.relationships.forEach(r => {
            lines.push(`- \`${r.fromTable}.${r.fromColumn}\` Γ₧í∩╕Å \`${r.toTable}.${r.toColumn}\``);
        });

        return lines.join('\n');
    }
}

// Lazy import with error handling
let pipelineModule: any = null;
let pipelineLoadError: Error | null = null;

async function loadPipeline() {
    if (pipelineModule) return pipelineModule;
    if (pipelineLoadError) throw pipelineLoadError;
    
    try {
        const module = await import('@xenova/transformers');
        pipelineModule = module.pipeline;
        return pipelineModule;
    } catch (error) {
        pipelineLoadError = error as Error;
        throw error;
    }
}

export interface SemanticMatch {
    key: string;
    score: number;
}

export interface QueryAnalysis {
    intent: SemanticMatch;
    entity: SemanticMatch;
    parameters: Record<string, any>;
    confidence: number;
    language: 'es' | 'en';
}

export class SemanticQueryAnalyzer {
    private static instance: SemanticQueryAnalyzer;
    private embedder: any = null;
    private isInitializing: boolean = false;
    private modelLoaded: boolean = false;
    private initializationFailed: boolean = false;

    private readonly INTENT_EMBEDDINGS: Record<string, number[][]> = {};
    private readonly ENTITY_EMBEDDINGS: Record<string, number[][]> = {};

    private readonly INTENT_SEEDS: Record<string, string[]> = {
        COUNT: ["cuantos", "cu├íntos", "cantidad de", "n├║mero de", "contar", "how many", "count", "number of"],
        SUM: ["cu├ínto es", "cuanto es", "suma total", "monto", "total de dinero", "valorizado", "how much", "total amount", "sum of"],
        FIND_MAX: ["m├ís alto", "m├íximo", "mejor", "superior", "highest", "best", "top", "maximum"],
        FIND_MIN: ["m├ís bajo", "m├¡nimo", "peor", "inferior", "lowest", "worst", "minimum"],
        EXPLAIN: ["qu├⌐ es", "que es", "que significa", "definici├│n", "concepto", "explicar", "explicame", "what is", "definition", "meaning", "concept", "explain"],
        HOW_TO: ["c├│mo", "como", "pasos para", "procedimiento", "gu├¡a", "instrucciones", "how do I", "how to", "steps for", "procedure"],
        LIST: ["mostrar", "ver", "listar", "lista de", "cat├ílogo", "show", "view", "list", "catalog"]
    };

    private readonly ENTITY_SEEDS: Record<string, string[]> = {
        CUSTOMER: ["clientes", "cliente", "compradores", "customers", "client", "buyer"],
        SUPPLIER: ["proveedores", "proveedor", "vendedores", "vendors", "supplier", "distributor"],
        PRODUCT: ["productos", "inventario", "stock", "mercanc├¡as", "art├¡culos", "products", "inventory", "items"],
        INVOICE: ["facturas", "recibos", "invoices", "ventas", "invoice", "sale", "receipt"],
        ACCOUNT: ["cuentas contables", "plan de cuentas", "ledger", "asientos", "accounts", "chart of accounts"],
        ASSET: ["activos", "bienes", "propiedades", "assets", "property"],
        EXPENSE: ["gastos", "costos", "expenses", "egresos", "expense", "costs"],
        REVENUE: ["ingresos", "ventas totales", "ganancias", "revenue", "income", "earnings"]
    };

    private readonly TYPO_MAP: Record<string, string> = {
        'cuanl': 'cual',
        'cuanlto': 'cuanto',
        'cliennte': 'cliente',
        'proveedorr': 'proveedor',
        'vendi': 'vend├¡',
        'compre': 'compr├⌐',
        'factrua': 'factura'
    };

    private constructor() { }

    static async getInstance(): Promise<SemanticQueryAnalyzer> {
        if (!this.instance) {
            this.instance = new SemanticQueryAnalyzer();
            // Don't await - let it initialize in background
            this.instance.initialize().catch(() => {
                // Silently fail - will use fallback mode
            });
        }
        return this.instance;
    }

    async initialize() {
        if (this.modelLoaded || this.isInitializing || this.initializationFailed) return;
        this.isInitializing = true;
        try {
            // Try to load the pipeline function first
            const pipeline = await loadPipeline();
            
            // Try to load the model with timeout
            const timeoutPromise = new Promise((_, reject) => 
                setTimeout(() => reject(new Error('Model loading timeout')), 10000)
            );
            
            const modelPromise = pipeline('feature-extraction', 'Xenova/paraphrase-multilingual-MiniLM-L12-v2', {
                quantized: true
            });
            
            this.embedder = await Promise.race([modelPromise, timeoutPromise]);
            this.modelLoaded = true;
            
            for (const [key, seeds] of Object.entries(this.INTENT_SEEDS)) {
                this.INTENT_EMBEDDINGS[key] = await Promise.all(seeds.map(s => this.getEmbedding(s)));
            }
            for (const [key, seeds] of Object.entries(this.ENTITY_SEEDS)) {
                this.ENTITY_EMBEDDINGS[key] = await Promise.all(seeds.map(s => this.getEmbedding(s)));
            }
            console.log('Γ£à AI model loaded successfully');
        } catch (error) {
            console.warn('ΓÜá∩╕Å AI model loading failed, using keyword-based fallback mode');
            this.modelLoaded = false;
            this.embedder = null;
            this.initializationFailed = true;
        } finally {
            this.isInitializing = false;
        }
    }

    public async getEmbedding(text: string): Promise<number[]> {
        if (!this.modelLoaded || !this.embedder) return new Array(384).fill(0);
        try {
            const output = await this.embedder(text, { pooling: 'mean', normalize: true });
            return Array.from(output.data);
        } catch (error) {
            return new Array(384).fill(0);
        }
    }

    async analyzeQuery(query: string): Promise<QueryAnalysis> {
        const language = this.detectLanguage(query);
        const normalizedInput = this.normalizeText(query);

        let processedQuery = normalizedInput.toLowerCase().trim();
        Object.entries(this.TYPO_MAP).forEach(([typo, correction]) => {
            processedQuery = processedQuery.replace(new RegExp(`\\b${typo}\\b`, 'g'), correction);
        });

        // PRIORIDAD 1: Keywords claras para Knowledge Base
        const lower = processedQuery;
        if (/\b(qu[├⌐|e] es|significa|definici[├│|o]n|expl[├¡|i]ca|what is|meaning|definition|explain)\b/i.test(lower)) {
            const fallback = this.analyzeQueryFallback(processedQuery, language);
            if (fallback.intent.key === 'EXPLAIN') return fallback;
        }
        if (/\b(c[├│|o]mo|pasos|procedimiento|instrucciones|gu[├¡|i]a|how to|steps|procedure|guide)\b/i.test(lower)) {
            const fallback = this.analyzeQueryFallback(processedQuery, language);
            if (fallback.intent.key === 'HOW_TO') return fallback;
        }

        if (!this.modelLoaded) return this.analyzeQueryFallback(processedQuery, language);

        // PRIORIDAD 2: Sem├íntica con embeddings
        const queryEmbedding = await this.getEmbedding(processedQuery);
        const intent = this.findBestMatch(queryEmbedding, this.INTENT_EMBEDDINGS, 0.4);
        const entity = this.findBestMatch(queryEmbedding, this.ENTITY_EMBEDDINGS, 0.4);

        if (intent.key === 'UNKNOWN' || entity.key === 'UNKNOWN') {
            const fallbackRes = this.analyzeQueryFallback(processedQuery, language);
            if (fallbackRes.intent.key !== 'UNKNOWN' || fallbackRes.entity.key !== 'UNKNOWN') {
                return fallbackRes;
            }
        }

        return {
            intent,
            entity,
            parameters: this.extractParameters(processedQuery),
            confidence: intent.score * entity.score,
            language
        };
    }

    private detectLanguage(text: string): 'es' | 'en' {
        const lowerText = text.toLowerCase();
        const normalizedText = this.normalizeText(lowerText);

        // 1. Indicadores fuertes de ESPA├æOL
        const spanishStrong = [
            /\b(cliente|proveedor|factura|gasto|ingreso|producto|asiento|cuenta|banco|activo|pasivo|patrimonio|impuesto|procedimiento|conciliacion)s?\b/i,
            /\b(cuanto|cuanto|que|como|donde|cuando|cual|cuales|quien|quienes)\b/i,
            /\b(tengo|tienes|tenemos|hay|vendi|compre|pague|recibi|hacer|registrar)\b/i,
            /[├í├⌐├¡├│├║├▒]/i
        ];

        // 2. Indicadores fuertes de INGL├ëS
        const englishStrong = [
            /\b(customer|supplier|invoice|expense|revenue|product|entry|account|bank|asset|liability|equity|tax|procedure|reconciliation)s?\b/i,
            /\b(how|what|where|when|why|many|much|which|who)\b/i,
            /\b(have|has|do|does|did|am|is|are|was|were|sold|bought|paid|received|make|register)\b/i,
            /\b(i|you|we|they|it|my|your|our|their)\b/i,
            /'s|'re|'ll|'ve|'d/i
        ];

        // 3. Contar coincidencias
        const spanishMatches = spanishStrong.filter(regex => regex.test(normalizedText)).length;
        const englishMatches = englishStrong.filter(regex => regex.test(lowerText)).length;

        if (spanishMatches > englishMatches) return 'es';
        if (englishMatches > spanishMatches) return 'en';

        // 4. Heur├¡stica de palabras de estructura (Common Words)
        const esCommonWords = ['el', 'la', 'los', 'las', 'de', 'y', 'en', 'con', 'por', 'un', 'una', 'para', 'que', 'su', 'mi'];
        const enCommonWords = ['the', 'a', 'an', 'and', 'in', 'with', 'for', 'to', 'of', 'on', 'at', 'that', 'it', 'is', 'my'];

        const words = normalizedText.split(/\s+/);
        const rawWords = lowerText.split(/\s+/);

        const esCommonCount = words.filter(w => esCommonWords.includes(w)).length;
        const enCommonCount = rawWords.filter(w => enCommonWords.includes(w)).length;

        if (esCommonCount > enCommonCount) return 'es';
        if (enCommonCount > esCommonCount) return 'en';

        // 5. Desempate final
        return (/[├í├⌐├¡├│├║├▒]/i.test(text)) ? 'es' : (englishMatches > 0 ? 'en' : 'es');
    }

    private normalizeText(text: string): string {
        return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    }

    private analyzeQueryFallback(query: string, language: 'es' | 'en' = 'es'): QueryAnalysis {
        const lower = query.toLowerCase().trim();
        let intentKey = 'UNKNOWN';
        let entityKey = 'UNKNOWN';

        // Intents
        if (/\b(cu[├í|a]ntos|contar|n[├║|u]mero|cantidad|how many|count)\b/i.test(lower)) intentKey = 'COUNT';
        else if (/\b(cu[├í|a]nto|suma|monto|total|valor|how much|sum)\b/i.test(lower)) intentKey = 'SUM';
        else if (/\b(qu[├⌐|e] es|significa|concepto|definici[├│|o]n|expl[├¡|i]ca|what is|meaning|definition|explain)\b/i.test(lower)) intentKey = 'EXPLAIN';
        else if (/\b(c[├│|o]mo|pasos|procedimiento|instrucciones|gu[├¡|i]a|how to|procedure|steps)\b/i.test(lower)) intentKey = 'HOW_TO';
        else if (/\b(mejor|m[├í|a]ximo|m[├í|a]s alto|superior|best|highest|maximum)\b/i.test(lower)) intentKey = 'FIND_MAX';
        else if (/\b(peor|m[├¡|i]nimo|m[├í|a]s bajo|inferior|worst|lowest|minimum)\b/i.test(lower)) intentKey = 'FIND_MIN';

        // Entities
        if (/\b(cliente(s)?|customer(s)?|client(s)?)\b/i.test(lower)) entityKey = 'CUSTOMER';
        else if (/\b(proveedor(es)?|vendor(s)?|supplier(s)?)\b/i.test(lower)) entityKey = 'SUPPLIER';
        else if (/\b(producto(s)?|inventario|stock|art[├¡|i]culo(s)?|product(s)?|item(s)?)\b/i.test(lower)) entityKey = 'PRODUCT';
        else if (/\b(factura(s)?|venta(s)?|invoice(s)?|sale(s)?)\b/i.test(lower)) entityKey = 'INVOICE';
        else if (/\b(activo(s)?|asset(s)?|bien(es)?)\b/i.test(lower)) entityKey = 'ASSET';
        else if (/\b(pasivo(s)?|liability|deuda(s)?|liabilities)\b/i.test(lower)) entityKey = 'LIABILITY';
        else if (/\b(patrimonio|capital|equity)\b/i.test(lower)) entityKey = 'EQUITY';
        else if (/\b(impuesto(s)?|tax(es)?|iva|tributo)\b/i.test(lower)) entityKey = 'TAX';
        else if (/\b(banco(s)?|bank(s)?|cuenta bancaria|bank account)\b/i.test(lower)) entityKey = 'BANK_ACCOUNT';
        else if (/\b(gasto(s)?|expense(s)?|egreso(s)?|cost(s)?)\b/i.test(lower)) entityKey = 'EXPENSE';
        else if (/\b(ingreso(s)?|revenue|ganancia(s)?|income|earnings)\b/i.test(lower)) entityKey = 'REVENUE';
        else if (/\b(cuenta(s)?|ledger|asiento(s)?|account(s)?)\b/i.test(lower)) entityKey = 'ACCOUNT';

        const hasKeywords = intentKey !== 'UNKNOWN' || entityKey !== 'UNKNOWN';

        return {
            intent: { key: intentKey, score: intentKey !== 'UNKNOWN' ? 0.95 : 0 },
            entity: { key: entityKey, score: entityKey !== 'UNKNOWN' ? 0.95 : 0 },
            parameters: this.extractParameters(query),
            confidence: hasKeywords ? 0.9 : 0,
            language
        };
    }

    private findBestMatch(queryEmbedding: number[], targetGroups: Record<string, number[][]>, threshold: number): SemanticMatch {
        let bestMatch = { key: 'UNKNOWN', score: 0 };
        for (const [key, embeddings] of Object.entries(targetGroups)) {
            for (const targetEmbedding of embeddings) {
                const similarity = this.cosineSimilarity(queryEmbedding, targetEmbedding);
                if (similarity > bestMatch.score) {
                    bestMatch = { key, score: similarity };
                }
            }
        }
        return bestMatch.score > threshold ? bestMatch : { key: 'UNKNOWN', score: 0 };
    }

    private cosineSimilarity(a: number[], b: number[]): number {
        let dotProduct = 0;
        let mA = 0, mB = 0;
        for (let i = 0; i < a.length; i++) {
            dotProduct += a[i] * b[i];
            mA += a[i] * a[i];
            mB += b[i] * b[i];
        }
        const denom = Math.sqrt(mA) * Math.sqrt(mB);
        return denom === 0 ? 0 : dotProduct / denom;
    }

    private extractParameters(query: string): Record<string, any> {
        const params: Record<string, any> = {};
        const lowerQuery = query.toLowerCase();
        const numbers = lowerQuery.match(/\d+/g);
        if (numbers) params.numeric_value = parseFloat(numbers[0]);
        if (lowerQuery.includes('miami')) params.county = 'Miami-Dade';
        if (lowerQuery.includes('broward')) params.county = 'Broward';
        return params;
    }
}

import { SchemaContext, TableMetadata } from '../../types/ai-context';
import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { ProductionLogger } from '../../core/logging/ProductionLogger';

/**
 * SemanticQueryResolver - Fase 2 del DAC (Semantic Bridge)
 * 
 * Este servicio resuelve entidades sem├ínticas (ej: 'CUSTOMER') a objetos reales
 * de la base de datos (tablas, columnas) usando el contexto din├ímico.
 */
export class SemanticQueryResolver {
    private context: SchemaContext | null = null;
    private db: SQLiteEngine;

    constructor(db: SQLiteEngine) {
        this.db = db;
    }

    /**
     * Carga el contexto desde la base de datos
     */
    public async loadContext(): Promise<SchemaContext | null> {
        const result = await this.db.select(`
            SELECT value FROM system_config WHERE key = 'ai_schema_context'
        `);
        if (result.length > 0 && result[0].value) {
            try {
                this.context = JSON.parse(result[0].value as string);
                ProductionLogger.info('SemanticQueryResolver', 'Context loaded successfully');
                return this.context;
            } catch (e) {
                ProductionLogger.error('SemanticQueryResolver', 'Failed to parse context JSON', e as Error);
            }
        } else {
            ProductionLogger.warn('SemanticQueryResolver', 'No AI context found in system_config');
        }
        return null;
    }

    /**
     * Establece el contexto manualmente (para compartir instancia)
     */
    public setContext(context: SchemaContext): void {
        this.context = context;
        ProductionLogger.info('SemanticQueryResolver', 'Context set manually');
    }

    /**
     * Resuelve una entidad sem├íntica a una tabla real
     */
    public resolveTable(entityKey: string): TableMetadata | null {
        if (!this.context) return null;

        // Buscar coincidencia exacta por businessEntity
        const table = this.context.tables.find(t => t.businessEntity === entityKey);
        if (table) return table;

        // Fallback: b├║squeda por nombre de tabla similar (heur├¡stica)
        const commonNames: Record<string, string[]> = {
            'CUSTOMER': ['customers', 'clients', 'clientes'],
            'SUPPLIER': ['suppliers', 'vendors', 'proveedores'],
            'INVOICE': ['invoices', 'sales', 'facturas'],
            'EXPENSE': ['bills', 'expenses', 'gastos'],
            'PRODUCT': ['products', 'items', 'productos', 'inventory']
        };

        const candidates = commonNames[entityKey] || [];
        return this.context.tables.find(t => candidates.includes(t.name.toLowerCase())) || null;
    }

    /**
     * Resuelve la columna principal de una tabla (ej: la que tiene el monto o nombre)
     */
    public resolvePrimaryColumn(tableName: string, purpose: 'amount' | 'name' | 'id'): string | null {
        if (!this.context) return null;
        const table = this.context.tables.find(t => t.name === tableName);
        if (!table) return null;

        const cols = table.columns.map(c => c.name.toLowerCase());

        if (purpose === 'amount') {
            const amountHints = ['total_amount', 'amount', 'total', 'subtotal', 'balance', 'price', 'debit_amount'];
            return table.columns.find(c => amountHints.includes(c.name.toLowerCase()))?.name || null;
        }

        if (purpose === 'name') {
            const nameHints = ['name', 'description', 'title', 'label'];
            return table.columns.find(c => nameHints.includes(c.name.toLowerCase()))?.name || null;
        }

        if (purpose === 'id') {
            return table.columns.find(c => c.pk)?.name || 'id';
        }

        return null;
    }

    /**
     * Obtiene el contexto actual
     */
    public getContext(): SchemaContext | null {
        return this.context;
    }
}

