}

export interface MedicareResult {
  medicare: number;
  medicareAdditional: number;
  totalMedicare: number;
}

export interface FederalTaxResult {
  federalIncomeTax: number;
  taxableIncome: number;
  annualTax: number;
}

export interface TaxBreakdown {
  socialSecurity: {
    rate: number;
    base: number;
    amount: number;
  };
  medicare: {
    rate: number;
    base: number;
    amount: number;
  };
  medicareAdditional: {
    rate: number;
