import { SQLiteEngine } from '../../core/database/SQLiteEngine';
import { AuditChainService } from '../../core/audit/AuditChainService';
import { FloridaTaxEngine, FloridaTaxRate } from '../accounting/FloridaTaxEngine';
import { JournalManager } from '../accounting/JournalManager';
import { InventoryManager } from '../../modules/inventory/InventoryManager'; // Fixed Path
import Big from 'big.js';

interface SaleTransaction {
    customerId: number;
    lines: {
        productId: number;
        description: string;
        quantity: number;
        unitPrice: number;
        taxable: boolean;
        cost: number;
    }[];
    county: string;
    userId: number;
}

export class TransactionManager {
    private engine: SQLiteEngine;
    private auditService: AuditChainService;
    private taxEngine: FloridaTaxEngine;
    private journalManager: JournalManager;
    private inventoryManager: InventoryManager; // New

    constructor(engine: SQLiteEngine) {
        this.engine = engine;
        this.auditService = new AuditChainService(engine);
        this.inventoryManager = new InventoryManager(engine);
        this.taxEngine = new FloridaTaxEngine(engine);
        this.journalManager = new JournalManager(engine);
    }

    private async ensureTaxRatesLoaded(): Promise<void> {
        await this.taxEngine.loadRates();
    }

    async processSale(sale: SaleTransaction): Promise<void> {
        // Ensure tax rates are current from DB
        await this.ensureTaxRatesLoaded();

        // 0. Pre-Calculation (Big.js Precision)
        let subtotal = Big(0);
        let taxableSubtotal = Big(0);
        let totalCost = Big(0);

        for (const line of sale.lines) {
            const qty = Big(line.quantity);
            const price = Big(line.unitPrice);
            const lineTotal = qty.times(price);
            subtotal = subtotal.plus(lineTotal);
            if (line.taxable) {
                taxableSubtotal = taxableSubtotal.plus(lineTotal);
            }
            totalCost = totalCost.plus(qty.times(Big(line.cost || 0)));
        }

        const taxResult = this.taxEngine.calculateTax(
            Number(subtotal.toFixed(2)),
            Number(taxableSubtotal.toFixed(2)),
            sale.county
        );

        if (!this.taxEngine.validateCompliance(taxResult.taxableAmount, taxResult.totalTax, sale.county)) {
            throw new Error('Tax Compliance Check Failed: Math mismatch in DR-15 validation');
        }

        // 2. ATOMIC TRANSACTION SCENARIO
        await this.engine.executeTransaction(async () => {
            const now = new Date().toISOString().split('T')[0];

            // A. Generate Invoice Number 
            const invResult = await this.engine.select("SELECT COUNT(*) as c FROM invoices");
            const nextNum = (invResult[0]?.c || 0) + 1;
            const invNumber = `INV-${new Date().getFullYear()}-${nextNum.toString().padStart(5, '0')}`;

            // B. INSERT INVOICE - WITH USER ATTRIBUTION
            await this.engine.run(`
                INSERT INTO invoices (invoice_number, customer_id, issue_date, subtotal, tax_amount, total_amount, status, created_by, updated_by)
                VALUES (?, ?, DATE('now'), ?, ?, ?, 'paid', ?, ?)
             `, [invNumber, sale.customerId, taxResult.subtotal, taxResult.totalTax, taxResult.totalAmount, sale.userId, sale.userId]);

            const invIdResult = await this.engine.select("SELECT last_insert_rowid() as id");
            const invoiceId = invIdResult[0].id;

            // C. PROCESS LINES & INVENTORY
            for (const line of sale.lines) {
                const lineTotal = Big(line.quantity).times(line.unitPrice).toFixed(2);
                // Insert Line
                await this.engine.run(`
                    INSERT INTO invoice_lines (invoice_id, product_id, description, quantity, unit_price, line_total, taxable)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                 `, [invoiceId, line.productId, line.description, line.quantity, line.unitPrice, lineTotal, line.taxable ? 1 : 0]);

                // Record STOCK OUT via InventoryManager (Handles batches/LIFO/FIFO)
                await this.inventoryManager.shipStock(line.productId, line.quantity, invNumber);
            }

            // Get the specific rates used for this county from DB for audit/history
            const rateRecord = await this.engine.select(
                "SELECT state_rate, county_rate FROM florida_tax_rates WHERE county_name = ? ORDER BY effective_date DESC LIMIT 1",
                [sale.county]
            );
            const stateRate = rateRecord[0]?.state_rate || 0.06;

            // C2. Insert Tax Transaction (Florida State)
            // The table expects: invoice_id, transaction_date, county_code, taxable_amount, effective_rate, tax_amount, is_exempt, exemption_type, verification_hash
            await this.engine.run(`
                INSERT INTO tax_transactions (invoice_id, transaction_date, county_code, taxable_amount, effective_rate, tax_amount, is_exempt, status)
                VALUES (?, ?, 'STATE', ?, ?, ?, 0, 'pending')
             `, [invoiceId, now, taxResult.taxableAmount, stateRate * 10000, taxResult.stateTax]);

            if (taxResult.countyTax > 0) {
                const rate = await this.engine.select(
                    "SELECT surtax_rate FROM florida_tax_rates WHERE county_name = ? LIMIT 1",
                    [sale.county]
                );
                const surtaxRate = rate[0]?.surtax_rate || 0;

                await this.engine.run(`
                    INSERT INTO tax_transactions (invoice_id, transaction_date, county_code, taxable_amount, effective_rate, tax_amount, is_exempt, status)
                    VALUES (?, ?, ?, ?, ?, ?, 0, 'pending')
                 `, [invoiceId, now, sale.county.toUpperCase(), taxResult.taxableAmount, surtaxRate, taxResult.countyTax]);
            }

            if (taxResult.exemptAmount > 0) {
                await this.engine.run(`
                    INSERT INTO tax_transactions (invoice_id, transaction_date, county_code, taxable_amount, effective_rate, tax_amount, is_exempt, status)
                    VALUES (?, ?, 'EXEMPT', ?, 0, 0, 1, 'pending')
                 `, [invoiceId, now, taxResult.exemptAmount]);
            }

            // D. CREATE JOURNAL ENTRY - USING SYSTEM CHART OF ACCOUNTS CODES
            await this.journalManager.createJournalEntry({
                date: now,
                description: `Sale Invoice ${invNumber}`,
                reference: invNumber,
                userId: sale.userId,
                details: [
                    {
                        accountCode: '1100', // Accounts Receivable (Match schema: 1100)
                        debit: Big(taxResult.totalAmount),
                        credit: Big(0)
                    },
                    {
                        accountCode: '4100', // Sales Revenue (Match schema: 4100)
                        debit: Big(0),
                        credit: Big(taxResult.subtotal)
                    },
                    {
                        accountCode: '2300', // Sales Tax Payable (Match schema: 2300)
                        debit: Big(0),
                        credit: Big(taxResult.totalTax)
                    },
                    // COGS Integration
                    {
                        accountCode: '5100', // Cost of Goods Sold
                        debit: totalCost,
                        credit: Big(0)
                    },
                    {
                        accountCode: '1200', // Inventory (Match schema: 1200)
                        debit: Big(0),
                        credit: totalCost
                    }
                ]
            });

            // E. AUDIT LOG
            await this.auditService.logEvent({
                eventType: 'SALE_PROCESSED',
                entityTable: 'invoices',
                entityId: invoiceId.toString(),
                userId: sale.userId.toString(),
                content: {
                    invoiceNumber: invNumber,
                    amount: taxResult.totalAmount,
                    itemsCount: sale.lines.length
                }
            });
        });

        console.log(`Transaction Completed Successfully.`);
    }
}

/**
 * I18nHelper - Utilidad para pasar traducciones a servicios y workers
 * 
 * Permite que servicios backend y web workers accedan a las traducciones
 * sin necesidad de importar React Context
 * SIMPLIFICADO: Solo soporte para espa├▒ol.
 */

import esTranslations from '@/locales/es.json';

type Locale = 'es';
type Translations = typeof esTranslations;

const translations: Record<Locale, Translations> = {
    es: esTranslations
};

export class I18nHelper {
    /**
     * Obtener locale actual (fijo a es)
     */
    static getCurrentLocale(): Locale {
        return 'es';
    }

    /**
     * Obtener traducciones para un locale espec├¡fico
     */
    static getTranslations(locale?: Locale): Translations {
        return translations.es;
    }

    /**
     * Traducir una clave
     */
    static translate(key: string, locale?: Locale, params?: Record<string, string | number>): string {
        const keys = key.split('.');
        let value: any = translations.es;

        // Navegar por el objeto de traducciones
        for (const k of keys) {
            if (value && typeof value === 'object' && k in value) {
                value = value[k];
            } else {
                return key;
            }
        }

        if (typeof value !== 'string') {
            return key;
        }

        // Interpolaci├│n de par├ímetros
        if (params) {
            return value.replace(/\{\{(\w+)\}\}/g, (match, paramKey) => {
                return paramKey in params ? String(params[paramKey]) : match;
            });
        }

        return value;
    }

    /**
     * Crear funci├│n de traducci├│n
     */
    static createTranslator(locale?: Locale) {
        return (key: string, params?: Record<string, string | number>) => {
            return this.translate(key, 'es', params);
        };
    }

    /**
     * Obtener objeto de traducciones completo para pasar a workers
     */
    static getTranslationsForWorker(locale?: Locale): { locale: Locale; translations: Translations } {
        return {
            locale: 'es',
            translations: translations.es
        };
    }
}

/**
 * Diagn├│stico y Restauraci├│n Exhaustiva de Autenticaci├│n
 */
import {
    initDB,
    db,
    getUserRoles,
    createUserRole,
    createUser,
    updateUserPassword,
