export const exhaustiveAuthDiagnostic = async () => {
    console.log('--- STARTING EXHAUSTIVE AUTH DIAGNOSTIC ---');

    try {
        // 1. Verificar Inicializaci├│n
        if (!db) {
            console.log('ΓÜá∩╕Å Database not initialized. Attempting initDB()...');
            await initDB();
        }

        if (!db) {
            console.error('Γ¥î CRITICAL: Could not initialize database.');
            return;
        }
        console.log('Γ£à Database is active.');

        // 2. Verificar Roles
        console.log('≡ƒöì Checking user_roles...');
        const roles = getUserRoles();
        console.log('≡ƒôè Current roles:', roles);

        const systemRoles = [
            { name: 'admin', level: 100 },
            { name: 'accountant', level: 50 },
            { name: 'viewer', level: 10 }
        ];

        for (const sysRole of systemRoles) {
            const exists = roles.find(r => r.name === sysRole.name);
            if (!exists) {
                console.log(`Γ₧ò Creating missing role: ${sysRole.name}`);
                createUserRole({
                    name: sysRole.name,
                    description: `Sistema: ${sysRole.name}`,
                    level: sysRole.level
                });
            }
        }

        // Refrescar roles
        const updatedRoles = getUserRoles();
        console.log('Γ£à Final roles:', updatedRoles);

        // 3. Verificar Usuarios y Restaurar Contrase├▒as
        const systemUsers = [
            { username: 'admin', display_name: 'Administrador', password: 'admin123', role: 'admin' },
            { username: 'viewer', display_name: 'Usuario Viewer', password: 'viewer123', role: 'viewer' }
        ];

        for (const sysUser of systemUsers) {
            console.log(`≡ƒæñ Processing user: ${sysUser.username}`);

            const role = updatedRoles.find(r => r.name === sysUser.role);
            if (!role) {
                console.error(`Γ¥î Role ${sysUser.role} not found for user ${sysUser.username}`);
                continue;
            }

            const existingUser = getUserByUsername(sysUser.username);

            if (!existingUser) {
                console.log(`Γ₧ò User ${sysUser.username} not found. Creating...`);
                const result = await createUser({
                    username: sysUser.username,
                    password: sysUser.password,
                    display_name: sysUser.display_name,
                    role_id: role.id
                });
                console.log(`   Result:`, result);
            } else {
                console.log(`≡ƒöä User ${sysUser.username} already exists. Resetting password...`);
                const result = await updateUserPassword(existingUser.id, sysUser.password);
                console.log(`   Password reset result:`, result);

                // Asegurarse de que est├⌐ activo
                (db as any).run('UPDATE users SET is_active = 1 WHERE id = ?', [existingUser.id]);
                console.log(`   User activated.`);
            }
        }

        console.log('--- DIAGNOSTIC COMPLETED ---');
        console.log('Γ£à You can now try logging in with:');
        console.log('   - admin / admin123');
        console.log('   - viewer / viewer123');

    } catch (error) {
        console.error('Γ¥î Error during diagnostic:', error);
    }
};

