import { logger as systemLogger, LogLevel } from '../core/logging/SystemLogger';

/**
 * Wrapper de logger para compatibilidad con el sistema y m├⌐todos adicionales
 */
type MaybeError = Error | undefined;

function normalizeArgs(args: IArguments | any[]): { module: string; action: string; message: string; data?: any; error?: MaybeError } {
    // Support two calling styles:
    // 1) module, action, message, data?, error?
    // 2) message, data?, module?, action?
    const a = Array.from(args as any[]);

    if (typeof a[0] === 'string' && typeof a[1] === 'string' && typeof a[2] === 'string') {
        // module, action, message, data?, error?
        return { module: a[0], action: a[1], message: a[2], data: a[3], error: a[4] };
    }

    // fallback: message, data?, module?, action?
    const message = a[0] as string;
    const data = a[1];
    const module = typeof a[2] === 'string' ? a[2] : 'Utils';
    const action = typeof a[3] === 'string' ? a[3] : 'log';
    return { module, action, message, data };
}

function wrapLevel(levelMethod: keyof typeof systemLogger, expectsError: boolean = false) {
    return function (...args: any[]) {
        const { module, action, message, data, error } = normalizeArgs(args as any[]);
        if (expectsError) {
            // @ts-ignore - forward to systemLogger method which accepts optional error
            (systemLogger as any)[levelMethod](module, action, message, data, error);
        } else {
            // @ts-ignore
            (systemLogger as any)[levelMethod](module, action, message, data);
        }
    };
}

export const logger = {
    debug: wrapLevel('debug'),
    info: wrapLevel('info'),
    warn: wrapLevel('warn'),
    error: wrapLevel('error', true),
    critical: wrapLevel('critical', true),
    emergency: wrapLevel('emergency', true),

    // M├⌐todo success solicitado por la especificaci├│n
    success: function (...args: any[]) {
        const { module, action, message, data } = normalizeArgs(args as any[]);
        // @ts-ignore
        systemLogger.success(module, action, message, data);
    },

    // Log con nivel din├ímico
    log: function (level: LogLevel, module: string, action: string, message: string, data?: any) {
        systemLogger.log(level, module, action, message, data);
    }
};

export default logger;

/**
 * PDF Generator for Closure Reports
 * 
 * Genera reportes de cierre contable en formato PDF usando jsPDF
 */

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { ClosureReportData } from '../components/accounting/ClosureReport';

export function generateClosureReportPDF(data: ClosureReportData): void {
  const doc = new jsPDF();
  const { period, validationResults, summary, closedBy, closedAt } = data;

  // Configuraci├│n
  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 20;
  let yPos = 20;

  // Helper para formatear moneda
  const formatCurrency = (amount: number): string => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(amount);
  };

  // Helper para formatear fecha
  const formatDate = (dateStr: string): string => {
    return new Date(dateStr).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  // Helper para obtener nombre de paso
  const getStepName = (stepId: number): string => {
    const names: Record<number, string> = {
      1: 'Validaci├│n de Transacciones',
      2: 'Conciliaci├│n Bancaria',
      3: 'Ajustes Contables',
      4: 'Balance de Comprobaci├│n',
      5: 'Confirmaci├│n'
    };
    return names[stepId] || `Paso ${stepId}`;
  };

  // ============================================================================
  // HEADER
  // ============================================================================
  
  // Logo/T├¡tulo
  doc.setFontSize(20);
  doc.setFont('helvetica', 'bold');
  doc.text('REPORTE DE CIERRE CONTABLE', pageWidth / 2, yPos, { align: 'center' });
  
  yPos += 10;
  doc.setFontSize(14);
  doc.setFont('helvetica', 'normal');
  doc.text(period.name, pageWidth / 2, yPos, { align: 'center' });
  
  yPos += 15;
  doc.setDrawColor(59, 130, 246); // Azul
  doc.setLineWidth(0.5);
  doc.line(margin, yPos, pageWidth - margin, yPos);
  
  yPos += 10;

  // ============================================================================
  // INFORMACI├ôN GENERAL
  // ============================================================================
  
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Informaci├│n General', margin, yPos);
  yPos += 7;

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  
  const infoData = [
    ['Per├¡odo:', period.name],
    ['Tipo:', period.period_type.charAt(0).toUpperCase() + period.period_type.slice(1)],
    ['Fecha Inicio:', formatDate(period.start_date)],
    ['Fecha Fin:', formatDate(period.end_date)],
    ['A├▒o Fiscal:', period.fiscal_year.toString()],
    ['Cerrado Por:', closedBy],
    ['Fecha de Cierre:', formatDate(closedAt)]
  ];

  autoTable(doc, {
    startY: yPos,
    head: [],
    body: infoData,
    theme: 'plain',
    styles: { fontSize: 10, cellPadding: 2 },
    columnStyles: {
      0: { fontStyle: 'bold', cellWidth: 40 },
      1: { cellWidth: 'auto' }
    },
    margin: { left: margin }
  });

  yPos = (doc as any).lastAutoTable.finalY + 10;

  // ============================================================================
  // RESUMEN FINANCIERO
  // ============================================================================
  
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen Financiero', margin, yPos);
  yPos += 7;

  const financialData = [
    ['Ingresos Totales', formatCurrency(summary.totalRevenue)],
    ['Gastos Totales', formatCurrency(summary.totalExpenses)],
    ['Utilidad Neta', formatCurrency(summary.netIncome)],
    ['Total Transacciones', summary.totalTransactions.toString()]
  ];

  autoTable(doc, {
    startY: yPos,
    head: [['Concepto', 'Monto']],
    body: financialData,
    theme: 'striped',
    headStyles: { fillColor: [59, 130, 246], textColor: 255 },
    styles: { fontSize: 10 },
    columnStyles: {
      0: { cellWidth: 80 },
      1: { cellWidth: 'auto', halign: 'right', fontStyle: 'bold' }
    },
    margin: { left: margin, right: margin }
  });

  yPos = (doc as any).lastAutoTable.finalY + 10;

  // ============================================================================
  // BALANCE DE COMPROBACI├ôN
  // ============================================================================
  
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Balance de Comprobaci├│n', margin, yPos);
  yPos += 7;

  const difference = Math.abs(summary.totalDebit - summary.totalCredit);
  const isBalanced = difference < 0.01;

  const balanceData = [
    ['Total D├⌐bitos', formatCurrency(summary.totalDebit)],
    ['Total Cr├⌐ditos', formatCurrency(summary.totalCredit)],
    ['Diferencia', formatCurrency(difference)],
    ['Estado', isBalanced ? 'Γ£ô BALANCEADO' : 'Γ£ù DESBALANCEADO']
  ];

  autoTable(doc, {
    startY: yPos,
    head: [['Concepto', 'Monto']],
    body: balanceData,
    theme: 'striped',
    headStyles: { fillColor: [59, 130, 246], textColor: 255 },
    styles: { fontSize: 10 },
    columnStyles: {
      0: { cellWidth: 80 },
      1: { cellWidth: 'auto', halign: 'right', fontStyle: 'bold' }
    },
    margin: { left: margin, right: margin }
  });

  yPos = (doc as any).lastAutoTable.finalY + 10;

  // Verificar si necesitamos nueva p├ígina
  if (yPos > 250) {
    doc.addPage();
    yPos = 20;
  }

  // ============================================================================
  // RESUMEN DE VALIDACIONES
  // ============================================================================
  
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen de Validaciones', margin, yPos);
  yPos += 7;

  // Calcular totales
  const totalChecks = validationResults.reduce((sum, r) => sum + r.checks.length, 0);
  const passedChecks = validationResults.reduce(
    (sum, r) => sum + r.checks.filter(c => c.status === 'passed').length,
    0
  );
  const warningChecks = validationResults.reduce(
    (sum, r) => sum + r.checks.filter(c => c.status === 'warning').length,
    0
  );
  const errorChecks = validationResults.reduce(
    (sum, r) => sum + r.checks.filter(c => c.status === 'error').length,
    0
  );

  const validationSummary = [
    ['Total Validaciones', totalChecks.toString()],
    ['Pasadas', passedChecks.toString()],
    ['Advertencias', warningChecks.toString()],
    ['Errores', errorChecks.toString()]
  ];

  autoTable(doc, {
    startY: yPos,
    head: [['Tipo', 'Cantidad']],
    body: validationSummary,
    theme: 'striped',
    headStyles: { fillColor: [59, 130, 246], textColor: 255 },
    styles: { fontSize: 10 },
    columnStyles: {
      0: { cellWidth: 80 },
      1: { cellWidth: 'auto', halign: 'center', fontStyle: 'bold' }
    },
    margin: { left: margin, right: margin }
  });

  yPos = (doc as any).lastAutoTable.finalY + 10;

  // ============================================================================
  // DETALLE DE VALIDACIONES POR PASO
  // ============================================================================
  
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Detalle de Validaciones', margin, yPos);
  yPos += 7;

  validationResults.forEach((result, index) => {
    // Verificar si necesitamos nueva p├ígina
    if (yPos > 240) {
      doc.addPage();
      yPos = 20;
    }

    // Nombre del paso
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.text(`${getStepName(result.stepId)}`, margin, yPos);
    yPos += 5;

    // Estado del paso
    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const statusText = result.status === 'passed' ? 'Aprobado' :
                      result.status === 'warning' ? 'Con Advertencias' :
                      result.status === 'error' ? 'Con Errores' : 'Pendiente';
    doc.text(`Estado: ${statusText}`, margin, yPos);
    yPos += 5;

    // Checks del paso
    const checksData = result.checks.map(check => {
      const statusIcon = check.status === 'passed' ? 'Γ£ô' :
                        check.status === 'warning' ? 'ΓÜá' :
                        check.status === 'error' ? 'Γ£ù' : 'Γùï';
      return [statusIcon, check.label, check.message || ''];
    });

    autoTable(doc, {
      startY: yPos,
      head: [],
      body: checksData,
      theme: 'plain',
      styles: { fontSize: 9, cellPadding: 2 },
      columnStyles: {
        0: { cellWidth: 10, halign: 'center' },
        1: { cellWidth: 80 },
        2: { cellWidth: 'auto', textColor: [107, 114, 128] }
      },
      margin: { left: margin + 5, right: margin }
    });

    yPos = (doc as any).lastAutoTable.finalY + 8;
  });

  // ============================================================================
  // NOTAS
  // ============================================================================
  
  if (period.notes) {
    // Verificar si necesitamos nueva p├ígina
    if (yPos > 240) {
      doc.addPage();
      yPos = 20;
    }

    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text('Notas', margin, yPos);
    yPos += 7;

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    const splitNotes = doc.splitTextToSize(period.notes, pageWidth - 2 * margin);
    doc.text(splitNotes, margin, yPos);
    yPos += splitNotes.length * 5 + 10;
  }

  // ============================================================================
  // FOOTER
  // ============================================================================
  
  const pageCount = doc.getNumberOfPages();
  
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    
    // L├¡nea separadora
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.5);
    doc.line(margin, 280, pageWidth - margin, 280);
    
    // Texto del footer
    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(128, 128, 128);
    
    const footerText = 'Generado por AccountExpress - ' + formatDate(new Date().toISOString());
    doc.text(footerText, pageWidth / 2, 285, { align: 'center' });
    
    // N├║mero de p├ígina
    doc.text(`P├ígina ${i} de ${pageCount}`, pageWidth - margin, 285, { align: 'right' });
  }

  // ============================================================================
  // GUARDAR PDF
  // ============================================================================
  
  const fileName = `Cierre_${period.name.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`;
  doc.save(fileName);
}

import { getCompanyData } from '@/database/simple-db';
import { getCompanyLogoUrl, getLogoHtml } from './logoUtils';
import { logger } from '../core/logging/SystemLogger';

/**
 * Genera el encabezado HTML para reportes con logo y datos de empresa
 */
export function generateReportHeader(reportTitle: string, includeDate: boolean = true): string {
  try {
    const companyData = getCompanyData();
    const logoHtml = getLogoHtml(150, 75);
    const currentDate = new Date().toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });

    if (!companyData) {
      logger.warn('ReportUtils', 'no_company_data', 'No se encontraron datos de empresa para el reporte');
      return `<h1>${reportTitle}</h1>`;
    }

    return `
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 30px; padding-bottom: 20px; border-bottom: 2px solid #e5e7eb;">
        <div style="display: flex; align-items: center; gap: 20px;">
          ${logoHtml ? `<div>${logoHtml}</div>` : ''}
          <div>
            <h1 style="margin: 0; color: #1f2937; font-size: 24px; font-weight: bold;">${companyData.company_name}</h1>
            <p style="margin: 5px 0 0 0; color: #6b7280; font-size: 14px;">${companyData.legal_name}</p>
            <p style="margin: 2px 0 0 0; color: #6b7280; font-size: 12px;">Tax ID: ${companyData.tax_id}</p>
          </div>
        </div>
        <div style="text-align: right;">
          <h2 style="margin: 0; color: #1f2937; font-size: 20px; font-weight: 600;">${reportTitle}</h2>
          ${includeDate ? `<p style="margin: 5px 0 0 0; color: #6b7280; font-size: 12px;">Generado el ${currentDate}</p>` : ''}
        </div>
      </div>
    `;
  } catch (error) {
    logger.error('ReportUtils', 'header_generation_failed', 'Error al generar encabezado de reporte', null, error as Error);
    return `<h1>${reportTitle}</h1>`;
  }
}

/**
 * Genera el pie de p├ígina para reportes
 */
export function generateReportFooter(): string {
  try {
    const companyData = getCompanyData();

    if (!companyData) {
      return '';
    }

    return `
      <div style="margin-top: 40px; padding-top: 20px; border-top: 1px solid #e5e7eb; text-align: center; color: #6b7280; font-size: 11px;">
        <p style="margin: 0;">
          ${companyData.company_name} ΓÇó ${companyData.address}, ${companyData.city}, ${companyData.state} ${companyData.zip_code}
        </p>
        <p style="margin: 5px 0 0 0;">
          Tel: ${companyData.phone} ΓÇó Email: ${companyData.email}
          ${companyData.website ? ` ΓÇó Web: ${companyData.website}` : ''}
        </p>
        <p style="margin: 10px 0 0 0; font-style: italic;">
          Generado por AccountExpress Next-Gen ΓÇó Sistema ERP Contable
        </p>
      </div>
    `;
  } catch (error) {
    logger.error('ReportUtils', 'footer_generation_failed', 'Error al generar pie de reporte', null, error as Error);
    return '';
  }
}

/**
 * Genera un reporte HTML completo con encabezado y pie de p├ígina
 */
export function generateCompleteReport(
  title: string,
  content: string,
  includeDate: boolean = true
): string {
  const header = generateReportHeader(title, includeDate);
  const footer = generateReportFooter();

  return `
    <!DOCTYPE html>
    <html lang="es">
    <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>${title}</title>
      <style>
        body {
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
          line-height: 1.6;
          color: #1f2937;
          max-width: 1200px;
          margin: 0 auto;
          padding: 20px;
          background: white;
        }
        table {
          width: 100%;
          border-collapse: collapse;
          margin: 20px 0;
        }
        th, td {
          padding: 12px;
          text-align: left;
          border-bottom: 1px solid #e5e7eb;
        }
        th {
          background-color: #f9fafb;
          font-weight: 600;
          color: #374151;
        }
        .text-right {
          text-align: right;
        }
        .text-center {
          text-align: center;
        }
        .font-black { font-weight: 900; }
        .text-green {
          color: #059669;
        }
        .text-red {
          color: #dc2626;
        }
        .text-blue {
          color: #2563eb;
        }
        @media print {
          body {
            padding: 0;
          }
        }
      </style>
    </head>
    <body>
      ${header}
      ${content}
      ${footer}
    </body>
    </html>
  `;
}

/**
 * Abre un reporte en una nueva ventana para impresi├│n
 */
export function printReport(title: string, content: string, includeDate: boolean = true): void {
  try {
    const reportHtml = generateCompleteReport(title, content, includeDate);

    const printWindow = window.open('', '_blank');
    if (printWindow) {
      printWindow.document.write(reportHtml);
      printWindow.document.close();

      // Esperar a que se cargue el contenido antes de imprimir
      printWindow.onload = () => {
        printWindow.print();
      };

      logger.info('ReportUtils', 'print_report', 'Reporte abierto para impresi├│n', { title });
    } else {
      throw new Error('No se pudo abrir la ventana de impresi├│n');
    }
  } catch (error) {
    logger.error('ReportUtils', 'print_failed', 'Error al imprimir reporte', { title }, error as Error);
    alert('Error al abrir el reporte para impresi├│n. Verifique que las ventanas emergentes est├⌐n habilitadas.');
  }
}

/**
 * Descarga un reporte como archivo HTML
 */
export function downloadReport(title: string, content: string, includeDate: boolean = true): void {
  try {
    const reportHtml = generateCompleteReport(title, content, includeDate);

    const blob = new Blob([reportHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = `${title.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().toISOString().split('T')[0]}.html`;

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);

    logger.info('ReportUtils', 'download_report', 'Reporte descargado', { title, filename: link.download });
  } catch (error) {
    logger.error('ReportUtils', 'download_failed', 'Error al descargar reporte', { title }, error as Error);
    alert('Error al descargar el reporte.');
  }
}

/**
 * validators.ts - Utilidades de validaci├│n centralizadas
 * 
 * Sistema de validaci├│n robusto para todo el sistema
 * Nivel NASA - A prueba de fallos
 * 
 * @author Kiro AI
 * @date 2026-02-08
 */

// ==========================================
// TYPES
// ==========================================

export interface ValidationResult {
  isValid: boolean;
  errors: ValidationError[];
}

export interface ValidationError {
  field: string;
  message: string;
  code: string;
}

export type ValidationRule<T> = (value: T) => ValidationError | null;

// ==========================================
// ERROR CODES
// ==========================================

export const ERROR_CODES = {
  // General
  REQUIRED: 'REQUIRED',
  INVALID_FORMAT: 'INVALID_FORMAT',
  INVALID_TYPE: 'INVALID_TYPE',
  
  // String
  TOO_SHORT: 'TOO_SHORT',
  TOO_LONG: 'TOO_LONG',
  INVALID_PATTERN: 'INVALID_PATTERN',
  
  // Number
  TOO_SMALL: 'TOO_SMALL',
  TOO_LARGE: 'TOO_LARGE',
  NOT_INTEGER: 'NOT_INTEGER',
  NOT_POSITIVE: 'NOT_POSITIVE',
  
  // Date
  INVALID_DATE: 'INVALID_DATE',
  DATE_IN_PAST: 'DATE_IN_PAST',
  DATE_IN_FUTURE: 'DATE_IN_FUTURE',
  DATE_OUT_OF_RANGE: 'DATE_OUT_OF_RANGE',
  
  // Email
  INVALID_EMAIL: 'INVALID_EMAIL',
  
  // SSN
  INVALID_SSN: 'INVALID_SSN',
  
  // EIN
  INVALID_EIN: 'INVALID_EIN',
  
  // Phone
  INVALID_PHONE: 'INVALID_PHONE',
  
  // Business Rules
  PERIOD_CLOSED: 'PERIOD_CLOSED',
  DUPLICATE_ENTRY: 'DUPLICATE_ENTRY',
  INSUFFICIENT_BALANCE: 'INSUFFICIENT_BALANCE',
  INVALID_ACCOUNT: 'INVALID_ACCOUNT',
} as const;

// ==========================================
// ERROR MESSAGES (ES)
// ==========================================

export const ERROR_MESSAGES: Record<string, string> = {
  // General
  REQUIRED: 'Este campo es requerido',
  INVALID_FORMAT: 'Formato inv├ílido',
  INVALID_TYPE: 'Tipo de dato inv├ílido',
  
  // String
  TOO_SHORT: 'Debe tener al menos {min} caracteres',
  TOO_LONG: 'No puede exceder {max} caracteres',
  INVALID_PATTERN: 'Formato inv├ílido',
  
  // Number
  TOO_SMALL: 'Debe ser al menos {min}',
  TOO_LARGE: 'No puede exceder {max}',
  NOT_INTEGER: 'Debe ser un n├║mero entero',
  NOT_POSITIVE: 'Debe ser un n├║mero positivo',
  
  // Date
  INVALID_DATE: 'Fecha inv├ílida',
  DATE_IN_PAST: 'La fecha no puede estar en el pasado',
  DATE_IN_FUTURE: 'La fecha no puede estar en el futuro',
  DATE_OUT_OF_RANGE: 'La fecha est├í fuera del rango permitido',
  
  // Email
  INVALID_EMAIL: 'Email inv├ílido',
  
  // SSN
  INVALID_SSN: 'SSN debe estar en formato XXX-XX-XXXX',
  
  // EIN
  INVALID_EIN: 'EIN debe estar en formato XX-XXXXXXX',
  
  // Phone
  INVALID_PHONE: 'Tel├⌐fono inv├ílido',
  
  // Business Rules
  PERIOD_CLOSED: 'El per├¡odo contable est├í cerrado',
  DUPLICATE_ENTRY: 'Ya existe un registro con estos datos',
  INSUFFICIENT_BALANCE: 'Saldo insuficiente',
  INVALID_ACCOUNT: 'Cuenta inv├ílida',
};

// ==========================================
// BASIC VALIDATORS
// ==========================================

/**
 * Valida que un valor no sea nulo, undefined o vac├¡o
 */
export function required(field: string, message?: string): ValidationRule<any> {
  return (value: any) => {
    if (value === null || value === undefined || value === '' || 
        (Array.isArray(value) && value.length === 0)) {
      return {
        field,
        message: message || ERROR_MESSAGES.REQUIRED,
        code: ERROR_CODES.REQUIRED
      };
    }
    return null;
  };
}

/**
 * Valida longitud m├¡nima de string
 */
export function minLength(field: string, min: number, message?: string): ValidationRule<string> {
  return (value: string) => {
    if (value && value.length < min) {
      return {
        field,
        message: message || ERROR_MESSAGES.TOO_SHORT.replace('{min}', min.toString()),
        code: ERROR_CODES.TOO_SHORT
      };
    }
    return null;
  };
}

/**
 * Valida longitud m├íxima de string
 */
export function maxLength(field: string, max: number, message?: string): ValidationRule<string> {
  return (value: string) => {
    if (value && value.length > max) {
      return {
        field,
        message: message || ERROR_MESSAGES.TOO_LONG.replace('{max}', max.toString()),
        code: ERROR_CODES.TOO_LONG
      };
    }
    return null;
  };
}

/**
 * Valida valor m├¡nimo de n├║mero
 */
export function min(field: string, minValue: number, message?: string): ValidationRule<number> {
  return (value: number) => {
    if (value !== null && value !== undefined && value < minValue) {
      return {
        field,
        message: message || ERROR_MESSAGES.TOO_SMALL.replace('{min}', minValue.toString()),
        code: ERROR_CODES.TOO_SMALL
      };
    }
    return null;
  };
}

/**
 * Valida valor m├íximo de n├║mero
 */
export function max(field: string, maxValue: number, message?: string): ValidationRule<number> {
  return (value: number) => {
    if (value !== null && value !== undefined && value > maxValue) {
      return {
        field,
        message: message || ERROR_MESSAGES.TOO_LARGE.replace('{max}', maxValue.toString()),
        code: ERROR_CODES.TOO_LARGE
      };
    }
    return null;
  };
}

/**
 * Valida que sea un n├║mero entero
 */
export function integer(field: string, message?: string): ValidationRule<number> {
  return (value: number) => {
    if (value !== null && value !== undefined && !Number.isInteger(value)) {
      return {
        field,
        message: message || ERROR_MESSAGES.NOT_INTEGER,
        code: ERROR_CODES.NOT_INTEGER
      };
    }
    return null;
  };
}

/**
 * Valida que sea un n├║mero positivo
 */
export function positive(field: string, message?: string): ValidationRule<number> {
  return (value: number) => {
    if (value !== null && value !== undefined && value <= 0) {
      return {
        field,
        message: message || ERROR_MESSAGES.NOT_POSITIVE,
        code: ERROR_CODES.NOT_POSITIVE
      };
    }
    return null;
  };
}

/**
 * Valida patr├│n regex
 */
export function pattern(field: string, regex: RegExp, message?: string): ValidationRule<string> {
  return (value: string) => {
    if (value && !regex.test(value)) {
      return {
        field,
        message: message || ERROR_MESSAGES.INVALID_PATTERN,
        code: ERROR_CODES.INVALID_PATTERN
      };
    }
    return null;
  };
}

// ==========================================
// SPECIFIC VALIDATORS
// ==========================================

/**
 * Valida formato de email
 */
export function email(field: string, message?: string): ValidationRule<string> {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return (value: string) => {
    if (value && !emailRegex.test(value)) {
      return {
        field,
        message: message || ERROR_MESSAGES.INVALID_EMAIL,
        code: ERROR_CODES.INVALID_EMAIL
      };
    }
    return null;
  };
}

/**
 * Valida formato de SSN (XXX-XX-XXXX)
 */
export function ssn(field: string, message?: string): ValidationRule<string> {
  const ssnRegex = /^\d{3}-\d{2}-\d{4}$/;
  return (value: string) => {
    if (value && !ssnRegex.test(value)) {
      return {
        field,
        message: message || ERROR_MESSAGES.INVALID_SSN,
        code: ERROR_CODES.INVALID_SSN
      };
    }
    return null;
  };
}

/**
 * Valida formato de EIN (XX-XXXXXXX)
 */
export function ein(field: string, message?: string): ValidationRule<string> {
  const einRegex = /^\d{2}-\d{7}$/;
  return (value: string) => {
    if (value && !einRegex.test(value)) {
      return {
        field,
        message: message || ERROR_MESSAGES.INVALID_EIN,
        code: ERROR_CODES.INVALID_EIN
      };
    }
    return null;
  };
}

/**
 * Valida formato de tel├⌐fono US
 */
export function phone(field: string, message?: string): ValidationRule<string> {
  const phoneRegex = /^(\+1)?[-.\s]?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}$/;
  return (value: string) => {
    if (value && !phoneRegex.test(value)) {
      return {
        field,
        message: message || ERROR_MESSAGES.INVALID_PHONE,
        code: ERROR_CODES.INVALID_PHONE
      };
    }
    return null;
  };
}

/**
 * Valida que sea una fecha v├ílida
 */
export function validDate(field: string, message?: string): ValidationRule<string | Date> {
  return (value: string | Date) => {
    const date = typeof value === 'string' ? new Date(value) : value;
    if (value && isNaN(date.getTime())) {
      return {
        field,
        message: message || ERROR_MESSAGES.INVALID_DATE,
        code: ERROR_CODES.INVALID_DATE
      };
    }
    return null;
  };
}

/**
 * Valida que la fecha no est├⌐ en el pasado
 */
export function notInPast(field: string, message?: string): ValidationRule<string | Date> {
  return (value: string | Date) => {
    const date = typeof value === 'string' ? new Date(value) : value;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    if (value && date < today) {
      return {
        field,
        message: message || ERROR_MESSAGES.DATE_IN_PAST,
        code: ERROR_CODES.DATE_IN_PAST
      };
    }
    return null;
  };
}

/**
 * Valida que la fecha no est├⌐ en el futuro
 */
export function notInFuture(field: string, message?: string): ValidationRule<string | Date> {
  return (value: string | Date) => {
    const date = typeof value === 'string' ? new Date(value) : value;
    const today = new Date();
    today.setHours(23, 59, 59, 999);
    
    if (value && date > today) {
      return {
        field,
        message: message || ERROR_MESSAGES.DATE_IN_FUTURE,
        code: ERROR_CODES.DATE_IN_FUTURE
      };
    }
    return null;
  };
}

// ==========================================
// VALIDATOR COMPOSER
// ==========================================

/**
 * Ejecuta m├║ltiples validaciones en un valor
 */
export function validate<T>(value: T, rules: ValidationRule<T>[]): ValidationResult {
  const errors: ValidationError[] = [];
  
  for (const rule of rules) {
    const error = rule(value);
    if (error) {
      errors.push(error);
    }
  }
  
  return {
    isValid: errors.length === 0,
    errors
  };
}

/**
 * Valida un objeto completo con m├║ltiples campos
 */
export function validateObject<T extends Record<string, any>>(
  obj: T,
  schema: Record<keyof T, ValidationRule<any>[]>
): ValidationResult {
  const errors: ValidationError[] = [];
  
  for (const field in schema) {
    const value = obj[field];
    const rules = schema[field];
    const result = validate(value, rules);
    
    if (!result.isValid) {
      errors.push(...result.errors);
    }
  }
  
  return {
    isValid: errors.length === 0,
    errors
  };
}

// ==========================================
// BUSINESS RULE VALIDATORS
// ==========================================

/**
 * Valida que un per├¡odo contable est├⌐ abierto
 */
export function periodOpen(field: string, date: string | Date): ValidationError | null {
  // Esta funci├│n deber├¡a consultar la base de datos
  // Por ahora, retornamos null (v├ílido)
  return null;
}

/**
 * Valida que no exista un duplicado
 */
export function noDuplicate(field: string, value: any, existingValues: any[]): ValidationError | null {
  if (existingValues.includes(value)) {
    return {
      field,
      message: ERROR_MESSAGES.DUPLICATE_ENTRY,
      code: ERROR_CODES.DUPLICATE_ENTRY
    };
  }
  return null;
}

/**
 * Valida saldo suficiente
 */
export function sufficientBalance(field: string, amount: number, balance: number): ValidationError | null {
  if (amount > balance) {
    return {
      field,
      message: ERROR_MESSAGES.INSUFFICIENT_BALANCE,
      code: ERROR_CODES.INSUFFICIENT_BALANCE
    };
  }
  return null;
}

