/**
 * SyncWorker (Iron Clad Upgrade)
 * Handles background synchronization tasks from sync_outbox.
 * Prevents UI freezes during network operations and heavy retries.
 */

// We need a minimal SQLite connection in the worker to read the outbox
import { SQLiteEngine } from '../core/database/SQLiteEngine';
import { S3Provider } from '../services/cloud/S3Provider';

const ctx: Worker = self as any;

let engine: SQLiteEngine | null = null;
let isOnline = true;
let isProcessing = false;
let pollingInterval: any = null;

async function initEngine() {
    if (!engine) {
        engine = new SQLiteEngine();
        await engine.initialize();
    }
}

async function processOutbox() {
    if (isProcessing || !isOnline || !engine) return;

    try {
        isProcessing = true;

        // Verify if the table exists before querying (Phase 7 - Silencio Inteligente)
        const tableCheck = await engine.select("SELECT name FROM sqlite_master WHERE type='table' AND name='sync_outbox'");
        if (tableCheck.length === 0) {
            isProcessing = false;
            return;
        }

        // 1. Get pending items with exponential backoff logic (simplified for now: status = 'pending' or 'failed')
        const items = await engine.select(`
            SELECT * FROM sync_outbox 
            WHERE status IN ('pending', 'failed') 
            AND retry_count < 10
            ORDER BY created_at ASC 
            LIMIT 5
        `);

        if (items.length === 0) {
            isProcessing = false;
            return;
        }

        console.log(`[SyncWorker] Processing ${items.length} operations...`);

        for (const item of items) {
            try {
                // Calculate backoff: 2^retry_count * 1000ms
                const backoffMs = Math.pow(2, item.retry_count || 0) * 1000;
                const lastUpdated = new Date(item.updated_at).getTime();
                const now = Date.now();

                // Skip if not enough time has passed since last failure
                if (item.status === 'failed' && (now - lastUpdated) < backoffMs) {
                    continue;
                }

                // Update status to processing
                await engine.run("UPDATE sync_outbox SET status = 'processing', updated_at = datetime('now') WHERE id = ?", [item.id]);

                const payload = JSON.parse(item.payload);

                // ---------------------------------------------------------
                // HANDLERS (Objective 1.3 - execute specific handlers)
                // ---------------------------------------------------------
                let success = false;

                switch (item.module) {
                    case 'backups':
                        // Objective 3.4: Hook into the Outbox
                        console.log(`[SyncWorker] Starting Cloud Vault Upload: ${payload.fileName || payload.filename}`);

                        // Parse cloud config (should be encrypted in localStorage)
                        let cloudConfig;
                        try {
                            const encryptedConfig = self.localStorage?.getItem('cloud_backup_config');
                            if (!encryptedConfig) {
                                throw new Error('Cloud backup not configured');
                            }

                            // In worker context, we need to decrypt
                            // For now, assume config is passed in payload or use a simpler approach
                            cloudConfig = payload.cloudConfig || JSON.parse(encryptedConfig);
                        } catch (configError: any) {
                            console.error('[SyncWorker] Cloud config error:', configError);
                            throw new Error(`Cloud configuration error: ${configError.message}`);
                        }

                        // Create S3Provider instance
                        const s3 = new S3Provider(cloudConfig);

                        // Convert Base64 data to Blob if needed
                        let uploadData: Blob | ArrayBuffer | string;
                        if (payload.data && typeof payload.data === 'string') {
                            // Assume Base64 encoded
                            const binaryString = atob(payload.data);
                            const bytes = new Uint8Array(binaryString.length);
                            for (let i = 0; i < binaryString.length; i++) {
                                bytes[i] = binaryString.charCodeAt(i);
                            }
                            uploadData = new Blob([bytes], { type: 'application/octet-stream' });
                        } else if (payload.encryptedData) {
                            // Legacy support
                            uploadData = payload.encryptedData;
                        } else {
                            throw new Error('No data found in backup payload');
                        }

                        // Upload to S3 with progress reporting
                        await s3.upload(
                            payload.filename || payload.fileName,
                            uploadData,
                            {
                                compress: false, // Already compressed by DatabaseService
                                contentType: 'application/octet-stream',
                                onProgress: (progress) => {
                                    console.log(`[SyncWorker] Upload progress: ${progress}%`);
                                    ctx.postMessage({
                                        type: 'UPLOAD_PROGRESS',
                                        opId: item.id,
                                        progress
                                    });
                                }
                            }
                        );

                        success = true;
                        break;
                    default:
                        console.warn(`[SyncWorker] No handler for module: ${item.module}`);
                        success = true;
                }

                if (success) {
                    await engine.run("UPDATE sync_outbox SET status = 'completed', updated_at = datetime('now') WHERE id = ?", [item.id]);
                    ctx.postMessage({ type: 'SYNC_SUCCESS', opId: item.id });
                } else {
                    throw new Error("Handler returned failure");
                }

            } catch (err: any) {
                const newRetryCount = (item.retry_count || 0) + 1;
                const nextStatus = newRetryCount >= 10 ? 'abandoned' : 'failed';

                await engine.run(`
                    UPDATE sync_outbox 
                    SET status = ?, 
                        retry_count = ?, 
                        last_error = ?, 
                        updated_at = datetime('now') 
                    WHERE id = ?
                `, [nextStatus, newRetryCount, err.message, item.id]);

                ctx.postMessage({ type: 'SYNC_ERROR', opId: item.id, error: err.message });
            }
        }

    } catch (e) {
        console.error('[SyncWorker] Global processing error:', e);
    } finally {
        isProcessing = false;
    }
}

ctx.onmessage = async (e) => {
    const { type, payload } = e.data;

    switch (type) {
        case 'INIT':
            await initEngine();
            isOnline = payload.isOnline;
            startPolling();
            break;
        case 'STATUS_CHANGE':
            isOnline = payload.isOnline;
            if (isOnline) processOutbox();
            break;
        case 'TRIGGER_SYNC':
            processOutbox();
            break;
    }
};

function startPolling() {
    if (pollingInterval) clearInterval(pollingInterval);
    // Poll every 30 seconds for pending tasks
    pollingInterval = setInterval(() => {
        processOutbox();
    }, 30000);
}

console.log('[SyncWorker] Background sync initialized.');

/**
 * CSV Worker (Iron Clad Upgrade - Phase 2, Day 2)
 * 
 * Procesa archivos CSV grandes en background sin bloquear la UI.
 * Soporta:
 * - Parsing de CSV con streaming
 * - Validaci├│n de datos
 * - Transformaci├│n de datos
 * - Generaci├│n de CSV
 * - Import de transacciones bancarias
 * - Import de inventario
 */

import Papa from 'papaparse';

interface CSVProcessingTask {
    type: 'PARSE' | 'GENERATE' | 'VALIDATE' | 'TRANSFORM';
    data: any;
    options?: {
        delimiter?: string;
        header?: boolean;
        skipEmptyLines?: boolean;
        transformHeader?: (header: string) => string;
        validate?: (row: any) => boolean;
    };
}

interface CSVProcessingResult {
    success: boolean;
    data?: any;
    errors?: string[];
    metadata?: {
        rowCount: number;
        columnCount: number;
        processingTime: number;
        validRows: number;
        invalidRows: number;
    };
}

/**
 * Main message handler
 */
self.onmessage = async (e: MessageEvent) => {
    const startTime = Date.now();
    const task: CSVProcessingTask = e.data;

    try {
        postProgress(0, 'Initializing CSV processor...');

        let result: any;

        switch (task.type) {
            case 'PARSE':
                result = await parseCSV(task.data, task.options);
                break;
            case 'GENERATE':
                result = await generateCSV(task.data, task.options);
                break;
            case 'VALIDATE':
                result = await validateCSV(task.data, task.options);
                break;
            case 'TRANSFORM':
                result = await transformCSV(task.data, task.options);
                break;
            default:
                throw new Error(`Unknown CSV operation: ${task.type}`);
        }

        const processingTime = Date.now() - startTime;

        postProgress(100, 'CSV processing complete!');

        const response: CSVProcessingResult = {
            success: true,
            data: result.data,
            errors: result.errors,
            metadata: {
                ...result.metadata,
                processingTime
            }
        };

        self.postMessage(response);

    } catch (error: any) {
        const response: CSVProcessingResult = {
            success: false,
            errors: [error.message]
        };
        self.postMessage(response);
    }
};

/**
 * Parse CSV file
 */
async function parseCSV(file: File | string, options?: any): Promise<any> {
    postProgress(10, 'Starting CSV parsing...');

    return new Promise((resolve, reject) => {
        const config: Papa.ParseConfig = {
            header: options?.header !== false,
            delimiter: options?.delimiter || ',',
            skipEmptyLines: options?.skipEmptyLines !== false,
            transformHeader: options?.transformHeader,
            dynamicTyping: true,
            complete: (results: Papa.ParseResult<any>) => {
                postProgress(80, 'Parsing complete, processing results...');

                const errors: string[] = [];
                const validRows: any[] = [];
                const invalidRows: any[] = [];

                // Validate rows if validator provided
                if (options?.validate) {
                    results.data.forEach((row: any, index: number) => {
                        try {
                            if (options.validate(row)) {
                                validRows.push(row);
                            } else {
                                invalidRows.push({ row, index, reason: 'Validation failed' });
                            }
                        } catch (error: any) {
                            invalidRows.push({ row, index, reason: error.message });
                        }
                    });
                } else {
                    validRows.push(...results.data);
                }

                // Collect parsing errors
                if (results.errors && results.errors.length > 0) {
                    results.errors.forEach((error: any) => {
                        errors.push(`Row ${error.row}: ${error.message}`);
                    });
                }

                resolve({
                    data: validRows,
                    errors: errors.concat(invalidRows.map(r => `Row ${r.index}: ${r.reason}`)),
                    metadata: {
                        rowCount: results.data.length,
                        columnCount: results.meta.fields?.length || 0,
                        validRows: validRows.length,
                        invalidRows: invalidRows.length
                    }
                });
            },
            // @ts-ignore Papa.parse accepts error callback even if types don't show it
            error: (error: Error) => {
                reject(error);
            },
            step: (row: Papa.ParseStepResult<any>) => {
                // Report progress during streaming
                const progress = Math.min(70, (row.meta.cursor / (file as File).size) * 70);
                postProgress(10 + progress, `Parsing row ${row.meta.cursor}...`);
            }
        };

        // @ts-ignore Papa.parse can accept File or string
        Papa.parse(file, config);
    });
}

/**
 * Generate CSV from data
 */
async function generateCSV(data: any[], options?: any): Promise<any> {
    postProgress(10, 'Generating CSV...');

    try {
        const csv = Papa.unparse(data, {
            delimiter: options?.delimiter || ',',
            header: options?.header !== false,
            skipEmptyLines: options?.skipEmptyLines !== false
        });

        postProgress(80, 'CSV generation complete!');

        return {
            data: csv,
            errors: [],
            metadata: {
                rowCount: data.length,
                columnCount: Object.keys(data[0] || {}).length,
                validRows: data.length,
                invalidRows: 0
            }
        };
    } catch (error: any) {
        throw new Error(`CSV generation failed: ${error.message}`);
    }
}

/**
 * Validate CSV data
 */
async function validateCSV(data: any, options?: any): Promise<any> {
    postProgress(10, 'Validating CSV data...');

    // First parse the CSV
    const parseResult = await parseCSV(data, options);

    postProgress(50, 'Running validation rules...');

    const validationErrors: string[] = [];
    const validRows: any[] = [];
    const invalidRows: any[] = [];

    parseResult.data.forEach((row: any, index: number) => {
        const rowErrors: string[] = [];

        // Check for required fields
        if (options?.requiredFields) {
            options.requiredFields.forEach((field: string) => {
                if (!row[field] || row[field] === '') {
                    rowErrors.push(`Missing required field: ${field}`);
                }
            });
        }

        // Check data types
        if (options?.fieldTypes) {
            Object.entries(options.fieldTypes).forEach(([field, type]) => {
                if (row[field] !== undefined && row[field] !== null) {
                    const value = row[field];
                    let isValid = true;

                    switch (type) {
                        case 'number':
                            isValid = typeof value === 'number' && !isNaN(value);
                            break;
                        case 'string':
                            isValid = typeof value === 'string';
                            break;
                        case 'date':
                            isValid = !isNaN(Date.parse(value));
                            break;
                        case 'email':
                            isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
                            break;
                    }

                    if (!isValid) {
                        rowErrors.push(`Invalid ${type} in field: ${field}`);
                    }
                }
            });
        }

        // Custom validation
        if (options?.validate) {
            try {
                if (!options.validate(row)) {
                    rowErrors.push('Custom validation failed');
                }
            } catch (error: any) {
                rowErrors.push(`Validation error: ${error.message}`);
            }
        }

        if (rowErrors.length > 0) {
            invalidRows.push({ row, index, errors: rowErrors });
            validationErrors.push(`Row ${index + 1}: ${rowErrors.join(', ')}`);
        } else {
            validRows.push(row);
        }

        // Report progress
        const progress = 50 + ((index / parseResult.data.length) * 40);
        postProgress(progress, `Validated ${index + 1} of ${parseResult.data.length} rows...`);
    });

    postProgress(90, 'Validation complete!');

    return {
        data: validRows,
        errors: validationErrors,
        metadata: {
            rowCount: parseResult.data.length,
            columnCount: parseResult.metadata.columnCount,
            validRows: validRows.length,
            invalidRows: invalidRows.length
        }
    };
}

/**
 * Transform CSV data
 */
async function transformCSV(data: any, options?: any): Promise<any> {
    postProgress(10, 'Transforming CSV data...');

    // First parse the CSV
    const parseResult = await parseCSV(data, {
        ...options,
        validate: undefined // Don't validate during parsing
    });

    postProgress(40, 'Applying transformations...');

    const transformedRows: any[] = [];
    const errors: string[] = [];

    parseResult.data.forEach((row: any, index: number) => {
        try {
            let transformedRow = { ...row };

            // Apply field mappings
            if (options?.fieldMappings) {
                const mappedRow: any = {};
                Object.entries(options.fieldMappings).forEach(([oldField, newField]) => {
                    mappedRow[newField as string] = transformedRow[oldField];
                });
                transformedRow = mappedRow;
            }

            // Apply transformations
            if (options?.transforms) {
                Object.entries(options.transforms).forEach(([field, transform]) => {
                    if (transformedRow[field] !== undefined) {
                        try {
                            transformedRow[field] = (transform as Function)(transformedRow[field], transformedRow);
                        } catch (error: any) {
                            errors.push(`Row ${index + 1}, field ${field}: ${error.message}`);
                        }
                    }
                });
            }

            // Apply custom transform function
            if (options?.transform) {
                transformedRow = options.transform(transformedRow, index);
            }

            transformedRows.push(transformedRow);

            // Report progress
            const progress = 40 + ((index / parseResult.data.length) * 50);
            postProgress(progress, `Transformed ${index + 1} of ${parseResult.data.length} rows...`);

        } catch (error: any) {
            errors.push(`Row ${index + 1}: ${error.message}`);
        }
    });

    postProgress(90, 'Transformation complete!');

    return {
        data: transformedRows,
        errors,
        metadata: {
            rowCount: transformedRows.length,
