// Encryption Worker
// Handles cryptographic operations in a separate thread
import sjcl from 'sjcl';

let key: CryptoKey | null = null;
let sjclPassword: string | null = null;

self.onmessage = async (e: MessageEvent) => {
    const { type, id, payload } = e.data;

    try {
        switch (type) {
            case 'INITIALIZE':
                await initializeKey(payload);
                self.postMessage({ type: 'SUCCESS', id });
                break;

            case 'ENCRYPT':
                // Check if we have a key (Web Crypto) or password (SJCL)
                if (!key && !sjclPassword) throw new Error('Key not initialized');

                let result;
                if (key) {
                    try {
                        result = await encryptWebCrypto(payload.data);
                    } catch (err) {
                        console.warn('Web Crypto encryption failed, falling back to SJCL if available', err);
                        if (sjclPassword) {
                            result = await encryptSJCL(payload.data);
                        } else {
                            throw err;
                        }
                    }
                } else {
                    result = await encryptSJCL(payload.data);
                }

                self.postMessage({ type: 'ENCRYPT_SUCCESS', id, payload: result });
                break;

            case 'HASH_CHAIN':
                const hash = await calculateAuditHash(payload.previousHash, payload.content);
                self.postMessage({ type: 'HASH_SUCCESS', id, payload: hash });
                break;

            default:
                console.warn('Unknown message type', type);
        }
    } catch (error: any) {
        self.postMessage({ type: 'ERROR', id, error: error.message });
    }
};

async function initializeKey(payload: { password: string, salt: Uint8Array, config: any }) {
    const { password, salt, config } = payload;
    sjclPassword = password; // Store for SJCL fallback

    try {
        if (!crypto.subtle) throw new Error('Web Crypto API not available');

        const keyMaterial = await crypto.subtle.importKey(
            'raw',
            new TextEncoder().encode(password),
            'PBKDF2',
            false,
            ['deriveKey']
        );

        // Ensure salt is ArrayBuffer
        let saltBuffer: ArrayBuffer;
        if (salt.buffer instanceof SharedArrayBuffer) {
            saltBuffer = new ArrayBuffer(salt.byteLength);
            new Uint8Array(saltBuffer).set(salt);
        } else {
            saltBuffer = salt.buffer.slice(salt.byteOffset, salt.byteOffset + salt.byteLength);
        }

        key = await crypto.subtle.deriveKey(
            {
                name: 'PBKDF2',
                salt: saltBuffer,
                iterations: config.iterations || 600000,
                hash: config.hash || 'SHA-256'
            },
            keyMaterial,
            { name: 'AES-GCM', length: config.keyLength || 256 },
            false,
            ['encrypt', 'decrypt']
        );
    } catch (e) {
        console.warn('Web Crypto initialization failed, will use SJCL only.', e);
        key = null;
    }
}

async function encryptWebCrypto(data: ArrayBuffer) {
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const encrypted = await crypto.subtle.encrypt(
        { name: 'AES-GCM', iv },
        key!,
        data
    );

    return {
        data: encrypted,
        iv,
        salt: null,
        method: 'webcrypto'
    };
}

// SJCL Encryption implementation
async function encryptSJCL(data: ArrayBuffer) {
    if (!sjclPassword) throw new Error('SJCL Password not set');

    // Convert ArrayBuffer to SJCL bitArray
    const dataArray = new Uint8Array(data);
    // Safe conversion for arbitrary binary data to something SJCL handles?
    // SJCL's codec.utf8String might fail on binary. 
    // Ideally we use sjcl.codec.hex or base64.
    // Let's use Base64 to be safe.
    const binaryString = String.fromCharCode(...dataArray);
    const base64 = btoa(binaryString);
    const bits = sjcl.codec.base64.toBits(base64);

    // Encrypt
    const encryptedJsonFn = sjcl.json.encrypt(sjclPassword, base64, { ks: 256, iter: 600000 } as any);
    const encryptedStr = typeof encryptedJsonFn === 'string' ? encryptedJsonFn : JSON.stringify(encryptedJsonFn);

    return {
        data: new TextEncoder().encode(encryptedStr).buffer, // Return JSON string as buffer
        iv: null, // SJCL packs everything
        salt: null,
        method: 'sjcl'
    };
}

async function calculateAuditHash(previousHash: string, content: any): Promise<string> {
    const contentStr = JSON.stringify(content);
    const dataToHash = previousHash + contentStr;

    if (crypto.subtle) {
        const msgBuffer = new TextEncoder().encode(dataToHash);
        const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    } else {
        // SJCL Hash Fallback
        const bitArray = sjcl.hash.sha256.hash(dataToHash);
        return sjcl.codec.hex.fromBits(bitArray);
    }
}

// inventory-analysis.worker.ts - Worker para an├ílisis pesado de inventario
/// <reference lib="webworker" />

interface InventoryAnalysisTask {
  type: 'ABC_ANALYSIS' | 'TURNOVER_CALCULATION' | 'STOCK_AGING' | 'REORDER_SUGGESTIONS';
  payload: any;
}

interface ABCClassification {
  productId: number;
  productName: string;
  annualValue: number;
  cumulativePercentage: number;
  classification: 'A' | 'B' | 'C';
}

interface TurnoverMetrics {
  productId: number;
  turnoverRatio: number;
  daysToSell: number;
  stockStatus: 'fast' | 'normal' | 'slow' | 'dead';
}

self.onmessage = async (event: MessageEvent) => {
  const { type, taskId, payload } = event.data;

  try {
    let result: any;

    switch (payload.type) {
      case 'ABC_ANALYSIS':
        result = performABCAnalysis(payload.payload);
        break;

      case 'TURNOVER_CALCULATION':
        result = calculateTurnoverMetrics(payload.payload);
        break;

      case 'STOCK_AGING':
        result = analyzeStockAging(payload.payload);
        break;

      case 'REORDER_SUGGESTIONS':
        result = generateReorderSuggestions(payload.payload);
        break;

      default:
        throw new Error(`Unknown task type: ${payload.type}`);
    }

    self.postMessage({
      taskId,
      type: 'SUCCESS',
      payload: result
    });

  } catch (error: any) {
    self.postMessage({
      taskId,
      type: 'ERROR',
      error: error.message
    });
  }
};

/**
 * An├ílisis ABC de inventario
 * Clasifica productos por valor anual (A: 80%, B: 15%, C: 5%)
 */
function performABCAnalysis(products: Array<{
  id: number;
  name: string;
  annualSales: number;
  unitCost: number;
}>): ABCClassification[] {
  // Calcular valor anual de cada producto
  const productsWithValue = products.map(p => ({
    productId: p.id,
    productName: p.name,
    annualValue: p.annualSales * p.unitCost
  }));

  // Ordenar por valor descendente
  productsWithValue.sort((a, b) => b.annualValue - a.annualValue);

  // Calcular valor total
  const totalValue = productsWithValue.reduce((sum, p) => sum + p.annualValue, 0);

  // Clasificar productos
  let cumulativeValue = 0;
  const classified: ABCClassification[] = productsWithValue.map(product => {
    cumulativeValue += product.annualValue;
    const cumulativePercentage = (cumulativeValue / totalValue) * 100;

    let classification: 'A' | 'B' | 'C';
    if (cumulativePercentage <= 80) {
      classification = 'A';
    } else if (cumulativePercentage <= 95) {
      classification = 'B';
    } else {
      classification = 'C';
    }

    return {
      ...product,
      cumulativePercentage: Math.round(cumulativePercentage * 100) / 100,
      classification
    };
  });

  return classified;
}

/**
 * Calcula m├⌐tricas de rotaci├│n de inventario
 */
function calculateTurnoverMetrics(products: Array<{
  id: number;
  name: string;
  currentStock: number;
  annualSales: number;
  avgStock: number;
}>): TurnoverMetrics[] {
  return products.map(product => {
    // Ratio de rotaci├│n = Ventas anuales / Stock promedio
    const turnoverRatio = product.avgStock > 0 
      ? Math.round((product.annualSales / product.avgStock) * 100) / 100
      : 0;

    // D├¡as para vender = 365 / Ratio de rotaci├│n
    const daysToSell = turnoverRatio > 0 
      ? Math.round(365 / turnoverRatio)
      : 999;

    // Clasificar velocidad de rotaci├│n
    let stockStatus: 'fast' | 'normal' | 'slow' | 'dead';
    if (turnoverRatio >= 12) {
      stockStatus = 'fast'; // Rota m├ís de 12 veces al a├▒o
    } else if (turnoverRatio >= 4) {
      stockStatus = 'normal'; // Rota 4-12 veces al a├▒o
    } else if (turnoverRatio >= 1) {
      stockStatus = 'slow'; // Rota 1-4 veces al a├▒o
    } else {
      stockStatus = 'dead'; // Rota menos de 1 vez al a├▒o
    }

    return {
      productId: product.id,
      turnoverRatio,
      daysToSell,
      stockStatus
    };
  });
}

/**
 * Analiza antig├╝edad del stock
 */
function analyzeStockAging(products: Array<{
  id: number;
  name: string;
  lastPurchaseDate: string;
  currentStock: number;
  unitCost: number;
}>): Array<{
  productId: number;
  productName: string;
  daysInStock: number;
  ageCategory: 'fresh' | 'aging' | 'old' | 'obsolete';
  stockValue: number;
}> {
  const today = new Date();

  return products.map(product => {
    const lastPurchase = new Date(product.lastPurchaseDate);
    const daysInStock = Math.floor((today.getTime() - lastPurchase.getTime()) / (1000 * 60 * 60 * 24));

    let ageCategory: 'fresh' | 'aging' | 'old' | 'obsolete';
    if (daysInStock <= 30) {
      ageCategory = 'fresh';
    } else if (daysInStock <= 90) {
      ageCategory = 'aging';
    } else if (daysInStock <= 180) {
      ageCategory = 'old';
    } else {
      ageCategory = 'obsolete';
    }

    return {
      productId: product.id,
      productName: product.name,
      daysInStock,
      ageCategory,
      stockValue: product.currentStock * product.unitCost
    };
  });
}

/**
 * Genera sugerencias de reorden basadas en an├ílisis
 */
function generateReorderSuggestions(products: Array<{
  id: number;
  name: string;
  currentStock: number;
  reorderLevel: number;
  avgDailySales: number;
  leadTimeDays: number;
  safetyStock: number;
}>): Array<{
  productId: number;
  productName: string;
  currentStock: number;
  reorderPoint: number;
  suggestedOrderQty: number;
  urgency: 'critical' | 'high' | 'medium' | 'low';
  daysUntilStockout: number;
}> {
  return products.map(product => {
    // Punto de reorden = (Demanda diaria ├ù Lead time) + Stock de seguridad
    const reorderPoint = (product.avgDailySales * product.leadTimeDays) + product.safetyStock;

    // Cantidad sugerida de orden = Demanda durante lead time + Stock de seguridad - Stock actual
    const suggestedOrderQty = Math.max(0, 
      (product.avgDailySales * product.leadTimeDays) + product.safetyStock - product.currentStock
    );

    // D├¡as hasta agotamiento
    const daysUntilStockout = product.avgDailySales > 0
      ? Math.floor(product.currentStock / product.avgDailySales)
      : 999;

    // Nivel de urgencia
    let urgency: 'critical' | 'high' | 'medium' | 'low';
    if (product.currentStock <= 0) {
      urgency = 'critical';
    } else if (product.currentStock <= product.reorderLevel) {
      urgency = 'high';
    } else if (product.currentStock <= reorderPoint) {
      urgency = 'medium';
    } else {
      urgency = 'low';
    }

    return {
      productId: product.id,
      productName: product.name,
      currentStock: product.currentStock,
      reorderPoint: Math.round(reorderPoint),
      suggestedOrderQty: Math.round(suggestedOrderQty),
      urgency,
      daysUntilStockout
    };
  });
}

